// solution.ets

class LogEntry {
  id: number
  message: string
  level: string

  constructor(id: number) {
    this.id = id
    this.message = `Event ${id}`
    if (id % 50 === 0) {
      this.level = 'error'
    } else if (id % 10 === 0) {
      this.level = 'warning'
    } else {
      this.level = 'info'
    }
  }
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = []
  private listener?: DataChangeListener

  constructor(entries: LogEntry[]) {
    this.entries = entries
  }

  totalCount(): number {
    return this.entries.length
  }

  getData(index: number): LogEntry {
    return this.entries[index]
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    this.listener = listener
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    this.listener = undefined
  }

  addAtTop(entry: LogEntry): void {
    this.entries.unshift(entry)
    if (this.listener) {
      this.listener.onDataAdd(0)
    }
  }
}

function levelColor(level: string): string {
  if (level === 'error') {
    return '#D32F2F'
  }
  if (level === 'warning') {
    return '#F57C00'
  }
  return '#757575'
}

@Entry
@Component
struct SolutionPage {
  @State isRefreshing: boolean = false
  @State entryCount: number = 0
  private nextId: number = 1
  private dataSource: LogDataSource = new LogDataSource([])

  aboutToAppear(): void {
    // Store highest id first.
    const initial: LogEntry[] = []
    for (let id = 3000; id >= 1; id--) {
      initial.push(new LogEntry(id))
    }
    this.dataSource = new LogDataSource(initial)
    this.nextId = 3001
    this.entryCount = this.dataSource.totalCount()
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .padding(16)
        .width('100%')

      Refresh({ refreshing: $$this.isRefreshing }) {
        List({ space: 0 }) {
          LazyForEach(this.dataSource, (entry: LogEntry) => {
            ListItem() {
              LogRow({ message: entry.message, level: entry.level })
            }
          }, (entry: LogEntry) => entry.id.toString())
        }
        .width('100%')
        .layoutWeight(1)
        .cachedCount(5)
        .edgeEffect(EdgeEffect.None)
        .scrollBar(BarState.Auto)
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        setTimeout(() => {
          // Insert ascending ids at index 0 each time, so the newest
          // (highest) id ends up on top of the list.
          for (let i = 0; i < 5; i++) {
            this.dataSource.addAtTop(new LogEntry(this.nextId))
            this.nextId++
          }
          this.entryCount = this.dataSource.totalCount()
          this.isRefreshing = false
        }, 1000)
      })
    }
    .width('100%')
    .height('100%')
  }
}

@Component
struct LogRow {
  @Prop message: string = ''
  @Prop level: string = ''

  build() {
    Row() {
      Text(this.message)
        .fontSize(16)
        .fontColor('#212121')
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis })
        .layoutWeight(1)

      Text(this.level)
        .fontSize(14)
        .fontColor(levelColor(this.level))
        .margin({ left: 12 })
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .border({ width: { bottom: 0.5 }, color: '#E0E0E0' })
    .alignItems(VerticalAlign.Center)
  }
}

class Address {
  id: string
  label: string
  street: string

  constructor(id: string, label: string, street: string) {
    this.id = id
    this.label = label
    this.street = street
  }
}

const ADDRESSES: Address[] = [
  new Address('home', 'Home', '12 Elm Street'),
  new Address('work', 'Work', '400 Harbour Road'),
  new Address('gym', 'Gym', '7 Mill Lane')
]

@Entry
@Component
struct CheckoutPage {
  @Provide('largeText') largeText: boolean = false
  @State chosenId: string = 'home'
  private pathStack: NavPathStack = new NavPathStack()

  private labelOf(id: string): string {
    const found: Address | undefined = ADDRESSES.find((a: Address) => a.id === id)
    return found ? found.label : ''
  }

  @Builder
  pageMap(name: string) {
    if (name === 'addresses') {
      AddressesScreen()
    }
  }

  build() {
    Navigation(this.pathStack) {
      Column({ space: 24 }) {
        Text('Deliver to: ' + this.labelOf(this.chosenId))
          .fontSize(20)

        Button('Change address')
          .onClick(() => {
            this.pathStack.pushPath(
              { name: 'addresses', param: this.chosenId },
              (popInfo: PopInfo) => {
                if (popInfo.result !== undefined && popInfo.result !== null) {
                  this.chosenId = popInfo.result as string
                }
              }
            )
          })

        Row({ space: 12 }) {
          Text('Large text')
            .fontSize(20)
          Toggle({ type: ToggleType.Switch, isOn: this.largeText })
            .onChange((isOn: boolean) => {
              this.largeText = isOn
            })
        }
      }
      .padding(20)
    }
    .title('Checkout')
    .mode(NavigationMode.Stack)
    .navDestination(this.pageMap)
  }
}

@Component
struct AddressesScreen {
  @State currentId: string = ''
  private pathStack: NavPathStack | null = null

  build() {
    NavDestination() {
      Column() {
        ForEach(ADDRESSES, (a: Address) => {
          AddressRow({
            address: a,
            isCurrent: this.currentId === a.id,
            onPick: (id: string) => {
              if (this.pathStack !== null) {
                this.pathStack.pop(id)
              }
            }
          })
        }, (a: Address) => a.id)
      }
    }
    .title('Addresses')
    .onReady((context: NavDestinationContext) => {
      this.pathStack = context.pathStack
      const param = context.pathInfo.param
      if (param !== undefined && param !== null) {
        this.currentId = param as string
      }
    })
  }
}

@Component
struct AddressRow {
  @Consume('largeText') largeText: boolean
  private address: Address = new Address('', '', '')
  private isCurrent: boolean = false
  private onPick: (id: string) => void = () => {}

  build() {
    Row({ space: 12 }) {
      Column({ space: 4 }) {
        Text(this.address.label)
          .fontSize(this.largeText ? 24 : 16)
        Text(this.address.street)
          .fontSize(this.largeText ? 24 : 16)
      }
      .alignItems(HorizontalAlign.Start)
      .layoutWeight(1)

      if (this.isCurrent) {
        Text('Current')
          .fontSize(this.largeText ? 24 : 16)
      }
    }
    .width('100%')
    .padding(16)
    .onClick(() => {
      this.onPick(this.address.id)
    })
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

const ORDER_FIELDS: string[] = ['id', 'status', 'lines'];
const LINE_FIELDS: string[] = ['sku', 'quantity', 'unitPrice'];
const STATUS_VALUES: string[] = ['draft', 'paid', 'shipped'];

function isJSONObject(value: Object | undefined | null): boolean {
  return value !== undefined && value !== null &&
    typeof value === 'object' && !Array.isArray(value);
}

export function parseOrder(text: string): ParseResult {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(text) as Object;
  } catch (e) {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }
  if (!isJSONObject(parsed)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const obj = parsed as Record<string, Object>;
  const errors: FieldError[] = [];

  let id: string | undefined = undefined;
  let status: OrderStatus = OrderStatus.Draft;
  const lines: OrderLine[] = [];

  // id
  const idVal = obj['id'];
  if (idVal === undefined || idVal === null) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof idVal !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (idVal === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  } else {
    id = idVal as string;
  }

  // status
  const statusVal = obj['status'];
  if (statusVal !== undefined && statusVal !== null) {
    if (typeof statusVal === 'string' && STATUS_VALUES.indexOf(statusVal as string) >= 0) {
      const s = statusVal as string;
      if (s === 'draft') {
        status = OrderStatus.Draft;
      } else if (s === 'paid') {
        status = OrderStatus.Paid;
      } else {
        status = OrderStatus.Shipped;
      }
    } else {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  }

  // lines
  const linesVal = obj['lines'];
  if (linesVal === undefined || linesVal === null) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(linesVal)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else {
    const arr = linesVal as Object[];
    if (arr.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
      for (let i = 0; i < arr.length; i++) {
        const base = `lines[${i}]`;
        const elem = arr[i];
        if (!isJSONObject(elem)) {
          errors.push({ path: base, message: 'expected an object' });
          continue;
        }
        const lineObj = elem as Record<string, Object>;

        let sku: string | undefined = undefined;
        let quantity: number | undefined = undefined;
        let unitPrice: number | undefined = undefined;

        // sku
        const skuVal = lineObj['sku'];
        if (skuVal === undefined || skuVal === null) {
          errors.push({ path: `${base}.sku`, message: 'required' });
        } else if (typeof skuVal !== 'string') {
          errors.push({ path: `${base}.sku`, message: 'expected a string' });
        } else if (skuVal === '') {
          errors.push({ path: `${base}.sku`, message: 'must not be empty' });
        } else {
          sku = skuVal as string;
        }

        // quantity
        const qtyVal = lineObj['quantity'];
        if (qtyVal === undefined || qtyVal === null) {
          errors.push({ path: `${base}.quantity`, message: 'required' });
        } else if (typeof qtyVal !== 'number') {
          errors.push({ path: `${base}.quantity`, message: 'expected a number' });
        } else if (!Number.isInteger(qtyVal) || qtyVal < 1) {
          errors.push({ path: `${base}.quantity`, message: 'must be a whole number of 1 or more' });
        } else {
          quantity = qtyVal as number;
        }

        // unitPrice
        const priceVal = lineObj['unitPrice'];
        if (priceVal === undefined || priceVal === null) {
          errors.push({ path: `${base}.unitPrice`, message: 'required' });
        } else if (typeof priceVal !== 'number') {
          errors.push({ path: `${base}.unitPrice`, message: 'expected a number' });
        } else if (priceVal < 0) {
          errors.push({ path: `${base}.unitPrice`, message: 'must be 0 or more' });
        } else {
          unitPrice = priceVal as number;
        }

        // unknown fields of the line
        const lineKeys = Object.keys(lineObj);
        for (let k = 0; k < lineKeys.length; k++) {
          const key = lineKeys[k];
          if (LINE_FIELDS.indexOf(key) < 0) {
            errors.push({ path: `${base}.${key}`, message: 'unknown field' });
          }
        }

        lines.push(new OrderLine(
          sku === undefined ? '' : sku,
          quantity === undefined ? 0 : quantity,
          unitPrice === undefined ? 0 : unitPrice
        ));
      }
    }
  }

  // unknown fields of the order
  const orderKeys = Object.keys(obj);
  for (let k = 0; k < orderKeys.length; k++) {
    const key = orderKeys[k];
    if (ORDER_FIELDS.indexOf(key) < 0) {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  }
  return {
    order: { id: id === undefined ? '' : id, status: status, lines: lines },
    errors: []
  };
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface QueueEntry {
  run: () => void;
  cancel: () => void;
}

export class JobQueue {
  private readonly limit: number;
  private runningCount: number = 0;
  private waitingList: Array<QueueEntry> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (Math.floor(concurrency) !== concurrency || concurrency < 1) {
      throw new Error('concurrency must be a whole number of at least 1');
    }
    this.limit = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingList.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  public add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve: (value: T) => void, reject: (reason: Error) => void) => {
      const entry: QueueEntry = {
        run: (): void => {
          this.runningCount++;
          job().then((value: T) => {
            this.runningCount--;
            this.completedCount++;
            resolve(value);
            this.afterSettled();
          }).catch((reason: Error) => {
            this.runningCount--;
            this.failedCount++;
            reject(reason);
            this.afterSettled();
          });
        },
        cancel: (): void => {
          reject(new Error('Job was cancelled'));
        }
      };
      this.waitingList.push(entry);
      this.startWaitingJobs();
    });
  }

  public pause(): void {
    this.paused = true;
  }

  public resume(): void {
    this.paused = false;
    this.startWaitingJobs();
  }

  public clear(): number {
    const removed: Array<QueueEntry> = this.waitingList;
    this.waitingList = [];
    const count: number = removed.length;
    for (let i: number = 0; i < removed.length; i++) {
      removed[i].cancel();
    }
    this.checkIdle();
    return count;
  }

  public whenIdle(): Promise<void> {
    return new Promise<void>((resolve: () => void) => {
      if (this.runningCount === 0 && this.waitingList.length === 0) {
        resolve();
      } else {
        this.idleResolvers.push(resolve);
      }
    });
  }

  public runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    return new Promise<Array<JobOutcome<T>>>((resolveAll: (value: Array<JobOutcome<T>>) => void) => {
      const outcomes: Array<JobOutcome<T>> = [];
      for (let i: number = 0; i < jobs.length; i++) {
        const initial: JobOutcome<T> = { ok: false, value: undefined, error: undefined };
        outcomes.push(initial);
      }
      if (jobs.length === 0) {
        resolveAll(outcomes);
        return;
      }
      let remaining: number = jobs.length;
      for (let i: number = 0; i < jobs.length; i++) {
        const index: number = i;
        this.add<T>(jobs[index]).then((value: T) => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          outcomes[index] = outcome;
          remaining--;
          if (remaining === 0) {
            resolveAll(outcomes);
          }
        }).catch((reason: Error) => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: reason };
          outcomes[index] = outcome;
          remaining--;
          if (remaining === 0) {
            resolveAll(outcomes);
          }
        });
      }
    });
  }

  private startWaitingJobs(): void {
    while (!this.paused && this.waitingList.length > 0 && this.runningCount < this.limit) {
      const entry: QueueEntry | undefined = this.waitingList.shift();
      if (entry !== undefined) {
        entry.run();
      }
    }
  }

  private afterSettled(): void {
    this.startWaitingJobs();
    this.checkIdle();
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.waitingList.length === 0) {
      const waiters: Array<() => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (let i: number = 0; i < waiters.length; i++) {
        waiters[i]();
      }
    }
  }
}

