// App-wide reading settings live in AppStorage under these keys.
// Any component on any page can read or write them and is redrawn on change.
const KEY_TEXT_SIZE: string = 'readingTextSize';
const KEY_BOLD: string = 'readingBold';

const MIN_SIZE: number = 14;
const MAX_SIZE: number = 30;
const STEP: number = 2;

// A preset is data: a label and a whole-number size.
class SizePreset {
  label: string;
  size: number;

  constructor(label: string, size: number) {
    this.label = label;
    this.size = size;
  }
}

// The three presets held in this file.
const PRESETS: SizePreset[] = [
  new SizePreset('Small', 14),
  new SizePreset('Medium', 18),
  new SizePreset('Large', 24)
];

@Entry
@Component
struct Index {
  @StorageLink(KEY_TEXT_SIZE) textSize: number = 18;
  @StorageLink(KEY_BOLD) bold: boolean = false;

  build() {
    Column({ space: 24 }) {
      // "Bold" label with a switch next to it.
      Row({ space: 12 }) {
        Text('Bold')
          .fontSize(16)
        Toggle({ type: ToggleType.Switch, isOn: this.bold })
          .onChange((isOn: boolean) => {
            this.bold = isOn;
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      SizeControls()
      ReadingPreview()
      ChangeCounter()
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .padding(24)
  }
}

// The size controls. Reads and changes the app-wide text size on its own.
@Component
struct SizeControls {
  @StorageLink(KEY_TEXT_SIZE) textSize: number = 18;

  private clamp(value: number): number {
    if (value < MIN_SIZE) {
      return MIN_SIZE;
    }
    if (value > MAX_SIZE) {
      return MAX_SIZE;
    }
    return value;
  }

  build() {
    Column({ space: 12 }) {
      Row({ space: 12 }) {
        Button('A-')
          .onClick(() => {
            this.textSize = this.clamp(this.textSize - STEP);
          })
        Text(this.textSize.toString())
          .fontSize(16)
          .width(40)
          .textAlign(TextAlign.Center)
        Button('A+')
          .onClick(() => {
            this.textSize = this.clamp(this.textSize + STEP);
          })
      }

      Row({ space: 12 }) {
        ForEach(PRESETS, (preset: SizePreset, index: number) => {
          Button(preset.label)
            .onClick(() => {
              this.textSize = preset.size;
            })
        }, (preset: SizePreset, index: number) => index.toString())
      }
    }
  }
}

// The preview. Draws the sentence at the text size, bold when bold is on.
// When the size changes it grows or shrinks smoothly over 300 ms.
@Component
struct ReadingPreview {
  @StorageProp(KEY_TEXT_SIZE) @Watch('onTextSizeChange') textSize: number = 18;
  @StorageProp(KEY_BOLD) bold: boolean = false;
  @State displaySize: number = 18;

  aboutToAppear(): void {
    this.displaySize = this.textSize;
  }

  onTextSizeChange(): void {
    this.getUIContext().animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
      this.displaySize = this.textSize;
    });
  }

  build() {
    Text('The quick brown fox')
      .fontSize(this.displaySize)
      .fontWeight(this.bold ? FontWeight.Bold : FontWeight.Normal)
  }
}

// The change counter. Counts changes of the text size to a different value.
// Bold changes are not counted. It owns its count and never changes a setting.
@Component
struct ChangeCounter {
  @StorageProp(KEY_TEXT_SIZE) @Watch('onTextSizeChange') textSize: number = 18;
  @State count: number = 0;
  private lastSize: number = 18;

  aboutToAppear(): void {
    this.lastSize = this.textSize;
  }

  onTextSizeChange(): void {
    if (this.textSize !== this.lastSize) {
      this.lastSize = this.textSize;
      this.count += 1;
    }
  }

  build() {
    Text(`Changed ${this.count} times`)
      .fontSize(16)
  }
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  return {
    min: min,
    max: max,
    width: max.x - min.x,
    height: max.y - min.y
  };
}

