// A quick choice for the daily goal, as data.
class GoalPreset {
  label: string
  glasses: number

  constructor(label: string, glasses: number) {
    this.label = label
    this.glasses = glasses
  }
}

// The three quick choices held in this file.
const GOAL_PRESETS: GoalPreset[] = [
  new GoalPreset('Light', 6),
  new GoalPreset('Standard', 8),
  new GoalPreset('Active', 12)
]

// Persistent storage keys: the count and the goal survive app restarts.
// On the very first run they fall back to the defaults 0 and 8.
PersistentStorage.persistProp<number>('waterCount', 0)
PersistentStorage.persistProp<number>('waterGoal', 8)

// The dialog shown on top of the page to change the daily goal.
@CustomDialog
struct GoalDialog {
  controller?: CustomDialogController
  // Function handed in by the page. The dialog never changes the goal itself.
  onSave: (glasses: number) => void = (glasses: number) => {}
  @State input: string = ''

  // The field is empty whenever the dialog opens: the input is cleared
  // every time the dialog is closed (Cancel or Save).
  build() {
    Column({ space: 16 }) {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Glasses per day', text: this.input })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.input = value
        })

      Row({ space: 8 }) {
        ForEach(GOAL_PRESETS, (preset: GoalPreset) => {
          Button(preset.label)
            .onClick(() => {
              this.input = preset.glasses.toString()
            })
