// Self-contained query-string parser for HarmonyOS (ArkTS, stage model).

function decodeComponent(s: string): string {
  // Replace '+' with space first.
  let t = s.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(t);
  } catch (e) {
    // Malformed escape: keep as written, with only '+' replaced.
    return t;
  }
}

export function parseQuery(query: string): Map<string, string> {
  const map = new Map<string, string>();

  let q = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return map;
  }

  const parts = q.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part.length === 0) {
      continue;
    }

    const eq = part.indexOf('=');
    let rawKey: string;
    let rawVal: string;
    if (eq === -1) {
      rawKey = part;
      rawVal = '';
    } else {
      rawKey = part.substring(0, eq);
      rawVal = part.substring(eq + 1);
    }

    const key = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const val = decodeComponent(rawVal);

    // Setting an existing key updates its value while keeping its first position.
    map.set(key, val);
  }

  return map;
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number = 0;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigitChar(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStartChar(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNamePartChar(c: string): boolean {
  return isNameStartChar(c) || isDigitChar(c);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const len = source.length;
  let i = 0;
  while (i < len) {
    const c = source.charAt(i);
    if (c === ' ') {
      i++;
      continue;
    }
    const start = i;
    if (isDigitChar(c)) {
      i++;
      while (i < len && isDigitChar(source.charAt(i))) {
        i++;
      }
      if (i < len && source.charAt(i) === '.' && i + 1 < len && isDigitChar(source.charAt(i + 1))) {
        i++;
        while (i < len && isDigitChar(source.charAt(i))) {
          i++;
        }
      }
      const tok: Token = { kind: 'number', text: source.substring(start, i), position: start };
      tokens.push(tok);
      continue;
    }
    if (isNameStartChar(c)) {
      i++;
      while (i < len && isNamePartChar(source.charAt(i))) {
        i++;
      }
      const tok: Token = { kind: 'name', text: source.substring(start, i), position: start };
      tokens.push(tok);
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      const tok: Token = { kind: 'operator', text: c, position: start };
      tokens.push(tok);
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      const tok: Token = { kind: 'paren', text: c, position: start };
      tokens.push(tok);
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, start);
  }
  return tokens;
}

interface Node {
  kind: string;
  position: number;
  value: number;
  name: string;
  op: string;
  child: Node | null;
  left: Node | null;
  right: Node | null;
}

function makeNode(kind: string, position: number): Node {
  const n: Node = {
    kind: kind,
    position: position,
    value: 0,
    name: '',
    op: '',
    child: null,
    left: null,
    right: null
  };
  return n;
}

class Parser {
  private tokens: Token[];
  private pos: number = 0;
  private sourceLength: number;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
  }

  private peek(): Token | null {
    if (this.pos < this.tokens.length) {
      return this.tokens[this.pos];
    }
    return null;
  }

  parse(): Node {
    const root = this.parseExpression();
    const extra = this.peek();
    if (extra !== null) {
      throw new ExpressionError(`Unexpected token '${extra.text}'`, extra.position);
    }
    return root;
  }

  private parseExpression(): Node {
    let left = this.parseTerm();
    while (this.pos < this.tokens.length) {
      const t = this.tokens[this.pos];
      if (t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.pos++;
        const right = this.parseTerm();
        const n = makeNode('binary', t.position);
        n.op = t.text;
        n.left = left;
        n.right = right;
        left = n;
      } else {
        break;
      }
    }
    return left;
  }

  private parseTerm(): Node {
    let left = this.parseFactor();
    while (this.pos < this.tokens.length) {
      const t = this.tokens[this.pos];
      if (t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.pos++;
        const right = this.parseFactor();
        const n = makeNode('binary', t.position);
        n.op = t.text;
        n.left = left;
        n.right = right;
        left = n;
      } else {
        break;
      }
    }
    return left;
  }

  private parseFactor(): Node {
    const t = this.peek();
    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (t.kind === 'operator' && t.text === '-') {
      this.pos++;
      const child = this.parseFactor();
      const n = makeNode('unary', t.position);
      n.child = child;
      return n;
    }
    return this.parsePrimary();
  }

  private parsePrimary(): Node {
    const t = this.peek();
    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (t.kind === 'number') {
      this.pos++;
      const n = makeNode('number', t.position);
      n.value = Number.parseFloat(t.text);
      return n;
    }
    if (t.kind === 'name') {
      this.pos++;
      const n = makeNode('name', t.position);
      n.name = t.text;
      return n;
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.pos++;
      const inner = this.parseExpression();
      const close = this.peek();
      if (close === null) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.pos++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function evalNode(node: Node, variables: Record<string, number>): number {
  if (node.kind === 'number') {
    return node.value;
  }
  if (node.kind === 'name') {
    const keys: string[] = Object.keys(variables);
    if (keys.indexOf(node.name) === -1) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return variables[node.name];
  }
  if (node.kind === 'unary') {
    if (node.child === null) {
      return 0;
    }
    return -evalNode(node.child, variables);
  }
  if (node.left === null || node.right === null) {
    return 0;
  }
  const left = evalNode(node.left, variables);
  const right = evalNode(node.right, variables);
  if (node.op === '+') {
    return left + right;
  }
  if (node.op === '-') {
    return left - right;
  }
  if (node.op === '*') {
    return left * right;
  }
  if (node.op === '/') {
    if (right === 0) {
      throw new ExpressionError('Division by zero', node.position);
    }
    return left / right;
  }
  if (right === 0) {
    throw new ExpressionError('Division by zero', node.position);
  }
  return left % right;
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const root = parser.parse();
  return evalNode(root, variables);
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const totalAttempts: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('');

  for (let i: number = 0; i < totalAttempts; i++) {
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(totalAttempts, lastError);
}

export interface CircleShape {
  kind: 'circle';
  radius: number;
}

export interface RectangleShape {
  kind: 'rectangle';
  width: number;
  height: number;
}

export interface TriangleShape {
  kind: 'triangle';
  base: number;
  height: number;
}

/**
 * A geometric shape. New kinds of shapes can be added later by
 * extending this union with another tagged interface.
 */
export type Shape = CircleShape | RectangleShape | TriangleShape;

export function circle(radius: number): Shape {
  return { kind: 'circle', radius: radius };
}

export function rectangle(width: number, height: number): Shape {
  return { kind: 'rectangle', width: width, height: height };
}

export function triangle(base: number, height: number): Shape {
  return { kind: 'triangle', base: base, height: height };
}

export function area(shape: Shape): number {
  if (shape.kind === 'circle') {
    return Math.PI * shape.radius * shape.radius;
  } else if (shape.kind === 'rectangle') {
    return shape.width * shape.height;
  } else {
    return shape.base * shape.height / 2;
  }
}

export function totalArea(shapes: Shape[]): number {
  let total: number = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += area(shapes[i]);
  }
  return total;
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  const result: User[] = [];

  let parsed: Object;
  try {
    parsed = JSON.parse(json) as Object;
  } catch (e) {
    return result;
  }

  if (parsed === null || parsed === undefined || !Array.isArray(parsed)) {
    return result;
  }

  const arr: Object[] = parsed as Object[];
  for (let i = 0; i < arr.length; i++) {
    const el: Object = arr[i];
    if (el === null || el === undefined || Array.isArray(el)) {
      continue;
    }

    const record: Record<string, Object> = el as Record<string, Object>;
    const id: Object = record['id'];
    const name: Object = record['name'];
    const email: Object = record['email'];

    if (id === undefined || name === undefined || email === undefined) {
      continue;
    }

    if (typeof id !== 'number' || !Number.isInteger(id as number)) {
      continue;
    }

    if (typeof name !== 'string' || (name as string).length === 0) {
      continue;
    }

    if (typeof email !== 'string' || (email as string).indexOf('@') < 0) {
      continue;
    }

    const user: User = {
      id: id as number,
      name: name as string,
      email: email as string
    };
    result.push(user);
  }

  return result;
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds < 0) {
    return '-' + formatDuration(-totalSeconds);
  }
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  const pad = (n: number): string => n < 10 ? '0' + n.toString() : n.toString();
  if (hours > 0) {
    return `${hours}h ${pad(minutes)}m ${pad(seconds)}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${pad(seconds)}s`;
  }
  return `${seconds}s`;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }
  let negative = false;
  let body = text;
  if (body[0] === '-') {
    negative = true;
    body = body.substring(1);
  }
  const pattern = /^-?(\d+(h|m|s))( \d+(h|m|s))*$/;
  if (!pattern.test(body)) {
    return NaN;
  }
  const parts = body.split(' ');
  let total = 0;
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    const unit = part[part.length - 1];
    const value = parseInt(part.substring(0, part.length - 1), 10);
    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
  }
  return negative ? -total : total;
}

