export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  for (let i = 0; i < items.length; i += size) {
    const end: number = Math.min(i + size, items.length);
    const group: T[] = items.slice(i, end);
    result.push(group);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const length: number = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = {
      first: a[i],
      second: b[i]
    };
    result.push(pair);
  }
  return result;
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  if (rules.length === 0) {
    return undefined;
  }

  const week: Weekday[] = [
    Weekday.Monday,
    Weekday.Tuesday,
    Weekday.Wednesday,
    Weekday.Thursday,
    Weekday.Friday,
    Weekday.Saturday,
    Weekday.Sunday
  ];

  const startIndex = week.indexOf(day);

  // The day itself is the last candidate (offset 7, i.e. one week later).
  for (let offset = 1; offset <= 7; offset++) {
    const candidate = week[(startIndex + offset) % week.length];
    let hasRule = false;
    for (let i = 0; i < rules.length; i++) {
      if (rules[i].day === candidate) {
        hasRule = true;
        break;
      }
    }
    if (hasRule) {
      return candidate;
    }
  }

  return undefined;
}

