// solution.ets
//
// A least-recently-used (LRU) cache for HarmonyOS NEXT (stage model, ArkTS, API 12+).
//
// Design notes:
// - A Map<K, V> holds the values. Map lookups use SameValueZero, which gives
//   exactly the key semantics we need:
//     * the number 1 and the string '1' are different keys,
//     * two objects are the same key only when they are the same object,
//     * NaN keys are still findable (SameValueZero treats NaN as equal to NaN).
// - A parallel array `order` tracks recency: order[0] is the least recently
//   used key, order[order.length - 1] the most recently used one. An array is
//   used instead of relying on Map iteration order so the code stays squarely
//   within ArkTS's supported feature set.
// - Key identity in `order` is checked with a helper that also treats two NaNs
//   as the same key (a !== a detects NaN without any type tricks).

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V> = new Map<K, V>();
  private order: K[] = [];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('LruCache: capacity must be a whole number of at least 1');
    }
    this.capacity = capacity;
  }

  /**
   * True when `a` and `b` are the same key.
   * - For objects, `===` is reference identity.
   * - For primitives, `===` is strict equality.
   * - NaN is the only value that is not strictly equal to itself, so
   *   `a !== a && b !== b` means "both are NaN".
   */
  private sameKey(a: K, b: K): boolean {
    if (a === b) {
      return true;
    }
    return a !== a && b !== b;
  }

  /** Index of `key` inside `this.order`, or -1 when absent. */
  private indexOfKey(key: K): number {
    for (let i = 0; i < this.order.length; i++) {
      if (this.sameKey(this.order[i], key)) {
        return i;
      }
    }
    return -1;
  }

  /** Remove `key` from the recency order (it stays in the value map). */
  private unlink(key: K): void {
    const idx = this.indexOfKey(key);
    if (idx >= 0) {
      this.order.splice(idx, 1);
    }
  }

  /**
   * Stores `value` under `key` and makes `key` the most recently used key.
   * When the cache would then exceed `capacity`, the least recently used
   * key is dropped.
   */
  set(key: K, value: V): void {
    if (this.map.has(key)) {
      this.unlink(key);
    }
    this.map.set(key, value);
    this.order.push(key);

    // Evict least recently used keys until we are within capacity.
    while (this.order.length > this.capacity) {
      const oldest: K = this.order[0];
      this.order.shift();
      this.map.delete(oldest);
    }
  }

  /**
   * Returns the stored value for `key` and marks it most recently used.
   * Returns undefined for a missing key (which is not a use).
   */
  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }
    this.unlink(key);
    this.order.push(key);
    return this.map.get(key);
  }

  /** Whether `key` is stored. Does not count as a use. */
  has(key: K): boolean {
    return this.map.has(key);
  }

  /**
   * A new array of the stored keys, from least recently used to most
   * recently used. Does not count as a use and does not expose internal
   * state (a fresh array is returned every time).
   */
  keys(): K[] {
    return this.order.slice(0);
  }

  /** How many keys are currently stored. */
  get size(): number {
    return this.map.size;
  }
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
}

