@Entry
@Component
struct Index {
  @State selectedTiles: Set<number> = new Set<number>()
  private readonly totalTiles: number = 12

  build() {
    Column({ space: 16 }) {
      Text(`Selected: ${this.selectedTiles.size}`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 24 })

      Grid() {
        ForEach(this.getTileNumbers(), (number: number) => {
          GridItem() {
            Text(number.toString())
              .fontSize(24)
              .fontWeight(FontWeight.Medium)
              .fontColor(this.selectedTiles.has(number) ? Color.White : Color.Black)
              .textAlign(TextAlign.Center)
              .width('100%')
              .height('100%')
          }
          .aspectRatio(1)
          .backgroundColor(this.selectedTiles.has(number) ? Color.Blue : Color.Gray)
          .borderRadius(8)
          .margin(4)
          .onClick(() => {
            this.toggleSelection(number)
          })
        }, (number: number) => number.toString())
      }
      .columnsTemplate('1fr 1fr 1fr')
      .columnsGap(8)
      .rowsGap(8)
      .padding(16)
    }
    .width('100%')
    .height('100%')
  }

  private getTileNumbers(): number[] {
    const numbers: number[] = []
    for (let i = 1; i <= this.totalTiles; i++) {
      numbers.push(i)
    }
    return numbers
  }

  private toggleSelection(number: number): void {
    if (this.selectedTiles.has(number)) {
      this.selectedTiles.delete(number)
    } else {
      this.selectedTiles.add(number)
    }
    // Reassign the @State to trigger a UI update, since mutating a Set
    // in place is not observed by the state management system.
    this.selectedTiles = new Set<number>(this.selectedTiles)
  }
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

export class Pipeline {
  private steps: { name: string, step: Transform }[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name: name, step: step });
    return this;
  }

  run(text: string): string {
    let current: string = text;
    for (const item of this.steps) {
      current = item.step(current);
    }
    return current;
  }

  names(): string[] {
    return this.steps.map(item => item.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let current: string = text;
    for (const step of steps) {
      current = step(current);
    }
    return current;
  };
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  let found = false;
  const result: Item[] = [];

  for (const item of items) {
    if (item.id === id) {
      found = true;
      if (quantity > 0) {
        result.push({ id: item.id, name: item.name, quantity: quantity });
      }
    } else {
      result.push(item);
    }
  }

  if (!found) {
    return items;
  }

  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let currentItems = items;

  for (const change of changes) {
    currentItems = updateQuantity(currentItems, change.id, change.quantity);
  }

  return currentItems;
}

