const PREFERENCES_NAME: string = 'my_app_prefs';
const KEY_NAME: string = 'saved_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State typedName: string = '';
  private prefs?: preferences.Preferences;

  private async loadPreferences(): Promise<void> {
    try {
      this.prefs = await preferences.getPreferences(getContext(this), PREFERENCES_NAME);
      const value = await this.prefs.get(KEY_NAME, '') as string;
      this.savedName = value;
    } catch (err) {
      const e: BusinessError = err as BusinessError;
      console.error(`Failed to load preferences. Code: ${e.code}, message: ${e.message}`);
    }
  }

  private async saveName(): Promise<void> {
    if (!this.prefs) {
      return;
    }
    try {
      await this.prefs.put(KEY_NAME, this.typedName);
      await this.prefs.flush();
      this.savedName = this.typedName;
    } catch (err) {
      const e: BusinessError = err as BusinessError;
      console.error(`Failed to save name. Code: ${e.code}, message: ${e.message}`);
    }
  }

  aboutToAppear(): void {
    this.loadPreferences();
  }

  build() {
    Column({ space: 16 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
