import { http } from '@kit.NetworkKit';

interface Item {
  id: number;
  name: string;
}

@Entry
@Component
struct Index {
  @State isLoading: boolean = true;
  @State failed: boolean = false;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.fetchItems();
  }

  private onFailure(): void {
    this.items = [];
    this.failed = true;
    this.isLoading = false;
  }

  private fetchItems(): void {
    this.isLoading = true;
    this.failed = false;
    this.items = [];

    const httpRequest = http.createHttp();
    httpRequest.request('https://example.com/api/items', {
      method: http.RequestMethod.GET,
      expectDataType: http.HttpDataType.STRING,
      connectTimeout: 15000,
      readTimeout: 15000
    }).then((response: http.HttpResponse) => {
      if (response.responseCode !== 200) {
        this.onFailure();
        return;
      }

      let parsed: object | null = null;
      try {
        parsed = JSON.parse(response.result as string);
      } catch (err) {
        this.onFailure();
        return;
      }

      if (parsed === null || !Array.isArray(parsed)) {
        this.onFailure();
        return;
      }

      const rawItems = parsed as Array<Record<string, Object>>;
      const items: Item[] = [];
      for (const entry of rawItems) {
        const id = entry['id'];
        const name = entry['name'];
        if (typeof id === 'number' && typeof name === 'string') {
          items.push({ id: id, name: name });
        }
      }

      this.items = items;
      this.isLoading = false;
      this.failed = false;
    }).catch(() => {
      this.onFailure();
    }).finally(() => {
      httpRequest.destroy();
    });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(18)
          .padding(16)
      } else if (this.failed) {
        Text('Could not load the items')
          .fontSize(18)
          .padding(16)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .padding(16)
                .width('100%')
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .layoutWeight(1)
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Start)
  }
}

