export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super();
    this.task = task;
    this.dependency = dependency;
    this.name = 'MissingDependencyError';
    this.message = `Task '${task}' depends on unknown task '${dependency}'`;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super();
    this.path = path;
    this.name = 'CycleError';
    this.message = `Dependency cycle: ${path.join(' -> ')}`;
  }
}

export class BuildPlan {
  private keys: string[] = [];
  private deps: Map<string, string[]> = new Map();
  private keySet: Set<string> = new Set();
  private orderList: string[] = [];

  constructor(spec: Record<string, string[]>) {
    const names: string[] = Object.keys(spec);
    this.keys = names;
    for (const n of names) {
      this.keySet.add(n);
      const list: string[] = spec[n];
      this.deps.set(n, list);
    }

    // Every dependency must be a known task.
    for (const n of names) {
      const list: string[] = spec[n];
      for (const d of list) {
        if (!this.keySet.has(d)) {
          throw new MissingDependencyError(n, d);
        }
      }
    }

    // Place the tasks in key order, detecting cycles.
    const placed: Set<string> = new Set();
    const chain: string[] = [];
    for (const n of names) {
      this.place(n, placed, chain);
    }
  }

  private place(name: string, placed: Set<string>, chain: string[]): void {
    if (placed.has(name)) {
      return;
    }
    const idx: number = chain.indexOf(name);
    if (idx >= 0) {
      const path: string[] = chain.slice(idx);
      path.push(name);
      throw new CycleError(path);
    }
    chain.push(name);
    const list: string[] | undefined = this.deps.get(name);
    if (list !== undefined) {
      for (const d of list) {
        this.place(d, placed, chain);
      }
    }
    chain.pop();
    placed.add(name);
    this.orderList.push(name);
  }

  order(): string[] {
    return this.orderList.slice();
  }

  layers(): string[][] {
    const levels: Map<string, number> = new Map();
    for (const name of this.orderList) {
      let level: number = 0;
      const list: string[] | undefined = this.deps.get(name);
      if (list !== undefined) {
        for (const d of list) {
          const depLevel: number | undefined = levels.get(d);
          if (depLevel !== undefined && depLevel + 1 > level) {
            level = depLevel + 1;
          }
        }
      }
      levels.set(name, level);
    }

    const result: string[][] = [];
    for (const k of this.keys) {
      const level: number | undefined = levels.get(k);
      if (level === undefined) {
        continue;
      }
      while (result.length <= level) {
        result.push([]);
      }
      result[level].push(k);
    }
    return result;
  }

  dependentsOf(name: string): string[] {
    if (!this.keySet.has(name)) {
      return [];
    }

    // For every task, the set of all tasks it depends on, directly or not.
    const allDeps: Map<string, Set<string>> = new Map();
    for (const t of this.orderList) {
      const set: Set<string> = new Set();
      const list: string[] | undefined = this.deps.get(t);
      if (list !== undefined) {
        for (const d of list) {
          set.add(d);
          const sub: Set<string> | undefined = allDeps.get(d);
          if (sub !== undefined) {
            for (const s of sub) {
              set.add(s);
            }
          }
        }
      }
      allDeps.set(t, set);
    }

    const result: string[] = [];
    for (const t of this.orderList) {
      if (t === name) {
        continue;
      }
      const set: Set<string> | undefined = allDeps.get(t);
      if (set !== undefined && set.has(name)) {
        result.push(t);
      }
    }
    return result;
  }
}

export interface EditorState {
  text: string
  cursor: number
  bold: boolean
}

type FieldValue = string | number | boolean
type FieldListener = (value: FieldValue, previous: FieldValue) => void
type Unsubscribe = () => void

function copyState(source: EditorState): EditorState {
  const copy: EditorState = {
    text: source.text,
    cursor: source.cursor,
    bold: source.bold
  }
  return copy
}

export class EditorStore {
  private current: EditorState
  private readonly limit: number
  private past: EditorState[] = []
  private future: EditorState[] = []
  private listeners: Map<string, FieldListener[]> = new Map()

  constructor(initial: EditorState, historyLimit: number) {
    this.current = copyState(initial)
    this.limit = historyLimit
  }

  get state(): EditorState {
    return copyState(this.current)
  }

  get canUndo(): boolean {
    return this.past.length > 0
  }

  get canRedo(): boolean {
    return this.future.length > 0
  }

  apply(patch: Partial<EditorState>): boolean {
    const next: EditorState = copyState(this.current)
    if (patch.text !== undefined) {
      next.text = patch.text
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold
    }
    return this.commit(next)
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = copyState(this.current)
    run(draft)
    const next: EditorState = copyState(this.current)
    if (draft.text !== undefined) {
      next.text = draft.text
    }
    if (draft.cursor !== undefined) {
      next.cursor = draft.cursor
    }
    if (draft.bold !== undefined) {
      next.bold = draft.bold
    }
    return this.commit(next)
  }

  undo(): boolean {
    if (this.past.length === 0) {
      return false
    }
    const target: EditorState | undefined = this.past.pop()
    if (target === undefined) {
      return false
    }
    const before: EditorState = this.current
    this.future.push(copyState(before))
    this.current = copyState(target)
    this.notify(before, this.current)
    return true
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false
    }
    const target: EditorState | undefined = this.future.pop()
    if (target === undefined) {
      return false
    }
    const before: EditorState = this.current
    this.rememberPast(copyState(before))
    this.current = copyState(target)
    this.notify(before, this.current)
    return true
  }

  watch(field: string, listener: FieldListener): Unsubscribe {
    let list: FieldListener[] | undefined = this.listeners.get(field)
    if (list === undefined) {
      list = []
      this.listeners.set(field, list)
    }
    list.push(listener)
    return (): void => {
      const currentList: FieldListener[] | undefined = this.listeners.get(field)
      if (currentList === undefined) {
        return
      }
      const index: number = currentList.indexOf(listener)
      if (index >= 0) {
        currentList.splice(index, 1)
      }
    }
  }

  private commit(next: EditorState): boolean {
    const before: EditorState = this.current
    if (next.text === before.text && next.cursor === before.cursor && next.bold === before.bold) {
      return false
    }
    this.rememberPast(copyState(before))
    this.future = []
    this.current = next
    this.notify(before, next)
    return true
  }

  private rememberPast(snapshot: EditorState): void {
    this.past.push(snapshot)
    while (this.past.length > this.limit) {
      this.past.shift()
    }
  }

  private notify(before: EditorState, after: EditorState): void {
    this.notifyField('text', before.text, after.text)
    this.notifyField('cursor', before.cursor, after.cursor)
    this.notifyField('bold', before.bold, after.bold)
  }

  private notifyField(field: string, previous: FieldValue, value: FieldValue): void {
    if (previous === value) {
      return
    }
    const list: FieldListener[] | undefined = this.listeners.get(field)
    if (list === undefined || list.length === 0) {
      return
    }
    const snapshot: FieldListener[] = list.slice(0)
    for (const listener of snapshot) {
      listener(value, previous)
    }
  }
}

