// A log viewer page: 3000 entries rendered lazily, with pull-to-refresh
// adding five new entries at the top after one second.

class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number, message: string, level: string) {
    this.id = id;
    this.message = message;
    this.level = level;
  }
}

function makeLogEntry(id: number): LogEntry {
  let level: string = 'info';
  if (id % 50 === 0) {
    level = 'error';
  } else if (id % 10 === 0) {
    level = 'warning';
  }
  return new LogEntry(id, `Event ${id}`, level);
}

function levelColor(level: string): ResourceColor {
  if (level === 'error') {
    return '#D32F2F';
  }
  if (level === 'warning') {
    return '#F57C00';
  }
  return '#757575';
}

class LogDataSource implements IDataSource {
  private listeners: DataChangeListener[] = [];
  private entries: LogEntry[] = [];

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos: number = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  // Append during initial construction; no listeners are attached yet.
  append(entry: LogEntry): void {
    this.entries.push(entry);
  }

  // Insert a new highest-id entry at the front and notify the lazy list.
  insertAtFront(entry: LogEntry): void {
    this.entries.unshift(entry);
    for (const listener of this.listeners) {
      listener.onDataAdd(0);
    }
  }
}

