@Entry
@Component
struct Index {
  @State refreshing: boolean = false;
  @State count: number = 0;
  private dataSource: LogDataSource = new LogDataSource();
  private highestId: number = 0;

  aboutToAppear(): void {
    // Highest id first: 3000, 2999, ... 1.
    for (let id: number = 3000; id >= 1; id--) {
      this.dataSource.append(makeLogEntry(id));
    }
    this.highestId = 3000;
    this.count = this.dataSource.totalCount();
  }

  private addNewEntries(): void {
    for (let i: number = 0; i < 5; i++) {
      this.highestId++;
      this.dataSource.insertAtFront(makeLogEntry(this.highestId));
    }
    this.count = this.dataSource.totalCount();
  }

  build() {
    Column() {
      Text(`${this.count} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .padding(16)
        .width('100%')

      Refresh({ refreshing: $$this.refreshing }) {
        List() {
          LazyForEach(this.dataSource, (item: LogEntry) => {
            LogRow({ message: item.message, level: item.level })
          }, (item: LogEntry) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .cachedCount(5)
      }
      .layoutWeight(1)
      .width('100%')
      .onRefreshing(() => {
        setTimeout(() => {
          this.addNewEntries();
          this.refreshing = false;
        }, 1000);
      })
    }
    .width('100%')
    .height('100%')
  }
}

