export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueEntry {
  private runner: () => Promise<void>;
  private canceller: () => void;

  constructor(runner: () => Promise<void>, canceller: () => void) {
    this.runner = runner;
    this.canceller = canceller;
  }

  public run(): Promise<void> {
    return this.runner();
  }

  public cancel(): void {
    this.canceller();
  }
}

export class JobQueue {
  private concurrencyLimit: number;
  private paused: boolean = false;
  private pending: QueueEntry[] = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new Error('concurrency must be a whole number of at least 1');
    }
    this.concurrencyLimit = concurrency;
  }

  public add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const entry: QueueEntry = new QueueEntry(
        (): Promise<void> => {
          return job().then((value: T): void => {
            resolve(value);
            this.completedCount += 1;
            this.afterSettle();
          }, (err: Error): void => {
            reject(err);
            this.failedCount += 1;
            this.afterSettle();
          });
        },
        (): void => {
          reject(new Error('Job was cancelled'));
        }
      );
      this.enqueue(entry);
    });
  }

  public get running(): number {
    return this.runningCount;
  }

  public get waiting(): number {
    return this.pending.length;
  }

  public get completed(): number {
    return this.completedCount;
  }

  public get failed(): number {
    return this.failedCount;
  }

  public pause(): void {
    this.paused = true;
  }

  public resume(): void {
    this.paused = false;
    this.fill();
    this.checkIdle();
  }

  public clear(): number {
    const removed: QueueEntry[] = this.pending;
    this.pending = [];
    for (const entry of removed) {
      entry.cancel();
    }
    this.checkIdle();
    return removed.length;
  }

  public whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.pending.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleWaiters.push(resolve);
    });
  }

  public runAll<T>(jobs: Array<() => Promise<T>>): Promise<Array<JobOutcome<T>>> {
    return new Promise<Array<JobOutcome<T>>>((resolve) => {
      const total: number = jobs.length;
      if (total === 0) {
        resolve([]);
        return;
      }
      const outcomes: Array<JobOutcome<T>> = [];
      for (let i = 0; i < total; i++) {
        const placeholder: JobOutcome<T> = { ok: false, value: undefined, error: undefined };
        outcomes.push(placeholder);
      }
      let remaining: number = total;
      for (let i = 0; i < total; i++) {
        const idx: number = i;
        const job: () => Promise<T> = jobs[idx];
        this.add<T>(job).then((value: T): void => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          outcomes[idx] = outcome;
          remaining -= 1;
          if (remaining === 0) {
            resolve(outcomes);
          }
        }, (err: Error): void => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: err };
          outcomes[idx] = outcome;
          remaining -= 1;
          if (remaining === 0) {
            resolve(outcomes);
          }
        });
      }
    });
  }

  private enqueue(entry: QueueEntry): void {
    if (this.paused || this.runningCount >= this.concurrencyLimit) {
      this.pending.push(entry);
    } else {
      this.startEntry(entry);
    }
  }

  private startEntry(entry: QueueEntry): void {
    this.runningCount += 1;
    entry.run();
  }

  private afterSettle(): void {
    this.runningCount -= 1;
    this.fill();
    this.checkIdle();
  }

  private fill(): void {
    if (this.paused) {
      return;
    }
    while (this.runningCount < this.concurrencyLimit && this.pending.length > 0) {
      const entry: QueueEntry | undefined = this.pending.shift();
      if (entry !== undefined) {
        this.startEntry(entry);
      }
    }
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.pending.length === 0 && this.idleWaiters.length > 0) {
      const waiters: Array<() => void> = this.idleWaiters;
      this.idleWaiters = [];
      for (const waiter of waiters) {
        waiter();
      }
    }
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

function decodePart(s: string): string {
  const plusReplaced: string = s.replace(/\+/g, ' ');
  try {
    return decodeURIComponent(plusReplaced);
  } catch (e) {
    // Malformed escape: keep the text as written, with only '+' replaced.
    return plusReplaced;
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();

  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }

  const parts: string[] = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }

    let key: string = part;
    let value: string = '';
    const eqIndex: number = part.indexOf('=');
    if (eqIndex >= 0) {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    if (key.length === 0) {
      continue;
    }

    // Setting an existing key updates its value and keeps its first position.
    result.set(decodePart(key), decodePart(value));
  }

  return result;
}

