export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i: number = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };

  return box;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
  return settings;
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const result: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language,
  };
  return result;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map<string, Array<Listener<T>>>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.listeners.set(event, list);
    }
    if (list.indexOf(listener) < 0) {
      list.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    const index: number = list.indexOf(listener);
    if (index >= 0) {
      list.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined || list.length === 0) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = list.slice(0);
    for (const listener of snapshot) {
      listener(payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

export interface User {
  id: number
  name: string
  email: string
}

export function parseUsers(json: string): User[] {
  const users: User[] = []

  let parsed: Object | null = null
  try {
    parsed = JSON.parse(json) as Object | null
  } catch (e) {
    return users
  }

  if (parsed === null || !Array.isArray(parsed)) {
    return users
  }

  const items: Object[] = parsed as Object[]
  for (let i = 0; i < items.length; i++) {
    const el: Object = items[i]

    // Must be a plain object, not null and not a nested array.
    if (el === null || el === undefined) {
      continue
    }
    if (typeof el !== 'object') {
      continue
    }
    if (Array.isArray(el)) {
      continue
    }

    const rec: Record<string, Object | undefined> = el as Record<string, Object | undefined>

    const idVal: Object | undefined = rec['id']
    const nameVal: Object | undefined = rec['name']
    const emailVal: Object | undefined = rec['email']

    // id must be an integer number.
    if (typeof idVal !== 'number') {
      continue
    }
    if (!Number.isInteger(idVal)) {
      continue
    }

    // name must be a non-empty string.
    if (typeof nameVal !== 'string') {
      continue
    }
    if (nameVal.length === 0) {
      continue
    }

    // email must be a string containing '@'.
    if (typeof emailVal !== 'string') {
      continue
    }
    if (emailVal.indexOf('@') < 0) {
      continue
    }

    const user: User = {
      id: idVal,
      name: nameVal,
      email: emailVal
    }
    users.push(user)
  }

  return users
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

type JsonRecord = Record<string, Object | null | undefined>;

function readField(rec: JsonRecord, keys: string[], name: string): Object | null | undefined {
  if (keys.indexOf(name) < 0) {
    return undefined;
  }
  const value: Object | null | undefined = rec[name];
  if (value === null) {
    return undefined;
  }
  return value;
}

export function parseOrder(text: string): ParseResult {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    const parseErrors: FieldError[] = [{ path: '', message: 'invalid JSON' }];
    const invalidResult: ParseResult = { order: undefined, errors: parseErrors };
    return invalidResult;
  }
  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    const notObjectErrors: FieldError[] = [{ path: '', message: 'expected an object' }];
    const notObjectResult: ParseResult = { order: undefined, errors: notObjectErrors };
    return notObjectResult;
  }

  const root: JsonRecord = parsed as JsonRecord;
  const rootKeys: string[] = Object.keys(root);
  const errors: FieldError[] = [];

  // id
  let id: string | undefined = undefined;
  const idValue: Object | null | undefined = readField(root, rootKeys, 'id');
  if (idValue === undefined) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof idValue !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else {
    const idString: string = idValue as string;
    if (idString === '') {
      errors.push({ path: 'id', message: 'must not be empty' });
    } else {
      id = idString;
    }
  }

  // status
  let status: OrderStatus = OrderStatus.Draft;
  const statusValue: Object | null | undefined = readField(root, rootKeys, 'status');
  if (statusValue !== undefined) {
    if (typeof statusValue === 'string') {
      const statusString: string = statusValue as string;
      if (statusString === 'draft') {
        status = OrderStatus.Draft;
      } else if (statusString === 'paid') {
        status = OrderStatus.Paid;
      } else if (statusString === 'shipped') {
        status = OrderStatus.Shipped;
      } else {
        errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
      }
    } else {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  }

  // lines
  const lines: OrderLine[] = [];
  const linesValue: Object | null | undefined = readField(root, rootKeys, 'lines');
  if (linesValue === undefined) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(linesValue)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else {
    const lineObjects: (Object | null)[] = linesValue as (Object | null)[];
    if (lineObjects.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
      for (let i = 0; i < lineObjects.length; i++) {
        const linePath: string = 'lines[' + i.toString() + ']';
        const rawLine: Object | null = lineObjects[i];
        if (rawLine === null || typeof rawLine !== 'object' || Array.isArray(rawLine)) {
          errors.push({ path: linePath, message: 'expected an object' });
        } else {
          const lineRecord: JsonRecord = rawLine as JsonRecord;
          const lineKeys: string[] = Object.keys(lineRecord);

          let sku: string | undefined = undefined;
          let quantity: number = 0;
          let unitPrice: number = 0;

          // sku
          const skuValue: Object | null | undefined = readField(lineRecord, lineKeys, 'sku');
          if (skuValue === undefined) {
            errors.push({ path: linePath + '.sku', message: 'required' });
          } else if (typeof skuValue !== 'string') {
            errors.push({ path: linePath + '.sku', message: 'expected a string' });
          } else {
            const skuString: string = skuValue as string;
            if (skuString === '') {
              errors.push({ path: linePath + '.sku', message: 'must not be empty' });
            } else {
              sku = skuString;
            }
          }

          // quantity
          const quantityValue: Object | null | undefined = readField(lineRecord, lineKeys, 'quantity');
          if (quantityValue === undefined) {
            errors.push({ path: linePath + '.quantity', message: 'required' });
          } else if (typeof quantityValue !== 'number') {
            errors.push({ path: linePath + '.quantity', message: 'expected a number' });
          } else {
            const quantityNumber: number = quantityValue as number;
            if (quantityNumber % 1 !== 0 || quantityNumber < 1) {
              errors.push({ path: linePath + '.quantity', message: 'must be a whole number of 1 or more' });
            } else {
              quantity = quantityNumber;
            }
          }

          // unitPrice
          const priceValue: Object | null | undefined = readField(lineRecord, lineKeys, 'unitPrice');
          if (priceValue === undefined) {
            errors.push({ path: linePath + '.unitPrice', message: 'required' });
          } else if (typeof priceValue !== 'number') {
            errors.push({ path: linePath + '.unitPrice', message: 'expected a number' });
          } else {
            const priceNumber: number = priceValue as number;
            if (priceNumber < 0) {
              errors.push({ path: linePath + '.unitPrice', message: 'must be 0 or more' });
            } else {
              unitPrice = priceNumber;
            }
          }

          // unknown fields of the line, in text order
          for (const key of lineKeys) {
            if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
              errors.push({ path: linePath + '.' + key, message: 'unknown field' });
            }
          }

          lines.push(new OrderLine(sku as string, quantity, unitPrice));
        }
      }
    }
  }

  // unknown fields of the order, in text order
  for (const key of rootKeys) {
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    const failure: ParseResult = { order: undefined, errors: errors };
    return failure;
  }
  const order: Order = { id: id as string, status: status, lines: lines };
  const success: ParseResult = { order: order, errors: errors };
  return success;
}

