export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        const updatedItem: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updatedItem);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let currentItems: Item[] = items;
  for (const change of changes) {
    currentItems = updateQuantity(currentItems, change.id, change.quantity);
  }
  return currentItems;
}

export interface Pair<A, B> {
  first: A
  second: B
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1) {
    return []
  }
  const result: T[][] = []
  let index = 0
  while (index < items.length) {
    const end = index + size
    const group: T[] = []
    const limit = end < items.length ? end : items.length
    for (let i = index; i < limit; i++) {
      group.push(items[i])
    }
    result.push(group)
    index = end
  }
  return result
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = []
  const length = a.length < b.length ? a.length : b.length
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = {
      first: a[i],
      second: b[i]
    }
    result.push(pair)
  }
  return result
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday
  openHour: number
  closeHour: number
}

const DAYS_IN_WEEK: number = 7

function hasRuleFor(rules: OpeningRule[], day: Weekday): boolean {
  for (let i = 0; i < rules.length; i++) {
    if (rules[i].day === day) {
      return true
    }
  }
  return false
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i]
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true
    }
  }
  return false
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  for (let offset = 1; offset <= DAYS_IN_WEEK; offset++) {
    const candidate: Weekday = (day + offset) % DAYS_IN_WEEK as Weekday
    if (hasRuleFor(rules, candidate)) {
      return candidate
    }
  }
  return undefined
}

export type Transform = (text: string) => string;

export const trim = (text: string): string => {
  return text.trim();
};

export const lowerCase = (text: string): string => {
  return text.toLowerCase();
};

export const collapseSpaces = (text: string): string => {
  return text.replace(/\s+/g, ' ');
};

interface Step {
  name: string;
  fn: Transform;
}

export class Pipeline {
  private steps: Step[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name: name, fn: step });
    return this;
  }

  run(text: string): string {
    let current: string = text;
    for (const step of this.steps) {
      current = step.fn(current);
    }
    return current;
  }

  names(): string[] {
    const result: string[] = [];
    for (const step of this.steps) {
      result.push(step.name);
    }
    return result;
  }

  toFunction(): Transform {
    const self: Pipeline = this;
    return (text: string): string => {
      return self.run(text);
    };
  }
}

export const compose = (...steps: Transform[]): Transform => {
  const all: Transform[] = steps;
  return (text: string): string => {
    let current: string = text;
    for (const step of all) {
      current = step(current);
    }
    return current;
  };
};

export class Stack<T> {
  private items: T[] = []
  private capacity: number

  constructor(capacity: number) {
    this.capacity = capacity
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false
    }
    this.items.push(item)
    return true
  }

  pop(): T | undefined {
    return this.items.pop()
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined
    }
    return this.items[this.items.length - 1]
  }

  size(): number {
    return this.items.length
  }

  isEmpty(): boolean {
    return this.items.length === 0
  }

  isFull(): boolean {
    return this.items.length >= this.capacity
  }

  clear(): void {
    this.items = []
  }

  toArray(): T[] {
    return this.items.slice()
  }
}

