import { preferences } from '@kit.ArkData'
import { Context } from '@kit.AbilityKit'

const PREFERENCES_NAME: string = 'my_app_prefs'
const KEY_NAME: string = 'saved_name'

@Entry
@Component
struct Index {
  @State savedName: string = ''
  @State typedName: string = ''

  private getPreferences(): Promise<preferences.Preferences> {
    const context = this.getUIContext().getHostContext() as Context
    return preferences.getPreferences(context, PREFERENCES_NAME)
  }

  aboutToAppear(): void {
    this.getPreferences()
      .then((prefs: preferences.Preferences) => {
        const value = prefs.getSync(KEY_NAME, '') as string
        this.savedName = value
      })
      .catch(() => {
        this.savedName = ''
      })
  }

  private saveName(): void {
    const name: string = this.typedName.trim()
    this.getPreferences()
      .then((prefs: preferences.Preferences) => {
        prefs.putSync(KEY_NAME, name)
        prefs.flush()
        this.savedName = name
        this.typedName = ''
      })
      .catch(() => {
        // Saving failed; keep the current display unchanged.
      })
  }

  build() {
    Column({ space: 16 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(22)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Type your name', text: this.typedName })
        .onChange((value: string) => {
          this.typedName = value
        })
        .width('80%')

      Button('Save')
        .width('60%')
        .onClick(() => {
          this.saveName()
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import { http } from '@kit.NetworkKit';

class Item {
  id: number = 0;
  name: string = '';
}

enum LoadState {
  Loading,
  Success,
  Error
}

@Entry
@Component
struct Index {
  @State state: LoadState = LoadState.Loading
  @State items: Item[] = []

  aboutToAppear(): void {
    this.loadItems()
  }

  loadItems(): void {
    let httpRequest = http.createHttp()
    httpRequest.request('https://example.com/api/items', {
      method: http.RequestMethod.GET
    })
      .then((resp: http.HttpResponse) => {
        if (resp.responseCode === 200) {
          try {
            let parsed: object | null = JSON.parse(resp.result as string)
            if (parsed instanceof Array) {
              let result: Item[] = []
              for (let i = 0; i < parsed.length; i++) {
                let item: Item = parsed[i] as Item
                let copied: Item = new Item()
                copied.id = item.id
                copied.name = item.name
                result.push(copied)
              }
              this.items = result
              this.state = LoadState.Success
            } else {
              this.state = LoadState.Error
            }
          } catch (e) {
            this.state = LoadState.Error
          }
        } else {
          this.state = LoadState.Error
        }
        httpRequest.destroy()
      })
      .catch(() => {
        this.state = LoadState.Error
        httpRequest.destroy()
      })
  }

  build() {
    Column() {
      if (this.state === LoadState.Loading) {
        Text('Loading...')
          .fontSize(16)
          .margin(16)
      } else if (this.state === LoadState.Error) {
        Text('Could not load the items')
          .fontSize(16)
          .margin(16)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .padding(16)
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .layoutWeight(1)
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
  }
}

interface TodoItem {
  id: number
  text: string
}

@Entry
@Component
struct TodoPage {
  @State inputText: string = ''
  @State todos: TodoItem[] = []
  private nextId: number = 0

  private addTodo(): void {
    const trimmed: string = this.inputText.trim()
    if (trimmed.length === 0) {
      this.inputText = ''
      return
    }
    const todo: TodoItem = { id: this.nextId, text: trimmed }
    this.nextId += 1
    this.todos.push(todo)
    this.inputText = ''
  }

  private removeTodo(id: number): void {
    const index: number = this.todos.findIndex((item: TodoItem) => item.id === id)
    if (index >= 0) {
      this.todos.splice(index, 1)
    }
  }

  build() {
    Column() {
      Row() {
        TextInput({ text: this.inputText, placeholder: 'New todo' })
          .type(InputType.Normal)
          .layoutWeight(1)
          .onChange((value: string) => {
            this.inputText = value
          })
        Button('Add')
          .margin({ left: 8 })
          .onClick(() => {
            this.addTodo()
          })
      }
      .width('100%')

      List({ space: 4 }) {
        ForEach(this.todos, (item: TodoItem) => {
          ListItem() {
            Text(item.text)
              .width('100%')
              .padding(12)
              .onClick(() => {
                this.removeTodo(item.id)
              })
          }
        }, (item: TodoItem) => item.id.toString())
      }
      .layoutWeight(1)
      .width('100%')
      .margin({ top: 12 })
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.cache = new Map<K, V>();
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    }
    this.cache.set(key, value);
    if (this.cache.size > this.capacity) {
      for (const lruKey of this.cache.keys()) {
        this.cache.delete(lruKey);
        break;
      }
    }
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }
    const value = this.cache.get(key) as V;
    this.cache.delete(key);
    this.cache.set(key, value);
    return value;
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    for (const key of this.cache.keys()) {
      result.push(key);
    }
    return result;
  }

  get size(): number {
    return this.cache.size;
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type FieldValue = string | number | boolean;
type FieldListener = (value: FieldValue, previous: FieldValue) => void;

interface ListenerEntry {
  field: string;
  listener: FieldListener;
}

export class EditorStore {
  private text: string;
  private cursor: number;
  private bold: boolean;
  private readonly historyLimit: number;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private listeners: ListenerEntry[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    // Copy the initial values so later mutations of the caller's object
    // have no effect on the store.
    this.text = initial.text;
    this.cursor = initial.cursor;
    this.bold = initial.bold;
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    return { text: this.text, cursor: this.cursor, bold: this.bold };
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const previous: EditorState = this.snapshot();
    const next: EditorState = this.snapshot();
    if (patch.text !== undefined) {
      next.text = patch.text;
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold;
    }
    return this.commit(next, previous);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const previous: EditorState = this.snapshot();
    const draft: EditorState = this.snapshot();
    // If run throws, no commit happens and the store stays unchanged.
    run(draft);
    return this.commit(draft, previous);
  }

  undo(): boolean {
    const restored: EditorState | undefined = this.undoStack.pop();
    if (restored === undefined) {
      return false;
    }
    const previous: EditorState = this.snapshot();
    this.redoStack.push(previous);
    this.text = restored.text;
    this.cursor = restored.cursor;
    this.bold = restored.bold;
    this.notify(previous, restored);
    return true;
  }

  redo(): boolean {
    const again: EditorState | undefined = this.redoStack.pop();
    if (again === undefined) {
      return false;
    }
    const previous: EditorState = this.snapshot();
    this.undoStack.push(previous);
    this.trimUndoStack();
    this.text = again.text;
    this.cursor = again.cursor;
    this.bold = again.bold;
    this.notify(previous, again);
    return true;
  }

  watch(field: string, listener: FieldListener): () => void {
    const entry: ListenerEntry = { field: field, listener: listener };
    this.listeners.push(entry);
    let removed: boolean = false;
    return (): void => {
      if (removed) {
        return;
      }
      removed = true;
      const index: number = this.listeners.indexOf(entry);
      if (index >= 0) {
        this.listeners.splice(index, 1);
      }
    };
  }

  private snapshot(): EditorState {
    return { text: this.text, cursor: this.cursor, bold: this.bold };
  }

  private commit(next: EditorState, previous: EditorState): boolean {
    const changed: boolean = next.text !== previous.text
      || next.cursor !== previous.cursor
      || next.bold !== previous.bold;
    if (!changed) {
      return false;
    }
    this.undoStack.push(previous);
    this.trimUndoStack();
    this.redoStack = [];
    this.text = next.text;
    this.cursor = next.cursor;
    this.bold = next.bold;
    this.notify(previous, next);
    return true;
  }

  private trimUndoStack(): void {
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
  }

  private notify(previous: EditorState, next: EditorState): void {
    // Iterate over a copy so that (un)registering listeners inside a
    // listener cannot disturb the ordering of this notification round.
    const snapshot: ListenerEntry[] = this.listeners.slice();
    for (let i = 0; i < snapshot.length; i++) {
      const entry: ListenerEntry = snapshot[i];
      if (entry.field === 'text') {
        if (next.text !== previous.text) {
          entry.listener(next.text, previous.text);
        }
      } else if (entry.field === 'cursor') {
        if (next.cursor !== previous.cursor) {
          entry.listener(next.cursor, previous.cursor);
        }
      } else if (entry.field === 'bold') {
        if (next.bold !== previous.bold) {
          entry.listener(next.bold, previous.bold);
        }
      }
    }
  }
}

// solution.ets
// HarmonyOS NEXT (stage model, API 12+), ArkTS / ArkUI.
// A page showing 3000 lazily-built log entries in a pull-to-refresh list.

const LOG_LEVEL_ERROR: string = 'error';
const LOG_LEVEL_WARNING: string = 'warning';
const LOG_LEVEL_INFO: string = 'info';

const COLOR_ERROR: string = '#D32F2F';
const COLOR_WARNING: string = '#F57C00';
const COLOR_INFO: string = '#757575';

const INITIAL_COUNT: number = 3000;
const LOAD_BATCH_SIZE: number = 5;
const REFRESH_DELAY_MS: number = 1000;

class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number, message: string, level: string) {
    this.id = id;
    this.message = message;
    this.level = level;
  }
}

function levelForId(id: number): string {
  if (id % 50 === 0) {
    return LOG_LEVEL_ERROR;
  }
  if (id % 10 === 0) {
    return LOG_LEVEL_WARNING;
  }
  return LOG_LEVEL_INFO;
}

function makeEntry(id: number): LogEntry {
  return new LogEntry(id, `Event ${id}`, levelForId(id));
}

/**
 * Data source for LazyForEach. The entries are stored highest id first,
 * and rows are created only as they scroll into view.
 */
class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  constructor() {
    // Ids 1..3000, highest id first.
    for (let id = INITIAL_COUNT; id >= 1; id--) {
      this.entries.push(makeEntry(id));
    }
  }

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  // Prepend new entries (highest id first) at the top of the list.
  addEntriesAtTop(newEntries: LogEntry[]): void {
    this.entries = newEntries.concat(this.entries);
    for (let i = 0; i < newEntries.length; i++) {
      this.listeners.forEach((listener: DataChangeListener) => {
        listener.onDataAdd(i);
      });
    }
  }
}

/**
 * One row of the list: the entry's message and its level side by side.
 */
@Component
struct LogRow {
  @Prop entry: LogEntry;

  private levelColor(): string {
    if (this.entry.level === LOG_LEVEL_ERROR) {
      return COLOR_ERROR;
    }
    if (this.entry.level === LOG_LEVEL_WARNING) {
      return COLOR_WARNING;
    }
    return COLOR_INFO;
  }

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .layoutWeight(1)
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis })

      Text(this.entry.level)
        .fontSize(14)
        .fontWeight(FontWeight.Medium)
        .fontColor(this.levelColor())
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
  }
}

@Entry
@Component
struct Index {
  @State entryCount: number = INITIAL_COUNT;
  @State refreshing: boolean = false;
  private dataSource: LogDataSource = new LogDataSource();
  private nextId: number = INITIAL_COUNT + 1;

  private loadMoreEntries(): void {
    const newEntries: LogEntry[] = [];
    for (let i = 0; i < LOAD_BATCH_SIZE; i++) {
      const id: number = this.nextId + i;
      newEntries.push(makeEntry(id));
    }
    this.nextId += LOAD_BATCH_SIZE;

    this.dataSource.addEntriesAtTop(newEntries);
    this.entryCount = this.dataSource.totalCount();
  }

  private handleRefresh(): void {
    setTimeout(() => {
      this.loadMoreEntries();
      this.refreshing = false;
    }, REFRESH_DELAY_MS);
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .padding(16)
        .width('100%')

      Refresh({ refreshing: $$this.refreshing }) {
        List({ space: 0 }) {
          LazyForEach(this.dataSource, (item: LogEntry) => {
            ListItem() {
              LogRow({ entry: item })
            }
          }, (item: LogEntry) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .edgeEffect(EdgeEffect.None)
        .divider({
          strokeWidth: 1,
          color: '#EEEEEE',
          startMargin: 16,
          endMargin: 16
        })
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        this.handleRefresh();
      })
    }
    .width('100%')
    .height('100%')
  }
}

