export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
    this.name = 'MissingDependencyError';
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super('Dependency cycle: ' + path.join(' -> '));
    this.path = path;
    this.name = 'CycleError';
  }
}

export class BuildPlan {
  private names: string[] = [];
  private deps: Record<string, string[]> = {};
  private ordered: string[] = [];
  private placed: Set<string> = new Set();
  private chain: string[] = [];
  private onChain: Set<string> = new Set();

  constructor(spec: Record<string, string[]>) {
    this.names = Object.keys(spec);
    for (const t of this.names) {
      this.deps[t] = spec[t];
    }

    // First pass: every dependency must be a known task.
    const known: Set<string> = new Set(this.names);
    for (const t of this.names) {
      const list: string[] = this.deps[t];
      for (const d of list) {
        if (!known.has(d)) {
          throw new MissingDependencyError(t, d);
        }
      }
    }

    // Second pass: place tasks (depth-first, in key/list order), detecting cycles.
    for (const t of this.names) {
      this.visit(t);
    }
  }

  private visit(task: string): void {
    if (this.onChain.has(task)) {
      const idx: number = this.chain.indexOf(task);
      const p: string[] = this.chain.slice(idx);
      p.push(task);
      throw new CycleError(p);
    }
    if (this.placed.has(task)) {
      return;
    }
    this.onChain.add(task);
    this.chain.push(task);
    const list: string[] = this.deps[task];
    for (const d of list) {
      this.visit(d);
    }
    this.chain.pop();
    this.onChain.delete(task);
    this.placed.add(task);
    this.ordered.push(task);
  }

  order(): string[] {
    return this.ordered.slice();
  }

  layers(): string[][] {
    const layerOf: Record<string, number> = {};
    const result: string[][] = [];
    for (const t of this.ordered) {
      let layer: number = 0;
      const list: string[] = this.deps[t];
      for (const d of list) {
        const l: number = layerOf[d] + 1;
        if (l > layer) {
          layer = l;
        }
      }
      layerOf[t] = layer;
      while (result.length <= layer) {
        result.push([]);
      }
      result[layer].push(t);
    }
    return result;
  }

  dependentsOf(name: string): string[] {
    const dependsOn: Record<string, boolean> = {};
    const res: string[] = [];
    for (const t of this.ordered) {
      let dep: boolean = false;
      const list: string[] = this.deps[t];
      for (const d of list) {
        if (d === name || dependsOn[d]) {
          dep = true;
        }
      }
      dependsOn[t] = dep;
      if (dep) {
        res.push(t);
      }
    }
    return res;
  }
}

