class JsonEntry {
  key: string;
  value: JsonNode;

  constructor(key: string, value: JsonNode) {
    this.key = key;
    this.value = value;
  }
}

class JsonNode {
  kind: string;
  str: string;
  num: number;
  bool: boolean;
  entries: JsonEntry[];
  items: JsonNode[];

  constructor(kind: string) {
    this.kind = kind;
    this.str = '';
    this.num = 0;
    this.bool = false;
    this.entries = [];
    this.items = [];
  }
}

class JsonParser {
  private text: string;
  private pos: number = 0;

  constructor(text: string) {
    this.text = text;
  }

  parse(): JsonNode | undefined {
    this.skipWhitespace();
    const node = this.parseValue();
    if (node === undefined) {
      return undefined;
    }
    this.skipWhitespace();
    if (this.pos < this.text.length) {
      return undefined;
    }
    return node;
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const c = this.text.charAt(this.pos);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.pos++;
      } else {
        break;
      }
    }
  }

  private isDigit(c: string): boolean {
    return c >= '0' && c <= '9';
  }

  private parseValue(): JsonNode | undefined {
    if (this.pos >= this.text.length) {
      return undefined;
    }
    const c = this.text.charAt(this.pos);
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      const s = this.parseString();
      if (s === undefined) {
        return undefined;
      }
      const node = new JsonNode('string');
      node.str = s;
      return node;
    }
    if (c === 't') {
      return this.parseLiteral('true', 'boolean', true);
    }
    if (c === 'f') {
      return this.parseLiteral('false', 'boolean', false);
    }
    if (c === 'n') {
      return this.parseLiteral('null', 'null', false);
    }
    if (c === '-' || this.isDigit(c)) {
      return this.parseNumber();
    }
    return undefined;
  }

  private parseLiteral(word: string, kind: string, value: boolean): JsonNode | undefined {
    if (this.text.startsWith(word, this.pos)) {
      this.pos += word.length;
      const node = new JsonNode(kind);
      node.bool = value;
      return node;
    }
    return undefined;
  }

  private parseNumber(): JsonNode | undefined {
    const start = this.pos;
    if (this.text.charAt(this.pos) === '-') {
      this.pos++;
    }
    const c = this.text.charAt(this.pos);
    if (c === '0') {
      this.pos++;
    } else if (c >= '1' && c <= '9') {
      while (this.pos < this.text.length && this.isDigit(this.text.charAt(this.pos))) {
        this.pos++;
      }
    } else {
      return undefined;
    }
    if (this.text.charAt(this.pos) === '.') {
      this.pos++;
      if (!this.isDigit(this.text.charAt(this.pos))) {
        return undefined;
      }
      while (this.pos < this.text.length && this.isDigit(this.text.charAt(this.pos))) {
        this.pos++;
      }
    }
    const e = this.text.charAt(this.pos);
    if (e === 'e' || e === 'E') {
      this.pos++;
      const s = this.text.charAt(this.pos);
      if (s === '+' || s === '-') {
        this.pos++;
      }
      if (!this.isDigit(this.text.charAt(this.pos))) {
        return undefined;
      }
      while (this.pos < this.text.length && this.isDigit(this.text.charAt(this.pos))) {
        this.pos++;
      }
    }
    const node = new JsonNode('number');
    node.num = parseFloat(this.text.substring(start, this.pos));
    return node;
  }

  private parseString(): string | undefined {
    this.pos++;
    let out = '';
    while (this.pos < this.text.length) {
      const c = this.text.charAt(this.pos);
      if (c === '"') {
        this.pos++;
        return out;
      }
      if (c === '\\') {
        this.pos++;
        if (this.pos >= this.text.length) {
          return undefined;
        }
        const esc = this.text.charAt(this.pos);
        if (esc === '"') {
          out += '"';
        } else if (esc === '\\') {
          out += '\\';
        } else if (esc === '/') {
          out += '/';
        } else if (esc === 'b') {
          out += '\b';
        } else if (esc === 'f') {
          out += '\f';
        } else if (esc === 'n') {
          out += '\n';
        } else if (esc === 'r') {
          out += '\r';
        } else if (esc === 't') {
          out += '\t';
        } else if (esc === 'u') {
          if (this.pos + 4 >= this.text.length) {
            return undefined;
          }
          let code = 0;
          for (let k = 1; k <= 4; k++) {
            const h = this.text.charAt(this.pos + k);
            let d = -1;
            if (h >= '0' && h <= '9') {
              d = h.charCodeAt(0) - 48;
            } else if (h >= 'a' && h <= 'f') {
              d = h.charCodeAt(0) - 87;
            } else if (h >= 'A' && h <= 'F') {
              d = h.charCodeAt(0) - 55;
            }
            if (d < 0) {
              return undefined;
            }
            code = code * 16 + d;
          }
          out += String.fromCharCode(code);
          this.pos += 4;
        } else {
          return undefined;
        }
        this.pos++;
      } else {
        const code = this.text.charCodeAt(this.pos);
        if (code < 0x20) {
          return undefined;
        }
        out += c;
        this.pos++;
      }
    }
    return undefined;
  }

  private parseArray(): JsonNode | undefined {
    this.pos++;
    const node = new JsonNode('array');
    this.skipWhitespace();
    if (this.text.charAt(this.pos) === ']') {
      this.pos++;
      return node;
    }
    while (true) {
      this.skipWhitespace();
      const value = this.parseValue();
      if (value === undefined) {
        return undefined;
      }
      node.items.push(value);
      this.skipWhitespace();
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
        continue;
      } else if (c === ']') {
        this.pos++;
        return node;
      } else {
        return undefined;
      }
    }
  }

  private parseObject(): JsonNode | undefined {
    this.pos++;
    const node = new JsonNode('object');
    this.skipWhitespace();
    if (this.text.charAt(this.pos) === '}') {
      this.pos++;
      return node;
    }
    while (true) {
      this.skipWhitespace();
      if (this.text.charAt(this.pos) !== '"') {
        return undefined;
      }
      const key = this.parseString();
      if (key === undefined) {
        return undefined;
      }
      this.skipWhitespace();
      if (this.text.charAt(this.pos) !== ':') {
        return undefined;
      }
      this.pos++;
      this.skipWhitespace();
      const value = this.parseValue();
      if (value === undefined) {
        return undefined;
      }
      node.entries.push(new JsonEntry(key, value));
      this.skipWhitespace();
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
        continue;
      } else if (c === '}') {
        this.pos++;
        return node;
      } else {
        return undefined;
      }
    }
  }
}

function parseJson(text: string): JsonNode | undefined {
  return new JsonParser(text).parse();
}

function lookupField(entries: JsonEntry[], key: string): JsonNode | undefined {
  for (const entry of entries) {
    if (entry.key === key) {
      if (entry.value.kind === 'null') {
        return undefined;
      }
      return entry.value;
    }
  }
  return undefined;
}

function fieldError(path: string, message: string): FieldError {
  const e: FieldError = {
    path: path,
    message: message
  };
  return e;
}

function makeResult(order: Order | undefined, errors: FieldError[]): ParseResult {
  const result: ParseResult = {
    order: order,
    errors: errors
  };
  return result;
}

export function parseOrder(text: string): ParseResult {
  const root = parseJson(text);
  const errors: FieldError[] = [];

  if (root === undefined) {
    errors.push(fieldError('', 'invalid JSON'));
    return makeResult(undefined, errors);
  }
  if (root.kind !== 'object') {
    errors.push(fieldError('', 'expected an object'));
    return makeResult(undefined, errors);
  }

  const entries = root.entries;

  let id = '';
  let status = OrderStatus.Draft;
  const parsedLines: OrderLine[] = [];

  // id
  const idNode = lookupField(entries, 'id');
  if (idNode === undefined) {
    errors.push(fieldError('id', 'required'));
  } else if (idNode.kind !== 'string') {
    errors.push(fieldError('id', 'expected a string'));
  } else if (idNode.str === '') {
    errors.push(fieldError('id', 'must not be empty'));
  } else {
    id = idNode.str;
  }

  // status
  const statusNode = lookupField(entries, 'status');
  if (statusNode !== undefined) {
    if (statusNode.kind === 'string' && statusNode.str === 'draft') {
      status = OrderStatus.Draft;
    } else if (statusNode.kind === 'string' && statusNode.str === 'paid') {
      status = OrderStatus.Paid;
    } else if (statusNode.kind === 'string' && statusNode.str === 'shipped') {
      status = OrderStatus.Shipped;
    } else {
      errors.push(fieldError('status', 'expected one of draft, paid, shipped'));
    }
  }

  // lines
  const linesNode = lookupField(entries, 'lines');
  if (linesNode === undefined) {
    errors.push(fieldError('lines', 'required'));
  } else if (linesNode.kind !== 'array') {
    errors.push(fieldError('lines', 'expected an array'));
  } else if (linesNode.items.length === 0) {
    errors.push(fieldError('lines', 'must not be empty'));
  } else {
    for (let i = 0; i < linesNode.items.length; i++) {
      const item = linesNode.items[i];
      const linePath = `lines[${i}]`;
      if (item.kind !== 'object') {
        errors.push(fieldError(linePath, 'expected an object'));
        continue;
      }
      let lineOk = true;

      // sku
      const skuNode = lookupField(item.entries, 'sku');
      let sku = '';
      if (skuNode === undefined) {
        errors.push(fieldError(`${linePath}.sku`, 'required'));
        lineOk = false;
      } else if (skuNode.kind !== 'string') {
        errors.push(fieldError(`${linePath}.sku`, 'expected a string'));
        lineOk = false;
      } else if (skuNode.str === '') {
        errors.push(fieldError(`${linePath}.sku`, 'must not be empty'));
        lineOk = false;
      } else {
        sku = skuNode.str;
      }

      // quantity
      const qNode = lookupField(item.entries, 'quantity');
      let quantity = 0;
      if (qNode === undefined) {
        errors.push(fieldError(`${linePath}.quantity`, 'required'));
        lineOk = false;
      } else if (qNode.kind !== 'number') {
        errors.push(fieldError(`${linePath}.quantity`, 'expected a number'));
        lineOk = false;
      } else if (qNode.num < 1 || Math.floor(qNode.num) !== qNode.num) {
        errors.push(fieldError(`${linePath}.quantity`, 'must be a whole number of 1 or more'));
        lineOk = false;
      } else {
        quantity = qNode.num;
      }

      // unitPrice
      const pNode = lookupField(item.entries, 'unitPrice');
      let unitPrice = 0;
      if (pNode === undefined) {
        errors.push(fieldError(`${linePath}.unitPrice`, 'required'));
        lineOk = false;
      } else if (pNode.kind !== 'number') {
        errors.push(fieldError(`${linePath}.unitPrice`, 'expected a number'));
        lineOk = false;
      } else if (pNode.num < 0) {
        errors.push(fieldError(`${linePath}.unitPrice`, 'must be 0 or more'));
        lineOk = false;
      } else {
        unitPrice = pNode.num;
      }

      // unknown fields of the line, in text order
      for (const entry of item.entries) {
        if (entry.key !== 'sku' && entry.key !== 'quantity' && entry.key !== 'unitPrice') {
          errors.push(fieldError(`${linePath}.${entry.key}`, 'unknown field'));
          lineOk = false;
        }
      }

      if (lineOk) {
        parsedLines.push(new OrderLine(sku, quantity, unitPrice));
      }
    }
  }

  // unknown fields of the order, in text order
  for (const entry of entries) {
    if (entry.key !== 'id' && entry.key !== 'status' && entry.key !== 'lines') {
      errors.push(fieldError(entry.key, 'unknown field'));
    }
  }

  if (errors.length > 0) {
    return makeResult(undefined, errors);
  }

  const order: Order = {
    id: id,
    status: status,
    lines: parsedLines
  };
  return makeResult(order, []);
}

