export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
  return merged;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  return {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    if (capacity < 0) {
      throw new Error('capacity must be non-negative');
    }
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return this.items.slice();
  }
}

