export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      arr = new Array<Listener<T>>();
      this.listeners.set(event, arr);
    }
    if (arr.indexOf(listener) === -1) {
      arr.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    let arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      return;
    }
    let index: number = arr.indexOf(listener);
    if (index !== -1) {
      arr.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    let arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined || arr.length === 0) {
      return 0;
    }
    let snapshot: Array<Listener<T>> = arr.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    let arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      return 0;
    }
    return arr.length;
  }
}

export class RetryError extends Error {
  public attempts: number;
  public lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const total: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('unknown');

  for (let i = 0; i < total; i++) {
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(total, lastError);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const current: Item = items[i];
    if (current.id === id) {
      if (quantity > 0) {
        result.push({ id: current.id, name: current.name, quantity: quantity });
      }
      // quantity <= 0: item is left out
    } else {
      result.push(current);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isLetter(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNameChar(c: string): boolean {
  return isLetter(c) || isDigit(c);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const length = source.length;
  while (i < length) {
    const c = source.charAt(i);
    if (c === ' ') {
      i++;
      continue;
    }
    if (isDigit(c)) {
      const start = i;
      while (i < length && isDigit(source.charAt(i))) {
        i++;
      }
      if (i < length && source.charAt(i) === '.' && i + 1 < length && isDigit(source.charAt(i + 1))) {
        i++;
        while (i < length && isDigit(source.charAt(i))) {
          i++;
        }
      }
      const token: Token = { kind: 'number', text: source.substring(start, i), position: start };
      tokens.push(token);
      continue;
    }
    if (isLetter(c)) {
      const start = i;
      while (i < length && isNameChar(source.charAt(i))) {
        i++;
      }
      const token: Token = { kind: 'name', text: source.substring(start, i), position: start };
      tokens.push(token);
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      const token: Token = { kind: 'operator', text: c, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      const token: Token = { kind: 'paren', text: c, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class ExprNode {
  kind: string;
  value: number = 0;
  name: string = '';
  op: string = '';
  position: number = 0;
  left: ExprNode | null = null;
  right: ExprNode | null = null;

  constructor(kind: string) {
    this.kind = kind;
  }
}

class Parser {
  private tokens: Token[];
  private index: number = 0;
  private sourceLength: number;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
  }

  private peek(): Token | null {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return null;
  }

  peekRemaining(): Token | null {
    return this.peek();
  }

  parseExpression(): ExprNode {
    let node = this.parseTerm();
    while (true) {
      const t = this.peek();
      if (t !== null && t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.index++;
        const right = this.parseTerm();
        const bin = new ExprNode('binary');
        bin.op = t.text;
        bin.position = t.position;
        bin.left = node;
        bin.right = right;
        node = bin;
      } else {
        break;
      }
    }
    return node;
  }

  private parseTerm(): ExprNode {
    let node = this.parseFactor();
    while (true) {
      const t = this.peek();
      if (t !== null && t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.index++;
        const right = this.parseFactor();
        const bin = new ExprNode('binary');
        bin.op = t.text;
        bin.position = t.position;
        bin.left = node;
        bin.right = right;
        node = bin;
      } else {
        break;
      }
    }
    return node;
  }

  private parseFactor(): ExprNode {
    const t = this.peek();
    if (t !== null && t.kind === 'operator' && t.text === '-') {
      this.index++;
      const child = this.parseFactor();
      const unary = new ExprNode('unary');
      unary.position = t.position;
      unary.left = child;
      return unary;
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ExprNode {
    const t = this.peek();
    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (t.kind === 'number') {
      this.index++;
      const node = new ExprNode('number');
      node.value = parseFloat(t.text);
      node.position = t.position;
      return node;
    }
    if (t.kind === 'name') {
      this.index++;
      const node = new ExprNode('name');
      node.name = t.text;
      node.position = t.position;
      return node;
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.index++;
      const inner = this.parseExpression();
      const close = this.peek();
      if (close === null) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (!(close.kind === 'paren' && close.text === ')')) {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.index++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function evalNode(node: ExprNode, variables: Record<string, number>): number {
  if (node.kind === 'number') {
    return node.value;
  }
  if (node.kind === 'name') {
    const value = variables[node.name];
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return value;
  }
  if (node.kind === 'unary') {
    const child = node.left as ExprNode;
    return -evalNode(child, variables);
  }
  const leftNode = node.left as ExprNode;
  const rightNode = node.right as ExprNode;
  const leftValue = evalNode(leftNode, variables);
  const rightValue = evalNode(rightNode, variables);
  if (node.op === '+') {
    return leftValue + rightValue;
  }
  if (node.op === '-') {
    return leftValue - rightValue;
  }
  if (node.op === '*') {
    return leftValue * rightValue;
  }
  if (node.op === '/') {
    if (rightValue === 0) {
      throw new ExpressionError('Division by zero', node.position);
    }
    return leftValue / rightValue;
  }
  if (node.op === '%') {
    if (rightValue === 0) {
      throw new ExpressionError('Division by zero', node.position);
    }
    return leftValue % rightValue;
  }
  return 0;
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const root = parser.parseExpression();
  const remaining = parser.peekRemaining();
  if (remaining !== null) {
    throw new ExpressionError(`Unexpected token '${remaining.text}'`, remaining.position);
  }
  return evalNode(root, variables);
}

// solution.ets
// Self-contained duration formatting/parsing helpers.

function pad2(value: number): string {
  if (value < 10) {
    return `0${value}`;
  }
  return `${value}`;
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const abs: number = negative ? -totalSeconds : totalSeconds;

  let body: string;
  if (abs < 60) {
    body = `${abs}s`;
  } else if (abs < 3600) {
    const minutes: number = Math.floor(abs / 60);
    const seconds: number = abs % 60;
    body = `${minutes}m ${pad2(seconds)}s`;
  } else {
    const hours: number = Math.floor(abs / 3600);
    const minutes: number = Math.floor((abs % 3600) / 60);
    const seconds: number = abs % 60;
    body = `${hours}h ${pad2(minutes)}m ${pad2(seconds)}s`;
  }

  return negative ? `-${body}` : body;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let negative: boolean = false;
  let body: string = text;
  if (text[0] === '-') {
    negative = true;
    body = text.substring(1);
  }

  // One or more parts, each one-or-more digits followed by h/m/s,
  // separated by exactly one single space, no leading/trailing space.
  const pattern: RegExp = /^(\d+[hms])( \d+[hms])*$/;
  if (!pattern.test(body)) {
    return NaN;
  }

  const parts: string[] = body.split(' ');
  let total: number = 0;
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    const value: number = parseInt(part.substring(0, part.length - 1));
    const unit: string = part[part.length - 1];
    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
  }

  return negative ? -total : total;
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1 || items.length === 0) {
    return result;
  }
  for (let i = 0; i < items.length; i += size) {
    const end = Math.min(i + size, items.length);
    const group: T[] = [];
    for (let j = i; j < end; j++) {
      group.push(items[j]);
    }
    result.push(group);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = {
      first: a[i],
      second: b[i]
    };
    result.push(pair);
  }
  return result;
}

class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | undefined = undefined;
  next: LruNode<K, V> | undefined = undefined;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  private head: LruNode<K, V>;
  private tail: LruNode<K, V>;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('capacity must be a whole number of 1 or more');
    }
    this.capacity = capacity;
    this.head = new LruNode<K, V>(undefined as K, undefined as V);
    this.tail = new LruNode<K, V>(undefined as K, undefined as V);
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }

  private detach(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | undefined = node.prev;
    const next: LruNode<K, V> | undefined = node.next;
    if (prev !== undefined) {
      prev.next = next;
    }
    if (next !== undefined) {
      next.prev = prev;
    }
    node.prev = undefined;
    node.next = undefined;
  }

  private attachToFront(node: LruNode<K, V>): void {
    const first: LruNode<K, V> | undefined = this.head.next;
    node.prev = this.head;
    node.next = first;
    this.head.next = node;
    if (first !== undefined) {
      first.prev = node;
    }
  }

  private moveToFront(node: LruNode<K, V>): void {
    this.detach(node);
    this.attachToFront(node);
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.map.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToFront(existing);
      return;
    }
    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.map.set(key, node);
    this.attachToFront(node);
    if (this.map.size > this.capacity) {
      const lru: LruNode<K, V> | undefined = this.tail.prev;
      if (lru !== undefined && lru !== this.head) {
        this.detach(lru);
        this.map.delete(lru.key);
      }
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.map.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToFront(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | undefined = this.tail.prev;
    while (current !== undefined && current !== this.head) {
      result.push(current.key);
      current = current.prev;
    }
    return result;
  }

  get size(): number {
    return this.map.size;
  }
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const hasRule: boolean[] = [false, false, false, false, false, false, false];
  for (let i = 0; i < rules.length; i++) {
    hasRule[rules[i].day] = true;
  }

  // Check the 6 days after `day`, then `day` itself last.
  for (let offset = 1; offset <= 6; offset++) {
    const candidate = (day + offset) % 7;
    if (hasRule[candidate]) {
      return candidate as Weekday;
    }
  }

  if (hasRule[day]) {
    return day;
  }

  return undefined;
}

