// Self-contained URL query string parser for HarmonyOS (ArkTS, stage model).

function isHexDigit(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function hexVal(c: string): number {
  const code = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 97 && code <= 102) {
    return code - 97 + 10;
  }
  return code - 65 + 10;
}

function replacePlusWithSpace(s: string): string {
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const c = s.charAt(i);
    if (c === '+') {
      out += ' ';
    } else {
      out += c;
    }
  }
  return out;
}

function isValidEscapes(s: string): boolean {
  for (let i = 0; i < s.length; i++) {
    if (s.charAt(i) === '%') {
      if (i + 3 > s.length || !isHexDigit(s.charAt(i + 1)) || !isHexDigit(s.charAt(i + 2))) {
        return false;
      }
    }
  }
  return true;
}

function utf8Decode(bytes: number[]): string {
  let out = '';
  let i = 0;
  const n = bytes.length;
  while (i < n) {
    const b = bytes[i];
    if (b < 0x80) {
      out += String.fromCharCode(b);
      i += 1;
      continue;
    }
    let len = 0;
    let cp = 0;
    if (b >= 0xC2 && b <= 0xDF) {
      len = 2;
      cp = b & 0x1F;
    } else if (b >= 0xE0 && b <= 0xEF) {
      len = 3;
      cp = b & 0x0F;
    } else if (b >= 0xF0 && b <= 0xF4) {
      len = 4;
      cp = b & 0x07;
    } else {
      out += String.fromCharCode(0xFFFD);
      i += 1;
      continue;
    }
    let valid = true;
    if (i + len > n) {
      valid = false;
    } else {
      for (let k = 1; k < len; k++) {
        const cb = bytes[i + k];
        if ((cb & 0xC0) !== 0x80) {
          valid = false;
          break;
        }
        cp = (cp << 6) | (cb & 0x3F);
      }
    }
    if (!valid) {
      out += String.fromCharCode(0xFFFD);
      i += 1;
      continue;
    }
    if (len === 3 && cp < 0x800) {
      // Overlong 3-byte sequence.
      out += String.fromCharCode(0xFFFD);
      i += 1;
      continue;
    }
    if (len === 4 && cp < 0x10000) {
      // Overlong 4-byte sequence.
      out += String.fromCharCode(0xFFFD);
      i += 1;
      continue;
    }
    if (len === 3 && cp >= 0xD800 && cp <= 0xDFFF) {
      // Encoded surrogate.
      out += String.fromCharCode(0xFFFD);
      i += 1;
      continue;
    }
    if (cp <= 0xFFFF) {
      out += String.fromCharCode(cp);
    } else {
      const offset = cp - 0x10000;
      const high = 0xD800 + (offset >> 10);
      const low = 0xDC00 + (offset & 0x3FF);
      out += String.fromCharCode(high, low);
    }
    i += len;
  }
  return out;
}

function decodeComponent(s: string): string {
  if (!isValidEscapes(s)) {
    // Malformed escape: keep the text as written, only replacing '+'.
    return replacePlusWithSpace(s);
  }
  let out = '';
  const buf: number[] = [];
  let i = 0;
  while (i < s.length) {
    const c = s.charAt(i);
    if (c === '%') {
      buf.push(hexVal(s.charAt(i + 1)) * 16 + hexVal(s.charAt(i + 2)));
      i += 3;
    } else if (c === '+') {
      if (buf.length > 0) {
        out += utf8Decode(buf);
        buf.length = 0;
      }
      out += ' ';
      i += 1;
    } else {
      if (buf.length > 0) {
        out += utf8Decode(buf);
        buf.length = 0;
      }
      out += c;
      i += 1;
    }
  }
  if (buf.length > 0) {
    out += utf8Decode(buf);
    buf.length = 0;
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();
  let q = query;
  // Ignore at most one leading '?'.
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  const parts = q.split('&');
  for (let idx = 0; idx < parts.length; idx++) {
    const part = parts[idx];
    // Skip empty parts (e.g. from 'a=1&&b=2' or a trailing '&').
    if (part.length === 0) {
      continue;
    }
    const eq = part.indexOf('=');
    let rawKey = '';
    let rawVal = '';
    if (eq < 0) {
      // No '=': key with empty value.
      rawKey = part;
    } else {
      // Split at the first '=' only.
      rawKey = part.substring(0, eq);
      rawVal = part.substring(eq + 1);
    }
    // A pair with an empty key is ignored.
    if (rawKey.length === 0) {
      continue;
    }
    const key = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const val = decodeComponent(rawVal);
    // Map.set on an existing key overwrites the value while keeping
    // the key's original insertion position.
    result.set(key, val);
  }
  return result;
}

