  @State email: string = ''
  @State password: string = ''

  private isValidEmail(email: string): boolean {
    const atCount: number = email.split('@').length - 1
    if (atCount !== 1) {
      return false
    }
    const atIndex: number = email.indexOf('@')
    const localPart: string = email.substring(0, atIndex)
    const domainPart: string = email.substring(atIndex + 1)
    if (localPart.length < 1 || domainPart.length < 1) {
      return false
    }
    const dotIndex: number = domainPart.indexOf('.')
    if (dotIndex < 1 || dotIndex === domainPart.length - 1) {
      return false
    }
    return true
  }

  private isValidPassword(password: string): boolean {
    return password.length >= 8
  }

  build() {
    Column({ space: 16 }) {
      TextInput({
        placeholder: 'Email',
        text: this.email
      })
        .type(InputType.Email)
        .onChange((value: string) => {
          this.email = value
