export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

function isWhitespaceChar(ch: string): boolean {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v';
}

export function collapseSpaces(text: string): string {
  let result: string = '';
  let pendingSpace: boolean = false;
  for (let i: number = 0; i < text.length; i++) {
    const ch: string = text.charAt(i);
    if (isWhitespaceChar(ch)) {
      pendingSpace = true;
    } else {
      if (pendingSpace) {
        result += ' ';
        pendingSpace = false;
      }
      result += ch;
    }
  }
  if (pendingSpace) {
    result += ' ';
  }
  return result;
}

export class Pipeline {
  private stepNames: string[] = [];
  private steps: Transform[] = [];

  add(name: string, step: Transform): Pipeline {
    this.stepNames.push(name);
    this.steps.push(step);
    return this;
  }

  run(text: string): string {
    let result: string = text;
    for (let i: number = 0; i < this.steps.length; i++) {
      result = this.steps[i](result);
    }
    return result;
  }

  names(): string[] {
    const copy: string[] = [];
    for (let i: number = 0; i < this.stepNames.length; i++) {
      copy.push(this.stepNames[i]);
    }
    return copy;
  }

  toFunction(): Transform {
    const pipeline: Pipeline = this;
    return (text: string): string => {
      return pipeline.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  const list: Transform[] = steps;
  return (text: string): string => {
    let result: string = text;
    for (let i: number = 0; i < list.length; i++) {
      result = list[i](result);
    }
    return result;
  };
}

