export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueEntry {
  public run: () => void = (): void => {};
  public cancel: () => void = (): void => {};
}

export class JobQueue {
  private readonly concurrency: number;
  private paused: boolean = false;
  private runningCount: number = 0;
  private entries: QueueEntry[] = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new Error('concurrency must be a whole number of at least 1');
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.entries.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>(
      (resolve: (value: T | PromiseLike<T>) => void, reject: (reason?: Object) => void) => {
        const entry: QueueEntry = new QueueEntry();
        entry.run = (): void => {
          this.runningCount++;
          job().then((value: T): void => {
            this.runningCount--;
            this.completedCount++;
            resolve(value);
            this.onSettled();
          }).catch((err: Error): void => {
            this.runningCount--;
            this.failedCount++;
            reject(err);
            this.onSettled();
          });
        };
        entry.cancel = (): void => {
          reject(new Error('Job was cancelled'));
        };
        this.entries.push(entry);
        // If there is capacity and we are not paused, this new entry (the only
        // possible one that can be started) is run synchronously, before add returns.
        this.startNext();
      });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.startNext();
  }

  clear(): number {
    const removed: QueueEntry[] = this.entries.splice(0);
    for (const entry of removed) {
      entry.cancel();
    }
    this.checkIdle();
    return removed.length;
  }

  whenIdle(): Promise<void> {
    return new Promise<void>((resolve: () => void) => {
      if (this.runningCount === 0 && this.entries.length === 0) {
        resolve();
      } else {
        this.idleResolvers.push(resolve);
      }
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: Array<Promise<JobOutcome<T>>> = [];
    for (const job of jobs) {
      const outcome: Promise<JobOutcome<T>> = this.add(job)
        .then((value: T): JobOutcome<T> => {
          const result: JobOutcome<T> = {
            ok: true,
            value: value,
            error: undefined
          };
          return result;
        })
        .catch((err: Error): JobOutcome<T> => {
          const result: JobOutcome<T> = {
            ok: false,
            value: undefined,
            error: err
          };
          return result;
        });
      outcomes.push(outcome);
    }
    return Promise.all(outcomes);
  }

  private startNext(): void {
    while (!this.paused && this.runningCount < this.concurrency && this.entries.length > 0) {
      const entry: QueueEntry | undefined = this.entries.shift();
      if (entry === undefined) {
        break;
      }
      entry.run();
    }
  }

  private onSettled(): void {
    this.startNext();
    this.checkIdle();
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.entries.length === 0 && this.idleResolvers.length > 0) {
      const resolvers: Array<() => void> = this.idleResolvers.splice(0);
      for (const resolve of resolvers) {
        resolve();
      }
    }
  }
}

