interface CircleShape {
  kind: 'circle';
  radius: number;
}

interface RectangleShape {
  kind: 'rectangle';
  width: number;
  height: number;
}

interface TriangleShape {
  kind: 'triangle';
  base: number;
  height: number;
}

export type Shape = CircleShape | RectangleShape | TriangleShape;

export function circle(radius: number): Shape {
  return { kind: 'circle', radius: radius };
}

export function rectangle(width: number, height: number): Shape {
  return { kind: 'rectangle', width: width, height: height };
}

export function triangle(base: number, height: number): Shape {
  return { kind: 'triangle', base: base, height: height };
}

export function area(shape: Shape): number {
  switch (shape.kind) {
    case 'circle':
      return Math.PI * shape.radius * shape.radius;
    case 'rectangle':
      return shape.width * shape.height;
    case 'triangle':
      return shape.base * shape.height / 2;
  }
}

export function totalArea(shapes: Shape[]): number {
  let total: number = 0;
  for (const shape of shapes) {
    total += area(shape);
  }
  return total;
}

import { http } from '@kit.NetworkKit'

interface Item {
  id: number
  name: string
}

enum LoadState {
  LOADING,
  SUCCESS,
  ERROR
}

@Entry
@Component
struct Index {
  @State state: LoadState = LoadState.LOADING
  @State items: Item[] = []

  aboutToAppear(): void {
    this.fetchItems()
  }

  private fetchItems(): void {
    this.state = LoadState.LOADING
    const httpRequest = http.createHttp()
    httpRequest.request(
      'https://example.com/api/items',
      {
        method: http.RequestMethod.GET,
        header: { 'Content-Type': 'application/json' }
      }
    ).then((resp: http.HttpResponse) => {
      if (resp.responseCode === 200) {
        try {
          const parsed: Item[] = JSON.parse(resp.result as string) as Item[]
          this.items = parsed
          this.state = LoadState.SUCCESS
        } catch (e) {
          this.state = LoadState.ERROR
        }
      } else {
        this.state = LoadState.ERROR
      }
    }).catch(() => {
      this.state = LoadState.ERROR
    }).finally(() => {
      httpRequest.destroy()
    })
  }

  build() {
    Column() {
      if (this.state === LoadState.LOADING) {
        Text('Loading...')
          .fontSize(20)
          .padding(16)
      } else if (this.state === LoadState.ERROR) {
        Text('Could not load the items')
          .fontSize(20)
          .padding(16)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(20)
                .padding(16)
                .width('100%')
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

