import { preferences } from '@kit.ArkData'

@Entry
@Component
struct Index {
  @State savedName: string = ''
  @State inputName: string = ''
  private preferencesInstance: preferences.Preferences | null = null

  aboutToAppear(): void {
    const context = getContext(this) as Context
    preferences.getPreferences(context, { name: 'myPrefs' })
      .then((prefs: preferences.Preferences) => {
        this.preferencesInstance = prefs
        const name = prefs.getSync('name', '') as string
        if (name !== '') {
          this.savedName = name
        }
      })
      .catch((err: BusinessError) => {
        console.error(`Failed to get preferences: ${err.code}, ${err.message}`)
      })
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName === '' ? 'No name saved' : `Hello, ${this.savedName}`)
        .fontSize(24)
        .margin({ top: 40 })

      TextInput({ placeholder: 'Enter your name', text: this.inputName })
        .onChange((value: string) => {
          this.inputName = value
        })
        .width('80%')

      Button('Save')
        .width('80%')
        .onClick(() => {
          const name = this.inputName.trim()
          if (name === '') {
            return
          }
          if (this.preferencesInstance !== null) {
            this.preferencesInstance.putSync('name', name)
            this.preferencesInstance.flush()
            this.savedName = name
          }
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .alignItems(HorizontalAlign.Center)
  }
}

