export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export interface EditorPatch {
  text?: string;
  cursor?: number;
  bold?: boolean;
}

type FieldValue = string | number | boolean;

interface Watcher {
  field: string;
  listener: (value: FieldValue, previous: FieldValue) => void;
  active: boolean;
}

export class EditorStore {
  private current: EditorState;
  private readonly limit: number;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private watchers: Watcher[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.current = EditorStore.copy(initial);
    let limit = Math.floor(historyLimit);
    if (limit < 1) {
      limit = 1;
    }
    this.limit = limit;
  }

  private static copy(state: EditorState): EditorState {
    return { text: state.text, cursor: state.cursor, bold: state.bold };
  }

  get state(): EditorState {
    return EditorStore.copy(this.current);
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: EditorPatch): boolean {
    const next = this.mergeValues(patch.text, patch.cursor, patch.bold);
    return this.commit(next);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = EditorStore.copy(this.current);
    run(draft);
    const next = this.mergeValues(draft.text, draft.cursor, draft.bold);
    return this.commit(next);
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const previous = this.current;
    this.redoStack.push(EditorStore.copy(previous));
    const index = this.undoStack.length - 1;
    const restored = this.undoStack[index];
    this.undoStack.splice(index, 1);
    this.current = restored;
    this.notify(previous, this.current);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const previous = this.current;
    this.undoStack.push(EditorStore.copy(previous));
    if (this.undoStack.length > this.limit) {
      this.undoStack.splice(0, 1);
    }
    const index = this.redoStack.length - 1;
    const restored = this.redoStack[index];
    this.redoStack.splice(index, 1);
    this.current = restored;
    this.notify(previous, this.current);
    return true;
  }

  watch(field: string, listener: (value: FieldValue, previous: FieldValue) => void): () => void {
    const watcher: Watcher = { field: field, listener: listener, active: true };
    this.watchers.push(watcher);
    return () => {
      watcher.active = false;
      const index = this.watchers.indexOf(watcher);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
  }

  private mergeValues(text: string | undefined, cursor: number | undefined, bold: boolean | undefined): EditorState {
    const next = EditorStore.copy(this.current);
    if (text !== undefined) {
      next.text = text;
    }
    if (cursor !== undefined) {
      next.cursor = cursor;
    }
    if (bold !== undefined) {
      next.bold = bold;
    }
    return next;
  }

  private commit(next: EditorState): boolean {
    const previous = this.current;
    if (next.text === previous.text && next.cursor === previous.cursor && next.bold === previous.bold) {
      return false;
    }
    this.undoStack.push(EditorStore.copy(previous));
    if (this.undoStack.length > this.limit) {
      this.undoStack.splice(0, 1);
    }
    this.redoStack = [];
    this.current = EditorStore.copy(next);
    this.notify(previous, this.current);
    return true;
  }

  private notify(previous: EditorState, current: EditorState): void {
    const snapshot: Watcher[] = [];
    for (let i = 0; i < this.watchers.length; i++) {
      snapshot.push(this.watchers[i]);
    }
    for (const watcher of snapshot) {
      if (!watcher.active) {
        continue;
      }
      let previousValue: FieldValue | undefined = undefined;
      let currentValue: FieldValue | undefined = undefined;
      if (watcher.field === 'text') {
        previousValue = previous.text;
        currentValue = current.text;
      } else if (watcher.field === 'cursor') {
        previousValue = previous.cursor;
        currentValue = current.cursor;
      } else if (watcher.field === 'bold') {
        previousValue = previous.bold;
        currentValue = current.bold;
      } else {
        continue;
      }
      if (previousValue !== currentValue) {
        watcher.listener(currentValue, previousValue);
      }
    }
  }
}

// solution.ets

class LogEntry {
  id: number
  message: string
  level: string

  constructor(id: number, message: string, level: string) {
    this.id = id
    this.message = message
    this.level = level
  }
}

function levelFor(id: number): string {
  if (id % 50 === 0) {
    return 'error'
  }
  if (id % 10 === 0) {
    return 'warning'
  }
  return 'info'
}

function makeEntry(id: number): LogEntry {
  return new LogEntry(id, `Event ${id}`, levelFor(id))
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = []
  private listeners: DataChangeListener[] = []

  constructor(initialCount: number) {
    for (let id = 1; id <= initialCount; id++) {
      this.entries.push(makeEntry(id))
    }
  }

  totalCount(): number {
    return this.entries.length
  }

  getData(index: number): LogEntry {
    return this.entries[index]
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener)
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos = this.listeners.indexOf(listener)
    if (pos >= 0) {
      this.listeners.splice(pos, 1)
    }
  }

  notifyAdd(index: number, count: number): void {
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataAdd(index)
    })
  }

  // Add new entries (given in descending order) at the top of the list.
  addAtTop(newEntries: LogEntry[]): void {
    const addedCount = newEntries.length
    // Insert at the front, preserving the caller's descending order.
    this.entries = newEntries.concat(this.entries)
    this.notifyAdd(0, addedCount)
  }
}

@Entry
@Component
struct LogListPage {
  @State refreshing: boolean = false
  @State entryCount: number = 0
  private dataSource: LogDataSource = new LogDataSource(3000)
  private highestId: number = 3000

  aboutToAppear(): void {
    this.entryCount = this.dataSource.totalCount()
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 12, bottom: 8 })
        .width('100%')
        .textAlign(TextAlign.Center)

      Refresh({ refreshing: $$this.refreshing }) {
        List({ space: 0 }) {
          LazyForEach(this.dataSource, (entry: LogEntry) => {
            LogRow({ entry: entry })
          }, (entry: LogEntry) => `log-${entry.id}`)
        }
        .width('100%')
        .height('100%')
        .edgeEffect(EdgeEffect.None)
        .cachedCount(5)
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        // One second later, add five new entries at the top.
        setTimeout(() => {
          const newEntries: LogEntry[] = []
          for (let i = 0; i < 5; i++) {
            this.highestId += 1
            newEntries.push(makeEntry(this.highestId))
          }
          this.dataSource.addAtTop(newEntries)
          this.entryCount = this.dataSource.totalCount()
          this.refreshing = false
        }, 1000)
      })
    }
    .width('100%')
    .height('100%')
  }
}

