export class MissingDependencyError extends Error {
  readonly task: string;
  readonly dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
    this.name = 'MissingDependencyError';
  }
}

export class CycleError extends Error {
  readonly path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
    this.name = 'CycleError';
  }
}

export class BuildPlan {
  private readonly spec: Record<string, string[]>;
  private readonly keyOrder: string[];
  private readonly keySet: Set<string>;
  private readonly orderList: string[];
  private readonly depSets: Map<string, Set<string>> = new Map<string, Set<string>>();

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.keyOrder = Object.keys(spec);
    this.keySet = new Set<string>(this.keyOrder);

    // First pass: every dependency must be a known task.
    for (const task of this.keyOrder) {
      const deps: string[] = spec[task];
      for (const dep of deps) {
        if (!this.keySet.has(dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Second pass: place the tasks in execution order, detecting cycles.
    const placed: Set<string> = new Set<string>();
    const chain: string[] = [];
    this.orderList = [];
    for (const task of this.keyOrder) {
      this.place(task, placed, chain);
    }

    // Precompute transitive dependency sets for dependentsOf.
    for (const task of this.keyOrder) {
      this.collectDeps(task);
    }
  }

  order(): string[] {
    return this.orderList.slice();
  }

  layers(): string[][] {
    const layerOf: Map<string, number> = new Map<string, number>();
    const result: string[][] = [];

    // Compute layers following the placement order (dependencies first).
    for (const task of this.orderList) {
      let layer: number = 0;
      const deps: string[] = this.spec[task];
      for (const dep of deps) {
        const depLayer: number = layerOf.get(dep) as number;
        if (depLayer + 1 > layer) {
          layer = depLayer + 1;
        }
      }
      layerOf.set(task, layer);
    }

    // Fill layers in key order.
    for (const task of this.keyOrder) {
      const layer: number = layerOf.get(task) as number;
      while (result.length <= layer) {
        result.push([]);
      }
      result[layer].push(task);
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    const result: string[] = [];
    if (!this.keySet.has(name)) {
      return result;
    }
    for (const task of this.orderList) {
      if (task !== name) {
        const deps: Set<string> | undefined = this.depSets.get(task);
        if (deps !== undefined && deps.has(name)) {
          result.push(task);
        }
      }
    }
    return result;
  }

  private place(task: string, placed: Set<string>, chain: string[]): void {
    if (placed.has(task)) {
      return;
    }
    const idx: number = chain.indexOf(task);
    if (idx >= 0) {
      const path: string[] = chain.slice(idx);
      path.push(task);
      throw new CycleError(path);
    }
    chain.push(task);
    const deps: string[] = this.spec[task];
    for (const dep of deps) {
      this.place(dep, placed, chain);
    }
    chain.pop();
    placed.add(task);
    this.orderList.push(task);
  }

  private collectDeps(task: string): Set<string> {
    const cached: Set<string> | undefined = this.depSets.get(task);
    if (cached !== undefined) {
      return cached;
    }
    const result: Set<string> = new Set<string>();
    this.depSets.set(task, result);
    const deps: string[] = this.spec[task];
    for (const dep of deps) {
      result.add(dep);
      const transitive: Set<string> = this.collectDeps(dep);
      transitive.forEach((item: string) => {
        result.add(item);
      });
    }
    return result;
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals = new Map<string, number>();
  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const current = totals.get(expense.category) ?? 0;
    totals.set(expense.category, current + expense.amount);
  }
  return totals;
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class WaitingJob {
  start: () => void;
  cancel: (reason: Error) => void;

  constructor(start: () => void, cancel: (reason: Error) => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

export class JobQueue {
  private readonly concurrency: number;
  private queue: Array<WaitingJob> = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve: (value: T) => void, reject: (reason: Error) => void) => {
      const entry = new WaitingJob((): void => {
        this.beginJob(job, resolve, reject);
      }, reject);
      this.queue.push(entry);
      if (!this.paused && this.runningCount < this.concurrency) {
        this.startNext();
      }
    });
  }

  private beginJob<T>(job: () => Promise<T>, resolve: (value: T) => void, reject: (reason: Error) => void): void {
    this.runningCount += 1;
    job().then((value: T): void => {
      this.runningCount -= 1;
      this.completedCount += 1;
      resolve(value);
      this.afterSettle();
    }, (reason: Error): void => {
      this.runningCount -= 1;
      this.failedCount += 1;
      reject(reason);
      this.afterSettle();
    });
  }

  private afterSettle(): void {
    this.startNext();
    if (this.runningCount === 0 && this.queue.length === 0) {
      this.resolveIdle();
    }
  }

  private startNext(): void {
    while (!this.paused && this.runningCount < this.concurrency && this.queue.length > 0) {
      const entry: WaitingJob | undefined = this.queue.shift();
      if (entry !== undefined) {
        entry.start();
      }
    }
  }

  private resolveIdle(): void {
    const waiters = this.idleWaiters;
    this.idleWaiters = [];
    for (let i = 0; i < waiters.length; i++) {
      waiters[i]();
    }
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.queue.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.startNext();
  }

  clear(): number {
    const removed = this.queue.length;
    while (this.queue.length > 0) {
      const entry: WaitingJob | undefined = this.queue.shift();
      if (entry !== undefined) {
        entry.cancel(new Error('Job was cancelled'));
      }
    }
    if (this.runningCount === 0) {
      this.resolveIdle();
    }
    return removed;
  }

  whenIdle(): Promise<void> {
    return new Promise<void>((resolve: () => void) => {
      if (this.runningCount === 0 && this.queue.length === 0) {
        resolve();
      } else {
        this.idleWaiters.push(resolve);
      }
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const results: Array<JobOutcome<T>> = [];
    const tracked: Array<Promise<void>> = [];
    for (let i = 0; i < jobs.length; i++) {
      const placeholder: JobOutcome<T> = { ok: false, value: undefined, error: undefined };
      results.push(placeholder);
      const job = jobs[i];
      const index = i;
      const trackedPromise: Promise<void> = this.add(job).then((value: T): void => {
        const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
        results[index] = outcome;
      }, (reason: Error): void => {
        const outcome: JobOutcome<T> = { ok: false, value: undefined, error: reason };
        results[index] = outcome;
      });
      tracked.push(trackedPromise);
    }
    return Promise.all(tracked).then((): Array<JobOutcome<T>> => {
      return results;
    });
  }
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStart(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNameChar(c: string): boolean {
  return isNameStart(c) || isDigit(c);
}

function makeToken(kind: string, text: string, position: number): Token {
  return { kind: kind, text: text, position: position };
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const len = source.length;
  let i = 0;
  while (i < len) {
    const c = source.charAt(i);
    if (c === ' ') {
      i++;
      continue;
    }
    if (isDigit(c)) {
      const start = i;
      while (i < len && isDigit(source.charAt(i))) {
        i++;
      }
      if (i < len && source.charAt(i) === '.' && i + 1 < len && isDigit(source.charAt(i + 1))) {
        i++;
        while (i < len && isDigit(source.charAt(i))) {
          i++;
        }
      }
      tokens.push(makeToken('number', source.substring(start, i), start));
      continue;
    }
    if (isNameStart(c)) {
      const start = i;
      while (i < len && isNameChar(source.charAt(i))) {
        i++;
      }
      tokens.push(makeToken('name', source.substring(start, i), start));
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      tokens.push(makeToken('operator', c, i));
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push(makeToken('paren', c, i));
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class ExprNode {
  kind: string;
  value: number;
  name: string;
  namePos: number;
  op: string;
  opPos: number;
  left: ExprNode | null;
  right: ExprNode | null;
  operand: ExprNode | null;

  constructor(kind: string) {
    this.kind = kind;
    this.value = 0;
    this.name = '';
    this.namePos = 0;
    this.op = '';
    this.opPos = 0;
    this.left = null;
    this.right = null;
    this.operand = null;
  }
}

function numNode(value: number): ExprNode {
  const node = new ExprNode('num');
  node.value = value;
  return node;
}

function nameNode(name: string, position: number): ExprNode {
  const node = new ExprNode('name');
  node.name = name;
  node.namePos = position;
  return node;
}

function negNode(operand: ExprNode): ExprNode {
  const node = new ExprNode('neg');
  node.operand = operand;
  return node;
}

function binNode(op: string, opPos: number, left: ExprNode, right: ExprNode): ExprNode {
  const node = new ExprNode('bin');
  node.op = op;
  node.opPos = opPos;
  node.left = left;
  node.right = right;
  return node;
}

class Parser {
  private tokens: Token[];
  private index: number;
  private end: number;

  constructor(tokens: Token[], end: number) {
    this.tokens = tokens;
    this.index = 0;
    this.end = end;
  }

  parse(): ExprNode {
    const result = this.parseExpression();
    if (this.index < this.tokens.length) {
      const t = this.tokens[this.index];
      throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
    }
    return result;
  }

  private peek(): Token | null {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return null;
  }

  private parseExpression(): ExprNode {
    let node = this.parseTerm();
    let t = this.peek();
    while (t !== null && t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
      this.index++;
      const right = this.parseTerm();
      node = binNode(t.text, t.position, node, right);
      t = this.peek();
    }
    return node;
  }

  private parseTerm(): ExprNode {
    let node = this.parseFactor();
    let t = this.peek();
    while (t !== null && t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
      this.index++;
      const right = this.parseFactor();
      node = binNode(t.text, t.position, node, right);
      t = this.peek();
    }
    return node;
  }

  private parseFactor(): ExprNode {
    const t = this.peek();
    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.end);
    }
    if (t.kind === 'operator' && t.text === '-') {
      this.index++;
      const operand = this.parseFactor();
      return negNode(operand);
    }
    if (t.kind === 'number') {
      this.index++;
      return numNode(parseFloat(t.text));
    }
    if (t.kind === 'name') {
      this.index++;
      return nameNode(t.text, t.position);
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.index++;
      const inner = this.parseExpression();
      const close = this.peek();
      if (close === null) {
        throw new ExpressionError('Unexpected end of expression', this.end);
      }
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.index++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function evalNode(node: ExprNode, variables: Record<string, number>): number {
  if (node.kind === 'num') {
    return node.value;
  }
  if (node.kind === 'name') {
    const value = variables[node.name];
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.namePos);
    }
    return value;
  }
  if (node.kind === 'neg') {
    const operand = node.operand;
    if (operand === null) {
      return 0;
    }
    return -evalNode(operand, variables);
  }
  const left = node.left;
  const right = node.right;
  if (left === null || right === null) {
    return 0;
  }
  const a = evalNode(left, variables);
  const b = evalNode(right, variables);
  if (node.op === '+') {
    return a + b;
  }
  if (node.op === '-') {
    return a - b;
  }
  if (node.op === '*') {
    return a * b;
  }
  if (b === 0) {
    throw new ExpressionError('Division by zero', node.opPos);
  }
  if (node.op === '/') {
    return a / b;
  }
  return a % b;
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const ast = parser.parse();
  return evalNode(ast, variables);
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY
  };
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
  return merged;
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    if (capacity < 0) {
      throw new Error('capacity must be non-negative');
    }
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return this.items.slice();
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map<string, Array<Listener<T>>>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.listeners.set(event, list);
    }
    if (!list.includes(listener)) {
      list.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    let index: number = list.indexOf(listener);
    if (index >= 0) {
      list.splice(index, 1);
    }
    if (list.length === 0) {
      this.listeners.delete(event);
    }
  }

  emit(event: string, payload: T): number {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined || list.length === 0) {
      return 0;
    }
    // Snapshot so that listeners registered/removed during this emit
    // only affect later calls to emit.
    let snapshot: Array<Listener<T>> = list.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

