export function parseQuery(query: string): Map<string, string> {
  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  const map: Map<string, string> = new Map<string, string>();
  if (q.length === 0) {
    return map;
  }
  const parts: string[] = q.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (part.length === 0) {
      continue;
    }
    let key: string = part;
    let value: string = '';
    const eq: number = part.indexOf('=');
    if (eq >= 0) {
      key = part.substring(0, eq);
      value = part.substring(eq + 1);
    }
    if (key.length === 0) {
      continue;
    }
    map.set(decodeComponent(key), decodeComponent(value));
  }
  return map;
}

function hexVal(c: string): number {
  const code: number = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 65 + 10;
  }
  if (code >= 97 && code <= 102) {
    return code - 97 + 10;
  }
  return -1;
}

function decodeComponent(s: string): string {
  let out: string = '';
  let bytes: number[] = [];
  let i = 0;
  const n = s.length;
  while (i < n) {
    const c: string = s.charAt(i);
    if (c === '+') {
      out += flushBytes(bytes);
      bytes = [];
      out += ' ';
      i++;
    } else if (c === '%' && i + 2 < n + 1 && i + 2 <= n - 1 + 1) {
      // need valid hex digits at i+1 and i+2; guard below keeps it safe
      const h: number = (i + 1 < n) ? hexVal(s.charAt(i + 1)) : -1;
      const l: number = (i + 2 < n) ? hexVal(s.charAt(i + 2)) : -1;
      if (h >= 0 && l >= 0) {
        bytes.push(h * 16 + l);
        i += 3;
      } else {
        out += flushBytes(bytes);
        bytes = [];
        out += '%';
        i++;
      }
    } else {
      out += flushBytes(bytes);
      bytes = [];
      out += c;
      i++;
    }
  }
  out += flushBytes(bytes);
  return out;
}

function flushBytes(bytes: number[]): string {
  if (bytes.length === 0) {
    return '';
  }
  const result: string = decodeUtf8(bytes);
  bytes.length = 0;
  return result;
}

function decodeUtf8(bytes: number[]): string {
  let out: string = '';
  let i = 0;
  const n = bytes.length;
  while (i < n) {
    const b: number = bytes[i];
    if (b < 0x80) {
      out += String.fromCharCode(b);
      i++;
      continue;
    }
    let len = 0;
    let cp = 0;
    if (b >= 0xC2 && b <= 0xDF) {
      len = 1;
      cp = b & 0x1F;
    } else if (b >= 0xE0 && b <= 0xEF) {
      len = 2;
      cp = b & 0x0F;
    } else if (b >= 0xF0 && b <= 0xF4) {
      len = 3;
      cp = b & 0x07;
    } else {
      out += '\u{FFFD}';
      i++;
      continue;
    }
    let valid = true;
    if (i + len >= n + 1) {
      valid = false;
    } else {
      for (let j = 1; j <= len; j++) {
        const cb: number = bytes[i + j];
        if ((cb & 0xC0) !== 0x80) {
          valid = false;
          break;
        }
        cp = (cp << 6) | (cb & 0x3F);
      }
    }
    if (!valid) {
      out += '\u{FFFD}';
      i++;
      continue;
    }
    if ((len === 2 && cp < 0x800) || (len === 3 && cp < 0x10000) ||
        cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
      out += '\u{FFFD}';
      i++;
      continue;
    }
    out += String.fromCharCode(cp);
    i += len + 1;
  }
  return out;
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

const KNOWN_ORDER_FIELDS: string[] = ['id', 'status', 'lines'];
const KNOWN_LINE_FIELDS: string[] = ['sku', 'quantity', 'unitPrice'];

function makeError(path: string, message: string): FieldError {
  const e: FieldError = { path: path, message: message };
  return e;
}

function hasKey(keys: string[], key: string): boolean {
  return keys.indexOf(key) >= 0;
}

function isJsonObject(value: Object | null): boolean {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function parseLine(linePath: string, rec: Record<string, Object | null>, errors: FieldError[]): OrderLine | undefined {
  const keys: string[] = Object.keys(rec);

  let sku: string = '';
  let quantity: number = 0;
  let unitPrice: number = 0;
  let skuOk: boolean = false;
  let quantityOk: boolean = false;
  let unitPriceOk: boolean = false;

  // sku
  const rawSku: Object | null = hasKey(keys, 'sku') ? rec['sku'] : null;
  if (rawSku === null) {
    errors.push(makeError(linePath + '.sku', 'required'));
  } else if (typeof rawSku !== 'string') {
    errors.push(makeError(linePath + '.sku', 'expected a string'));
  } else {
    const s: string = rawSku as string;
    if (s === '') {
      errors.push(makeError(linePath + '.sku', 'must not be empty'));
    } else {
      sku = s;
      skuOk = true;
    }
  }

  // quantity
  const rawQuantity: Object | null = hasKey(keys, 'quantity') ? rec['quantity'] : null;
  if (rawQuantity === null) {
    errors.push(makeError(linePath + '.quantity', 'required'));
  } else if (typeof rawQuantity !== 'number') {
    errors.push(makeError(linePath + '.quantity', 'expected a number'));
  } else {
    const q: number = rawQuantity as number;
    if (q % 1 !== 0 || q < 1) {
      errors.push(makeError(linePath + '.quantity', 'must be a whole number of 1 or more'));
    } else {
      quantity = q;
      quantityOk = true;
    }
  }

  // unitPrice
  const rawUnitPrice: Object | null = hasKey(keys, 'unitPrice') ? rec['unitPrice'] : null;
  if (rawUnitPrice === null) {
    errors.push(makeError(linePath + '.unitPrice', 'required'));
  } else if (typeof rawUnitPrice !== 'number') {
    errors.push(makeError(linePath + '.unitPrice', 'expected a number'));
  } else {
    const p: number = rawUnitPrice as number;
    if (p < 0) {
      errors.push(makeError(linePath + '.unitPrice', 'must be 0 or more'));
    } else {
      unitPrice = p;
      unitPriceOk = true;
    }
  }

  // unknown fields of this line, in text order
  for (let i: number = 0; i < keys.length; i++) {
    const key: string = keys[i];
    if (KNOWN_LINE_FIELDS.indexOf(key) < 0) {
      errors.push(makeError(linePath + '.' + key, 'unknown field'));
    }
  }

  if (skuOk && quantityOk && unitPriceOk) {
    return new OrderLine(sku, quantity, unitPrice);
  }
  return undefined;
}

export function parseOrder(text: string): ParseResult {
  let root: Object | null = null;
  try {
    root = JSON.parse(text);
  } catch (e) {
    const err: FieldError = makeError('', 'invalid JSON');
    return { order: undefined, errors: [err] };
  }

  if (!isJsonObject(root)) {
    const err: FieldError = makeError('', 'expected an object');
    return { order: undefined, errors: [err] };
  }

  const rec: Record<string, Object | null> = root as Record<string, Object | null>;
  const keys: string[] = Object.keys(rec);
  const errors: FieldError[] = [];

  // id
  let id: string = '';
  const rawId: Object | null = hasKey(keys, 'id') ? rec['id'] : null;
  if (rawId === null) {
    errors.push(makeError('id', 'required'));
  } else if (typeof rawId !== 'string') {
    errors.push(makeError('id', 'expected a string'));
  } else {
    const s: string = rawId as string;
    if (s === '') {
      errors.push(makeError('id', 'must not be empty'));
    } else {
      id = s;
    }
  }

  // status
  let status: OrderStatus = OrderStatus.Draft;
  const rawStatus: Object | null = hasKey(keys, 'status') ? rec['status'] : null;
  if (rawStatus !== null) {
    if (typeof rawStatus !== 'string') {
      errors.push(makeError('status', 'expected one of draft, paid, shipped'));
    } else {
      const s: string = rawStatus as string;
      if (s === OrderStatus.Draft) {
        status = OrderStatus.Draft;
      } else if (s === OrderStatus.Paid) {
        status = OrderStatus.Paid;
      } else if (s === OrderStatus.Shipped) {
        status = OrderStatus.Shipped;
      } else {
        errors.push(makeError('status', 'expected one of draft, paid, shipped'));
      }
    }
  }

  // lines
  const lines: OrderLine[] = [];
  const rawLines: Object | null = hasKey(keys, 'lines') ? rec['lines'] : null;
  if (rawLines === null) {
    errors.push(makeError('lines', 'required'));
  } else if (!Array.isArray(rawLines)) {
    errors.push(makeError('lines', 'expected an array'));
  } else {
    const arr: (Object | null)[] = rawLines as (Object | null)[];
    if (arr.length === 0) {
      errors.push(makeError('lines', 'must not be empty'));
    } else {
      for (let i: number = 0; i < arr.length; i++) {
        const linePath: string = 'lines[' + i.toString() + ']';
        const elem: Object | null = arr[i];
        if (!isJsonObject(elem)) {
          errors.push(makeError(linePath, 'expected an object'));
        } else {
          const lineRec: Record<string, Object | null> = elem as Record<string, Object | null>;
          const line: OrderLine | undefined = parseLine(linePath, lineRec, errors);
          if (line !== undefined) {
            lines.push(line);
          }
        }
      }
    }
  }

  // unknown fields of the order, in text order
  for (let i: number = 0; i < keys.length; i++) {
    const key: string = keys[i];
    if (KNOWN_ORDER_FIELDS.indexOf(key) < 0) {
      errors.push(makeError(key, 'unknown field'));
    }
  }

  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  }

  const order: Order = {
    id: id,
    status: status,
    lines: lines
  };
  const noErrors: FieldError[] = [];
  return { order: order, errors: noErrors };
}

// solution.ets
// A self-contained shape library.
//
// `Shape` is modeled as an abstract base class. Every concrete shape is a
// subclass, so a new kind of shape can be added later simply by declaring
// another subclass and extending the dispatch in `area`.

export abstract class Shape {
}

export class Circle extends Shape {
  readonly radius: number

  constructor(radius: number) {
    super()
    this.radius = radius
  }
}

export class Rectangle extends Shape {
  readonly width: number
  readonly height: number

  constructor(width: number, height: number) {
    super()
    this.width = width
    this.height = height
  }
}

export class Triangle extends Shape {
  readonly base: number
  readonly height: number

  constructor(base: number, height: number) {
    super()
    this.base = base
    this.height = height
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius)
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height)
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height)
}

export function area(shape: Shape): number {
  if (shape instanceof Circle) {
    return Math.PI * shape.radius * shape.radius
  }
  if (shape instanceof Rectangle) {
    return shape.width * shape.height
  }
  if (shape instanceof Triangle) {
    return shape.base * shape.height / 2
  }
  return 0
}

export function totalArea(shapes: Shape[]): number {
  let total: number = 0
  for (let i = 0; i < shapes.length; i++) {
    total += area(shapes[i])
  }
  return total
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        result.push({ id: item.id, name: item.name, quantity: quantity });
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    current = updateQuantity(current, changes[i].id, changes[i].quantity);
  }
  return current;
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1 || items.length === 0) {
    return result;
  }
  for (let i = 0; i < items.length; i += size) {
    const end: number = Math.min(i + size, items.length);
    const group: T[] = items.slice(i, end);
    result.push(group);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const daysWithRules = new Set<Weekday>();
  for (let i = 0; i < rules.length; i++) {
    daysWithRules.add(rules[i].day);
  }
  if (daysWithRules.size === 0) {
    return undefined;
  }
  const dayCount = 7;
  const base = day.valueOf();
  // Check the 6 days after `day`, then `day` itself (one week later).
  for (let offset = 1; offset <= dayCount; offset++) {
    const candidate = (base + offset) % dayCount;
    const candidateDay = candidate as Weekday;
    if (daysWithRules.has(candidateDay)) {
      return candidateDay;
    }
  }
  return undefined;
}

export class LruCache<K, V> {
  private readonly capacity_: number;
  private readonly map: Map<K, V> = new Map<K, V>();

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('capacity must be a whole number of 1 or more');
    }
    this.capacity_ = capacity;
  }

  get size(): number {
    return this.map.size;
  }

  set(key: K, value: V): void {
    // Re-insert so the key becomes the most recently used.
    if (this.map.has(key)) {
      this.map.delete(key);
    }
    this.map.set(key, value);
    if (this.map.size > this.capacity_) {
      this.evictLeastRecentlyUsed();
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }
    const value: V = this.map.get(key) as V;
    // Refresh recency by deleting and re-inserting.
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    this.map.forEach((value: V, key: K) => {
      result.push(key);
    });
    return result;
  }

  private evictLeastRecentlyUsed(): void {
    // Map preserves insertion order, so the first key is the least recently used.
    let eldest: K | undefined = undefined;
    let found: boolean = false;
    this.map.forEach((value: V, key: K) => {
      if (!found) {
        eldest = key;
        found = true;
      }
    });
    if (found) {
      this.map.delete(eldest as K);
    }
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  const result: User[] = [];
  try {
    const parsed: Object | null = JSON.parse(json);
    if (parsed === null || !(parsed instanceof Array)) {
      return result;
    }
    const arr: Object[] = parsed as Object[];
    for (let i = 0; i < arr.length; i++) {
      const item: Object = arr[i];
      // Skip null / undefined and anything that is not a plain object.
      if (item === null || item === undefined) {
        continue;
      }
      if (typeof item !== 'object' || item instanceof Array) {
        continue;
      }
      const rec: Record<string, Object> = item as Record<string, Object>;
      const idRaw: Object = rec['id'];
      const nameRaw: Object = rec['name'];
      const emailRaw: Object = rec['email'];
      // All three fields must be present.
      if (idRaw === undefined || nameRaw === undefined || emailRaw === undefined) {
        continue;
      }
      // Types must match: id number, name string, email string.
      if (typeof idRaw !== 'number' || typeof nameRaw !== 'string' || typeof emailRaw !== 'string') {
        continue;
      }
      const idVal: number = idRaw as number;
      const nameVal: string = nameRaw as string;
      const emailVal: string = emailRaw as string;
      // id must be an integer number.
      if (!Number.isInteger(idVal)) {
        continue;
      }
      // name must be non-empty.
      if (nameVal.length === 0) {
        continue;
      }
      // email must contain '@'.
      if (emailVal.indexOf('@') < 0) {
        continue;
      }
      const user: User = {
        id: idVal,
        name: nameVal,
        email: emailVal
      };
      result.push(user);
    }
  } catch (e) {
    // Any unexpected failure: return whatever has been collected so far.
  }
  return result;
}

