// Modal dialog used to change the daily goal.
@CustomDialog
struct GoalDialog {
  controller: CustomDialogController;
  // Bound to the page so the field can be cleared before each open.
  @Link goalInput: string;
  // The page hands this in; the dialog never changes the goal itself.
  onSave: (glasses: number) => void = () => {};

  // Returns the entered goal if it is a whole number >= 1, otherwise -1.
  private parseGoal(): number {
    const text: string = this.goalInput.trim();
    if (text.length === 0) {
      return -1;
    }
    const value: number = Number.parseInt(text, 10);
    if (Number.isNaN(value) || value < 1 || `${value}` !== text) {
      return -1;
    }
    return value;
  }

  build() {
    Column({ space: 16 }) {
      Text('Daily goal')
        .fontSize(22)
        .fontWeight(FontWeight.Bold);

      TextInput({ text: this.goalInput, placeholder: 'Glasses per day' })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.goalInput = value;
        });

      Row({ space: 8 }) {
        ForEach(GOAL_PRESETS, (preset: GoalPreset) => {
          Button(preset.label)
            .layoutWeight(1)
            .fontSize(14)
            .onClick(() => {
              this.goalInput = `${preset.glasses}`;
            });
        }, (preset: GoalPreset) => preset.label);
      }
      .width('100%');

      Row({ space: 8 }) {
        Button('Cancel')
          .onClick(() => {
            this.controller.close();
          });
        Blank();
        Button('Save')
          .onClick(() => {
            const glasses: number = this.parseGoal();
            if (glasses >= 1) {
              this.controller.close();
              this.onSave(glasses);
            }
          });
      }
      .width('100%');
    }
    .width('90%')
    .padding(24)
    .backgroundColor(Color.White)
    .borderRadius(16);
  }
}

