struct Solution {
  @State inputText: string = '';
  @State todos: TodoItem[] = [];
  private nextId: number = 0;

  private addTodo(): void {
    const trimmed: string = this.inputText.trim();
    if (trimmed.length === 0) {
      return;
    }
    const item: TodoItem = new TodoItem(trimmed, this.nextId);
    this.nextId += 1;
    this.todos = this.todos.concat([item]);
    this.inputText = '';
