  private isValidEmail(value: string): boolean {
    // Exactly one '@', at least one character before it, and after it
    // a '.' with at least one character on each side (name@host.tld).
    const pattern: RegExp = /^[^@]+@[^@]+\.[^@]+$/
    return pattern.test(value)
