    return this.email.length > 0 && !this.emailValid
  }

  private get showPasswordError(): boolean {
    return this.password.length > 0 && !this.passwordValid
  }

  private get canSignIn(): boolean {
    return this.emailValid && this.passwordValid
  }

  build() {
    Column({ space: 16 }) {
