interface Item {
  id: number;
  name: string;
}

interface LoadState {
  status: 'loading' | 'success' | 'error';
  items: Item[];
}

@Entry
@Component
struct Index {
  @State loadState: LoadState = { status: 'loading', items: [] };

  aboutToAppear(): void {
    this.fetchItems();
  }

  private fetchItems(): void {
    this.loadState = { status: 'loading', items: [] };

    const httpClient = http.createHttp();
    httpClient.request(
      'https://example.com/api/items',
      {
        method: http.RequestMethod.GET,
        expectDataType: http.HttpDataType.STRING,
        connectTimeout: 15000,
        readTimeout: 15000
      }
    ).then((response: http.HttpResponse) => {
      if (response.responseCode !== 200) {
        this.loadState = { status: 'error', items: [] };
        return;
      }
      try {
        const parsed = JSON.parse(response.result as string) as Item[];
        if (!Array.isArray(parsed)) {
          this.loadState = { status: 'error', items: [] };
          return;
        }
        this.loadState = { status: 'success', items: parsed };
      } catch (err) {
        this.loadState = { status: 'error', items: [] };
      }
    }).catch(() => {
      this.loadState = { status: 'error', items: [] };
    }).finally(() => {
      httpClient.destroy();
    });
  }

  build() {
    Column() {
      if (this.loadState.status === 'loading') {
        Text('Loading...')
          .fontSize(18)
          .alignSelf(ItemAlign.Center)
      } else if (this.loadState.status === 'error') {
        Text('Could not load the items')
          .fontSize(18)
          .alignSelf(ItemAlign.Center)
      } else {
        List({ space: 8 }) {
