export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
    this.message = `Task '${task}' depends on unknown task '${dependency}'`;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
    this.message = `Dependency cycle: ${path.join(' -> ')}`;
  }
}

export class BuildPlan {
  private names: string[] = [];
  private deps: Record<string, string[]> = {};
  private placedOrder: string[] = [];

  constructor(spec: Record<string, string[]>) {
    this.names = Object.keys(spec);
    this.deps = spec;

    // First pass: every dependency must be a known task.
    const known = new Set<string>();
    for (const name of this.names) {
      known.add(name);
    }
    for (const task of this.names) {
      const list: string[] = spec[task];
      for (const dep of list) {
        if (!known.has(dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Second pass: place the tasks, detecting cycles.
    const placed: string[] = [];
    const placedSet = new Set<string>();
    const stack: string[] = [];
    const inStack = new Set<string>();

    const place = (task: string): void => {
      if (placedSet.has(task)) {
        return;
      }
      if (inStack.has(task)) {
        const start: number = stack.indexOf(task);
        const cyclePath: string[] = stack.slice(start);
        cyclePath.push(task);
        throw new CycleError(cyclePath);
      }
      stack.push(task);
      inStack.add(task);
      const list: string[] = spec[task];
      for (const dep of list) {
        place(dep);
      }
      stack.pop();
      inStack.delete(task);
      placedSet.add(task);
      placed.push(task);
    };

    for (const task of this.names) {
      place(task);
    }

    this.placedOrder = placed;
  }

  order(): string[] {
    return this.placedOrder.slice();
  }

  layers(): string[][] {
    if (this.names.length === 0) {
      return [];
    }
    const layerOf = new Map<string, number>();
    const layer = (task: string): number => {
      const cached: number | undefined = layerOf.get(task);
      if (cached !== undefined) {
        return cached;
      }
      let value: number = 0;
      const list: string[] = this.deps[task];
      for (const dep of list) {
        const depLayer: number = layer(dep);
        if (depLayer + 1 > value) {
          value = depLayer + 1;
        }
      }
      layerOf.set(task, value);
      return value;
    };
    const result: string[][] = [];
    for (const task of this.names) {
      const index: number = layer(task);
      while (result.length <= index) {
        const empty: string[] = [];
        result.push(empty);
      }
      result[index].push(task);
    }
    return result;
  }

  dependentsOf(name: string): string[] {
    if (this.names.indexOf(name) < 0) {
      return [];
    }

    // Build reverse edges (each task listed once per dependency).
    const reverse = new Map<string, string[]>();
    for (const task of this.names) {
      const list: string[] = this.deps[task];
      const seen = new Set<string>();
      for (const dep of list) {
        if (!seen.has(dep)) {
          seen.add(dep);
          let arr: string[] | undefined = reverse.get(dep);
          if (arr === undefined) {
            arr = [];
            reverse.set(dep, arr);
          }
          arr.push(task);
        }
      }
    }

    // Breadth-first search over the reverse edges, starting at name.
    const reached = new Set<string>();
    const queue: string[] = [];
    queue.push(name);
    let head: number = 0;
    while (head < queue.length) {
      const current: string = queue[head];
      head++;
      const next: string[] | undefined = reverse.get(current);
      if (next === undefined) {
        continue;
      }
      for (const t of next) {
        if (t !== name && !reached.has(t)) {
          reached.add(t);
          queue.push(t);
        }
      }
    }

    // Report in the order of order().
    const result: string[] = [];
    for (const task of this.placedOrder) {
      if (reached.has(task)) {
        result.push(task);
      }
    }
    return result;
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type EditorValue = string | number | boolean;
type EditorListener = (value: EditorValue, previous: EditorValue) => void;
type TransactionRunner = (draft: EditorState) => void;

interface PatchValues {
  text: string | undefined;
  cursor: number | undefined;
  bold: boolean | undefined;
}

class Watcher {
  field: string;
  listener: EditorListener;

  constructor(field: string, listener: EditorListener) {
    this.field = field;
    this.listener = listener;
  }
}

export class EditorStore {
  private current: EditorState;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private readonly limit: number;
  private watchers: Watcher[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.current = EditorStore.copyOf(initial);
    const whole: number = Math.floor(historyLimit);
    this.limit = whole >= 1 ? whole : 1;
  }

  get state(): EditorState {
    return EditorStore.copyOf(this.current);
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const values: PatchValues = {
      text: patch.text,
      cursor: patch.cursor,
      bold: patch.bold
    };
    return this.commitValues(values);
  }

  transaction(run: TransactionRunner): boolean {
    const draft: EditorState = EditorStore.copyOf(this.current);
    run(draft);
    const values: PatchValues = {
      text: draft.text,
      cursor: draft.cursor,
      bold: draft.bold
    };
    return this.commitValues(values);
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const top: EditorState | undefined = this.undoStack.pop();
    if (top === undefined) {
      return false;
    }
    const before: EditorState = this.current;
    this.redoStack.push(EditorStore.copyOf(before));
    this.current = top;
    this.notifyChanged(before, this.current);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const top: EditorState | undefined = this.redoStack.pop();
    if (top === undefined) {
      return false;
    }
    const before: EditorState = this.current;
    this.undoStack.push(EditorStore.copyOf(before));
    if (this.undoStack.length > this.limit) {
      this.undoStack.shift();
    }
    this.current = top;
    this.notifyChanged(before, this.current);
    return true;
  }

  watch(field: string, listener: EditorListener): () => void {
    const entry: Watcher = new Watcher(field, listener);
    this.watchers.push(entry);
    let removed: boolean = false;
    const unwatch = (): void => {
      if (removed) {
        return;
      }
      removed = true;
      const index: number = this.watchers.indexOf(entry);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
    return unwatch;
  }

  private static copyOf(source: EditorState): EditorState {
    const copy: EditorState = {
      text: source.text,
      cursor: source.cursor,
      bold: source.bold
    };
    return copy;
  }

  private commitValues(values: PatchValues): boolean {
    const before: EditorState = this.current;
    const after: EditorState = EditorStore.copyOf(before);
    let changed: boolean = false;

    if (values.text !== undefined && values.text !== before.text) {
      after.text = values.text;
      changed = true;
    }
    if (values.cursor !== undefined && values.cursor !== before.cursor) {
      after.cursor = values.cursor;
      changed = true;
    }
    if (values.bold !== undefined && values.bold !== before.bold) {
      after.bold = values.bold;
      changed = true;
    }

    if (!changed) {
      return false;
    }

    this.undoStack.push(EditorStore.copyOf(before));
    while (this.undoStack.length > this.limit) {
      this.undoStack.shift();
    }
    this.redoStack = [];
    this.current = after;
    this.notifyChanged(before, after);
    return true;
  }

  private notifyChanged(before: EditorState, after: EditorState): void {
    const textChanged: boolean = before.text !== after.text;
    const cursorChanged: boolean = before.cursor !== after.cursor;
    const boldChanged: boolean = before.bold !== after.bold;
    for (const watcher of this.watchers) {
      if (watcher.field === 'text' && textChanged) {
        watcher.listener(after.text, before.text);
      } else if (watcher.field === 'cursor' && cursorChanged) {
        watcher.listener(after.cursor, before.cursor);
      } else if (watcher.field === 'bold' && boldChanged) {
        watcher.listener(after.bold, before.bold);
      }
    }
  }
}

