export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueItem {
  run: () => void = () => {};
  cancel: () => void = () => {};
}

export class JobQueue {
  private concurrency: number;
  private items: Array<QueueItem> = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (Math.floor(concurrency) !== concurrency || concurrency < 1) {
      throw new Error('concurrency must be a whole number of 1 or more');
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.items.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    const item: QueueItem = new QueueItem();
    const promise: Promise<T> = new Promise<T>((resolve, reject) => {
      const succeed = (value: T): void => {
        this.runningCount--;
        this.completedCount++;
        resolve(value);
        this.afterSettle();
      };
      const fail = (err: Error): void => {
        this.runningCount--;
        this.failedCount++;
        reject(err);
        this.afterSettle();
      };
      item.run = (): void => {
        this.runningCount++;
        try {
          job().then(succeed).catch(fail);
        } catch (e) {
          fail(new Error('Job threw before returning a promise'));
        }
      };
      item.cancel = (): void => {
        reject(new Error('Job was cancelled'));
      };
    });
    this.items.push(item);
    if (!this.paused && this.runningCount < this.concurrency) {
      this.startNext();
    }
    return promise;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.startNext();
    this.checkIdle();
  }

  clear(): number {
    const removed: Array<QueueItem> = this.items;
    this.items = [];
    const count: number = removed.length;
    for (const item of removed) {
      item.cancel();
    }
    this.checkIdle();
    return count;
  }

  whenIdle(): Promise<void> {
    return new Promise<void>((resolve) => {
      const wake = (): void => {
        resolve();
      };
      this.idleResolvers.push(wake);
      this.checkIdle();
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    return new Promise<JobOutcome<T>[]>((resolve) => {
      const total: number = jobs.length;
      if (total === 0) {
        const empty: JobOutcome<T>[] = [];
        resolve(empty);
        return;
      }
      const outcomes: JobOutcome<T>[] = new Array<JobOutcome<T>>(total);
      let remaining: number = total;
      const settleOne = (): void => {
        remaining--;
        if (remaining === 0) {
          resolve(outcomes);
        }
      };
      for (let i = 0; i < total; i++) {
        const job: () => Promise<T> = jobs[i];
        const index: number = i;
        this.add<T>(job)
          .then((value: T): void => {
            const outcome: JobOutcome<T> = {
              ok: true,
              value: value,
              error: undefined
            };
            outcomes[index] = outcome;
            settleOne();
          })
          .catch((err: Error): void => {
            const outcome: JobOutcome<T> = {
              ok: false,
              value: undefined,
              error: err
            };
            outcomes[index] = outcome;
            settleOne();
          });
      }
    });
  }

  private startNext(): void {
    while (!this.paused && this.runningCount < this.concurrency && this.items.length > 0) {
      const item: QueueItem = this.items[0];
      this.items.splice(0, 1);
      item.run();
    }
  }

  private afterSettle(): void {
    this.startNext();
    this.checkIdle();
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.items.length === 0 && this.idleResolvers.length > 0) {
      const resolvers: Array<() => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (const wake of resolvers) {
        wake();
      }
    }
  }
}

