export class Stack<T> {
  private items: T[] = [];
  private readonly capacity: number;

  constructor(capacity: number) {
    if (capacity < 0) {
      throw new Error('capacity must be non-negative');
    }
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    const copy: T[] = [];
    for (let i: number = 0; i < this.items.length; i++) {
      copy.push(this.items[i]);
    }
    return copy;
  }
}

// solution.ets
// A small calculator for arithmetic expressions with variables.

export interface Token {
  kind: string; // 'number' | 'name' | 'operator' | 'paren'
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function isDigit(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

function isNameStart(ch: string): boolean {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
}

function isNameChar(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < source.length) {
    const ch = source.charAt(i);
    if (ch === ' ') {
      i++;
      continue;
    }
    if (isDigit(ch)) {
      const start = i;
      while (i < source.length && isDigit(source.charAt(i))) {
        i++;
      }
      // A '.' is part of the number only with a digit on both sides.
      if (i < source.length && source.charAt(i) === '.' &&
        i + 1 < source.length && isDigit(source.charAt(i + 1))) {
        i++;
        while (i < source.length && isDigit(source.charAt(i))) {
          i++;
        }
      }
      const token: Token = {
        kind: 'number',
        text: source.substring(start, i),
        position: start
      };
      tokens.push(token);
      continue;
    }
    if (isNameStart(ch)) {
      const start = i;
      i++;
      while (i < source.length && isNameChar(source.charAt(i))) {
        i++;
      }
      const token: Token = {
        kind: 'name',
        text: source.substring(start, i),
        position: start
      };
      tokens.push(token);
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%') {
      const token: Token = { kind: 'operator', text: ch, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    if (ch === '(' || ch === ')') {
      const token: Token = { kind: 'paren', text: ch, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${ch}'`, i);
  }
  return tokens;
}

// ---- Syntax tree ----

abstract class ExprNode {
}

class NumberNode extends ExprNode {
  value: number;

  constructor(value: number) {
    super();
    this.value = value;
  }
}

class VariableNode extends ExprNode {
  name: string;
  position: number;

  constructor(name: string, position: number) {
    super();
    this.name = name;
    this.position = position;
  }
}

class NegateNode extends ExprNode {
  operand: ExprNode;

  constructor(operand: ExprNode) {
    super();
    this.operand = operand;
  }
}

class BinaryNode extends ExprNode {
  operator: string;
  left: ExprNode;
  right: ExprNode;
  position: number;

  constructor(operator: string, left: ExprNode, right: ExprNode, position: number) {
    super();
    this.operator = operator;
    this.left = left;
    this.right = right;
    this.position = position;
  }
}

// ---- Parser (syntax errors only, no evaluation) ----

class Parser {
  private tokens: Token[] = [];
  private index: number = 0;
  private sourceLength: number = 0;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
    this.index = 0;
  }

  parse(): ExprNode {
    if (this.tokens.length === 0) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    const node = this.parseExpression();
    if (this.index < this.tokens.length) {
      const extra = this.tokens[this.index];
      throw new ExpressionError(`Unexpected token '${extra.text}'`, extra.position);
    }
    return node;
  }

  private peek(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return undefined;
  }

  private parseExpression(): ExprNode {
    let node = this.parseTerm();
    while (true) {
      const t = this.peek();
      if (t !== undefined && t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.index++;
        const right = this.parseTerm();
        node = new BinaryNode(t.text, node, right, t.position);
      } else {
        break;
      }
    }
    return node;
  }

  private parseTerm(): ExprNode {
    let node = this.parseFactor();
    while (true) {
      const t = this.peek();
      if (t !== undefined && t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.index++;
        const right = this.parseFactor();
        node = new BinaryNode(t.text, node, right, t.position);
      } else {
        break;
      }
    }
    return node;
  }

  private parseFactor(): ExprNode {
    const t = this.peek();
    if (t === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (t.kind === 'operator' && t.text === '-') {
      this.index++;
      return new NegateNode(this.parseFactor());
    }
    if (t.kind === 'number') {
      this.index++;
      return new NumberNode(Number(t.text));
    }
    if (t.kind === 'name') {
      this.index++;
      return new VariableNode(t.text, t.position);
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.index++;
      const inner = this.parseExpression();
      const close = this.peek();
      if (close === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.index++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

// ---- Evaluation ----

function evaluateNode(node: ExprNode, variables: Map<string, number>): number {
  if (node instanceof NumberNode) {
    return node.value;
  }
  if (node instanceof VariableNode) {
    const value = variables.get(node.name);
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return value;
  }
  if (node instanceof NegateNode) {
    return -evaluateNode(node.operand, variables);
  }
  if (node instanceof BinaryNode) {
    const left = evaluateNode(node.left, variables);
    const right = evaluateNode(node.right, variables);
    if (node.operator === '+') {
      return left + right;
    }
    if (node.operator === '-') {
      return left - right;
    }
    if (node.operator === '*') {
      return left * right;
    }
    if (node.operator === '/') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', node.position);
      }
      return left / right;
    }
    // '%'
    if (right === 0) {
      throw new ExpressionError('Division by zero', node.position);
    }
    return left % right;
  }
  throw new Error('Unknown expression node');
}

export function evaluate(source: string, variables: Record<string, number>): number {
  // Token errors first.
  const tokens = tokenize(source);
  // Syntax errors next: the whole expression is parsed before any evaluation.
  const parser = new Parser(tokens, source.length);
  const root = parser.parse();
  // Copy the record into a map for dynamic lookups.
  const values = new Map<string, number>();
  const keys = Object.keys(variables);
  for (const key of keys) {
    values.set(key, variables[key]);
  }
  return evaluateNode(root, values);
}

export enum ShapeKind {
  Circle,
  Rectangle,
  Triangle
}

export abstract class Shape {
  readonly kind: ShapeKind

  constructor(kind: ShapeKind) {
    this.kind = kind
  }
}

export class Circle extends Shape {
  readonly radius: number

  constructor(radius: number) {
    super(ShapeKind.Circle)
    this.radius = radius
  }
}

export class Rectangle extends Shape {
  readonly width: number
  readonly height: number

  constructor(width: number, height: number) {
    super(ShapeKind.Rectangle)
    this.width = width
    this.height = height
  }
}

export class Triangle extends Shape {
  readonly base: number
  readonly height: number

  constructor(base: number, height: number) {
    super(ShapeKind.Triangle)
    this.base = base
    this.height = height
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius)
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height)
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height)
}

export function area(shape: Shape): number {
  if (shape instanceof Circle) {
    return Math.PI * shape.radius * shape.radius
  }
  if (shape instanceof Rectangle) {
    return shape.width * shape.height
  }
  if (shape instanceof Triangle) {
    return shape.base * shape.height / 2
  }
  throw new Error('Unknown shape kind: ' + shape.kind.toString())
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0
  for (const shape of shapes) {
    sum += area(shape)
  }
  return sum
}

// solution.ets
// Self-contained URL query string parser. No imports.

function isHexDigit(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function hexValue(c: string): number {
  if (c >= '0' && c <= '9') {
    return c.charCodeAt(0) - 48;
  }
  if (c >= 'a' && c <= 'f') {
    return c.charCodeAt(0) - 87;
  }
  return c.charCodeAt(0) - 55;
}

function isContinuationByte(b: number): boolean {
  return (b & 0xC0) === 0x80;
}

function codePointToString(cp: number): string {
  if (cp <= 0xFFFF) {
    return String.fromCharCode(cp);
  }
  const v = cp - 0x10000;
  const hi = 0xD800 + (v >> 10);
  const lo = 0xDC00 + (v & 0x3FF);
  return String.fromCharCode(hi, lo);
}

// Decode a UTF-8 byte sequence into a string. Invalid sequences become U+FFFD.
function decodeUtf8(bytes: number[]): string {
  let out = '';
  let i = 0;
  const n = bytes.length;
  while (i < n) {
    const b = bytes[i];
    let cp = -1;
    let step = 1;
    if (b < 0x80) {
      cp = b;
      step = 1;
    } else if ((b & 0xE0) === 0xC0) {
      if (i + 1 < n && isContinuationByte(bytes[i + 1])) {
        const v = ((b & 0x1F) << 6) | (bytes[i + 1] & 0x3F);
        if (v >= 0x80) {
          cp = v;
          step = 2;
        }
      }
    } else if ((b & 0xF0) === 0xE0) {
      if (i + 2 < n && isContinuationByte(bytes[i + 1]) && isContinuationByte(bytes[i + 2])) {
        const v = ((b & 0x0F) << 12) | ((bytes[i + 1] & 0x3F) << 6) | (bytes[i + 2] & 0x3F);
        if (v >= 0x800 && !(v >= 0xD800 && v <= 0xDFFF)) {
          cp = v;
          step = 3;
        }
      }
    } else if ((b & 0xF8) === 0xF0) {
      if (i + 3 < n && isContinuationByte(bytes[i + 1]) && isContinuationByte(bytes[i + 2]) &&
        isContinuationByte(bytes[i + 3])) {
        const v = ((b & 0x07) << 18) | ((bytes[i + 1] & 0x3F) << 12) |
          ((bytes[i + 2] & 0x3F) << 6) | (bytes[i + 3] & 0x3F);
        if (v >= 0x10000 && v <= 0x10FFFF) {
          cp = v;
          step = 4;
        }
      }
    }
    if (cp >= 0) {
      out += codePointToString(cp);
    } else {
      out += String.fromCharCode(0xFFFD);
    }
    i += step;
  }
  return out;
}

// Decode a single query component: '+' becomes a space and valid %XX escapes
// are decoded as UTF-8. Malformed escapes are kept as written.
function decodeComponent(s: string): string {
  let out = '';
  let pending: number[] = [];
  const n = s.length;
  let i = 0;
  while (i < n) {
    const c = s[i];
    let handled = false;
    if (c === '%') {
      if (i + 2 < n && isHexDigit(s[i + 1]) && isHexDigit(s[i + 2])) {
        pending.push(hexValue(s[i + 1]) * 16 + hexValue(s[i + 2]));
        i += 3;
        handled = true;
      }
    }
    if (!handled) {
      if (pending.length > 0) {
        out += decodeUtf8(pending);
        pending = [];
      }
      if (c === '+') {
        out += ' ';
      } else {
        out += c;
      }
      i += 1;
    }
  }
  if (pending.length > 0) {
    out += decodeUtf8(pending);
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const map = new Map<string, string>();
  let q = query;
  if (q.length > 0 && q[0] === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return map;
  }
  const parts = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq = part.indexOf('=');
    let rawKey = '';
    let rawVal = '';
    if (eq === -1) {
      rawKey = part;
      rawVal = '';
    } else if (eq === 0) {
      // A pair with an empty key is ignored.
      continue;
    } else {
      rawKey = part.substring(0, eq);
      rawVal = part.substring(eq + 1);
    }
    const key = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value = decodeComponent(rawVal);
    // Map.set keeps the first insertion position and lets the last value win.
    map.set(key, value);
  }
  return map;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  const first: Point = points[0];
  let minX: number = first.x;
  let minY: number = first.y;
  let maxX: number = first.x;
  let maxY: number = first.y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };
  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };
  return box;
}

