export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const total: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('unknown error');
  for (let i: number = 0; i < total; i++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }
  throw new RetryError(total, lastError);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  let found = false;
  for (let i = 0; i < items.length; i++) {
    if (items[i].id === id) {
      found = true;
      break;
    }
  }
  if (!found) {
    return items;
  }
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = { id: item.id, name: item.name, quantity: quantity };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    const change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

class PipelineStep {
  name: string;
  step: Transform;

  constructor(name: string, step: Transform) {
    this.name = name;
    this.step = step;
  }
}

export class Pipeline {
  private steps: PipelineStep[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push(new PipelineStep(name, step));
    return this;
  }

  run(text: string): string {
    let result: string = text;
    for (const entry of this.steps) {
      result = entry.step(result);
    }
    return result;
  }

  names(): string[] {
    const result: string[] = [];
    for (const entry of this.steps) {
      result.push(entry.name);
    }
    return result;
  }

  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  for (let i = 0; i < items.length; i += size) {
    const end: number = Math.min(i + size, items.length);
    const group: T[] = items.slice(i, end);
    result.push(group);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = {
      first: a[i],
      second: b[i]
    };
    result.push(pair);
  }
  return result;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>>;

  constructor() {
    this.listeners = new Map<string, Array<Listener<T>>>();
  }

  on(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.listeners.set(event, list);
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        return;
      }
    }
    list.push(listener);
  }

  off(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        list.splice(i, 1);
        return;
      }
    }
  }

  emit(event: string, payload: T): number {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    let snapshot: Array<Listener<T>> = list.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && rule.openHour <= hour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const hasRule: boolean[] = [false, false, false, false, false, false, false];
  for (let i = 0; i < rules.length; i++) {
    hasRule[rules[i].day] = true;
  }

  for (let offset = 1; offset <= 6; offset++) {
    const candidate: number = (day + offset) % 7;
    if (hasRule[candidate]) {
      return candidate as Weekday;
    }
  }

  if (hasRule[day]) {
    return day;
  }

  return undefined;
}

@Entry
@Component
struct Solution {
  @State count: number = 0

