export interface User {
  id: number
  name: string
  email: string
}

function isPlainObjectValue(value: Object): boolean {
  if (typeof value !== 'object') {
    return false
  }
  if (value === null || value === undefined) {
    return false
  }
  if (Array.isArray(value)) {
    return false
  }
  return true
}

function toUser(element: Object): User | null {
  if (!isPlainObjectValue(element)) {
    return null
  }
  const record: Record<string, Object> = element as Record<string, Object>
  const idValue: Object = record['id']
  const nameValue: Object = record['name']
  const emailValue: Object = record['email']
  if (typeof idValue !== 'number') {
    return null
  }
  if (typeof nameValue !== 'string') {
    return null
  }
  if (typeof emailValue !== 'string') {
    return null
  }
  const id: number = idValue as number
  const name: string = nameValue as string
  const email: string = emailValue as string
  if (!Number.isInteger(id)) {
    return null
  }
  if (name.length === 0) {
    return null
  }
  if (email.indexOf('@') < 0) {
    return null
  }
  const user: User = {
    id: id,
    name: name,
    email: email
  }
  return user
}

export function parseUsers(json: string): User[] {
  const users: User[] = []
  let parsed: Object | undefined = undefined
  try {
    parsed = JSON.parse(json) as Object
  } catch (e) {
    return users
  }
  if (parsed === undefined || parsed === null) {
    return users
  }
  if (!Array.isArray(parsed)) {
    return users
  }
  const elements: Array<Object> = parsed as Array<Object>
  for (const element of elements) {
    const user: User | null = toUser(element)
    if (user !== null) {
      users.push(user)
    }
  }
  return users
}

const UNIT_H: string = 'h'
const UNIT_M: string = 'm'
const UNIT_S: string = 's'

function isDigit(c: string): boolean {
  const code: number = c.charCodeAt(0)
  return code >= 48 && code <= 57
}

function pad2(n: number): string {
  return n < 10 ? `0${n}` : `${n}`
}

function parsePart(part: string): number {
  if (part.length < 2) {
    return NaN
  }
  const unit: string = part.charAt(part.length - 1)
  if (unit !== UNIT_H && unit !== UNIT_M && unit !== UNIT_S) {
    return NaN
  }
  let value: number = 0
  for (let i: number = 0; i < part.length - 1; i++) {
    const c: string = part.charAt(i)
    if (!isDigit(c)) {
      return NaN
    }
    value = value * 10 + (part.charCodeAt(i) - 48)
  }
  if (unit === UNIT_H) {
    return value * 3600
  }
  if (unit === UNIT_M) {
    return value * 60
  }
  return value
}

export function formatDuration(totalSeconds: number): string {
  let negative: boolean = false
  let seconds: number = totalSeconds
  if (seconds < 0) {
    negative = true
    seconds = -seconds
  }
  let result: string
  if (seconds < 60) {
    result = `${seconds}s`
  } else if (seconds < 3600) {
    const minutes: number = Math.floor(seconds / 60)
    const rest: number = seconds % 60
    result = `${minutes}m ${pad2(rest)}s`
  } else {
    const hours: number = Math.floor(seconds / 3600)
    const minutes: number = Math.floor((seconds % 3600) / 60)
    const rest: number = seconds % 60
    result = `${hours}h ${pad2(minutes)}m ${pad2(rest)}s`
  }
  return negative ? `-${result}` : result
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN
  }
  let negative: boolean = false
  let body: string = text
  if (body.charAt(0) === '-') {
    negative = true
    body = body.substring(1)
    if (body.length === 0) {
      return NaN
    }
  }
  const parts: string[] = body.split(' ')
  let total: number = 0
  for (const part of parts) {
    const value: number = parsePart(part)
    if (Number.isNaN(value)) {
      return NaN
    }
    total += value
  }
  return negative ? -total : total
}

