class Node<K, V> {
  key: K;
  value: V;
  prev: Node<K, V> | undefined;
  next: Node<K, V> | undefined;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
    this.prev = undefined;
    this.next = undefined;
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, Node<K, V>>;
  private head: Node<K, V> | undefined;
  private tail: Node<K, V> | undefined;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.map = new Map<K, Node<K, V>>();
    this.head = undefined;
    this.tail = undefined;
  }

  private removeNode(node: Node<K, V>): void {
    const prev: Node<K, V> | undefined = node.prev;
    const next: Node<K, V> | undefined = node.next;
    if (prev !== undefined) {
      prev.next = next;
    } else {
      this.head = next;
    }
    if (next !== undefined) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }
    node.prev = undefined;
    node.next = undefined;
  }

  private addToTail(node: Node<K, V>): void {
    const tail: Node<K, V> | undefined = this.tail;
    if (tail === undefined) {
      this.head = node;
      this.tail = node;
    } else {
      tail.next = node;
      node.prev = tail;
      this.tail = node;
    }
  }

  private moveToTail(node: Node<K, V>): void {
    if (this.tail === node) {
      return;
    }
    this.removeNode(node);
    this.addToTail(node);
  }

  set(key: K, value: V): void {
    const existing: Node<K, V> | undefined = this.map.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToTail(existing);
      return;
    }
    const node: Node<K, V> = new Node<K, V>(key, value);
    this.map.set(key, node);
    this.addToTail(node);
    if (this.map.size > this.capacity) {
      const lru: Node<K, V> | undefined = this.head;
      if (lru !== undefined) {
        this.removeNode(lru);
        this.map.delete(lru.key);
      }
    }
  }

  get(key: K): V | undefined {
    const node: Node<K, V> | undefined = this.map.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToTail(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: Node<K, V> | undefined = this.head;
    while (current !== undefined) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  get size(): number {
    return this.map.size;
  }
}

