export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.name = 'MissingDependencyError';
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.name = 'CycleError';
    this.path = path;
  }
}

export class BuildPlan {
  private keys: string[] = [];
  private deps: Map<string, string[]> = new Map<string, string[]>();
  private orderCache: string[] = [];

  constructor(spec: Record<string, string[]>) {
    this.keys = Object.keys(spec);
    this.deps = new Map<string, string[]>();

    for (const key of this.keys) {
      const list = spec[key];
      if (list !== undefined) {
        this.deps.set(key, list.slice());
      } else {
        this.deps.set(key, []);
      }
    }

    for (const task of this.keys) {
      const list = this.deps.get(task);
      if (list !== undefined) {
        for (const dep of list) {
          if (!this.deps.has(dep)) {
            throw new MissingDependencyError(task, dep);
          }
        }
      }
    }

    const placed = new Set<string>();
    const active: string[] = [];
    const activeSet = new Set<string>();
    const result: string[] = [];

    for (const task of this.keys) {
      this.visit(task, placed, active, activeSet, result);
    }

    this.orderCache = result;
  }

  private visit(
    task: string,
    placed: Set<string>,
    active: string[],
    activeSet: Set<string>,
    result: string[]
  ): void {
    if (placed.has(task)) {
      return;
    }

    if (activeSet.has(task)) {
      const index = active.indexOf(task);
      const path = active.slice(index);
      path.push(task);
      throw new CycleError(path);
    }

    active.push(task);
    activeSet.add(task);

    const list = this.deps.get(task);
    if (list !== undefined) {
      for (const dep of list) {
        this.visit(dep, placed, active, activeSet, result);
      }
    }

    active.pop();
    activeSet.delete(task);
    placed.add(task);
    result.push(task);
  }

  order(): string[] {
    return this.orderCache.slice();
  }

  layers(): string[][] {
    const layerOf = new Map<string, number>();
    const result: string[][] = [];

    for (const task of this.keys) {
      const layer = this.computeLayer(task, layerOf);
      while (result.length <= layer) {
        result.push([]);
      }
      result[layer].push(task);
    }

    return result;
  }

  private computeLayer(task: string, layerOf: Map<string, number>): number {
    const cached = layerOf.get(task);
    if (cached !== undefined) {
      return cached;
    }

    const list = this.deps.get(task);
    let max = -1;

    if (list !== undefined) {
      for (const dep of list) {
        const depLayer = this.computeLayer(dep, layerOf);
        if (depLayer > max) {
          max = depLayer;
        }
      }
    }

    const layer = max + 1;
    layerOf.set(task, layer);
    return layer;
  }

  dependentsOf(name: string): string[] {
    if (!this.deps.has(name)) {
      return [];
    }

    const reverse = new Map<string, string[]>();

    for (const task of this.keys) {
      const list = this.deps.get(task);
      if (list !== undefined) {
        for (const dep of list) {
          let arr = reverse.get(dep);
          if (arr === undefined) {
            arr = [];
            reverse.set(dep, arr);
          }
          arr.push(task);
        }
      }
    }

    const seen = new Set<string>();
    const queue: string[] = [];

    const direct = reverse.get(name);
    if (direct !== undefined) {
      for (const task of direct) {
        if (!seen.has(task)) {
          seen.add(task);
          queue.push(task);
        }
      }
    }

    let index = 0;
    while (index < queue.length) {
      const current = queue[index];
      index++;

      const next = reverse.get(current);
      if (next !== undefined) {
        for (const task of next) {
          if (!seen.has(task)) {
            seen.add(task);
            queue.push(task);
          }
        }
      }
    }

    const result: string[] = [];
    for (const task of this.orderCache) {
      if (task !== name && seen.has(task)) {
        result.push(task);
      }
    }

    return result;
  }
}

