export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i: number = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };
  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };
  return box;
}

export class Stack<T> {
  private items: T[] = [];
  private readonly capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return this.items.slice();
  }
}

/**
 * A shape that can compute its own area.
 *
 * Modelling `Shape` as an interface with an `area()` method keeps the type open
 * for extension: a new kind of shape only needs to implement this interface and
 * provide a factory function — no existing code has to change.
 */
export interface Shape {
  area(): number;
}

class Circle implements Shape {
  private radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle implements Shape {
  private width: number;
  private height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

class Triangle implements Shape {
  private base: number;
  private height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += shape.area();
  }
  return sum;
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const maxAttempts: number = Math.max(1, Math.floor(attempts));
  let lastError: Error = new Error('Unknown error');

  for (let i = 0; i < maxAttempts; i++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(maxAttempts, lastError);
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      const created: Listener<T>[] = [listener];
      this.listeners.set(event, created);
      return;
    }
    if (existing.indexOf(listener) === -1) {
      existing.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return;
    }
    const index: number = existing.indexOf(listener);
    if (index !== -1) {
      existing.splice(index, 1);
    }
    if (existing.length === 0) {
      this.listeners.delete(event);
    }
  }

  emit(event: string, payload: T): number {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    const snapshot: Listener<T>[] = existing.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    return existing.length;
  }
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        result.push({ id: item.id, name: item.name, quantity: quantity });
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items.slice();
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

