/**
 * Duration formatting and parsing helpers.
 * Self-contained: no imports.
 */

function pad2(value: number): string {
  return value < 10 ? '0' + value.toString() : value.toString();
}

/**
 * Formats a whole number of seconds as a human readable duration.
 * Examples: "0s", "59s", "1m 00s", "1h 05m 09s", "-1m 30s".
 */
export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const abs: number = negative ? -totalSeconds : totalSeconds;

  const hours: number = Math.floor(abs / 3600);
  const minutes: number = Math.floor((abs % 3600) / 60);
  const seconds: number = abs % 60;

  let body: string;
  if (hours > 0) {
    body = hours.toString() + 'h ' + pad2(minutes) + 'm ' + pad2(seconds) + 's';
  } else if (minutes > 0) {
    body = minutes.toString() + 'm ' + pad2(seconds) + 's';
  } else {
    body = seconds.toString() + 's';
  }

  return negative ? '-' + body : body;
}

const PART_PATTERN: RegExp = new RegExp('^[0-9]+[hms]$');

/**
 * Parses a duration text such as "1h 05m 09s" or "-1m 30s" into seconds.
 * Returns NaN when the text is not a valid duration.
 */
export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let body: string = text;
  let negative: boolean = false;
  if (body.charAt(0) === '-') {
    negative = true;
    body = body.substring(1);
  }

  if (body.length === 0) {
    return NaN;
  }

  const parts: string[] = body.split(' ');
  let total: number = 0;

  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (!PART_PATTERN.test(part)) {
      return NaN;
    }

    const unit: string = part.charAt(part.length - 1);
    const digits: string = part.substring(0, part.length - 1);
    const value: number = parseInt(digits, 10);

    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
  }

  return negative ? -total : total;
}

/**
 * A generic pair holding two values.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements.
 * The final group may be shorter. Returns an empty array when
 * `items` is empty or `size` is below 1.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  const step: number = Math.floor(size);
  if (step < 1) {
    return result;
  }
  let start: number = 0;
  while (start < items.length) {
    const end: number = Math.min(start + step, items.length);
    const group: T[] = [];
    for (let i = start; i < end; i++) {
      group.push(items[i]);
    }
    result.push(group);
    start = end;
  }
  return result;
}

/**
 * Combines two arrays element-wise into pairs. The result has the
 * length of the shorter input.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

function replacePlus(s: string): string {
  let out: string = '';
  for (let i = 0; i < s.length; i++) {
    const ch: string = s.charAt(i);
    out += ch === '+' ? ' ' : ch;
  }
  return out;
}

function decodeComponent(s: string): string {
  const plusReplaced: string = replacePlus(s);
  try {
    return decodeURIComponent(plusReplaced);
  } catch (e) {
    return plusReplaced;
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();

  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }

  if (q.length === 0) {
    return result;
  }

  const parts: string[] = q.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (part.length === 0) {
      continue;
    }

    const eq: number = part.indexOf('=');
    let rawKey: string = '';
    let rawValue: string = '';

    if (eq >= 0) {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    } else {
      rawKey = part;
      rawValue = '';
    }

    const key: string = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }

    const value: string = decodeComponent(rawValue);
    result.set(key, value);
  }

  return result;
}

