export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

const WEEK_DAYS: Weekday[] = [
  Weekday.Monday,
  Weekday.Tuesday,
  Weekday.Wednesday,
  Weekday.Thursday,
  Weekday.Friday,
  Weekday.Saturday,
  Weekday.Sunday
];

function indexOfDay(day: Weekday): number {
  for (let i: number = 0; i < WEEK_DAYS.length; i++) {
    if (WEEK_DAYS[i] === day) {
      return i;
    }
  }
  return 0;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i: number = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const startIndex: number = indexOfDay(day);

  for (let offset: number = 1; offset <= 7; offset++) {
    const candidate: Weekday = WEEK_DAYS[(startIndex + offset) % 7];

    for (let i: number = 0; i < rules.length; i++) {
      if (rules[i].day === candidate) {
        return candidate;
      }
    }
  }

  return undefined;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

class Step {
  name: string;
  step: Transform;

  constructor(name: string, step: Transform) {
    this.name = name;
    this.step = step;
  }
}

export class Pipeline {
  private steps: Step[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push(new Step(name, step));
    return this;
  }

  run(text: string): string {
    let result: string = text;
    for (const entry of this.steps) {
      result = entry.step(result);
    }
    return result;
  }

  names(): string[] {
    const result: string[] = [];
    for (const entry of this.steps) {
      result.push(entry.name);
    }
    return result;
  }

  toFunction(): Transform {
    return (text: string): string => this.run(text);
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

