class CacheNode<K, V> {
  key: K;
  value: V;
  prev: CacheNode<K, V> | null = null;
  next: CacheNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, CacheNode<K, V>> = new Map<K, CacheNode<K, V>>();
  private head: CacheNode<K, V> | null = null;
  private tail: CacheNode<K, V> | null = null;
  private count: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  get size(): number {
    return this.count;
  }

  private detach(node: CacheNode<K, V>): void {
    const prev: CacheNode<K, V> | null = node.prev;
    const next: CacheNode<K, V> | null = node.next;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.head = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private append(node: CacheNode<K, V>): void {
    node.prev = this.tail;
    node.next = null;
    if (this.tail !== null) {
      this.tail.next = node;
    } else {
      this.head = node;
    }
    this.tail = node;
  }

  set(key: K, value: V): void {
    const existing: CacheNode<K, V> | undefined = this.map.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.detach(existing);
      this.append(existing);
      return;
    }
    const node: CacheNode<K, V> = new CacheNode<K, V>(key, value);
    this.map.set(key, node);
    this.append(node);
    this.count++;
    if (this.count > this.capacity) {
      const oldest: CacheNode<K, V> | null = this.head;
      if (oldest !== null) {
        this.detach(oldest);
        this.map.delete(oldest.key);
        this.count--;
      }
    }
  }

  get(key: K): V | undefined {
    const node: CacheNode<K, V> | undefined = this.map.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.detach(node);
    this.append(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: CacheNode<K, V> | null = this.head;
    while (current !== null) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }
}

