/*
 * solution.ets
 *
 * Self-contained JSON reader that extracts valid `User` objects from a JSON
 * array text. A small hand-written JSON parser is used so that the function
 * never throws and never relies on dynamic typing.
 */

export interface User {
  id: number;
  name: string;
  email: string;
}

/**
 * A minimal JSON value tree.
 * kind: 0 = null, 1 = boolean, 2 = number, 3 = string, 4 = array, 5 = object
 */
class JsonValue {
  kind: number = 0;
  boolValue: boolean = false;
  numValue: number = 0;
  strValue: string = '';
  arrValue: JsonValue[] = [];
  objKeys: string[] = [];
  objValues: JsonValue[] = [];
}

class JsonParser {
  private text: string;
  private pos: number = 0;
  private failed: boolean = false;

  constructor(text: string) {
    this.text = text;
  }

  parse(): JsonValue | null {
    this.skipWhitespace();
    const value = this.parseValue();
    if (this.failed || value === null) {
      return null;
    }
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      return null;
    }
    return value;
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const code = this.text.charCodeAt(this.pos);
      if (code === 32 || code === 9 || code === 10 || code === 13) {
        this.pos++;
      } else {
        break;
      }
    }
  }

  private matchLiteral(literal: string): boolean {
    if (this.pos + literal.length > this.text.length) {
      this.failed = true;
      return false;
    }
    const slice = this.text.substring(this.pos, this.pos + literal.length);
    if (slice === literal) {
      this.pos += literal.length;
      return true;
    }
    this.failed = true;
    return false;
  }

  private parseValue(): JsonValue | null {
    if (this.failed) {
      return null;
    }
    this.skipWhitespace();
    if (this.pos >= this.text.length) {
      this.failed = true;
      return null;
    }
    const c = this.text.charAt(this.pos);
    const code = this.text.charCodeAt(this.pos);

    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      const s = this.parseString();
      if (s === null) {
        return null;
      }
      const v = new JsonValue();
      v.kind = 3;
      v.strValue = s;
      return v;
    }
    if (c === 't') {
      if (!this.matchLiteral('true')) {
        return null;
      }
      const v = new JsonValue();
      v.kind = 1;
      v.boolValue = true;
      return v;
    }
    if (c === 'f') {
      if (!this.matchLiteral('false')) {
        return null;
      }
      const v = new JsonValue();
      v.kind = 1;
      v.boolValue = false;
      return v;
    }
    if (c === 'n') {
      if (!this.matchLiteral('null')) {
        return null;
      }
      const v = new JsonValue();
      v.kind = 0;
      return v;
    }
    if (c === '-' || (code >= 48 && code <= 57)) {
      return this.parseNumber();
    }

    this.failed = true;
    return null;
  }

  private parseObject(): JsonValue | null {
    const result = new JsonValue();
    result.kind = 5;
    this.pos++; // consume '{'
    this.skipWhitespace();

    if (this.pos < this.text.length && this.text.charAt(this.pos) === '}') {
      this.pos++;
      return result;
    }

    while (true) {
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== '"') {
        this.failed = true;
        return null;
      }
      const key = this.parseString();
      if (key === null) {
        return null;
      }
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== ':') {
        this.failed = true;
        return null;
      }
      this.pos++; // consume ':'
      const value = this.parseValue();
      if (value === null) {
        return null;
      }
      result.objKeys.push(key);
      result.objValues.push(value);

      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        this.failed = true;
        return null;
      }
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
        continue;
      }
      if (c === '}') {
        this.pos++;
        return result;
      }
      this.failed = true;
      return null;
    }
  }

  private parseArray(): JsonValue | null {
    const result = new JsonValue();
    result.kind = 4;
    this.pos++; // consume '['
    this.skipWhitespace();

    if (this.pos < this.text.length && this.text.charAt(this.pos) === ']') {
      this.pos++;
      return result;
    }

    while (true) {
      const value = this.parseValue();
      if (value === null) {
        return null;
      }
      result.arrValue.push(value);

      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        this.failed = true;
        return null;
      }
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
        continue;
      }
      if (c === ']') {
        this.pos++;
        return result;
      }
      this.failed = true;
      return null;
    }
  }

  private parseString(): string | null {
    // Current character is the opening quote.
    this.pos++;
    let out = '';

    while (true) {
      if (this.pos >= this.text.length) {
        this.failed = true;
        return null;
      }
      const code = this.text.charCodeAt(this.pos);

      if (code === 34) { // '"'
        this.pos++;
        return out;
      }

      if (code === 92) { // '\\'
        this.pos++;
        if (this.pos >= this.text.length) {
          this.failed = true;
          return null;
        }
        const esc = this.text.charAt(this.pos);
        if (esc === '"') {
          out += '"';
          this.pos++;
        } else if (esc === '\\') {
          out += '\\';
          this.pos++;
        } else if (esc === '/') {
          out += '/';
          this.pos++;
        } else if (esc === 'b') {
          out += '\b';
          this.pos++;
        } else if (esc === 'f') {
          out += '\f';
          this.pos++;
        } else if (esc === 'n') {
          out += '\n';
          this.pos++;
        } else if (esc === 'r') {
          out += '\r';
          this.pos++;
        } else if (esc === 't') {
          out += '\t';
          this.pos++;
        } else if (esc === 'u') {
          this.pos++;
          if (this.pos + 4 > this.text.length) {
            this.failed = true;
            return null;
          }
          let unit = 0;
          for (let i = 0; i < 4; i++) {
            const digit = this.hexDigit(this.text.charCodeAt(this.pos + i));
            if (digit < 0) {
              this.failed = true;
              return null;
            }
            unit = unit * 16 + digit;
          }
          this.pos += 4;
          out += String.fromCharCode(unit);
        } else {
          this.failed = true;
          return null;
        }
        continue;
      }

      if (code < 32) {
        this.failed = true;
        return null;
      }

      out += this.text.charAt(this.pos);
      this.pos++;
    }
  }

  private hexDigit(code: number): number {
    if (code >= 48 && code <= 57) {
      return code - 48;
    }
    if (code >= 65 && code <= 70) {
      return code - 55;
    }
    if (code >= 97 && code <= 102) {
      return code - 87;
    }
    return -1;
  }

  private parseNumber(): JsonValue | null {
    const start = this.pos;

    if (this.pos < this.text.length && this.text.charAt(this.pos) === '-') {
      this.pos++;
    }

    // Integer part.
    if (this.pos >= this.text.length) {
      this.failed = true;
      return null;
    }
    let code = this.text.charCodeAt(this.pos);
    if (code === 48) { // '0'
      this.pos++;
    } else if (code >= 49 && code <= 57) {
      while (this.pos < this.text.length) {
        code = this.text.charCodeAt(this.pos);
        if (code >= 48 && code <= 57) {
          this.pos++;
        } else {
          break;
        }
      }
    } else {
      this.failed = true;
      return null;
    }

    // Fraction part.
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '.') {
      this.pos++;
      if (this.pos >= this.text.length) {
        this.failed = true;
        return null;
      }
      code = this.text.charCodeAt(this.pos);
      if (code < 48 || code > 57) {
        this.failed = true;
        return null;
      }
      while (this.pos < this.text.length) {
        code = this.text.charCodeAt(this.pos);
        if (code >= 48 && code <= 57) {
          this.pos++;
        } else {
          break;
        }
      }
    }

    // Exponent part.
    if (this.pos < this.text.length) {
      const e = this.text.charAt(this.pos);
      if (e === 'e' || e === 'E') {
        this.pos++;
        if (this.pos < this.text.length) {
          const sign = this.text.charAt(this.pos);
          if (sign === '+' || sign === '-') {
            this.pos++;
          }
        }
        if (this.pos >= this.text.length) {
          this.failed = true;
          return null;
        }
        code = this.text.charCodeAt(this.pos);
        if (code < 48 || code > 57) {
          this.failed = true;
          return null;
        }
        while (this.pos < this.text.length) {
          code = this.text.charCodeAt(this.pos);
          if (code >= 48 && code <= 57) {
            this.pos++;
          } else {
            break;
          }
        }
      }
    }

    const literal = this.text.substring(start, this.pos);
    const value = new JsonValue();
    value.kind = 2;
    value.numValue = Number.parseFloat(literal);
    return value;
  }
}

function getField(obj: JsonValue, key: string): JsonValue | null {
  let found: JsonValue | null = null;
  for (let i = 0; i < obj.objKeys.length; i++) {
    if (obj.objKeys[i] === key) {
      found = obj.objValues[i];
    }
  }
  return found;
}

function toUser(value: JsonValue): User | null {
  if (value.kind !== 5) {
    return null;
  }

  const idValue = getField(value, 'id');
  const nameValue = getField(value, 'name');
  const emailValue = getField(value, 'email');

  if (idValue === null || nameValue === null || emailValue === null) {
    return null;
  }
  if (idValue.kind !== 2 || !Number.isInteger(idValue.numValue)) {
    return null;
  }
  if (nameValue.kind !== 3 || nameValue.strValue.length === 0) {
    return null;
  }
  if (emailValue.kind !== 3 || emailValue.strValue.indexOf('@') < 0) {
    return null;
  }

  const user: User = {
    id: idValue.numValue,
    name: nameValue.strValue,
    email: emailValue.strValue
  };
  return user;
}

export function parseUsers(json: string): User[] {
  const users: User[] = [];
  try {
    const parser = new JsonParser(json);
    const root = parser.parse();
    if (root === null || root.kind !== 4) {
      return users;
    }
    const items = root.arrValue;
    for (let i = 0; i < items.length; i++) {
      const user = toUser(items[i]);
      if (user !== null) {
        users.push(user);
      }
    }
  } catch (e) {
    return [];
  }
  return users;
}

