@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isEmailValid(value: string): boolean {
    const atIndex: number = value.indexOf('@');
    if (atIndex <= 0) {
      return false;
    }
    if (value.indexOf('@', atIndex + 1) >= 0) {
      return false;
    }
    const domain: string = value.substring(atIndex + 1);
    const dotIndex: number = domain.indexOf('.');
    if (dotIndex <= 0 || dotIndex >= domain.length - 1) {
      return false;
    }
    return true;
  }

  private isPasswordValid(value: string): boolean {
    return value.length >= 8;
  }

  private canSubmit(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  build() {
    Column({ space: 8 }) {
      Text('Sign in')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .width('100%')
        .margin({ bottom: 16 })

      TextInput({ placeholder: 'Email', text: this.email })
        .type(InputType.Email)
        .height(48)
        .width('100%')
        .onChange((value: string) => {
          this.email = value;
        })

      if (this.email.length > 0 && !this.isEmailValid(this.email)) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor('#E84026')
          .width('100%')
      }

      TextInput({ placeholder: 'Password', text: this.password })
        .type(InputType.Password)
        .height(48)
        .width('100%')
        .margin({ top: 8 })
        .onChange((value: string) => {
          this.password = value;
        })

      if (this.password.length > 0 && !this.isPasswordValid(this.password)) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor('#E84026')
          .width('100%')
      }

      Button('Sign in')
        .width('100%')
        .height(44)
        .margin({ top: 16 })
        .enabled(this.canSubmit())
        .onClick(() => {
          console.info('Sign in tapped for: ' + this.email);
        })
    }
    .width('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Start)
  }
}

