import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';
import { BusinessError } from '@kit.BasicServicesKit';

const PREF_STORE: string = 'app_settings';
const KEY_NAME: string = 'user_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State inputName: string = '';
  private store: preferences.Preferences | undefined = undefined;

  aboutToAppear(): void {
    this.loadName();
  }

  onPageShow(): void {
    this.loadName();
  }

  private async getStore(): Promise<preferences.Preferences> {
    if (this.store === undefined) {
      const context = this.getUIContext().getHostContext() as common.UIAbilityContext;
      this.store = await preferences.getPreferences(context, PREF_STORE);
    }
    return this.store;
  }

  private async loadName(): Promise<void> {
    try {
      const store: preferences.Preferences = await this.getStore();
      const value: preferences.ValueType = await store.get(KEY_NAME, '');
      this.savedName = typeof value === 'string' ? value : '';
    } catch (err) {
      const e = err as BusinessError;
      console.error(`Failed to load name, code: ${e.code}, message: ${e.message}`);
    }
  }

  private async saveName(): Promise<void> {
    const name: string = this.inputName.trim();
    try {
      const store: preferences.Preferences = await this.getStore();
      await store.put(KEY_NAME, name);
      await store.flush();
      this.savedName = name;
    } catch (err) {
      const e = err as BusinessError;
      console.error(`Failed to save name, code: ${e.code}, message: ${e.message}`);
    }
  }

  build() {
    Column({ space: 16 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .width('100%')

      TextInput({ placeholder: 'Enter your name', text: this.inputName })
        .width('100%')
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('100%')
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Start)
    .justifyContent(FlexAlign.Start)
  }
}

@Entry
@Component
struct Index {
  @State selected: boolean[] = [
    false, false, false,
    false, false, false,
    false, false, false,
    false, false, false
  ];

  private toggle(index: number): void {
    const next: boolean[] = this.selected.slice();
    next[index] = !next[index];
    this.selected = next;
  }

  private countSelected(): number {
    let count: number = 0;
    for (let i: number = 0; i < this.selected.length; i++) {
      if (this.selected[i]) {
        count++;
      }
    }
    return count;
  }

  @Builder
  tile(index: number) {
    Stack() {
      Text(`${index + 1}`)
        .fontSize(26)
        .fontWeight(FontWeight.Medium)
        .fontColor(this.selected[index] ? Color.White : '#37474F')
    }
    .layoutWeight(1)
    .aspectRatio(1)
    .backgroundColor(this.selected[index] ? '#1E88E5' : '#E3E7EB')
    .borderRadius(14)
    .onClick(() => {
      this.toggle(index);
    })
  }

  build() {
    Column() {
      Text(`Selected: ${this.countSelected()}`)
        .fontSize(20)
        .fontWeight(FontWeight.Medium)
        .fontColor('#1F2933')
        .width('100%')
        .textAlign(TextAlign.Center)
        .margin({ top: 28, bottom: 20 })

      Column({ space: 12 }) {
        ForEach([0, 1, 2, 3], (row: number) => {
          Row({ space: 12 }) {
            ForEach([0, 1, 2], (col: number) => {
              this.tile(row * 3 + col)
            }, (col: number) => `c${col}`)
          }
          .width('100%')
        }, (row: number) => `r${row}`)
      }
      .width('100%')
      .padding({ left: 16, right: 16 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F7F9FB')
  }
}

import { http } from '@kit.NetworkKit';

interface Item {
