@Entry
@Component
struct Index {
  @State isLoading: boolean = true;
  @State hasError: boolean = false;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.loadItems();
  }

  async loadItems(): Promise<void> {
    this.isLoading = true;
    this.hasError = false;
    this.items = [];

    const httpRequest = http.createHttp();
    try {
      const response = await httpRequest.request('https://example.com/api/items', {
        method: http.RequestMethod.GET,
        expectDataType: http.HttpDataType.STRING,
        connectTimeout: 10000,
        readTimeout: 10000
      });

      if (response.responseCode === http.ResponseCode.OK) {
        const parsed: Item[] = JSON.parse(response.result as string) as Item[];
        this.items = parsed;
        this.isLoading = false;
      } else {
        this.hasError = true;
        this.isLoading = false;
      }
    } catch (err) {
      this.hasError = true;
      this.isLoading = false;
    } finally {
      httpRequest.destroy();
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(18)
      } else if (this.hasError) {
        Text('Could not load the items')
          .fontSize(18)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .width('100%')
                .padding(12)
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .divider({ strokeWidth: 1, color: '#E0E0E0' })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type EditorListener = (value: string | number | boolean, previous: string | number | boolean) => void;

class WatchEntry {
  field: string;
  listener: EditorListener;
  active: boolean;

  constructor(field: string, listener: EditorListener) {
    this.field = field;
    this.listener = listener;
    this.active = true;
  }
}

export class EditorStore {
  private text: string;
  private cursor: number;
  private bold: boolean;
  private historyLimit: number;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private watchers: WatchEntry[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.text = initial.text;
    this.cursor = initial.cursor;
    this.bold = initial.bold;
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    const snapshot: EditorState = {
      text: this.text,
      cursor: this.cursor,
      bold: this.bold
    };
    return snapshot;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next: EditorState = {
      text: this.text,
      cursor: this.cursor,
      bold: this.bold
    };
    const patchText: string | undefined = patch.text;
    if (patchText !== undefined) {
      next.text = patchText;
    }
    const patchCursor: number | undefined = patch.cursor;
    if (patchCursor !== undefined) {
      next.cursor = patchCursor;
    }
    const patchBold: boolean | undefined = patch.bold;
    if (patchBold !== undefined) {
      next.bold = patchBold;
    }
    return this.commit(next);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = this.state;
    run(draft);
    return this.commit(draft);
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const before: EditorState = this.state;
    const target: EditorState = this.undoStack[this.undoStack.length - 1];
    this.undoStack.pop();
    this.redoStack.push(before);
    this.text = target.text;
    this.cursor = target.cursor;
    this.bold = target.bold;
    this.notify(before);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const before: EditorState = this.state;
    const target: EditorState = this.redoStack[this.redoStack.length - 1];
    this.redoStack.pop();
    this.undoStack.push(before);
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
    this.text = target.text;
    this.cursor = target.cursor;
    this.bold = target.bold;
    this.notify(before);
    return true;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    const entry: WatchEntry = new WatchEntry(field, listener);
    this.watchers.push(entry);
    const dispose = (): void => {
      entry.active = false;
    };
    return dispose;
  }

  private commit(next: EditorState): boolean {
    if (next.text === this.text && next.cursor === this.cursor && next.bold === this.bold) {
      return false;
    }
    const before: EditorState = this.state;
    this.undoStack.push(before);
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
    this.redoStack.splice(0, this.redoStack.length);
    this.text = next.text;
    this.cursor = next.cursor;
    this.bold = next.bold;
    this.notify(before);
    return true;
  }

  private fieldValue(state: EditorState, field: string): string | number | boolean {
    if (field === 'cursor') {
      return state.cursor;
    }
    if (field === 'bold') {
      return state.bold;
    }
    return state.text;
  }

  private notify(before: EditorState): void {
    const after: EditorState = this.state;
    const entries: WatchEntry[] = this.watchers.slice();
    for (let i = 0; i < entries.length; i++) {
      const entry: WatchEntry = entries[i];
      if (!entry.active) {
        continue;
      }
      const newValue: string | number | boolean = this.fieldValue(after, entry.field);
      const previousValue: string | number | boolean = this.fieldValue(before, entry.field);
      if (newValue === previousValue) {
        continue;
      }
      entry.listener(newValue, previousValue);
    }
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super('Dependency cycle: ' + path.join(' -> '));
    this.path = path;
  }
}

export class BuildPlan {
  private tasks: string[] = [];
  private deps: Map<string, string[]> = new Map<string, string[]>();
  private ordered: string[] = [];

  constructor(spec: Record<string, string[]>) {
    const keys: string[] = Object.keys(spec);
    this.tasks = keys.slice();

    const taskSet: Set<string> = new Set<string>();
    for (let i = 0; i < keys.length; i++) {
      taskSet.add(keys[i]);
    }

    for (let i = 0; i < keys.length; i++) {
      const task: string = keys[i];
      const raw: string[] = spec[task];
      for (let j = 0; j < raw.length; j++) {
        const dependency: string = raw[j];
        if (!taskSet.has(dependency)) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    this.deps = new Map<string, string[]>();
    for (let i = 0; i < keys.length; i++) {
      const task: string = keys[i];
      const raw: string[] = spec[task];
      const unique: string[] = [];
      const seen: Set<string> = new Set<string>();
      for (let j = 0; j < raw.length; j++) {
        const dependency: string = raw[j];
        if (!seen.has(dependency)) {
          seen.add(dependency);
          unique.push(dependency);
        }
      }
      this.deps.set(task, unique);
    }

    const placed: Set<string> = new Set<string>();
    const visiting: Set<string> = new Set<string>();
    const chain: string[] = [];
    const result: string[] = [];

    for (let i = 0; i < keys.length; i++) {
      this.place(keys[i], placed, visiting, chain, result);
    }

    this.ordered = result;
  }

  private place(
    task: string,
    placed: Set<string>,
    visiting: Set<string>,
    chain: string[],
    result: string[]
  ): void {
    if (placed.has(task)) {
      return;
    }

    if (visiting.has(task)) {
      const index: number = chain.indexOf(task);
      const path: string[] = index >= 0 ? chain.slice(index) : [];
      path.push(task);
      throw new CycleError(path);
    }

    visiting.add(task);
    chain.push(task);

    const dependencies: string[] | undefined = this.deps.get(task);
    if (dependencies !== undefined) {
      for (let i = 0; i < dependencies.length; i++) {
        this.place(dependencies[i], placed, visiting, chain, result);
      }
    }

    chain.pop();
    visiting.delete(task);
    placed.add(task);
    result.push(task);
  }

  order(): string[] {
    return this.ordered.slice();
  }

  layers(): string[][] {
    const layerOf: Map<string, number> = new Map<string, number>();

    for (let i = 0; i < this.ordered.length; i++) {
      const task: string = this.ordered[i];
      const dependencies: string[] | undefined = this.deps.get(task);
      let layer: number = 0;

      if (dependencies !== undefined) {
        for (let j = 0; j < dependencies.length; j++) {
          const dependencyLayer: number | undefined = layerOf.get(dependencies[j]);
          if (dependencyLayer !== undefined && dependencyLayer + 1 > layer) {
            layer = dependencyLayer + 1;
          }
        }
      }

      layerOf.set(task, layer);
    }

    const result: string[][] = [];
    if (this.tasks.length === 0) {
      return result;
    }

    let maxLayer: number = 0;
    for (let i = 0; i < this.tasks.length; i++) {
      const taskLayer: number | undefined = layerOf.get(this.tasks[i]);
      if (taskLayer !== undefined && taskLayer > maxLayer) {
        maxLayer = taskLayer;
      }
    }

    for (let layerIndex = 0; layerIndex <= maxLayer; layerIndex++) {
      const layer: string[] = [];
      for (let i = 0; i < this.tasks.length; i++) {
        const task: string = this.tasks[i];
        const taskLayer: number | undefined = layerOf.get(task);
        if (taskLayer === layerIndex) {
          layer.push(task);
        }
      }
      result.push(layer);
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    if (!this.deps.has(name)) {
      return [];
    }

    const reverse: Map<string, string[]> = new Map<string, string[]>();

    for (let i = 0; i < this.tasks.length; i++) {
      const task: string = this.tasks[i];
      const dependencies: string[] | undefined = this.deps.get(task);
      if (dependencies !== undefined) {
        for (let j = 0; j < dependencies.length; j++) {
          const dependency: string = dependencies[j];
          const existing: string[] | undefined = reverse.get(dependency);
          if (existing === undefined) {
            const list: string[] = [];
            list.push(task);
            reverse.set(dependency, list);
          } else {
            existing.push(task);
          }
        }
      }
    }

    const found: Set<string> = new Set<string>();
    const stack: string[] = [];

    const direct: string[] | undefined = reverse.get(name);
    if (direct !== undefined) {
      for (let i = 0; i < direct.length; i++) {
        if (!found.has(direct[i])) {
          found.add(direct[i]);
          stack.push(direct[i]);
        }
      }
    }

    while (stack.length > 0) {
      const current: string | undefined = stack.pop();
      if (current === undefined) {
        continue;
      }

      const next: string[] | undefined = reverse.get(current);
      if (next !== undefined) {
        for (let i = 0; i < next.length; i++) {
          const candidate: string = next[i];
          if (!found.has(candidate)) {
            found.add(candidate);
            stack.push(candidate);
          }
        }
      }
    }

    const result: string[] = [];
    for (let i = 0; i < this.ordered.length; i++) {
      const task: string = this.ordered[i];
      if (found.has(task)) {
        result.push(task);
      }
    }

    return result;
  }
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class PendingJob {
  readonly start: () => void;
  readonly cancel: (reason: Error) => void;

  constructor(start: () => void, cancel: (reason: Error) => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

export class JobQueue {
  private readonly concurrency: number;
  private waitingJobs: Array<PendingJob> = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleWaiters: Array<() => void> = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const pending: PendingJob = new PendingJob(
        () => {
          this.startJob<T>(job, resolve, reject);
        },
        (reason: Error) => {
          reject(reason);
        }
      );
      this.waitingJobs.push(pending);
      this.pump();
    });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.pump();
  }

  clear(): number {
    const removed: Array<PendingJob> = this.waitingJobs;
    this.waitingJobs = [];
    for (let i = 0; i < removed.length; i++) {
      removed[i].cancel(new Error('Job was cancelled'));
    }
    this.checkIdle();
    return removed.length;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleWaiters.push(() => {
        resolve();
      });
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: Array<Promise<JobOutcome<T>>> = [];
    for (let i = 0; i < jobs.length; i++) {
      const job: () => Promise<T> = jobs[i];
      const outcome: Promise<JobOutcome<T>> = this.add<T>(job).then(
        (value: T): JobOutcome<T> => {
          const result: JobOutcome<T> = { ok: true, value: value, error: undefined };
          return result;
        },
        (err: Error): JobOutcome<T> => {
          const result: JobOutcome<T> = { ok: false, value: undefined, error: err };
          return result;
        }
      );
      outcomes.push(outcome);
    }
    return Promise.all(outcomes);
  }

  private startJob<T>(job: () => Promise<T>, resolve: (value: T) => void, reject: (reason: Error) => void): void {
    this.runningCount = this.runningCount + 1;
    let promise: Promise<T>;
    try {
      promise = job();
    } catch (e) {
      this.runningCount = this.runningCount - 1;
      this.failedCount = this.failedCount + 1;
      reject(e as Error);
      return;
    }
    promise.then((value: T) => {
      this.runningCount = this.runningCount - 1;
      this.completedCount = this.completedCount + 1;
      resolve(value);
      this.pump();
    }, (err: Error) => {
      this.runningCount = this.runningCount - 1

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();

  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }

  return totals;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

export function defaultSettings(): Settings {
  const result: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return result;
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const theme: string = user.theme !== undefined ? user.theme : defaults.theme;
  const fontSize: number = user.fontSize !== undefined ? user.fontSize : defaults.fontSize;
  const notifications: boolean =
    user.notifications !== undefined ? user.notifications : defaults.notifications;
  const language: string = user.language !== undefined ? user.language : defaults.language;

  const merged: Settings = {
    theme: theme,
    fontSize: fontSize,
    notifications: notifications,
    language: language
  };
  return merged;
}

// App-wide reading settings, shared through AppStorage:
//   'textSize' : number  (14..30, default 18)
//   'isBold'   : boolean (default false)

class SizePreset {
  label: string;
  size: number;

  constructor(label: string, size: number) {
    this.label = label;
    this.size = size;
  }
}

const MIN_SIZE: number = 14;
const MAX_SIZE: number = 30;
const SIZE_STEP: number = 2;

const SIZE_PRESETS: SizePreset[] = [
  new SizePreset('Small', 14),
  new SizePreset('Medium', 18),
  new SizePreset('Large', 24)
];

AppStorage.setOrCreate<number>('textSize', 18);
AppStorage.setOrCreate<boolean>('isBold', false);

@Component
struct SizeControls {
  @StorageLink('textSize') textSize: number = 18;

  private clampSize(value: number): number {
    if (value < MIN_SIZE) {
      return MIN_SIZE;
    }
    if (value > MAX_SIZE) {
      return MAX_SIZE;
    }
    return value;
  }

  build() {
    Column({ space: 12 }) {
      Row({ space: 16 }) {
        Button('A-')
          .onClick(() => {
            this.textSize = this.clampSize(this.textSize - SIZE_STEP);
          })

        Text(this.textSize.toString())
          .fontSize(22)
          .fontWeight(FontWeight.Medium)
          .width(56)
          .textAlign(TextAlign.Center)

        Button('A+')
          .onClick(() => {
            this.textSize = this.clampSize(this.textSize + SIZE_STEP);
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      Row({ space: 12 }) {
        ForEach(SIZE_PRESETS, (preset: SizePreset) => {
          Button(preset.label)
            .onClick(() => {
              this.textSize = preset.size;
            })
        }, (preset: SizePreset) => preset.label)
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)
    }
    .width('100%')
    .padding(12)
  }
}

@Component
struct TextPreview {
  @StorageLink('textSize') @Watch('onTextSizeChanged') textSize: number = 18;
  @StorageLink('isBold') isBold: boolean = false;
  @State displaySize: number = 18;

  aboutToAppear(): void {
    this.displaySize = this.textSize;
  }

  onTextSizeChanged(): void {
    animateTo({ duration: 300, curve: Curve.EaseInOut }, () => {
      this.displaySize = this.textSize;
    });
  }

  build() {
    Column() {
      Text('The quick brown fox')
        .fontSize(this.displaySize)
        .fontWeight(this.isBold ? FontWeight.Bold : FontWeight.Normal)
        .textAlign(TextAlign.Center)
        .width('100%')
    }
    .width('100%')
    .padding(12)
  }
}

@Component
struct ChangeCounter {
  @StorageLink('textSize') @Watch('onTextSizeChanged') textSize: number = 18;
  @State count: number = 0;
  private lastSize: number = 18;

  aboutToAppear(): void {
    this.lastSize = this.textSize;
  }

  onTextSizeChanged(): void {
    if (this.textSize !== this.lastSize) {
      this.lastSize = this.textSize;
      this.count = this.count + 1;
    }
  }

  build() {
    Text(`Changed ${this.count} times`)
      .fontSize(16)
      .width('100%')
      .textAlign(TextAlign.Center)
      .padding(12)
  }
}

@Entry
@Component
struct Index {
  @StorageLink('isBold') isBold: boolean = false;

  build() {
    Column({ space: 16 }) {
      Row({ space: 12 }) {
        Text('Bold')
          .fontSize(18)

        Toggle({ type: ToggleType.Switch, isOn: this.isBold })
          .onChange((isOn: boolean) => {
            this.isBold = isOn;
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.Center)

      SizeControls()

      TextPreview()

      ChangeCounter()
    }
    .width('100%')
