@Entry
@Component
struct CheckoutPage {
  @Provide('largeText') largeText: boolean = false;
  @State selectedId: string = 'home';
  private pathStack: NavPathStack = new NavPathStack();

  private labelOf(id: string): string {
    for (let i = 0; i < ADDRESSES.length; i++) {
      if (ADDRESSES[i].id === id) {
        return ADDRESSES[i].label;
      }
    }
    return '';
  }

  private openAddresses(): void {
    this.pathStack.pushPathByName('addresses', this.selectedId, (info: PopInfo) => {
      const picked: Object = info.result;
      if (typeof picked === 'string') {
        this.selectedId = picked as string;
      }
    });
  }

  @Builder
  PageMap(name: string) {
    if (name === 'addresses') {
      AddressesScreen({
        currentId: this.selectedId,
        pathStack: this.pathStack
      })
    }
  }

  build() {
    Navigation(this.pathStack) {
      Column() {
