export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const minPoint: Point = { x: minX, y: minY };
  const maxPoint: Point = { x: maxX, y: maxY };
  const box: Box = {
    min: minPoint,
    max: maxPoint,
    width: maxX - minX,
    height: maxY - minY
  };
  return box;
}

import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';

const STORE_NAME: string = 'water_tracker_store';
const KEY_COUNT: string = 'glasses_drunk';
const KEY_GOAL: string = 'daily_goal';
const DEFAULT_GOAL: number = 8;

/**
 * A quick choice offered in the goal dialog.
 */
class GoalPreset {
  label: string;
  glasses: number;

  constructor(label: string, glasses: number) {
    this.label = label;
    this.glasses = glasses;
  }
}

const GOAL_PRESETS: GoalPreset[] = [
  new GoalPreset('Light', 6),
  new GoalPreset('Standard', 8),
  new GoalPreset('Active', 12)
];

/**
 * Modal dialog used to pick a new daily goal.
 * It never changes the goal itself: it only reports the chosen number
 * through the callback the page handed to it.
 */
@CustomDialog
struct GoalDialog {
  controller?: CustomDialogController;
  onSave: (glasses: number) => void = (glasses: number): void => {
  };
  @State input: string = '';

  aboutToAppear(): void {
    this.input = '';
  }

  private applyPreset(preset: GoalPreset): void {
    this.input = preset.glasses.toString();
  }

  private closeDialog(): void {
    if (this.controller !== undefined) {
      this.controller.close();
    }
  }

  private save(): void {
    const trimmed: string = this.input.trim();
    if (trimmed.length === 0) {
      return;
    }
    const value: number = Number(trimmed);
    if (Number.isNaN(value) || !Number.isInteger(value) || value < 1) {
      return;
    }
    this.closeDialog();
    this.onSave(value);
  }

  build() {
    Column({ space: 16 }) {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Glasses per day', text: this.input })
        .type(InputType.Number)
        .width('100%')
        .onChange((value: string) => {
          this.input = value;
        })

      Row({ space: 8 }) {
        ForEach(GOAL_PRESETS, (preset: GoalPreset) => {
          Button(preset.label)
            .layoutWeight(1)
            .onClick(() => {
              this.applyPreset(preset);
            })
        }, (preset: GoalPreset) => preset.label)
      }
      .width('100%')

      Row({ space: 8 }) {
        Button('Cancel')
          .layoutWeight(1)
          .backgroundColor(Color.Gray)
          .onClick(() => {
            this.closeDialog();
          })

        Button('Save')
          .layoutWeight(1)
          .onClick(() => {
            this.save();
          })
      }
      .width('100%')
    }
    .width('100%')
    .padding(24)
  }
}

@Entry
@Component
struct WaterTrackerPage {
  @State count: number = 0;
  @State goal: number = DEFAULT_GOAL;
  private store: preferences.Preferences | undefined = undefined;

  private goalDialog: CustomDialogController = new CustomDialogController({
    builder: GoalDialog({
      onSave: (glasses: number): void => {
        this.applyGoal(glasses);
      }
    }),
    autoCancel: true,
    alignment: DialogAlignment.Center
  });

  aboutToAppear(): void {
    this.loadState();
  }

  private async getStore(): Promise<preferences.Preferences | undefined> {
    if (this.store !== undefined) {
      return this.store;
    }
    try {
      const context: common.Context = getContext(this) as common.Context;
      const options: preferences.Options = { name: STORE_NAME };
      const opened: preferences.Preferences = await preferences.getPreferences(context, options);
      this.store = opened;
      return opened;
    } catch (e) {
      return undefined;
    }
  }

  private async loadState(): Promise<void> {
    const store: preferences.Preferences | undefined = await this.getStore();
    if (store === undefined) {
      return;
    }
    try {
      const savedCount: preferences.ValueType = await store.get(KEY_COUNT, 0);
      const savedGoal: preferences.ValueType = await store.get(KEY_GOAL, DEFAULT_GOAL);
      if (typeof savedCount === 'number') {
        this.count = savedCount;
      }
      if (typeof savedGoal === 'number') {
        this.goal = savedGoal;
      }
    } catch (e) {
      // Keep the defaults when nothing could be read.
    }
  }

  private async saveState(): Promise<void> {
    const store: preferences.Preferences | undefined = await this.getStore();
    if (store === undefined) {
      return;
    }
    try {
      await store.put(KEY_COUNT, this.count);
      await store.put(KEY_GOAL, this.goal);
      await store.flush();
    } catch (e) {
      // Nothing else to do: the in-memory values stay correct.
    }
  }

  private addGlass(): void {
    this.count = this.count + 1;
    this.saveState();
  }

  private applyGoal(glasses: number): void {
    this.goal = glasses;
    this.saveState();
  }

  build() {
    Column({ space: 20 }) {
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(28)
        .fontWeight(FontWeight.Bold)

      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(20)
          .fontColor(Color.Green)
      }

      Button('Add a glass')
        .width(200)
        .onClick(() => {
          this.addGlass();
        })

      Button('Change goal')
        .width(200)
        .onClick(() => {
          this.goalDialog.open();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(24)
  }
}

/**
 * A last-in, first-out stack that holds at most a fixed number of items.
 */
export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  /**
   * @param capacity the largest number of items the stack can hold.
   */
  constructor(capacity: number) {
    if (capacity > 0) {
      this.capacity = Math.floor(capacity);
    } else {
      this.capacity = 0;
    }
  }

  /**
   * Puts the item on top of the stack.
   * @returns true when the item was added, false when the stack is full.
   */
  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes and returns the top item, or undefined when the stack is empty.
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it, or undefined when the stack is empty.
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * How many items the stack currently holds.
   */
  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /**
   * Removes every item from the stack.
   */
  clear(): void {
    this.items = [];
  }

  /**
   * The items from bottom to top, as a new array that is independent of the stack.
   */
  toArray(): T[] {
    const copy: T[] = [];
    for (let i = 0; i < this.items.length; i++) {
      copy.push(this.items[i]);
    }
    return copy;
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private readonly listeners: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    const existing = this.listeners.get(event);
    if (existing === undefined) {
      const listeners: Listener<T>[] = [listener];
      this.listeners.set(event, listeners);
    } else {
      if (existing.indexOf(listener) === -1) {
        existing.push(listener);
      }
    }
  }

  off(event: string, listener: Listener<T>): void {
    const existing = this.listeners.get(event);
    if (existing === undefined) {
      return;
    }
    const index = existing.indexOf(listener);
    if (index !== -1) {
      existing.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    const existing = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    const snapshot = existing.slice();
    for (const listener of snapshot) {
      listener(payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const existing = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    return existing.length;
  }
}

/**
 * A shape that can be measured.
 *
 * Shape is an abstract class so that every concrete shape is a real class and
 * new kinds of shapes can be added later by extending it. The `area()` method
 * is the single extension point: `area()` and `totalArea()` below only need
 * this interface and never look at the concrete shape.
 */
export abstract class Shape {
  abstract area(): number;
}

/** A circle given by its radius. */
export class Circle extends Shape {
  private radius: number;

  constructor(radius: number) {
    super();
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

/** A rectangle given by its width and height. */
export class Rectangle extends Shape {
  private width: number;
  private height: number;

  constructor(width: number, height: number) {
    super();
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

/** A triangle given by one side and the height on that side. */
export class Triangle extends Shape {
  private base: number;
  private height: number;

  constructor(base: number, height: number) {
    super();
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

/** Creates a circle with the given radius. */
export function circle(radius: number): Shape {
  return new Circle(radius);
}

/** Creates a rectangle with the given width and height. */
export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

/** Creates a triangle with the given base and the height on that base. */
export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

/** Returns the area of a single shape. */
export function area(shape: Shape): number {
  return shape.area();
}

/** Returns the sum of the areas of all shapes; 0 for an empty list. */
export function totalArea(shapes: Shape[]): number {
  let total: number = 0;
  for (const shape of shapes) {
    total += shape.area();
  }
  return total;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = { id: item.id, name: item.name, quantity: quantity };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

