class JsonValue {
}

class JsonNull extends JsonValue {
}

class JsonBool extends JsonValue {
  value: boolean;

  constructor(value: boolean) {
    super();
    this.value = value;
  }
}

class JsonNumber extends JsonValue {
  value: number;

  constructor(value: number) {
    super();
    this.value = value;
  }
}

class JsonString extends JsonValue {
  value: string;

  constructor(value: string) {
    super();
    this.value = value;
  }
}

class JsonArray extends JsonValue {
  items: JsonValue[];

  constructor(items: JsonValue[]) {
    super();
    this.items = items;
  }
}

class JsonObject extends JsonValue {
  keys: string[];
  values: JsonValue[];

  constructor(keys: string[], values: JsonValue[]) {
    super();
    this.keys = keys;
    this.values = values;
  }
}

function hexDigit(c: string): number {
  const code = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  return -1;
}

class JsonParser {
  private text: string;
  private pos: number = 0;

  constructor(text: string) {
    this.text = text;
  }

  parse(): JsonValue {
    this.skipWhitespace();
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      throw new Error('trailing characters');
    }
    return value;
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const c = this.text.charAt(this.pos);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.pos++;
      } else {
        break;
      }
    }
  }

  private expectLiteral(lit: string): void {
    if (this.text.substring(this.pos, this.pos + lit.length) !== lit) {
      throw new Error('invalid literal');
    }
    this.pos += lit.length;
  }

  private parseValue(): JsonValue {
    this.skipWhitespace();
    if (this.pos >= this.text.length) {
      throw new Error('unexpected end of input');
    }
    const c = this.text.charAt(this.pos);
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      return new JsonString(this.parseString());
    }
    if (c === 't') {
      this.expectLiteral('true');
      return new JsonBool(true);
    }
    if (c === 'f') {
      this.expectLiteral('false');
      return new JsonBool(false);
    }
    if (c === 'n') {
      this.expectLiteral('null');
      return new JsonNull();
    }
    if (c === '-' || (c >= '0' && c <= '9')) {
      return this.parseNumber();
    }
    throw new Error('unexpected character');
  }

  private parseObject(): JsonObject {
    this.pos++;
    const keys: string[] = [];
    const values: JsonValue[] = [];
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '}') {
      this.pos++;
      return new JsonObject(keys, values);
    }
    while (true) {
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== '"') {
        throw new Error('expected key');
      }
      const key = this.parseString();
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== ':') {
        throw new Error('expected colon');
      }
      this.pos++;
      const value = this.parseValue();
      keys.push(key);
      values.push(value);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        throw new Error('unexpected end of input');
      }
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
      } else if (c === '}') {
        this.pos++;
        break;
      } else {
        throw new Error('expected comma or closing brace');
      }
    }
    return new JsonObject(keys, values);
  }

  private parseArray(): JsonArray {
    this.pos++;
    const items: JsonValue[] = [];
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === ']') {
      this.pos++;
      return new JsonArray(items);
    }
    while (true) {
      const value = this.parseValue();
      items.push(value);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        throw new Error('unexpected end of input');
      }
      const c = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
      } else if (c === ']') {
        this.pos++;
        break;
      } else {
        throw new Error('expected comma or closing bracket');
      }
    }
    return new JsonArray(items);
  }

  private parseString(): string {
    this.pos++;
    let result = '';
    while (true) {
      if (this.pos >= this.text.length) {
        throw new Error('unterminated string');
      }
      const c = this.text.charAt(this.pos);
      if (c === '"') {
        this.pos++;
        return result;
      }
      if (c === '\\') {
        this.pos++;
        if (this.pos >= this.text.length) {
          throw new Error('unterminated escape');
        }
        const e = this.text.charAt(this.pos);
        if (e === '"') {
          result += '"';
          this.pos++;
        } else if (e === '\\') {
          result += '\\';
          this.pos++;
        } else if (e === '/') {
          result += '/';
          this.pos++;
        } else if (e === 'b') {
          result += '\b';
          this.pos++;
        } else if (e === 'f') {
          result += '\f';
          this.pos++;
        } else if (e === 'n') {
          result += '\n';
          this.pos++;
        } else if (e === 'r') {
          result += '\r';
          this.pos++;
        } else if (e === 't') {
          result += '\t';
          this.pos++;
        } else if (e === 'u') {
          this.pos++;
          if (this.pos + 4 > this.text.length) {
            throw new Error('bad unicode escape');
          }
          let code = 0;
          for (let k = 0; k < 4; k++) {
            const d = hexDigit(this.text.charAt(this.pos + k));
            if (d < 0) {
              throw new Error('bad unicode escape');
            }
            code = code * 16 + d;
          }
          result += String.fromCharCode(code);
          this.pos += 4;
        } else {
          throw new Error('bad escape');
        }
      } else if (c.charCodeAt(0) < 0x20) {
        throw new Error('control character in string');
      } else {
        result += c;
        this.pos++;
      }
    }
  }

  private parseNumber(): JsonNumber {
    const start = this.pos;
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '-') {
      this.pos++;
    }
    if (this.pos >= this.text.length) {
      throw new Error('bad number');
    }
    let c = this.text.charAt(this.pos);
    if (c === '0') {
      this.pos++;
    } else if (c >= '1' && c <= '9') {
      this.pos++;
      while (this.pos < this.text.length) {
        c = this.text.charAt(this.pos);
        if (c >= '0' && c <= '9') {
          this.pos++;
        } else {
          break;
        }
      }
    } else {
      throw new Error('bad number');
    }
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '.') {
      this.pos++;
      if (this.pos >= this.text.length) {
        throw new Error('bad number');
      }
      c = this.text.charAt(this.pos);
      if (!(c >= '0' && c <= '9')) {
        throw new Error('bad number');
      }
      while (this.pos < this.text.length) {
        c = this.text.charAt(this.pos);
        if (c >= '0' && c <= '9') {
          this.pos++;
        } else {
          break;
        }
      }
    }
    if (this.pos < this.text.length) {
      c = this.text.charAt(this.pos);
      if (c === 'e' || c === 'E') {
        this.pos++;
        if (this.pos < this.text.length) {
          c = this.text.charAt(this.pos);
          if (c === '+' || c === '-') {
            this.pos++;
          }
        }
        if (this.pos >= this.text.length) {
          throw new Error('bad number');
        }
        c = this.text.charAt(this.pos);
        if (!(c >= '0' && c <= '9')) {
          throw new Error('bad number');
        }
        while (this.pos < this.text.length) {
          c = this.text.charAt(this.pos);
          if (c >= '0' && c <= '9') {
            this.pos++;
          } else {
            break;
          }
        }
      }
    }
    const numText = this.text.substring(start, this.pos);
    return new JsonNumber(Number(numText));
  }
}

function addError(errors: FieldError[], path: string, message: string): void {
  const e: FieldError = { path: path, message: message };
  errors.push(e);
}

function findKey(obj: JsonObject, key: string): number {
  for (let i = 0; i < obj.keys.length; i++) {
    if (obj.keys[i] === key) {
      return i;
    }
  }
  return -1;
}

function isMissing(obj: JsonObject, index: number): boolean {
  if (index < 0) {
    return true;
  }
  return obj.values[index] instanceof JsonNull;
}

export function parseOrder(text: string): ParseResult {
  let root: JsonValue = new JsonNull();
  try {
    const parser = new JsonParser(text);
    root = parser.parse();
  } catch (e) {
    const errs: FieldError[] = [];
    addError(errs, '', 'invalid JSON');
    const res: ParseResult = { order: undefined, errors: errs };
    return res;
  }

  if (!(root instanceof JsonObject)) {
    const errs: FieldError[] = [];
    addError(errs, '', 'expected an object');
    const res: ParseResult = { order: undefined, errors: errs };
    return res;
  }

  const obj = root as JsonObject;
  const errors: FieldError[] = [];

  let idValue = '';
  const idIndex = findKey(obj, 'id');
  if (isMissing(obj, idIndex)) {
    addError(errors, 'id', 'required');
  } else {
    const v = obj.values[idIndex];
    if (!(v instanceof JsonString)) {
      addError(errors, 'id', 'expected a string');
    } else {
      const s = (v as JsonString).value;
      if (s === '') {
        addError(errors, 'id', 'must not be empty');
      } else {
        idValue = s;
      }
    }
  }

  let status: OrderStatus = OrderStatus.Draft;
  const statusIndex = findKey(obj, 'status');
  if (!isMissing(obj, statusIndex)) {
    const v = obj.values[statusIndex];
    if (!(v instanceof JsonString)) {
      addError(errors, 'status', 'expected one of draft, paid, shipped');
    } else {
      const s = (v as JsonString).value;
      if (s === 'draft') {
        status = OrderStatus.Draft;
      } else if (s === 'paid') {
        status = OrderStatus.Paid;
      } else if (s === 'shipped') {
        status = OrderStatus.Shipped;
      } else {
        addError(errors, 'status', 'expected one of draft, paid, shipped');
      }
    }
  }

  const lines: OrderLine[] = [];
  const linesIndex = findKey(obj, 'lines');
  if (isMissing(obj, linesIndex)) {
    addError(errors, 'lines', 'required');
  } else {
    const lv = obj.values[linesIndex];
    if (!(lv instanceof JsonArray)) {
      addError(errors, 'lines', 'expected an array');
    } else {
      const arr = lv as JsonArray;
      if (arr.items.length === 0) {
        addError(errors, 'lines', 'must not be empty');
      } else {
        for (let i = 0; i < arr.items.length; i++) {
          const item = arr.items[i];
          const base = 'lines[' + i.toString() + ']';
          if (!(item instanceof JsonObject)) {
            addError(errors, base, 'expected an object');
          } else {
            const lineObj = item as JsonObject;

            let sku = '';
            const skuIndex = findKey(lineObj, 'sku');
            if (isMissing(lineObj, skuIndex)) {
              addError(errors, base + '.sku', 'required');
            } else {
              const sv = lineObj.values[skuIndex];
              if (!(sv instanceof JsonString)) {
                addError(errors, base + '.sku', 'expected a string');
              } else {
                const s = (sv as JsonString).value;
                if (s === '') {
                  addError(errors, base + '.sku', 'must not be empty');
                } else {
                  sku = s;
                }
              }
            }

            let quantity = 0;
            const quantityIndex = findKey(lineObj, 'quantity');
            if (isMissing(lineObj, quantityIndex)) {
              addError(errors, base + '.quantity', 'required');
            } else {
              const qv = lineObj.values[quantityIndex];
              if (!(qv instanceof JsonNumber)) {
                addError(errors, base + '.quantity', 'expected a number');
              } else {
                const n = (qv as JsonNumber).value;
                if (Math.floor(n) !== n || n < 1) {
                  addError(errors, base + '.quantity', 'must be a whole number of 1 or more');
                } else {
                  quantity = n;
                }
              }
            }

            let unitPrice = 0;
            const priceIndex = findKey(lineObj, 'unitPrice');
            if (isMissing(lineObj, priceIndex)) {
              addError(errors, base + '.unitPrice', 'required');
            } else {
              const pv = lineObj.values[priceIndex];
              if (!(pv instanceof JsonNumber)) {
                addError(errors, base + '.unitPrice', 'expected a number');
              } else {
                const n = (pv as JsonNumber).value;
                if (n < 0) {
                  addError(errors, base + '.unitPrice', 'must be 0 or more');
                } else {
                  unitPrice = n;
                }
              }
            }

            for (let k = 0; k < lineObj.keys.length; k++) {
              const key = lineObj.keys[k];
              if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
                addError(errors, base + '.' + key, 'unknown field');
              }
            }

            lines.push(new OrderLine(sku, quantity, unitPrice));
          }
        }
      }
    }
  }

  for (let k = 0; k < obj.keys.length; k++) {
    const key = obj.keys[k];
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      addError(errors, key, 'unknown field');
    }
  }

  if (errors.length > 0) {
    const res: ParseResult = { order: undefined, errors: errors };
    return res;
  }

  const order: Order = { id: idValue, status: status, lines: lines };
  const res: ParseResult = { order: order, errors: errors };
  return res;
}

function pad2(value: number): string {
  return value < 10 ? `0${value}` : `${value}`;
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds < 0) {
    return '-' + formatDuration(-totalSeconds);
  }
  const hours: number = Math.floor(totalSeconds / 3600);
  const minutes: number = Math.floor((totalSeconds % 3600) / 60);
  const seconds: number = totalSeconds % 60;
  if (hours > 0) {
    return `${hours}h ${pad2(minutes)}m ${pad2(seconds)}s`;
  }
  if (minutes > 0) {
    return `${minutes}m ${pad2(seconds)}s`;
  }
  return `${seconds}s`;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }
  let negative: boolean = false;
  let body: string = text;
  if (body.charAt(0) === '-') {
    negative = true;
    body = body.substring(1);
  }
  if (body.length === 0) {
    return NaN;
  }
  const parts: string[] = body.split(' ');
  let total: number = 0;
  for (const part of parts) {
    if (part.length < 2) {
      return NaN;
    }
    const unit: string = part.charAt(part.length - 1);
    if (unit !== 'h' && unit !== 'm' && unit !== 's') {
      return NaN;
    }
    const numStr: string = part.substring(0, part.length - 1);
    if (!/^[0-9]+$/.test(numStr)) {
      return NaN;
    }
    const value: number = Number(numStr);
    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
  }
  return negative ? -total : total;
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  const step: number = Math.floor(size);
  let i: number = 0;
  while (i < items.length) {
    result.push(items.slice(i, i + step));
    i += step;
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const n: number = a.length < b.length ? a.length : b.length;
  for (let i: number = 0; i < n; i++) {
    const p: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(p);
  }
  return result;
}

