/**
 * Parses a URL query string into a Map.
 * - A single leading '?' is ignored.
 * - Parts are separated by '&'; empty parts are skipped.
 * - A part is split at its first '='; a part without '=' has an empty value.
 * - Keys/values are decoded: '+' -> ' ', %XX -> UTF-8 bytes.
 * - If a key or value contains a malformed escape, it is kept as written
 *   (only '+' is replaced by a space).
 * - Pairs with an empty key are ignored.
 * - The last value for a repeated key wins; the key keeps its first position.
 */

function isHexDigit(c: string): boolean {
  if (c.length !== 1) {
    return false;
  }
  const code: number = c.charCodeAt(0);
  return (code >= 48 && code <= 57) || (code >= 65 && code <= 70) || (code >= 97 && code <= 102);
}

function hexValue(c: string): number {
  const code: number = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  return code - 87;
}

function hasMalformedEscape(input: string): boolean {
  const n: number = input.length;
  let i: number = 0;
  while (i < n) {
    if (input.charAt(i) === '%') {
      if (i + 2 >= n) {
        return true;
      }
      if (!isHexDigit(input.charAt(i + 1)) || !isHexDigit(input.charAt(i + 2))) {
        return true;
      }
      i += 3;
    } else {
      i += 1;
    }
  }
  return false;
}

function bytesToUtf8(bytes: number[]): string {
  let out: string = '';
  let i: number = 0;
  const n: number = bytes.length;
  while (i < n) {
    const b: number = bytes[i];
    if (b < 0x80) {
      out += String.fromCharCode(b);
      i += 1;
      continue;
    }
    let need: number = 0;
    let cp: number = 0;
    let minCp: number = 0;
    if (b >= 0xC2 && b <= 0xDF) {
      need = 1;
      cp = b & 0x1F;
      minCp = 0x80;
    } else if (b >= 0xE0 && b <= 0xEF) {
      need = 2;
      cp = b & 0x0F;
      minCp = 0x800;
    } else if (b >= 0xF0 && b <= 0xF4) {
      need = 3;
      cp = b & 0x07;
      minCp = 0x10000;
    } else {
      out += '\uFFFD';
      i += 1;
      continue;
    }
    if (i + need >= n) {
      out += '\uFFFD';
      i += 1;
      continue;
    }
    let ok: boolean = true;
    for (let k: number = 1; k <= need; k++) {
      const cb: number = bytes[i + k];
      if (cb < 0x80 || cb > 0xBF) {
        ok = false;
        break;
      }
      cp = (cp << 6) | (cb & 0x3F);
    }
    if (!ok || cp < minCp || cp > 0x10FFFF || (cp >= 0xD800 && cp <= 0xDFFF)) {
      out += '\uFFFD';
      i += 1;
      continue;
    }
    if (cp > 0xFFFF) {
      const v: number = cp - 0x10000;
      out += String.fromCharCode(0xD800 + (v >> 10));
      out += String.fromCharCode(0xDC00 + (v & 0x3FF));
    } else {
      out += String.fromCharCode(cp);
    }
    i += need + 1;
  }
  return out;
}

function decodeComponent(input: string): string {
  if (hasMalformedEscape(input)) {
    // Keep as written; only '+' becomes a space.
    return input.split('+').join(' ');
  }
  let out: string = '';
  let bytes: number[] = [];
  const n: number = input.length;
  let i: number = 0;
  while (i < n) {
    const c: string = input.charAt(i);
    if (c === '%') {
      const hi: number = hexValue(input.charAt(i + 1));
      const lo: number = hexValue(input.charAt(i + 2));
      bytes.push(hi * 16 + lo);
      i += 3;
    } else {
      if (bytes.length > 0) {
        out += bytesToUtf8(bytes);
        bytes = [];
      }
      out += (c === '+') ? ' ' : c;
      i += 1;
    }
  }
  if (bytes.length > 0) {
    out += bytesToUtf8(bytes);
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }
  const parts: string[] = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq: number = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key: string = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value: string = decodeComponent(rawValue);
    // Setting an existing key keeps its original insertion position.
    result.set(key, value);
  }
  return result;
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
    this.name = 'RetryError';
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const maxAttempts: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('No attempts made');

  for (let i: number = 0; i < maxAttempts; i++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(maxAttempts, lastError);
}

