/**
 * A least-recently-used cache with a fixed capacity.
 *
 * Keys are compared with `Map` semantics (SameValueZero): the number `1` and the
 * string `'1'` are distinct keys, and two objects are the same key only when they
 * are the very same object reference.
 */

class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private count: number = 0;
  private map: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  // head is the least recently used node, tail is the most recently used node.
  private head: LruNode<K, V> | null = null;
  private tail: LruNode<K, V> | null = null;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  get size(): number {
    return this.count;
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.map.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToTail(existing);
      return;
    }

    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.map.set(key, node);
    this.appendToTail(node);
    this.count = this.count + 1;

    if (this.count > this.capacity) {
      const oldest: LruNode<K, V> | null = this.head;
      if (oldest !== null) {
        this.removeNode(oldest);
        this.map.delete(oldest.key);
        this.count = this.count - 1;
      }
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.map.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToTail(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | null = this.head;
    while (current !== null) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  private appendToTail(node: LruNode<K, V>): void {
    node.prev = this.tail;
    node.next = null;
    if (this.tail !== null) {
      this.tail.next = node;
    } else {
      this.head = node;
    }
    this.tail = node;
  }

  private removeNode(node: LruNode<K, V>): void {
    const before: LruNode<K, V> | null = node.prev;
    const after: LruNode<K, V> | null = node.next;

    if (before !== null) {
      before.next = after;
    } else {
      this.head = after;
    }

    if (after !== null) {
      after.prev = before;
    } else {
      this.tail = before;
    }

    node.prev = null;
    node.next = null;
  }

  private moveToTail(node: LruNode<K, V>): void {
    if (this.tail === node) {
      return;
    }
    this.removeNode(node);
    this.appendToTail(node);
  }
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

interface Step {
  name: string;
  step: Transform;
}

export class Pipeline {
  private steps: Step[] = [];

  add(name: string, step: Transform): Pipeline {
    const entry: Step = { name: name, step: step };
    this.steps.push(entry);
    return this;
  }

  run(text: string): string {
    let result: string = text;
    for (const entry of this.steps) {
      result = entry.step(result);
    }
    return result;
  }

  names(): string[] {
    const out: string[] = [];
    for (const entry of this.steps) {
      out.push(entry.name);
    }
    return out;
  }

  toFunction(): Transform {
    return (text: string): string => this.run(text);
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

