/**
 * The seven days of the week, running from Monday to Sunday.
 */
export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

/**
 * An opening rule: the place is open on `day` from `openHour` up to,
 * but not including, `closeHour`.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Tells whether at least one rule covers the given day and hour.
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the first day after `day` that has at least one rule, wrapping
 * around from Sunday to Monday. `day` itself is only returned when it is
 * the sole day with a rule (one week later). Returns `undefined` when no
 * day has a rule at all.
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  for (let offset = 1; offset <= 7; offset++) {
    const candidate: Weekday = ((day + offset) % 7) as Weekday;
    for (const rule of rules) {
      if (rule.day === candidate) {
        return candidate;
      }
    }
  }
  return undefined;
}

