const DOMAIN: number = 0x0000;
const TAG: string = 'SignInPage';
const MIN_PASSWORD_LENGTH: number = 8;

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isEmailValid(value: string): boolean {
    const atIndex: number = value.indexOf('@');
    if (atIndex <= 0) {
      return false; // no '@' or nothing before it
    }
    if (value.indexOf('@', atIndex + 1) !== -1) {
      return false; // more than one '@'
    }
    const domain: string = value.substring(atIndex + 1);
    const dotIndex: number = domain.indexOf('.');
    if (dotIndex <= 0) {
      return false; // no '.' or nothing between '@' and '.'
    }
    if (dotIndex === domain.length - 1) {
      return false; // nothing after the '.'
    }
    return true;
  }

  private isPasswordValid(value: string): boolean {
    return value.length >= MIN_PASSWORD_LENGTH;
  }

  private isEmailInvalid(): boolean {
    return this.email.length > 0 && !this.isEmailValid(this.email);
  }

  private isPasswordInvalid(): boolean {
    return this.password.length > 0 && !this.isPasswordValid(this.password);
  }

  private canSubmit(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  build() {
    Column({ space: 8 }) {
      Text('Sign in')
        .fontSize(26)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 16 })

      TextInput({ placeholder: 'Email', text: this.email })
        .type(InputType.Email)
        .width('100%')
        .height(48)
        .onChange((value: string) => {
          this.email = value;
        })

      if (this.isEmailInvalid()) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
          .textAlign(TextAlign.Start)
      }

      TextInput({ placeholder: 'Password', text: this.password })
        .type(InputType.Password)
        .width('100%')
        .height(48)
        .margin({ top: 8 })
        .onChange((value: string) => {
          this.password = value;
        })

      if (this.isPasswordInvalid()) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
          .textAlign(TextAlign.Start)
      }

      Button('Sign in')
        .width('100%')
        .height(44)
        .margin({ top: 24 })
        .enabled(this.canSubmit())
        .onClick(() => {
          hilog.info(DOMAIN, TAG, 'Sign in tapped for %{public}s', this.email);
        })
    }
    .width('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Start)
  }
}

