export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0
  const abs: number = negative ? -totalSeconds : totalSeconds
  const s: number = abs % 60
  const m: number = Math.floor(abs / 60) % 60
  const h: number = Math.floor(abs / 3600)

  const ss: string = s < 10 ? '0' + s.toString() : s.toString()
  const mm: string = m < 10 ? '0' + m.toString() : m.toString()

  let body: string = ''
  if (h > 0) {
    body = h.toString() + 'h ' + mm + 'm ' + ss + 's'
  } else if (m > 0) {
    body = m.toString() + 'm ' + ss + 's'
  } else {
    body = s.toString() + 's'
  }

  return negative ? '-' + body : body
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN
  }

  const parts: string[] = text.split(' ')
  let total: number = 0
  let negative: boolean = false

  for (let i = 0; i < parts.length; i++) {
    let part: string = parts[i]
    if (part.length === 0) {
      return NaN
    }

    if (part[0] === '-') {
      if (i !== 0) {
        return NaN
      }
      negative = true
      part = part.substring(1)
      if (part.length === 0) {
        return NaN
      }
    }

    const unit: string = part[part.length - 1]
    if (unit !== 'h' && unit !== 'm' && unit !== 's') {
      return NaN
    }

    const digits: string = part.substring(0, part.length - 1)
    if (digits.length === 0) {
      return NaN
    }

    for (let j = 0; j < digits.length; j++) {
      const c: number = digits.charCodeAt(j)
      if (c < 48 || c > 57) {
        return NaN
      }
    }

    const value: number = Number(digits)
    const multiplier: number = unit === 'h' ? 3600 : (unit === 'm' ? 60 : 1)
    total += value * multiplier
  }

  return negative ? -total : total
}

