export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    let eventListeners = this.listeners.get(event);
    if (eventListeners === undefined) {
      eventListeners = [];
      this.listeners.set(event, eventListeners);
    }
    if (eventListeners.indexOf(listener) === -1) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const eventListeners = this.listeners.get(event);
    if (eventListeners !== undefined) {
      const index = eventListeners.indexOf(listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    }
  }

  emit(event: string, payload: T): number {
    const eventListeners = this.listeners.get(event);
    if (eventListeners === undefined) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = [];
    for (let i = 0; i < eventListeners.length; i++) {
      snapshot.push(eventListeners[i]);
    }
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const eventListeners = this.listeners.get(event);
    if (eventListeners === undefined) {
      return 0;
    }
    return eventListeners.length;
  }
}

