export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type FieldName = 'text' | 'cursor' | 'bold';
type FieldValue = string | number | boolean;
type Listener = (value: FieldValue, previous: FieldValue) => void;

interface ListenerEntry {
  field: FieldName;
  fn: Listener;
  active: boolean;
}

export class EditorStore {
  private _text: string;
  private _cursor: number;
  private _bold: boolean;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private _historyLimit: number;
  private listenerEntries: ListenerEntry[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this._text = initial.text;
    this._cursor = initial.cursor;
    this._bold = initial.bold;
    this._historyLimit = Math.max(1, Math.floor(historyLimit));
  }

  get state(): EditorState {
    return { text: this._text, cursor: this._cursor, bold: this._bold };
  }

  private snapshot(): EditorState {
    return { text: this._text, cursor: this._cursor, bold: this._bold };
  }

  private setFrom(s: EditorState): void {
    this._text = s.text;
    this._cursor = s.cursor;
    this._bold = s.bold;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next: EditorState = this.snapshot();
    let changed = false;
    if (patch.text !== undefined && patch.text !== next.text) {
      next.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined && patch.cursor !== next.cursor) {
      next.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined && patch.bold !== next.bold) {
      next.bold = patch.bold;
      changed = true;
    }
    if (!changed) {
      return false;
    }
    this.commit(next);
    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = this.snapshot();
    run(draft);
    return this.apply(draft);
  }

  private commit(next: EditorState): void {
    const prev: EditorState = this.snapshot();
    this.pushUndo(prev);
    this.redoStack = [];
    this.setFrom(next);
    this.notify(prev, next);
  }

  private pushUndo(s: EditorState): void {
    this.undoStack.push(s);
    while (this.undoStack.length > this._historyLimit) {
      this.undoStack.shift();
    }
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const prev: EditorState = this.snapshot();
    const target: EditorState = this.undoStack.pop()!;
    this.redoStack.push(prev);
    this.setFrom(target);
    this.notify(prev, target);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const prev: EditorState = this.snapshot();
    const target: EditorState = this.redoStack.pop()!;
    this.undoStack.push(prev);
    while (this.undoStack.length > this._historyLimit) {
      this.undoStack.shift();
    }
    this.setFrom(target);
    this.notify(prev, target);
    return true;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  watch(field: string, listener: Listener): () => void {
    if (field !== 'text' && field !== 'cursor' && field !== 'bold') {
      return () => {};
    }
    const entry: ListenerEntry = { field: field as FieldName, fn: listener, active: true };
    this.listenerEntries.push(entry);
    return () => {
      if (!entry.active) {
        return;
      }
      entry.active = false;
    };
  }

  private notify(prev: EditorState, next: EditorState): void {
    const snapshot: ListenerEntry[] = [];
    for (const e of this.listenerEntries) {
      if (e.active) {
        snapshot.push(e);
      }
    }
    for (const entry of snapshot) {
      if (!entry.active) {
        continue;
      }
      const f: FieldName = entry.field;
      const oldValue: FieldValue = prev[f];
      const newValue: FieldValue = next[f];
      if (oldValue !== newValue) {
        entry.fn(newValue, oldValue);
      }
    }
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    return [];
  }

  if (!Array.isArray(parsed)) {
    return [];
  }

  let arr = parsed as Object[];
  let result: User[] = [];

  for (let i = 0; i < arr.length; i++) {
    let item = arr[i];
    if (typeof item !== 'object' || item === null || Array.isArray(item)) {
      continue;
    }
    let record = item as Record<string, Object>;
    if ('id' in record && 'name' in record && 'email' in record) {
      let id = record['id'];
      let name = record['name'];
      let email = record['email'];
      if (typeof id === 'number' && Number.isInteger(id) &&
          typeof name === 'string' && name.length > 0 &&
          typeof email === 'string' && email.includes('@')) {
        result.push({ id: id, name: name, email: email });
      }
    }
  }

  return result;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

interface StepInfo {
  name: string;
  step: Transform;
}

export class Pipeline {
  private steps: StepInfo[] = [];

  add(name: string, step: Transform): Pipeline {
    const newStep: StepInfo = { name: name, step: step };
    this.steps.push(newStep);
    return this;
  }

  run(text: string): string {
    let current: string = text;
    for (const item of this.steps) {
      current = item.step(current);
    }
    return current;
  }

  names(): string[] {
    return this.steps.map((item: StepInfo): string => {
      return item.name;
    });
  }

  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let current: string = text;
    for (const step of steps) {
      current = step(current);
    }
    return current;
  };
}

