@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isValidEmail(email: string): boolean {
    const firstAt: number = email.indexOf('@');
    // Needs an '@' with at least one character before it.
    if (firstAt <= 0) {
      return false;
    }
    // Exactly one '@'.
    if (email.lastIndexOf('@') !== firstAt) {
      return false;
    }
    const domain: string = email.substring(firstAt + 1);
    const dotIndex: number = domain.indexOf('.');
    // Needs a '.' with at least one character before it...
    if (dotIndex <= 0) {
      return false;
    }
    // ...and at least one character after it.
    return dotIndex < domain.length - 1;
  }

  private isValidPassword(password: string): boolean {
    return password.length >= 8;
  }

  private canSubmit(): boolean {
    return this.isValidEmail(this.email) && this.isValidPassword(this.password);
  }

  build() {
    Column({ space: 24 }) {
      Column({ space: 4 }) {
        TextInput({ placeholder: 'Email' })
          .type(InputType.Email)
          .width('100%')
          .onChange((value: string) => {
            this.email = value;
          })
        if (this.email.length > 0 && !this.isValidEmail(this.email)) {
          Text('Enter a valid email address')
            .fontSize(12)
            .fontColor(Color.Red)
            .width('100%')
        }
      }
      .width('100%')

      Column({ space: 4 }) {
        TextInput({ placeholder: 'Password' })
          .type(InputType.Password)
          .width('100%')
          .onChange((value: string) => {
            this.password = value;
          })
        if (this.password.length > 0 && !this.isValidPassword(this.password)) {
          Text('Password must be at least 8 characters')
            .fontSize(12)
            .fontColor(Color.Red)
            .width('100%')
        }
      }
      .width('100%')

      Button('Sign in')
        .width('100%')
        .enabled(this.canSubmit())
        .onClick(() => {
          hilog.info(0x0000, 'SignIn', 'Sign in submitted, email=%{public}s', this.email);
        })
    }
    .justifyContent(FlexAlign.Center)
    .padding(24)
    .width('100%')
    .height('100%')
  }
}

/*
 * solution.ets
 *
 * Self-contained JSON reader that extracts valid `User` records from a JSON text.
 * No imports are used: a small JSON parser is implemented locally so that the
 * code stays fully typed (no `any` / `unknown`) and never throws to the caller.
 */

export interface User {
  id: number;
  name: string;
  email: string;
}

/* ------------------------------------------------------------------ */
/* Minimal JSON value model                                            */
/* ------------------------------------------------------------------ */

class JsonValue {
}

class JsonNull extends JsonValue {
}

class JsonBool extends JsonValue {
  value: boolean = false;

  constructor(value: boolean) {
    super();
    this.value = value;
  }
}

class JsonNumber extends JsonValue {
  value: number = 0;

  constructor(value: number) {
    super();
    this.value = value;
  }
}

class JsonString extends JsonValue {
  value: string = '';

  constructor(value: string) {
    super();
    this.value = value;
  }
}

class JsonArray extends JsonValue {
  items: JsonValue[] = [];
}

class JsonObject extends JsonValue {
  keys: string[] = [];
  values: JsonValue[] = [];

  // Returns the last value stored under `key`, or null when the key is absent.
  get(key: string): JsonValue | null {
    for (let i = this.keys.length - 1; i >= 0; i--) {
      if (this.keys[i] === key) {
        return this.values[i];
      }
    }
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* Character helpers                                                   */
/* ------------------------------------------------------------------ */

function isDigitChar(c: string): boolean {
  const code: number = c.charCodeAt(0);
  return code >= 48 && code <= 57;
}

function hexValue(c: string): number {
  const code: number = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  return -1;
}

/* ------------------------------------------------------------------ */
/* JSON parser                                                         */
/* ------------------------------------------------------------------ */

class JsonParser {
  private text: string = '';
  private pos: number = 0;

  constructor(text: string) {
    this.text = text;
  }

  parseDocument(): JsonValue {
    this.pos = 0;
    this.skipWhitespace();
    const value: JsonValue = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      throw new Error('Unexpected trailing characters');
    }
    return value;
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const c: string = this.text.charAt(this.pos);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.pos = this.pos + 1;
      } else {
        break;
      }
    }
  }

  private parseValue(): JsonValue {
    if (this.pos >= this.text.length) {
      throw new Error('Unexpected end of input');
    }
    const c: string = this.text.charAt(this.pos);
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      return new JsonString(this.parseString());
    }
    if (c === 't') {
      this.expectLiteral('true');
      return new JsonBool(true);
    }
    if (c === 'f') {
      this.expectLiteral('false');
      return new JsonBool(false);
    }
    if (c === 'n') {
      this.expectLiteral('null');
      return new JsonNull();
    }
    return new JsonNumber(this.parseNumber());
  }

  private expectLiteral(literal: string): void {
    if (this.pos + literal.length > this.text.length) {
      throw new Error('Invalid literal');
    }
    const part: string = this.text.substring(this.pos, this.pos + literal.length);
    if (part !== literal) {
      throw new Error('Invalid literal');
    }
    this.pos = this.pos + literal.length;
  }

  private parseString(): string {
    // The current character is the opening quote.
    this.pos = this.pos + 1;
    let result: string = '';
    while (true) {
      if (this.pos >= this.text.length) {
        throw new Error('Unterminated string');
      }
      const c: string = this.text.charAt(this.pos);
      if (c === '"') {
        this.pos = this.pos + 1;
        return result;
      }
      if (c === '\\') {
        this.pos = this.pos + 1;
        if (this.pos >= this.text.length) {
          throw new Error('Unterminated escape sequence');
        }
        const e: string = this.text.charAt(this.pos);
        this.pos = this.pos + 1;
        if (e === '"') {
          result = result + '"';
        } else if (e === '\\') {
          result = result + '\\';
        } else if (e === '/') {
          result = result + '/';
        } else if (e === 'b') {
          result = result + '\b';
        } else if (e === 'f') {
          result = result + '\f';
        } else if (e === 'n') {
          result = result + '\n';
        } else if (e === 'r') {
          result = result + '\r';
        } else if (e === 't') {
          result = result + '\t';
        } else if (e === 'u') {
          if (this.pos + 4 > this.text.length) {
            throw new Error('Invalid unicode escape');
          }
          let code: number = 0;
          for (let i = 0; i < 4; i++) {
            const h: number = hexValue(this.text.charAt(this.pos + i));
            if (h < 0) {
              throw new Error('Invalid unicode escape');
            }
            code = code * 16 + h;
          }
          this.pos = this.pos + 4;
          result = result + String.fromCharCode(code);
        } else {
          throw new Error('Invalid escape sequence');
        }
      } else {
        result = result + c;
        this.pos = this.pos + 1;
      }
    }
  }

  private parseNumber(): number {
    const start: number = this.pos;
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '-') {
      this.pos = this.pos + 1;
    }
    if (this.pos >= this.text.length) {
      throw new Error('Invalid number');
    }
    let c: string = this.text.charAt(this.pos);
    if (c === '0') {
      this.pos = this.pos + 1;
    } else if (isDigitChar(c)) {
      while (this.pos < this.text.length && isDigitChar(this.text.charAt(this.pos))) {
        this.pos = this.pos + 1;
      }
    } else {
      throw new Error('Invalid number');
    }
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '.') {
      this.pos = this.pos + 1;
      let fractionDigits: number = 0;
      while (this.pos < this.text.length && isDigitChar(this.text.charAt(this.pos))) {
        this.pos = this.pos + 1;
        fractionDigits = fractionDigits + 1;
      }
      if (fractionDigits === 0) {
        throw new Error('Invalid number');
      }
    }
    if (this.pos < this.text.length) {
      c = this.text.charAt(this.pos);
      if (c === 'e' || c === 'E') {
        this.pos = this.pos + 1;
        if (this.pos < this.text.length) {
          c = this.text.charAt(this.pos);
          if (c === '+' || c === '-') {
            this.pos = this.pos + 1;
          }
        }
        let exponentDigits: number = 0;
        while (this.pos < this.text.length && isDigitChar(this.text.charAt(this.pos))) {
          this.pos = this.pos + 1;
          exponentDigits = exponentDigits + 1;
        }
        if (exponentDigits === 0) {
          throw new Error('Invalid number');
        }
      }
    }
    const raw: string = this.text.substring(start, this.pos);
    const value: number = Number(raw);
    if (Number.isNaN(value)) {
      throw new Error('Invalid number');
    }
    return value;
  }

  private parseObject(): JsonObject {
    this.pos = this.pos + 1; // consume '{'
    const obj: JsonObject = new JsonObject();
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '}') {
      this.pos = this.pos + 1;
      return obj;
    }
    while (true) {
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== '"') {
        throw new Error('Expected object key');
      }
      const key: string = this.parseString();
      this.skipWhitespace();
      if (this.pos >= this.text.length || this.text.charAt(this.pos) !== ':') {
        throw new Error('Expected colon');
      }
      this.pos = this.pos + 1;
      this.skipWhitespace();
      const value: JsonValue = this.parseValue();
      obj.keys.push(key);
      obj.values.push(value);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        throw new Error('Unterminated object');
      }
      const c: string = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos = this.pos + 1;
      } else if (c === '}') {
        this.pos = this.pos + 1;
        return obj;
      } else {
        throw new Error('Expected comma or closing brace');
      }
    }
  }

  private parseArray(): JsonArray {
    this.pos = this.pos + 1; // consume '['
    const arr: JsonArray = new JsonArray();
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === ']') {
      this.pos = this.pos + 1;
      return arr;
    }
    while (true) {
      this.skipWhitespace();
      const value: JsonValue = this.parseValue();
      arr.items.push(value);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        throw new Error('Unterminated array');
      }
      const c: string = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos = this.pos + 1;
      } else if (c === ']') {
        this.pos = this.pos + 1;
        return arr;
      } else {
        throw new Error('Expected comma or closing bracket');
      }
    }
  }
}

/* ------------------------------------------------------------------ */
/* Parsing entry point (never throws)                                  */
/* ------------------------------------------------------------------ */

function tryParseJson(text: string): JsonValue | null {
  try {
    const parser: JsonParser = new JsonParser(text);
    return parser.parseDocument();
  } catch (e) {
    return null;
  }
}

/* ------------------------------------------------------------------ */
/* Validation                                                          */
/* ------------------------------------------------------------------ */

function toUser(value: JsonValue): User | null {
  if (!(value instanceof JsonObject)) {
    return null;
  }
  const obj: JsonObject = value as JsonObject;

  const idValue: JsonValue | null = obj.get('id');
  const nameValue: JsonValue | null = obj.get('name');
  const emailValue: JsonValue | null = obj.get('email');

  if (idValue === null || nameValue === null || emailValue === null) {
    return null;
  }
  if (!(idValue instanceof JsonNumber)) {
    return null;
  }
  if (!(nameValue instanceof JsonString)) {
    return null;
  }
  if (!(emailValue instanceof JsonString)) {
    return null;
  }

  const id: number = (idValue as JsonNumber).value;
  const name: string = (nameValue as JsonString).value;
  const email: string = (emailValue as JsonString).value;

  if (!Number.isInteger(id)) {
    return null;
  }
  if (name.length === 0) {
    return null;
  }
  if (email.indexOf('@') < 0) {
    return null;
  }

  const user: User = {
    id: id,
    name: name,
    email: email
  };
  return user;
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */

export function parseUsers(json: string): User[] {
  const result: User[] = [];

  const root: JsonValue | null = tryParseJson(json);
  if (root === null) {
    return result;
  }
  if (!(root instanceof JsonArray)) {
    return result;
  }

  const arr: JsonArray = root as JsonArray;
  for (const item of arr.items) {
    const user: User | null = toUser(item);
    if (user !== null) {
      result.push(user);
    }
  }
  return result;
}

