import { http } from '@kit.NetworkKit';
import { BusinessError } from '@kit.BasicServicesKit';

class Item {
  id: number = 0;
  name: string = '';
}

@Entry
@Component
struct ItemListPage {
  @State isLoading: boolean = true;
  @State hasError: boolean = false;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.loadItems();
  }

  private loadItems(): void {
    const request: http.HttpRequest = http.createHttp();
    request.request('https://example.com/api/items', {
      method: http.RequestMethod.GET,
      expectDataType: http.HttpDataType.STRING,
      connectTimeout: 60000,
      readTimeout: 60000
    }, (err: BusinessError, data: http.HttpResponse) => {
      if (err) {
        this.isLoading = false;
        this.hasError = true;
        request.destroy();
        return;
      }
      if (data.responseCode !== http.ResponseCode.OK) {
        this.isLoading = false;
        this.hasError = true;
        request.destroy();
        return;
      }
      try {
        const body: string = data.result as string;
        const parsed: Item[] = JSON.parse(body) as Item[];
        this.items = parsed;
        this.isLoading = false;
      } catch (e) {
        this.isLoading = false;
        this.hasError = true;
      }
      request.destroy();
    });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(18)
          .fontColor(Color.Gray)
      } else if (this.hasError) {
        Text('Could not load the items')
          .fontSize(18)
          .fontColor(Color.Red)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .width('100%')
                .padding(12)
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .layoutWeight(1)
        .divider({ strokeWidth: 1, color: '#EEEEEE' })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';

const STORE_NAME: string = 'app_settings';
const KEY_NAME: string = 'saved_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State inputName: string = '';
  private store: preferences.Preferences | undefined = undefined;

  aboutToAppear(): void {
    this.loadSavedName();
  }

  onPageShow(): void {
    this.loadSavedName();
  }

  private async getStore(): Promise<preferences.Preferences | undefined> {
    if (this.store !== undefined) {
      return this.store;
    }
    const context: common.Context | undefined = this.getUIContext().getHostContext();
    if (context === undefined) {
      return undefined;
    }
    this.store = await preferences.getPreferences(context, STORE_NAME);
    return this.store;
  }

  private async loadSavedName(): Promise<void> {
    const store: preferences.Preferences | undefined = await this.getStore();
    if (store === undefined) {
      return;
    }
    const value: preferences.ValueType = await store.get(KEY_NAME, '');
    if (typeof value === 'string') {
      this.savedName = value;
    } else {
      this.savedName = '';
    }
  }

  private async saveName(): Promise<void> {
    const store: preferences.Preferences | undefined = await this.getStore();
    if (store === undefined) {
      return;
    }
    await store.put(KEY_NAME, this.inputName);
    await store.flush();
    this.savedName = this.inputName;
  }

  private displayText(): string {
    if (this.savedName.length === 0) {
      return 'No name saved';
    }
    return 'Hello, ' + this.savedName;
  }

  build() {
    Column({ space: 16 }) {
      Text(this.displayText())
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)
        .width('100%')

      TextInput({ placeholder: 'Enter your name' })
        .width('100%')
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('100%')
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .justifyContent(FlexAlign.Center)
  }
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  let secs: number = negative ? -totalSeconds : totalSeconds;

  const h: number = Math.floor(secs / 3600);
  secs = secs % 3600;
  const m: number = Math.floor(secs / 60);
  const s: number = secs % 60;

  let result: string = '';
  if (h > 0) {
    result = h.toString() + 'h ' + padTwo(m) + 'm ' + padTwo(s) + 's';
  } else if (m > 0) {
    result = m.toString() + 'm ' + padTwo(s) + 's';
  } else {
    result = s.toString() + 's';
  }

  if (negative) {
    result = '-' + result;
  }

  return result;
}

function padTwo(n: number): string {
  if (n < 10) {
    return '0' + n.toString();
  }
  return n.toString();
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let pos: number = 0;
  let negative: boolean = false;

  if (text.charAt(0) === '-') {
    negative = true;
    pos = 1;
  }

  const rest: string = text.substring(pos);
  if (rest.length === 0) {
    return NaN;
  }

  if (rest.charAt(0) === ' ' || rest.charAt(rest.length - 1) === ' ') {
    return NaN;
  }

  for (let i: number = 0; i < rest.length - 1; i++) {
    if (rest.charAt(i) === ' ' && rest.charAt(i + 1) === ' ') {
      return NaN;
    }
  }

  const parts: string[] = rest.split(' ');

  let totalSecs: number = 0;

  for (let i: number = 0; i < parts.length; i++) {
    const parsed: number = parsePart(parts[i]);
    if (isNaN(parsed)) {
      return NaN;
    }
    totalSecs += parsed;
  }

  if (negative) {
    totalSecs = -totalSecs;
  }

  return totalSecs;
}

function parsePart(part: string): number {
  if (part.length < 2) {
    return NaN;
  }

  const unit: string = part.charAt(part.length - 1);
  if (unit !== 'h' && unit !== 'm' && unit !== 's') {
    return NaN;
  }

  const numStr: string = part.substring(0, part.length - 1);
  if (numStr.length === 0) {
    return NaN;
  }

  for (let i: number = 0; i < numStr.length; i++) {
    const c: string = numStr.charAt(i);
    if (c < '0' || c > '9') {
      return NaN;
    }
  }

  const num: number = parseInt(numStr, 10);

  if (unit === 'h') {
    return num * 3600;
  }
  if (unit === 'm') {
    return num * 60;
  }
  return num;
}

