  private dataSource: LogDataSource = new LogDataSource(createInitialEntries());
  @State entryCount: number = 3000;
  @State isRefreshing: boolean = false;
  private nextId: number = 3001;

  private addNewEntries(): void {
    const added: LogEntry[] = [];
    // Newest (highest id) goes first so the list stays ordered highest id first.
    for (let i = 4; i >= 0; i--) {
      added.push(createEntry(this.nextId + i));
