export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = result.get(expense.category);
    if (current === undefined) {
      result.set(expense.category, expense.amount);
    } else {
      result.set(expense.category, current + expense.amount);
    }
  }
  return result;
}

