/**
 * Settings model and helpers.
 *
 * Self-contained: no imports.
 */

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

/**
 * Returns a fresh Settings object holding the default values.
 * A new object is created on every call.
 */
export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return settings;
}

/**
 * Merges user overrides on top of the defaults.
 *
 * A field is taken from `user` whenever it is present (even if its value is
 * `false`, `0` or `''`); otherwise the value from `defaults` is used.
 * Neither argument is modified.
 */
export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const theme: string = user.theme !== undefined ? user.theme : defaults.theme;
  const fontSize: number = user.fontSize !== undefined ? user.fontSize : defaults.fontSize;
  const notifications: boolean =
    user.notifications !== undefined ? user.notifications : defaults.notifications;
  const language: string = user.language !== undefined ? user.language : defaults.language;

  const merged: Settings = {
    theme: theme,
    fontSize: fontSize,
    notifications: notifications,
    language: language
  };
  return merged;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i: number = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const minPoint: Point = { x: minX, y: minY };
  const maxPoint: Point = { x: maxX, y: maxY };

  const result: Box = {
    min: minPoint,
    max: maxPoint,
    width: maxX - minX,
    height: maxY - minY
  };

  return result;
}

/**
 * A last-in, first-out (LIFO) stack that holds at most a fixed number of items.
 *
 * This file is self-contained and does not import anything.
 */
export class Stack<T> {
  private items: T[] = [];
  private readonly capacity: number;

  /**
   * Creates a stack that can hold at most `capacity` items.
   * @param capacity The largest number of items the stack can hold.
   */
  constructor(capacity: number) {
    this.capacity = capacity;
  }

  /**
   * Puts `item` on top of the stack.
   * @returns `true` if the item was added, `false` if the stack was full.
   */
  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes and returns the top item.
   * @returns The top item, or `undefined` if the stack is empty.
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it.
   * @returns The top item, or `undefined` if the stack is empty.
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * @returns How many items the stack currently holds.
   */
  size(): number {
    return this.items.length;
  }

  /**
   * @returns `true` if the stack holds no items.
   */
  isEmpty(): boolean {
    return this.items.length === 0;
  }

  /**
   * @returns `true` if the stack holds as many items as its capacity allows.
   */
  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /**
   * Removes every item from the stack.
   */
  clear(): void {
    this.items = [];
  }

  /**
   * Returns the items ordered from bottom to top.
   * The returned array is a new array; modifying it does not affect the stack.
   */
  toArray(): T[] {
    return this.items.slice();
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map<string, Array<Listener<T>>>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      arr = new Array<Listener<T>>();
      this.listeners.set(event, arr);
    }
    if (arr.indexOf(listener) === -1) {
      arr.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      return;
    }
    const index: number = arr.indexOf(listener);
    if (index !== -1) {
      arr.splice(index, 1);
    }
    if (arr.length === 0) {
      this.listeners.delete(event);
    }
  }

  emit(event: string, payload: T): number {
    const arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = arr.slice();
    let count: number = 0;
    for (const listener of snapshot) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const arr: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (arr === undefined) {
      return 0;
    }
    return arr.length;
  }
}

/**
 * Shape abstraction.
 *
 * `Shape` is an interface exposing a single `area()` operation. Any new kind of
 * shape only has to implement this interface; `area` and `totalArea` below work
 * with it without modification.
 */
export interface Shape {
  area(): number;
}

class Circle implements Shape {
  private radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle implements Shape {
  private width: number;
  private height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

class Triangle implements Shape {
  private base: number;
  private height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (let i = 0; i < shapes.length; i++) {
    sum += shapes[i].area();
  }
  return sum;
}

/**
 * Error thrown by {@link retry} when every attempt has failed.
 */
export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

/**
 * Calls `action` until it succeeds or until it has been called `attempts` times.
 * Calls are made one at a time, with no delay in between.
 */
export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const total: number = attempts < 1 ? 1 : Math.floor(attempts);
  let lastError: Error = new Error('unknown error');

  for (let i = 0; i < total; i++) {
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(total, lastError);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

/**
 * A simple generic pair holding two values.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements.
 * The final group may be shorter. Returns an empty array when
 * `items` is empty or `size` is less than 1.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1 || items.length === 0) {
    return result;
  }
  let index: number = 0;
  while (index < items.length) {
    const group: T[] = [];
    const end: number = Math.min(index + size, items.length);
    for (let i: number = index; i < end; i++) {
      group.push(items[i]);
    }
    result.push(group);
    index = end;
  }
  return result;
}

/**
 * Combines two arrays into an array of pairs, stopping at the
 * length of the shorter input.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i: number = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

const WEEK: Weekday[] = [
  Weekday.Monday,
  Weekday.Tuesday,
  Weekday.Wednesday,
  Weekday.Thursday,
  Weekday.Friday,
  Weekday.Saturday,
  Weekday.Sunday
];

function dayIndex(day: Weekday): number {
  switch (day) {
    case Weekday.Monday:
      return 0;
    case Weekday.Tuesday:
      return 1;
    case Weekday.Wednesday:
      return 2;
    case Weekday.Thursday:
      return 3;
    case Weekday.Friday:
      return 4;
    case Weekday.Saturday:
      return 5;
    case Weekday.Sunday:
      return 6;
    default:
      return 0;
  }
}

function hasRule(rules: OpeningRule[], day: Weekday): boolean {
  for (let i = 0; i < rules.length; i++) {
    if (rules[i].day === day) {
      return true;
    }
  }
  return false;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const start: number = dayIndex(day);
  for (let offset = 1; offset <= 7; offset++) {
    const candidate: Weekday = WEEK[(start + offset) % 7];
    if (hasRule(rules, candidate)) {
      return candidate;
    }
  }
  return undefined;
}

class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

/**
 * A cache that keeps at most `capacity` entries and evicts the least
 * recently used entry when it becomes full.
 *
 * Keys are compared the same way the built-in Map compares them, so `1` and
 * `'1'` are different keys and object keys are matched by identity.
 */
export class LruCache<K, V> {
  private readonly capacity: number;
  private readonly index: Map<K, LruNode<K, V>>;
  // Least recently used entry.
  private head: LruNode<K, V> | null = null;
  // Most recently used entry.
  private tail: LruNode<K, V> | null = null;
  private count: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.index = new Map<K, LruNode<K, V>>();
  }

  get size(): number {
    return this.count;
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.index.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToTail(existing);
      return;
    }
    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.index.set(key, node);
    this.appendToTail(node);
    this.count += 1;
    while (this.count > this.capacity) {
      const victim: LruNode<K, V> | null = this.head;
      if (victim === null) {
        break;
      }
      this.removeNode(victim);
      this.index.delete(victim.key);
      this.count -= 1;
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.index.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToTail(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.index.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | null = this.head;
    while (current !== null) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  private moveToTail(node: LruNode<K, V>): void {
    if (node === this.tail) {
      return;
    }
    this.removeNode(node);
    this.appendToTail(node);
  }

  private removeNode(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | null = node.prev;
    const next: LruNode<K, V> | null = node.next;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.head = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private appendToTail(node: LruNode<K, V>): void {
    node.prev = this.tail;
    node.next = null;
    if (this.tail !== null) {
      this.tail.next = node;
    } else {
      this.head = node;
    }
    this.tail = node;
  }
}

