class GroceryItem {
  id: number;
  name: string;
  bought: boolean;

  constructor(id: number, name: string, bought: boolean) {
    this.id = id;
    this.name = name;
    this.bought = bought;
  }
}

@Component
struct GroceryRow {
  @ObjectLink item: GroceryItem;
  onToggle: () => void = () => {};

