@Entry
@Component
struct Index {
  @State items: GroceryItem[] = [
    new GroceryItem(1, 'Milk', false),
    new GroceryItem(2, 'Bread', false),
    new GroceryItem(3, 'Eggs', false),
    new GroceryItem(4, 'Apples', false)
  ];
  @State newName: string = '';
  private nextId: number = 5;

  boughtCount(): number {
    let count: number = 0;
    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i].bought) {
        count++;
      }
    }
    return count;
  }

  toggleItem(id: number): void {
    for (let i = 0; i < this.items.length; i++) {
      if (this.items[i].id === id) {
        this.items[i].bought = !this.items[i].bought;
        break;
      }
    }
    // Refresh the array reference so the header text is recomputed.
    this.items = this.items.slice();
  }

  removeItem(id: number): void {
    this.items = this.items.filter((it: GroceryItem) => it.id !== id);
  }

  addItem(): void {
    const name: string = this.newName.trim();
    if (name.length === 0) {
      return;
    }
    this.items.push(new GroceryItem(this.nextId, name, false));
    this.nextId = this.nextId + 1;
    this.newName = '';
  }

  @Builder
  DeleteAction(item: GroceryItem) {
    Button('Delete')
      .type(ButtonType.Normal)
      .fontSize(16)
      .fontColor(Color.White)
      .backgroundColor('#D32F2F')
      .height('100%')
      .width(88)
      .borderRadius(0)
      .onClick(() => {
        this.removeItem(item.id);
      })
  }

  build() {
    Column() {
      Text(`${this.items.length} items, ${this.boughtCount()} bought`)
        .fontSize(16)
        .fontColor('#616161')
        .width('100%')
        .padding({ left: 16, right: 16, top: 16, bottom: 12 })
        .textAlign(TextAlign.Start)

      List() {
        ForEach(this.items, (item: GroceryItem) => {
          ListItem() {
            GroceryRow({
              item: item,
              onToggle: () => {
                this.toggleItem(item.id);
              }
            })
          }
          .swipeAction({
            end: {
              builder: () => {
                this.DeleteAction(item);
              },
              onAction: () => {
                this.removeItem(item.id);
              }
            }
          })
        }, (item: GroceryItem) => item.id.toString())
      }
      .width('100%')
      .layoutWeight(1)
      .divider({ strokeWidth: 1, color: '#EEEEEE' })

      Row() {
        TextInput({ placeholder: 'New item', text: this.newName })
          .layoutWeight(1)
          .height(44)
          .onChange((value: string) => {
            this.newName = value;
          })
        Button('Add')
          .height(44)
          .margin({ left: 8 })
          .onClick(() => {
            this.addItem();
          })
      }
      .width('100%')
      .padding(12)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

