export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

export class Pipeline {
  private stepNames: string[] = [];
  private stepFunctions: Transform[] = [];

  add(name: string, step: Transform): Pipeline {
    this.stepNames.push(name);
    this.stepFunctions.push(step);
    return this;
  }

  run(text: string): string {
    let result: string = text;
    for (let i = 0; i < this.stepFunctions.length; i++) {
      result = this.stepFunctions[i](result);
    }
    return result;
  }

  names(): string[] {
    const result: string[] = [];
    for (let i = 0; i < this.stepNames.length; i++) {
      result.push(this.stepNames[i]);
    }
    return result;
  }

  toFunction(): Transform {
    const self: Pipeline = this;
    return (text: string): string => {
      return self.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (let i = 0; i < steps.length; i++) {
      result = steps[i](result);
    }
    return result;
  };
}

/**
 * Parsing of user lists from JSON text.
 *
 * The file is self-contained: JSON parsing is implemented locally so that no
 * import of any kind is required.
 */

export interface User {
  id: number;
  name: string;
  email: string;
}

/* ------------------------------------------------------------------ */
/* Internal JSON value representation                                  */
/* ------------------------------------------------------------------ */

const KIND_NULL: number = 0;
const KIND_BOOLEAN: number = 1;
const KIND_NUMBER: number = 2;
const KIND_STRING: number = 3;
const KIND_ARRAY: number = 4;
const KIND_OBJECT: number = 5;

class JsonNode {
  kind: number = KIND_NULL;
  boolValue: boolean = false;
  numValue: number = 0;
  strValue: string = '';
  arrValue: JsonNode[] = [];
  objValue: Map<string, JsonNode> = new Map<string, JsonNode>();
}

/* ------------------------------------------------------------------ */
/* Recursive descent JSON parser                                       */
/* ------------------------------------------------------------------ */

class JsonParser {
  private text: string;
  private pos: number = 0;

  constructor(text: string) {
    this.text = text;
  }

  /**
   * Parses the whole document. Throws on malformed input.
   */
  parseDocument(): JsonNode {
    const value: JsonNode = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      throw new Error('Unexpected trailing content');
    }
    return value;
  }

  private peek(): string {
    if (this.pos >= this.text.length) {
      return '';
    }
    return this.text.charAt(this.pos);
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const c: string = this.text.charAt(this.pos);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.pos++;
      } else {
        break;
      }
    }
  }

  private isDigit(c: string): boolean {
    if (c.length !== 1) {
      return false;
    }
    const code: number = c.charCodeAt(0);
    return code >= 48 && code <= 57;
  }

  private isHexDigit(c: string): boolean {
    if (c.length !== 1) {
      return false;
    }
    const code: number = c.charCodeAt(0);
    if (code >= 48 && code <= 57) {
      return true;
    }
    if (code >= 65 && code <= 70) {
      return true;
    }
    return code >= 97 && code <= 102;
  }

  private parseValue(): JsonNode {
    this.skipWhitespace();
    const c: string = this.peek();
    if (c === '') {
      throw new Error('Unexpected end of input');
    }
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      const node: JsonNode = new JsonNode();
      node.kind = KIND_STRING;
      node.strValue = this.readString();
      return node;
    }
    if (c === 't') {
      this.expectLiteral('true');
      const node: JsonNode = new JsonNode();
      node.kind = KIND_BOOLEAN;
      node.boolValue = true;
      return node;
    }
    if (c === 'f') {
      this.expectLiteral('false');
      const node: JsonNode = new JsonNode();
      node.kind = KIND_BOOLEAN;
      node.boolValue = false;
      return node;
    }
    if (c === 'n') {
      this.expectLiteral('null');
      const node: JsonNode = new JsonNode();
      node.kind = KIND_NULL;
      return node;
    }
    if (c === '-' || this.isDigit(c)) {
      return this.parseNumber();
    }
    throw new Error('Unexpected character');
  }

  private expectLiteral(literal: string): void {
    const end: number = this.pos + literal.length;
    if (end > this.text.length) {
      throw new Error('Invalid literal');
    }
    if (this.text.substring(this.pos, end) !== literal) {
      throw new Error('Invalid literal');
    }
    this.pos = end;
  }

  private parseObject(): JsonNode {
    const node: JsonNode = new JsonNode();
    node.kind = KIND_OBJECT;
    this.pos++; // consume '{'
    this.skipWhitespace();
    if (this.peek() === '}') {
      this.pos++;
      return node;
    }
    while (true) {
      this.skipWhitespace();
      if (this.peek() !== '"') {
        throw new Error('Expected property name');
      }
      const key: string = this.readString();
      this.skipWhitespace();
      if (this.peek() !== ':') {
        throw new Error('Expected colon');
      }
      this.pos++;
      const value: JsonNode = this.parseValue();
      node.objValue.set(key, value);
      this.skipWhitespace();
      const c: string = this.peek();
      if (c === ',') {
        this.pos++;
        continue;
      }
      if (c === '}') {
        this.pos++;
        return node;
      }
      throw new Error('Expected , or }');
    }
  }

  private parseArray(): JsonNode {
    const node: JsonNode = new JsonNode();
    node.kind = KIND_ARRAY;
    this.pos++; // consume '['
    this.skipWhitespace();
    if (this.peek() === ']') {
      this.pos++;
      return node;
    }
    while (true) {
      const value: JsonNode = this.parseValue();
      node.arrValue.push(value);
      this.skipWhitespace();
      const c: string = this.peek();
      if (c === ',') {
        this.pos++;
        continue;
      }
      if (c === ']') {
        this.pos++;
        return node;
      }
      throw new Error('Expected , or ]');
    }
  }

  private parseNumber(): JsonNode {
    const start: number = this.pos;
    if (this.peek() === '-') {
      this.pos++;
    }
    if (!this.isDigit(this.peek())) {
      throw new Error('Invalid number');
    }
    while (this.isDigit(this.peek())) {
      this.pos++;
    }
    if (this.peek() === '.') {
      this.pos++;
      if (!this.isDigit(this.peek())) {
        throw new Error('Invalid number');
      }
      while (this.isDigit(this.peek())) {
        this.pos++;
      }
    }
    const expMarker: string = this.peek();
    if (expMarker === 'e' || expMarker === 'E') {
      this.pos++;
      const sign: string = this.peek();
      if (sign === '+' || sign === '-') {
        this.pos++;
      }
      if (!this.isDigit(this.peek())) {
        throw new Error('Invalid number');
      }
      while (this.isDigit(this.peek())) {
        this.pos++;
      }
    }
    const raw: string = this.text.substring(start, this.pos);
    const value: number = parseFloat(raw);
    if (value !== value) {
      throw new Error('Invalid number');
    }
    const node: JsonNode = new JsonNode();
    node.kind = KIND_NUMBER;
    node.numValue = value;
    return node;
  }

  private readString(): string {
    this.pos++; // consume opening quote
    let result: string = '';
    while (true) {
      if (this.pos >= this.text.length) {
        throw new Error('Unterminated string');
      }
      const c: string = this.text.charAt(this.pos);
      if (c === '"') {
        this.pos++;
        return result;
      }
      if (c === '\\') {
        this.pos++;
        const esc: string = this.peek();
        if (esc === '') {
          throw new Error('Unterminated string');
        }
        this.pos++;
        if (esc === '"') {
          result += '"';
        } else if (esc === '\\') {
          result += '\\';
        } else if (esc === '/') {
          result += '/';
        } else if (esc === 'b') {
          result += '\b';
        } else if (esc === 'f') {
          result += '\f';
        } else if (esc === 'n') {
          result += '\n';
        } else if (esc === 'r') {
          result += '\r';
        } else if (esc === 't') {
          result += '\t';
        } else if (esc === 'u') {
          const hex: string = this.text.substring(this.pos, this.pos + 4);
          if (hex.length !== 4) {
            throw new Error('Invalid unicode escape');
          }
          for (let i = 0; i < 4; i++) {
            if (!this.isHexDigit(hex.charAt(i))) {
              throw new Error('Invalid unicode escape');
            }
          }
          const code: number = parseInt(hex, 16);
          if (code !== code) {
            throw new Error('Invalid unicode escape');
          }
          result += String.fromCharCode(code);
          this.pos += 4;
        } else {
          throw new Error('Invalid escape sequence');
        }
        continue;
      }
      result += c;
      this.pos++;
    }
  }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

function parseDocumentSafe(text: string): JsonNode | null {
  try {
    const parser: JsonParser = new JsonParser(text);
    return parser.parseDocument();
  } catch (e) {
    return null;
  }
}

function isIntegerNumber(value: number): boolean {
  // NaN and +/-Infinity fail this check (NaN * 0 !== 0 and Infinity * 0 !== 0).
  if (value * 0 !== 0) {
    return false;
  }
  return Math.floor(value) === value;
}

/* ------------------------------------------------------------------ */
/* Public API                                                          */
/* ------------------------------------------------------------------ */

/**
 * Reads a JSON text and returns the valid user objects contained in it.
 * Never throws; returns an empty array for anything that is not a JSON array.
 */
export function parseUsers(json: string): User[] {
  const users: User[] = [];
  const root: JsonNode | null = parseDocumentSafe(json);
  if (root === null) {
    return users;
  }
  if (root.kind !== KIND_ARRAY) {
    return users;
  }
  const items: JsonNode[] = root.arrValue;
  for (let i = 0; i < items.length; i++) {
    const item: JsonNode = items[i];
    if (item.kind !== KIND_OBJECT) {
      continue;
    }
    const idNode: JsonNode | undefined = item.objValue.get('id');
    const nameNode: JsonNode | undefined = item.objValue.get('name');
    const emailNode: JsonNode | undefined = item.objValue.get('email');
    if (idNode === undefined || nameNode === undefined || emailNode === undefined) {
      continue;
    }
    if (idNode.kind !== KIND_NUMBER) {
      continue;
    }
    if (nameNode.kind !== KIND_STRING) {
      continue;
    }
    if (emailNode.kind !== KIND_STRING) {
      continue;
    }
    const id: number = idNode.numValue;
    if (!isIntegerNumber(id)) {
      continue;
    }
    const name: string = nameNode.strValue;
    if (name.length === 0) {
      continue;
    }
    const email: string = emailNode.strValue;
    if (email.indexOf('@') < 0) {
      continue;
    }
    const user: User = { id: id, name: name, email: email };
    users.push(user);
  }
  return users;
}

class TodoItem {
  id: number;
  text: string;

  constructor(id: number, text: string) {
    this.id = id;
    this.text = text;
  }
}

@Entry
@Component
struct TodoPage {
  @State todos: TodoItem[] = [];
  @State inputText: string = '';
  private nextId: number = 0;

  private addTodo(): void {
    const text: string = this.inputText.trim();
    if (text.length === 0) {
      return;
    }
    const item: TodoItem = new TodoItem(this.nextId, text);
    this.nextId += 1;
    // Reassign the array so the UI is notified about the change.
    this.todos = this.todos.concat(item);
    this.inputText = '';
  }

  private removeTodo(id: number): void {
    // Filter by the unique id, so only the tapped todo is removed,
    // even when several todos share the same text.
    this.todos = this.todos.filter((item: TodoItem) => item.id !== id);
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'New todo', text: this.inputText })
          .layoutWeight(1)
          .onChange((value: string) => {
            this.inputText = value;
          })
          .onSubmit((enterKey: EnterKeyType, event: SubmitEvent) => {
            this.addTodo();
          })

        Button('Add')
          .margin({ left: 8 })
          .onClick(() => {
            this.addTodo();
          })
      }
      .width('100%')
      .padding({ left: 16, right: 16, top: 12, bottom: 12 })

      List({ space: 2 }) {
        ForEach(this.todos, (item: TodoItem) => {
