import { hilog } from '@kit.PerformanceAnalysisKit';

const DOMAIN: number = 0x0000;
const TAG: string = 'SignInPage';

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isEmailValid(value: string): boolean {
    const atIndex: number = value.indexOf('@');
    // At least one character before the "@".
    if (atIndex <= 0) {
      return false;
    }
    // Exactly one "@".
    if (value.indexOf('@', atIndex + 1) !== -1) {
      return false;
    }
    const domain: string = value.substring(atIndex + 1);
    const dotIndex: number = domain.lastIndexOf('.');
    // At least one character before the "." and at least one after it.
    if (dotIndex <= 0) {
      return false;
    }
    if (dotIndex === domain.length - 1) {
      return false;
    }
    return true;
  }

  private isPasswordValid(value: string): boolean {
    return value.length >= 8;
  }

  private showEmailError(): boolean {
    return this.email.length > 0 && !this.isEmailValid(this.email);
  }

  private showPasswordError(): boolean {
    return this.password.length > 0 && !this.isPasswordValid(this.password);
  }

  private canSubmit(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  private onSignIn(): void {
    hilog.info(DOMAIN, TAG, 'Sign in tapped for %{public}s', this.email);
  }

  build() {
    Column({ space: 12 }) {
      TextInput({ placeholder: 'Email' })
        .type(InputType.Email)
        .width('100%')
        .height(48)
        .onChange((value: string) => {
          this.email = value;
        })

      if (this.showEmailError()) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
      }

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .width('100%')
        .height(48)
        .onChange((value: string) => {
          this.password = value;
        })

      if (this.showPasswordError()) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
      }

      Button('Sign in')
        .width('100%')
        .height(48)
        .enabled(this.canSubmit())
        .onClick(() => {
          this.onSignIn();
        })
    }
    .width('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Start)
  }
}

