import { http } from '@kit.NetworkKit';
import { BusinessError } from '@kit.BasicServicesKit';

interface Item {
  id: number;
  name: string;
}

@Entry
@Component
struct Index {
  @State items: Item[] = [];
  @State loading: boolean = true;
  @State failed: boolean = false;

  aboutToAppear(): void {
    this.loadItems();
  }

  private loadItems(): void {
    this.loading = true;
    this.failed = false;
    this.items = [];

    const request = http.createHttp();
    request.request(
      'https://example.com/api/items',
      {
        method: http.RequestMethod.GET,
        expectDataType: http.HttpDataType.STRING,
        connectTimeout: 10000,
        readTimeout: 10000
      },
      (err: BusinessError, data: http.HttpResponse) => {
        if (err) {
          this.failed = true;
          this.loading = false;
          request.destroy();
          return;
        }

        if (data.responseCode !== http.ResponseCode.OK) {
          this.failed = true;
          this.loading = false;
          request.destroy();
          return;
        }

        try {
          if (typeof data.result !== 'string') {
            this.failed = true;
            this.loading = false;
            request.destroy();
            return;
          }
          const body: string = data.result as string;
          const parsed: Item[] = JSON.parse(body) as Item[];
          this.items = parsed;
          this.loading = false;
        } catch (e) {
          this.failed = true;
          this.loading = false;
        }
        request.destroy();
      }
    );
  }

  build() {
    Column() {
      if (this.loading) {
        Text('Loading...')
          .fontSize(18)
          .fontColor('#333333')
      } else if (this.failed) {
        Text('Could not load the items')
          .fontSize(18)
          .fontColor('#333333')
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .width('100%')
                .padding({ left: 16, right: 16, top: 12, bottom: 12 })
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .divider({ strokeWidth: 1, color: '#EEEEEE' })
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

@Entry
@Component
struct Index {
  // One flag per tile: true means the tile is selected.
  @State selected: boolean[] = [
    false, false, false, false,
    false, false, false, false,
    false, false, false, false
  ];

  private countSelected(): number {
    let count: number = 0;
    for (let i: number = 0; i < this.selected.length; i++) {
      if (this.selected[i]) {
        count++;
      }
    }
    return count;
  }

  private toggle(index: number): void {
    // Reassign the array so the state change is observed.
    this.selected = this.selected.map((value: boolean, i: number) => {
