export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type FieldValue = string | number | boolean;

interface Watcher {
  field: string;
  listener: (value: FieldValue, previous: FieldValue) => void;
  active: boolean;
}

function copyState(source: EditorState): EditorState {
  const result: EditorState = {
    text: source.text,
    cursor: source.cursor,
    bold: source.bold
  };
  return result;
}

function sameState(a: EditorState, b: EditorState): boolean {
  return a.text === b.text && a.cursor === b.cursor && a.bold === b.bold;
}

export class EditorStore {
  private current: EditorState;
  private historyLimit: number;
  private past: EditorState[] = [];
  private future: EditorState[] = [];
  private watchers: Watcher[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.current = copyState(initial);
    this.historyLimit = historyLimit >= 1 ? Math.floor(historyLimit) : 1;
  }

  get state(): EditorState {
    return copyState(this.current);
  }

  get canUndo(): boolean {
    return this.past.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next: EditorState = copyState(this.current);
    if (patch.text !== undefined) {
      next.text = patch.text;
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold;
    }
    return this.commit(next);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = copyState(this.current);
    run(draft);
    const patch: Partial<EditorState> = {
      text: draft.text,
      cursor: draft.cursor,
      bold: draft.bold
    };
    return this.apply(patch);
  }

  undo(): boolean {
    if (this.past.length === 0) {
      return false;
    }
    const before: EditorState = this.current;
    const restored: EditorState | undefined = this.past.pop();
    if (restored === undefined) {
      return false;
    }
    this.future.push(copyState(before));
    this.current = copyState(restored);
    this.notify(before, this.current);
    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }
    const before: EditorState = this.current;
    const reapplied: EditorState | undefined = this.future.pop();
    if (reapplied === undefined) {
      return false;
    }
    this.past.push(copyState(before));
    while (this.past.length > this.historyLimit) {
      this.past.shift();
    }
    this.current = copyState(reapplied);
    this.notify(before, this.current);
    return true;
  }

  watch(field: string,
    listener: (value: FieldValue, previous: FieldValue) => void): () => void {
    const entry: Watcher = {
      field: field,
      listener: listener,
      active: true
    };
    this.watchers.push(entry);
    const remove: () => void = () => {
      entry.active = false;
      const index: number = this.watchers.indexOf(entry);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
    return remove;
  }

  private commit(next: EditorState): boolean {
    if (sameState(this.current, next)) {
      return false;
    }
    const before: EditorState = this.current;
    this.past.push(copyState(before));
    while (this.past.length > this.historyLimit) {
      this.past.shift();
    }
    this.future = [];
    this.current = copyState(next);
    this.notify(before, this.current);
    return true;
  }

  private notify(before: EditorState, after: EditorState): void {
    const snapshot: Watcher[] = this.watchers.slice();
    for (const watcher of snapshot) {
      if (!watcher.active) {
        continue;
      }
      let changed: boolean = false;
      let newValue: FieldValue = '';
      let oldValue: FieldValue = '';
      if (watcher.field === 'text') {
        changed = before.text !== after.text;
        newValue = after.text;
        oldValue = before.text;
      } else if (watcher.field === 'cursor') {
        changed = before.cursor !== after.cursor;
        newValue = after.cursor;
        oldValue = before.cursor;
      } else if (watcher.field === 'bold') {
        changed = before.bold !== after.bold;
        newValue = after.bold;
        oldValue = before.bold;
      }
      if (changed) {
        watcher.listener(newValue, oldValue);
      }
    }
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.name = 'MissingDependencyError';
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.name = 'CycleError';
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private keys: string[];
  private keySet: Set<string>;
  private taskOrder: string[];
  private taskLayers: string[][];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;

    const keys = Object.keys(spec);
    const keySet = new Set<string>();
    for (const key of keys) {
      keySet.add(key);
    }

    this.keys = keys;
    this.keySet = keySet;

    for (const task of keys) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!keySet.has(dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    this.taskOrder = this.computeOrder();
    this.taskLayers = this.computeLayers();
  }

  order(): string[] {
    return this.taskOrder.slice();
  }

  layers(): string[][] {
    const result: string[][] = [];
    for (const layer of this.taskLayers) {
      result.push(layer.slice());
    }
    return result;
  }

  dependentsOf(name: string): string[] {
    if (!this.keySet.has(name)) {
      return [];
    }

    const reverse = new Map<string, string[]>();
    for (const task of this.keys) {
      const deps = this.spec[task];
      for (const dep of deps) {
        const existing = reverse.get(dep);
        if (existing === undefined) {
          reverse.set(dep, [task]);
        } else {
          existing.push(task);
        }
      }
    }

    const visited = new Set<string>();
    const queue: string[] = [name];
    visited.add(name);

    for (let i = 0; i < queue.length; i++) {
      const current = queue[i];
      const list = reverse.get(current);
      if (list !== undefined) {
        for (const task of list) {
          if (!visited.has(task)) {
            visited.add(task);
            queue.push(task);
          }
        }
      }
    }

    const result: string[] = [];
    for (const task of this.taskOrder) {
      if (task !== name && visited.has(task)) {
        result.push(task);
      }
    }
    return result;
  }

  private computeOrder(): string[] {
    const placed = new Set<string>();
    const active: string[] = [];
    const result: string[] = [];

    for (const task of this.keys) {
      if (!placed.has(task)) {
        this.placeTask(task, placed, active, result);
      }
    }

    return result;
  }

  private placeTask(
    task: string,
    placed: Set<string>,
    active: string[],
    result: string[]
  ): void {
    if (placed.has(task)) {
      return;
    }

    const activeIndex = active.indexOf(task);
    if (activeIndex !== -1) {
      const path = active.slice(activeIndex);
      path.push(task);
      throw new CycleError(path);
    }

    active.push(task);

    const deps = this.spec[task];
    for (const dep of deps) {
      this.placeTask(dep, placed, active, result);
    }

    active.pop();
    placed.add(task);
    result.push(task);
  }

  private computeLayers(): string[][] {
    const layerOf = new Map<string, number>();

    for (const task of this.taskOrder) {
      let layer = 0;
      const deps = this.spec[task];

      for (const dep of deps) {
        const depLayer = layerOf.get(dep);
        if (depLayer !== undefined) {
          const candidate = depLayer + 1;
          if (candidate > layer) {
            layer = candidate;
          }
        }
      }

      layerOf.set(task, layer);
    }

    const layers: string[][] = [];

    for (const task of this.keys) {
      const layer = layerOf.get(task);
      const layerIndex = layer === undefined ? 0 : layer;

      while (layers.length <= layerIndex) {
        layers.push([]);
      }

      layers[layerIndex].push(task);
    }

    return layers;
  }
}

