export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i: number = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  return {
    min: min,
    max: max,
    width: max.x - min.x,
    height: max.y - min.y
  };
}

/**
 * A generic last-in, first-out stack that holds at most a fixed number of items.
 */
export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  /**
   * Creates a stack that can hold at most `capacity` items.
   */
  constructor(capacity: number) {
    this.capacity = capacity;
  }

  /**
   * Puts `item` on top of the stack.
   * @returns `true` if the item was added, `false` if the stack is full.
   */
  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes and returns the top item, or `undefined` if the stack is empty.
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it, or `undefined` if the stack is empty.
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * Returns the number of items currently held by the stack.
   */
  size(): number {
    return this.items.length;
  }

  /**
   * Returns `true` when the stack holds no items.
   */
  isEmpty(): boolean {
    return this.items.length === 0;
  }

  /**
   * Returns `true` when the stack cannot hold any more items.
   */
  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /**
   * Removes every item from the stack.
   */
  clear(): void {
    this.items = [];
  }

  /**
   * Returns the items from bottom to top as a new array.
   * Mutating the returned array does not affect the stack.
   */
  toArray(): T[] {
    return this.items.slice();
  }
}

function decodeComponent(raw: string): string {
  const plusReplaced: string = raw.split('+').join(' ');
  if (plusReplaced.indexOf('%') < 0) {
    return plusReplaced;
  }
  try {
    return decodeURIComponent(plusReplaced);
  } catch (e) {
    return plusReplaced;
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }
  const parts: string[] = q.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (part.length === 0) {
      continue;
    }
    let rawKey: string = '';
    let rawValue: string = '';
    const eq: number = part.indexOf('=');
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key: string = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value: string = decodeComponent(rawValue);
    result.set(key, value);
  }
  return result;
}

/**
 * Shape modelling.
 *
 * `Shape` is an interface that only promises an `area()` method. Any new kind
 * of shape can be added later simply by writing a new class that implements
 * this interface — no existing code (including `area` and `totalArea`) has to
 * be touched.
 */
export interface Shape {
  area(): number;
}

class Circle implements Shape {
  private readonly radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle implements Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

class Triangle implements Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let total: number = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += shapes[i].area();
  }
  return total;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
    this.listeners = new Map<string, Listener<T>[]>();
  }

  on(event: string, listener: Listener<T>): void {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      this.listeners.set(event, [listener]);
      return;
    }
    if (existing.indexOf(listener) === -1) {
      existing.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return;
    }
    const index: number = existing.indexOf(listener);
    if (index === -1) {
      return;
    }
    existing.splice(index, 1);
    if (existing.length === 0) {
      this.listeners.delete(event);
    }
  }

  emit(event: string, payload: T): number {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    const snapshot: Listener<T>[] = existing.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const existing: Listener<T>[] | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    return existing.length;
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  let maxAttempts: number = Math.floor(attempts);
  if (!(maxAttempts >= 1)) {
    maxAttempts = 1;
  }

  let lastError: Error = new Error('unknown error');

  for (let i = 0; i < maxAttempts; i++) {
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(maxAttempts, lastError);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

