@Component
struct GroceryRow {
  @ObjectLink item: GroceryItem;
  onToggle: (id: number) => void = () => {};
  onDelete: (id: number) => void = () => {};
  @State offsetX: number = 0;
  private startOffset: number = 0;

  build() {
    Stack({ alignContent: Alignment.End }) {
      // Delete button, uncovered when the row is swiped to the left.
      Row() {
        Text('Delete')
          .fontSize(16)
          .fontColor(Color.White)
      }
      .width(DELETE_WIDTH)
      .height('100%')
      .backgroundColor('#D32F2F')
      .justifyContent(FlexAlign.Center)
      .onClick(() => {
        this.onDelete(this.item.id);
      })

      // The row content itself, which slides aside.
      Row() {
        Text(this.item.name)
          .fontSize(18)
          .fontColor(this.item.bought ? '#9E9E9E' : '#212121')
          .decoration({
            type: this.item.bought ? TextDecorationType.LineThrough : TextDecorationType.None,
            color: '#9E9E9E'
          })
      }
      .width('100%')
      .height('100%')
      .padding({ left: 16, right: 16 })
      .backgroundColor(Color.White)
      .translate({ x: this.offsetX })
      .gesture(
        GestureGroup(GestureMode.Exclusive,
          LongPressGesture({ duration: 500 })
            .onAction(() => {
              this.onToggle(this.item.id);
            }),
          PanGesture({ direction: PanDirection.Horizontal, distance: 5 })
            .onActionStart(() => {
              this.startOffset = this.offsetX;
            })
            .onActionUpdate((event: GestureEvent) => {
              let x: number = this.startOffset + event.offsetX;
              if (x > 0) {
                x = 0;
              }
              if (x < -DELETE_WIDTH) {
                x = -DELETE_WIDTH;
              }
              this.offsetX = x;
            })
            .onActionEnd(() => {
              animateTo({ duration: 200, curve: Curve.EaseOut }, () => {
                this.offsetX = this.offsetX < -DELETE_WIDTH / 2 ? -DELETE_WIDTH : 0;
              });
            })
        )
      )
    }
    .width('100%')
    .height(56)
    .clip(true)
  }
}

