/**
 * A simple generic pair holding two values.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements.
 * The final group may be shorter. Returns an empty array when
 * `items` is empty or `size` is less than 1.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  const step: number = Math.floor(size);
  for (let i = 0; i < items.length; i += step) {
    result.push(items.slice(i, i + step));
  }
  return result;
}

/**
 * Combines two arrays element-wise into pairs, stopping at the
 * length of the shorter input.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

export interface User {
  id: number;
  name: string;
  email: string;
}

interface RawUser {
  id?: Object;
  name?: Object;
  email?: Object;
}

export function parseUsers(json: string): User[] {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(json);
  } catch (e) {
    return [];
  }
  if (parsed === null || !Array.isArray(parsed)) {
    return [];
  }
  const arr = parsed as Object[];
  const result: User[] = [];
  for (let i = 0; i < arr.length; i++) {
    const element = arr[i];
    if (element === null || typeof element !== 'object' || Array.isArray(element)) {
      continue;
    }
    const raw = element as RawUser;
    const id = raw.id;
    const name = raw.name;
    const email = raw.email;
    if (typeof id !== 'number' || !Number.isInteger(id)) {
      continue;
    }
    if (typeof name !== 'string' || name.length === 0) {
      continue;
    }
    if (typeof email !== 'string' || !email.includes('@')) {
      continue;
    }
    result.push({ id: id, name: name, email: email });
  }
  return result;
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

function hasRule(rules: OpeningRule[], day: Weekday): boolean {
  for (let i = 0; i < rules.length; i++) {
    if (rules[i].day === day) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const weekdays: Weekday[] = [
    Weekday.Monday,
    Weekday.Tuesday,
    Weekday.Wednesday,
    Weekday.Thursday,
    Weekday.Friday,
    Weekday.Saturday,
    Weekday.Sunday
  ];

  const startIndex: number = weekdays.indexOf(day);
  if (startIndex < 0) {
    return undefined;
  }

  for (let offset = 1; offset <= weekdays.length; offset++) {
    const candidate: Weekday = weekdays[(startIndex + offset) % weekdays.length];
    if (hasRule(rules, candidate)) {
      return candidate;
    }
  }

  return undefined;
}

