class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

/**
 * A least-recently-used cache holding at most `capacity` keys.
 * Keys are compared by identity (SameValueZero): the number 1 and the
 * string '1' are different keys, and objects are equal only when they
 * are the very same object.
 */
export class LruCache<K, V> {
  private capacity: number;
  private store: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  // Least recently used node (front of the recency list).
  private head: LruNode<K, V> | null = null;
  // Most recently used node (back of the recency list).
  private tail: LruNode<K, V> | null = null;

  constructor(capacity: number) {
    if (!(capacity >= 1) || Math.floor(capacity) !== capacity) {
      throw new Error('capacity must be an integer greater than or equal to 1');
    }
    this.capacity = capacity;
  }

  get size(): number {
    return this.store.size;
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.store.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.unlink(existing);
      this.pushBack(existing);
      return;
    }
    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.store.set(key, node);
    this.pushBack(node);
    if (this.store.size > this.capacity) {
      const lru: LruNode<K, V> | null = this.head;
      if (lru !== null) {
        this.unlink(lru);
        this.store.delete(lru.key);
      }
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.store.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.unlink(node);
    this.pushBack(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.store.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | null = this.head;
    while (current !== null) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  private unlink(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | null = node.prev;
    const next: LruNode<K, V> | null = node.next;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.head = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private pushBack(node: LruNode<K, V>): void {
    const tail: LruNode<K, V> | null = this.tail;
    node.prev = tail;
    node.next = null;
    if (tail !== null) {
      tail.next = node;
    } else {
      this.head = node;
    }
    this.tail = node;
  }
}

