struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isEmailValid(value: string): boolean {
    // exactly one "@", at least one char before it, and after it a "."
    // with at least one character on each side (name@host.tld)
    return /^[^@]+@[^@.]+\.[^@.]+(\.[^@.]+)*$/.test(value);
  }

  private isPasswordValid(value: string): boolean {
    return value.length >= 8;
  }

  private canSignIn(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  build() {
    Column({ space: 12 }) {
      Text('Sign in')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .width('100%')
        .margin({ bottom: 8 })

