import { http } from '@kit.NetworkKit';
import { BusinessError } from '@kit.BasicServicesKit';

interface Item {
  id: number;
  name: string;
}

@Entry
@Component
struct Index {
  @State items: Item[] = [];
  @State loading: boolean = true;
  @State failed: boolean = false;

  aboutToAppear(): void {
    this.fetchItems();
  }

  private fetchItems(): void {
    this.loading = true;
    this.failed = false;

    const httpRequest = http.createHttp();
    httpRequest.request(
      'https://example.com/api/items',
      {
        method: http.RequestMethod.GET,
        expectDataType: http.HttpDataType.STRING,
        connectTimeout: 10000,
        readTimeout: 10000
      },
      (err: BusinessError, data: http.HttpResponse) => {
        if (err) {
          this.failed = true;
          this.loading = false;
          httpRequest.destroy();
          return;
        }

        if (data.responseCode !== http.ResponseCode.OK) {
          this.failed = true;
          this.loading = false;
          httpRequest.destroy();
          return;
        }

        try {
          const parsed = JSON.parse(data.result as string) as Item[];
          const loaded: Item[] = [];
          for (const entry of parsed) {
            loaded.push({ id: entry.id, name: entry.name });
          }
          this.items = loaded;
          this.loading = false;
        } catch (e) {
          this.failed = true;
          this.loading = false;
        }

        httpRequest.destroy();
      }
    );
  }

  build() {
    Column() {
      if (this.loading) {
        Text('Loading...')
          .fontSize(20)
          .fontColor('#333333')
          .margin({ top: 40 })
      } else if (this.failed) {
        Text('Could not load the items')
          .fontSize(20)
          .fontColor('#333333')
          .margin({ top: 40 })
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .fontColor('#000000')
                .width('100%')
                .padding({ top: 12, bottom: 12, left: 16, right: 16 })
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .divider({ strokeWidth: 1, color: '#E5E5E5' })
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
  }
}

import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';

const PREF_STORE_NAME: string = 'name_store';
const KEY_SAVED_NAME: string = 'saved_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State inputName: string = '';
  private pref: preferences.Preferences | null = null;

  aboutToAppear(): void {
    this.loadSavedName();
  }

  private getPref(): preferences.Preferences {
    if (this.pref === null) {
      const context = getContext(this) as common.UIAbilityContext;
      this.pref = preferences.getPreferencesSync(context, { name: PREF_STORE_NAME });
    }
    return this.pref;
  }

  private loadSavedName(): void {
    try {
      const pref = this.getPref();
      const stored = pref.getSync(KEY_SAVED_NAME, '') as string;
      this.savedName = stored;
      this.inputName = stored;
    } catch (err) {
      this.savedName = '';
    }
  }

  private saveName(): void {
    const name = this.inputName.trim();
    try {
      const pref = this.getPref();
      pref.putSync(KEY_SAVED_NAME, name);
      pref.flush();
      this.savedName = name;
    } catch (err) {
      // Saving failed; keep the current state as is.
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Medium)
        .textAlign(TextAlign.Center)

      TextInput({ placeholder: 'Enter your name', text: this.inputName })
        .width('100%')
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('100%')
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .justifyContent(FlexAlign.Center)
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.name = 'MissingDependencyError';
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.name = 'CycleError';
    this.path = path;
  }
}

export class BuildPlan {
  private names: string[] = [];
  private deps: Map<string, string[]> = new Map<string, string[]>();
  private ordered: string[] = [];

  constructor(spec: Record<string, string[]>) {
    const keys: string[] = Object.keys(spec);
    for (let i = 0; i < keys.length; i++) {
      const key: string = keys[i];
      this.names.push(key);
      const raw: string[] = spec[key];
      const copy: string[] = [];
      for (let j = 0; j < raw.length; j++) {
        copy.push(raw[j]);
      }
      this.deps.set(key, copy);
    }

    for (let i = 0; i < this.names.length; i++) {
      const name: string = this.names[i];
      const list: string[] = this.depsOf(name);
      for (let j = 0; j < list.length; j++) {
        const dep: string = list[j];
        if (!this.deps.has(dep)) {
          throw new MissingDependencyError(name, dep);
        }
      }
    }

    this.ordered = this.computeOrder();
  }

  order(): string[] {
    const result: string[] = [];
    for (let i = 0; i < this.ordered.length; i++) {
      result.push(this.ordered[i]);
    }
    return result;
  }

  layers(): string[][] {
    const layerOf: Map<string, number> = new Map<string, number>();
    for (let i = 0; i < this.ordered.length; i++) {
      const name: string = this.ordered[i];
      const list: string[] = this.depsOf(name);
      let level: number = 0;
      for (let j = 0; j < list.length; j++) {
        const depLevel: number = layerOf.get(list[j]) ?? 0;
        if (depLevel + 1 > level) {
          level = depLevel + 1;
        }
      }
      layerOf.set(name, level);
    }

    const result: string[][] = [];
    for (let i = 0; i < this.names.length; i++) {
      const name: string = this.names[i];
      const level: number = layerOf.get(name) ?? 0;
      while (result.length <= level) {
        result.push([]);
      }
      result[level].push(name);
    }
    return result;
  }

  dependentsOf(name: string): string[] {
    if (!this.deps.has(name)) {
      return [];
    }

    const reverse: Map<string, string[]> = new Map<string, string[]>();
    for (let i = 0; i < this.names.length; i++) {
      const task: string = this.names[i];
      const list: string[] = this.depsOf(task);
      for (let j = 0; j < list.length; j++) {
        const dep: string = list[j];
        const arr: string[] = reverse.get(dep) ?? [];
        arr.push(task);
        reverse.set(dep, arr);
      }
    }

    const found: Set<string> = new Set<string>();
    const stack: string[] = [name];
    while (stack.length > 0) {
      const current: string = stack.pop() as string;
      const arr: string[] = reverse.get(current) ?? [];
      for (let i = 0; i < arr.length; i++) {
        const task: string = arr[i];
        if (!found.has(task)) {
          found.add(task);
          stack.push(task);
        }
      }
    }

    const result: string[] = [];
    for (let i = 0; i < this.ordered.length; i++) {
      const task: string = this.ordered[i];
      if (found.has(task)) {
        result.push(task);
      }
    }
    return result;
  }

  private depsOf(name: string): string[] {
    const list: string[] | undefined = this.deps.get(name);
    if (list === undefined) {
      return [];
    }
    return list;
  }

  private computeOrder(): string[] {
    const placed: Set<string> = new Set<string>();
    const inChain: Set<string> = new Set<string>();
    const chain: string[] = [];
    const result: string[] = [];
    for (let i = 0; i < this.names.length; i++) {
      this.place(this.names[i], placed, inChain, chain, result);
    }
    return result;
  }

  private place(name: string, placed: Set<string>, inChain: Set<string>, chain: string[],
    result: string[]): void {
    if (placed.has(name)) {
      return;
    }
    if (inChain.has(name)) {
      const start: number = chain.indexOf(name);
      const path: string[] = [];
      for (let i = start; i < chain.length; i++) {
        path.push(chain[i]);
      }
      path.push(name);
      throw new CycleError(path);
    }

    inChain.add(name);
    chain.push(name);

    const list: string[] = this.depsOf(name);
    for (let i = 0; i < list.length; i++) {
      this.place(list[i], placed, inChain, chain, result);
    }

    chain.pop();
    inChain.delete(name);
    placed.add(name);
    result.push(name);
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export type EditorListener = (value: string | number | boolean, previous: string | number | boolean) => void;

class FieldWatcher {
  field: string;
  listener: EditorListener;
  active: boolean = true;

  constructor(field: string, listener: EditorListener) {
    this.field = field;
    this.listener = listener;
  }
}

export class EditorStore {
  private current: EditorState;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private historyLimit: number;
  private watchers: FieldWatcher[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.current = this.copy(initial);
    let limit: number = Math.floor(historyLimit);
    if (!(limit >= 1)) {
      limit = 1;
    }
    this.historyLimit = limit;
  }

  private copy(source: EditorState): EditorState {
    const result: EditorState = {
      text: source.text,
      cursor: source.cursor,
      bold: source.bold
    };
    return result;
  }

  get state(): EditorState {
    return this.copy(this.current);
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  private commit(next: EditorState): boolean {
    if (next.text === this.current.text && next.cursor === this.current.cursor && next.bold === this.current.bold) {
      return false;
    }
    const before: EditorState = this.copy(this.current);
    this.undoStack.push(before);
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
    this.redoStack = [];
    this.current = this.copy(next);
    this.notify(before, this.current);
    return true;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next: EditorState = this.copy(this.current);
    if (patch.text !== undefined) {
      next.text = patch.text;
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold;
    }
    return this.commit(next);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = this.copy(this.current);
    run(draft);
    const next: EditorState = this.copy(draft);
    return this.commit(next);
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const previous: EditorState = this.undoStack[this.undoStack.length - 1];
    this.undoStack.pop();
    const before: EditorState = this.copy(this.current);
    this.redoStack.push(before);
    this.current = this.copy(previous);
    this.notify(before, this.current);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const next: EditorState = this.redoStack[this.redoStack.length - 1];
    this.redoStack.pop();
    const before: EditorState = this.copy(this.current);
    this.undoStack.push(before);
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
    this.current = this.copy(next);
    this.notify(before, this.current);
    return true;
  }

  watch(field: string, listener: EditorListener): () => void {
    const watcher: FieldWatcher = new FieldWatcher(field, listener);
    this.watchers.push(watcher);
    const remover: () => void = () => {
      watcher.active = false;
      const index: number = this.watchers.indexOf(watcher);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
    return remover;
  }

  private notify(previous: EditorState, next: EditorState): void {
    const textChanged: boolean = previous.text !== next.text;
    const cursorChanged: boolean = previous.cursor !== next.cursor;
    const boldChanged: boolean = previous.bold !== next.bold;
    if (!textChanged && !cursorChanged && !boldChanged) {
      return;
    }
    const snapshot: FieldWatcher[] = [];
    for (const watcher of this.watchers) {
      snapshot.push(watcher);
    }
    for (const watcher of snapshot) {
      if (!watcher.active) {
        continue;
      }
      if (watcher.field === 'text') {
        if (textChanged) {
          watcher.listener(next.text, previous.text);
        }
      } else if (watcher.field === 'cursor') {
        if (cursorChanged) {
          watcher.listener(next.cursor, previous.cursor);
        }
      } else if (watcher.field === 'bold') {
        if (boldChanged) {
          watcher.listener(next.bold, previous.bold);
        }
      }
    }
  }
}

class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  constructor() {
    for (let i = 3000; i >= 1; i--) {
      this.entries.push(new LogEntry(i));
    }
  }

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos: number = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  highestId(): number {
    if (this.entries.length === 0) {
      return 0;
    }
    return this.entries[0].id;
  }

  addAtTop(items: LogEntry[]): void {
    for (let i = 0; i < items.length; i++) {
      this.entries.unshift(items[i]);
      for (let j = 0; j < this.listeners.length; j++) {
        this.listeners[j].onDataAdd(0);
      }
    }
  }
}

@Component
struct LogRow {
  @Prop entry: LogEntry = new LogEntry(0);

  private levelColor(): string {
    if (this.entry.level === 'error') {
      return '#D32F2F';
    }
    if (this.entry.level === 'warning') {
      return '#F57C00';
    }
    return '#757575';
  }

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontColor('#212121')
        .layoutWeight(1)
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis })
      Text(this.entry.level)
        .fontSize(14)
        .fontColor(this.levelColor())
        .margin({ left: 12 })
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .alignItems(VerticalAlign.Center)
  }
}

@Entry
@Component
struct LogPage {
  private dataSource: LogDataSource = new LogDataSource();
  private scroller: Scroller = new Scroller();
  @State count: number = 0;
  @State refreshing: boolean = false;

  aboutToAppear(): void {
    this.count = this.dataSource.totalCount();
  }

  private handleRefresh(): void {
    setTimeout(() => {
      const base: number = this.dataSource.highestId();
      const items: LogEntry[] = [];
      for (let i = 1; i <= 5; i++) {
        items.push(new LogEntry(base + i));
      }
      this.dataSource.addAtTop(items);
      this.count = this.dataSource.totalCount();
      this.refreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Text(`${this.count} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .width('100%')
        .padding({ left: 16, right: 16, top: 16, bottom: 16 })

      Refresh({ refreshing: $$this.refreshing }) {
        List({ scroller: this.scroller }) {
          LazyForEach(this.dataSource, (item: LogEntry, index: number) => {
            ListItem() {
              LogRow({ entry: item })
            }
          }, (item: LogEntry, index: number) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .cachedCount(5)
        .divider({ strokeWidth: 1, color: '#EEEEEE' })
      }
      .layoutWeight(1)
      .width('100%')
      .onRefreshing(() => {
        this.handleRefresh();
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

