import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';

/**
 * A quick choice offered in the goal dialog: a label and a number of glasses.
 */
class GoalPreset {
  label: string;
  glasses: number;

  constructor(label: string, glasses: number) {
    this.label = label;
    this.glasses = glasses;
  }
}

const GOAL_PRESETS: GoalPreset[] = [
  new GoalPreset('Light', 6),
  new GoalPreset('Standard', 8),
  new GoalPreset('Active', 12)
];

const PREFERENCES_NAME: string = 'water_tracker';
const KEY_COUNT: string = 'count';
const KEY_GOAL: string = 'goal';
const DEFAULT_GOAL: number = 8;

/**
 * Modal dialog used to pick a new daily goal.
 * It never changes the goal itself: it only reports the chosen number
 * through the `onSave` callback handed over by the page.
 */
@CustomDialog
struct GoalDialog {
  controller?: CustomDialogController;
  onSave: (glasses: number) => void = () => {
  };

  @State inputText: string = '';

  aboutToAppear(): void {
    // The field is empty every time the dialog opens.
    this.inputText = '';
  }

  private closeDialog(): void {
    if (this.controller !== undefined) {
      this.controller.close();
    }
  }

  private handleSave(): void {
    const value: number = Number(this.inputText);
    if (Number.isInteger(value) && value >= 1) {
      this.onSave(value);
      this.closeDialog();
    }
  }

  build() {
    Column({ space: 16 }) {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)

      TextInput({ text: this.inputText, placeholder: 'Glasses per day' })
        .type(InputType.Number)
        .onChange((value: string) => {
          this.inputText = value;
        })

      Row({ space: 8 }) {
        ForEach(GOAL_PRESETS, (preset: GoalPreset) => {
          Button(preset.label)
            .layoutWeight(1)
            .onClick(() => {
              this.inputText = preset.glasses.toString();
            })
        }, (preset: GoalPreset) => preset.label)
      }
      .width('100%')

      Row({ space: 12 }) {
        Button('Cancel')
          .layoutWeight(1)
          .onClick(() => {
            this.closeDialog();
          })
        Button('Save')
          .layoutWeight(1)
          .onClick(() => {
            this.handleSave();
          })
      }
      .width('100%')
    }
    .width('100%')
    .padding(24)
  }
}

@Entry
@Component
struct WaterTrackerPage {
  @State count: number = 0;
  @State goal: number = DEFAULT_GOAL;
  private store: preferences.Preferences | undefined = undefined;

  private dialogController: CustomDialogController = new CustomDialogController({
    builder: GoalDialog({
      onSave: (glasses: number): void => {
        this.updateGoal(glasses);
      }
    }),
    autoCancel: true,
    alignment: DialogAlignment.Center
  });

  aboutToAppear(): void {
    const context = getContext(this) as common.UIAbilityContext;
    const options: preferences.Options = { name: PREFERENCES_NAME };
    this.store = preferences.getPreferencesSync(context, options);
    this.count = this.store.getSync(KEY_COUNT, 0) as number;
    this.goal = this.store.getSync(KEY_GOAL, DEFAULT_GOAL) as number;
  }

  private persist(): void {
    if (this.store === undefined) {
      return;
    }
    this.store.putSync(KEY_COUNT, this.count);
    this.store.putSync(KEY_GOAL, this.goal);
    this.store.flush();
  }

  private addGlass(): void {
    this.count = this.count + 1;
    this.persist();
  }

  private updateGoal(glasses: number): void {
    this.goal = glasses;
    this.persist();
  }

  build() {
    Column({ space: 20 }) {
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(28)
        .fontWeight(FontWeight.Bold)

      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(20)
          .fontColor(Color.Green)
      }

      Button('Add a glass')
        .width(200)
        .onClick(() => {
          this.addGlass();
        })

      Button('Change goal')
        .width(200)
        .onClick(() => {
          this.dialogController.open();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(24)
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return settings;
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const theme: string = user.theme !== undefined ? user.theme : defaults.theme;
  const fontSize: number = user.fontSize !== undefined ? user.fontSize : defaults.fontSize;
  const notifications: boolean =
    user.notifications !== undefined ? user.notifications : defaults.notifications;
  const language: string = user.language !== undefined ? user.language : defaults.language;

  const merged: Settings = {
    theme: theme,
    fontSize: fontSize,
    notifications: notifications,
    language: language
  };
  return merged;
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
    this.name = 'ExpressionError';
  }
}

function isDigitChar(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStartChar(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNamePartChar(c: string): boolean {
  return isNameStartChar(c) || isDigitChar(c);
}

function makeToken(kind: string, text: string, position: number): Token {
  const token: Token = { kind: kind, text: text, position: position };
  return token;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const length: number = source.length;
  let i: number = 0;
  while (i < length) {
    const c: string = source.charAt(i);
    if (c === ' ') {
      i = i + 1;
      continue;
    }
    if (isDigitChar(c)) {
      const start: number = i;
      while (i < length && isDigitChar(source.charAt(i))) {
        i = i + 1;
      }
      if (i + 1 < length && source.charAt(i) === '.' && isDigitChar(source.charAt(i + 1))) {
        i = i + 1;
        while (i < length && isDigitChar(source.charAt(i))) {
          i = i + 1;
        }
      }
      tokens.push(makeToken('number', source.substring(start, i), start));
      continue;
    }
    if (isNameStartChar(c)) {
      const start: number = i;
      while (i < length && isNamePartChar(source.charAt(i))) {
        i = i + 1;
      }
      tokens.push(makeToken('name', source.substring(start, i), start));
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      tokens.push(makeToken('operator', c, i));
      i = i + 1;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push(makeToken('paren', c, i));
      i = i + 1;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class Expr {
  position: number = 0;
}

class NumberExpr extends Expr {
  value: number;

  constructor(value: number, position: number) {
    super();
    this.value = value;
    this.position = position;
  }
}

class NameExpr extends Expr {
  name: string;

  constructor(name: string, position: number) {
    super();
    this.name = name;
    this.position = position;
  }
}

class NegExpr extends Expr {
  operand: Expr;

  constructor(operand: Expr, position: number) {
    super();
    this.operand = operand;
    this.position = position;
  }
}

class BinaryExpr extends Expr {
  op: string;
  left: Expr;
  right: Expr;

  constructor(op: string, left: Expr, right: Expr, position: number) {
    super();
    this.op = op;
    this.left = left;
    this.right = right;
    this.position = position;
  }
}

class Parser {
  private tokens: Token[];
  private index: number;
  private endPosition: number;

  constructor(tokens: Token[], endPosition: number) {
    this.tokens = tokens;
    this.index = 0;
    this.endPosition = endPosition;
  }

  parse(): Expr {
    const expr: Expr = this.parseExpression();
    if (this.index < this.tokens.length) {
      const extra: Token = this.tokens[this.index];
      throw new ExpressionError(`Unexpected token '${extra.text}'`, extra.position);
    }
    return expr;
  }

  private peek(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return undefined;
  }

  private parseExpression(): Expr {
    let left: Expr = this.parseTerm();
    while (true) {
      const token: Token | undefined = this.peek();
      if (token === undefined) {
        break;
      }
      if (token.kind !== 'operator') {
        break;
      }
      if (token.text !== '+' && token.text !== '-') {
        break;
      }
      this.index = this.index + 1;
      const right: Expr = this.parseTerm();
      left = new BinaryExpr(token.text, left, right, token.position);
    }
    return left;
  }

  private parseTerm(): Expr {
    let left: Expr = this.parseUnary();
    while (true) {
      const token: Token | undefined = this.peek();
      if (token === undefined) {
        break;
      }
      if (token.kind !== 'operator') {
        break;
      }
      if (token.text !== '*' && token.text !== '/' && token.text !== '%') {
        break;
      }
      this.index = this.index + 1;
      const right: Expr = this.parseUnary();
      left = new BinaryExpr(token.text, left, right, token.position);
    }
    return left;
  }

  private parseUnary(): Expr {
    const token: Token | undefined = this.peek();
    if (token === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.endPosition);
    }
    if (token.kind === 'operator' && token.text === '-') {
      this.index = this.index + 1;
      const operand: Expr = this.parseUnary();
      return new NegExpr(operand, token.position);
    }
    return this.parsePrimary();
  }

  private parsePrimary(): Expr {
    const token: Token | undefined = this.peek();
    if (token === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.endPosition);
    }
    if (token.kind === 'number') {
      this.index = this.index + 1;
      return new NumberExpr(parseFloat(token.text), token.position);
    }
    if (token.kind === 'name') {
      this.index = this.index + 1;
      return new NameExpr(token.text, token.position);
    }
    if (token.kind === 'paren' && token.text === '(') {
      this.index = this.index + 1;
      const inner: Expr = this.parseExpression();
      const close: Token | undefined = this.peek();
      if (close === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.endPosition);
      }
      if (close.kind === 'paren' && close.text === ')') {
        this.index = this.index + 1;
        return inner;
      }
      throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
    }
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
}

function evalExpr(node: Expr, vars: Map<string, number>): number {
  if (node instanceof NumberExpr) {
    return node.value;
  } else if (node instanceof NameExpr) {
    const value: number | undefined = vars.get(node.name);
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return value;
  } else if (node instanceof NegExpr) {
    const operand: number = evalExpr(node.operand, vars);
    return -operand;
  } else if (node instanceof BinaryExpr) {
    const left: number = evalExpr(node.left, vars);
    const right: number = evalExpr(node.right, vars);
    if (node.op === '+') {
      return left + right;
    }
    if (node.op === '-') {
      return left - right;
    }
    if (node.op === '*') {
      return left * right;
    }
    if (node.op === '/') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', node.position);
      }
      return left / right;
    }
    if (node.op === '%') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', node.position);
      }
      return left % right;
    }
    throw new ExpressionError(`Unexpected token '${node.op}'`, node.position);
  }
  throw new ExpressionError('Unexpected end of expression', 0);
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens: Token[] = tokenize(source);
  const parser: Parser = new Parser(tokens, source.length);
  const root: Expr = parser.parse();
  const vars: Map<string, number> = new Map<string, number>();
  const keys: string[] = Object.keys(variables);
  for (let i = 0; i < keys.length; i++) {
    const key: string = keys[i];
    vars.set(key, variables[key]);
  }
  return evalExpr(root, vars);
}

