    new GroceryItem(3, 'Eggs', false),
    new GroceryItem(4, 'Apples', false)
  ];
  @State boughtCount: number = 0;
  @State newName: string = '';
  private nextId: number = 5;

  private countBought(list: GroceryItem[]): number {
    let count: number = 0;
    for (const entry of list) {
      if (entry.bought) {
        count = count + 1;
      }
    }
    return count;
  }

  private toggleItem(id: number): void {
    for (const entry of this.items) {
      if (entry.id === id) {
        entry.bought = !entry.bought;
      }
    }
    this.boughtCount = this.countBought(this.items);
  }

  private deleteItem(id: number): void {
    const rest: GroceryItem[] = [];
    for (const entry of this.items) {
      if (entry.id !== id) {
        rest.push(entry);
      }
    }
    this.items = rest;
    this.boughtCount = this.countBought(rest);
  }

