    const trimmed: string = this.newName.trim();
    if (trimmed.length === 0) {
      return;
    }
    const created: GroceryItem = new GroceryItem(this.nextId, trimmed, false);
    this.nextId = this.nextId + 1;
    this.items = this.items.concat([created]);
    this.newName = '';
    this.boughtCount = this.countBought(this.items);
  }

