export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (const p of points) {
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const minPoint: Point = { x: minX, y: minY };
  const maxPoint: Point = { x: maxX, y: maxY };
  const result: Box = {
    min: minPoint,
    max: maxPoint,
    width: maxX - minX,
    height: maxY - minY
  };
  return result;
}

