/**
 * A last-in, first-out stack that holds at most a fixed number of items.
 */
export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  /**
   * @param capacity the largest number of items the stack can hold.
   */
  constructor(capacity: number) {
    if (capacity > 0) {
      this.capacity = Math.floor(capacity);
    } else {
      this.capacity = 0;
    }
  }

  /**
   * Puts the item on top of the stack.
   * @returns true when the item was added, false when the stack is full.
   */
  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes the top item and returns it, or undefined when the stack is empty.
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it, or undefined when the stack is empty.
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * How many items the stack holds.
   */
  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /**
   * Removes every item.
   */
  clear(): void {
    this.items = [];
  }

  /**
   * The items from bottom to top, as a new array.
   */
  toArray(): T[] {
    return this.items.slice();
  }
}

const PI: number = Math.PI;

/**
 * A shape that can report its own area. New kinds of shapes only need to
 * implement this interface and provide their own `area()` implementation.
 */
export interface Shape {
  area(): number;
}

class Circle implements Shape {
  private radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return PI * this.radius * this.radius;
  }
}

class Rectangle implements Shape {
  private width: number;
  private height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

class Triangle implements Shape {
  private base: number;
  private height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += shape.area();
  }
  return sum;
}

function isHexDigit(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function hexValue(c: string): number {
  const code: number = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  return code - 55;
}

function hasMalformedEscape(s: string): boolean {
  let i: number = 0;
  const n: number = s.length;
  while (i < n) {
    if (s.charAt(i) === '%') {
      if (i + 2 >= n) {
        return true;
      }
      if (!isHexDigit(s.charAt(i + 1)) || !isHexDigit(s.charAt(i + 2))) {
        return true;
      }
      i += 3;
    } else {
      i += 1;
    }
  }
  return false;
}

function replacePlus(s: string): string {
  let out: string = '';
  let i: number = 0;
  const n: number = s.length;
  while (i < n) {
    const ch: string = s.charAt(i);
    if (ch === '+') {
      out += ' ';
    } else {
      out += ch;
    }
    i += 1;
  }
  return out;
}

function utf8Decode(bytes: number[]): string {
  let out: string = '';
  let i: number = 0;
  const n: number = bytes.length;
  while (i < n) {
    const b0: number = bytes[i];
    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
    } else if (b0 >= 0xC2 && b0 <= 0xDF) {
      if (i + 1 < n && (bytes[i + 1] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x1F) << 6) | (bytes[i + 1] & 0x3F);
        out += String.fromCharCode(cp);
        i += 2;
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else if (b0 >= 0xE0 && b0 <= 0xEF) {
      if (i + 2 < n && (bytes[i + 1] & 0xC0) === 0x80 && (bytes[i + 2] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x0F) << 12) | ((bytes[i + 1] & 0x3F) << 6) | (bytes[i + 2] & 0x3F);
        if (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF)) {
          out += '\uFFFD';
          i += 1;
        } else {
          out += String.fromCharCode(cp);
          i += 3;
        }
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else if (b0 >= 0xF0 && b0 <= 0xF4) {
      if (i + 3 < n && (bytes[i + 1] & 0xC0) === 0x80 && (bytes[i + 2] & 0xC0) === 0x80 &&
        (bytes[i + 3] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x07) << 18) | ((bytes[i + 1] & 0x3F) << 12) |
          ((bytes[i + 2] & 0x3F) << 6) | (bytes[i + 3] & 0x3F);
        if (cp < 0x10000 || cp > 0x10FFFF) {
          out += '\uFFFD';
          i += 1;
        } else {
          const v: number = cp - 0x10000;
          out += String.fromCharCode(0xD800 + (v >> 10), 0xDC00 + (v & 0x3FF));
          i += 4;
        }
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else {
      out += '\uFFFD';
      i += 1;
    }
  }
  return out;
}

function encodeCharToBytes(code: number, bytes: number[]): void {
  if (code < 0x80) {
    bytes.push(code);
  } else if (code < 0x800) {
    bytes.push(0xC0 | (code >> 6));
    bytes.push(0x80 | (code & 0x3F));
  } else {
    bytes.push(0xE0 | (code >> 12));
    bytes.push(0x80 | ((code >> 6) & 0x3F));
    bytes.push(0x80 | (code & 0x3F));
  }
}

function decodeComponent(s: string): string {
  if (hasMalformedEscape(s)) {
    return replacePlus(s);
  }
  const bytes: number[] = [];
  let i: number = 0;
  const n: number = s.length;
  while (i < n) {
    const ch: string = s.charAt(i);
    if (ch === '+') {
      bytes.push(0x20);
      i += 1;
    } else if (ch === '%') {
      const hi: number = hexValue(s.charAt(i + 1));
      const lo: number = hexValue(s.charAt(i + 2));
      bytes.push(hi * 16 + lo);
      i += 3;
    } else {
      const code: number = s.charCodeAt(i);
      if (code >= 0xD800 && code <= 0xDBFF && i + 1 < n) {
        const next: number = s.charCodeAt(i + 1);
        if (next >= 0xDC00 && next <= 0xDFFF) {
          const cp: number = 0x10000 + ((code - 0xD800) << 10) + (next - 0xDC00);
          bytes.push(0xF0 | (cp >> 18));
          bytes.push(0x80 | ((cp >> 12) & 0x3F));
          bytes.push(0x80 | ((cp >> 6) & 0x3F));
          bytes.push(0x80 | (cp & 0x3F));
          i += 2;
        } else {
          bytes.push(0xEF);
          bytes.push(0xBF);
          bytes.push(0xBD);
          i += 1;
        }
      } else if (code >= 0xDC00 && code <= 0xDFFF) {
        bytes.push(0xEF);
        bytes.push(0xBF);
        bytes.push(0xBD);
        i += 1;
      } else {
        encodeCharToBytes(code, bytes);
        i += 1;
      }
    }
  }
  return utf8Decode(bytes);
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }
  const parts: string[] = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq: number = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key: string = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value: string = decodeComponent(rawValue);
    result.set(key, value);
  }
  return result;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map<string, Array<Listener<T>>>();

  constructor() {
    this.listeners = new Map<string, Array<Listener<T>>>();
  }

  on(event: string, listener: Listener<T>): void {
    let list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.listeners.set(event, list);
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        return;
      }
    }
    list.push(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        list.splice(i, 1);
        break;
      }
    }
    if (list.length === 0) {
      this.listeners.delete(event);
    }
  }

  emit(event: string, payload: T): number {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = list.slice();
    for (let i = 0; i < snapshot.length; i++) {
      const current: Listener<T> = snapshot[i];
      current(payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const list: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  let total: number = Math.floor(attempts);
  if (total < 1) {
    total = 1;
  }
  let made: number = 0;
  let lastError: Error = new Error('No attempt was made');
  for (let i = 0; i < total; i++) {
    made = made + 1;
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }
  throw new RetryError(made, lastError);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = { id: item.id, name: item.name, quantity: quantity };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    current.push(items[i]);
  }
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

function padTwo(value: number): string {
  return value < 10 ? '0' + value.toString() : value.toString();
}

function isDigitChar(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const t: number = negative ? -totalSeconds : totalSeconds;

  const hours: number = Math.floor(t / 3600);
  const minutes: number = Math.floor((t % 3600) / 60);
  const seconds: number = t % 60;

  let result: string = '';
  if (hours > 0) {
    result = hours.toString() + 'h ' + padTwo(minutes) + 'm ' + padTwo(seconds) + 's';
  } else if (minutes > 0) {
    result = minutes.toString() + 'm ' + padTwo(seconds) + 's';
  } else {
    result = seconds.toString() + 's';
  }

  return negative ? '-' + result : result;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let index: number = 0;
  let negative: boolean = false;
  if (text.charAt(0) === '-') {
    negative = true;
    index = 1;
    if (index >= text.length) {
      return NaN;
    }
  }

  let total: number = 0;
  let first: boolean = true;

  while (index < text.length) {
    if (!first) {
      if (text.charAt(index) !== ' ') {
        return NaN;
      }
      index++;
      if (index >= text.length) {
        return NaN;
      }
    }

    const digitsStart: number = index;
    while (index < text.length && isDigitChar(text.charAt(index))) {
      index++;
    }
    if (index === digitsStart) {
      return NaN;
    }
    const digits: string = text.substring(digitsStart, index);

    if (index >= text.length) {
      return NaN;
    }
    const unit: string = text.charAt(index);
    index++;

    let multiplier: number = 0;
    if (unit === 'h') {
      multiplier = 3600;
    } else if (unit === 'm') {
      multiplier = 60;
    } else if (unit === 's') {
      multiplier = 1;
    } else {
      return NaN;
    }

    total += Number(digits) * multiplier;
    first = false;
  }

  return negative ? -total : total;
}

/**
 * Days of the week, running from Monday to Sunday.
 */
export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

/**
 * An opening rule: the place is open on `day` from `openHour` up to,
 * but not including, `closeHour`.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Returns true when at least one rule covers the given day and hour.
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the first day after `day` that has at least one rule, wrapping
 * around from Sunday to Monday. `day` itself is considered last, so it is
 * returned only when it is the sole day with a rule. Returns undefined when
 * no day has a rule at all.
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const dayCount: number = 7;
  for (let offset = 1; offset <= dayCount; offset++) {
    const candidate: Weekday = ((day + offset) % dayCount) as Weekday;
    for (let i = 0; i < rules.length; i++) {
      if (rules[i].day === candidate) {
        return candidate;
      }
    }
  }
  return undefined;
}

/**
 * A simple generic pair of two values.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements.
 * The final group may be shorter. A `size` below 1 yields an empty array.
 * The input array is never modified and every group is a fresh array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  const step: number = Math.floor(size);
  let start: number = 0;
  while (start < items.length) {
    const end: number = Math.min(start + step, items.length);
    const group: T[] = [];
    for (let i: number = start; i < end; i++) {
      group.push(items[i]);
    }
    result.push(group);
    start = end;
  }
  return result;
}

/**
 * Combines two arrays index by index into an array of pairs.
 * The result is as long as the shorter input. Neither input is modified.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i: number = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

