/**
 * A transform takes one string and returns one string.
 */
export type Transform = (text: string) => string;

/**
 * Removes whitespace from both ends of the text.
 */
export function trim(text: string): string {
  return text.trim();
}

/**
 * Turns the text into lower case.
 */
export function lowerCase(text: string): string {
  return text.toLowerCase();
}

/**
 * Replaces every run of whitespace characters with a single space.
 */
export function collapseSpaces(text: string): string {
  let result: string = '';
  let inWhitespace: boolean = false;
  for (let i = 0; i < text.length; i++) {
    const code: number = text.charCodeAt(i);
    const isWhitespace: boolean =
      code === 32 || code === 9 || code === 10 || code === 11 || code === 12 || code === 13;
    if (isWhitespace) {
      if (!inWhitespace) {
        result += ' ';
        inWhitespace = true;
      }
    } else {
      result += text.charAt(i);
      inWhitespace = false;
    }
  }
  return result;
}

/**
 * One named step of a pipeline.
 */
class PipelineStep {
  name: string;
  transform: Transform;

  constructor(name: string, transform: Transform) {
    this.name = name;
    this.transform = transform;
  }
}

/**
 * An ordered list of named transformation steps.
 */
export class Pipeline {
  private steps: PipelineStep[] = [];

  /**
   * Appends a step and returns the pipeline itself.
   */
  add(name: string, step: Transform): Pipeline {
    this.steps.push(new PipelineStep(name, step));
    return this;
  }

  /**
   * Passes the text through every step in order.
   */
  run(text: string): string {
    let result: string = text;
    for (let i = 0; i < this.steps.length; i++) {
      result = this.steps[i].transform(result);
    }
    return result;
  }

  /**
   * Returns the step names in order, as a new array.
   */
  names(): string[] {
    const result: string[] = [];
    for (let i = 0; i < this.steps.length; i++) {
      result.push(this.steps[i].name);
    }
    return result;
  }

  /**
   * Returns a function behaving like `run`, always using the current steps.
   */
  toFunction(): Transform {
    return (text: string): string => this.run(text);
  }
}

/**
 * Returns one function applying the given steps from first to last.
 */
export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (let i = 0; i < steps.length; i++) {
      result = steps[i](result);
    }
    return result;
  };
}

