/**
 * A fixed-capacity cache that evicts the least recently used key when full.
 *
 * Keys are compared with the same semantics as `Map`: the number `1` and the
 * string `'1'` are different keys, and two objects are the same key only when
 * they are the very same object.
 */
class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | undefined = undefined;
  next: LruNode<K, V> | undefined = undefined;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private readonly capacity: number;
  private readonly nodes: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  // Least recently used end of the list.
  private head: LruNode<K, V> | undefined = undefined;
  // Most recently used end of the list.
  private tail: LruNode<K, V> | undefined = undefined;
  private count: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity >= 1 ? Math.floor(capacity) : 1;
  }

  get size(): number {
    return this.count;
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.nodes.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToTail(existing);
      return;
    }

    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.nodes.set(key, node);
    this.appendToTail(node);
    this.count++;

    while (this.count > this.capacity) {
      const oldest: LruNode<K, V> | undefined = this.head;
      if (oldest === undefined) {
        break;
      }
      this.removeNode(oldest);
      this.nodes.delete(oldest.key);
      this.count--;
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.nodes.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToTail(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.nodes.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | undefined = this.head;
    while (current !== undefined) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  private appendToTail(node: LruNode<K, V>): void {
    node.prev = this.tail;
    node.next = undefined;
    if (this.tail !== undefined) {
      this.tail.next = node;
    } else {
      this.head = node;
    }
    this.tail = node;
  }

  private removeNode(node: LruNode<K, V>): void {
    const before: LruNode<K, V> | undefined = node.prev;
    const after: LruNode<K, V> | undefined = node.next;

    if (before !== undefined) {
      before.next = after;
    } else {
      this.head = after;
    }

    if (after !== undefined) {
      after.prev = before;
    } else {
      this.tail = before;
    }

    node.prev = undefined;
    node.next = undefined;
  }

  private moveToTail(node: LruNode<K, V>): void {
    if (this.tail === node) {
      return;
    }
    this.removeNode(node);
    this.appendToTail(node);
  }
}

