import { http } from '@kit.NetworkKit';
import { BusinessError } from '@kit.BasicServicesKit';

const ITEMS_URL: string = 'https://example.com/api/items';

class Item {
  id: number = 0;
  name: string = '';
}

enum LoadState {
  Loading,
  Success,
  Error
}

@Entry
@Component
struct ItemListPage {
  @State loadState: LoadState = LoadState.Loading;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.loadItems();
  }

  private loadItems(): void {
    const httpRequest = http.createHttp();
    const options: http.HttpRequestOptions = {
      method: http.RequestMethod.GET,
      expectDataType: http.HttpDataType.STRING,
      connectTimeout: 10000,
      readTimeout: 10000
    };
    httpRequest.request(ITEMS_URL, options)
      .then((response: http.HttpResponse) => {
        if (response.responseCode === http.ResponseCode.OK) {
          this.handleBody(response.result as string);
        } else {
          this.loadState = LoadState.Error;
        }
        httpRequest.destroy();
      })
      .catch((err: BusinessError) => {
        this.loadState = LoadState.Error;
        httpRequest.destroy();
      });
  }

  private handleBody(body: string): void {
    try {
      const parsed: Item[] = JSON.parse(body) as Item[];
      this.items = parsed;
      this.loadState = LoadState.Success;
    } catch (e) {
      this.loadState = LoadState.Error;
    }
  }

  build() {
    Column() {
      if (this.loadState === LoadState.Loading) {
        Text('Loading...')
          .fontSize(20)
          .fontColor(Color.Gray)
      } else if (this.loadState === LoadState.Success) {
        List({ space: 8 }) {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .width('100%')
                .padding(8)
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .layoutWeight(1)
      } else {
        Text('Could not load the items')
          .fontSize(20)
          .fontColor(Color.Red)
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .justifyContent(FlexAlign.Center)
  }
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
    this.name = 'ExpressionError';
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const len = source.length;

  while (i < len) {
    const char = source[i];

    // Skip spaces
    if (char === ' ') {
      i++;
      continue;
    }

    // Numbers: digits, optionally followed by '.' and more digits
    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < len && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      if (i < len && source[i] === '.' && i + 1 < len && source[i + 1] >= '0' && source[i + 1] <= '9') {
        i++; // consume '.'
        while (i < len && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Names: letter or underscore, followed by letters, digits, underscores
    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < len && (
        (source[i] >= 'a' && source[i] <= 'z') ||
        (source[i] >= 'A' && source[i] <= 'Z') ||
        (source[i] >= '0' && source[i] <= '9') ||
        source[i] === '_'
      )) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Operators and parentheses
    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({
        kind: 'paren',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

// Parser state
interface ParserState {
  tokens: Token[];
  position: number;
}

function peek(state: ParserState): Token | undefined {
  return state.position < state.tokens.length ? state.tokens[state.position] : undefined;
}

function consume(state: ParserState): Token {
  return state.tokens[state.position++];
}

function expect(state: ParserState, kind: string, text?: string): Token {
  const token = peek(state);
  if (!token) {
    throw new ExpressionError('Unexpected end of expression', state.tokens.length > 0 ? state.tokens[state.tokens.length - 1].position : 0);
  }
  if (text !== undefined && token.text !== text) {
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
  if (text === undefined && token.kind !== kind) {
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
  return consume(state);
}

// Grammar:
// expression     = term { ("+" | "-") term }
// term           = unary { ("*" | "/" | "%") unary }
// unary          = "-" unary | primary
// primary        = number | name | "(" expression ")"

function parseExpression(state: ParserState, variables: Record<string, number>): number {
  let left = parseTerm(state, variables);

  while (peek(state)?.text === '+' || peek(state)?.text === '-') {
    const op = consume(state).text;
    const right = parseTerm(state, variables);
    if (op === '+') {
      left = left + right;
    } else {
      left = left - right;
    }
  }

  return left;
}

function parseTerm(state: ParserState, variables: Record<string, number>): number {
  let left = parseUnary(state, variables);

  while (peek(state)?.text === '*' || peek(state)?.text === '/' || peek(state)?.text === '%') {
    const op = consume(state).text;
    const right = parseUnary(state, variables);
    if (op === '*') {
      left = left * right;
    } else if (op === '/') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', op === '/' ? peek(state)?.position || 0 : 0);
      }
      left = left / right;
    } else { // op === '%'
      if (right === 0) {
        throw new ExpressionError('Division by zero', peek(state)?.position || 0);
      }
      left = left % right;
    }
  }

  return left;
}

function parseUnary(state: ParserState, variables: Record<string, number>): number {
  if (peek(state)?.text === '-') {
    consume(state); // consume '-'
    return -parseUnary(state, variables);
  }
  return parsePrimary(state, variables);
}

function parsePrimary(state: ParserState, variables: Record<string, number>): number {
  const token = peek(state);

  if (!token) {
    throw new ExpressionError('Unexpected end of expression', state.tokens.length > 0 ? state.tokens[state.tokens.length - 1].position : 0);
  }

  if (token.kind === 'number') {
    consume(state);
    return parseFloat(token.text);
  }

  if (token.kind === 'name') {
    consume(state);
    if (!(token.text in variables)) {
      throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
    }
    return variables[token.text];
  }

  if (token.kind === 'paren' && token.text === '(') {
    consume(state); // consume '('
    const result = parseExpression(state, variables);
    expect(state, 'paren', ')');
    return result;
  }

  throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
}

function evaluate(source: string, variables: Record<string, number>): number {
  // Handle empty source
  if (source.trim() === '') {
    throw new ExpressionError('Unexpected end of expression', 0);
  }

  // Tokenize first
  let tokens: Token[];
  try {
    tokens = tokenize(source);
  } catch (e) {
    if (e instanceof ExpressionError) {
      throw e;
    }
    throw e;
  }

  // If no tokens, it's an error
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', 0);
  }

  // Parse and evaluate
  const state: ParserState = {
    tokens,
    position: 0
  };

  const result = parseExpression(state, variables);

  // Check for extra tokens
  if (state.position < state.tokens.length) {
    const token = state.tokens[state.position];
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  return result;
}

class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];
  private dependencies: Map<string, string[]>;
  private orderCache: string[] | null = null;
  private layersCache: string[][] | null = null;

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);
    this.dependencies = new Map();

    // First, validate that all dependencies exist as keys
    for (const task of this.tasks) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!(dep in spec)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Then, check for cycles during construction
    this.checkAndBuildOrder();
  }

  private checkAndBuildOrder(): void {
    const visited = new Set<string>();
    const inStack = new Set<string>();
    const order: string[] = [];
    const path: string[] = [];

    const dfs = (task: string): void => {
      if (inStack.has(task)) {
        // Found a cycle: find the cycle path
        const cycleStartIndex = path.indexOf(task);
        const cyclePath = path.slice(cycleStartIndex);
        cyclePath.push(task);
        throw new CycleError(cyclePath);
      }

      if (visited.has(task)) {
        return;
      }

      visited.add(task);
      inStack.add(task);
      path.push(task);

      const deps = this.spec[task];
      for (const dep of deps) {
        dfs(dep);
      }

      inStack.delete(task);
      path.pop();
      order.push(task);
    };

    // Process tasks in key order
    for (const task of this.tasks) {
      if (!visited.has(task)) {
        dfs(task);
      }
    }

    this.orderCache = order;
  }

  order(): string[] {
    if (this.orderCache === null) {
      this.checkAndBuildOrder();
    }
    return [...this.orderCache];
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    // Compute layers based on dependencies
    const layerMap = new Map<string, number>();
    const order = this.order();

    // First pass: assign layers
    for (const task of order) {
      const deps = this.spec[task];
      let maxLayer = -1;

      for (const dep of deps) {
        if (layerMap.has(dep)) {
          maxLayer = Math.max(maxLayer, layerMap.get(dep)!);
        }
      }

      layerMap.set(task, maxLayer + 1);
    }

    // Group tasks by layer, maintaining key order within each layer
    const maxLayer = Math.max(...Array.from(layerMap.values()));
    const result: string[][] = [];

    for (let i = 0; i <= maxLayer; i++) {
      result.push([]);
    }

    // Process tasks in key order to maintain consistency
    for (const task of this.tasks) {
      const layer = layerMap.get(task)!;
      result[layer].push(task);
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    // Get all tasks that depend on 'name' directly or indirectly
    const dependents = new Set<string>();
    const visited = new Set<string>();

    const collectDependents = (task: string): void => {
      if (visited.has(task)) {
        return;
      }
      visited.add(task);

      // Check all tasks to see if they depend on 'task'
      for (const t of this.tasks) {
        const deps = this.spec[t];
        if (deps.includes(task)) {
          if (!dependents.has(t)) {
            dependents.add(t);
            collectDependents(t);
          }
        }
      }
    };

    collectDependents(name);

    // Return in the order from order()
    const order = this.order();
    return order.filter(task => dependents.has(task));
  }
}

interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class JobQueue {
  private concurrency: number;
  private runningCount: number = 0;
  private waitingJobs: Array<{ job: () => Promise<any>; resolve: (value: any) => void; reject: (reason: Error) => void }> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleResolver: (() => void)[] = [];
  private idlePromise: Promise<void> | null = null;

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error('Concurrency must be a whole number of at least 1');
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({ job, resolve, reject });
      this._tryStartJobs();
    });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this._tryStartJobs();
  }

  clear(): number {
    const removedCount = this.waitingJobs.length;
    const error = new Error('Job was cancelled');

    // Reject all waiting jobs with the cancellation error
    for (const { reject } of this.waitingJobs) {
      reject(error);
    }

    this.waitingJobs = [];
    this._checkIdle();
    return removedCount;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    return new Promise<void>(resolve => {
      this.idleResolver.push(resolve);
    });
  }

  async runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = new Array(jobs.length);
    const promises: Promise<void>[] = [];

    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      const promise = this.add<T>(job)
        .then(value => {
          outcomes[i] = { ok: true, value, error: undefined };
        })
        .catch(error => {
          outcomes[i] = { ok: false, value: undefined, error };
        });
      promises.push(promise);
    }

    await Promise.all(promises);
    return outcomes;
  }

  private _tryStartJobs(): void {
    while (
      this.runningCount < this.concurrency &&
      this.waitingJobs.length > 0 &&
      !this.paused
    ) {
      const jobEntry = this.waitingJobs.shift();
      if (!jobEntry) break;

      this.runningCount++;
      const { job, resolve, reject } = jobEntry;

      job()
        .then(value => {
          this.runningCount--;
          this.completedCount++;
          resolve(value);
          this._checkIdle();
          this._tryStartJobs();
        })
        .catch(error => {
          this.runningCount--;
          this.failedCount++;
          reject(error);
          this._checkIdle();
          this._tryStartJobs();
        });
    }
  }

  private _checkIdle(): void {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      const resolvers = this.idleResolver;
      this.idleResolver = [];
      for (const resolve of resolvers) {
        resolve();
      }
    }
  }
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private _state: EditorState;
  private history: EditorState[] = [];
  private future: EditorState[] = [];
  private historyLimit: number;
  private listeners: {
    text: Array<(value: string, previous: string) => void>;
    cursor: Array<(value: number, previous: number) => void>;
    bold: Array<(value: boolean, previous: boolean) => void>;
  } = {
    text: [],
    cursor: [],
    bold: []
  };

  constructor(initial: EditorState, historyLimit: number) {
    // Deep copy the initial state to avoid external mutations affecting the store
    this._state = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = Math.max(1, Math.floor(historyLimit));
  }

  get state(): EditorState {
    // Return a new object with current values
    return {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    // Check if any field actually changes
    const newText = patch.text !== undefined ? patch.text : this._state.text;
    const newCursor = patch.cursor !== undefined ? patch.cursor : this._state.cursor;
    const newBold = patch.bold !== undefined ? patch.bold : this._state.bold;

    // If nothing changes, return false
    if (newText === this._state.text && newCursor === this._state.cursor && newBold === this._state.bold) {
      return false;
    }

    // Save current state to history before making changes
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Clear future since we're making a new change
    this.future = [];

    // Apply the changes
    this._state.text = newText;
    this._state.cursor = newCursor;
    this._state.bold = newBold;

    // Notify listeners
    this._notifyListeners(patch);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    // Create a draft copy of the current state
    const draft: EditorState = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    try {
      // Call the transaction function with the draft
      run(draft);

      // Apply the draft as a patch
      return this.apply(draft);
    } catch (error) {
      // If an error occurs, do nothing and rethrow
      throw error;
    }
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    // Save current state to future
    this.future.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Get previous state from history
    const previousState = this.history.pop()!;

    // Store the previous state before changing
    const previousStateForNotification = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    // Apply the previous state
    this._state = {
      text: previousState.text,
      cursor: previousState.cursor,
      bold: previousState.bold
    };

    // Notify listeners about changes
    this._notifyUndoRedoListeners(previousStateForNotification);

    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    // Save current state to history
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Get next state from future
    const nextState = this.future.pop()!;

    // Store the previous state before changing
    const previousStateForNotification = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    // Apply the next state
    this._state = {
      text: nextState.text,
      cursor: nextState.cursor,
      bold: nextState.bold
    };

    // Notify listeners about changes
    this._notifyUndoRedoListeners(previousStateForNotification);

    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    // Validate field
    if (field !== 'text' && field !== 'cursor' && field !== 'bold') {
      throw new Error('Invalid field. Must be "text", "cursor", or "bold".');
    }

    // Add listener to the appropriate array
    const listenersArray = this.listeners[field];
    listenersArray.push(listener as any);

    // Return a function to remove the listener
    return () => {
      const index = listenersArray.indexOf(listener as any);
      if (index !== -1) {
        listenersArray.splice(index, 1);
      }
    };
  }

  private _notifyListeners(patch: Partial<EditorState>): void {
    // Notify text listeners if text changed
    if (patch.text !== undefined) {
      const previousText = this.history.length > 0 ? this.history[this.history.length - 1].text : this._state.text;
      // Actually, we need the previous value before the change, which is the current state before applying the patch
      // But since we already updated _state, we need to get the previous value from the patch application logic
      // Let's fix this by storing previous values before applying changes
    }

    // Actually, let's fix the implementation to properly track previous values
    // We'll do this in the apply method itself
  }

  // Redesign the implementation to properly track previous values for notifications
  // This is a corrected version of the apply method
  private _applyWithNotification(patch: Partial<EditorState>): boolean {
    // Check if any field actually changes
    const newText = patch.text !== undefined ? patch.text : this._state.text;
    const newCursor = patch.cursor !== undefined ? patch.cursor : this._state.cursor;
    const newBold = patch.bold !== undefined ? patch.bold : this._state.bold;

    // If nothing changes, return false
    if (newText === this._state.text && newCursor === this._state.cursor && newBold === this._state.bold) {
      return false;
    }

    // Save current state to history before making changes
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Clear future since we're making a new change
    this.future = [];

    // Store previous values for notification
    const previousText = this._state.text;
    const previousCursor = this._state.cursor;
    const previousBold = this._state.bold;

    // Apply the changes
    this._state.text = newText;
    this._state.cursor = newCursor;
    this._state.bold = newBold;

    // Notify listeners
    if (patch.text !== undefined) {
      this.listeners.text.forEach(listener => listener(this._state.text, previousText));
    }
    if (patch.cursor !== undefined) {
      this.listeners.cursor.forEach(listener => listener(this._state.cursor, previousCursor));
    }
    if (patch.bold !== undefined) {
      this.listeners.bold.forEach(listener => listener(this._state.bold, previousBold));
    }

    return true;
  }

  // Redesign the transaction method to use the corrected apply
  private _transactionWithNotification(run: (draft: EditorState) => void): boolean {
    // Create a draft copy of the current state
    const draft: EditorState = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    try {
      // Call the transaction function with the draft
      run(draft);

      // Apply the draft as a patch
      return this._applyWithNotification(draft);
    } catch (error) {
      // If an error occurs, do nothing and rethrow
      throw error;
    }
  }

  // Redesign the undo method to properly track previous values for notifications
  private _undoWithNotification(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    // Save current state to future
    this.future.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Get previous state from history
    const previousState = this.history.pop()!;

    // Store the previous state before changing
    const previousStateForNotification = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    // Apply the previous state
    this._state = {
      text: previousState.text,
      cursor: previousState.cursor,
      bold: previousState.bold
    };

    // Notify listeners about changes
    if (previousStateForNotification.text !== this._state.text) {
      this.listeners.text.forEach(listener => listener(this._state.text, previousStateForNotification.text));
    }
    if (previousStateForNotification.cursor !== this._state.cursor) {
      this.listeners.cursor.forEach(listener => listener(this._state.cursor, previousStateForNotification.cursor));
    }
    if (previousStateForNotification.bold !== this._state.bold) {
      this.listeners.bold.forEach(listener => listener(this._state.bold, previousStateForNotification.bold));
    }

    return true;
  }

  // Redesign the redo method to properly track previous values for notifications
  private _redoWithNotification(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    // Save current state to history
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Get next state from future
    const nextState = this.future.pop()!;

    // Store the previous state before changing
    const previousStateForNotification = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    // Apply the next state
    this._state = {
      text: nextState.text,
      cursor: nextState.cursor,
      bold: nextState.bold
    };

    // Notify listeners about changes
    if (previousStateForNotification.text !== this._state.text) {
      this.listeners.text.forEach(listener => listener(this._state.text, previousStateForNotification.text));
    }
    if (previousStateForNotification.cursor !== this._state.cursor) {
      this.listeners.cursor.forEach(listener => listener(this._state.cursor, previousStateForNotification.cursor));
    }
    if (previousStateForNotification.bold !== this._state.bold) {
      this.listeners.bold.forEach(listener => listener(this._state.bold, previousStateForNotification.bold));
    }

    return true;
  }

  // Override the public methods with the corrected versions
  apply(patch: Partial<EditorState>): boolean {
    return this._applyWithNotification(patch);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    return this._transactionWithNotification(run);
  }

  undo(): boolean {
    return this._undoWithNotification();
  }

  redo(): boolean {
    return this._redoWithNotification();
  }

  // Helper method for undo/redo notifications
  private _notifyUndoRedoListeners(previousState: EditorState): void {
    if (previousState.text !== this._state.text) {
      this.listeners.text.forEach(listener => listener(this._state.text, previousState.text));
    }
    if (previousState.cursor !== this._state.cursor) {
      this.listeners.cursor.forEach(listener => listener(this._state.cursor, previousState.cursor));
    }
    if (previousState.bold !== this._state.bold) {
      this.listeners.bold.forEach(listener => listener(this._state.bold, previousState.bold));
    }
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

export function parseOrder(text: string): ParseResult {
  let obj: any;
  try {
    obj = JSON.parse(text);
  } catch (e) {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }

  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const errors: FieldError[] = [];
  const unknownOrderFields: string[] = [];
  const orderFields = Object.keys(obj);

  // Check for unknown fields in order and collect them in order of appearance
  for (const field of orderFields) {
    if (!['id', 'status', 'lines'].includes(field)) {
      unknownOrderFields.push(field);
    }
  }

  // Process id
  if (!(obj.id !== undefined && obj.id !== null)) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof obj.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (obj.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  }

  // Process status
  let statusValue: OrderStatus = OrderStatus.Draft;
  if (obj.status !== undefined && obj.status !== null) {
    if (obj.status === 'draft' || obj.status === 'paid' || obj.status === 'shipped') {
      statusValue = obj.status as OrderStatus;
    } else {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  }

  // Process lines
  let lines: any[] = [];
  if (!(obj.lines !== undefined && obj.lines !== null)) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(obj.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if (obj.lines.length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    lines = obj.lines;
  }

  // Process each line
  const orderLines: OrderLine[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const linePath = `lines[${i}]`;

    // Check if line is an object
    if (line === null || typeof line !== 'object' || Array.isArray(line)) {
      errors.push({ path: linePath, message: 'expected an object' });
      // Collect unknown fields for this line (if it's not an object, skip field checks)
      continue;
    }

    const lineFields = Object.keys(line);
    const unknownLineFields: string[] = [];

    // Collect unknown fields in order of appearance
    for (const field of lineFields) {
      if (!['sku', 'quantity', 'unitPrice'].includes(field)) {
        unknownLineFields.push(field);
      }
    }

    // Process sku
    if (!(line.sku !== undefined && line.sku !== null)) {
      errors.push({ path: `${linePath}.sku`, message: 'required' });
    } else if (typeof line.sku !== 'string') {
      errors.push({ path: `${linePath}.sku`, message: 'expected a string' });
    } else if (line.sku === '') {
      errors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
    }

    // Process quantity
    if (!(line.quantity !== undefined && line.quantity !== null)) {
      errors.push({ path: `${linePath}.quantity`, message: 'required' });
    } else if (typeof line.quantity !== 'number') {
      errors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
    } else if (!Number.isInteger(line.quantity) || line.quantity < 1) {
      errors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
    }

    // Process unitPrice
    if (!(line.unitPrice !== undefined && line.unitPrice !== null)) {
      errors.push({ path: `${linePath}.unitPrice`, message: 'required' });
    } else if (typeof line.unitPrice !== 'number') {
      errors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
    } else if (line.unitPrice < 0) {
      errors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
    }

    // Add unknown line fields
    for (const field of unknownLineFields) {
      errors.push({ path: `${linePath}.${field}`, message: 'unknown field' });
    }

    // If all required fields are valid, create OrderLine
    const skuValid = line.sku !== undefined && line.sku !== null && typeof line.sku === 'string' && line.sku !== '';
    const quantityValid = line.quantity !== undefined && line.quantity !== null && 
      typeof line.quantity === 'number' && Number.isInteger(line.quantity) && line.quantity >= 1;
    const unitPriceValid = line.unitPrice !== undefined && line.unitPrice !== null && 
      typeof line.unitPrice === 'number' && line.unitPrice >= 0;

    if (skuValid && quantityValid && unitPriceValid) {
      orderLines.push(new OrderLine(line.sku, line.quantity, line.unitPrice));
    }
  }

  // Add unknown order fields
  for (const field of unknownOrderFields) {
    errors.push({ path: field, message: 'unknown field' });
  }

  // If there are errors, return undefined order
  if (errors.length > 0) {
    return { order: undefined, errors };
  }

  // Otherwise, return the order
  return {
    order: {
      id: obj.id,
      status: statusValue,
      lines: orderLines
    },
    errors: []
  };
}

import { router } from '@ohos.router'

interface Address {
