import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';
import { promptAction } from '@kit.ArkUI';

const STORE_NAME: string = 'name_store';
const KEY_NAME: string = 'saved_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State inputName: string = '';
  private store: preferences.Preferences | undefined = undefined;

  aboutToAppear(): void {
    this.loadName();
  }

  onPageShow(): void {
    this.loadName();
  }

  private async getStore(): Promise<preferences.Preferences> {
    if (this.store !== undefined) {
      return this.store;
    }
    const context: common.UIAbilityContext = getContext(this) as common.UIAbilityContext;
    const options: preferences.Options = { name: STORE_NAME };
    const store: preferences.Preferences = await preferences.getPreferences(context, options);
    this.store = store;
    return store;
  }

  private async loadName(): Promise<void> {
    try {
      const store: preferences.Preferences = await this.getStore();
      const value: preferences.ValueType = await store.get(KEY_NAME, '');
      if (typeof value === 'string') {
        this.savedName = value;
      } else {
        this.savedName = '';
      }
    } catch (err) {
      this.savedName = '';
    }
  }

  private async saveName(): Promise<void> {
    const name: string = this.inputName.trim();
    if (name.length === 0) {
      const emptyOptions: promptAction.ShowToastOptions = { message: 'Please enter a name' };
      promptAction.showToast(emptyOptions);
      return;
    }
    try {
      const store: preferences.Preferences = await this.getStore();
      await store.put(KEY_NAME, name);
      await store.flush();
      this.savedName = name;
      const okOptions: promptAction.ShowToastOptions = { message: 'Name saved' };
      promptAction.showToast(okOptions);
    } catch (err) {
      const failOptions: promptAction.ShowToastOptions = { message: 'Failed to save name' };
      promptAction.showToast(failOptions);
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .width('100%')

      TextInput({ placeholder: 'Enter your name', text: this.inputName })
        .width('100%')
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('100%')
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .alignItems(HorizontalAlign.Start)
    .justifyContent(FlexAlign.Start)
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentTotal = result.get(expense.category) || 0;
    result.set(expense.category, currentTotal + expense.amount);
  }

  return result;
}

import storageManager from '@ohos.data.storageManager';

@Entry
@Component
struct WaterTrackerPage {
  @State count: number = 0
  @State goal: number = 8
  @State showGoalDialog: boolean = false

  // Storage key constants
  private static readonly COUNT_KEY = 'water_count'
  private static readonly GOAL_KEY = 'water_goal'

  // Load persisted data on initialization
  aboutToAppear() {
    this.loadState()
  }

  // Load data from storage
  loadState() {
    storageManager.getStorage().then((storage) => {
      this.count = storage.get(WaterTrackerPage.COUNT_KEY, 0) as number
      this.goal = storage.get(WaterTrackerPage.GOAL_KEY, 8) as number
    }).catch((err) => {
      console.error('Failed to load state:', err)
    })
  }

  // Save current state to storage
  saveState() {
    storageManager.getStorage().then((storage) => {
      storage.put(WaterTrackerPage.COUNT_KEY, this.count)
      storage.put(WaterTrackerPage.GOAL_KEY, this.goal)
    }).catch((err) => {
      console.error('Failed to save state:', err)
    })
  }

  // Add a glass
  addGlass() {
    this.count++
    this.saveState()
  }

  // Update goal and save
  updateGoal(newGoal: number) {
    this.goal = newGoal
    this.saveState()
  }

  // Dialog component
  @Component
  struct GoalDialog {
    @Prop goal: number
    @State newGoal: string = ''
    @State show: boolean = false
    @Event('onSave') onSave: (goal: number) => void
    @Event('onCancel') onCancel: () => void

    // Quick presets
    private presets: GoalPreset[] = [
      new GoalPreset('Light', 6),
      new GoalPreset('Standard', 8),
      new GoalPreset('Active', 12)
    ]

    // Apply preset to input field
    applyPreset(glasses: number) {
      this.newGoal = glasses.toString()
    }

    // Validate and save goal
    handleSave() {
      const value = parseInt(this.newGoal)
      if (!isNaN(value) && value >= 1 && Number.isInteger(value)) {
        this.onSave(value)
        this.show = false
      }
    }

    build() {
      ModalDialog({
        title: Text('Daily goal'),
        content: Column() {
          // Input field
          TextField({
            text: this.$newGoal,
            placeholder: 'Glasses per day'
          })
            .width('80%')
            .margin({ top: 10, bottom: 15 })

          // Quick preset buttons
          Row() {
            ForEach(this.presets, (preset: GoalPreset) => {
              Button(preset.label)
                .type(ButtonType.Capsule)
                .onClick(() => this.applyPreset(preset.glasses))
            }, (preset: GoalPreset) => preset.label)
          }
          .width('80%')
          .justifyContent(FlexAlign.SpaceEvenly)
          .margin({ bottom: 20 })

          // Action buttons
          Row() {
            Button('Cancel')
              .type(ButtonType.Capsule)
              .onClick(() => {
                this.onCancel()
                this.show = false
              })
              .margin({ right: 10 })

            Button('Save')
              .type(ButtonType.Capsule)
              .onClick(() => this.handleSave())
          }
          .width('80%')
          .justifyContent(FlexAlign.End)
        },
        cancelable: true,
        onCancel: () => {
          this.onCancel()
          this.show = false
        }
      })
        .onShow(() => {
          this.newGoal = ''
        })
        .onHide(() => {
          this.show = false
        })
    }
  }

  build() {
    Column() {
      // Main display
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(32)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 20 })

      // Goal reached message
      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .fontColor(Color.Green)
          .margin({ bottom: 30 })
      }

      // Add glass button
      Button('Add a glass')
        .width('80%')
        .height(50)
        .fontSize(18)
        .onClick(() => this.addGlass())
        .margin({ bottom: 15 })

      // Change goal button
      Button('Change goal')
        .type(ButtonType.Outline)
        .width('80%')
        .height(50)
        .fontSize(18)
        .onClick(() => {
          this.showGoalDialog = true
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .padding(20)

    // Goal dialog
    if (this.showGoalDialog) {
      GoalDialog({
        goal: this.goal,
        onSave: (newGoal: number) => {
          this.updateGoal(newGoal)
        },
        onCancel: () => {
          // Do nothing on cancel
        }
      })
        .show(this.showGoalDialog)
    }
  }
}

// Goal preset class
class GoalPreset {
  label: string
  glasses: number

  constructor(label: string, glasses: number) {
    this.label = label
    this.glasses = glasses
  }
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
}

import { promptAction } from '@ohos.promptAction';

@Entry
@Component
struct LogEntryPage {
  @State entries: LogEntry[] = [];
  @State isRefreshing: boolean = false;

  aboutToAppear() {
    // Initialize 3000 entries
    this.entries = this.generateEntries(1, 3000);
  }

  generateEntries(startId: number, endId: number): LogEntry[] {
    const result: LogEntry[] = [];
    for (let i = startId; i <= endId; i++) {
      let level: string;
      if (i % 50 === 0) {
        level = 'error';
      } else if (i % 10 === 0) {
        level = 'warning';
      } else {
        level = 'info';
      }
      result.push(new LogEntry(i, `Event ${i}`, level));
    }
    return result;
  }

  onRefresh() {
    this.isRefreshing = true;

    // Simulate 1 second delay
    setTimeout(() => {
      const highestId = this.entries.length > 0 ? this.entries[0].id : 0;
      const newEntries = this.generateEntries(highestId + 1, highestId + 5);

      // Add new entries at the top
      this.entries = [...newEntries, ...this.entries];
      this.isRefreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Text(` ${this.entries.length} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 })
        .textAlign(TextAlign.Center)

      List({ space: 8, initialIndex: 0 }) {
        ForEach(this.entries, (entry: LogEntry) => {
          LogEntryRow(entry)
        }, (item: LogEntry) => item.id.toString())
      }
      .width('100%')
      .height('80%')
      .scrollBar(BarState.AUTO)
      .onRefresh(() => {
        this.onRefresh();
      })
    }
    .width('100%')
    .height('100%')
  }
}

