/**
 * A user record.
 */
export interface User {
  id: number;
  name: string;
  email: string;
}

/**
 * The kind of a parsed JSON value.
 */
enum JsonKind {
  Null = 0,
  Bool = 1,
  Number = 2,
  String = 3,
  Array = 4,
  Object = 5
}

/**
 * A parsed JSON value. A single class with a kind tag keeps the code free of
 * `any`/`unknown` and of union-typed containers.
 */
class JsonValue {
  kind: JsonKind = JsonKind.Null;
  boolValue: boolean = false;
  numValue: number = 0;
  strValue: string = '';
  items: JsonValue[] = [];
  fields: Map<string, JsonValue> = new Map<string, JsonValue>();
}

/**
 * A small, strict, self-contained JSON parser.
 */
class JsonParser {
  private text: string;
  private pos: number = 0;
  private failed: boolean = false;

  constructor(text: string) {
    this.text = text;
  }

  /**
   * Parses the whole text. Returns null when the text is not valid JSON.
   */
  parseDocument(): JsonValue | null {
    this.skipWhitespace();
    const value: JsonValue | null = this.parseValue();
    if (value === null || this.failed) {
      return null;
    }
    this.skipWhitespace();
    if (this.pos !== this.text.length) {
      return null;
    }
    return value;
  }

  private fail(): JsonValue | null {
    this.failed = true;
    return null;
  }

  private skipWhitespace(): void {
    while (this.pos < this.text.length) {
      const c: string = this.text.charAt(this.pos);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.pos++;
      } else {
        break;
      }
    }
  }

  private parseValue(): JsonValue | null {
    if (this.failed) {
      return null;
    }
    this.skipWhitespace();
    if (this.pos >= this.text.length) {
      return this.fail();
    }
    const c: string = this.text.charAt(this.pos);
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      return this.parseString();
    }
    if (c === 't') {
      return this.parseKeyword('true', JsonKind.Bool, true);
    }
    if (c === 'f') {
      return this.parseKeyword('false', JsonKind.Bool, false);
    }
    if (c === 'n') {
      return this.parseKeyword('null', JsonKind.Null, false);
    }
    if (c === '-' || (c >= '0' && c <= '9')) {
      return this.parseNumber();
    }
    return this.fail();
  }

  private parseKeyword(word: string, kind: JsonKind, boolValue: boolean): JsonValue | null {
    if (this.text.substring(this.pos, this.pos + word.length) !== word) {
      return this.fail();
    }
    this.pos += word.length;
    const value: JsonValue = new JsonValue();
    value.kind = kind;
    value.boolValue = boolValue;
    return value;
  }

  private parseNumber(): JsonValue | null {
    const start: number = this.pos;
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '-') {
      this.pos++;
    }
    if (this.pos >= this.text.length) {
      return this.fail();
    }
    let c: string = this.text.charAt(this.pos);
    if (c === '0') {
      this.pos++;
    } else if (c >= '1' && c <= '9') {
      this.pos++;
      while (this.pos < this.text.length) {
        c = this.text.charAt(this.pos);
        if (c >= '0' && c <= '9') {
          this.pos++;
        } else {
          break;
        }
      }
    } else {
      return this.fail();
    }
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '.') {
      this.pos++;
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      c = this.text.charAt(this.pos);
      if (!(c >= '0' && c <= '9')) {
        return this.fail();
      }
      while (this.pos < this.text.length) {
        c = this.text.charAt(this.pos);
        if (c >= '0' && c <= '9') {
          this.pos++;
        } else {
          break;
        }
      }
    }
    if (this.pos < this.text.length) {
      c = this.text.charAt(this.pos);
      if (c === 'e' || c === 'E') {
        this.pos++;
        if (this.pos < this.text.length) {
          c = this.text.charAt(this.pos);
          if (c === '+' || c === '-') {
            this.pos++;
          }
        }
        if (this.pos >= this.text.length) {
          return this.fail();
        }
        c = this.text.charAt(this.pos);
        if (!(c >= '0' && c <= '9')) {
          return this.fail();
        }
        while (this.pos < this.text.length) {
          c = this.text.charAt(this.pos);
          if (c >= '0' && c <= '9') {
            this.pos++;
          } else {
            break;
          }
        }
      }
    }
    const raw: string = this.text.substring(start, this.pos);
    const num: number = Number(raw);
    if (isNaN(num)) {
      return this.fail();
    }
    const value: JsonValue = new JsonValue();
    value.kind = JsonKind.Number;
    value.numValue = num;
    return value;
  }

  private parseString(): JsonValue | null {
    // The current character is the opening quote.
    this.pos++;
    let out: string = '';
    let closed: boolean = false;
    while (!closed) {
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      const c: string = this.text.charAt(this.pos);
      if (c === '"') {
        this.pos++;
        closed = true;
      } else if (c === '\\') {
        this.pos++;
        if (this.pos >= this.text.length) {
          return this.fail();
        }
        const esc: string = this.text.charAt(this.pos);
        this.pos++;
        if (esc === '"') {
          out += '"';
        } else if (esc === '\\') {
          out += '\\';
        } else if (esc === '/') {
          out += '/';
        } else if (esc === 'b') {
          out += '\b';
        } else if (esc === 'f') {
          out += '\f';
        } else if (esc === 'n') {
          out += '\n';
        } else if (esc === 'r') {
          out += '\r';
        } else if (esc === 't') {
          out += '\t';
        } else if (esc === 'u') {
          if (this.pos + 4 > this.text.length) {
            return this.fail();
          }
          const hex: string = this.text.substring(this.pos, this.pos + 4);
          let code: number = 0;
          for (let i = 0; i < 4; i++) {
            const h: string = hex.charAt(i);
            let digit: number = -1;
            if (h >= '0' && h <= '9') {
              digit = h.charCodeAt(0) - 48;
            } else if (h >= 'a' && h <= 'f') {
              digit = h.charCodeAt(0) - 87;
            } else if (h >= 'A' && h <= 'F') {
              digit = h.charCodeAt(0) - 55;
            }
            if (digit < 0) {
              return this.fail();
            }
            code = code * 16 + digit;
          }
          this.pos += 4;
          out += String.fromCharCode(code);
        } else {
          return this.fail();
        }
      } else if (c.charCodeAt(0) < 0x20) {
        return this.fail();
      } else {
        out += c;
        this.pos++;
      }
    }
    const value: JsonValue = new JsonValue();
    value.kind = JsonKind.String;
    value.strValue = out;
    return value;
  }

  private parseArray(): JsonValue | null {
    // The current character is '['.
    this.pos++;
    const value: JsonValue = new JsonValue();
    value.kind = JsonKind.Array;
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === ']') {
      this.pos++;
      return value;
    }
    let done: boolean = false;
    while (!done) {
      const item: JsonValue | null = this.parseValue();
      if (item === null || this.failed) {
        return this.fail();
      }
      value.items.push(item);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      const c: string = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
      } else if (c === ']') {
        this.pos++;
        done = true;
      } else {
        return this.fail();
      }
    }
    return value;
  }

  private parseObject(): JsonValue | null {
    // The current character is '{'.
    this.pos++;
    const value: JsonValue = new JsonValue();
    value.kind = JsonKind.Object;
    this.skipWhitespace();
    if (this.pos < this.text.length && this.text.charAt(this.pos) === '}') {
      this.pos++;
      return value;
    }
    let done: boolean = false;
    while (!done) {
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      if (this.text.charAt(this.pos) !== '"') {
        return this.fail();
      }
      const keyValue: JsonValue | null = this.parseString();
      if (keyValue === null || this.failed) {
        return this.fail();
      }
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      if (this.text.charAt(this.pos) !== ':') {
        return this.fail();
      }
      this.pos++;
      const fieldValue: JsonValue | null = this.parseValue();
      if (fieldValue === null || this.failed) {
        return this.fail();
      }
      value.fields.set(keyValue.strValue, fieldValue);
      this.skipWhitespace();
      if (this.pos >= this.text.length) {
        return this.fail();
      }
      const c: string = this.text.charAt(this.pos);
      if (c === ',') {
        this.pos++;
      } else if (c === '}') {
        this.pos++;
        done = true;
      } else {
        return this.fail();
      }
    }
    return value;
  }
}

function isIntegerNumber(value: number): boolean {
  if (!isFinite(value)) {
    return false;
  }
  return Math.floor(value) === value;
}

/**
 * Reads a JSON text and returns the valid users it contains, in input order.
 * Never throws: invalid JSON or a non-array top level yields an empty array.
 */
export function parseUsers(json: string): User[] {
  const result: User[] = [];
  const parser: JsonParser = new JsonParser(json);
  const root: JsonValue | null = parser.parseDocument();
  if (root === null) {
    return result;
  }
  if (root.kind !== JsonKind.Array) {
    return result;
  }
  for (let i = 0; i < root.items.length; i++) {
    const element: JsonValue = root.items[i];
    if (element.kind !== JsonKind.Object) {
      continue;
    }
    const idValue: JsonValue | undefined = element.fields.get('id');
    const nameValue: JsonValue | undefined = element.fields.get('name');
    const emailValue: JsonValue | undefined = element.fields.get('email');
    if (idValue === undefined || nameValue === undefined || emailValue === undefined) {
      continue;
    }
    if (idValue.kind !== JsonKind.Number) {
      continue;
    }
    if (nameValue.kind !== JsonKind.String) {
      continue;
    }
    if (emailValue.kind !== JsonKind.String) {
      continue;
    }
    const id: number = idValue.numValue;
    if (!isIntegerNumber(id)) {
      continue;
    }
    const name: string = nameValue.strValue;
    if (name.length === 0) {
      continue;
    }
    const email: string = emailValue.strValue;
    if (email.indexOf('@') < 0) {
      continue;
    }
    const user: User = { id: id, name: name, email: email };
    result.push(user);
  }
  return result;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }

    const eventListeners = this.listeners.get(event)!;
    // Check if listener is already registered for this event
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }

    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    // Create a copy of the listeners array to ensure consistency during emit
    // This handles the requirement that changes during emit only affect later calls
    const eventListeners = this.listeners.get(event)!;
    const listenersCopy = [...eventListeners];

    for (const listener of listenersCopy) {
      listener(payload);
    }

    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    return this.listeners.get(event)!.length;
  }
}

// Define a Shape interface with a type tag for discrimination
interface Shape {
  type: 'circle' | 'rectangle' | 'triangle';
}

// Circle shape implementation
interface CircleShape extends Shape {
  type: 'circle';
  radius: number;
}

// Rectangle shape implementation
interface RectangleShape extends Shape {
  type: 'rectangle';
  width: number;
  height: number;
}

// Triangle shape implementation
interface TriangleShape extends Shape {
  type: 'triangle';
  base: number;
  height: number;
}

// Export the Shape type
export type Shape = CircleShape | RectangleShape | TriangleShape;

// Create a circle shape
export function circle(radius: number): Shape {
  return {
    type: 'circle',
    radius: radius
  };
}

// Create a rectangle shape
export function rectangle(width: number, height: number): Shape {
  return {
    type: 'rectangle',
    width: width,
    height: height
  };
}

// Create a triangle shape
export function triangle(base: number, height: number): Shape {
  return {
    type: 'triangle',
    base: base,
    height: height
  };
}

// Calculate area of a shape
export function area(shape: Shape): number {
  switch (shape.type) {
    case 'circle':
      return Math.PI * shape.radius * shape.radius;
    case 'rectangle':
      return shape.width * shape.height;
    case 'triangle':
      return shape.base * shape.height / 2;
    default:
      // This should never happen due to exhaustive type checking
      return 0;
  }
}

// Calculate total area of an array of shapes
export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + area(shape), 0);
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  // Handle invalid JSON
  let data: any;
  try {
    data = JSON.parse(json);
  } catch {
    return [];
  }

  // Check if top-level is an array
  if (!Array.isArray(data)) {
    return [];
  }

  const users: User[] = [];

  for (const item of data) {
    // Skip non-objects
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      continue;
    }

    // Check required fields exist
    if (!('id' in item) || !('name' in item) || !('email' in item)) {
      continue;
    }

    const { id, name, email } = item;

    // Validate id: must be a number and an integer
    if (typeof id !== 'number' || !Number.isInteger(id)) {
      continue;
    }

    // Validate name: must be a non-empty string
    if (typeof name !== 'string' || name.length === 0) {
      continue;
    }

    // Validate email: must be a string containing '@'
    if (typeof email !== 'string' || !email.includes('@')) {
      continue;
    }

    // Add valid user to result
    users.push({ id, name, email });
  }

  return users;
}

class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
    Object.setPrototypeOf(this, RetryError.prototype);
  }
}

async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  // Ensure at least 1 attempt
  const maxAttempts = Math.max(1, attempts);

  let lastError: Error | undefined;

  for (let i = 1; i <= maxAttempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error as Error;
      // If this is the last attempt, we'll throw the RetryError
      if (i === maxAttempts) {
        throw new RetryError(maxAttempts, lastError);
      }
    }
  }

  // This line should never be reached, but added for completeness
  throw new RetryError(maxAttempts, lastError || new Error('Unknown error'));
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  // If quantity is 0 or less, we want to remove the item
  if (quantity <= 0) {
    return items.filter(item => item.id !== id);
  }

  // Create a new array with updated item
  return items.map(item => {
    if (item.id === id) {
      // Create a new object with the updated quantity
      return {
        ...item,
        quantity: quantity
      };
    }
    // Return the original item unchanged
    return item;
  });
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  // Start with a copy of the original items array
  let result = [...items];

  // Apply each change in order
  for (const change of changes) {
    // Only apply the change if the item still exists in the result
    const itemExists = result.some(item => item.id === change.id);
    if (itemExists) {
      result = updateQuantity(result, change.id, change.quantity);
    }
  }

  return result;
}

