class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.map = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    // If key already exists, remove it from order first
    if (this.map.has(key)) {
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    }

    // Add to map and end of order array (most recently used)
    this.map.set(key, value);
    this.order.push(key);

    // If over capacity, remove least recently used (first in order array)
    if (this.map.size > this.capacity) {
      const lruKey = this.order.shift();
      if (lruKey !== undefined) {
        this.map.delete(lruKey);
      }
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }

    // Move key to end of order array (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (least to most recently used)
    return [...this.order];
  }

  get size(): number {
    return this.map.size;
  }
}

export default LruCache;

export type Pair<A, B> = {
  first: A;
  second: B;
};

export function chunk<T>(items: T[], size: number): T[][] {
  // Handle edge cases: empty array or invalid size
  if (items.length === 0 || size < 1) {
    return [];
  }

  const result: T[][] = [];

  // Process items in chunks of 'size'
  for (let i = 0; i < items.length; i += size) {
    // Create a new array for each chunk
    const chunkSize = Math.min(size, items.length - i);
    const chunk: T[] = [];

    for (let j = 0; j < chunkSize; j++) {
      chunk.push(items[i + j]);
    }

    result.push(chunk);
  }

  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  // Determine the length of the shorter array
  const minLength = Math.min(a.length, b.length);

  // Create result array
  const result: Pair<A, B>[] = [];

  // Zip elements together
  for (let i = 0; i < minLength; i++) {
    result.push({
      first: a[i],
      second: b[i]
    });
  }

  return result;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

export class Pipeline {
  private steps: { name: string; transform: Transform }[] = [];

  constructor() {}

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, transform: step });
    return this;
  }

  run(text: string): string {
    return this.steps.reduce((acc, step) => step.transform(acc), text);
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    return steps.reduce((acc, step) => step(acc), text);
  };
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return "0s";
  }

  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);

  const hours = Math.floor(absSeconds / 3600);
  const minutes = Math.floor((absSeconds % 3600) / 60);
  const seconds = absSeconds % 60;

  let result = "";

  if (hours > 0) {
    result += `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    result += `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    result += `${seconds}s`;
  }

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  // Handle empty string
  if (!text || text.trim() === "") {
    return NaN;
  }

  // Check for leading space or trailing space
  if (text !== text.trim()) {
    return NaN;
  }

  // Split by spaces and check for empty parts (consecutive spaces)
  const parts = text.split(" ");
  if (parts.some(part => part === "")) {
    return NaN;
  }

  let isNegative = false;
  let totalSeconds = 0;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Check for negative sign on first part only
    if (i === 0 && part.startsWith("-")) {
      isNegative = true;
      const rest = part.substring(1);
      if (rest === "") {
        return NaN;
      }
      const parsed = parsePart(rest);
      if (isNaN(parsed)) {
        return NaN;
      }
      totalSeconds += parsed;
      continue;
    }

    const parsed = parsePart(part);
    if (isNaN(parsed)) {
      return NaN;
    }
    totalSeconds += parsed;
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

function parsePart(part: string): number {
  // Match pattern: one or more digits followed by h, m, or s
  const match = part.match(/^(\d+)([hms])$/);
  if (!match) {
    return NaN;
  }

  const value = parseInt(match[1], 10);
  const unit = match[2];

  switch (unit) {
    case 'h':
      return value * 3600;
    case 'm':
      return value * 60;
    case 's':
      return value;
    default:
      return NaN;
  }
}

