export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Get all days that have at least one rule
  const daysWithRules = new Set<Weekday>();
  for (const rule of rules) {
    daysWithRules.add(rule.day);
  }

  // If no day has rules, return undefined
  if (daysWithRules.size === 0) {
    return undefined;
  }

  // Start checking from the next day after the given day
  let currentDay = (day + 1) % 7;

  // Check all days in order until we find one with rules or come back to the original day
  while (currentDay !== day) {
    if (daysWithRules.has(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  // If we've checked all days and only the original day has rules, return it
  if (daysWithRules.has(day)) {
    return day;
  }

  // This shouldn't happen if daysWithRules is not empty, but just in case
  return undefined;
}

