export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query.length === 0) {
    return result;
  }

  // Split by '&' and process each pair
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty parts
    if (pair.length === 0) {
      continue;
    }

    // Split at first '='
    const eqIndex = pair.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found, entire string is key with empty value
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    key = decodeComponent(key);
    value = decodeComponent(value);

    // Add to map (last value wins, but keep first position)
    result.set(key, value);
  }

  return result;
}

// Helper function to decode URL components
function decodeComponent(str: string): string {
  // Replace '+' with space
  let result = str.replace(/\+/g, ' ');

  // Process percent-escapes
  let i = 0;
  let decoded = '';

  while (i < result.length) {
    if (result[i] === '%' && i + 2 < result.length) {
      const hex = result.substring(i + 1, i + 3);
      // Check if it's a valid hex sequence
      if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
        try {
          const byte1 = parseInt(hex.substring(0, 2), 16);
          // Check for valid UTF-8 sequences
          if (byte1 < 0x80) {
            // ASCII character
            decoded += String.fromCharCode(byte1);
            i += 3;
            continue;
          } else if (byte1 >= 0xC0 && byte1 <= 0xDF) {
            // 2-byte sequence
            if (i + 5 < result.length && result[i + 3] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 4, i + 6))) {
              const byte2 = parseInt(result.substring(i + 4, i + 6), 16);
              if ((byte2 & 0xC0) === 0x80) {
                const codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
                decoded += String.fromCharCode(codePoint);
                i += 6;
                continue;
              }
            }
          } else if (byte1 >= 0xE0 && byte1 <= 0xEF) {
            // 3-byte sequence
            if (i + 8 < result.length && result[i + 3] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 4, i + 6)) &&
                result[i + 6] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 7, i + 9))) {
              const byte2 = parseInt(result.substring(i + 4, i + 6), 16);
              const byte3 = parseInt(result.substring(i + 7, i + 9), 16);
              if ((byte2 & 0xC0) === 0x80 && (byte3 & 0xC0) === 0x80) {
                const codePoint = ((byte1 & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F);
                decoded += String.fromCharCode(codePoint);
                i += 9;
                continue;
              }
            }
          } else if (byte1 >= 0xF0 && byte1 <= 0xF7) {
            // 4-byte sequence
            if (i + 11 < result.length && result[i + 3] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 4, i + 6)) &&
                result[i + 6] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 7, i + 9)) &&
                result[i + 9] === '%' && 
                /^[0-9A-Fa-f]{2}$/.test(result.substring(i + 10, i + 12))) {
              const byte2 = parseInt(result.substring(i + 4, i + 6), 16);
              const byte3 = parseInt(result.substring(i + 7, i + 9), 16);
              const byte4 = parseInt(result.substring(i + 10, i + 12), 16);
              if ((byte2 & 0xC0) === 0x80 && (byte3 & 0xC0) === 0x80 && (byte4 & 0xC0) === 0x80) {
                const codePoint = ((byte1 & 0x07) << 18) | ((byte2 & 0x3F) << 12) | ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
                // Use surrogate pairs for code points > 0xFFFF
                if (codePoint > 0xFFFF) {
                  const high = 0xD800 + ((codePoint - 0x10000) >> 10);
                  const low = 0xDC00 + ((codePoint - 0x10000) & 0x3FF);
                  decoded += String.fromCharCode(high, low);
                } else {
                  decoded += String.fromCharCode(codePoint);
                }
                i += 12;
                continue;
              }
            }
          }
        } catch (e) {
          // If any error occurs, fall through to keep original
        }
      }
    }

    // If we couldn't decode, just add the character as is
    decoded += result[i];
    i++;
  }

  return decoded;
}

import { logger } from '@ohos.logger';

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';
  @State emailError: string = '';
  @State passwordError: string = '';
  @State isSignInEnabled: boolean = false;

  // Email validation: exactly one '@', at least one char before, and after '@' a '.' with at least one char on each side
  validateEmail(email: string): boolean {
    if (email.isEmpty()) {
      return true; // Empty is considered valid (no error shown)
    }

    // Check for exactly one '@'
    const atIndex = email.indexOf('@');
    if (atIndex === -1 || email.indexOf('@', atIndex + 1) !== -1) {
      return false;
    }

    // Check at least one char before '@'
    if (atIndex === 0) {
      return false;
    }

    // Check for '.' after '@' with at least one char on each side
    const domainPart = email.substring(atIndex + 1);
    const dotIndex = domainPart.indexOf('.');
    if (dotIndex === -1 || dotIndex === 0 || dotIndex === domainPart.length - 1) {
      return false;
    }

    return true;
  }

  // Password validation: at least 8 characters
  validatePassword(password: string): boolean {
    return password.length >= 8;
  }

  // Update validation messages and button state
  updateValidation() {
    // Email validation
    if (this.email.isEmpty()) {
      this.emailError = '';
    } else if (!this.validateEmail(this.email)) {
      this.emailError = 'Enter a valid email address';
    } else {
      this.emailError = '';
    }

    // Password validation
    if (this.password.isEmpty()) {
      this.passwordError = '';
    } else if (!this.validatePassword(this.password)) {
      this.passwordError = 'Password must be at least 8 characters';
    } else {
      this.passwordError = '';
    }

    // Enable sign-in only if both fields are valid
    this.isSignInEnabled = this.validateEmail(this.email) && this.validatePassword(this.password);
  }

  build() {
    Column() {
      Text('Sign In')
        .fontSize(32)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 30 })

      Column() {
        // Email input
        TextField({
          placeholder: 'Email',
          text: this.$email,
          inputType: InputType.Email
        })
          .width('90%')
          .height(50)
          .fontSize(16)
          .border({ width: 1, color: '#cccccc', radius: 8 })
          .padding(10)
          .onChange((value: string) => {
            this.updateValidation();
          })

        // Email error message
        if (!this.emailError.isEmpty()) {
          Text(this.emailError)
            .fontSize(12)
            .fontColor('#ff0000')
            .margin({ top: 5, bottom: 5 })
        }

        // Password input
        TextField({
          placeholder: 'Password',
          text: this.$password,
          inputType: InputType.Password
        })
          .width('90%')
          .height(50)
          .fontSize(16)
          .border({ width: 1, color: '#cccccc', radius: 8 })
          .padding(10)
          .onChange((value: string) => {
            this.updateValidation();
          })

        // Password error message
        if (!this.passwordError.isEmpty()) {
          Text(this.passwordError)
            .fontSize(12)
            .fontColor('#ff0000')
            .margin({ top: 5, bottom: 5 })
        }
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)

      // Sign in button
      Button('Sign in')
        .width('90%')
        .height(50)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .backgroundColor(this.isSignInEnabled ? '#007DFF' : '#cccccc')
        .enabled(this.isSignInEnabled)
        .onClick(() => {
          logger.info('Sign in button clicked');
        })
        .margin({ top: 20 })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Start)
  }
}

