import http from '@ohos.net.http';
import { BusinessError } from '@ohos.base';

@Entry
@Component
struct SolutionPage {
  @State items: Array<{ id: number, name: string }> = [];
  @State isLoading: boolean = true;
  @State isError: boolean = false;

  aboutToAppear(): void {
    this.fetchItems();
  }

  fetchItems(): void {
    this.isLoading = true;
    this.isError = false;

    try {
      const request = http.createHttp();

      request.request(
        'https://example.com/api/items',
        {
          method: http.HttpMethod.GET,
          header: {
            'Content-Type': 'application/json'
          }
        },
        (err: BusinessError, data: http.HttpResponse) => {
          if (err) {
            console.error('HTTP request failed:', err.message);
            this.isLoading = false;
            this.isError = true;
            return;
          }

          // Check if status code is 200
          if (data.responseCode === http.HttpResponseCode.OK) {
            try {
              // Parse the response body
              const result = JSON.parse(data.result as string);

              // Validate that it's an array
              if (Array.isArray(result)) {
                this.items = result;
              } else {
                throw new Error('Response is not an array');
              }
            } catch (parseError) {
              console.error('Failed to parse response:', parseError);
              this.isError = true;
            }
          } else {
            console.error(`Server returned status code: ${data.responseCode}`);
            this.isError = true;
          }

          this.isLoading = false;
        }
      );
    } catch (error) {
      console.error('HTTP request initialization failed:', error);
      this.isLoading = false;
      this.isError = true;
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
      } else if (this.isError) {
        Text('Could not load the items')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .fontColor(Color.Red)
      } else {
        List({ space: 8 }) {
          ForEach(this.items, (item: { id: number, name: string }) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
            }
          }, (item: { id: number, name: string }) => item.id.toString())
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

