@State var nameInput: string = "";

interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const length = source.length;

  while (i < length) {
    const char = source[i];

    // Skip spaces
    if (char === ' ') {
      i++;
      continue;
    }

    // Numbers: digits, optionally followed by '.' and more digits
    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < length && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      if (i < length && source[i] === '.' && i + 1 < length && source[i + 1] >= '0' && source[i + 1] <= '9') {
        i++; // consume '.'
        while (i < length && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Names: letter or underscore, followed by letters, digits, or underscores
    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < length && (
        (source[i] >= 'a' && source[i] <= 'z') ||
        (source[i] >= 'A' && source[i] <= 'Z') ||
        (source[i] >= '0' && source[i] <= '9') ||
        source[i] === '_'
      )) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Operators and parentheses
    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({
        kind: 'paren',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  // First tokenize
  const tokens = tokenize(source);

  // If no tokens, handle empty source
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  // Parser state
  let pos = 0;

  function peek(): Token | undefined {
    return tokens[pos];
  }

  function consume(): Token {
    const token = tokens[pos];
    pos++;
    return token;
  }

  function expect(kind: string, text?: string): Token {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    if (token.kind !== kind || (text !== undefined && token.text !== text)) {
      throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
    }
    return consume();
  }

  // Grammar:
  // expression   := term (('+' | '-') term)*
  // term         := unary (('*' | '/' | '%') unary)*
  // unary        := '-' unary | primary
  // primary      := number | name | '(' expression ')'

  function parseExpression(): number {
    let left = parseTerm();

    while (peek() && (peek().text === '+' || peek().text === '-')) {
      const op = consume().text;
      const right = parseTerm();
      if (op === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }

    return left;
  }

  function parseTerm(): number {
    let left = parseUnary();

    while (peek() && (peek().text === '*' || peek().text === '/' || peek().text === '%')) {
      const op = consume().text;
      const right = parseUnary();
      if (op === '*') {
        left = left * right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', pos - 1);
        }
        left = left / right;
      } else { // op === '%'
        if (right === 0) {
          throw new ExpressionError('Division by zero', pos - 1);
        }
        left = left % right;
      }
    }

    return left;
  }

  function parseUnary(): number {
    if (peek() && peek().text === '-') {
      consume(); // consume '-'
      const value = parseUnary();
      return -value;
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      consume();
      return Number(token.text);
    }

    if (token.kind === 'name') {
      consume();
      if (!(token.text in variables)) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return variables[token.text];
    }

    if (token.kind === 'paren' && token.text === '(') {
      consume(); // consume '('
      const value = parseExpression();
      expect('paren', ')');
      return value;
    }

    // Unexpected token where operand expected
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  // Start parsing
  const result = parseExpression();

  // Check for extra tokens after the expression
  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

