interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class JobQueue {
  private concurrency: number;
  private runningCount: number = 0;
  private waitingJobs: Array<{ job: () => Promise<any>, resolve: (value: any) => void, reject: (reason: Error) => void }> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private idleResolver: (() => void) | null = null;
  private idlePromise: Promise<void> | null = null;

  constructor(concurrency: number) {
    this.concurrency = Math.max(1, Math.floor(concurrency));
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this._startWaitingJobs();
  }

  clear(): number {
    const removedCount = this.waitingJobs.length;
    const error = new Error('Job was cancelled');

    for (const jobInfo of this.waitingJobs) {
      jobInfo.reject(error);
    }

    this.waitingJobs = [];
    this._checkIdle();

    return removedCount;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    if (!this.idlePromise) {
      this.idlePromise = new Promise<void>(resolve => {
        this.idleResolver = resolve;
      });
    }

    return this.idlePromise;
  }

  async runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = new Array(jobs.length);
    const promises: Promise<void>[] = [];

    for (let i = 0; i < jobs.length; i++) {
      const jobIndex = i;
      const job = jobs[jobIndex];

      const promise = this.add(job)
        .then(value => {
          outcomes[jobIndex] = { ok: true, value, error: undefined };
        })
        .catch(error => {
          outcomes[jobIndex] = { ok: false, value: undefined, error };
        });

      promises.push(promise);
    }

    await Promise.all(promises);
    return outcomes;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({
        job,
        resolve: resolve as (value: any) => void,
        reject: reject as (reason: Error) => void
      });

      this._startWaitingJobs();
    });
  }

  private _startWaitingJobs(): void {
    while (
      this.runningCount < this.concurrency &&
      this.waitingJobs.length > 0 &&
      !this.paused
    ) {
      const jobInfo = this.waitingJobs.shift();
      if (!jobInfo) break;

      this.runningCount++;

      try {
        const promise = jobInfo.job();

        promise
          .then(value => {
            this.runningCount--;
            this.completedCount++;
            jobInfo.resolve(value);
            this._checkIdle();
            this._startWaitingJobs();
          })
          .catch(error => {
            this.runningCount--;
            this.failedCount++;
            jobInfo.reject(error);
            this._checkIdle();
            this._startWaitingJobs();
          });
      } catch (error) {
        // This shouldn't happen per spec, but just in case
        this.runningCount--;
        this.failedCount++;
        jobInfo.reject(error as Error);
        this._checkIdle();
        this._startWaitingJobs();
      }
    }
  }

  private _checkIdle(): void {
    if (this.runningCount === 0 && this.waitingJobs.length === 0 && this.idleResolver) {
      const resolver = this.idleResolver;
      this.idleResolver = null;
      this.idlePromise = null;
      resolver();
    }
  }
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private state: EditorState;
  private history: EditorState[];
  private historyIndex: number;
  private historyLimit: number;
  private listeners: {
    text: Array<(value: string, previous: string) => void>;
    cursor: Array<(value: number, previous: number) => void>;
    bold: Array<(value: boolean, previous: boolean) => void>;
  };

  constructor(initial: EditorState, historyLimit: number) {
    this.state = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold,
    };
    this.historyLimit = Math.max(1, historyLimit);
    this.history = [];
    this.historyIndex = -1;
    this.listeners = {
      text: [],
      cursor: [],
      bold: [],
    };
  }

  get state(): EditorState {
    return {
      text: this.state.text,
      cursor: this.state.cursor,
      bold: this.state.bold,
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    const previousState = {
      text: this.state.text,
      cursor: this.state.cursor,
      bold: this.state.bold,
    };

    let changed = false;

    if (patch.text !== undefined) {
      this.state.text = patch.text;
      changed = true;
    }

    if (patch.cursor !== undefined) {
      this.state.cursor = patch.cursor;
      changed = true;
    }

    if (patch.bold !== undefined) {
      this.state.bold = patch.bold;
      changed = true;
    }

    if (!changed) {
      return false;
    }

    // Clear redo history
    this.history = this.history.slice(0, this.historyIndex + 1);

    // Add new state to history
    this.history.push({
      text: previousState.text,
      cursor: previousState.cursor,
      bold: previousState.bold,
    });

    // Enforce history limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    } else {
      this.historyIndex++;
    }

    // Notify listeners
    this.notifyListeners(previousState);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = {
      text: this.state.text,
      cursor: this.state.cursor,
      bold: this.state.bold,
    };

    try {
      run(draft);
    } catch (e) {
      throw e;
    }

    return this.apply(draft);
  }

  undo(): boolean {
    if (this.historyIndex < 0) {
      return false;
    }

    const previousState = this.state;
    const previousHistoryState = this.history[this.historyIndex];

    this.state = {
      text: previousHistoryState.text,
      cursor: previousHistoryState.cursor,
      bold: previousHistoryState.bold,
    };

    this.historyIndex--;

    this.notifyListeners(previousState);

    return true;
  }

  redo(): boolean {
    if (this.historyIndex >= this.history.length - 1) {
      return false;
    }

    this.historyIndex++;

    const previousState = this.state;
    const nextHistoryState = this.history[this.historyIndex];

    this.state = {
      text: nextHistoryState.text,
      cursor: nextHistoryState.cursor,
      bold: nextHistoryState.bold,
    };

    this.notifyListeners(previousState);

    return true;
  }

  get canUndo(): boolean {
    return this.historyIndex >= 0;
  }

  get canRedo(): boolean {
    return this.historyIndex < this.history.length - 1;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (field === 'text') {
      this.listeners.text.push(listener as (value: string, previous: string) => void);
      return () => {
        const index = this.listeners.text.indexOf(listener as (value: string, previous: string) => void);
        if (index !== -1) {
          this.listeners.text.splice(index, 1);
        }
      };
    } else if (field === 'cursor') {
      this.listeners.cursor.push(listener as (value: number, previous: number) => void);
      return () => {
        const index = this.listeners.cursor.indexOf(listener as (value: number, previous: number) => void);
        if (index !== -1) {
          this.listeners.cursor.splice(index, 1);
        }
      };
    } else if (field === 'bold') {
      this.listeners.bold.push(listener as (value: boolean, previous: boolean) => void);
      return () => {
        const index = this.listeners.bold.indexOf(listener as (value: boolean, previous: boolean) => void);
        if (index !== -1) {
          this.listeners.bold.splice(index, 1);
        }
      };
    } else {
      throw new Error('Invalid field name');
    }
  }

  private notifyListeners(previousState: EditorState): void {
    // Notify text listeners
    if (this.state.text !== previousState.text) {
      for (const listener of this.listeners.text) {
        listener(this.state.text, previousState.text);
      }
    }

    // Notify cursor listeners
    if (this.state.cursor !== previousState.cursor) {
      for (const listener of this.listeners.cursor) {
        listener(this.state.cursor, previousState.cursor);
      }
    }

    // Notify bold listeners
    if (this.state.bold !== previousState.bold) {
      for (const listener of this.listeners.bold) {
        listener(this.state.bold, previousState.bold);
      }
    }
  }
}

