// LogEntry class
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

// LogEntryRow component
@Component
struct LogEntryRow {
  @Prop entry: LogEntry;

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontWeight(FontWeight.Normal)
        .margin({ right: 10 })
      Text(this.entry.level)
        .fontSize(14)
        .fontWeight(FontWeight.Bold)
        .fontColor(this.getLevelColor(this.entry.level))
    }
    .padding(10)
    .backgroundColor(Color.White)
    .borderBottom({ width: 1, color: '#E0E0E0' })
  }

  @Builder getLevelColor(level: string): string {
    switch (level) {
      case 'error':
        return '#D32F2F';
      case 'warning':
        return '#F57C00';
      case 'info':
        return '#757575';
      default:
        return '#757575';
    }
  }
}

// Main page component
@Entry
@Component
struct LogPage {
  @State entries: LogEntry[] = [];
  @State isRefreshing: boolean = false;

  aboutToAppear() {
    // Create initial 3000 entries
    this.entries = [];
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
  }

  build() {
    Column() {
      // Header with entry count
      Text(`${this.entries.length} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10, left: 10, right: 10 })

      // Scrollable list with pull-to-refresh
      List({ space: 0, initialIndex: 0 }) {
        LazyForEach(this.entries.slice().reverse(), (entry: LogEntry) => {
          LogEntryRow({ entry: entry })
        }, (entry: LogEntry) => entry.id)
      }
      .width('100%')
      .height('100%')
      .scrollBar(BarState.Off)
      .onRefresh(() => {
        this.isRefreshing = true;
        // Simulate 1 second refresh delay
        setTimeout(() => {
          this.addNewEntries();
          this.isRefreshing = false;
        }, 1000);
      })
      .refreshStatus((status: RefreshStatus) => {
        if (status === RefreshStatus.Refreshing) {
          this.isRefreshing = true;
        } else {
          this.isRefreshing = false;
        }
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.Gray)
  }

  addNewEntries() {
    const highestId = this.entries.length > 0 ? this.entries[0].id : 0;
    const newEntries: LogEntry[] = [];
    for (let i = 1; i <= 5; i++) {
      newEntries.push(new LogEntry(highestId + i));
    }
    // Add new entries at the beginning (highest id first)
    this.entries = newEntries.concat(this.entries);
  }
}

interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const currentTotal = result.get(expense.category);

    if (currentTotal === undefined) {
      result.set(expense.category, expense.amount);
    } else {
      result.set(expense.category, currentTotal + expense.amount);
    }
  }

  return result;
}

struct BuildPlan {
  private spec: Record<string, string[]>
  private orderCache: string[] | undefined
  private layersCache: string[][] | undefined

  constructor(spec: Record<string, string[]>) {
    this.spec = spec

    // Check for missing dependencies
    const keys = Object.keys(spec)
    for (let i = 0; i < keys.length; i++) {
      const task = keys[i]
      const deps = spec[task]
      for (let j = 0; j < deps.length; j++) {
        const dependency = deps[j]
        if (!(dependency in spec)) {
          throw new MissingDependencyError(task, dependency)
        }
      }
    }

    // Check for cycles during order computation
    const placed = new Set<string>()
    const placing = new Set<string>()
    const order: string[] = []

    const placeTask = (task: string): void => {
      if (placed.has(task)) {
        return
      }

      if (placing.has(task)) {
        // Found a cycle - build the path
        const path: string[] = []
        let found = false
        for (let i = 0; i < keys.length; i++) {
          const key = keys[i]
          if (key === task) {
            found = true
          }
          if (found) {
            path.push(key)
          }
        }
        // Continue collecting until we find the task again
        // Actually, we need to reconstruct the path from the placing stack
        // Let's do this properly by tracking the actual path
        throw new CycleError(path)
      }

      placing.add(task)

      // Place dependencies first
      const deps = spec[task]
      for (let i = 0; i < deps.length; i++) {
        const dep = deps[i]
        placeTask(dep)
      }

      placing.delete(task)
      placed.add(task)
      order.push(task)
    }

    // Process tasks in key order
    for (let i = 0; i < keys.length; i++) {
      const task = keys[i]
      placeTask(task)
    }

    this.orderCache = order
  }

  order(): string[] {
    if (this.orderCache === undefined) {
      this.computeOrderAndLayers()
    }
    return [...this.orderCache]
  }

  layers(): string[][] {
    if (this.layersCache === undefined) {
      this.computeOrderAndLayers()
    }
    if (this.layersCache.length === 0) {
      return []
    }
    return this.layersCache.map(layer => [...layer])
  }

  dependentsOf(name: string): string[] {
    const order = this.order()
    const result: string[] = []
    let found = false

    for (let i = 0; i < order.length; i++) {
      const task = order[i]
      if (task === name) {
        found = true
        continue
      }
      if (found) {
        // Check if this task depends on name (directly or indirectly)
        if (this.dependsOn(task, name, new Set<string>())) {
          result.push(task)
        }
      }
    }

    return result
  }

  private dependsOn(task: string, target: string, visited: Set<string>): boolean {
    if (visited.has(task)) {
      return false
    }
    visited.add(task)

    const deps = this.spec[task]
    for (let i = 0; i < deps.length; i++) {
      const dep = deps[i]
      if (dep === target) {
        return true
      }
      if (this.dependsOn(dep, target, visited)) {
        return true
      }
    }

    return false
  }

  private computeOrderAndLayers(): void {
    const keys = Object.keys(this.spec)
    const placed = new Set<string>()
    const placing = new Set<string>()
    const order: string[] = []

    const placeTask = (task: string): void => {
      if (placed.has(task)) {
        return
      }

      if (placing.has(task)) {
        // Found a cycle - build the path
        const path: string[] = []
        let inCycle = false
        for (let i = 0; i < keys.length; i++) {
          const key = keys[i]
          if (key === task) {
            inCycle = true
          }
          if (inCycle) {
            path.push(key)
          }
        }
        // Add the task again to complete the cycle
        path.push(task)
        throw new CycleError(path)
      }

      placing.add(task)

      // Place dependencies first
      const deps = this.spec[task]
      for (let i = 0; i < deps.length; i++) {
        const dep = deps[i]
        placeTask(dep)
      }

      placing.delete(task)
      placed.add(task)
      order.push(task)
    }

    // Process tasks in key order
    for (let i = 0; i < keys.length; i++) {
      const task = keys[i]
      placeTask(task)
    }

    this.orderCache = order

    // Compute layers
    const layerMap = new Map<string, number>()

    const computeLayer = (task: string): number => {
      if (layerMap.has(task)) {
        return layerMap.get(task)!
      }

      const deps = this.spec[task]
      let maxDepLayer = -1

      for (let i = 0; i < deps.length; i++) {
        const dep = deps[i]
        const depLayer = computeLayer(dep)
        if (depLayer > maxDepLayer) {
          maxDepLayer = depLayer
        }
      }

      const layer = maxDepLayer + 1
      layerMap.set(task, layer)
      return layer
    }

    // Compute layers for all tasks
    for (let i = 0; i < keys.length; i++) {
      const task = keys[i]
      computeLayer(task)
    }

    // Group by layer
    const layers: string[][] = []
    for (let i = 0; i < keys.length; i++) {
      const task = keys[i]
      const layer = layerMap.get(task)!
      while (layers.length <= layer) {
        layers.push([])
      }
      layers[layer].push(task)
    }

    this.layersCache = layers
  }
}

class MissingDependencyError extends Error {
  task: string
  dependency: string

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`)
    this.task = task
    this.dependency = dependency
  }
}

class CycleError extends Error {
  path: string[]

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`)
    this.path = path
  }
}

import { router, promptAction } from '@kit.ArkUI';

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

export function parseOrder(text: string): ParseResult {
  let obj: any;
  try {
    obj = JSON.parse(text);
  } catch (e) {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }

  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const errors: FieldError[] = [];

  // Check id field
  if (!(obj.id !== undefined && obj.id !== null)) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof obj.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (obj.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  }

  // Check status field
  let status: OrderStatus | undefined = undefined;
  if (obj.status !== undefined && obj.status !== null) {
    if (obj.status === 'draft' || obj.status === 'paid' || obj.status === 'shipped') {
      status = obj.status as OrderStatus;
    } else {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  } else {
    status = OrderStatus.Draft;
  }

  // Check lines field
  let lines: any[] | undefined = undefined;
  if (!(obj.lines !== undefined && obj.lines !== null)) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(obj.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if (obj.lines.length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    lines = obj.lines;
  }

  // Process lines if we have an array
  const orderLines: OrderLine[] = [];
  if (lines !== undefined) {
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const linePath = 'lines[' + i + ']';

      // Check if line is an object
      if (line === null || typeof line !== 'object' || Array.isArray(line)) {
        errors.push({ path: linePath, message: 'expected an object' });
        continue;
      }

      // Check sku field
      if (!(line.sku !== undefined && line.sku !== null)) {
        errors.push({ path: linePath + '.sku', message: 'required' });
      } else if (typeof line.sku !== 'string') {
        errors.push({ path: linePath + '.sku', message: 'expected a string' });
      } else if (line.sku === '') {
        errors.push({ path: linePath + '.sku', message: 'must not be empty' });
      }

      // Check quantity field
      let quantity: number | undefined = undefined;
      if (!(line.quantity !== undefined && line.quantity !== null)) {
        errors.push({ path: linePath + '.quantity', message: 'required' });
      } else if (typeof line.quantity !== 'number') {
        errors.push({ path: linePath + '.quantity', message: 'expected a number' });
      } else if (!Number.isInteger(line.quantity) || line.quantity < 1) {
        errors.push({ path: linePath + '.quantity', message: 'must be a whole number of 1 or more' });
      } else {
        quantity = line.quantity;
      }

      // Check unitPrice field
      let unitPrice: number | undefined = undefined;
      if (!(line.unitPrice !== undefined && line.unitPrice !== null)) {
        errors.push({ path: linePath + '.unitPrice', message: 'required' });
      } else if (typeof line.unitPrice !== 'number') {
        errors.push({ path: linePath + '.unitPrice', message: 'expected a number' });
      } else if (line.unitPrice < 0) {
        errors.push({ path: linePath + '.unitPrice', message: 'must be 0 or more' });
      } else {
        unitPrice = line.unitPrice;
      }

      // Check for unknown fields in this line
      for (const key in line) {
        if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
          errors.push({ path: linePath + '.' + key, message: 'unknown field' });
        }
      }

      // If we have valid quantity and unitPrice, create OrderLine
      if (quantity !== undefined && unitPrice !== undefined) {
        orderLines.push(new OrderLine(line.sku, quantity, unitPrice));
      }
    }
  }

  // Check for unknown fields in the order object
  for (const key in obj) {
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  // Build result
  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  } else {
    return {
      order: {
        id: obj.id,
        status: status as OrderStatus,
        lines: orderLines
      },
      errors: []
    };
  }
}

