export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) {
      minX = point.x;
    }
    if (point.y < minY) {
      minY = point.y;
    }
    if (point.x > maxX) {
      maxX = point.x;
    }
    if (point.y > maxY) {
      maxY = point.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY
  };
}

struct Stack<T> {
  private data: T[] = [];
  private capacity: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.data.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.data.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.data[this.data.length - 1];
  }

  size(): number {
    return this.data.length;
  }

  isEmpty(): boolean {
    return this.data.length === 0;
  }

  isFull(): boolean {
    return this.data.length >= this.capacity;
  }

  clear(): void {
    this.data = [];
  }

  toArray(): T[] {
    return [...this.data];
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const eventListeners = this.listeners.get(event);
    if (eventListeners && !eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }
    const eventListeners = this.listeners.get(event);
    if (eventListeners) {
      const index = eventListeners.indexOf(listener);
      if (index !== -1) {
        eventListeners.splice(index, 1);
      }
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    const eventListeners = this.listeners.get(event);
    if (!eventListeners) {
      return 0;
    }
    // Create a copy to ensure that modifications during emit don't affect current iteration
    const listenersCopy = [...eventListeners];
    for (const listener of listenersCopy) {
      listener(payload);
    }
    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    const eventListeners = this.listeners.get(event);
    return eventListeners ? eventListeners.length : 0;
  }
}

