@Entry
@Component
struct WaterTrackerPage {
  @State private count: number = 0
  @State private goal: number = 8
  private showGoalDialog: boolean = false

  aboutToAppear() {
    this.loadState()
  }

  private loadState() {
    try {
      const countValue = preferences.getSync(STORAGE_KEY_COUNT)
      if (typeof countValue === 'number') {
        this.count = countValue
      }
    } catch (e) {
      // Use default 0
    }

    try {
      const goalValue = preferences.getSync(STORAGE_KEY_GOAL)
      if (typeof goalValue === 'number') {
        this.goal = goalValue
      }
    } catch (e) {
      // Use default 8
    }
  }

  private saveState() {
    try {
      preferences.setSync(STORAGE_KEY_COUNT, this.count)
    } catch (e) {
      // Ignore errors
    }

    try {
      preferences.setSync(STORAGE_KEY_GOAL, this.goal)
    } catch (e) {
      // Ignore errors
    }
  }

  private handleSaveGoal(newGoal: number) {
    this.goal = newGoal
    this.showGoalDialog = false
    this.saveState()
  }

  private handleCancelGoal() {
    this.showGoalDialog = false
  }

  build() {
    Column() {
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 20 })

      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(18)
          .fontColor(Color.Green)
          .margin({ bottom: 20 })
      }

      Column() {
        Button('Add a glass')
          .onClick(() => {
            this.count++
            this.saveState()
          })
          .margin({ bottom: 12 })

        Button('Change goal')
          .onClick(() => {
            this.showGoalDialog = true
          })
      }
      .width('80%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .padding(16)

    if (this.showGoalDialog) {
      GoalDialog({
        onSave: (goal: number) => {
          this.handleSaveGoal(goal)
        },
        onCancel: () => {
          this.handleCancelGoal()
        }
      })
      .onChange((visible: boolean) => {
        if (!visible) {
          this.showGoalDialog = false
        }
      })
    }
  }
}

interface User {
  id: number
  name: string
  email: string
}

function parseUsers(json: string): User[] {
  try {
    const parsed = JSON.parse(json)
    if (!Array.isArray(parsed)) {
      return []
    }

    const users: User[] = []
    for (let i = 0; i < parsed.length; i++) {
      const element = parsed[i]

      // Check if element is an object (and not null)
      if (element === null || typeof element !== 'object' || Array.isArray(element)) {
        continue
      }

      // Check id: must be a number and an integer
      const id = element.id
      if (typeof id !== 'number' || !Number.isInteger(id)) {
        continue
      }

      // Check name: must be a non-empty string
      const name = element.name
      if (typeof name !== 'string' || name.length === 0) {
        continue
      }

      // Check email: must be a string containing '@'
      const email = element.email
      if (typeof email !== 'string' || email.indexOf('@') === -1) {
        continue
      }

      // All checks passed, create a new User object with only the required fields
      users.push({
        id: id,
        name: name,
        email: email
      })
    }
    return users
  } catch (e) {
    // If JSON parsing fails, return empty array
    return []
  }
}

class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error;
  let i = 0;

  while (i < attempts) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
      i++;
    }
  }

  throw new RetryError(attempts, lastError);
}

// Define a Shape interface with a type discriminator
interface Shape {
  type: string;
}

// Circle shape implementation
class Circle implements Shape {
  type: string = 'circle';
  radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }
}

// Rectangle shape implementation
class Rectangle implements Shape {
  type: string = 'rectangle';
  width: number;
  height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }
}

// Triangle shape implementation
class Triangle implements Shape {
  type: string = 'triangle';
  base: number;
  height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }
}

// Export the Shape type
export type Shape = Circle | Rectangle | Triangle;

// Create a circle shape
export function circle(radius: number): Shape {
  return new Circle(radius);
}

// Create a rectangle shape
export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

// Create a triangle shape
export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

// Calculate the area of a shape
export function area(shape: Shape): number {
  if (shape.type === 'circle') {
    const circleShape = shape as Circle;
    return Math.PI * circleShape.radius * circleShape.radius;
  } else if (shape.type === 'rectangle') {
    const rectShape = shape as Rectangle;
    return rectShape.width * rectShape.height;
  } else if (shape.type === 'triangle') {
    const triShape = shape as Triangle;
    return triShape.base * triShape.height / 2;
  }
  return 0;
}

// Calculate the total area of an array of shapes
export function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += area(shapes[i]);
  }
  return total;
}

struct LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    this.capacity = capacity;
    this.map = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    // If key already exists, remove it from order first
    if (this.map.has(key)) {
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else {
      // If cache is full, remove least recently used (first in order)
      if (this.map.size >= this.capacity) {
        const lruKey = this.order[0];
        if (lruKey !== undefined) {
          this.order.shift();
          this.map.delete(lruKey);
        }
      }
    }

    // Add to end of order (most recently used)
    this.order.push(key);
    this.map.set(key, value);
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }

    // Move key to end of order (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (least to most recently used)
    return this.order.slice();
  }

  get size(): number {
    return this.map.size;
  }
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.id === id) {
      if (quantity > 0) {
        result.push({ id: item.id, name: item.name, quantity: quantity });
      }
    } else {
      result.push({ id: item.id, name: item.name, quantity: item.quantity });
    }
  }

  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result = items;

  for (let i = 0; i < changes.length; i++) {
    const change = changes[i];
    const hasItem = result.some(item => item.id === change.id);

    if (hasItem) {
      result = updateQuantity(result, change.id, change.quantity);
    }
  }

  return result;
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  let index = 0;

  while (index < items.length) {
    const chunkSize = Math.min(size, items.length - index);
    const chunk: T[] = [];

    for (let i = 0; i < chunkSize; i++) {
      chunk.push(items[index + i]);
    }

    result.push(chunk);
    index += chunkSize;
  }

  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length = Math.min(a.length, b.length);

  for (let i = 0; i < length; i++) {
    result.push({
      first: a[i],
      second: b[i]
    });
  }

  return result;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

export class Pipeline {
  private steps: { name: string; transform: Transform }[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, transform: step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const step of this.steps) {
      result = step.transform(result);
    }
    return result;
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      let result = text;
      for (const step of this.steps) {
        result = step.transform(result);
      }
      return result;
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

