export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday
  openHour: number
  closeHour: number
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i]
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true
    }
  }
  return false
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Collect all days that have at least one rule
  const daysWithRules: Weekday[] = []
  for (let i = 0; i < rules.length; i++) {
    const ruleDay = rules[i].day
    if (!daysWithRules.includes(ruleDay)) {
      daysWithRules.push(ruleDay)
    }
  }

  // If no day has rules, return undefined
  if (daysWithRules.length === 0) {
    return undefined
  }

  // Start checking from the next day after the given day
  let currentDay = (day + 1) % 7
  let iterations = 0

  // We need to check at most 7 days (a full week) to find the next open day
  while (iterations < 7) {
    if (daysWithRules.includes(currentDay)) {
      return currentDay as Weekday
    }
    currentDay = (currentDay + 1) % 7
    iterations++
  }

  // This should never be reached if daysWithRules is not empty
  return undefined
}

