struct DurationFormatter {
  formatDuration(totalSeconds: number): string {
    if (totalSeconds === 0) {
      return '0s';
    }

    const isNegative = totalSeconds < 0;
    const absSeconds = Math.abs(totalSeconds);
    let hours = Math.floor(absSeconds / 3600);
    let minutes = Math.floor((absSeconds % 3600) / 60);
    let seconds = absSeconds % 60;

    let result = '';
    if (isNegative) {
      result = '-';
    }

    if (hours > 0) {
      result = result + hours + 'h ' + this.padTwo(minutes) + 'm ' + this.padTwo(seconds) + 's';
    } else if (minutes > 0) {
      result = result + minutes + 'm ' + this.padTwo(seconds) + 's';
    } else {
      result = result + seconds + 's';
    }

    return result;
  }

  padTwo(num: number): string {
    return num < 10 ? '0' + num : num.toString();
  }

  parseDuration(text: string): number {
    if (text === '') {
      return NaN;
    }

    const parts = text.split(' ');
    if (parts.length === 0) {
      return NaN;
    }

    let isNegative = false;
    let totalSeconds = 0;
    let firstPartIndex = 0;

    // Check for leading negative sign
    if (parts[0].startsWith('-')) {
      isNegative = true;
      if (parts[0] === '-') {
        // Only a minus sign, no digits after
        return NaN;
      }
      // Remove the minus sign from the first part
      parts[0] = parts[0].substring(1);
      firstPartIndex = 0;
    } else {
      firstPartIndex = 0;
    }

    // Check for empty parts (consecutive spaces or leading/trailing spaces)
    for (let i = 0; i < parts.length; i++) {
      if (parts[i] === '') {
        return NaN;
      }
    }

    for (let i = 0; i < parts.length; i++) {
      const part = parts[i];
      const match = part.match(/^(\d+)([hms])$/);
      if (!match) {
        return NaN;
      }

      const value = Number(match[1]);
      const unit = match[2];

      if (unit === 'h') {
        totalSeconds += value * 3600;
      } else if (unit === 'm') {
        totalSeconds += value * 60;
      } else if (unit === 's') {
        totalSeconds += value;
      }
    }

    if (isNegative) {
      totalSeconds = -totalSeconds;
    }

    return totalSeconds;
  }
}

export function formatDuration(totalSeconds: number): string {
  const formatter = new DurationFormatter();
  return formatter.formatDuration(totalSeconds);
}

export function parseDuration(text: string): number {
  const formatter = new DurationFormatter();
  return formatter.parseDuration(text);
}

