            logger.info('Sign in button tapped')
          })
          .disabled(!(this.emailError === '' && this.passwordError === ''))
          .width('100%')
      }
      .width('90%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
