@Component
struct ItemListPage {
  @State items: Item[] = [];
  @State isLoading: boolean = true;
  @State hasError: boolean = false;

  aboutToAppear(): void {
    this.fetchItems();
  }

  fetchItems(): void {
    this.isLoading = true;
    this.hasError = false;

    try {
      const request = http.createHttp();
      request.request("https://example.com/api/items", {
        method: http.RequestMethod.GET,
        header: {
          'Content-Type': 'application/json'
        }
      }, (err, data) => {
        if (err) {
          this.isLoading = false;
          this.hasError = true;
          return;
        }

        if (data && data.result) {
          try {
            const response = JSON.parse(data.result.toString()) as Item[];

            if (Array.isArray(response)) {
              this.items = response;
              this.isLoading = false;
              this.hasError = false;
            } else {
              this.isLoading = false;
              this.hasError = true;
            }
          } catch (e) {
            this.isLoading = false;
            this.hasError = true;
          }
        } else {
          this.isLoading = false;
          this.hasError = true;
        }
      });
    } catch (e) {
      this.isLoading = false;
      this.hasError = true;
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
      } else if (this.hasError) {
        Text('Could not load the items')
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
          .fontColor(Color.Red)
      } else {
        List({ space: 8 }) {
