            ListItem() {
              Text(item.name)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
            }
          }, (item: Item) => item.id.toString())
        }
        .width('100%')
        .padding(16)
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

