const PREFERENCES_NAME = 'UserPreferences';
const KEY_NAME = 'userName';

@Entry
@Component
struct SolutionPage {
  @State name: string = '';
  @State inputName: string = '';

  aboutToAppear() {
    this.loadName();
  }

  loadName() {
    try {
      const pref = preferences.getPreferencesSync(this, PREFERENCES_NAME);
      const savedName = pref.get(KEY_NAME, '');
      if (savedName !== undefined && savedName !== '') {
        this.name = savedName as string;
      } else {
        this.name = '';
      }
    } catch (e) {
      this.name = '';
    }
  }

  saveName() {
    if (this.inputName.trim() === '') {
      this.name = '';
    } else {
      this.name = this.inputName.trim();
    }

    try {
      const pref = preferences.getPreferencesSync(this, PREFERENCES_NAME);
      pref.put(KEY_NAME, this.name);
      pref.flush();
    } catch (e) {
      console.error('Failed to save name:', e);
    }
  }

  build() {
    Column() {
      Text(this.name !== '' ? `Hello, ${this.name}` : 'No name saved')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

