    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

struct QueryParser {
  @State index: number = 0;
  @State input: string = '';

  parseQuery(query: string): Map<string, string> {
    const result: Map<string, string> = new Map();
    let i: number = 0;
    const len: number = query.length;

    // Skip leading '?'
    if (len > 0 && query.charAt(0) === '?') {
      i = 1;
    }

    while (i < len) {
      // Find the next '&' or end of string
      const start: number = i;
      while (i < len && query.charAt(i) !== '&') {
        i++;
      }

      const pairStr: string = query.substring(start, i);
      i++; // Skip '&'

      // Skip empty pairs
      if (pairStr.length === 0) {
        continue;
      }

      // Split at first '='
      const eqIndex: number = pairStr.indexOf('=');
      let key: string;
      let value: string;

      if (eqIndex === -1) {
        // No '=' means key with empty value
        key = pairStr;
        value = '';
      } else {
        key = pairStr.substring(0, eqIndex);
        value = pairStr.substring(eqIndex + 1);
      }

      // Skip empty keys
      if (key.length === 0) {
        continue;
      }

      // Decode key and value
      key = this.decodeComponent(key);
      value = this.decodeComponent(value);

      // Update map: last value wins, but keep first position
      if (result.has(key)) {
        result.delete(key);
      }
      result.set(key, value);
    }

    return result;
  }

  decodeComponent(str: string): string {
    // Replace '+' with space
    let result: string = str.replace(/\+/g, ' ');

    // Process percent-escapes
    let decoded: string = '';
    let i: number = 0;
    const len: number = result.length;

    while (i < len) {
      if (result.charAt(i) === '%' && i + 2 < len) {
        const hex: string = result.substring(i + 1, i + 3);
        // Check if hex characters are valid
        if (this.isValidHex(hex)) {
          const code: number = parseInt(hex, 16);
          // Try to decode as UTF-8
          if (code < 128) {
            // ASCII character
            decoded += String.fromCharCode(code);
            i += 3;
          } else {
            // Multi-byte UTF-8 sequence
            let bytes: number[] = [code];
            let j: number = i + 3;
            // Collect continuation bytes
            while (j < len && bytes.length < 4) {
              if (result.charAt(j) === '%' && j + 2 < len && this.isValidHex(result.substring(j + 1, j + 3))) {
                const nextCode: number = parseInt(result.substring(j + 1, j + 3), 16);
                if (nextCode >= 128 && (nextCode & 0xC0) === 0x80) {
                  bytes.push(nextCode);
                  j += 3;
                } else {
                  break;
                }
              } else {
                break;
              }
            }

            // Validate UTF-8 sequence
            if (this.isValidUtf8(bytes)) {
              decoded += this.utf8BytesToString(bytes);
              i = j;
            } else {
              // Invalid UTF-8 sequence, keep original string
              decoded += '%';
              i++;
            }
          }
        } else {
          // Invalid hex, keep original
          decoded += '%';
          i++;
        }
      } else {
        decoded += result.charAt(i);
        i++;
      }
    }

    return decoded;
  }

  isValidHex(str: string): boolean {
    if (str.length !== 2) {
      return false;
    }
    for (let i: number = 0; i < 2; i++) {
      const c: string = str.charAt(i);
      if (!((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))) {
        return false;
      }
    }
    return true;
  }

  isValidUtf8(bytes: number[]): boolean {
    if (bytes.length === 0) {
      return false;
    }

    if (bytes.length === 1) {
      return bytes[0] < 128;
    }

    if (bytes.length === 2) {
      // 110xxxxx 10xxxxxx
      if ((bytes[0] & 0xE0) === 0xC0 && (bytes[1] & 0xC0) === 0x80) {
        const code: number = ((bytes[0] & 0x1F) << 6) | (bytes[1] & 0x3F);
        return code >= 0x80 && code < 0x800;
      }
      return false;
    }

    if (bytes.length === 3) {
      // 1110xxxx 10xxxxxx 10xxxxxx
      if ((bytes[0] & 0xF0) === 0xE0 && (bytes[1] & 0xC0) === 0x80 && (bytes[2] & 0xC0) === 0x80) {
        const code: number = ((bytes[0] & 0x0F) << 12) | ((bytes[1] & 0x3F) << 6) | (bytes[2] & 0x3F);
        return code >= 0x800 && code < 0x10000;
      }
      return false;
    }

    if (bytes.length === 4) {
      // 11110xxx 10xxxxxx 10xxxxxx 10xxxxxx
      if ((bytes[0] & 0xF8) === 0xF0 && (bytes[1] & 0xC0) === 0x80 && (bytes[2] & 0xC0) === 0x80 && (bytes[3] & 0xC0) === 0x80) {
        const code: number = ((bytes[0] & 0x07) << 18) | ((bytes[1] & 0x3F) << 12) | ((bytes[2] & 0x3F) << 6) | (bytes[3] & 0x3F);
        return code >= 0x10000 && code < 0x110000;
      }
      return false;
    }

    return false;
  }

  utf8BytesToString(bytes: number[]): string {
    if (bytes.length === 0) {
      return '';
    }

    if (bytes.length === 1) {
      return String.fromCharCode(bytes[0]);
    }

    if (bytes.length === 2) {
      const code: number = ((bytes[0] & 0x1F) << 6) | (bytes[1] & 0x3F);
      return String.fromCharCode(code);
    }

    if (bytes.length === 3) {
      const code: number = ((bytes[0] & 0x0F) << 12) | ((bytes[1] & 0x3F) << 6) | (bytes[2] & 0x3F);
      return String.fromCharCode(code);
    }

    if (bytes.length === 4) {
      const code: number = ((bytes[0] & 0x07) << 18) | ((bytes[1] & 0x3F) << 12) | ((bytes[2] & 0x3F) << 6) | (bytes[3] & 0x3F);
      // Convert to surrogate pairs for characters outside BMP
      if (code >= 0x10000) {
        const adjusted: number = code - 0x10000;
        const high: number = 0xD800 | (adjusted >> 10);
        const low: number = 0xDC00 | (adjusted & 0x3FF);
        return String.fromCharCode(high) + String.fromCharCode(low);
      }
      return String.fromCharCode(code);
    }

    return '';
  }
}

export function parseQuery(query: string): Map<string, string> {
  const parser: QueryParser = new QueryParser();
  return parser.parseQuery(query);
}

export interface User {
  id: number;
  name: string;
  email: string;
}

type JsonValue = string | number | boolean | null | Object;

class ParsedObj {
  id: JsonValue | undefined = undefined;
  name: JsonValue | undefined = undefined;
  email: JsonValue | undefined = undefined;
}

export function parseUsers(json: string): User[] {
  let parsed: Array<JsonValue> = [];
  try {
    let result: Object = JSON.parse(json);
    if (result instanceof Array) {
      parsed = result as Array<JsonValue>;
    } else {
      return [];
    }
  } catch (e) {
    return [];
  }

  let users: User[] = [];
  for (let i = 0; i < parsed.length; i++) {
    let item: JsonValue = parsed[i];
    if (item === null || typeof item !== 'object' || item instanceof Array) {
      continue;
    }

    let obj: ParsedObj = item as ParsedObj;
    let idVal: JsonValue | undefined = obj.id;
    let nameVal: JsonValue | undefined = obj.name;
    let emailVal: JsonValue | undefined = obj.email;

    if (typeof idVal === 'number' && Number.isInteger(idVal) &&
        typeof nameVal === 'string' && nameVal.length > 0 &&
        typeof emailVal === 'string' && emailVal.includes('@')) {
      let user: User = {
        id: idVal,
        name: nameVal,
        email: emailVal
      };
      users.push(user);
    }
  }
  return users;
}

interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: Array<{ resolve: (value: T) => void; reject: (reason: Error) => void; job: () => Promise<T> }> = [];
  private completedJobs: number = 0;
  private failedJobs: number = 0;
  private paused: boolean = false;
  private idlePromise: Promise<void> | null = null;
  private idleResolver: (() => void) | null = null;

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error('Concurrency must be a whole number of at least 1');
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedJobs;
  }

  get failed(): number {
    return this.failedJobs;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.startWaitingJobs();
  }

  clear(): number {
    const removedCount = this.waitingJobs.length;
    // Reject all waiting jobs with cancellation error
    for (const { reject } of this.waitingJobs) {
      reject(new Error('Job was cancelled'));
    }
    this.waitingJobs = [];
    return removedCount;
  }

  whenIdle(): Promise<void> {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    if (!this.idlePromise || this.idleResolver === null) {
      this.idlePromise = new Promise<void>(resolve => {
        this.idleResolver = resolve;
      });
    }

    return this.idlePromise;
  }

  async runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = new Array(jobs.length);
    const promises: Promise<void>[] = [];

    for (let i = 0; i < jobs.length; i++) {
      const jobIndex = i;
      const job = jobs[jobIndex];
      const promise = this.add(job)
        .then(value => {
          outcomes[jobIndex] = { ok: true, value, error: undefined };
        })
        .catch(error => {
          outcomes[jobIndex] = { ok: false, value: undefined, error };
        });
      promises.push(promise);
    }

    await Promise.all(promises);
    return outcomes;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({ resolve, reject, job });
      this.startWaitingJobs();
    });
  }

  private startWaitingJobs(): void {
    while (
      this.runningJobs < this.concurrency &&
      this.waitingJobs.length > 0 &&
      !this.paused
    ) {
      const jobEntry = this.waitingJobs.shift();
      if (!jobEntry) break;

      this.runningJobs++;

      const { resolve, reject, job } = jobEntry;

      job()
        .then(value => {
          this.runningJobs--;
          this.completedJobs++;
          resolve(value);
          this.checkIdle();
          this.startWaitingJobs();
        })
        .catch(error => {
          this.runningJobs--;
          this.failedJobs++;
          reject(error);
          this.checkIdle();
          this.startWaitingJobs();
        });
    }
  }

  private checkIdle(): void {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0 && this.idleResolver) {
      const resolver = this.idleResolver;
      this.idleResolver = null;
      this.idlePromise = null;
      resolver();
    }
  }
}

// Token interface
export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

// ExpressionError class
export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
    this.name = 'ExpressionError';
  }
}

// Tokenizer function
export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const length = source.length;

  while (i < length) {
    const char = source[i];

    // Skip spaces
    if (char === ' ') {
      i++;
      continue;
    }

    // Numbers: digits, optionally followed by . and more digits
    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < length && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      // Check for decimal part
      if (i < length && source[i] === '.' && i + 1 < length && source[i + 1] >= '0' && source[i + 1] <= '9') {
        i++; // consume '.'
        while (i < length && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Names: letter or underscore, followed by letters, digits, underscores
    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < length && (
        (source[i] >= 'a' && source[i] <= 'z') ||
        (source[i] >= 'A' && source[i] <= 'Z') ||
        (source[i] >= '0' && source[i] <= '9') ||
        source[i] === '_'
      )) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Operators and parentheses
    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({
        kind: 'paren',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

// Parser and evaluator
function parseAndEvaluate(tokens: Token[], variables: Record<string, number>, sourceLength: number): number {
  let pos = 0;

  // Helper to peek current token or null if at end
  function peek(): Token | null {
    return pos < tokens.length ? tokens[pos] : null;
  }

  // Helper to consume current token
  function consume(): Token {
    return tokens[pos++];
  }

  // Helper to check if current token matches expected kind and text
  function match(kind: string, text?: string): boolean {
    const token = peek();
    if (!token) return false;
    if (token.kind !== kind) return false;
    if (text !== undefined && token.text !== text) return false;
    return true;
  }

  // Parse primary expression: number, name, unary minus, parenthesized expression
  function parsePrimary(): number {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', sourceLength);
    }

    // Unary minus
    if (token.kind === 'operator' && token.text === '-') {
      consume(); // consume '-'
      const value = parsePrimary(); // recursively parse the operand
      return -value;
    }

    // Number
    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    // Name
    if (token.kind === 'name') {
      consume();
      if (!(token.text in variables)) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return variables[token.text];
    }

    // Parenthesized expression
    if (token.kind === 'paren' && token.text === '(') {
      consume(); // consume '('
      const value = parseExpression();
      if (!match('paren', ')')) {
        throw new ExpressionError(`Unexpected token '${peek()?.text || ''}'`, peek()?.position || sourceLength);
      }
      consume(); // consume ')'
      return value;
    }

    // Unexpected token
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  // Parse binary operations with precedence: * / % before + -
  // We'll use recursive descent with precedence climbing
  // Left associative: a + b + c = (a + b) + c
  // Unary minus has highest precedence

  // Parse multiplication and division (higher precedence)
  function parseTerm(): number {
    let left = parsePrimary();

    while (true) {
      const token = peek();
      if (!token || token.kind !== 'operator' || !['*', '/', '%'].includes(token.text)) {
        break;
      }
      consume(); // consume operator
      const right = parsePrimary();
      if (token.text === '/') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', token.position);
        }
        left = left / right;
      } else if (token.text === '*') {
        left = left * right;
      } else if (token.text === '%') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', token.position);
        }
        left = left % right;
      }
    }

    return left;
  }

  // Parse addition and subtraction (lower precedence)
  function parseExpression(): number {
    let left = parseTerm();

    while (true) {
      const token = peek();
      if (!token || token.kind !== 'operator' || !['+', '-'].includes(token.text)) {
        break;
      }
      consume(); // consume operator
      const right = parseTerm();
      if (token.text === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }

    return left;
  }

  // Start parsing
  const result = parseExpression();

  // Check for extra tokens
  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

// Main evaluate function
export function evaluate(source: string, variables: Record<string, number>): number {
  // Handle empty source
  if (source.length === 0) {
    throw new ExpressionError('Unexpected end of expression', 0);
  }

  // Tokenize first
  let tokens: Token[];
  try {
    tokens = tokenize(source);
  } catch (error) {
    if (error instanceof ExpressionError) {
      throw error;
    }
    throw error;
  }

  // Parse and evaluate
  return parseAndEvaluate(tokens, variables, source.length);
}

