// Dialog content component
@Component
struct GoalDialogContent {
  @LocalStorageLink('dailyGoal') goal: number;
  @LocalStorageLink('waterCount') count: number;
  @LocalStorageProp('dialogVisible') dialogVisible: boolean;
  @State private inputGoal: string = '';
  private onSave: (value: number) => void;
  private onCancel: () => void;

