    this.inputGoal = this.goal.toString();
  }

  build() {
    Column() {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 10, bottom: 10 });

      TextInput({
        placeholder: 'Glasses per day',
        text: this.inputGoal
