enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

interface FieldError {
  path: string;
  message: string;
}

interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
  let obj: any;
  try {
    obj = JSON.parse(text);
  } catch (e) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'invalid JSON' }]
    };
  }

  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'expected an object' }]
    };
  }

  const errors: FieldError[] = [];
  const orderKeys = Object.keys(obj);

  // Helper to check if a value is null
  const isNull = (val: any) => val === null;

  // Check id
  if (!obj.hasOwnProperty('id') || isNull(obj.id)) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof obj.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (obj.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  }

  // Check status
  let statusValue: OrderStatus | undefined;
  if (!obj.hasOwnProperty('status') || isNull(obj.status)) {
    statusValue = OrderStatus.Draft;
  } else if (typeof obj.status !== 'string' || !['draft', 'paid', 'shipped'].includes(obj.status)) {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else {
    statusValue = obj.status as OrderStatus;
  }

  // Check lines
  let lines: any[] = [];
  if (!obj.hasOwnProperty('lines') || isNull(obj.lines)) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(obj.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if (obj.lines.length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    lines = obj.lines;
  }

  // Process lines
  const orderLines: OrderLine[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const linePath = `lines[${i}]`;

    // Check if line is an object
    if (line === null || typeof line !== 'object' || Array.isArray(line)) {
      errors.push({ path: linePath, message: 'expected an object' });
      continue;
    }

    const lineKeys = Object.keys(line);
    const lineErrors: FieldError[] = [];
    let sku: string | undefined;
    let quantity: number | undefined;
    let unitPrice: number | undefined;

    // Check sku
    if (!line.hasOwnProperty('sku') || isNull(line.sku)) {
      lineErrors.push({ path: `${linePath}.sku`, message: 'required' });
    } else if (typeof line.sku !== 'string') {
      lineErrors.push({ path: `${linePath}.sku`, message: 'expected a string' });
    } else if (line.sku === '') {
      lineErrors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
    } else {
      sku = line.sku;
    }

    // Check quantity
    if (!line.hasOwnProperty('quantity') || isNull(line.quantity)) {
      lineErrors.push({ path: `${linePath}.quantity`, message: 'required' });
    } else if (typeof line.quantity !== 'number') {
      lineErrors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
    } else if (!Number.isInteger(line.quantity) || line.quantity < 1) {
      lineErrors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
    } else {
      quantity = line.quantity;
    }

    // Check unitPrice
    if (!line.hasOwnProperty('unitPrice') || isNull(line.unitPrice)) {
      lineErrors.push({ path: `${linePath}.unitPrice`, message: 'required' });
    } else if (typeof line.unitPrice !== 'number') {
      lineErrors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
    } else if (line.unitPrice < 0) {
      lineErrors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
    } else {
      unitPrice = line.unitPrice;
    }

    // Add line-specific errors (sku, quantity, unitPrice)
    errors.push(...lineErrors);

    // Check unknown fields in line
    for (const key of lineKeys) {
      if (!['sku', 'quantity', 'unitPrice'].includes(key)) {
        errors.push({ path: `${linePath}.${key}`, message: 'unknown field' });
      }
    }

    // If all required fields are valid, create OrderLine
    if (sku !== undefined && quantity !== undefined && unitPrice !== undefined) {
      orderLines.push(new OrderLine(sku, quantity, unitPrice));
    }
  }

  // Check unknown fields in order
  for (const key of orderKeys) {
    if (!['id', 'status', 'lines'].includes(key)) {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  // If there are errors, return undefined order
  if (errors.length > 0) {
    return {
      order: undefined,
      errors: errors
    };
  }

  // Otherwise, return the order
  return {
    order: {
      id: obj.id,
      status: statusValue!,
      lines: orderLines
    },
    errors: []
  };
}

interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentTotal = result.get(expense.category) || 0;
    result.set(expense.category, currentTotal + expense.amount);
  }

  return result;
}

