class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

class BuildPlan {
  private spec: Record<string, string[]>;
  private keys: string[];
  private orderResult: string[] | null = null;
  private layersResult: string[][] | null = null;

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.keys = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.keys) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!(dep in spec)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Check for cycles during construction
    this.getOrder();
  }

  private getOrder(): string[] {
    if (this.orderResult !== null) {
      return this.orderResult;
    }

    const placed = new Set<string>();
    const result: string[] = [];
    const visiting = new Set<string>();
    const path: string[] = [];

    const placeTask = (task: string): void => {
      if (placed.has(task)) {
        return;
      }

      if (visiting.has(task)) {
        // Found a cycle: extract the cycle path
        const cycleStartIndex = path.indexOf(task);
        const cyclePath = path.slice(cycleStartIndex);
        cyclePath.push(task);
        throw new CycleError(cyclePath);
      }

      visiting.add(task);
      path.push(task);

      const deps = this.spec[task];
      for (const dep of deps) {
        placeTask(dep);
      }

      path.pop();
      visiting.delete(task);
      placed.add(task);
      result.push(task);
    };

    for (const task of this.keys) {
      placeTask(task);
    }

    this.orderResult = result;
    return result;
  }

  order(): string[] {
    return [...this.getOrder()];
  }

  layers(): string[][] {
    if (this.layersResult !== null) {
      return this.layersResult;
    }

    const order = this.getOrder();
    const layerMap = new Map<string, number>();
    const layers: string[][] = [];

    // Initialize layers array
    for (const task of order) {
      const deps = this.spec[task];
      let maxDepLayer = -1;

      for (const dep of deps) {
        const depLayer = layerMap.get(dep) ?? 0;
        if (depLayer > maxDepLayer) {
          maxDepLayer = depLayer;
        }
      }

      const taskLayer = maxDepLayer + 1;
      layerMap.set(task, taskLayer);

      // Add to appropriate layer
      if (taskLayer >= layers.length) {
        layers.push([]);
      }
      layers[taskLayer].push(task);
    }

    this.layersResult = layers;
    return layers;
  }

  dependentsOf(name: string): string[] {
    const order = this.getOrder();
    const dependents: string[] = [];
    const visited = new Set<string>();

    // BFS to find all tasks that depend on 'name' (directly or indirectly)
    const queue: string[] = [name];

    while (queue.length > 0) {
      const current = queue.shift()!;
      const tasks = Object.keys(this.spec);

      for (const task of tasks) {
        if (visited.has(task)) {
          continue;
        }

        // Check if task depends on current (directly or indirectly)
        if (this.dependsOn(task, current, new Set<string>())) {
          dependents.push(task);
          visited.add(task);
          queue.push(task);
        }
      }
    }

    // Filter to only include tasks that appear in order and maintain order
    return order.filter(task => dependents.includes(task));
  }

  private dependsOn(task: string, target: string, visited: Set<string>): boolean {
    if (visited.has(task)) {
      return false;
    }
    visited.add(task);

    const deps = this.spec[task];
    for (const dep of deps) {
      if (dep === target) {
        return true;
      }
      if (this.dependsOn(dep, target, visited)) {
        return true;
      }
    }
    return false;
  }
}

