export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  // Initialize min and max with the first point's coordinates
  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  // Iterate through all points to find the min and max coordinates
  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) {
      minX = point.x;
    }
    if (point.y < minY) {
      minY = point.y;
    }
    if (point.x > maxX) {
      maxX = point.x;
    }
    if (point.y > maxY) {
      maxY = point.y;
    }
  }

  // Create new Point objects for min and max (not referencing input points)
  const minPoint: Point = { x: minX, y: minY };
  const maxPoint: Point = { x: maxX, y: maxY };

  return {
    min: minPoint,
    max: maxPoint,
    width: maxX - minX,
    height: maxY - minY
  };
}

interface User {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  try {
    const parsed = JSON.parse(json);
    if (!Array.isArray(parsed)) {
      return [];
    }

    const users: User[] = [];
    for (const item of parsed) {
      // Skip non-objects
      if (item === null || typeof item !== 'object' || Array.isArray(item)) {
        continue;
      }

      // Check id: must be a number and an integer
      const id = item.id;
      if (typeof id !== 'number' || !Number.isInteger(id)) {
        continue;
      }

      // Check name: must be a non-empty string
      const name = item.name;
      if (typeof name !== 'string' || name.length === 0) {
        continue;
      }

      // Check email: must be a string containing '@'
      const email = item.email;
      if (typeof email !== 'string' || email.indexOf('@') === -1) {
        continue;
      }

      // Add valid user with only required fields
      users.push({
        id: id,
        name: name,
        email: email
      });
    }

    return users;
  } catch (e) {
    // If JSON parsing fails, return empty array
    return [];
  }
}

export class Stack<T> {
  private readonly capacity: number;
  private readonly items: T[];

  constructor(capacity: number) {
    this.capacity = capacity;
    this.items = [];
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items.length = 0;
  }

  toArray(): T[] {
    return [...this.items];
  }
}

