class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error | undefined;

  for (let i = 0; i < attempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error instanceof Error ? error : new Error(String(error));
    }
  }

  throw new RetryError(attempts, lastError!);
}

type Listener<T> = (payload: T) => void;

class EventBus<T> {
  private events: Map<string, Listener<T>[]> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    if (!this.events.has(event)) {
      this.events.set(event, []);
    }
    const listeners = this.events.get(event)!;
    if (!listeners.includes(listener)) {
      listeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.events.has(event)) {
      return;
    }
    const listeners = this.events.get(event)!;
    const index = listeners.indexOf(listener);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.events.has(event)) {
      return 0;
    }
    const listeners = this.events.get(event)!;
    // Create a copy to avoid issues with modifications during iteration
    const listenersCopy = [...listeners];
    for (const listener of listenersCopy) {
      listener(payload);
    }
    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    if (!this.events.has(event)) {
      return 0;
    }
    return this.events.get(event)!.length;
  }
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  if (quantity <= 0) {
    // Remove the item with the given id
    return items.filter(item => item.id !== id);
  }

  // Create a new array with the updated item
  return items.map(item => {
    if (item.id === id) {
      // Create a new object with the updated quantity
      return {
        id: item.id,
        name: item.name,
        quantity: quantity
      };
    }
    return item;
  });
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  // Start with a copy of the original items array
  let result = [...items];

  // Apply each change sequentially
  for (const change of changes) {
    // Check if the item with this id still exists in the result
    const existingItem = result.find(item => item.id === change.id);

    // If the item exists, apply the change; otherwise, skip it
    if (existingItem !== undefined) {
      result = updateQuantity(result, change.id, change.quantity);
    }
  }

  return result;
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private currentState: EditorState;
  private history: EditorState[] = [];
  private future: EditorState[] = [];
  private historyLimit: number;
  private listeners: {
    text: Array<(value: string, previous: string) => void>;
    cursor: Array<(value: number, previous: number) => void>;
    bold: Array<(value: boolean, previous: boolean) => void>;
  } = {
    text: [],
    cursor: [],
    bold: []
  };

  constructor(initial: EditorState, historyLimit: number) {
    // Deep copy the initial state to avoid external mutations affecting the store
    this.currentState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = Math.max(1, Math.floor(historyLimit));
  }

  get state(): EditorState {
    // Return a new object with current values
    return {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    // Check if any field actually changes
    const newText = patch.text !== undefined ? patch.text : this.currentState.text;
    const newCursor = patch.cursor !== undefined ? patch.cursor : this.currentState.cursor;
    const newBold = patch.bold !== undefined ? patch.bold : this.currentState.bold;

    // If nothing changes, return false
    if (newText === this.currentState.text && newCursor === this.currentState.cursor && newBold === this.currentState.bold) {
      return false;
    }

    // Save current state to history before making changes
    this.saveToHistory();

    // Record previous values for listeners
    const prevText = this.currentState.text;
    const prevCursor = this.currentState.cursor;
    const prevBold = this.currentState.bold;

    // Apply changes
    this.currentState.text = newText;
    this.currentState.cursor = newCursor;
    this.currentState.bold = newBold;

    // Notify listeners
    this.notifyListeners('text', newText, prevText);
    this.notifyListeners('cursor', newCursor, prevCursor);
    this.notifyListeners('bold', newBold, prevBold);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    // Create a draft copy of the current state
    const draft: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    try {
      // Call the transaction function with the draft
      run(draft);

      // Apply the draft as a patch
      return this.apply(draft);
    } catch (error) {
      // If an error occurs, do nothing and rethrow
      throw error;
    }
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    // Save current state to future
    this.future.push({
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    });

    // Get previous state from history
    const previousState = this.history.pop()!;

    // Record previous values for listeners
    const prevText = this.currentState.text;
    const prevCursor = this.currentState.cursor;
    const prevBold = this.currentState.bold;

    // Restore previous state
    this.currentState = {
      text: previousState.text,
      cursor: previousState.cursor,
      bold: previousState.bold
    };

    // Notify listeners
    this.notifyListeners('text', this.currentState.text, prevText);
    this.notifyListeners('cursor', this.currentState.cursor, prevCursor);
    this.notifyListeners('bold', this.currentState.bold, prevBold);

    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    // Save current state to history
    this.saveToHistory();

    // Get next state from future
    const nextState = this.future.pop()!;

    // Record previous values for listeners
    const prevText = this.currentState.text;
    const prevCursor = this.currentState.cursor;
    const prevBold = this.currentState.bold;

    // Restore next state
    this.currentState = {
      text: nextState.text,
      cursor: nextState.cursor,
      bold: nextState.bold
    };

    // Notify listeners
    this.notifyListeners('text', this.currentState.text, prevText);
    this.notifyListeners('cursor', this.currentState.cursor, prevCursor);
    this.notifyListeners('bold', this.currentState.bold, prevBold);

    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    // Validate field
    if (field !== 'text' && field !== 'cursor' && field !== 'bold') {
      throw new Error('Invalid field name. Must be "text", "cursor", or "bold".');
    }

    // Add listener to the appropriate array
    const listenersArray = this.listeners[field] as Array<(value: any, previous: any) => void>;
    listenersArray.push(listener as any);

    // Return a function to remove the listener
    return () => {
      const index = listenersArray.indexOf(listener as any);
      if (index !== -1) {
        listenersArray.splice(index, 1);
      }
    };
  }

  private saveToHistory(): void {
    // Add current state to history
    this.history.push({
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Clear future when a new action is performed
    this.future = [];
  }

  private notifyListeners(field: 'text' | 'cursor' | 'bold', newValue: string | number | boolean, previousValue: string | number | boolean): void {
    const listeners = this.listeners[field] as Array<(value: any, previous: any) => void>;
    for (const listener of listeners) {
      listener(newValue, previousValue);
    }
  }
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return "0s";
  }

  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);

  const hours = Math.floor(absSeconds / 3600);
  const minutes = Math.floor((absSeconds % 3600) / 60);
  const seconds = absSeconds % 60;

  let result = "";

  if (hours > 0) {
    result += `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    result += `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    result += `${seconds}s`;
  }

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  // Handle empty string
  if (!text || text.trim() === "") {
    return NaN;
  }

  // Check for leading space or trailing space
  if (text !== text.trim()) {
    return NaN;
  }

  // Check for double spaces
  if (text.includes("  ")) {
    return NaN;
  }

  const parts = text.split(" ");
  let totalSeconds = 0;
  let isNegative = false;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Check if part matches the expected pattern: one or more digits followed by h, m, or s
    const match = part.match(/^(\d+)([hms])$/);

    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    // Check if this is the first part and starts with '-'
    if (i === 0 && part.startsWith("-")) {
      // Extract the actual part without the minus sign
      const cleanPart = part.substring(1);
      const cleanMatch = cleanPart.match(/^(\d+)([hms])$/);

      if (!cleanMatch) {
        return NaN;
      }

      const cleanValue = parseInt(cleanMatch[1], 10);
      const cleanUnit = cleanMatch[2];

      isNegative = true;

      if (cleanUnit === 'h') {
        totalSeconds += cleanValue * 3600;
      } else if (cleanUnit === 'm') {
        totalSeconds += cleanValue * 60;
      } else {
        totalSeconds += cleanValue;
      }
    } else {
      if (unit === 'h') {
        totalSeconds += value * 3600;
      } else if (unit === 'm') {
        totalSeconds += value * 60;
      } else {
        totalSeconds += value;
      }
    }
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.map = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    // If key already exists, remove it from order first
    if (this.map.has(key)) {
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    }

    // Add to the end (most recently used)
    this.order.push(key);
    this.map.set(key, value);

    // If over capacity, remove least recently used (first element)
    if (this.map.size > this.capacity) {
      const lruKey = this.order.shift();
      if (lruKey !== undefined) {
        this.map.delete(lruKey);
      }
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }

    // Move key to end (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (least to most recently used)
    return [...this.order];
  }

  get size(): number {
    return this.map.size;
  }
}

export { LruCache };

// Define a Shape interface that all shapes must implement
export interface Shape {
  type: 'circle' | 'rectangle' | 'triangle';
  area(): number;
}

// Circle shape implementation
class CircleShape implements Shape {
  type: 'circle' = 'circle';
  radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

// Rectangle shape implementation
class RectangleShape implements Shape {
  type: 'rectangle' = 'rectangle';
  width: number;
  height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

// Triangle shape implementation
class TriangleShape implements Shape {
  type: 'triangle' = 'triangle';
  base: number;
  height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

// Factory function to create a circle shape
export function circle(radius: number): Shape {
  return new CircleShape(radius);
}

// Factory function to create a rectangle shape
export function rectangle(width: number, height: number): Shape {
  return new RectangleShape(width, height);
}

// Factory function to create a triangle shape
export function triangle(base: number, height: number): Shape {
  return new TriangleShape(base, height);
}

// Calculate the area of a shape
export function area(shape: Shape): number {
  return shape.area();
}

// Calculate the total area of an array of shapes
export function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (const shape of shapes) {
    total += shape.area();
  }
  return total;
}

export type Pair<A, B> = {
  first: A;
  second: B;
};

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const length = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < length; i++) {
    result.push({
      first: a[i],
      second: b[i]
    });
  }

  return result;
}

