type Transform = (text: string) => string;

function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

class Pipeline {
  private steps: Array<{ name: string; transform: Transform }> = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, transform: step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const step of this.steps) {
      result = step.transform(result);
    }
    return result;
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      let result = text;
      for (const step of this.steps) {
        result = step.transform(result);
      }
      return result;
    };
  }
}

function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

export { Transform, trim, lowerCase, collapseSpaces, Pipeline, compose };

