@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';
  @State emailError: string = '';
  @State passwordError: string = '';

  // Email validation: exactly one '@', at least one char before, and after '@' there must be a '.' with at least one char on each side
  validateEmail(email: string): boolean {
    if (email === '') return true;
    const atIndex = email.indexOf('@');
    if (atIndex === -1 || atIndex === 0) return false;

    const afterAt = email.substring(atIndex + 1);
    const dotIndex = afterAt.indexOf('.');
    if (dotIndex === -1 || dotIndex === 0 || dotIndex === afterAt.length - 1) return false;

    return email.indexOf('@') === atIndex && email.indexOf('@', atIndex + 1) === -1;
  }

  // Password validation: at least 8 characters
  validatePassword(password: string): boolean {
    return password.length >= 8;
  }

  // Update email and validate
  onEmailChange(value: string) {
    this.email = value;
    if (value === '') {
      this.emailError = '';
    } else if (!this.validateEmail(value)) {
      this.emailError = 'Enter a valid email address';
    } else {
      this.emailError = '';
    }
  }

  // Update password and validate
  onPasswordChange(value: string) {
    this.password = value;
    if (value === '') {
      this.passwordError = '';
    } else if (!this.validatePassword(value)) {
      this.passwordError = 'Password must be at least 8 characters';
    } else {
      this.passwordError = '';
    }
  }

  // Sign in button click handler
  onSignIn() {
    logger.info('Sign in button tapped');
  }

  build() {
    Column() {
      // Email input
      TextInput({
        text: this.email,
        placeholder: 'Email'
      })
        .onChange((value: string) => {
          this.onEmailChange(value);
        })
        .width('90%')
        .margin({ top: 20, bottom: 5 })

      // Email error message
      if (this.emailError !== '') {
        Text(this.emailError)
          .fontSize(12)
          .fontColor('#FF0000')
          .width('90%')
          .margin({ bottom: 10 })
      }

      // Password input
      TextInput({
        text: this.password,
        placeholder: 'Password',
        type: InputType.Password
      })
        .onChange((value: string) => {
          this.onPasswordChange(value);
        })
        .width('90%')
        .margin({ top: 10, bottom: 5 })

      // Password error message
      if (this.passwordError !== '') {
        Text(this.passwordError)
          .fontSize(12)
          .fontColor('#FF0000')
          .width('90%')
          .margin({ bottom: 10 })
      }

      // Sign in button
      Button('Sign in')
        .onClick(() => {
          this.onSignIn();
        })
        .width('90%')
        .margin({ top: 20 })
        .disabled(!(this.validateEmail(this.email) && this.validatePassword(this.password)))
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

