@Entry
@Component
struct SolutionPage {
  @State items: Array<{ id: number; name: string }> = [];
  @State isLoading: boolean = true;
  @State hasError: boolean = false;

  aboutToAppear(): void {
    this.loadItems();
  }

  loadItems(): void {
    this.isLoading = true;
    this.hasError = false;

    fetch.fetch({
      url: 'https://example.com/api/items',
      method: 'GET',
      success: (res: fetch.FetchResponse) => {
        if (res.code === 200) {
          try {
            const data = res.data as Array<{ id: number; name: string }>;
            if (Array.isArray(data)) {
              this.items = data;
              this.isLoading = false;
            } else {
              this.hasError = true;
              this.isLoading = false;
            }
          } catch (e) {
            this.hasError = true;
            this.isLoading = false;
          }
        } else {
          this.hasError = true;
          this.isLoading = false;
        }
      },
      fail: (data: any, code: number) => {
        this.hasError = true;
        this.isLoading = false;
      }
    });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
      } else if (this.hasError) {
        Text('Could not load the items')
      } else {
        List() {
          ForEach(this.items, (item: { id: number; name: string }) => {
            ListItem() {
              Text(item.name)
