interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface QueueItem<T> {
  resolve: (value: T) => void;
  reject: (reason: Error) => void;
  job: () => Promise<T>;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: number = 0;
  private completedJobs: number = 0;
  private failedJobs: number = 0;
  private queue: Array<QueueItem<never>> = [];
  private paused: boolean = false;
  private whenIdleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error('Concurrency must be a whole number of at least 1');
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs;
  }

  get completed(): number {
    return this.completedJobs;
  }

  get failed(): number {
    return this.failedJobs;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.queue.push({ resolve, reject, job } as QueueItem<T>);
      this.waitingJobs++;
      this._tryStartJobs();
    });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this._tryStartJobs();
  }

  clear(): number {
    const removedCount = this.queue.length;
    const error = new Error('Job was cancelled');

    // Reject all waiting jobs
    for (const item of this.queue) {
      item.reject(error);
    }

    this.queue = [];
    this.waitingJobs = 0;

    // Check if we should resolve whenIdle promises
    this._checkIdle();

    return removedCount;
  }

  whenIdle(): Promise<void> {
    if (this.runningJobs === 0 && this.waitingJobs === 0) {
      return Promise.resolve();
    }

    return new Promise<void>((resolve) => {
      this.whenIdleResolvers.push(resolve);
    });
  }

  async runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = new Array(jobs.length);
    const promises: Array<Promise<void>> = [];

    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      const promise = this.add<T>(job)
        .then((value: T) => {
          outcomes[i] = { ok: true, value, error: undefined };
        })
        .catch((error: Error) => {
          outcomes[i] = { ok: false, value: undefined, error };
        });
      promises.push(promise);
    }

    await Promise.all(promises);
    return outcomes;
  }

  private _tryStartJobs(): void {
    while (
      this.runningJobs < this.concurrency &&
      this.queue.length > 0 &&
      !this.paused
    ) {
      const item = this.queue.shift();
      if (!item) break;

      this.waitingJobs--;
      this.runningJobs++;

      // Execute the job
      Promise.resolve()
        .then(() => item.job())
        .then((value: unknown) => {
          this.runningJobs--;
          this.completedJobs++;
          item.resolve(value as never);
          this._checkIdle();
          this._tryStartJobs();
        })
        .catch((error: Error) => {
          this.runningJobs--;
          this.failedJobs++;
          item.reject(error);
          this._checkIdle();
          this._tryStartJobs();
        });
    }
  }

  private _checkIdle(): void {
    if (this.runningJobs === 0 && this.waitingJobs === 0) {
      const resolvers = this.whenIdleResolvers;
      this.whenIdleResolvers = [];
      for (const resolve of resolvers) {
        resolve();
      }
    }
  }
}

class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];
  private orderCache: string[] | null = null;

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);

    // First, validate dependencies exist as keys
    for (const task of this.tasks) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!this.hasKey(spec, dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Then, check for cycles during construction
    this.checkAndBuildOrder();
  }

  private hasKey(obj: Record<string, string>, key: string): boolean {
    return Object.prototype.hasOwnProperty.call(obj, key);
  }

  private checkAndBuildOrder(): void {
    const visited = new Set<string>();
    const inStack = new Set<string>();
    const order: string[] = [];
    const path: string[] = [];

    const dfs = (task: string): void => {
      if (inStack.has(task)) {
        // Found a cycle: find the cycle path
        const cycleStartIndex = path.indexOf(task);
        const cyclePath = path.slice(cycleStartIndex);
        cyclePath.push(task);
        throw new CycleError(cyclePath);
      }

      if (visited.has(task)) {
        return;
      }

      visited.add(task);
      inStack.add(task);
      path.push(task);

      const deps = this.spec[task];
      for (const dep of deps) {
        dfs(dep);
      }

      inStack.delete(task);
      path.pop();
      order.push(task);
    };

    // Process tasks in key order
    for (const task of this.tasks) {
      if (!visited.has(task)) {
        dfs(task);
      }
    }

    this.orderCache = order;
  }

  order(): string[] {
    if (this.orderCache === null) {
      this.checkAndBuildOrder();
    }
    return this.orderCache.slice();
  }

  layers(): string[][] {
    if (this.orderCache === null) {
      this.checkAndBuildOrder();
    }

    if (this.tasks.length === 0) {
      return [];
    }

    // Compute layer for each task
    const layerMap = new Map<string, number>();
    const order = this.orderCache;

    // First pass: assign layers based on dependencies
    for (const task of order) {
      const deps = this.spec[task];
      let maxDepLayer = -1;

      for (const dep of deps) {
        const depLayer = layerMap.get(dep) ?? 0;
        if (depLayer > maxDepLayer) {
          maxDepLayer = depLayer;
        }
      }

      layerMap.set(task, maxDepLayer + 1);
    }

    // Group tasks by layer, maintaining key order within each layer
    const maxLayer = Math.max(...Array.from(layerMap.values()), -1);
    const layers: string[][] = [];

    for (let i = 0; i <= maxLayer; i++) {
      layers.push([]);
    }

    // Process tasks in key order to maintain consistency
    for (const task of this.tasks) {
      const layer = layerMap.get(task) ?? 0;
      layers[layer].push(task);
    }

    return layers;
  }

  dependentsOf(name: string): string[] {
    const order = this.order();
    const dependents: string[] = [];

    // For each task in order, check if it depends on 'name'
    for (const task of order) {
      if (task === name) continue;
      if (this.dependsOn(task, name)) {
        dependents.push(task);
      }
    }

    return dependents;
  }

  private dependsOn(task: string, target: string): boolean {
    const visitedDeps = new Set<string>();
    const stack: string[] = [];

    // Add dependencies of task to stack
    const deps = this.spec[task];
    for (let i = 0; i < deps.length; i++) {
      stack.push(deps[i]);
    }

    while (stack.length > 0) {
      const current = stack.pop();
      if (current === undefined) continue;

      if (current === target) return true;
      if (visitedDeps.has(current)) continue;
      visitedDeps.add(current);

      const taskDeps = this.spec[current];
      for (let i = 0; i < taskDeps.length; i++) {
        stack.push(taskDeps[i]);
      }
    }
    return false;
  }
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
    this.name = 'ExpressionError';
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const len = source.length;

  while (i < len) {
    const char = source[i];

    // Skip spaces
    if (char === ' ') {
      i++;
      continue;
    }

    // Numbers: digits, optionally followed by '.' and more digits
    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < len && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      if (i < len && source[i] === '.' && i + 1 < len && source[i + 1] >= '0' && source[i + 1] <= '9') {
        i++; // consume '.'
        while (i < len && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Names: letter or underscore, followed by letters, digits, or underscores
    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < len && (
        (source[i] >= 'a' && source[i] <= 'z') ||
        (source[i] >= 'A' && source[i] <= 'Z') ||
        (source[i] >= '0' && source[i] <= '9') ||
        source[i] === '_'
      )) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Operators and parentheses
    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({
        kind: char === '(' || char === ')' ? 'paren' : 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

// Result type for parser functions
interface ParseResult {
  value: number;
  newPos: number;
}

function parseExpression(tokens: TokenWithIndex[], pos: number, variables: Record<string, number>): ParseResult {
  return parseAdditive(tokens, pos, variables);
}

function parseAdditive(tokens: TokenWithIndex[], pos: number, variables: Record<string, number>): ParseResult {
  let left = parseMultiplicative(tokens, pos, variables);
  let currentPos = left.newPos;

  while (currentPos < tokens.length) {
    const token = tokens[currentPos].token;
    if (token.kind === 'operator' && (token.text === '+' || token.text === '-')) {
      const op = token.text;
      currentPos++;
      const right = parseMultiplicative(tokens, currentPos, variables);
      if (op === '+') {
        left.value = left.value + right.value;
      } else {
        left.value = left.value - right.value;
      }
      currentPos = right.newPos;
    } else {
      break;
    }
  }

  return { value: left.value, newPos: currentPos };
}

function parseMultiplicative(tokens: TokenWithIndex[], pos: number, variables: Record<string, number>): ParseResult {
  let left = parseUnary(tokens, pos, variables);
  let currentPos = left.newPos;

  while (currentPos < tokens.length) {
    const token = tokens[currentPos].token;
    if (token.kind === 'operator' && (token.text === '*' || token.text === '/' || token.text === '%')) {
      const op = token.text;
      currentPos++;
      const right = parseUnary(tokens, currentPos, variables);

      if (op === '/') {
        if (right.value === 0) {
          throw new ExpressionError('Division by zero', token.position);
        }
        left.value = left.value / right.value;
      } else if (op === '%') {
        if (right.value === 0) {
          throw new ExpressionError('Division by zero', token.position);
        }
        left.value = left.value % right.value;
      } else {
        left.value = left.value * right.value;
      }
      currentPos = right.newPos;
    } else {
      break;
    }
  }

  return { value: left.value, newPos: currentPos };
}

function parseUnary(tokens: TokenWithIndex[], pos: number, variables: Record<string, number>): ParseResult {
  if (pos < tokens.length && tokens[pos].token.kind === 'operator' && tokens[pos].token.text === '-') {
    const token = tokens[pos].token;
    const result = parseUnary(tokens, pos + 1, variables);
    result.value = -result.value;
    return result;
  }
  return parsePrimary(tokens, pos, variables);
}

function parsePrimary(tokens: TokenWithIndex[], pos: number, variables: Record<string, number>): ParseResult {
  if (pos >= tokens.length) {
    throw new ExpressionError('Unexpected end of expression', tokens.length > 0 ? tokens[tokens.length - 1].token.position + 1 : 0);
  }

  const token = tokens[pos].token;

  if (token.kind === 'number') {
    return { value: parseFloat(token.text), newPos: pos + 1 };
  }

  if (token.kind === 'name') {
    if (hasOwnProperty.call(variables, token.text)) {
      return { value: variables[token.text], newPos: pos + 1 };
    } else {
      throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
    }
  }

  if (token.kind === 'paren' && token.text === '(') {
    const inner = parseExpression(tokens, pos + 1, variables);
    if (inner.newPos >= tokens.length || tokens[inner.newPos].token.kind !== 'paren' || tokens[inner.newPos].token.text !== ')') {
      const errorMsg = inner.newPos < tokens.length 
        ? `Unexpected token '${tokens[inner.newPos].token.text}'` 
        : 'Unexpected end of expression';
      const errorPos = inner.newPos < tokens.length 
        ? tokens[inner.newPos].token.position 
        : (tokens.length > 0 ? tokens[tokens.length - 1].token.position + 1 : 0);
      throw new ExpressionError(errorMsg, errorPos);
    }
    return { value: inner.value, newPos: inner.newPos + 1 };
  }

  // Unexpected token
  throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
}

// Helper interface for token with index
interface TokenWithIndex {
  token: Token;
  index: number;
}

// Custom hasOwnProperty implementation to avoid using Object.prototype.hasOwnProperty directly
function hasOwnProperty(obj: Record<string, number>, prop: string): boolean {
  const proto = Object.prototype;
  return proto.hasOwnProperty.call(obj, prop);
}

export function evaluate(source: string, variables: Record<string, number>): number {
  // First tokenize
  const tokens = tokenize(source);

  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', 0);
  }

  // Convert to indexed tokens for easier tracking
  const tokenWithIndex: TokenWithIndex[] = [];
  for (let i = 0; i < tokens.length; i++) {
    tokenWithIndex.push({ token: tokens[i], index: i });
  }

  // Parse and evaluate
  const result = parseExpression(tokenWithIndex, 0, variables);

  // Check if there are remaining tokens
  if (result.newPos < tokenWithIndex.length) {
    throw new ExpressionError(`Unexpected token '${tokenWithIndex[result.newPos].token.text}'`, tokenWithIndex[result.newPos].token.position);
  }

  return result.value;
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

export function parseOrder(text: string): ParseResult {
  let obj: Record<string, unknown>;
  try {
    const parsed = JSON.parse(text);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
      return {
        order: undefined,
        errors: [{ path: '', message: 'expected an object' }]
      };
    }
    obj = parsed as Record<string, unknown>;
  } catch (e) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'invalid JSON' }]
    };
  }

  const errors: FieldError[] = [];
  const unknownOrderFields: string[] = [];
  const orderFields = Object.keys(obj);

  // Check id
  if (!(obj.id !== undefined && obj.id !== null)) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof obj.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (obj.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  }

  // Check status
  let status: OrderStatus | undefined;
  if (obj.status === undefined || obj.status === null) {
    status = OrderStatus.Draft;
  } else if (typeof obj.status !== 'string' || !['draft', 'paid', 'shipped'].includes(obj.status)) {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else {
    status = obj.status as OrderStatus;
  }

  // Check lines
  let lines: unknown[] | undefined;
  if (!(obj.lines !== undefined && obj.lines !== null)) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(obj.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if ((obj.lines as unknown[]).length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    lines = obj.lines as unknown[];
  }

  // Process lines if we have an array
  const orderLines: OrderLine[] = [];
  if (lines !== undefined) {
    for (let i = 0; i < lines.length; i++) {
      const line = lines[i];
      const linePath = `lines[${i}]`;
      const lineErrors: FieldError[] = [];
      const unknownLineFields: string[] = [];
      let lineObj: Record<string, unknown> | null = null;

      // Check if line is an object
      if (line === null || typeof line !== 'object' || Array.isArray(line)) {
        errors.push({ path: linePath, message: 'expected an object' });
        // Skip further checks for this line
        continue;
      }

      lineObj = line as Record<string, unknown>;
      const lineFields = Object.keys(lineObj);

      // Check sku
      if (!(lineObj.sku !== undefined && lineObj.sku !== null)) {
        lineErrors.push({ path: `${linePath}.sku`, message: 'required' });
      } else if (typeof lineObj.sku !== 'string') {
        lineErrors.push({ path: `${linePath}.sku`, message: 'expected a string' });
      } else if (lineObj.sku === '') {
        lineErrors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
      }

      // Check quantity
      if (!(lineObj.quantity !== undefined && lineObj.quantity !== null)) {
        lineErrors.push({ path: `${linePath}.quantity`, message: 'required' });
      } else if (typeof lineObj.quantity !== 'number') {
        lineErrors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
      } else if (!Number.isInteger(lineObj.quantity) || lineObj.quantity < 1) {
        lineErrors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
      }

      // Check unitPrice
      if (!(lineObj.unitPrice !== undefined && lineObj.unitPrice !== null)) {
        lineErrors.push({ path: `${linePath}.unitPrice`, message: 'required' });
      } else if (typeof lineObj.unitPrice !== 'number') {
        lineErrors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
      } else if (lineObj.unitPrice < 0) {
        lineErrors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
      }

      // Check unknown fields in line
      for (const field of lineFields) {
        if (!['sku', 'quantity', 'unitPrice'].includes(field)) {
          unknownLineFields.push(field);
        }
      }

      // Add line errors in order: sku, quantity, unitPrice, then unknown fields
      errors.push(...lineErrors);
      for (const field of unknownLineFields) {
        errors.push({ path: `${linePath}.${field}`, message: 'unknown field' });
      }

      // If no errors in this line, create OrderLine
      if (lineErrors.length === 0 && unknownLineFields.length === 0) {
        orderLines.push(new OrderLine(
          lineObj.sku as string,
          lineObj.quantity as number,
          lineObj.unitPrice as number
        ));
      }
    }
  }

  // Check unknown fields in order
  for (const field of orderFields) {
    if (!['id', 'status', 'lines'].includes(field)) {
      unknownOrderFields.push(field);
    }
  }

  // Add unknown order fields at the end
  for (const field of unknownOrderFields) {
    errors.push({ path: field, message: 'unknown field' });
  }

  // If there are errors, return undefined order
  if (errors.length > 0) {
    return {
      order: undefined,
      errors: errors
    };
  }

  // Otherwise, return the order
  return {
    order: {
      id: obj.id as string,
      status: status as OrderStatus,
      lines: orderLines
    },
    errors: []
  };
}

