export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentTotal = result.get(expense.category) || 0;
    result.set(expense.category, currentTotal + expense.amount);
  }

  return result;
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private _state: EditorState;
  private history: EditorState[] = [];
  private future: EditorState[] = [];
  private historyLimit: number;
  private listeners: {
    text: Array<(value: string, previous: string) => void>;
    cursor: Array<(value: number, previous: number) => void>;
    bold: Array<(value: boolean, previous: boolean) => void>;
  } = {
    text: [],
    cursor: [],
    bold: []
  };

  constructor(initial: EditorState, historyLimit: number) {
    // Deep copy the initial state to avoid external mutations affecting the store
    this._state = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = Math.max(1, Math.floor(historyLimit));
  }

  get state(): EditorState {
    // Return a new object with current values
    return {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    // Check if any field actually changes
    const newText = patch.text !== undefined ? patch.text : this._state.text;
    const newCursor = patch.cursor !== undefined ? patch.cursor : this._state.cursor;
    const newBold = patch.bold !== undefined ? patch.bold : this._state.bold;

    // If nothing changes, return false
    if (newText === this._state.text && newCursor === this._state.cursor && newBold === this._state.bold) {
      return false;
    }

    // Save current state to history before applying changes
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Clear future since we're making a new change
    this.future = [];

    // Apply the changes
    this._state.text = newText;
    this._state.cursor = newCursor;
    this._state.bold = newBold;

    // Notify listeners
    this._notifyListeners(patch);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    // Create a draft copy of the current state
    const draft: EditorState = {
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    };

    try {
      // Call the run function with the draft
      run(draft);

      // Apply the draft as a patch
      return this.apply(draft);
    } catch {
      // If an error occurs, do nothing and rethrow
      throw new Error();
    }
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    // Save current state to future
    this.future.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Get previous state from history
    const previousState = this.history.pop()!;
    const previousStateCopy: EditorState = {
      text: previousState.text,
      cursor: previousState.cursor,
      bold: previousState.bold
    };

    // Set the new state
    this._state.text = previousState.text;
    this._state.cursor = previousState.cursor;
    this._state.bold = previousState.bold;

    // Notify listeners about changes
    this._notifyUndoRedoListeners(previousStateCopy);

    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    // Save current state to history
    this.history.push({
      text: this._state.text,
      cursor: this._state.cursor,
      bold: this._state.bold
    });

    // Trim history if it exceeds the limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Get next state from future
    const nextState = this.future.pop()!;
    const nextStateCopy: EditorState = {
      text: nextState.text,
      cursor: nextState.cursor,
      bold: nextState.bold
    };

    // Set the new state
    this._state.text = nextState.text;
    this._state.cursor = nextState.cursor;
    this._state.bold = nextState.bold;

    // Notify listeners about changes
    this._notifyUndoRedoListeners(nextStateCopy);

    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    // Validate field
    if (field !== 'text' && field !== 'cursor' && field !== 'bold') {
      throw new Error(`Invalid field: ${field}. Must be 'text', 'cursor', or 'bold'.`);
    }

    // Add listener to the appropriate array
    const listeners = this.listeners[field];
    listeners.push(listener);

    // Return a function to remove the listener
    return () => {
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    };
  }

  private _notifyListeners(patch: Partial<EditorState>): void {
    // Notify text listeners if text changed
    if (patch.text !== undefined) {
      const previousText = this.history.length > 0 ? this.history[this.history.length - 1].text : this._state.text;
      this.listeners.text.forEach(listener => {
        listener(this._state.text, previousText);
      });
    }

    // Notify cursor listeners if cursor changed
    if (patch.cursor !== undefined) {
      const previousCursor = this.history.length > 0 ? this.history[this.history.length - 1].cursor : this._state.cursor;
      this.listeners.cursor.forEach(listener => {
        listener(this._state.cursor, previousCursor);
      });
    }

    // Notify bold listeners if bold changed
    if (patch.bold !== undefined) {
      const previousBold = this.history.length > 0 ? this.history[this.history.length - 1].bold : this._state.bold;
      this.listeners.bold.forEach(listener => {
        listener(this._state.bold, previousBold);
      });
    }
  }

  private _notifyUndoRedoListeners(stateBeforeChange: EditorState): void {
    // Notify text listeners
    if (this._state.text !== stateBeforeChange.text) {
      this.listeners.text.forEach(listener => {
        listener(this._state.text, stateBeforeChange.text);
      });
    }

    // Notify cursor listeners
    if (this._state.cursor !== stateBeforeChange.cursor) {
      this.listeners.cursor.forEach(listener => {
        listener(this._state.cursor, stateBeforeChange.cursor);
      });
    }

    // Notify bold listeners
    if (this._state.bold !== stateBeforeChange.bold) {
      this.listeners.bold.forEach(listener => {
        listener(this._state.bold, stateBeforeChange.bold);
      });
    }
  }
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
}

@Entry
@Component
struct LogEntryPage {
  @State entries: LogEntry[] = [];
  @State isRefreshing: boolean = false;
  private refreshController: RefreshController = new RefreshController();

  aboutToAppear() {
    // Initialize 3000 entries
    this.entries = this.generateEntries(1, 3000);
  }

  generateEntries(startId: number, endId: number): LogEntry[] {
    const result: LogEntry[] = [];
    for (let i = startId; i <= endId; i++) {
      let level: string;
      if (i % 50 === 0) {
        level = 'error';
      } else if (i % 10 === 0) {
        level = 'warning';
      } else {
        level = 'info';
      }
      result.push(new LogEntry(i, `Event ${i}`, level));
    }
    return result;
  }

  onRefresh() {
    this.isRefreshing = true;

    // Simulate 1 second delay
    setTimeout(() => {
      const highestId = this.entries.length > 0 ? this.entries[0].id : 0;
      const newEntries = this.generateEntries(highestId + 1, highestId + 5);

      // Add new entries at the top
      this.entries = [...newEntries, ...this.entries];
      this.isRefreshing = false;
    }, 1000);
  }

  build() {
    Column() {
      Text(`Entries: ${this.entries.length}`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 })
        .textAlign(TextAlign.Center)

      List({ space: 8, initialIndex: 0 }) {
        ForEach(this.entries, (entry: LogEntry) => {
          LogEntryRow({ entry: entry })
        }, (item: LogEntry) => item.id.toString())
      }
      .width('100%')
      .height('80%')
      .scrollBar(BarState.Auto)
      .refreshController(this.refreshController)
    }
    .width('100%')
    .height('100%')
    .onChange('entries.length', () => {
      // This is a workaround to handle refresh logic
    })
  }
}

