export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  // Initialize min and max with the first point's values
  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  // Find the actual min and max coordinates
  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) {
      minX = point.x;
    }
    if (point.x > maxX) {
      maxX = point.x;
    }
    if (point.y < minY) {
      minY = point.y;
    }
    if (point.y > maxY) {
      maxY = point.y;
    }
  }

  // Create new Point objects for min and max
  const minPoint: Point = { x: minX, y: minY };
  const maxPoint: Point = { x: maxX, y: maxY };

  return {
    min: minPoint,
    max: maxPoint,
    width: maxX - minX,
    height: maxY - minY
  };
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query.length === 0) {
    return result;
  }

  // Split by '&' and process each pair
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty parts
    if (pair.length === 0) {
      continue;
    }

    // Split at first '='
    const eqIndex = pair.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found, key is the whole pair, value is empty
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (last value wins, but keep first position)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

// Helper function to decode URL components
function decodeComponent(str: string): string {
  // Replace '+' with space
  let result = str.replace(/\+/g, ' ');

  // Try to decode percent-escapes
  try {
    // Use decodeURIComponent but handle malformed escapes gracefully
    // We'll process the string character by character to handle malformed escapes
    let decoded = '';
    let i = 0;

    while (i < result.length) {
      if (result[i] === '%' && i + 2 < result.length) {
        const hex = result.substring(i + 1, i + 3);
        // Check if hex is valid (two hex digits)
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          // Try to decode the percent-encoded sequence
          try {
            // Convert hex to decimal and then to character
            const charCode = parseInt(hex, 16);
            // For multi-byte UTF-8 sequences, we need to handle them properly
            // We'll use a different approach: try decodeURIComponent on the whole string
            // but catch errors for malformed sequences
            decoded += String.fromCharCode(charCode);
            i += 3;
            continue;
          } catch (e) {
            // If decode fails, keep the original sequence
            decoded += result[i];
            i++;
            continue;
          }
        } else {
          // Invalid hex, keep the '%' and continue
          decoded += result[i];
          i++;
          continue;
        }
      } else {
        decoded += result[i];
        i++;
      }
    }

    // Now try to decode the whole string as UTF-8
    // We need to handle multi-byte sequences properly
    // Let's use a more robust approach
    try {
      // First, try to decode the whole string with decodeURIComponent
      // If it fails, return the string with '+' replaced by space
      return decodeURIComponent(str.replace(/\+/g, ' '));
    } catch (e) {
      // If decodeURIComponent fails, process manually
      // We'll do a more careful manual decoding
      let manualResult = '';
      let j = 0;

      while (j < str.length) {
        if (str[j] === '%' && j + 2 < str.length) {
          const hex = str.substring(j + 1, j + 3);
          if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
            try {
              // Try to decode this specific sequence
              const charCode = parseInt(hex, 16);
              manualResult += String.fromCharCode(charCode);
              j += 3;
              continue;
            } catch (e) {
              manualResult += str[j];
              j++;
              continue;
            }
          } else {
            manualResult += str[j];
            j++;
            continue;
          }
        } else if (str[j] === '+') {
          manualResult += ' ';
          j++;
          continue;
        } else {
          manualResult += str[j];
          j++;
        }
      }

      // Now try to decode the manual result as UTF-8
      // We need to handle multi-byte sequences properly
      // Let's use a different approach: try to decode the whole string
      // but handle errors by keeping malformed sequences
      try {
        return decodeURIComponent(manualResult.replace(/\+/g, ' '));
      } catch (e) {
        // If still fails, return the manual result
        return manualResult;
      }
    }
  } catch (e) {
    // If anything goes wrong, just replace '+' with space
    return str.replace(/\+/g, ' ');
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }

    const eventListeners = this.listeners.get(event)!;
    // Check if listener is already registered for this event
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }

    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    // Create a copy of the listeners array to ensure consistency during emit
    // This handles the requirement that changes during emit only affect later calls
    const eventListeners = this.listeners.get(event)!;
    const listenersCopy = [...eventListeners];

    for (const listener of listenersCopy) {
      listener(payload);
    }

    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    return this.listeners.get(event)!.length;
  }
}

