class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  // Ensure at least 1 attempt
  const maxAttempts = Math.max(1, attempts);
  let lastError: Error | undefined;

  for (let i = 1; i <= maxAttempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error as Error;
      // If this is the last attempt, we'll throw the RetryError
      if (i === maxAttempts && lastError !== undefined) {
        throw new RetryError(maxAttempts, lastError);
      }
    }
  }

  // This line should never be reached due to the loop logic
  if (lastError !== undefined) {
    throw new RetryError(maxAttempts, lastError);
  }

  // Fallback for unreachable case
  throw new RetryError(maxAttempts, new Error('Unknown error'));
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return "0s";
  }

  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);

  const hours = Math.floor(absSeconds / 3600);
  const minutes = Math.floor((absSeconds % 3600) / 60);
  const seconds = absSeconds % 60;

  let result = "";

  if (hours > 0) {
    result += `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    result += `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    result += `${seconds}s`;
  }

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  // Handle empty string
  if (!text || text.trim() === "") {
    return NaN;
  }

  // Check for leading space or trailing space
  if (text.startsWith(" ") || text.endsWith(" ")) {
    return NaN;
  }

  // Check for double spaces
  if (text.includes("  ")) {
    return NaN;
  }

  const parts = text.split(" ");
  let result = 0;
  let isNegative = false;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Check if part matches the expected pattern: one or more digits followed by h, m, or s
    const match = part.match(/^(\d+)([hms])$/);

    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    // Check for negative sign on first part only
    if (i === 0 && part.startsWith("-")) {
      // This case is handled by checking the sign separately
      // But our regex already captured the digits without the minus, so we need to handle it differently
      // Actually, let's restructure to handle the negative sign properly
      // Since we split by space, the first part might have a leading minus
      // Let's fix this by checking the original part for minus
      if (part.charAt(0) === '-') {
        isNegative = true;
        // Remove the minus and re-parse
        const cleanPart = part.substring(1);
        const cleanMatch = cleanPart.match(/^(\d+)([hms])$/);
        if (!cleanMatch) {
          return NaN;
        }
        const cleanValue = parseInt(cleanMatch[1], 10);
        const cleanUnit = cleanMatch[2];

        if (cleanUnit === 'h') {
          result += cleanValue * 3600;
        } else if (cleanUnit === 'm') {
          result += cleanValue * 60;
        } else if (cleanUnit === 's') {
          result += cleanValue;
        }
      } else {
        if (unit === 'h') {
          result += value * 3600;
        } else if (unit === 'm') {
          result += value * 60;
        } else if (unit === 's') {
          result += value;
        }
      }
    } else {
      if (unit === 'h') {
        result += value * 3600;
      } else if (unit === 'm') {
        result += value * 60;
      } else if (unit === 's') {
        result += value;
      }
    }
  }

  // Handle the negative sign for the first part
  if (text.charAt(0) === '-') {
    result = -result;
  }

  return result;
}

class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('Capacity must be a positive integer');
    }
    this.capacity = capacity;
    this.map = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    // If key already exists, remove it from order first
    if (this.map.has(key)) {
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else if (this.map.size >= this.capacity) {
      // Remove least recently used (first in order array)
      const lruKey = this.order.shift();
      if (lruKey !== undefined) {
        this.map.delete(lruKey);
      }
    }

    // Add to end of order (most recently used)
    this.order.push(key);
    this.map.set(key, value);
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }

    // Move key to end of order (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (least to most recently used)
    return [...this.order];
  }

  get size(): number {
    return this.map.size;
  }
}

export default LruCache;

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  try {
    const parsed = JSON.parse(json);

    // Check if the parsed value is an array
    if (!Array.isArray(parsed)) {
      return [];
    }

    const users: User[] = [];

    for (let i = 0; i < parsed.length; i++) {
      const item = parsed[i];

      // Skip non-object items
      if (item === null || typeof item !== 'object' || Array.isArray(item)) {
        continue;
      }

      // Check if id is a number and an integer
      const id = (item as { id: number }).id;
      if (typeof id !== 'number' || !Number.isInteger(id)) {
        continue;
      }

      // Check if name is a non-empty string
      const name = (item as { name: string }).name;
      if (typeof name !== 'string' || name.length === 0) {
        continue;
      }

      // Check if email is a string containing '@'
      const email = (item as { email: string }).email;
      if (typeof email !== 'string' || !email.includes('@')) {
        continue;
      }

      // Add valid user to the result
      users.push({
        id: id,
        name: name,
        email: email
      });
    }

    return users;
  } catch {
    // If JSON parsing fails, return empty array
    return [];
  }
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  // Handle edge cases: empty array or invalid size
  if (items.length === 0 || size < 1) {
    return [];
  }

  const result: T[][] = [];

  // Process items in chunks of 'size'
  for (let i = 0; i < items.length; i += size) {
    // Create a new array for each chunk
    result.push(items.slice(i, i + size));
  }

  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  // Determine the length of the shorter array
  const minLength = Math.min(a.length, b.length);

  // Create result array
  const result: Pair<A, B>[] = [];

  // Zip elements up to the minimum length
  for (let i = 0; i < minLength; i++) {
    result.push({
      first: a[i],
      second: b[i]
    });
  }

  return result;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  // If quantity is 0 or less, we want to remove the item
  if (quantity <= 0) {
    return items.filter(item => item.id !== id);
  }

  // Create a new array with updated item
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.id === id) {
      // Create a new object with the updated quantity
      result.push({
        id: item.id,
        name: item.name,
        quantity: quantity
      });
    } else {
      result.push({
        id: item.id,
        name: item.name,
        quantity: item.quantity
      });
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  // Start with a copy of the original items
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    result.push({
      id: items[i].id,
      name: items[i].name,
      quantity: items[i].quantity
    });
  }

  // Apply each change in order
  for (let i = 0; i < changes.length; i++) {
    const change = changes[i];
    // Only apply the change if the item still exists in the result
    let itemExists = false;
    for (let j = 0; j < result.length; j++) {
      if (result[j].id === change.id) {
        itemExists = true;
        break;
      }
    }

    if (itemExists) {
      // Apply the change using updateQuantity
      const newResult: Item[] = [];
      for (let j = 0; j < result.length; j++) {
        const item = result[j];
        if (item.id === change.id) {
          if (change.quantity > 0) {
            newResult.push({
              id: item.id,
              name: item.name,
              quantity: change.quantity
            });
          }
          // If quantity <= 0, skip adding this item (remove it)
        } else {
          newResult.push({
            id: item.id,
            name: item.name,
            quantity: item.quantity
          });
        }
      }
      result.length = 0;
      for (let j = 0; j < newResult.length; j++) {
        result.push(newResult[j]);
      }
    }
  }

  return result;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

interface Step {
  name: string;
  transform: Transform;
}

export class Pipeline {
  private steps: Step[] = [];

  constructor() {}

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, transform: step });
    return this;
  }

  run(text: string): string {
    return this.steps.reduce((acc, step) => step.transform(acc), text);
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    return steps.reduce((acc, step) => step(acc), text);
  };
}

