export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday
  openHour: number
  closeHour: number
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true
    }
  }
  return false
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Get all days that have at least one rule
  const daysWithRules = new Set<Weekday>()
  for (const rule of rules) {
    daysWithRules.add(rule.day)
  }

  // If no day has rules, return undefined
  if (daysWithRules.size === 0) {
    return undefined
  }

  // Start checking from the next day after the given day
  let currentDay = (day + 1) % 7

  // Check up to 7 days ahead (including wrapping around the week)
  for (let i = 0; i < 7; i++) {
    if (daysWithRules.has(currentDay)) {
      return currentDay
    }
    currentDay = (currentDay + 1) % 7
  }

  // This should never be reached since we know there's at least one day with rules
  return undefined
}

// Define a Shape interface with a type tag for discrimination
export interface Shape {
  type: 'circle' | 'rectangle' | 'triangle';
}

// Circle shape implementation
export interface CircleShape extends Shape {
  radius: number;
}

// Rectangle shape implementation
export interface RectangleShape extends Shape {
  width: number;
  height: number;
}

// Triangle shape implementation
export interface TriangleShape extends Shape {
  base: number;
  height: number;
}

// Factory function for circle
export function circle(radius: number): CircleShape {
  return {
    type: 'circle',
    radius: radius
  };
}

// Factory function for rectangle
export function rectangle(width: number, height: number): RectangleShape {
  return {
    type: 'rectangle',
    width: width,
    height: height
  };
}

// Factory function for triangle
export function triangle(base: number, height: number): TriangleShape {
  return {
    type: 'triangle',
    base: base,
    height: height
  };
}

// Calculate area of a shape
export function area(shape: Shape): number {
  if (shape.type === 'circle') {
    const circleShape = shape as CircleShape;
    return Math.PI * circleShape.radius * circleShape.radius;
  } else if (shape.type === 'rectangle') {
    const rectShape = shape as RectangleShape;
    return rectShape.width * rectShape.height;
  } else if (shape.type === 'triangle') {
    const triShape = shape as TriangleShape;
    return triShape.base * triShape.height / 2;
  }

  // This line should never be reached due to exhaustive checking above
  throw new Error(`Unknown shape type: ${shape.type}`);
}

// Calculate total area of an array of shapes
export function totalArea(shapes: Shape[]): number {
  if (shapes.length === 0) {
    return 0;
  }

  return shapes.reduce((sum, shape) => sum + area(shape), 0);
}

