import hilog from '@ohos.hilog';

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';
  @State emailError: string = '';
  @State passwordError: string = '';
  @State isSignInEnabled: boolean = false;

  // Email validation: exactly one '@', at least one char before, and after '@' a '.' with at least one char on each side
  validateEmail(email: string): boolean {
    if (email.length === 0) {
      return true; // Empty is considered valid (no error shown)
    }

    // Check for exactly one '@'
    const atIndex = email.indexOf('@');
    if (atIndex === -1 || email.indexOf('@', atIndex + 1) !== -1) {
      return false;
    }

    // Check for at least one char before '@'
    if (atIndex === 0) {
      return false;
    }

    // Check for '.' after '@' with at least one char on each side
    const domainPart = email.substring(atIndex + 1);
    const dotIndex = domainPart.indexOf('.');
    if (dotIndex === -1 || dotIndex === 0 || dotIndex === domainPart.length - 1) {
      return false;
    }

    return true;
  }

  // Password validation: at least 8 characters
  validatePassword(password: string): boolean {
    if (password.length === 0) {
      return true; // Empty is considered valid (no error shown)
    }

    return password.length >= 8;
  }

  // Update validation state when fields change
  updateValidation() {
    const emailValid = this.validateEmail(this.email);
    const passwordValid = this.validatePassword(this.password);

    // Set error messages only when field is not empty and invalid
    this.emailError = (this.email.length === 0 || emailValid) ? '' : 'Enter a valid email address';
    this.passwordError = (this.password.length === 0 || passwordValid) ? '' : 'Password must be at least 8 characters';

    // Sign in is enabled only when both fields are valid (non-empty and passing validation)
    this.isSignInEnabled = this.email.length > 0 && this.password.length > 0 && emailValid && passwordValid;
  }

  build() {
    Column() {
      Text('Sign In')
        .fontSize(32)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 30 })

      Column() {
        TextInput({
          text: this.$email,
          placeholder: 'Email'
        })
        .width('90%')
        .height(50)
        .fontSize(16)
        .border({ width: 1, color: '#cccccc', radius: 8 })
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.email = value;
          this.updateValidation();
        })
        .keyboardType(KeyBoardType.Email)

        if (this.emailError.length > 0) {
          Text(this.emailError)
            .fontSize(12)
            .fontColor('#ff0000')
            .margin({ top: 2, left: 5 })
        }
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)

      Column() {
        TextInput({
          text: this.$password,
          placeholder: 'Password'
        })
        .width('90%')
        .height(50)
        .fontSize(16)
        .border({ width: 1, color: '#cccccc', radius: 8 })
        .margin({ bottom: 10 })
        .onChange((value: string) => {
          this.password = value;
          this.updateValidation();
        })
        .password(true)

        if (this.passwordError.length > 0) {
          Text(this.passwordError)
            .fontSize(12)
            .fontColor('#ff0000')
            .margin({ top: 2, left: 5 })
        }
      }
      .width('100%')
      .alignItems(HorizontalAlign.Center)

      Button('Sign in')
        .width('90%')
        .height(50)
        .fontSize(18)
        .backgroundColor(this.isSignInEnabled ? '#007DFF' : '#cccccc')
        .fontColor(this.isSignInEnabled ? '#ffffff' : '#666666')
        .onClick(() => {
          hilog.info(0x0001, 'SignInPage', 'Sign in button clicked');
        })
        .opacity(this.isSignInEnabled ? 1.0 : 0.5)
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#f5f5f5')
    .justifyContent(FlexAlign.Start)
    .padding(20)
  }
}

import promptAction from '@ohos.promptAction';
import preferences from '@ohos.data.preferences';

@Entry
@Component
struct SolutionPage {
  @State savedName: string = "No name saved";
  @State inputName: string = "";
  private preferencesInstance: preferences.Preferences | null = null;

  aboutToAppear() {
    this.loadName();
  }

  async loadName() {
    try {
      const context = getContext(this) as unknown as AbilityContext;
      this.preferencesInstance = await preferences.getPreferences(context, 'userPreferences');
      const name = await this.preferencesInstance.get('savedName', 'No name saved');
      this.savedName = name as string;
    } catch (e) {
      console.error('Failed to load preferences:', e);
      this.savedName = "No name saved";
    }
  }

  async saveName() {
    if (this.inputName.trim() === "") {
      promptAction.showToast({ message: 'Please enter a name' });
      return;
    }

    try {
      if (this.preferencesInstance === null) {
        const context = getContext(this) as unknown as AbilityContext;
        this.preferencesInstance = await preferences.getPreferences(context, 'userPreferences');
      }

      await this.preferencesInstance.put('savedName', this.inputName.trim());
      await this.preferencesInstance.flush();

      this.savedName = this.inputName.trim();
      promptAction.showToast({ message: 'Name saved successfully' });
    } catch (e) {
      console.error('Failed to save preferences:', e);
      promptAction.showToast({ message: 'Failed to save name' });
    }
  }

  build() {
    Column() {
      // Display saved name
      Text(this.savedName)
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 20 })

      // Text input for name
      TextInput({
        text: this.inputName,
        placeholder: 'Enter your name'
      })
      .width('80%')
      .height(50)
      .border({ width: 1, color: Color.Gray, radius: 8 })
      .padding(10)
      .margin({ bottom: 20 })
      .onChange((value: string) => {
        this.inputName = value;
      })

      // Save button
      Button('Save')
        .width('80%')
        .height(50)
        .fontSize(18)
        .backgroundColor(Color.Blue)
        .foregroundColor(Color.White)
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

