// Global dark mode state using app context
const DARK_MODE_KEY = 'darkMode';

// Global context reference
let globalContext: any;

// Initialize context in the main application entry
export function setGlobalContext(context: any) {
  globalContext = context;
}

// Helper to get and set dark mode state in app context
function getDarkMode(): boolean {
  try {
    if (!globalContext) {
      return false;
    }
    const value = globalContext.getApplicationContext().getPersistentDataSync(DARK_MODE_KEY);
    return value === 'true';
  } catch (e) {
    return false;
  }
}

function setDarkMode(value: boolean) {
  try {
    if (!globalContext) {
      return;
    }
    globalContext.getApplicationContext().setPersistentDataSync(DARK_MODE_KEY, value.toString());
    // Notify all subscribers of the change
    globalContext.getApplicationContext().notifyDataChange(DARK_MODE_KEY);
  } catch (e) {
    console.error('Failed to set dark mode:', e);
  }
}

// Global state for dark mode
let darkModeState = getDarkMode();

// Subscribe to changes in dark mode
function subscribeToDarkModeChanges() {
  try {
    if (!globalContext) {
      return;
    }
    globalContext.getApplicationContext().on('dataChange', (key: string) => {
      if (key === DARK_MODE_KEY) {
        darkModeState = getDarkMode();
        darkModeCounter++;
      }
    });
  } catch (e) {
    console.error('Failed to subscribe to dark mode changes:', e);
  }
}

// Global counter to force re-renders when dark mode changes
let darkModeCounter = 0;

