interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  const len = source.length;

  while (i < len) {
    const char = source[i];

    // Skip spaces
    if (char === ' ') {
      i++;
      continue;
    }

    // Numbers: digits, optionally followed by '.' and more digits
    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < len && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      if (i < len && source[i] === '.' && i + 1 < len && source[i + 1] >= '0' && source[i + 1] <= '9') {
        i++; // consume '.'
        while (i < len && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Names: letter or underscore, followed by letters, digits, underscores
    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < len) {
        const c = source[i];
        if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c === '_') {
          i++;
        } else {
          break;
        }
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    // Operators and parentheses
    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({
        kind: 'paren',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    // Unexpected character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

// Token kinds
const KIND_NUMBER = 'number';
const KIND_NAME = 'name';
const KIND_OPERATOR = 'operator';
const KIND_PAREN = 'paren';

// Operator precedence and associativity
const PRECEDENCE: Record<string, number> = {
  '+': 1,
  '-': 1,
  '*': 2,
  '/': 2,
  '%': 2
};

function isUnaryOperator(token: Token): boolean {
  return token.kind === KIND_OPERATOR && token.text === '-';
}

function isBinaryOperator(token: Token): boolean {
  return token.kind === KIND_OPERATOR && token.text !== '-';
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  return parseExpression(tokens, 0, source.length, variables, source).value;
}

interface ParseResult {
  value: number;
  position: number;
}

function parseExpression(tokens: Token[], start: number, end: number, variables: Record<string, number>, source: string): ParseResult {
  return parseAdditive(tokens, start, end, variables, source);
}

function parseAdditive(tokens: Token[], start: number, end: number, variables: Record<string, number>, source: string): ParseResult {
  let left = parseMultiplicative(tokens, start, end, variables, source);
  let pos = left.position;

  while (pos < tokens.length) {
    const token = tokens[pos];
    if (token.kind !== KIND_OPERATOR || (token.text !== '+' && token.text !== '-')) {
      break;
    }

    const op = token.text;
    pos++;

    const right = parseMultiplicative(tokens, pos, end, variables, source);
    if (op === '+') {
      left.value = left.value + right.value;
    } else {
      left.value = left.value - right.value;
    }
    pos = right.position;
  }

  return { value: left.value, position: pos };
}

function parseMultiplicative(tokens: Token[], start: number, end: number, variables: Record<string, number>, source: string): ParseResult {
  let left = parseUnary(tokens, start, end, variables, source);
  let pos = left.position;

  while (pos < tokens.length) {
    const token = tokens[pos];
    if (token.kind !== KIND_OPERATOR || (token.text !== '*' && token.text !== '/' && token.text !== '%')) {
      break;
    }

    const op = token.text;
    pos++;

    const right = parseUnary(tokens, pos, end, variables, source);
    if (op === '*') {
      left.value = left.value * right.value;
    } else if (op === '/') {
      if (right.value === 0) {
        throw new ExpressionError('Division by zero', token.position);
      }
      left.value = left.value / right.value;
    } else { // op === '%'
      if (right.value === 0) {
        throw new ExpressionError('Division by zero', token.position);
      }
      left.value = left.value % right.value;
    }
    pos = right.position;
  }

  return { value: left.value, position: pos };
}

function parseUnary(tokens: Token[], start: number, end: number, variables: Record<string, number>, source: string): ParseResult {
  let pos = start;
  let negateCount = 0;

  while (pos < tokens.length && isUnaryOperator(tokens[pos])) {
    negateCount++;
    pos++;
  }

  let result = parsePrimary(tokens, pos, end, variables, source);
  pos = result.position;

  if (negateCount % 2 === 1) {
    result.value = -result.value;
  }

  return { value: result.value, position: pos };
}

function parsePrimary(tokens: Token[], start: number, end: number, variables: Record<string, number>, source: string): ParseResult {
  if (start >= tokens.length) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  const token = tokens[start];

  if (token.kind === KIND_NUMBER) {
    return {
      value: Number(token.text),
      position: start + 1
    };
  }

  if (token.kind === KIND_NAME) {
    // Check if variable exists without using 'in' operator or 'for...in'
    let found = false;
    const keys = Object.keys(variables);
    let i = 0;
    while (i < keys.length) {
      if (keys[i] === token.text) {
        found = true;
        break;
      }
      i++;
    }
    if (!found) {
      throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
    }
    return {
      value: variables[token.text],
      position: start + 1
    };
  }

  if (token.kind === KIND_PAREN && token.text === '(') {
    const inner = parseExpression(tokens, start + 1, end, variables, source);
    let pos = inner.position;

    if (pos >= tokens.length || tokens[pos].kind !== KIND_PAREN || tokens[pos].text !== ')') {
      if (pos >= tokens.length) {
        throw new ExpressionError('Unexpected end of expression', source.length);
      }
      throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
    }

    return {
      value: inner.value,
      position: pos + 1
    };
  }

  // Unexpected token
  throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
}

import { router, promptAction } from '@kit.ArkUI';

// LogEntry class
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

// LogEntryDataSource class implementing IDataSource
class LogEntryDataSource implements IDataSource {
  private entries: LogEntry[] = [];

  constructor() {
    // Initialize with 3000 entries
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
  }

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    // Return entries in reverse order (highest id first)
    return this.entries[this.entries.length - 1 - index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    // No dynamic changes to register for this implementation
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    // No dynamic changes to unregister for this implementation
  }

  addEntries(count: number): void {
    const startId = this.entries.length + 1;
    for (let i = startId; i < startId + count; i++) {
      this.entries.push(new LogEntry(i));
    }
  }

  getEntryCount(): number {
    return this.entries.length;
  }
}

// Component for a single log entry row
@Component
struct LogEntryRow {
  @Prop entry: LogEntry;

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontWeight(FontWeight.Normal)
        .margin({ left: 16, right: 8 })

      Text(this.entry.level)
        .fontSize(14)
        .fontWeight(FontWeight.Bold)
        .margin({ left: 8, right: 16 })
        .fontColor(this.getLevelColor(this.entry.level))
    }
    .width('100%')
    .height(48)
    .justifyContent(FlexAlign.SpaceBetween)
    .alignItems(VerticalAlign.Center)
  }

  getLevelColor(level: string): string {
    switch (level) {
      case 'error':
        return '#D32F2F';
      case 'warning':
        return '#F57C00';
      case 'info':
        return '#757575';
      default:
        return '#757575';
    }
  }
}

// Main page component
@Entry
@Component
struct LogPage {
  @State entryDataSource: LogEntryDataSource = new LogEntryDataSource();
  @State refreshing: boolean = false;
  @State refreshCounter: number = 0;

  aboutToAppear() {
    // Nothing special needed here, entries are already created in constructor
  }

  build() {
    Column() {
      // Top text showing entry count
      Text(`${this.entryDataSource.getEntryCount()} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 16 })
        .textAlign(TextAlign.Center)

      // List of entries with pull-to-refresh
      List({ initialIndex: 0, space: 0 }) {
        LazyForEach(
          this.entryDataSource,
          (item: LogEntry, index: number) => {
            LogEntryRow({ entry: item })
          },
          (item: LogEntry) => item.id.toString()
        )
      }
      .width('100%')
      .height('100%')
      .scrollBar(BarState.Off)
      .listDirection(Axis.Vertical)

      // Refresh component
      Refresh({
        refreshing: this.refreshing,
        friction: 2.5
      })
      .onStateChange((state: RefreshStatus) => {
        if (state === RefreshStatus.Refresh) {
          this.refreshing = true;
        } else {
          this.refreshing = false;
        }
      })
      .onRefreshing(() => {
        // Simulate 1 second refresh delay
        setTimeout(() => {
          // Add 5 new entries
          this.entryDataSource.addEntries(5);
          // Force UI update by incrementing refresh counter
          this.refreshCounter++;
        }, 1000);
      })
      .refreshOffset(80)
      .pullToRefresh(true)
      .pullDownRatio(2.5)
    }
    .width('100%')
    .height('100%')
  }
}

function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query.length === 0) {
    return result;
  }

  // Split by '&' and process each part
  const parts = query.split('&');

  for (const part of parts) {
    // Skip empty parts
    if (part.length === 0) {
      continue;
    }

    // Split at first '='
    const equalIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (equalIndex === -1) {
      // No '=' found, key is the whole part, value is empty
      key = part;
      value = '';
    } else {
      key = part.substring(0, equalIndex);
      value = part.substring(equalIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (last value wins, but first position is preserved)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

// Helper function to decode URL components
function decodeComponent(str: string): string {
  // Replace '+' with space
  let result = str.replace(/\+/g, ' ');

  // Try to decode percent-encoded characters
  try {
    // Use decodeURIComponent if available, but handle errors gracefully
    // Since we can't import, we'll implement our own decoding
    result = decodeURIComponentSafe(result);
  } catch (e) {
    // If decoding fails, return the string with '+' replaced
    return result;
  }

  return result;
}

// Safe decodeURIComponent implementation
function decodeURIComponentSafe(str: string): string {
  let result = '';
  let i = 0;

  while (i < str.length) {
    if (str[i] === '%' && i + 2 < str.length) {
      const hex = str.substring(i + 1, i + 3);
      // Check if it's a valid hex pair
      if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
        try {
          const code = parseInt(hex, 16);
          // For ASCII characters (0-127), we can use String.fromCharCode
          // For multi-byte UTF-8, we need to handle sequences
          if (code < 128) {
            result += String.fromCharCode(code);
            i += 3;
            continue;
          } else {
            // This is the start of a multi-byte sequence
            // We'll try to decode the full sequence
            const bytes: number[] = [code];
            let j = i + 3;

            // Check for continuation bytes (10xxxxxx pattern)
            while (j < str.length && 
                   str[j] === '%' && 
                   j + 2 < str.length) {
              const nextHex = str.substring(j + 1, j + 3);
              if (/^[0-9A-Fa-f]{2}$/.test(nextHex)) {
                const nextCode = parseInt(nextHex, 16);
                if ((nextCode & 0xC0) === 0x80) { // Continuation byte
                  bytes.push(nextCode);
                  j += 3;
                  continue;
                }
              }
              break;
            }

            // Try to decode the bytes as UTF-8
            try {
              // Create a Uint8Array with the bytes
              const uint8Array = new Uint8Array(bytes);
              // Use TextDecoder if available, but since we can't import,
              // we'll implement a simple UTF-8 decoder for common cases
              result += utf8DecodeBytes(uint8Array);
              i = j;
              continue;
            } catch (e) {
              // If decoding fails, keep the original percent encoding
              result += str.substring(i, i + 3);
              i += 3;
              continue;
            }
          }
        } catch (e) {
          // If parsing fails, keep the original percent encoding
          result += str.substring(i, i + 3);
          i += 3;
          continue;
        }
      }
    }

    // Not a percent-encoded sequence, just add the character
    result += str[i];
    i++;
  }

  return result;
}

// Simple UTF-8 decoder for common cases
function utf8DecodeBytes(bytes: Uint8Array): string {
  if (bytes.length === 0) {
    return '';
  }

  // Handle ASCII
  if (bytes.length === 1 && bytes[0] < 128) {
    return String.fromCharCode(bytes[0]);
  }

  // For HarmonyOS, we can try to use the built-in TextDecoder if available
  // But since we can't import, we'll implement a basic decoder
  let result = '';
  let i = 0;

  while (i < bytes.length) {
    const byte = bytes[i];

    if (byte < 128) {
      // ASCII
      result += String.fromCharCode(byte);
      i++;
    } else if ((byte & 0xE0) === 0xC0) {
      // 2-byte sequence
      if (i + 1 < bytes.length) {
        const byte2 = bytes[i + 1];
        if ((byte2 & 0xC0) === 0x80) {
          const code = ((byte & 0x1F) << 6) | (byte2 & 0x3F);
          result += String.fromCharCode(code);
          i += 2;
          continue;
        }
      }
      // Invalid sequence, add replacement character
      result += '\uFFFD';
      i++;
    } else if ((byte & 0xF0) === 0xE0) {
      // 3-byte sequence
      if (i + 2 < bytes.length) {
        const byte2 = bytes[i + 1];
        const byte3 = bytes[i + 2];
        if ((byte2 & 0xC0) === 0x80 && (byte3 & 0xC0) === 0x80) {
          const code = ((byte & 0x0F) << 12) | ((byte2 & 0x3F) << 6) | (byte3 & 0x3F);
          if (code < 0x10000) {
            result += String.fromCharCode(code);
          } else {
            // For codepoints > 0xFFFF, use surrogate pairs
            const surrogate1 = 0xD800 + ((code - 0x10000) >> 10);
            const surrogate2 = 0xDC00 + ((code - 0x10000) & 0x3FF);
            result += String.fromCharCode(surrogate1) + String.fromCharCode(surrogate2);
          }
          i += 3;
          continue;
        }
      }
      // Invalid sequence, add replacement character
      result += '\uFFFD';
      i++;
    } else if ((byte & 0xF8) === 0xF0) {
      // 4-byte sequence
      if (i + 3 < bytes.length) {
        const byte2 = bytes[i + 1];
        const byte3 = bytes[i + 2];
        const byte4 = bytes[i + 3];
        if ((byte2 & 0xC0) === 0x80 && (byte3 & 0xC0) === 0x80 && (byte4 & 0xC0) === 0x80) {
          const code = ((byte & 0x07) << 18) | ((byte2 & 0x3F) << 12) | ((byte3 & 0x3F) << 6) | (byte4 & 0x3F);
          if (code >= 0x10000 && code < 0x110000) {
            const surrogate1 = 0xD800 + ((code - 0x10000) >> 10);
            const surrogate2 = 0xDC00 + ((code - 0x10000) & 0x3FF);
            result += String.fromCharCode(surrogate1) + String.fromCharCode(surrogate2);
            i += 4;
            continue;
          }
        }
      }
      // Invalid sequence, add replacement character
      result += '\uFFFD';
      i++;
    } else {
      // Invalid UTF-8 start byte, add replacement character
      result += '\uFFFD';
      i++;
    }
  }

  return result;
}

