class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];
  private dependencies: Map<string, string[]>;
  private orderResult: string[] | null = null;
  private layersResult: string[][] | null = null;

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);
    this.dependencies = new Map<string, string[]>();

    // Validate dependencies exist
    for (const task of this.tasks) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!this.hasKey(spec, dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Check for cycles using DFS
    const visited = new Set<string>();
    const inStack = new Set<string>();
    const path: string[] = [];

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        this.dfsCheckCycle(task, visited, inStack, path);
      }
    }
  }

  private hasKey(obj: Record<string, string[]>, key: string): boolean {
    // Check if key exists without using 'in' operator or prototype methods
    const keys = Object.keys(obj);
    for (let i = 0; i < keys.length; i++) {
      if (keys[i] === key) {
        return true;
      }
    }
    return false;
  }

  private dfsCheckCycle(task: string, visited: Set<string>, inStack: Set<string>, path: string[]): void {
    visited.add(task);
    inStack.add(task);
    path.push(task);

    const deps = this.spec[task];
    for (const dep of deps) {
      if (inStack.has(dep)) {
        // Found cycle: extract path from dep to current task, then add dep again
        const cycleStartIndex = path.indexOf(dep);
        const cyclePath = path.slice(cycleStartIndex);
        cyclePath.push(dep);
        throw new CycleError(cyclePath);
      }

      if (!visited.has(dep)) {
        this.dfsCheckCycle(dep, visited, inStack, path);
      }
    }

    inStack.delete(task);
    path.pop();
  }

  order(): string[] {
    if (this.orderResult !== null) {
      return this.orderResult;
    }

    const result: string[] = [];
    const placed = new Set<string>();

    for (const task of this.tasks) {
      if (!placed.has(task)) {
        this.placeTask(task, placed, result);
      }
    }

    this.orderResult = result;
    return result;
  }

  private placeTask(task: string, placed: Set<string>, result: string[]): void {
    const deps = this.spec[task];
    for (const dep of deps) {
      if (!placed.has(dep)) {
        this.placeTask(dep, placed, result);
      }
    }
    result.push(task);
    placed.add(task);
  }

  layers(): string[][] {
    if (this.layersResult !== null) {
      return this.layersResult;
    }

    if (this.tasks.length === 0) {
      this.layersResult = [];
      return this.layersResult;
    }

    const layerMap = new Map<string, number>();
    const order = this.order();

    for (const task of order) {
      const deps = this.spec[task];
      let maxLayer = -1;

      for (const dep of deps) {
        const depLayer = layerMap.get(dep) ?? 0;
        if (depLayer > maxLayer) {
          maxLayer = depLayer;
        }
      }

      layerMap.set(task, maxLayer + 1);
    }

    const maxLayer = Math.max(...Array.from(layerMap.values()));
    const layers: string[][] = [];

    for (let i = 0; i <= maxLayer; i++) {
      layers.push([]);
    }

    for (const task of order) {
      const layer = layerMap.get(task) ?? 0;
      layers[layer].push(task);
    }

    this.layersResult = layers;
    return this.layersResult;
  }

  dependentsOf(name: string): string[] {
    const order = this.order();
    const dependents: string[] = [];
    const visited = new Set<string>();

    // BFS to find all tasks that depend on 'name' directly or indirectly
    const queue: string[] = [name];

    while (queue.length > 0) {
      const current = queue.shift()!;
      const deps = this.spec[current];

      for (const task of order) {
        if (!visited.has(task)) {
          const taskDeps = this.spec[task];
          if (taskDeps.includes(current) && !visited.has(task)) {
            if (task !== name) {
              dependents.push(task);
            }
            visited.add(task);
            queue.push(task);
          }
        }
      }
    }

    return dependents;
  }
}

interface Expense {
  category: string;
  amount: number;
}

function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result: Map<string, number> = new Map();

  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const category = expense.category;
    const amount = expense.amount;

    if (result.has(category)) {
      result.set(category, result.get(category)! + amount);
    } else {
      result.set(category, amount);
    }
  }

  return result;
}

interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const result: Settings = {
    theme: defaults.theme,
    fontSize: defaults.fontSize,
    notifications: defaults.notifications,
    language: defaults.language
  };

  if (user.theme !== undefined) {
    result.theme = user.theme;
  }

  if (user.fontSize !== undefined) {
    result.fontSize = user.fontSize;
  }

  if (user.notifications !== undefined) {
    result.notifications = user.notifications;
  }

  if (user.language !== undefined) {
    result.language = user.language;
  }

  return result;
}

interface JobOutcome<T> {
  ok: boolean
  value: T | undefined
  error: Error | undefined
}

class JobQueue {
  private concurrency: number
  private runningCount: number = 0
  private waitingJobs: Array<WaitingJob<unknown>> = []
  private completedCount: number = 0
  private failedCount: number = 0
  private paused: boolean = false
  private idlePromise: Promise<void> | null = null
  private idleResolver: (() => void) | null = null

  constructor(concurrency: number) {
    this.concurrency = Math.max(1, Math.floor(concurrency))
  }

  private startNextJob(): void {
    if (this.paused || this.runningCount >= this.concurrency || this.waitingJobs.length === 0) {
      return
    }

    const jobEntry = this.waitingJobs.shift()!
    const job = jobEntry.job
    const resolve = jobEntry.resolve
    const reject = jobEntry.reject
    this.runningCount++

    job().then((value) => {
      this.runningCount--
      this.completedCount++
      resolve(value)
      this.checkIdle()
      this.startNextJob()
    }).catch((error) => {
      this.runningCount--
      this.failedCount++
      reject(error)
      this.checkIdle()
      this.startNextJob()
    })
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.waitingJobs.length === 0 && this.idleResolver !== null) {
      const resolver = this.idleResolver
      this.idleResolver = null
      this.idlePromise = null
      resolver()
    }
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push(new WaitingJob<T>(job, resolve, reject))
      this.startNextJob()
    })
  }

  get running(): number {
    return this.runningCount
  }

  get waiting(): number {
    return this.waitingJobs.length
  }

  get completed(): number {
    return this.completedCount
  }

  get failed(): number {
    return this.failedCount
  }

  pause(): void {
    this.paused = true
  }

  resume(): void {
    this.paused = false
    while (this.runningCount < this.concurrency && this.waitingJobs.length > 0) {
      this.startNextJob()
    }
  }

  clear(): number {
    const removedCount = this.waitingJobs.length
    const error = new Error('Job was cancelled')

    for (let i = 0; i < this.waitingJobs.length; i++) {
      const jobEntry = this.waitingJobs[i]
      jobEntry.reject(error)
    }

    this.waitingJobs = []
    this.checkIdle()

    return removedCount
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve()
    }

    if (this.idlePromise === null) {
      this.idlePromise = new Promise<void>((resolve) => {
        this.idleResolver = resolve
      })
    }

    return this.idlePromise
  }

  async runAll<T>(jobs: Array<() => Promise<T>>): Promise<Array<JobOutcome<T>>> {
    const outcomes: Array<JobOutcome<T>> = []

    // Add all jobs to the queue
    const promises: Array<Promise<JobOutcome<T>>> = []
    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i]
      const promise = this.add<T>(job).then((value) => {
        return new JobOutcomeImpl<T>(true, value, undefined)
      }).catch((error) => {
        return new JobOutcomeImpl<T>(false, undefined, error)
      })
      promises.push(promise)
    }

    // Wait for all jobs to settle
    const results = await Promise.all(promises)

    // Return outcomes in the same order as jobs
    return results
  }
}

class WaitingJob<T> {
  job: () => Promise<T>
  resolve: (value: T) => void
  reject: (reason: Error) => void

  constructor(job: () => Promise<T>, resolve: (value: T) => void, reject: (reason: Error) => void) {
    this.job = job
    this.resolve = resolve
    this.reject = reject
  }
}

class JobOutcomeImpl<T> implements JobOutcome<T> {
  ok: boolean
  value: T | undefined
  error: Error | undefined

  constructor(ok: boolean, value: T | undefined, error: Error | undefined) {
    this.ok = ok
    this.value = value
    this.error = error
  }
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) {
      minX = point.x;
    }
    if (point.y < minY) {
      minY = point.y;
    }
    if (point.x > maxX) {
      maxX = point.x;
    }
    if (point.y > maxY) {
      maxY = point.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY
  };
}

class MyStack<T> {
  private capacity: number;
  private items: T[] = [];

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private currentState: EditorState;
  private history: EditorState[];
  private historyIndex: number;
  private historyLimit: number;
  private redoStack: EditorState[];
  private listeners: {
    text: Array<(newVal: string, prevVal: string) => void>;
    cursor: Array<(newVal: number, prevVal: number) => void>;
    bold: Array<(newVal: boolean, prevVal: boolean) => void>;
  };

  constructor(initial: EditorState, historyLimit: number) {
    // Make a deep copy of initial state to avoid external mutations affecting the store
    this.currentState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };

    if (historyLimit < 1) {
      this.historyLimit = 1;
    } else {
      this.historyLimit = historyLimit;
    }

    this.history = [];
    this.historyIndex = -1;
    this.redoStack = [];

    this.listeners = {
      text: [],
      cursor: [],
      bold: []
    };
  }

  get state(): EditorState {
    return {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    const prevText = this.currentState.text;
    const prevCursor = this.currentState.cursor;
    const prevBold = this.currentState.bold;

    let changed = false;

    if (patch.text !== undefined) {
      this.currentState.text = patch.text;
      changed = true;
    }

    if (patch.cursor !== undefined) {
      this.currentState.cursor = patch.cursor;
      changed = true;
    }

    if (patch.bold !== undefined) {
      this.currentState.bold = patch.bold;
      changed = true;
    }

    if (!changed) {
      return false;
    }

    // Clear redo stack on new action
    this.redoStack = [];

    // Add to history
    this.historyIndex++;
    if (this.historyIndex < this.history.length) {
      this.history[this.historyIndex] = {
        text: prevText,
        cursor: prevCursor,
        bold: prevBold
      };
    } else {
      this.history.push({
        text: prevText,
        cursor: prevCursor,
        bold: prevBold
      });
    }

    // Trim history if it exceeds limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
      this.historyIndex = this.history.length - 1;
    }

    // Notify listeners
    this.notifyListeners(prevText, prevCursor, prevBold);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    // Create a draft copy
    const draft: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    try {
      run(draft);
    } catch (e) {
      if (e instanceof Error) {
        throw e;
      }
      throw new Error(String(e));
    }

    // Apply the draft as a patch
    return this.apply(draft);
  }

  undo(): boolean {
    if (this.historyIndex < 0) {
      return false;
    }

    // Save current state to redo stack
    this.redoStack.push({
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    });

    // Restore previous state from history
    const prev = this.history[this.historyIndex];
    this.currentState.text = prev.text;
    this.currentState.cursor = prev.cursor;
    this.currentState.bold = prev.bold;

    this.historyIndex--;

    // Notify listeners
    this.notifyListeners(prev.text, prev.cursor, prev.bold);

    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }

    // Save current state to history
    this.historyIndex++;
    if (this.historyIndex < this.history.length) {
      this.history[this.historyIndex] = {
        text: this.currentState.text,
        cursor: this.currentState.cursor,
        bold: this.currentState.bold
      };
    } else {
      this.history.push({
        text: this.currentState.text,
        cursor: this.currentState.cursor,
        bold: this.currentState.bold
      });
    }

    // Trim history if it exceeds limit
    if (this.history.length > this.historyLimit) {
      this.history.shift();
      this.historyIndex = this.history.length - 1;
    }

    // Restore state from redo stack
    const next = this.redoStack.pop()!;
    this.currentState.text = next.text;
    this.currentState.cursor = next.cursor;
    this.currentState.bold = next.bold;

    // Notify listeners
    this.notifyListeners(next.text, next.cursor, next.bold);

    return true;
  }

  get canUndo(): boolean {
    return this.historyIndex >= 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (field === 'text') {
      this.listeners.text.push(listener as (newVal: string, prevVal: string) => void);
      return () => {
        const index = this.listeners.text.indexOf(listener as (newVal: string, prevVal: string) => void);
        if (index !== -1) {
          this.listeners.text.splice(index, 1);
        }
      };
    } else if (field === 'cursor') {
      this.listeners.cursor.push(listener as (newVal: number, prevVal: number) => void);
      return () => {
        const index = this.listeners.cursor.indexOf(listener as (newVal: number, prevVal: number) => void);
        if (index !== -1) {
          this.listeners.cursor.splice(index, 1);
        }
      };
    } else if (field === 'bold') {
      this.listeners.bold.push(listener as (newVal: boolean, prevVal: boolean) => void);
      return () => {
        const index = this.listeners.bold.indexOf(listener as (newVal: boolean, prevVal: boolean) => void);
        if (index !== -1) {
          this.listeners.bold.splice(index, 1);
        }
      };
    }

    // Return a no-op function for invalid field names
    return () => {};
  }

  private notifyListeners(prevText: string, prevCursor: number, prevBold: boolean): void {
    // Notify text listeners
    if (this.currentState.text !== prevText) {
      for (const listener of this.listeners.text) {
        listener(this.currentState.text, prevText);
      }
    }

    // Notify cursor listeners
    if (this.currentState.cursor !== prevCursor) {
      for (const listener of this.listeners.cursor) {
        listener(this.currentState.cursor, prevCursor);
      }
    }

    // Notify bold listeners
    if (this.currentState.bold !== prevBold) {
      for (const listener of this.listeners.bold) {
        listener(this.currentState.bold, prevBold);
      }
    }
  }
}

interface User {
  id: number;
  name: string;
  email: string;
}

interface JsonObject {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  try {
    const parsed: unknown = JSON.parse(json);
    if (!Array.isArray(parsed)) {
      return [];
    }

    const users: User[] = [];
    for (let i = 0; i < parsed.length; i++) {
      const element: unknown = parsed[i];

      // Skip non-objects
      if (element === null || typeof element !== 'object' || Array.isArray(element)) {
        continue;
      }

      // Check id: must be a number and an integer
      const idValue: unknown = (element as JsonObject).id;
      if (typeof idValue !== 'number' || !Number.isInteger(idValue)) {
        continue;
      }

      // Check name: must be a non-empty string
      const nameValue: unknown = (element as JsonObject).name;
      if (typeof nameValue !== 'string' || nameValue.length === 0) {
        continue;
      }

      // Check email: must be a string containing '@'
      const emailValue: unknown = (element as JsonObject).email;
      if (typeof emailValue !== 'string' || emailValue.indexOf('@') === -1) {
        continue;
      }

      // Valid user - create with only required fields
      users.push({
        id: idValue as number,
        name: nameValue as string,
        email: emailValue as string
      });
    }

    return users;
  } catch (e) {
    // Invalid JSON or any other error - return empty array
    return [];
  }
}

