export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private events: Map<string, Listener<T>[]> = new Map();

  constructor() {}

  on(event: string, listener: Listener<T>): void {
    let listeners = this.events.get(event);
    if (!listeners) {
      listeners = [];
      this.events.set(event, listeners);
    }
    if (!listeners.includes(listener)) {
      listeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const listeners = this.events.get(event);
    if (listeners) {
      const index = listeners.indexOf(listener);
      if (index !== -1) {
        listeners.splice(index, 1);
      }
    }
  }

  emit(event: string, payload: T): number {
    const listeners = this.events.get(event);
    if (!listeners) {
      return 0;
    }
    // Create a copy to ensure that modifications during emit don't affect current call
    const listenersCopy = listeners.slice();
    for (const listener of listenersCopy) {
      listener(payload);
    }
    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    const listeners = this.events.get(event);
    return listeners ? listeners.length : 0;
  }
}

enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

interface FieldError {
  path: string;
  message: string;
}

interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
  let obj: Record<string, unknown>;
  try {
    obj = JSON.parse(text);
  } catch (e) {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }

  if (obj === null || typeof obj !== 'object' || Array.isArray(obj)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const errors: FieldError[] = [];

  // Helper to check if a value is a number (and not NaN)
  function isNumber(value: unknown): value is number {
    return typeof value === 'number' && !isNaN(value as number);
  }

  // Helper to check if a number is a whole number >= 1
  function isWholeNumberAtLeastOne(value: unknown): value is number {
    return isNumber(value) && Number.isInteger(value as number) && (value as number) >= 1;
  }

  // Helper to check if a number is >= 0
  function isNonNegativeNumber(value: unknown): value is number {
    return isNumber(value) && (value as number) >= 0;
  }

  // Helper to check if a value is a string
  function isString(value: unknown): value is string {
    return typeof value === 'string';
  }

  // Helper to check if a value is an array
  function isArray(value: unknown): value is unknown[] {
    return Array.isArray(value);
  }

  // Helper to check if a value is an object (but not null or array)
  function isObject(value: unknown): value is Record<string, unknown> {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
  }

  // Process id field
  if (!Object.prototype.hasOwnProperty.call(obj, 'id')) {
    errors.push({ path: 'id', message: 'required' });
  } else {
    const idValue = obj.id;
    if (idValue === null) {
      errors.push({ path: 'id', message: 'required' });
    } else if (!isString(idValue)) {
      errors.push({ path: 'id', message: 'expected a string' });
    } else if (idValue === '') {
      errors.push({ path: 'id', message: 'must not be empty' });
    }
  }

  // Process status field
  let statusValue: OrderStatus = OrderStatus.Draft;
  if (Object.prototype.hasOwnProperty.call(obj, 'status')) {
    const status = obj.status;
    if (status === null) {
      // null is treated like missing, so use default
      statusValue = OrderStatus.Draft;
    } else if (typeof status === 'string' && (status === 'draft' || status === 'paid' || status === 'shipped')) {
      statusValue = status as OrderStatus;
    } else {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  }

  // Process lines field
  let linesValue: unknown[] = [];
  if (!Object.prototype.hasOwnProperty.call(obj, 'lines')) {
    errors.push({ path: 'lines', message: 'required' });
  } else {
    const lines = obj.lines;
    if (lines === null) {
      errors.push({ path: 'lines', message: 'required' });
    } else if (!isArray(lines)) {
      errors.push({ path: 'lines', message: 'expected an array' });
    } else if ((lines as unknown[]).length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
      linesValue = lines as unknown[];
    }
  }

  // Process lines elements
  const orderLines: OrderLine[] = [];
  const lineErrors: FieldError[] = [];
  const lineUnknownFields: FieldError[] = [];

  if (linesValue.length > 0) {
    for (let i = 0; i < linesValue.length; i++) {
      const line = linesValue[i];
      const linePathPrefix = `lines[${i}]`;

      // Check if line is an object
      if (line === null || !isObject(line)) {
        lineErrors.push({ path: linePathPrefix, message: 'expected an object' });
        continue;
      }

      const lineObj = line as Record<string, unknown>;

      // Process sku field
      if (!Object.prototype.hasOwnProperty.call(lineObj, 'sku')) {
        lineErrors.push({ path: `${linePathPrefix}.sku`, message: 'required' });
      } else {
        const sku = lineObj.sku;
        if (sku === null) {
          lineErrors.push({ path: `${linePathPrefix}.sku`, message: 'required' });
        } else if (!isString(sku)) {
          lineErrors.push({ path: `${linePathPrefix}.sku`, message: 'expected a string' });
        } else if (sku === '') {
          lineErrors.push({ path: `${linePathPrefix}.sku`, message: 'must not be empty' });
        }
      }

      // Process quantity field
      if (!Object.prototype.hasOwnProperty.call(lineObj, 'quantity')) {
        lineErrors.push({ path: `${linePathPrefix}.quantity`, message: 'required' });
      } else {
        const quantity = lineObj.quantity;
        if (quantity === null) {
          lineErrors.push({ path: `${linePathPrefix}.quantity`, message: 'required' });
        } else if (!isNumber(quantity)) {
          lineErrors.push({ path: `${linePathPrefix}.quantity`, message: 'expected a number' });
        } else if (!isWholeNumberAtLeastOne(quantity)) {
          lineErrors.push({ path: `${linePathPrefix}.quantity`, message: 'must be a whole number of 1 or more' });
        }
      }

      // Process unitPrice field
      if (!Object.prototype.hasOwnProperty.call(lineObj, 'unitPrice')) {
        lineErrors.push({ path: `${linePathPrefix}.unitPrice`, message: 'required' });
      } else {
        const unitPrice = lineObj.unitPrice;
        if (unitPrice === null) {
          lineErrors.push({ path: `${linePathPrefix}.unitPrice`, message: 'required' });
        } else if (!isNumber(unitPrice)) {
          lineErrors.push({ path: `${linePathPrefix}.unitPrice`, message: 'expected a number' });
        } else if (!isNonNegativeNumber(unitPrice)) {
          lineErrors.push({ path: `${linePathPrefix}.unitPrice`, message: 'must be 0 or more' });
        }
      }

      // Process unknown fields in line
      const lineKeys = Object.keys(lineObj);
      for (let j = 0; j < lineKeys.length; j++) {
        const key = lineKeys[j];
        if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
          lineUnknownFields.push({ path: `${linePathPrefix}.${key}`, message: 'unknown field' });
        }
      }
    }
  }

  // Collect line errors in order: first the line-level errors, then unknown fields
  errors.push(...lineErrors);
  errors.push(...lineUnknownFields);

  // Process unknown fields in order
  const orderKeys = Object.keys(obj);
  for (let i = 0; i < orderKeys.length; i++) {
    const key = orderKeys[i];
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  // If there are errors, return undefined order
  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  }

  // Build order lines
  for (let i = 0; i < linesValue.length; i++) {
    const line = linesValue[i] as Record<string, unknown>;
    const sku = line.sku as string;
    const quantity = line.quantity as number;
    const unitPrice = line.unitPrice as number;
    orderLines.push(new OrderLine(sku, quantity, unitPrice));
  }

  // Build order
  const order: Order = {
    id: obj.id as string,
    status: statusValue,
    lines: orderLines
  };

  return { order: order, errors: [] };
}

