export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return '0s';
  }

  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);
  let result = '';

  const hours = Math.floor(absSeconds / 3600);
  const minutes = Math.floor((absSeconds % 3600) / 60);
  const seconds = absSeconds % 60;

  if (hours > 0) {
    result = `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    result = `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    result = `${seconds}s`;
  }

  if (isNegative) {
    result = `-${result}`;
  }

  return result;
}

export function parseDuration(text: string): number {
  if (text === '') {
    return NaN;
  }

  const parts = text.split(' ');
  if (parts.length === 0) {
    return NaN;
  }

  let isNegative = false;
  let totalSeconds = 0;
  let firstPartProcessed = false;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part === '') {
      return NaN;
    }

    // Check for negative sign on first part
    if (i === 0 && part.startsWith('-')) {
      isNegative = true;
      const withoutSign = part.substring(1);
      if (withoutSign === '') {
        return NaN;
      }
      const parsed = parseSinglePart(withoutSign);
      if (isNaN(parsed)) {
        return NaN;
      }
      totalSeconds += parsed;
      firstPartProcessed = true;
      continue;
    }

    const parsed = parseSinglePart(part);
    if (isNaN(parsed)) {
      return NaN;
    }
    totalSeconds += parsed;
    firstPartProcessed = true;
  }

  if (!firstPartProcessed) {
    return NaN;
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

function parseSinglePart(part: string): number {
  // Part must be one or more digits followed by h, m, or s
  const match = part.match(/^(\d+)([hms])$/);
  if (!match) {
    return NaN;
  }

  const value = Number(match[1]);
  const unit = match[2];

  switch (unit) {
    case 'h':
      return value * 3600;
    case 'm':
      return value * 60;
    case 's':
      return value;
    default:
      return NaN;
  }
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    const end = i + size;
    const chunkArray: T[] = [];
    for (let j = i; j < end && j < items.length; j++) {
      chunkArray.push(items[j]);
    }
    result.push(chunkArray);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length = a.length < b.length ? a.length : b.length;
  for (let i = 0; i < length; i++) {
    result.push({ first: a[i], second: b[i] });
  }
  return result;
}

// Define a Shape interface with an area method
interface Shape {
  area(): number;
}

// Circle class implementing Shape
class Circle implements Shape {
  private radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

// Rectangle class implementing Shape
class Rectangle implements Shape {
  private width: number;
  private height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

// Triangle class implementing Shape
class Triangle implements Shape {
  private base: number;
  private height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

// Export the Shape type with a different name to avoid conflict with built-in Shape
export type ShapeType = Shape;

// Export functions to create shapes
export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

// Export function to calculate total area
export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += area(shapes[i]);
  }
  return total;
}

