interface Item {
  id: string;
  name: string;
  quantity: number;
}

interface Change {
  id: string;
  quantity: number;
}

function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  if (quantity <= 0) {
    return items.filter((item) => item.id !== id);
  }

  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.id === id) {
      result.push({ id: item.id, name: item.name, quantity: quantity });
    } else {
      result.push({ id: item.id, name: item.name, quantity: item.quantity });
    }
  }
  return result;
}

function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result = items;
  const removedIds: Set<string> = new Set();

  for (let i = 0; i < changes.length; i++) {
    const change = changes[i];
    if (removedIds.has(change.id)) {
      continue;
    }

    const item = result.find((item) => item.id === change.id);
    if (item === undefined) {
      continue;
    }

    if (change.quantity <= 0) {
      removedIds.add(change.id);
      result = result.filter((item) => item.id !== change.id);
    } else {
      result = updateQuantity(result, change.id, change.quantity);
    }
  }

  return result;
}

