type Transform = (text: string) => string;

function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

interface Step {
  name: string;
  step: Transform;
}

class Pipeline {
  private steps: Step[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const step of this.steps) {
      result = step.step(result);
    }
    return result;
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string): string => {
      let result = text;
      for (const step of this.steps) {
        result = step.step(result);
      }
      return result;
    };
  }
}

function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // First, check if there are any rules at all
  let hasAnyRule = false;
  for (let i = 0; i < rules.length; i++) {
    hasAnyRule = true;
    break;
  }
  if (!hasAnyRule) {
    return undefined;
  }

  // Start checking from the next day after 'day'
  let currentDay = (day as number) + 1;
  if (currentDay > 6) {
    currentDay = 0;
  }

  // Iterate through all days of the week, wrapping around from Sunday to Monday
  for (let i = 0; i < 7; i++) {
    // Check if any rule exists for currentDay
    for (let j = 0; j < rules.length; j++) {
      if (rules[j].day === currentDay) {
        return currentDay as Weekday;
      }
    }

    // Move to next day
    currentDay = (currentDay + 1) % 7;
  }

  // If no day has a rule (shouldn't happen if hasAnyRule is true, but for safety)
  return undefined;
}

