class LruCacheNode<K, V> {
  key: K;
  value: V;
  prev: LruCacheNode<K, V> | undefined;
  next: LruCacheNode<K, V> | undefined;

  constructor() {
    this.key = undefined as K;
    this.value = undefined as V;
    this.prev = undefined;
    this.next = undefined;
  }
}

class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, LruCacheNode<K, V>>;
  private head: LruCacheNode<K, V> | undefined;
  private tail: LruCacheNode<K, V> | undefined;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.map = new Map<K, LruCacheNode<K, V>>();
    this.head = undefined;
    this.tail = undefined;
  }

  private moveToHead(node: LruCacheNode<K, V>): void {
    if (node === this.head) {
      return;
    }

    // Remove node from its current position
    if (node.prev !== undefined) {
      node.prev.next = node.next;
    }
    if (node.next !== undefined) {
      node.next.prev = node.prev;
    }
    if (node === this.tail) {
      this.tail = node.prev;
    }

    // Insert at head
    node.prev = undefined;
    node.next = this.head;
    if (this.head !== undefined) {
      this.head.prev = node;
    }
    this.head = node;
    if (this.tail === undefined) {
      this.tail = node;
    }
  }

  private addNewNode(key: K, value: V): LruCacheNode<K, V> {
    const node = new LruCacheNode<K, V>();
    node.key = key;
    node.value = value;
    node.prev = undefined;
    node.next = undefined;

    if (this.head === undefined) {
      this.head = node;
      this.tail = node;
    } else {
      node.next = this.head;
      this.head.prev = node;
      this.head = node;
    }

    return node;
  }

  private removeTail(): void {
    if (this.tail === undefined) {
      return;
    }

    const nodeToRemove = this.tail;
    this.tail = nodeToRemove.prev;

    if (this.tail !== undefined) {
      this.tail.next = undefined;
    } else {
      this.head = undefined;
    }

    this.map.delete(nodeToRemove.key);
  }

  set(key: K, value: V): void {
    let node = this.map.get(key);

    if (node !== undefined) {
      node.value = value;
      this.moveToHead(node);
    } else {
      // Create new node
      node = this.addNewNode(key, value);
      this.map.set(key, node);

      // Check capacity
      if (this.map.size > this.capacity) {
        this.removeTail();
      }
    }
  }

  get(key: K): V | undefined {
    const node = this.map.get(key);

    if (node === undefined) {
      return undefined;
    }

    this.moveToHead(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current = this.tail;

    while (current !== undefined) {
      result.push(current.key);
      current = current.next;
    }

    return result;
  }

  get size(): number {
    return this.map.size;
  }
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    if (/\d/.test(char)) {
      const start = i;
      while (i < source.length && /\d/.test(source[i])) {
        i++;
      }
      if (i < source.length && source[i] === '.') {
        i++;
        if (i >= source.length || !/\d/.test(source[i])) {
          throw new ExpressionError(`Unexpected character '${source[i]}'`, i);
        }
        while (i < source.length && /\d/.test(source[i])) {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (/[a-zA-Z_]/.test(char)) {
      const start = i;
      while (i < source.length && /[a-zA-Z0-9_]/.test(source[i])) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  let pos = 0;

  function peek(): Token | undefined {
    return tokens[pos];
  }

  function consume(): Token {
    if (pos >= tokens.length) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    return tokens[pos++];
  }

  function expect(kind: Token['kind']): Token {
    const token = peek();
    if (!token || token.kind !== kind) {
      if (!token) {
        throw new ExpressionError('Unexpected end of expression', source.length);
      }
      throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
    }
    return consume();
  }

  function parseExpression(): number {
    return parseAdditive();
  }

  function parseAdditive(): number {
    let result = parseMultiplicative();

    while (true) {
      const token = peek();
      if (token && (token.text === '+' || token.text === '-')) {
        const op = token.text;
        consume();
        const right = parseMultiplicative();
        if (op === '+') {
          result += right;
        } else {
          result -= right;
        }
      } else {
        break;
      }
    }

    return result;
  }

  function parseMultiplicative(): number {
    let result = parseUnary();

    while (true) {
      const token = peek();
      if (token && ['*', '/', '%'].includes(token.text)) {
        const op = token.text;
        consume();
        const right = parseUnary();
        if (op === '*') {
          result *= right;
        } else if (op === '/') {
          if (right === 0) {
            throw new ExpressionError('Division by zero', token.position);
          }
          result /= right;
        } else {
          if (right === 0) {
            throw new ExpressionError('Division by zero', token.position);
          }
          result %= right;
        }
      } else {
        break;
      }
    }

    return result;
  }

  function parseUnary(): number {
    const token = peek();
    if (token && token.text === '-') {
      consume();
      return -parsePrimary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      return parseFloat(consume().text);
    }

    if (token.kind === 'name') {
      const name = consume().text;
      if (!(name in variables)) {
        throw new ExpressionError(`Unknown variable '${name}'`, token.position);
      }
      return variables[name];
    }

    if (token.text === '(') {
      consume();
      const result = parseExpression();
      expect('paren');
      return result;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpression();

  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

