function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  if (!query) {
    return result;
  }

  // Remove leading '?' if present
  let cleanQuery = query;
  if (query.charAt(0) === '?') {
    cleanQuery = query.substring(1);
  }

  // Split by '&' and process each part
  const parts = cleanQuery.split('&');

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Skip empty parts
    if (part === '') {
      continue;
    }

    // Split at first '='
    const eqIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' means key with empty value
      key = part;
      value = '';
    } else {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key === '') {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (last value wins, but keep first position)
    if (!result.has(decodedKey)) {
      result.set(decodedKey, decodedValue);
    } else {
      result.set(decodedKey, decodedValue);
    }
  }

  return result;
}

function decodeComponent(str: string): string {
  // Replace '+' with space
  let result = str.replace(/\+/g, ' ');

  // Decode percent-escapes
  let i = 0;
  while (i < result.length) {
    if (result.charAt(i) === '%') {
      // Check if we have at least 2 more characters
      if (i + 2 < result.length) {
        const hex = result.substring(i + 1, i + 3);
        // Check if hex is valid (two hex digits)
        if (/^[0-9a-fA-F]{2}$/.test(hex)) {
          try {
            const code = parseInt(hex, 16);
            // Convert to UTF-8 character
            // For ASCII (0-127), direct conversion
            if (code < 128) {
              result = result.substring(0, i) + String.fromCharCode(code) + result.substring(i + 3);
              i++;
              continue;
            } else {
              // For multi-byte UTF-8 sequences, we need to handle them properly
              // First, collect the full UTF-8 sequence
              let bytes: number[] = [code];
              let j = i + 3;

              // Check for continuation bytes (10xxxxxx pattern)
              while (j < result.length && result.charAt(j) === '%' && j + 2 < result.length) {
                const nextHex = result.substring(j + 1, j + 3);
                if (/^[0-9a-fA-F]{2}$/.test(nextHex)) {
                  const nextCode = parseInt(nextHex, 16);
                  if (nextCode >= 128 && nextCode <= 191) { // Continuation byte
                    bytes.push(nextCode);
                    j = j + 3;
                  } else {
                    break;
                  }
                } else {
                  break;
                }
              }

              // Try to decode the UTF-8 sequence using util.TextDecoder
              try {
                const decoder = new util.TextDecoder('utf-8');
                const uint8Array = new Uint8Array(bytes);
                const decoded = decoder.decode(uint8Array);
                result = result.substring(0, i) + decoded + result.substring(j);
                i = i + decoded.length;
                continue;
              } catch (e) {
                // If decoding fails, keep the original percent-encoded form
                i++;
                continue;
              }
            }
          } catch (e) {
            // If parsing fails, keep the original percent-encoded form
            i++;
            continue;
          }
        } else {
          // Invalid hex, keep as is
          i++;
          continue;
        }
      } else {
        // Not enough characters for a percent escape
        i++;
        continue;
      }
    } else {
      i++;
    }
  }

  return result;
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];
  private taskDependencies: Record<string, string[]>;

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);
    this.taskDependencies = {};

    // Check for missing dependencies
    for (const task of this.tasks) {
      const dependencies = spec[task];
      for (const dependency of dependencies) {
        if (!(dependency in spec)) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    // Check for cycles
    const visited = new Set<string>();
    const visiting = new Set<string>();
    const path: string[] = [];

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        this._checkCycle(task, visited, visiting, path);
      }
    }
  }

  private _checkCycle(
    task: string,
    visited: Set<string>,
    visiting: Set<string>,
    path: string[]
  ): void {
    if (visiting.has(task)) {
      // Found a cycle
      const cycleStartIndex = path.indexOf(task);
      const cyclePath = path.slice(cycleStartIndex).concat(task);
      throw new CycleError(cyclePath);
    }

    if (visited.has(task)) {
      return;
    }

    visiting.add(task);
    path.push(task);

    const dependencies = this.spec[task] || [];
    for (const dependency of dependencies) {
      this._checkCycle(dependency, visited, visiting, path);
    }

    visiting.delete(task);
    path.pop();
    visited.add(task);
  }

  order(): string[] {
    const result: string[] = [];
    const placed = new Set<string>();

    const placeTask = (task: string) => {
      if (placed.has(task)) {
        return;
      }

      const dependencies = this.spec[task] || [];
      for (const dependency of dependencies) {
        placeTask(dependency);
      }

      result.push(task);
      placed.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task);
    }

    return result;
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    const result: string[][] = [];
    const placed = new Set<string>();
    const taskLayers: Record<string, number> = {};

    // Initialize all tasks to layer -1 (unplaced)
    for (const task of this.tasks) {
      taskLayers[task] = -1;
    }

    const placeTask = (task: string) => {
      if (placed.has(task)) {
        return;
      }

      const dependencies = this.spec[task] || [];
      let maxLayer = -1;

      for (const dependency of dependencies) {
        placeTask(dependency);
        maxLayer = Math.max(maxLayer, taskLayers[dependency]);
      }

      const layer = maxLayer + 1;
      taskLayers[task] = layer;

      if (result.length <= layer) {
        result.push([]);
      }

      result[layer].push(task);
      placed.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task);
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    const result: string[] = [];
    const visited = new Set<string>();

    // Find all tasks that depend on the given name
    const findDependents = (task: string) => {
      if (visited.has(task)) {
        return;
      }

      visited.add(task);

      const dependencies = this.spec[task] || [];
      if (dependencies.includes(name)) {
        result.push(task);
      }

      // Recursively check dependents of this task
      for (const dep of dependencies) {
        findDependents(dep);
      }
    };

    // Start from all tasks
    for (const task of this.tasks) {
      findDependents(task);
    }

    // Return in order
    const orderedTasks = this.order();
    return result.filter(task => orderedTasks.includes(task));
  }
}

