interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: Array<{ job: () => Promise<any>; resolve: (value: any) => void; reject: (reason?: any) => void }> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;

  constructor(concurrency: number) {
    if (concurrency < 1) {
      throw new Error("Concurrency must be at least 1");
    }
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({ job, resolve, reject });
      this.tryStartNext();
    });
  }

  private tryStartNext(): void {
    if (this.paused || this.runningJobs >= this.concurrency || this.waitingJobs.length === 0) {
      return;
    }

    const { job, resolve, reject } = this.waitingJobs.shift()!;
    this.runningJobs++;

    job()
      .then(value => {
        this.completedCount++;
        this.runningJobs--;
        resolve(value);
        this.tryStartNext();
      })
      .catch(error => {
        this.failedCount++;
        this.runningJobs--;
        reject(error);
        this.tryStartNext();
      });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.tryStartNext();
  }

  clear(): number {
    const count = this.waitingJobs.length;
    for (const { reject } of this.waitingJobs) {
      reject(new Error("Job was cancelled"));
    }
    this.waitingJobs = [];
    return count;
  }

  whenIdle(): Promise<void> {
    if (this.running === 0 && this.waiting === 0) {
      return Promise.resolve();
    }

    return new Promise(resolve => {
      const check = () => {
        if (this.running === 0 && this.waiting === 0) {
          resolve(undefined);
        } else {
          // Schedule next check
          setTimeout(check, 0);
        }
      };
      check();
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const outcomes: JobOutcome<T>[] = [];
    const promises: Promise<void>[] = [];

    for (const job of jobs) {
      const promise = this.add(job)
        .then(value => {
          outcomes.push({ ok: true, value, error: undefined });
        })
        .catch(error => {
          outcomes.push({ ok: false, value: undefined, error });
        });

      promises.push(promise);
    }

    return Promise.all(promises).then(() => outcomes);
  }
}

enum OrderStatus {
    Draft = 'draft',
    Paid = 'paid',
    Shipped = 'shipped'
}

class OrderLine {
    constructor(
        public sku: string,
        public quantity: number,
        public unitPrice: number
    ) {}

    total(): number {
        return this.quantity * this.unitPrice;
    }
}

interface Order {
    id: string;
    status: OrderStatus;
    lines: OrderLine[];
}

interface FieldError {
    path: string;
    message: string;
}

interface ParseResult {
    order: Order | undefined;
    errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
    let parsed: any;
    try {
        parsed = JSON.parse(text);
    } catch (e) {
        return {
            order: undefined,
            errors: [{ path: '', message: 'invalid JSON' }]
        };
    }

    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        return {
            order: undefined,
            errors: [{ path: '', message: 'expected an object' }]
        };
    }

    const errors: FieldError[] = [];

    // Helper to check required fields
    function checkRequired(value: any, path: string, fieldName: string): boolean {
        if (value === undefined || value === null) {
            errors.push({ path, message: 'required' });
            return false;
        }
        return true;
    }

    // Helper to check type
    function checkType(value: any, path: string, expectedType: string): boolean {
        if (typeof value !== expectedType) {
            errors.push({ path, message: `expected a ${expectedType}` });
            return false;
        }
        return true;
    }

    // Helper to check string conditions
    function checkString(value: any, path: string): boolean {
        if (!checkType(value, path, 'string')) return false;
        if (value === '') {
            errors.push({ path, message: 'must not be empty' });
            return false;
        }
        return true;
    }

    // Helper to check number conditions
    function checkNumber(value: any, path: string): boolean {
        if (!checkType(value, path, 'number')) return false;
        return true;
    }

    // Helper to check whole number >= 1
    function checkWholePositive(value: any, path: string): boolean {
        if (!checkNumber(value, path)) return false;
        if (value < 1 || !Number.isInteger(value)) {
            errors.push({ path, message: 'must be a whole number of 1 or more' });
            return false;
        }
        return true;
    }

    // Helper to check non-negative
    function checkNonNegative(value: any, path: string): boolean {
        if (!checkNumber(value, path)) return false;
        if (value < 0) {
            errors.push({ path, message: 'must be 0 or more' });
            return false;
        }
        return true;
    }

    // Check id
    let id: string | undefined = undefined;
    if (checkRequired(parsed.id, 'id', 'id') && checkString(parsed.id, 'id')) {
        id = parsed.id;
    }

    // Check status
    let status: OrderStatus = OrderStatus.Draft;
    if (parsed.status !== undefined && parsed.status !== null) {
        if (typeof parsed.status !== 'string') {
            errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
        } else if (parsed.status !== OrderStatus.Draft &&
                   parsed.status !== OrderStatus.Paid &&
                   parsed.status !== OrderStatus.Shipped) {
            errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
        } else {
            status = parsed.status as OrderStatus;
        }
    }

    // Check lines
    let lines: OrderLine[] = [];
    if (checkRequired(parsed.lines, 'lines', 'lines') && checkType(parsed.lines, 'lines', 'array')) {
        if (parsed.lines.length === 0) {
            errors.push({ path: 'lines', message: 'must not be empty' });
        } else {
            for (let i = 0; i < parsed.lines.length; i++) {
                const line = parsed.lines[i];
                const linePath = `lines[${i}]`;

                if (typeof line !== 'object' || line === null) {
                    errors.push({ path: linePath, message: 'expected an object' });
                    continue;
                }

                // Check sku
                let sku: string | undefined = undefined;
                if (checkRequired(line.sku, `${linePath}.sku`, 'sku') && checkString(line.sku, `${linePath}.sku`)) {
                    sku = line.sku;
                }

                // Check quantity
                let quantity: number | undefined = undefined;
                if (checkRequired(line.quantity, `${linePath}.quantity`, 'quantity') && checkNumber(line.quantity, `${linePath}.quantity`)) {
                    if (checkWholePositive(line.quantity, `${linePath}.quantity`)) {
                        quantity = line.quantity;
                    }
                }

                // Check unitPrice
                let unitPrice: number | undefined = undefined;
                if (checkRequired(line.unitPrice, `${linePath}.unitPrice`, 'unitPrice') && checkNumber(line.unitPrice, `${linePath}.unitPrice`)) {
                    if (checkNonNegative(line.unitPrice, `${linePath}.unitPrice`)) {
                        unitPrice = line.unitPrice;
                    }
                }

                // Create OrderLine if all required fields are valid
                if (sku !== undefined && quantity !== undefined && unitPrice !== undefined) {
                    lines.push(new OrderLine(sku, quantity, unitPrice));
                }

                // Check for unknown fields in line
                const knownFields = new Set(['sku', 'quantity', 'unitPrice']);
                for (const key in line) {
                    if (!knownFields.has(key)) {
                        errors.push({ path: `${linePath}.${key}`, message: 'unknown field' });
                    }
                }
            }
        }
    }

    // Check for unknown fields in order
    const knownFields = new Set(['id', 'status', 'lines']);
    for (const key in parsed) {
        if (!knownFields.has(key)) {
            errors.push({ path: key, message: 'unknown field' });
        }
    }

    // Return result
    if (errors.length > 0) {
        return {
            order: undefined,
            errors
        };
    } else {
        return {
            order: {
                id,
                status,
                lines
            },
            errors: []
        };
    }
}

