export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query === '') {
    return result;
  }

  // Split by '&' and process each part
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair === '') {
      continue;
    }

    let key: string;
    let value: string;

    // Find the first '=' to split key and value
    const equalsIndex = pair.indexOf('=');

    if (equalsIndex === -1) {
      // No '=' found, treat entire string as key with empty value
      key = pair;
      value = '';
    } else {
      // Split at first '='
      key = pair.substring(0, equalsIndex);
      value = pair.substring(equalsIndex + 1);
    }

    // Skip pairs with empty keys
    if (key === '') {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (keys maintain first appearance order)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeComponent(str: string): string {
  if (str === '') {
    return str;
  }

  // Replace '+' with space first
  str = str.replace(/\+/g, ' ');

  // Try to decode percent escapes
  try {
    // Use decodeURIComponent for valid percent escapes
    return decodeURIComponent(str);
  } catch (e) {
    // If decoding fails due to malformed escape, return original with only '+' replaced
    return str;
  }
}

interface User {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  try {
    const data = JSON.parse(json);

    if (!Array.isArray(data)) {
      return [];
    }

    const users: User[] = [];

    for (const item of data) {
      // Check if item is an object
      if (typeof item !== 'object' || item === null) {
        continue;
      }

      // Check if id is an integer number
      if (typeof item.id !== 'number' || !Number.isInteger(item.id)) {
        continue;
      }

      // Check if name is a non-empty string
      if (typeof item.name !== 'string' || item.name.length === 0) {
        continue;
      }

      // Check if email is a string containing '@'
      if (typeof item.email !== 'string' || !item.email.includes('@')) {
        continue;
      }

      // If all checks pass, add the user with only the required fields
      users.push({
        id: item.id,
        name: item.name,
        email: item.email
      });
    }

    return users;
  } catch (error) {
    // Return empty array if JSON parsing fails
    return [];
  }
}

type Listener<T> = (payload: T) => void;

class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }

    const eventListeners = this.listeners.get(event)!;
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }

    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    const eventListeners = this.listeners.get(event)!;
    // Create a copy to avoid issues if listeners modify the array during iteration
    const listenersCopy = [...eventListeners];

    for (const listener of listenersCopy) {
      listener(payload);
    }

    return listenersCopy.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    return this.listeners.get(event)!.length;
  }
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error | null = null;

  for (let i = 0; i < attempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error as Error;
    }
  }

  throw new RetryError(attempts, lastError!);
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return "0s";
  }

  const isNegative = totalSeconds < 0;
  if (isNegative) {
    totalSeconds = -totalSeconds;
  }

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  let result = "";

  if (hours > 0) {
    result += `${hours}h `;
  }

  if (minutes > 0 || hours > 0) {
    result += `${minutes.toString().padStart(2, '0')}m `;
  }

  result += `${seconds.toString().padStart(2, '0')}s`;

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  // Check for invalid spacing
  if (text.startsWith(' ') || text.endsWith(' ') || text.includes('  ')) {
    return NaN;
  }

  const parts = text.split(' ');
  let totalSeconds = 0;
  let isNegative = false;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Check if this is the first part and starts with minus
    if (i === 0 && part.startsWith('-')) {
      if (part.length === 1) {
        return NaN; // Just a minus sign
      }
      isNegative = true;
      const numPart = part.substring(1);
      if (!/^\d+[hms]$/.test(numPart)) {
        return NaN;
      }
      const match = numPart.match(/^(\d+)([hms])$/);
      if (!match) {
        return NaN;
      }
      const value = parseInt(match[1]);
      const unit = match[2];

      switch (unit) {
        case 'h':
          totalSeconds += value * 3600;
          break;
        case 'm':
          totalSeconds += value * 60;
          break;
        case 's':
          totalSeconds += value;
          break;
      }
    } else {
      // Regular part
      if (!/^\d+[hms]$/.test(part)) {
        return NaN;
      }
      const match = part.match(/^(\d+)([hms])$/);
      if (!match) {
        return NaN;
      }
      const value = parseInt(match[1]);
      const unit = match[2];

      switch (unit) {
        case 'h':
          totalSeconds += value * 3600;
          break;
        case 'm':
          totalSeconds += value * 60;
          break;
        case 's':
          totalSeconds += value;
          break;
      }
    }
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

/**
 * A generic type representing a pair of values.
 */
export type Pair<A, B> = {
  first: A;
  second: B;
};

/**
 * Splits an array into consecutive groups of a specified size.
 * @param items - The array to split.
 * @param size - The size of each group.
 * @returns An array of arrays, where each inner array contains up to `size` elements from the original array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Zips two arrays together into an array of pairs.
 * @param a - The first array.
 * @param b - The second array.
 * @returns An array of pairs where each pair contains elements from the corresponding indices of the input arrays.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    result.push({ first: a[i], second: b[i] });
  }

  return result;
}

export class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more");
    }
    this.capacity = capacity;
    this.cache = new Map();
    this.order = [];
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      // Key already exists, update its position
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else if (this.cache.size >= this.capacity) {
      // Cache is full, remove the least recently used key
      const oldestKey = this.order.shift();
      if (oldestKey !== undefined) {
        this.cache.delete(oldestKey);
      }
    }

    // Add/update the key-value pair
    this.cache.set(key, value);
    this.order.push(key);
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move the key to the end (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.cache.get(key);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (from least to most recent)
    return [...this.order];
  }

  get size(): number {
    return this.cache.size;
  }
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  const dayRules = rules.filter(rule => rule.day === day);

  for (const rule of dayRules) {
    if (hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }

  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Get all days that have at least one rule
  const daysWithRules = new Set<Weekday>();
  for (const rule of rules) {
    daysWithRules.add(rule.day);
  }

  // If no days have rules, return undefined
  if (daysWithRules.size === 0) {
    return undefined;
  }

  // Start checking from the day after the given day
  let currentDay = (day + 1) % 7;

  // Check each day in order until we find one with rules
  while (currentDay !== day) {
    if (daysWithRules.has(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  // If we get here, the original day was the only one with rules
  // Return the same day (one week later)
  return day;
}

// Define the Shape type as an interface to allow for extensibility
interface Shape {
  type: string;
  // Add common properties if needed, but keeping it flexible for future shapes
}

// Function to create a circle shape
function circle(radius: number): Shape {
  return {
    type: "circle",
    radius: radius
  };
}

// Function to create a rectangle shape
function rectangle(width: number, height: number): Shape {
  return {
    type: "rectangle",
    width: width,
    height: height
  };
}

// Function to create a triangle shape
function triangle(base: number, height: number): Shape {
  return {
    type: "triangle",
    base: base,
    height: height
  };
}

// Function to calculate the area of a shape
function area(shape: Shape): number {
  switch (shape.type) {
    case "circle":
      const circleShape = shape as { radius: number };
      return Math.PI * circleShape.radius * circleShape.radius;
    case "rectangle":
      const rectShape = shape as { width: number; height: number };
      return rectShape.width * rectShape.height;
    case "triangle":
      const triShape = shape as { base: number; height: number };
      return triShape.base * triShape.height / 2;
    default:
      return 0;
  }
}

// Function to calculate the total area of multiple shapes
function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (const shape of shapes) {
    total += area(shape);
  }
  return total;
}

