type Transform = (text: string) => string;

function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

class Pipeline {
  private steps: Array<{ name: string; func: Transform }> = [];

  add(name: string, step: Transform): this {
    this.steps.push({ name, func: step });
    return this;
  }

  run(text: string): string {
    return this.steps.reduce((result, { func }) => func(result), text);
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    const pipeline = this;
    return function(text: string): string {
      return pipeline.run(text);
    };
  }
}

function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }
  return (text: string) => steps.reduce((result, step) => step(result), text);
}

interface Item {
  id: string;
  name: string;
  quantity: number;
}

interface Change {
  id: string;
  quantity: number;
}

function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  let found = false;

  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        // Create a new item with updated quantity
        result.push({
          id: item.id,
          name: item.name,
          quantity: quantity
        });
      }
      found = true;
    } else {
      // Keep the original item
      result.push({
        id: item.id,
        name: item.name,
        quantity: item.quantity
      });
    }
  }

  // If no item with the given id was found, return the original array
  if (!found) {
    return items;
  }

  return result;
}

function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result: Item[] = [...items]; // Create a shallow copy of the original array

  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }

  return result;
}

import { http } from '@kit.NetworkKit';

interface Item {
  id: number;
  name: string;
}

@Component
struct MainEntry {
  @State items: Item[] = [];
  @State loading: boolean = true;
  @State error: boolean = false;

  aboutToAppear(): void {
    this.loadItems();
  }

  loadItems(): void {
    this.loading = true;
    this.error = false;

    const httpRequest = http.createHttp();

    httpRequest
      .request(
        'https://example.com/api/items',
        {
          method: http.RequestMethod.GET,
          header: {
            'Content-Type': 'application/json'
          }
        }
      )
      .then((response: http.HttpResponse) => {
        if (response.responseCode === http.ResponseCode.OK) {
          try {
            const data = JSON.parse(response.result as string) as Item[];
            if (Array.isArray(data)) {
              this.items = data;
              this.loading = false;
            } else {
              this.loading = false;
              this.error = true;
            }
          } catch (e) {
            this.loading = false;
            this.error = true;
          }
        } else {
          this.loading = false;
          this.error = true;
        }
      })
      .catch(() => {
        this.loading = false;
        this.error = true;
      })
      .finally(() => {
        try {
          httpRequest.destroy();
        } catch (e) {
          // Ignore errors during cleanup
        }
      });
  }

  build(): void {
    Column() {
      if (this.loading) {
        Text('Loading...')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
      } else if (this.error) {
        Text('Could not load the items')
          .fontSize(18)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 20 })
      } else {
        List() {
          ForEach(
            this.items,
            (item: Item) => {
              ListItem() {
                Text(item.name)
                  .fontSize(16)
                  .padding({ left: 16, right: 16, top: 12, bottom: 12 })
              }
            },
            (item: Item) => item.id.toString()
          )
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

