interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    if (/\d/.test(char)) {
      const start = i;
      while (i < source.length && /\d/.test(source[i])) {
        i++;
      }
      if (i < source.length && source[i] === '.') {
        i++;
        if (i >= source.length || !/\d/.test(source[i])) {
          throw new ExpressionError(`Unexpected character '${source[i - 1]}'`, i - 1);
        }
        while (i < source.length && /\d/.test(source[i])) {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (/[a-zA-Z_]/.test(char)) {
      const start = i;
      while (i < source.length && /[a-zA-Z0-9_]/.test(source[i])) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);

  if (tokens.length === 0) {
    throw new ExpressionError("Unexpected end of expression", source.length);
  }

  let pos = 0;
  const peek = () => tokens[pos];
  const consume = () => tokens[pos++];

  function parseExpression(): number {
    return parseAdditive();
  }

  function parseAdditive(): number {
    let result = parseMultiplicative();

    while (pos < tokens.length && 
           (peek().text === '+' || peek().text === '-')) {
      const op = peek().text;
      consume();
      const right = parseMultiplicative();

      if (op === '+') {
        result += right;
      } else {
        result -= right;
      }
    }

    return result;
  }

  function parseMultiplicative(): number {
    let result = parseUnary();

    while (pos < tokens.length && 
           (peek().text === '*' || peek().text === '/' || peek().text === '%')) {
      const op = peek().text;
      consume();
      const right = parseUnary();

      if (op === '*') {
        result *= right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError("Division by zero", peek().position);
        }
        result /= right;
      } else {
        if (right === 0) {
          throw new ExpressionError("Division by zero", peek().position);
        }
        result %= right;
      }
    }

    return result;
  }

  function parseUnary(): number {
    if (pos < tokens.length && peek().text === '-') {
      consume();
      return -parsePrimary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    if (pos >= tokens.length) {
      throw new ExpressionError("Unexpected end of expression", source.length);
    }

    const token = peek();

    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      consume();
      const value = variables[token.text];
      if (value === undefined) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return value;
    }

    if (token.text === '(') {
      consume();
      const result = parseExpression();
      if (pos >= tokens.length || peek().text !== ')') {
        throw new ExpressionError("Unexpected end of expression", source.length);
      }
      consume();
      return result;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpression();

  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: Array<{ job: () => Promise<any>; resolve: (value: any) => void; reject: (reason?: any) => void }> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error("Concurrency must be a whole number greater than or equal to 1");
    }
    this.concurrency = concurrency;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({ job, resolve, reject });
      if (!this.paused && this.runningJobs < this.concurrency) {
        this.startNextJob();
      }
    });
  }

  private startNextJob(): void {
    if (this.waitingJobs.length === 0 || this.runningJobs >= this.concurrency || this.paused) {
      return;
    }

    const { job, resolve, reject } = this.waitingJobs.shift()!;
    this.runningJobs++;

    job()
      .then(value => {
        this.completedCount++;
        this.runningJobs--;
        resolve(value);
        this.startNextJob();
      })
      .catch(error => {
        this.failedCount++;
        this.runningJobs--;
        reject(error);
        this.startNextJob();
      });
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    while (this.runningJobs < this.concurrency && this.waitingJobs.length > 0) {
      this.startNextJob();
    }
  }

  clear(): number {
    const count = this.waitingJobs.length;
    for (const { reject } of this.waitingJobs) {
      reject(new Error("Job was cancelled"));
    }
    this.waitingJobs = [];
    return count;
  }

  whenIdle(): Promise<void> {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    return new Promise<void>(resolve => {
      const checkIdle = () => {
        if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
          resolve();
        } else {
          // Schedule next check
          setTimeout(checkIdle, 0);
        }
      };
      checkIdle();
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const outcomes: JobOutcome<T>[] = new Array(jobs.length);
    const promises: Promise<void>[] = [];

    for (let i = 0; i < jobs.length; i++) {
      const jobIndex = i;
      const job = jobs[i];

      const promise = this.add(job)
        .then(value => {
          outcomes[jobIndex] = { ok: true, value, error: undefined };
        })
        .catch(error => {
          outcomes[jobIndex] = { ok: false, value: undefined, error };
        });

      promises.push(promise);
    }

    return Promise.all(promises).then(() => outcomes);
  }
}

