class Address {
  constructor(public id: string, public label: string, public street: string) {}
}

enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

class OrderLine {
  constructor(
    public sku: string,
    public quantity: number,
    public unitPrice: number
  ) {}

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

interface FieldError {
  path: string;
  message: string;
}

interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
  let parsed: any;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'invalid JSON' }]
    };
  }

  if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'expected an object' }]
    };
  }

  const errors: FieldError[] = [];

  // Helper function to add error
  const addError = (path: string, message: string) => {
    errors.push({ path, message });
  };

  // Helper function to check if value is null or undefined
  const isNullOrUndefined = (value: any) => value === null || value === undefined;

  // Helper function to check if value is a string
  const isString = (value: any): value is string => typeof value === 'string';

  // Helper function to check if value is a number
  const isNumber = (value: any): value is number => typeof value === 'number';

  // Helper function to check if value is an array
  const isArray = (value: any): value is any[] => Array.isArray(value);

  // Helper function to check if value is an object
  const isObject = (value: any): value is object => 
    value !== null && typeof value === 'object' && !Array.isArray(value);

  // Check id
  const idValue = parsed.id;
  if (isNullOrUndefined(idValue)) {
    addError('id', 'required');
  } else if (!isString(idValue)) {
    addError('id', 'expected a string');
  } else if (idValue === '') {
    addError('id', 'must not be empty');
  }

  // Check status
  const statusValue = parsed.status;
  let status: OrderStatus;
  if (isNullOrUndefined(statusValue)) {
    status = OrderStatus.Draft;
  } else if (!isString(statusValue)) {
    addError('status', 'expected one of draft, paid, shipped');
  } else {
    switch (statusValue) {
      case OrderStatus.Draft:
      case OrderStatus.Paid:
      case OrderStatus.Shipped:
        status = statusValue;
        break;
      default:
        addError('status', 'expected one of draft, paid, shipped');
        status = OrderStatus.Draft;
    }
  }

  // Check lines
  const linesValue = parsed.lines;
  let lines: OrderLine[] = [];
  if (isNullOrUndefined(linesValue)) {
    addError('lines', 'required');
  } else if (!isArray(linesValue)) {
    addError('lines', 'expected an array');
  } else if (linesValue.length === 0) {
    addError('lines', 'must not be empty');
  } else {
    lines = [];
    for (let i = 0; i < linesValue.length; i++) {
      const lineValue = linesValue[i];
      const linePath = `lines[${i}]`;

      if (!isObject(lineValue)) {
        addError(linePath, 'expected an object');
        continue;
      }

      // Check sku
      const skuValue = lineValue.sku;
      if (isNullOrUndefined(skuValue)) {
        addError(`${linePath}.sku`, 'required');
      } else if (!isString(skuValue)) {
        addError(`${linePath}.sku`, 'expected a string');
      } else if (skuValue === '') {
        addError(`${linePath}.sku`, 'must not be empty');
      }

      // Check quantity
      const quantityValue = lineValue.quantity;
      if (isNullOrUndefined(quantityValue)) {
        addError(`${linePath}.quantity`, 'required');
      } else if (!isNumber(quantityValue)) {
        addError(`${linePath}.quantity`, 'expected a number');
      } else if (quantityValue < 1 || !Number.isInteger(quantityValue)) {
        addError(`${linePath}.quantity`, 'must be a whole number of 1 or more');
      }

      // Check unitPrice
      const unitPriceValue = lineValue.unitPrice;
      if (isNullOrUndefined(unitPriceValue)) {
        addError(`${linePath}.unitPrice`, 'required');
      } else if (!isNumber(unitPriceValue)) {
        addError(`${linePath}.unitPrice`, 'expected a number');
      } else if (unitPriceValue < 0) {
        addError(`${linePath}.unitPrice`, 'must be 0 or more');
      }

      // Create OrderLine if all validations pass
      if (
        !isNullOrUndefined(skuValue) &&
        isString(skuValue) &&
        skuValue !== '' &&
        !isNullOrUndefined(quantityValue) &&
        isNumber(quantityValue) &&
        quantityValue >= 1 &&
        Number.isInteger(quantityValue) &&
        !isNullOrUndefined(unitPriceValue) &&
        isNumber(unitPriceValue) &&
        unitPriceValue >= 0
      ) {
        lines.push(new OrderLine(skuValue, quantityValue, unitPriceValue));
      }

      // Check for unknown fields in line
      const knownLineFields = ['sku', 'quantity', 'unitPrice'];
      for (const key in lineValue) {
        if (!knownLineFields.includes(key)) {
          addError(`${linePath}.${key}`, 'unknown field');
        }
      }
    }
  }

  // Check for unknown fields in order
  const knownOrderFields = ['id', 'status', 'lines'];
  for (const key in parsed) {
    if (!knownOrderFields.includes(key)) {
      addError(key, 'unknown field');
    }
  }

  // Return result
  if (errors.length > 0) {
    return {
      order: undefined,
      errors
    };
  } else {
    return {
      order: {
        id: isString(idValue) ? idValue : '',
        status,
        lines
      },
      errors: []
    };
  }
}

/**
 * Interface representing an expense with category and amount
 */
export interface Expense {
  category: string;
  amount: number;
}

/**
 * Calculates the total amount for each expense category
 * @param expenses - Array of expense objects
 * @returns Map with category as key and total amount as value
 */
export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const category = expense.category;
    const amount = expense.amount;

    if (result.has(category)) {
      const currentTotal = result.get(category)!;
      result.set(category, currentTotal + amount);
    } else {
      result.set(category, amount);
    }
  }

  return result;
}

