interface Point {
  x: number;
  y: number;
}

interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) minX = point.x;
    if (point.y < minY) minY = point.y;
    if (point.x > maxX) maxX = point.x;
    if (point.y > maxY) maxY = point.y;
  }

  const width = maxX - minX;
  const height = maxY - minY;

  // Return new objects to avoid modifying input
  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width,
    height
  };
}

interface User {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  try {
    const data = JSON.parse(json);
    if (!Array.isArray(data)) {
      return [];
    }

    const result: User[] = [];

    for (const item of data) {
      if (item === null || typeof item !== 'object') {
        continue;
      }

      if (typeof item.id !== 'number' || !Number.isInteger(item.id)) {
        continue;
      }

      if (typeof item.name !== 'string' || item.name.length === 0) {
        continue;
      }

      if (typeof item.email !== 'string' || !item.email.includes('@')) {
        continue;
      }

      result.push({
        id: item.id,
        name: item.name,
        email: item.email
      });
    }

    return result;
  } catch {
    return [];
  }
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

type Listener<T> = (payload: T) => void;

class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const eventListeners = this.listeners.get(event)!;
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }
    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    const eventListeners = this.listeners.get(event)!;
    for (const listener of eventListeners) {
      listener(payload);
    }
    return eventListeners.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    return this.listeners.get(event)!.length;
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error | null = null;

  for (let i = 0; i < attempts; i++) {
    try {
      return await action();
    } catch (error) {
      if (error instanceof Error) {
        lastError = error;
      } else {
        lastError = new Error(String(error));
      }
    }
  }

  if (lastError) {
    throw new RetryError(attempts, lastError);
  } else {
    throw new RetryError(attempts, new Error("Unknown error"));
  }
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds < 0) {
    return '-' + formatDuration(-totalSeconds);
  }

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    return `${seconds}s`;
  }
}

export function parseDuration(text: string): number {
  if (!text) {
    return NaN;
  }

  let result = 0;
  let isNegative = false;
  let startIndex = 0;

  if (text[0] === '-') {
    isNegative = true;
    startIndex = 1;
  }

  let i = startIndex;
  while (i <= text.length) {
    if (i === text.length || text[i] === ' ') {
      if (i > startIndex) {
        const part = text.substring(startIndex, i);
        const match = part.match(/^(\d+)([hms])$/);
        if (!match) {
          return NaN;
        }
        const value = parseInt(match[1]);
        const unit = match[2];
        if (isNaN(value)) {
          return NaN;
        }
        switch (unit) {
          case 'h':
            result += value * 3600;
            break;
          case 'm':
            result += value * 60;
            break;
          case 's':
            result += value;
            break;
        }
      }
      startIndex = i + 1;
    }
    i++;
  }

  if (startIndex < text.length) {
    return NaN;
  }

  return isNegative ? -result : result;
}

interface Item {
  id: string;
  name: string;
  quantity: number;
}

interface Change {
  id: string;
  quantity: number;
}

function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  let found = false;

  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        result.push({ ...item, quantity });
      }
      found = true;
    } else {
      result.push(item);
    }
  }

  if (!found) {
    return items;
  }

  return result;
}

function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result: Item[] = [...items];

  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }

  return result;
}

