/**
 * Represents a shape with an area calculation method
 */
interface Shape {
  area(): number;
}

/**
 * Creates a circle shape
 * @param radius - The radius of the circle
 * @returns A circle shape
 */
function circle(radius: number): Shape {
  return {
    area(): number {
      return Math.PI * radius * radius;
    }
  };
}

/**
 * Creates a rectangle shape
 * @param width - The width of the rectangle
 * @param height - The height of the rectangle
 * @returns A rectangle shape
 */
function rectangle(width: number, height: number): Shape {
  return {
    area(): number {
      return width * height;
    }
  };
}

/**
 * Creates a triangle shape
 * @param base - The base of the triangle
 * @param height - The height of the triangle
 * @returns A triangle shape
 */
function triangle(base: number, height: number): Shape {
  return {
    area(): number {
      return (base * height) / 2;
    }
  };
}

/**
 * Calculates the total area of multiple shapes
 * @param shapes - An array of shapes
 * @returns The sum of all shape areas
 */
function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += shapes[i].area();
  }
  return total;
}

/**
 * A generic type representing a pair of values.
 */
export type Pair<A, B> = {
  first: A;
  second: B;
};

/**
 * Splits an array into consecutive groups of a specified size.
 * @param items - The array to split.
 * @param size - The size of each group.
 * @returns An array of arrays, where each inner array contains up to `size` elements from the input array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }

  return result;
}

/**
 * Zips two arrays together into an array of pairs.
 * @param a - The first array.
 * @param b - The second array.
 * @returns An array of pairs, where each pair contains elements from the corresponding indices of the input arrays.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    result.push({ first: a[i], second: b[i] });
  }

  return result;
}

class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more");
    }
    this.capacity = capacity;
    this.cache = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      // Key already exists, update its position
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else if (this.cache.size >= this.capacity) {
      // Cache is full, remove the least recently used key
      const oldestKey = this.order.shift();
      if (oldestKey !== undefined) {
        this.cache.delete(oldestKey);
      }
    }

    // Add/update the key-value pair
    this.cache.set(key, value);
    this.order.push(key);
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move the key to the end (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.cache.get(key);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (from least to most recent)
    return [...this.order];
  }

  get size(): number {
    return this.cache.size;
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query.length === 0) {
    return result;
  }

  // Split by '&' and process each part
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair.length === 0) {
      continue;
    }

    let key: string;
    let value: string;

    // Find the first '=' to split key and value
    const equalsIndex = pair.indexOf('=');

    if (equalsIndex === -1) {
      // No '=' found, treat entire string as key with empty value
      key = pair;
      value = '';
    } else {
      // Split at first '='
      key = pair.substring(0, equalsIndex);
      value = pair.substring(equalsIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (last value wins, but keep first position)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeComponent(str: string): string {
  if (str.length === 0) {
    return str;
  }

  // Replace '+' with space first
  str = str.replace(/\+/g, ' ');

  // Try to decode percent escapes
  try {
    // Use URLSearchParams to handle decoding properly
    // We need to handle malformed sequences carefully
    const decoded = decodeURIComponent(str);
    return decoded;
  } catch (e) {
    // If decodeURIComponent fails due to malformed sequence,
    // return the string as-is (but with + replaced by space)
    return str;
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.tasks) {
      const dependencies = spec[task];
      for (const dependency of dependencies) {
        if (!(dependency in spec)) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    // Check for cycles
    const visited = new Set<string>();
    const visiting = new Set<string>();
    const path: string[] = [];

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        this.visit(task, visited, visiting, path);
      }
    }
  }

  private visit(task: string, visited: Set<string>, visiting: Set<string>, path: string[]): void {
    if (visiting.has(task)) {
      // Found a cycle
      const cycleStartIndex = path.indexOf(task);
      const cyclePath = path.slice(cycleStartIndex).concat(task);
      throw new CycleError(cyclePath);
    }

    if (visited.has(task)) {
      return;
    }

    visiting.add(task);
    path.push(task);

    const dependencies = this.spec[task];
    for (const dependency of dependencies) {
      this.visit(dependency, visited, visiting, path);
    }

    visiting.delete(task);
    path.pop();
    visited.add(task);
  }

  order(): string[] {
    const result: string[] = [];
    const placed = new Set<string>();

    const placeTask = (task: string) => {
      if (placed.has(task)) {
        return;
      }

      const dependencies = this.spec[task];
      for (const dependency of dependencies) {
        placeTask(dependency);
      }

      result.push(task);
      placed.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task);
    }

    return result;
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    const result: string[][] = [];
    const placed = new Set<string>();
    const layerMap = new Map<string, number>();

    const placeTask = (task: string, layer: number) => {
      if (placed.has(task)) {
        return;
      }

      const dependencies = this.spec[task];
      let maxLayer = layer;

      for (const dependency of dependencies) {
        const depLayer = layerMap.get(dependency) ?? -1;
        if (depLayer > maxLayer) {
          maxLayer = depLayer;
        }
      }

      const newLayer = maxLayer + 1;
      layerMap.set(task, newLayer);

      for (const dependency of dependencies) {
        placeTask(dependency, newLayer);
      }

      result[newLayer] = result[newLayer] || [];
      result[newLayer].push(task);
      placed.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task, -1);
    }

    // Remove empty layers and sort within layers
    return result.filter(layer => layer !== undefined).map(layer => {
      return [...layer].sort((a, b) => {
        const indexA = this.tasks.indexOf(a);
        const indexB = this.tasks.indexOf(b);
        return indexA - indexB;
      });
    });
  }

  dependentsOf(name: string): string[] {
    if (!(name in this.spec)) {
      return [];
    }

    const order = this.order();
    const result: string[] = [];
    const seen = new Set<string>();

    for (const task of order) {
      if (task === name) {
        continue;
      }

      const dependencies = this.spec[task];
      if (dependencies.includes(name)) {
        result.push(task);
        seen.add(task);
      }
    }

    return result;
  }
}

/**
 * Enumeration of the seven days of the week, starting with Monday.
 */
export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

/**
 * Interface representing an opening rule for a specific day.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Determines if a place is open at a given day and hour based on the provided rules.
 * 
 * @param rules - Array of opening rules
 * @param day - The day to check
 * @param hour - The hour to check
 * @returns true if the place is open, false otherwise
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  const dayRules = rules.filter(rule => rule.day === day);

  for (const rule of dayRules) {
    if (hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }

  return false;
}

/**
 * Finds the next day that has at least one opening rule after the given day.
 * 
 * @param rules - Array of opening rules
 * @param day - The current day
 * @returns The next day with rules, or undefined if no day has rules
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Create a set of days that have rules for quick lookup
  const daysWithRules = new Set<Weekday>();
  for (const rule of rules) {
    daysWithRules.add(rule.day);
  }

  // If no days have rules, return undefined
  if (daysWithRules.size === 0) {
    return undefined;
  }

  // Start checking from the day after the given day
  let currentDay = (day + 1) % 7;

  // Check each subsequent day until we find one with rules or we've checked all days
  for (let i = 0; i < 7; i++) {
    if (daysWithRules.has(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  // If we get here, the only day with rules is the input day itself
  // Return the day one week later (which is the same day)
  return day;
}

/**
 * Type definition for a transform function
 */
type Transform = (text: string) => string;

/**
 * Trim whitespace from both ends of a string
 */
export function trim(text: string): string {
  return text.trim();
}

/**
 * Convert text to lowercase
 */
export function lowerCase(text: string): string {
  return text.toLowerCase();
}

/**
 * Replace runs of whitespace with single spaces
 */
export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

/**
 * Pipeline class for chaining transforms
 */
export class Pipeline {
  private steps: Array<{ name: string; func: Transform }> = [];

  /**
   * Add a step to the pipeline
   */
  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, func: step });
    return this;
  }

  /**
   * Run the pipeline on text
   */
  run(text: string): string {
    return this.steps.reduce((result, step) => step.func(result), text);
  }

  /**
   * Get the names of all steps
   */
  names(): string[] {
    return this.steps.map(step => step.name);
  }

  /**
   * Convert pipeline to a transform function
   */
  toFunction(): Transform {
    return (text: string) => this.run(text);
  }
}

/**
 * Compose multiple transforms into one
 */
export function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }

  return (text: string) => {
    return steps.reduce((result, step) => step(result), text);
  };
}

