interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private currentState: EditorState;
  private history: EditorState[] = [];
  private historyLimit: number;
  private listeners: Map<string, Array<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();

  constructor(initial: EditorState, historyLimit: number) {
    if (historyLimit < 1) {
      throw new Error("historyLimit must be 1 or more");
    }
    this.currentState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    return {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };
  }

  private notifyListeners(field: string, newValue: string | number | boolean, oldValue: string | number | boolean): void {
    const fieldListeners = this.listeners.get(field);
    if (fieldListeners) {
      for (const listener of fieldListeners) {
        listener(newValue, oldValue);
      }
    }
  }

  private addToHistory(state: EditorState): void {
    this.history.push({
      text: state.text,
      cursor: state.cursor,
      bold: state.bold
    });
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }
  }

  private applyPatch(patch: Partial<EditorState>): boolean {
    let changed = false;
    const oldState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    if (patch.text !== undefined && patch.text !== this.currentState.text) {
      this.currentState.text = patch.text;
      changed = true;
      this.notifyListeners('text', this.currentState.text, oldState.text);
    }

    if (patch.cursor !== undefined && patch.cursor !== this.currentState.cursor) {
      this.currentState.cursor = patch.cursor;
      changed = true;
      this.notifyListeners('cursor', this.currentState.cursor, oldState.cursor);
    }

    if (patch.bold !== undefined && patch.bold !== this.currentState.bold) {
      this.currentState.bold = patch.bold;
      changed = true;
      this.notifyListeners('bold', this.currentState.bold, oldState.bold);
    }

    return changed;
  }

  apply(patch: Partial<EditorState>): boolean {
    const hasChanges = this.applyPatch(patch);
    if (hasChanges) {
      this.addToHistory(this.currentState);
    }
    return hasChanges;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    try {
      run(draft);
    } catch (error) {
      throw error;
    }

    const oldState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    const patch: Partial<EditorState> = {};
    if (draft.text !== oldState.text) {
      patch.text = draft.text;
    }
    if (draft.cursor !== oldState.cursor) {
      patch.cursor = draft.cursor;
    }
    if (draft.bold !== oldState.bold) {
      patch.bold = draft.bold;
    }

    if (Object.keys(patch).length === 0) {
      return false;
    }

    const hasChanges = this.applyPatch(patch);
    if (hasChanges) {
      this.addToHistory(this.currentState);
    }
    return hasChanges;
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const prevState = this.history.pop()!;
    const oldState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    this.currentState = prevState;

    // Notify listeners about the changes
    if (prevState.text !== oldState.text) {
      this.notifyListeners('text', prevState.text, oldState.text);
    }
    if (prevState.cursor !== oldState.cursor) {
      this.notifyListeners('cursor', prevState.cursor, oldState.cursor);
    }
    if (prevState.bold !== oldState.bold) {
      this.notifyListeners('bold', prevState.bold, oldState.bold);
    }

    return true;
  }

  redo(): boolean {
    // This implementation assumes we don't maintain a separate redo stack
    // In a real implementation, we'd need to track redoable actions
    // For now, we'll just return false since we don't support redo
    return false;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    // We don't maintain a redo stack in this simplified version
    return false;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    const fieldListeners = this.listeners.get(field)!;
    fieldListeners.push(listener);

    return () => {
      const index = fieldListeners.indexOf(listener);
      if (index !== -1) {
        fieldListeners.splice(index, 1);
      }
    };
  }
}

