export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

export class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: Array<{ job: () => Promise<any>; resolve: (value: any) => void; reject: (reason?: any) => void }> = [];
  private completedJobs: number = 0;
  private failedJobs: number = 0;
  private paused: boolean = false;
  private idlePromise: Promise<void> | null = null;
  private idleResolve: (() => void) | null = null;

  constructor(concurrency: number) {
    if (concurrency < 1) {
      throw new Error("Concurrency must be at least 1");
    }
    this.concurrency = concurrency;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      this.waitingJobs.push({ job, resolve, reject });
      this.checkAndStartJobs();
    });
  }

  private checkAndStartJobs(): void {
    while (!this.paused && this.runningJobs < this.concurrency && this.waitingJobs.length > 0) {
      const { job, resolve, reject } = this.waitingJobs.shift()!;
      this.runningJobs++;

      job()
        .then(value => {
          this.completedJobs++;
          resolve(value);
          this.runningJobs--;
          this.checkAndStartJobs();
          this.updateIdlePromise();
        })
        .catch(error => {
          this.failedJobs++;
          reject(error);
          this.runningJobs--;
          this.checkAndStartJobs();
          this.updateIdlePromise();
        });
    }

    this.updateIdlePromise();
  }

  private updateIdlePromise(): void {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0 && this.idleResolve) {
      this.idleResolve();
      this.idlePromise = null;
      this.idleResolve = null;
    }
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedJobs;
  }

  get failed(): number {
    return this.failedJobs;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.checkAndStartJobs();
  }

  clear(): number {
    const count = this.waitingJobs.length;
    for (const { reject } of this.waitingJobs) {
      reject(new Error("Job was cancelled"));
    }
    this.waitingJobs = [];
    this.updateIdlePromise();
    return count;
  }

  whenIdle(): Promise<void> {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    if (!this.idlePromise) {
      this.idlePromise = new Promise(resolve => {
        this.idleResolve = resolve;
      });
    }

    return this.idlePromise;
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const outcomes: JobOutcome<T>[] = [];
    const promises: Promise<void>[] = [];

    for (const job of jobs) {
      const promise = this.add(job)
        .then(value => {
          outcomes.push({ ok: true, value, error: undefined });
        })
        .catch(error => {
          outcomes.push({ ok: false, value: undefined, error });
        });

      promises.push(promise);
    }

    return Promise.all(promises).then(() => outcomes);
  }
}

