export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.tasks) {
      const dependencies = spec[task];
      for (const dependency of dependencies) {
        if (!(dependency in spec)) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    // Check for cycles during ordering
    const visited = new Set<string>();
    const visiting = new Set<string>();
    const order: string[] = [];

    const visit = (task: string) => {
      if (visiting.has(task)) {
        // Found a cycle
        const path = [...visiting, task];
        throw new CycleError(path);
      }
      if (visited.has(task)) {
        return;
      }

      visiting.add(task);
      const dependencies = spec[task] || [];
      for (const dep of dependencies) {
        visit(dep);
      }
      visiting.delete(task);
      visited.add(task);
      order.push(task);
    };

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        visit(task);
      }
    }
  }

  order(): string[] {
    const visited = new Set<string>();
    const result: string[] = [];

    const visit = (task: string) => {
      if (visited.has(task)) {
        return;
      }

      const dependencies = this.spec[task] || [];
      for (const dep of dependencies) {
        visit(dep);
      }
      visited.add(task);
      result.push(task);
    };

    for (const task of this.tasks) {
      visit(task);
    }

    return [...result];
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    const inDegree: Record<string, number> = {};
    const adjacency: Record<string, string[]> = {};

    // Initialize in-degree and adjacency list
    for (const task of this.tasks) {
      inDegree[task] = 0;
      adjacency[task] = [];
    }

    // Calculate in-degrees and build adjacency list
    for (const task of this.tasks) {
      const dependencies = this.spec[task] || [];
      for (const dep of dependencies) {
        inDegree[task]++;
        adjacency[dep].push(task);
      }
    }

    // Find all nodes with in-degree 0
    const queue: string[] = [];
    for (const task of this.tasks) {
      if (inDegree[task] === 0) {
        queue.push(task);
      }
    }

    const layers: string[][] = [];
    let layerIndex = 0;

    while (queue.length > 0) {
      const currentLayer: string[] = [];
      const size = queue.length;

      for (let i = 0; i < size; i++) {
        const task = queue.shift()!;
        currentLayer.push(task);

        // Reduce in-degree of neighbors
        for (const neighbor of adjacency[task]) {
          inDegree[neighbor]--;
          if (inDegree[neighbor] === 0) {
            queue.push(neighbor);
          }
        }
      }

      // Sort current layer by key order
      currentLayer.sort((a, b) => {
        const indexA = this.tasks.indexOf(a);
        const indexB = this.tasks.indexOf(b);
        return indexA - indexB;
      });

      layers.push(currentLayer);
      layerIndex++;
    }

    return layers;
  }

  dependentsOf(name: string): string[] {
    const result: string[] = [];
    const visited = new Set<string>();

    const findDependents = (task: string) => {
      if (visited.has(task)) {
        return;
      }

      visited.add(task);
      const dependencies = this.spec[task] || [];

      if (dependencies.includes(name)) {
        result.push(task);
      }

      // Recursively check dependents of this task
      for (const dep of this.tasks) {
        if (this.spec[dep]?.includes(task)) {
          findDependents(dep);
        }
      }
    };

    // Find direct dependents
    for (const task of this.tasks) {
      if (this.spec[task]?.includes(name)) {
        findDependents(task);
      }
    }

    // Get the full order to maintain correct sequence
    const fullOrder = this.order();
    return result.filter(task => fullOrder.includes(task)).sort((a, b) => {
      return fullOrder.indexOf(a) - fullOrder.indexOf(b);
    });
  }
}

