    .width('100%')
    .height('100%')
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  constructor(
    public sku: string,
    public quantity: number,
    public unitPrice: number
  ) {}

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

interface FieldError {
  path: string;
  message: string;
}

interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
  let jsonObject: any;
  try {
    jsonObject = JSON.parse(text);
  } catch (e) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'invalid JSON' }]
    };
  }

  if (typeof jsonObject !== 'object' || jsonObject === null) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'expected an object' }]
    };
  }

  const errors: FieldError[] = [];
  const order: Partial<Order> = {};

  // Check id
  if (jsonObject.id === undefined || jsonObject.id === null) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof jsonObject.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (jsonObject.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  } else {
    order.id = jsonObject.id;
  }

  // Check status
  if (jsonObject.status === undefined || jsonObject.status === null) {
    order.status = OrderStatus.Draft;
  } else if (typeof jsonObject.status !== 'string') {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else if (!Object.values(OrderStatus).includes(jsonObject.status as OrderStatus)) {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else {
    order.status = jsonObject.status as OrderStatus;
  }

  // Check lines
  if (jsonObject.lines === undefined || jsonObject.lines === null) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(jsonObject.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if (jsonObject.lines.length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    const lines: OrderLine[] = [];
    for (let i = 0; i < jsonObject.lines.length; i++) {
      const line = jsonObject.lines[i];
      const linePath = `lines[${i}]`;

      if (typeof line !== 'object' || line === null) {
        errors.push({ path: linePath, message: 'expected an object' });
        continue;
      }

      // Check sku
      let sku: string | undefined;
      if (line.sku === undefined || line.sku === null) {
        errors.push({ path: `${linePath}.sku`, message: 'required' });
      } else if (typeof line.sku !== 'string') {
        errors.push({ path: `${linePath}.sku`, message: 'expected a string' });
      } else if (line.sku === '') {
        errors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
      } else {
        sku = line.sku;
      }

      // Check quantity
      let quantity: number | undefined;
      if (line.quantity === undefined || line.quantity === null) {
        errors.push({ path: `${linePath}.quantity`, message: 'required' });
      } else if (typeof line.quantity !== 'number') {
        errors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
      } else if (line.quantity < 1 || !Number.isInteger(line.quantity)) {
        errors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
      } else {
        quantity = line.quantity;
      }

      // Check unitPrice
      let unitPrice: number | undefined;
      if (line.unitPrice === undefined || line.unitPrice === null) {
        errors.push({ path: `${linePath}.unitPrice`, message: 'required' });
      } else if (typeof line.unitPrice !== 'number') {
        errors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
      } else if (line.unitPrice < 0) {
        errors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
      } else {
        unitPrice = line.unitPrice;
      }

      // Add to lines if all fields are valid
      if (sku !== undefined && quantity !== undefined && unitPrice !== undefined) {
        lines.push(new OrderLine(sku, quantity, unitPrice));
      }

      // Check unknown fields in line
      const knownFields = ['sku', 'quantity', 'unitPrice'];
      for (const key in line) {
        if (!knownFields.includes(key) && !/^\d+$/.test(key)) {
          errors.push({ path: `${linePath}.${key}`, message: 'unknown field' });
        }
      }
    }
    order.lines = lines;
  }

  // Check unknown fields in order
  const knownFields = ['id', 'status', 'lines'];
  for (const key in jsonObject) {
    if (!knownFields.includes(key) && !/^\d+$/.test(key)) {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    return {
      order: undefined,
      errors
    };
  }

  return {
    order: order as Order,
    errors: []
  };
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    if (!result.has(expense.category)) {
      result.set(expense.category, 0);
    }
    const currentAmount = result.get(expense.category) || 0;
    result.set(expense.category, currentAmount + expense.amount);
  }

  return result;
}

