@Component
struct GroceryItemRow {
  @Prop item: GroceryItem;
  @Prop onDelete: () => void;

  build() {
    let isSwiped = false;
    let swipeOffset = 0;

    Row() {
      // Main content
      Text(this.item.name)
        .fontSize(16)
        .textDecoration(this.item.bought ? TextDecoration.LineThrough : TextDecoration.None)
        .fontColor(this.item.bought ? '#9E9E9E' : '#000000')
        .padding({ left: 10, right: 10, top: 10, bottom: 10 })
        .flexGrow(1)
        .onTouch((event) => {
          if (event.type === TouchEventType.Down) {
            isSwiped = false;
            swipeOffset = 0;
          }
        })

      // Delete button (hidden by default)
      Button('Delete')
        .backgroundColor('#D32F2F')
        .width(80)
        .height(60)
        .visibility(isSwiped ? Visibility.Visible : Visibility.Hidden)
        .onClick(() => {
          this.onDelete();
        })
        .margin({ right: 10 })
    }
    .width('100%')
    .height(60)
    .gesture(
      LongPressGesture()
        .onAction(() => {
          this.item.bought = !this.item.bought;
        })
    )
    .gesture(
      SwipeGesture()
        .onUpdate((event) => {
          swipeOffset = event.offsetX;
          if (swipeOffset < -50) {
            isSwiped = true;
          } else if (swipeOffset > 0) {
            isSwiped = false;
          }
        })
        .onEnd(() => {
          if (swipeOffset < -50) {
            isSwiped = true;
          } else {
            isSwiped = false;
          }
        })
    )
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private currentState: EditorState;
  private history: EditorState[] = [];
  private historyLimit: number;
  private listeners: Map<string, Array<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();

  constructor(initial: EditorState, historyLimit: number) {
    this.currentState = { ...initial };
    this.historyLimit = Math.max(1, historyLimit);
  }

  get state(): EditorState {
    return { ...this.currentState };
  }

  apply(patch: Partial<EditorState>): boolean {
    const oldState = { ...this.currentState };
    let changed = false;

    if (patch.text !== undefined && patch.text !== this.currentState.text) {
      this.currentState.text = patch.text;
      changed = true;
    }

    if (patch.cursor !== undefined && patch.cursor !== this.currentState.cursor) {
      this.currentState.cursor = patch.cursor;
      changed = true;
    }

    if (patch.bold !== undefined && patch.bold !== this.currentState.bold) {
      this.currentState.bold = patch.bold;
      changed = true;
    }

    if (!changed) {
      return false;
    }

    // Add to history
    this.history.push(oldState);
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Notify listeners
    this.notifyListeners(oldState);

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const oldState = { ...this.currentState };
    try {
      run(this.currentState);
    } catch (error) {
      this.currentState = oldState;
      throw error;
    }

    // Check if anything changed
    if (this.currentState.text === oldState.text && 
        this.currentState.cursor === oldState.cursor && 
        this.currentState.bold === oldState.bold) {
      return false;
    }

    // Add to history
    this.history.push(oldState);
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }

    // Notify listeners
    this.notifyListeners(oldState);

    return true;
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const prevState = this.history.pop()!;
    const oldState = { ...this.currentState };

    this.currentState = prevState;

    // Notify listeners
    this.notifyListeners(oldState);

    return true;
  }

  redo(): boolean {
    // This is a simplified implementation - in a real scenario we'd need to track redo history
    // For now, we'll just return false since we don't maintain redo history
    return false;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    // Simplified - in a real implementation we'd track redo history
    return false;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    const fieldListeners = this.listeners.get(field)!;
    fieldListeners.push(listener);

    return () => {
      const index = fieldListeners.indexOf(listener);
      if (index !== -1) {
        fieldListeners.splice(index, 1);
      }
    };
  }

  private notifyListeners(oldState: EditorState): void {
    const fields: (keyof EditorState)[] = ['text', 'cursor', 'bold'];

    for (const field of fields) {
      if (this.listeners.has(field)) {
        const listeners = this.listeners.get(field)!;
        const value = this.currentState[field];
        const previous = oldState[field];

        for (const listener of listeners) {
          listener(value, previous);
        }
      }
    }
  }
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export type Shape = 
  | { type: 'circle', radius: number }
  | { type: 'rectangle', width: number, height: number }
  | { type: 'triangle', base: number, height: number };

export function circle(radius: number): Shape {
  return { type: 'circle', radius };
}

export function rectangle(width: number, height: number): Shape {
  return { type: 'rectangle', width, height };
}

export function triangle(base: number, height: number): Shape {
  return { type: 'triangle', base, height };
}

export function area(shape: Shape): number {
  switch (shape.type) {
    case 'circle':
      return Math.PI * shape.radius * shape.radius;
    case 'rectangle':
      return shape.width * shape.height;
    case 'triangle':
      return shape.base * shape.height / 2;
  }
}

export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + area(shape), 0);
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  let parsed: any;
  try {
    parsed = JSON.parse(json);
  } catch {
    return [];
  }

  if (!Array.isArray(parsed)) {
    return [];
  }

  const result: User[] = [];

  for (const item of parsed) {
    if (
      item !== null &&
      typeof item === 'object' &&
      typeof item.id === 'number' &&
      Number.isInteger(item.id) &&
      typeof item.name === 'string' &&
      item.name.length > 0 &&
      typeof item.email === 'string' &&
      item.email.includes('@')
    ) {
      result.push({
        id: item.id,
        name: item.name,
        email: item.email
      });
    }
  }

  return result;
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    const position = i;

    if (/[0-9]/.test(char)) {
      let numStr = '';
      while (i < source.length && /[0-9.]/.test(source[i])) {
        numStr += source[i];
        i++;
      }

      // Validate number format
      if (numStr.includes('.')) {
        const parts = numStr.split('.');
        if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
          throw new ExpressionError(`Unexpected character '${numStr}'`, position);
        }
      }

      tokens.push({
        kind: 'number',
        text: numStr,
        position
      });
    } else if (/[a-zA-Z_]/.test(char)) {
      let nameStr = '';
      while (i < source.length && /[a-zA-Z0-9_]/.test(source[i])) {
        nameStr += source[i];
        i++;
      }
      tokens.push({
        kind: 'name',
        text: nameStr,
        position
      });
    } else if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({
        kind: 'operator',
        text: char,
        position
      });
      i++;
    } else {
      throw new ExpressionError(`Unexpected character '${char}'`, position);
    }
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);

  let pos = 0;

  function peek(): Token | null {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function consume(kind: string): Token {
    const token = peek();
    if (!token || token.kind !== kind) {
      throw new ExpressionError(`Unexpected token '${token?.text || ''}'`, token?.position || source.length);
    }
    pos++;
    return token;
  }

  function parseExpression(): number {
    return parseAdditive();
  }

  function parseAdditive(): number {
    let left = parseMultiplicative();

    while (true) {
      const op = peek();
      if (op && (op.text === '+' || op.text === '-')) {
        pos++;
        const right = parseMultiplicative();
        if (op.text === '+') {
          left += right;
        } else {
          left -= right;
        }
      } else {
        break;
      }
    }

    return left;
  }

  function parseMultiplicative(): number {
    let left = parseUnary();

    while (true) {
      const op = peek();
      if (op && (op.text === '*' || op.text === '/' || op.text === '%')) {
        pos++;
        const right = parseUnary();

        if (right === 0) {
          throw new ExpressionError('Division by zero', op.position);
        }

        if (op.text === '*') {
          left *= right;
        } else if (op.text === '/') {
          left /= right;
        } else {
          left %= right;
        }
      } else {
        break;
      }
    }

    return left;
  }

  function parseUnary(): number {
    const token = peek();
    if (token && token.text === '-') {
      pos++;
      return -parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = peek();

    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      pos++;
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      pos++;
      const value = variables[token.text];
      if (value === undefined) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return value;
    }

    if (token.text === '(') {
      pos++;
      const expr = parseExpression();
      consume(')');
      return expr;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpression();

  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query === '') {
    return result;
  }

  // Split by '&' and process each part
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair === '') {
      continue;
    }

    let key: string;
    let value: string;

    // Find the first '=' to split key and value
    const equalsIndex = pair.indexOf('=');

    if (equalsIndex === -1) {
      // No '=' found, treat entire string as key with empty value
      key = pair;
      value = '';
    } else {
      // Split at first '='
      key = pair.substring(0, equalsIndex);
      value = pair.substring(equalsIndex + 1);
    }

    // Skip pairs with empty keys
    if (key === '') {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeComponent(key);
    const decodedValue = decodeComponent(value);

    // Add to map (last value wins, but first position is preserved)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeComponent(str: string): string {
  if (str === '') {
    return str;
  }

  // Replace '+' with space first
  str = str.replace(/\+/g, ' ');

  // Try to decode percent-encoded characters
  try {
    // Use decodeURIComponent for proper UTF-8 decoding
    return decodeURIComponent(str);
  } catch (e) {
    // If decoding fails, return the string as-is (with + replaced)
    return str;
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error | null = null;

  for (let i = 0; i < attempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error as Error;
    }
  }

  throw new RetryError(attempts, lastError!);
}

