export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  return items.map(item => item.id === id ? ({ ...item, quantity }) : item)
    .filter(item => item.quantity > 0);
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result = [...items];

  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }

  return result;
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds < 0) {
    return '-' + formatDuration(-totalSeconds);
  }

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  if (hours > 0) {
    return `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  } else if (minutes > 0) {
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    return `${seconds}s`;
  }
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  const parts = text.trim().split(' ');
  let isNegative = false;

  if (parts.length === 0) {
    return NaN;
  }

  // Check for negative sign at the beginning
  if (parts[0].startsWith('-')) {
    isNegative = true;
    parts[0] = parts[0].substring(1);
  }

  // Validate each part
  for (const part of parts) {
    if (!/^\d+[hms]$/.test(part)) {
      return NaN;
    }
  }

  let totalSeconds = 0;

  for (const part of parts) {
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1]);
    const unit = match[2];

    switch (unit) {
      case 'h':
        totalSeconds += value * 3600;
        break;
      case 'm':
        totalSeconds += value * 60;
        break;
      case 's':
        totalSeconds += value;
        break;
    }
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

type Listener<T> = (payload: T) => void;

class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }
    const eventListeners = this.listeners.get(event)!;
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }
    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    const eventListeners = this.listeners.get(event)!;
    const listenersToCall = [...eventListeners];
    for (const listener of listenersToCall) {
      listener(payload);
    }
    return listenersToCall.length;
  }

  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }
    return this.listeners.get(event)!.length;
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more");
    }
    this.capacity = capacity;
    this.cache = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      // Key already exists, update its value and move to end (most recent)
      this.cache.set(key, value);
      this.updateOrder(key);
    } else {
      // New key
      if (this.cache.size >= this.capacity) {
        // Remove least recently used key
        const oldestKey = this.order.shift();
        if (oldestKey !== undefined) {
          this.cache.delete(oldestKey);
        }
      }
      this.cache.set(key, value);
      this.order.push(key);
    }
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }
    this.updateOrder(key);
    return this.cache.get(key);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (from least to most recent)
    return [...this.order];
  }

  get size(): number {
    return this.cache.size;
  }

  private updateOrder(key: K): void {
    // Remove key from current position
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
    }
    // Add key to end (most recent)
    this.order.push(key);
  }
}

