interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private currentState: EditorState;
  private history: EditorState[] = [];
  private historyLimit: number;
  private listeners: Map<string, Array<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();

  constructor(initial: EditorState, historyLimit: number) {
    this.currentState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = Math.max(1, historyLimit);
  }

  get state(): EditorState {
    return {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };
  }

  private notifyListeners(field: string, newValue: string | number | boolean, oldValue: string | number | boolean): void {
    const fieldListeners = this.listeners.get(field);
    if (fieldListeners) {
      for (const listener of fieldListeners) {
        listener(newValue, oldValue);
      }
    }
  }

  private saveToHistory(): void {
    if (this.history.length >= this.historyLimit) {
      this.history.shift();
    }
    this.history.push({
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    });
  }

  private restoreFromHistory(index: number): boolean {
    if (index < 0 || index >= this.history.length) {
      return false;
    }

    const previousState: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    const historyItem = this.history[index];
    this.currentState = {
      text: historyItem.text,
      cursor: historyItem.cursor,
      bold: historyItem.bold
    };

    // Notify listeners about changes
    if (previousState.text !== this.currentState.text) {
      this.notifyListeners('text', this.currentState.text, previousState.text);
    }
    if (previousState.cursor !== this.currentState.cursor) {
      this.notifyListeners('cursor', this.currentState.cursor, previousState.cursor);
    }
    if (previousState.bold !== this.currentState.bold) {
      this.notifyListeners('bold', this.currentState.bold, previousState.bold);
    }

    return true;
  }

  apply(patch: Partial<EditorState>): boolean {
    if (!patch || Object.keys(patch).length === 0) {
      return false;
    }

    const previousState: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    let hasChanges = false;
    const newState: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    if (patch.text !== undefined && patch.text !== this.currentState.text) {
      newState.text = patch.text;
      hasChanges = true;
    }
    if (patch.cursor !== undefined && patch.cursor !== this.currentState.cursor) {
      newState.cursor = patch.cursor;
      hasChanges = true;
    }
    if (patch.bold !== undefined && patch.bold !== this.currentState.bold) {
      newState.bold = patch.bold;
      hasChanges = true;
    }

    if (!hasChanges) {
      return false;
    }

    this.currentState = newState;
    // Save to history
    this.saveToHistory();

    // Notify listeners about changes
    if (previousState.text !== this.currentState.text) {
      this.notifyListeners('text', this.currentState.text, previousState.text);
    }
    if (previousState.cursor !== this.currentState.cursor) {
      this.notifyListeners('cursor', this.currentState.cursor, previousState.cursor);
    }
    if (previousState.bold !== this.currentState.bold) {
      this.notifyListeners('bold', this.currentState.bold, previousState.bold);
    }

    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    const previousState: EditorState = {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };

    let hasChanges = false;

    try {
      run(draft);

      // Check if any changes were made
      if (draft.text !== this.currentState.text) {
        this.currentState.text = draft.text;
        hasChanges = true;
      }
      if (draft.cursor !== this.currentState.cursor) {
        this.currentState.cursor = draft.cursor;
        hasChanges = true;
      }
      if (draft.bold !== this.currentState.bold) {
        this.currentState.bold = draft.bold;
        hasChanges = true;
      }

      if (!hasChanges) {
        return false;
      }

      // Save to history
      this.saveToHistory();

      // Notify listeners about changes
      if (previousState.text !== this.currentState.text) {
        this.notifyListeners('text', this.currentState.text, previousState.text);
      }
      if (previousState.cursor !== this.currentState.cursor) {
        this.notifyListeners('cursor', this.currentState.cursor, previousState.cursor);
      }
      if (previousState.bold !== this.currentState.bold) {
        this.notifyListeners('bold', this.currentState.bold, previousState.bold);
      }

      return true;
    } catch (error) {
      // Restore original state on error
      this.currentState = {
        text: previousState.text,
        cursor: previousState.cursor,
        bold: previousState.bold
      };
      throw new Error("Transaction failed");
    }
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const historyIndex = this.history.length - 1;
    return this.restoreFromHistory(historyIndex);
  }

  redo(): boolean {
    // In a real implementation, we'd need to track redo history
    // For simplicity, we'll just return false here since we don't implement redo history
    return false;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    // In a real implementation, we'd check if there's redo history
    return false;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    const fieldListeners = this.listeners.get(field)!;
    fieldListeners.push(listener);

    return () => {
      const index = fieldListeners.indexOf(listener);
      if (index !== -1) {
        fieldListeners.splice(index, 1);
      }
    };
  }
}

interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface WaitingJob<T> {
  job: () => Promise<T>;
  resolve: (value: T | PromiseLike<T>) => void;
  reject: (reason: Error) => void;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: Array<WaitingJob<Object>> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error('Concurrency must be a whole number greater than or equal to 1');
    }
    this.concurrency = concurrency;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const waitingJob: WaitingJob<T> = {
        job: job,
        resolve: resolve,
        reject: reject
      };
      this.waitingJobs.push(waitingJob as unknown as WaitingJob<Object>);

      if (!this.paused && this.runningJobs < this.concurrency) {
        this.startNextJob();
      }
    });
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    while (this.runningJobs < this.concurrency && this.waitingJobs.length > 0) {
      this.startNextJob();
    }
  }

  clear(): number {
    const count = this.waitingJobs.length;
    for (let i = 0; i < this.waitingJobs.length; i++) {
      const waitingJob = this.waitingJobs[i];
      waitingJob.reject(new Error('Job was cancelled'));
    }
    this.waitingJobs = [];
    return count;
  }

  whenIdle(): Promise<void> {
    if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }

    return new Promise<void>(resolve => {
      const checkIdle = () => {
        if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
          resolve();
        } else {
          // Schedule next check
          setTimeout(checkIdle, 0);
        }
      };
      checkIdle();
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const outcomes: JobOutcome<T>[] = [];
    const promises: Promise<void>[] = [];

    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i];
      const promise = this.add(job)
        .then(value => {
          outcomes.push({ ok: true, value: value, error: undefined });
        })
        .catch(error => {
          outcomes.push({ ok: false, value: undefined, error: error });
        });

      promises.push(promise);
    }

    return Promise.all(promises).then(() => outcomes);
  }

  private startNextJob(): void {
    if (this.waitingJobs.length === 0 || this.runningJobs >= this.concurrency || this.paused) {
      return;
    }

    const waitingJob = this.waitingJobs.shift()!;
    this.runningJobs++;

    waitingJob.job()
      .then((value: Object) => {
        this.completedCount++;
        this.runningJobs--;
        waitingJob.resolve(value as any);
        this.startNextJob();
      })
      .catch((error: Error) => {
        this.failedCount++;
        this.runningJobs--;
        waitingJob.reject(error);
        this.startNextJob();
      });
  }
}

