interface Expense {
  category: string;
  amount: number;
}

function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentAmount = result.get(expense.category) || 0;
    result.set(expense.category, currentAmount + expense.amount);
  }

  return result;
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    if (/\d/.test(char)) {
      const start = i;
      while (i < source.length && /\d/.test(source[i])) {
        i++;
      }
      if (i < source.length && source[i] === '.') {
        i++;
        if (i >= source.length || !/\d/.test(source[i])) {
          throw new ExpressionError(`Unexpected character '${source[i]}'`, i);
        }
        while (i < source.length && /\d/.test(source[i])) {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (/[a-zA-Z_]/.test(char)) {
      const start = i;
      while (i < source.length && /[a-zA-Z0-9_]/.test(source[i])) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i
      });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  let pos = 0;

  function peek(): Token | null {
    return pos < tokens.length ? tokens[pos] : null;
  }

  function consume(kind: string): Token {
    const token = peek();
    if (!token || token.kind !== kind) {
      throw new ExpressionError(`Unexpected token '${token?.text || ''}'`, token?.position || source.length);
    }
    pos++;
    return token;
  }

  function parseExpression(): number {
    return parseAdditive();
  }

  function parseAdditive(): number {
    let result = parseMultiplicative();

    while (peek()?.text === '+' || peek()?.text === '-') {
      const op = peek()!.text;
      pos++;
      const right = parseMultiplicative();
      if (op === '+') {
        result += right;
      } else {
        result -= right;
      }
    }

    return result;
  }

  function parseMultiplicative(): number {
    let result = parseUnary();

    while (peek()?.text === '*' || peek()?.text === '/' || peek()?.text === '%') {
      const op = peek()!.text;
      pos++;
      const right = parseUnary();
      if (op === '*') {
        result *= right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', pos - 1);
        }
        result /= right;
      } else {
        if (right === 0) {
          throw new ExpressionError('Division by zero', pos - 1);
        }
        result %= right;
      }
    }

    return result;
  }

  function parseUnary(): number {
    if (peek()?.text === '-') {
      pos++;
      return -parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      pos++;
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      pos++;
      // Check if variable exists using Object.hasOwn (fallback for older environments)
      let hasVariable = false;
      for (const key in variables) {
        if (key === token.text) {
          hasVariable = true;
          break;
        }
      }
      if (!hasVariable) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return variables[token.text];
    }

    if (token.text === '(') {
      pos++;
      const result = parseExpression();
      consume('paren');
      return result;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpression();

  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

