export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  if (attempts < 1) {
    attempts = 1;
  }

  let lastError: Error | null = null;

  for (let i = 0; i < attempts; i++) {
    try {
      return await action();
    } catch (error) {
      lastError = error as Error;
    }
  }

  throw new RetryError(attempts, lastError!);
}

// Define the Shape type as an interface with common properties
interface Shape {
  type: string;
}

// Extend the Shape interface for specific shapes
interface Circle extends Shape {
  type: "circle";
  radius: number;
}

interface Rectangle extends Shape {
  type: "rectangle";
  width: number;
  height: number;
}

interface Triangle extends Shape {
  type: "triangle";
  base: number;
  height: number;
}

// Union type for all possible shapes
type ShapeType = Circle | Rectangle | Triangle;

// Function to create a circle shape
function circle(radius: number): ShapeType {
  return {
    type: "circle",
    radius: radius
  };
}

// Function to create a rectangle shape
function rectangle(width: number, height: number): ShapeType {
  return {
    type: "rectangle",
    width: width,
    height: height
  };
}

// Function to create a triangle shape
function triangle(base: number, height: number): ShapeType {
  return {
    type: "triangle",
    base: base,
    height: height
  };
}

// Function to calculate the area of a shape
function area(shape: ShapeType): number {
  switch (shape.type) {
    case "circle":
      return Math.PI * shape.radius * shape.radius;
    case "rectangle":
      return shape.width * shape.height;
    case "triangle":
      return shape.base * shape.height / 2;
    default:
      return 0;
  }
}

// Function to calculate the total area of multiple shapes
function totalArea(shapes: ShapeType[]): number {
  let total = 0;
  for (const shape of shapes) {
    total += area(shape);
  }
  return total;
}

export { ShapeType as Shape, circle, rectangle, triangle, area, totalArea };

interface Item {
  id: string;
  name: string;
  quantity: number;
}

interface Change {
  id: string;
  quantity: number;
}

function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  let found = false;

  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        result.push({
          id: item.id,
          name: item.name,
          quantity: quantity
        });
      }
      found = true;
    } else {
      result.push({
        id: item.id,
        name: item.name,
        quantity: item.quantity
      });
    }
  }

  // If no item with the given id was found, return the original array
  if (!found) {
    return items;
  }

  return result;
}

function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result: Item[] = [...items];

  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }

  return result;
}

