export function formatDuration(totalSeconds: number): string {
  if (totalSeconds === 0) {
    return "0s";
  }

  const isNegative = totalSeconds < 0;
  if (isNegative) {
    totalSeconds = -totalSeconds;
  }

  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  let result = "";

  if (hours > 0) {
    result += `${hours}h `;
  }

  if (minutes > 0 || hours > 0) {
    result += `${minutes.toString().padStart(2, '0')}m `;
  }

  result += `${seconds.toString().padStart(2, '0')}s`;

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  // Check for invalid characters or patterns
  if (/[^0-9hms\s-]/.test(text)) {
    return NaN;
  }

  // Check for consecutive spaces or leading/trailing spaces
  if (text.startsWith(' ') || text.endsWith(' ') || /  /.test(text)) {
    return NaN;
  }

  const parts = text.trim().split(/\s+/);

  if (parts.length === 0) {
    return NaN;
  }

  let isNegative = false;
  let totalSeconds = 0;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Handle negative sign only at the beginning
    if (i === 0 && part.startsWith('-')) {
      isNegative = true;
      const numPart = part.substring(1);
      if (!/^\d+[hms]$/.test(numPart)) {
        return NaN;
      }
      const match = numPart.match(/^(\d+)([hms])$/);
      if (!match) {
        return NaN;
      }
      const value = parseInt(match[1]);
      const unit = match[2];

      switch (unit) {
        case 'h':
          totalSeconds += value * 3600;
          break;
        case 'm':
          totalSeconds += value * 60;
          break;
        case 's':
          totalSeconds += value;
          break;
      }
    } else if (/^\d+[hms]$/.test(part)) {
      const match = part.match(/^(\d+)([hms])$/);
      if (!match) {
        return NaN;
      }
      const value = parseInt(match[1]);
      const unit = match[2];

      switch (unit) {
        case 'h':
          totalSeconds += value * 3600;
          break;
        case 'm':
          totalSeconds += value * 60;
          break;
        case 's':
          totalSeconds += value;
          break;
      }
    } else {
      return NaN;
    }
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  const dayRules = rules.filter(rule => rule.day === day);

  for (const rule of dayRules) {
    if (hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }

  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Create a list of all days with at least one rule
  const daysWithRules = new Set<Weekday>();
  for (const rule of rules) {
    daysWithRules.add(rule.day);
  }

  // If no day has any rules, return undefined
  if (daysWithRules.size === 0) {
    return undefined;
  }

  // Start checking from the day after the given day
  let currentDay = (day + 1) % 7;

  // Check each day in order until we find one with rules
  // We check up to 7 days (one full week) to avoid infinite loop
  for (let i = 0; i < 7; i++) {
    if (daysWithRules.has(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  // If we get here, the only day with rules is the input day itself
  // Return the day one week later (same day)
  return day;
}

interface User {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  try {
    const data = JSON.parse(json);

    if (!Array.isArray(data)) {
      return [];
    }

    const users: User[] = [];

    for (const item of data) {
      // Check if item is an object
      if (typeof item !== 'object' || item === null) {
        continue;
      }

      // Check if id is an integer number
      if (typeof item.id !== 'number' || !Number.isInteger(item.id)) {
        continue;
      }

      // Check if name is a non-empty string
      if (typeof item.name !== 'string' || item.name.length === 0) {
        continue;
      }

      // Check if email is a string containing '@'
      if (typeof item.email !== 'string' || !item.email.includes('@')) {
        continue;
      }

      // If all checks pass, add the user with only the required fields
      users.push({
        id: item.id,
        name: item.name,
        email: item.email
      });
    }

    return users;
  } catch (error) {
    // Return empty array if JSON parsing fails
    return [];
  }
}

/**
 * A generic type representing a pair of values.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits an array into consecutive groups of a specified size.
 * @param items - The array to split.
 * @param size - The size of each group.
 * @returns An array of arrays, where each inner array contains up to `size` elements from the original array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Zips two arrays together into an array of pairs.
 * @param a - The first array.
 * @param b - The second array.
 * @returns An array of pairs where each pair contains elements from the corresponding indices of the input arrays.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    result.push({ first: a[i], second: b[i] } as Pair<A, B>);
  }

  return result;
}

