export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.tasks) {
      const dependencies = spec[task];
      for (const dependency of dependencies) {
        let found = false;
        const specKeys = Object.keys(spec);
        for (let i = 0; i < specKeys.length; i++) {
          if (specKeys[i] === dependency) {
            found = true;
            break;
          }
        }
        if (!found) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    // Check for cycles
    const visited = new Set<string>();
    const visiting = new Set<string>();
    const path: string[] = [];

    const visit = (task: string): void => {
      if (visiting.has(task)) {
        // Found a cycle
        const cycleStartIndex = path.indexOf(task);
        const cyclePath = path.slice(cycleStartIndex).concat(task);
        throw new CycleError(cyclePath);
      }

      if (visited.has(task)) {
        return;
      }

      visiting.add(task);
      path.push(task);

      const dependencies = spec[task] || [];
      for (const dependency of dependencies) {
        visit(dependency);
      }

      path.pop();
      visiting.delete(task);
      visited.add(task);
    };

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        visit(task);
      }
    }
  }

  order(): string[] {
    const result: string[] = [];
    const visited = new Set<string>();

    const placeTask = (task: string): void => {
      if (visited.has(task)) {
        return;
      }

      const dependencies = this.spec[task] || [];
      for (const dependency of dependencies) {
        placeTask(dependency);
      }

      result.push(task);
      visited.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task);
    }

    return result;
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    const layers: string[][] = [];
    const visited = new Set<string>();
    const taskLayers = new Map<string, number>();

    // Initialize all tasks to layer -1 (unprocessed)
    for (const task of this.tasks) {
      taskLayers.set(task, -1);
    }

    const computeLayer = (task: string): number => {
      if (taskLayers.get(task) !== -1) {
        return taskLayers.get(task)!;
      }

      const dependencies = this.spec[task] || [];
      let maxLayer = -1;

      for (const dependency of dependencies) {
        const depLayer = computeLayer(dependency);
        if (depLayer > maxLayer) {
          maxLayer = depLayer;
        }
      }

      const layer = maxLayer + 1;
      taskLayers.set(task, layer);
      return layer;
    };

    // Compute layers for all tasks
    for (const task of this.tasks) {
      computeLayer(task);
    }

    // Group tasks into layers
    for (const task of this.tasks) {
      const layer = taskLayers.get(task)!;
      if (layers.length <= layer) {
        layers.push([]);
      }
      layers[layer].push(task);
    }

    // Sort each layer according to key order
    for (const layer of layers) {
      layer.sort((a, b) => {
        const indexA = this.tasks.indexOf(a);
        const indexB = this.tasks.indexOf(b);
        return indexA - indexB;
      });
    }

    return layers;
  }

  dependentsOf(name: string): string[] {
    const result: string[] = [];
    const visited = new Set<string>();

    const findDependents = (task: string): void => {
      if (visited.has(task)) {
        return;
      }

      visited.add(task);

      const dependencies = this.spec[task] || [];
      if (dependencies.includes(name)) {
        result.push(task);
      }

      for (const dep of this.tasks) {
        if (this.spec[dep]?.includes(task)) {
          findDependents(dep);
        }
      }
    };

    for (const task of this.tasks) {
      if (task !== name && this.spec[task]?.includes(name)) {
        result.push(task);
      }
    }

    // Add all transitive dependents
    const visitedForTransitive = new Set<string>();
    const addTransitiveDependents = (task: string): void => {
      if (visitedForTransitive.has(task)) {
        return;
      }

      visitedForTransitive.add(task);

      for (const dep of this.tasks) {
        if (this.spec[dep]?.includes(task)) {
          if (!result.includes(dep)) {
            result.push(dep);
          }
          addTransitiveDependents(dep);
        }
      }
    };

    for (const task of result) {
      addTransitiveDependents(task);
    }

    // Return in order of execution
    const orderResult = this.order();
    return result.filter(task => orderResult.includes(task)).sort((a, b) => {
      const indexA = orderResult.indexOf(a);
      const indexB = orderResult.indexOf(b);
      return indexA - indexB;
    });
  }
}

export class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more");
    }
    this.capacity = capacity;
    this.cache = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      // Key already exists, update its position
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else if (this.cache.size >= this.capacity) {
      // Cache is full, remove the least recently used key
      const oldestKey = this.order.shift();
      if (oldestKey !== undefined) {
        this.cache.delete(oldestKey);
      }
    }

    // Add/update the key-value pair
    this.cache.set(key, value);
    this.order.push(key);
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move the key to the end (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.cache.get(key);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (from least to most recent)
    return [...this.order];
  }

  get size(): number {
    return this.cache.size;
  }
}

