type Transform = (text: string) => string;

function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

interface PipelineStep {
  name: string;
  func: Transform;
}

class Pipeline {
  private steps: PipelineStep[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, func: step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const step of this.steps) {
      result = step.func(result);
    }
    return result;
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    const steps = this.steps;
    return (text: string): string => {
      let result = text;
      for (const step of steps) {
        result = step.func(result);
      }
      return result;
    };
  }
}

function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }
  return (text: string) => steps.reduce((result, step) => step(result), text);
}

enum OrderStatus {
    Draft = 'draft',
    Paid = 'paid',
    Shipped = 'shipped'
}

class OrderLine {
    sku: string;
    quantity: number;
    unitPrice: number;

    constructor(sku: string, quantity: number, unitPrice: number) {
        this.sku = sku;
        this.quantity = quantity;
        this.unitPrice = unitPrice;
    }

    total(): number {
        return this.quantity * this.unitPrice;
    }
}

interface Order {
    id: string;
    status: OrderStatus;
    lines: OrderLine[];
}

interface FieldError {
    path: string;
    message: string;
}

interface ParseResult {
    order: Order | undefined;
    errors: FieldError[];
}

function parseOrder(text: string): ParseResult {
    let parsed: Record<string, unknown>;
    try {
        parsed = JSON.parse(text);
    } catch (e) {
        return {
            order: undefined,
            errors: [{ path: '', message: 'invalid JSON' }]
        };
    }

    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        return {
            order: undefined,
            errors: [{ path: '', message: 'expected an object' }]
        };
    }

    const errors: FieldError[] = [];
    const order: Partial<Order> = {};

    // Check id
    if (parsed.id === undefined || parsed.id === null) {
        errors.push({ path: 'id', message: 'required' });
    } else if (typeof parsed.id !== 'string') {
        errors.push({ path: 'id', message: 'expected a string' });
    } else if (parsed.id === '') {
        errors.push({ path: 'id', message: 'must not be empty' });
    } else {
        order.id = parsed.id as string;
    }

    // Check status
    if (parsed.status === undefined || parsed.status === null) {
        order.status = OrderStatus.Draft;
    } else if (typeof parsed.status !== 'string') {
        errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    } else if (!Object.values(OrderStatus).includes(parsed.status as OrderStatus)) {
        errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    } else {
        order.status = parsed.status as OrderStatus;
    }

    // Check lines
    if (parsed.lines === undefined || parsed.lines === null) {
        errors.push({ path: 'lines', message: 'required' });
    } else if (!Array.isArray(parsed.lines)) {
        errors.push({ path: 'lines', message: 'expected an array' });
    } else if (parsed.lines.length === 0) {
        errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
        order.lines = [];
        for (let i = 0; i < parsed.lines.length; i++) {
            const line = parsed.lines[i];
            const linePath = `lines[${i}]`;

            if (typeof line !== 'object' || line === null) {
                errors.push({ path: linePath, message: 'expected an object' });
                continue;
            }

            const lineObj: Partial<OrderLine> = {};
            const lineErrors: FieldError[] = [];

            // Check sku
            if (line.sku === undefined || line.sku === null) {
                lineErrors.push({ path: `${linePath}.sku`, message: 'required' });
            } else if (typeof line.sku !== 'string') {
                lineErrors.push({ path: `${linePath}.sku`, message: 'expected a string' });
            } else if (line.sku === '') {
                lineErrors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
            } else {
                lineObj.sku = line.sku as string;
            }

            // Check quantity
            if (line.quantity === undefined || line.quantity === null) {
                lineErrors.push({ path: `${linePath}.quantity`, message: 'required' });
            } else if (typeof line.quantity !== 'number') {
                lineErrors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
            } else if (line.quantity < 1 || !Number.isInteger(line.quantity)) {
                lineErrors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
            } else {
                lineObj.quantity = line.quantity as number;
            }

            // Check unitPrice
            if (line.unitPrice === undefined || line.unitPrice === null) {
                lineErrors.push({ path: `${linePath}.unitPrice`, message: 'required' });
            } else if (typeof line.unitPrice !== 'number') {
                lineErrors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
            } else if (line.unitPrice < 0) {
                lineErrors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
            } else {
                lineObj.unitPrice = line.unitPrice as number;
            }

            // Check unknown fields in line
            const knownFields = ['sku', 'quantity', 'unitPrice'];
            const lineKeys = Object.keys(line);
            for (let j = 0; j < lineKeys.length; j++) {
                const key = lineKeys[j];
                if (!knownFields.includes(key)) {
                    lineErrors.push({ path: `${linePath}.${key}`, message: 'unknown field' });
                }
            }

            // Add line errors to main errors
            errors.push(...lineErrors);

            // If no errors for this line, create OrderLine instance
            if (lineErrors.length === 0 && 
                lineObj.sku !== undefined && 
                lineObj.quantity !== undefined && 
                lineObj.unitPrice !== undefined) {
                const newLine = new OrderLine(lineObj.sku, lineObj.quantity, lineObj.unitPrice);
                order.lines.push(newLine);
            }
        }
    }

    // Check unknown fields in order
    const knownFields = ['id', 'status', 'lines'];
    const parsedKeys = Object.keys(parsed);
    for (let i = 0; i < parsedKeys.length; i++) {
        const key = parsedKeys[i];
        if (!knownFields.includes(key)) {
            errors.push({ path: key, message: 'unknown field' });
        }
    }

    if (errors.length > 0) {
        return {
            order: undefined,
            errors
        };
    }

    return {
        order: order as Order,
        errors: []
    };
}

