interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface WaitingJob<T> {
  job: () => Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: Error) => void;
}

class JobQueue {
  private concurrency: number;
  private runningJobs: number = 0;
  private waitingJobs: WaitingJob<Object>[] = [];
  private completedJobs: number = 0;
  private failedJobs: number = 0;
  private paused: boolean = false;

  constructor(concurrency: number) {
    if (concurrency < 1 || !Number.isInteger(concurrency)) {
      throw new Error("Concurrency must be a whole number greater than or equal to 1");
    }
    this.concurrency = concurrency;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const waitingJob: WaitingJob<T> = { job, resolve, reject };
      this.waitingJobs.push(waitingJob);

      if (!this.paused && this.runningJobs < this.concurrency) {
        this.startNextJob();
      }
    });
  }

  private startNextJob(): void {
    if (this.waitingJobs.length === 0 || this.runningJobs >= this.concurrency) {
      return;
    }

    const waitingJob = this.waitingJobs.shift()!;
    this.runningJobs++;

    waitingJob.job().then(value => {
      this.completedJobs++;
      this.runningJobs--;
      waitingJob.resolve(value);
      this.maybeStartNextJob();
    }).catch(error => {
      this.failedJobs++;
      this.runningJobs--;
      waitingJob.reject(error);
      this.maybeStartNextJob();
    });
  }

  private maybeStartNextJob(): void {
    if (!this.paused && this.runningJobs < this.concurrency && this.waitingJobs.length > 0) {
      this.startNextJob();
    }
  }

  get running(): number {
    return this.runningJobs;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedJobs;
  }

  get failed(): number {
    return this.failedJobs;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    while (this.runningJobs < this.concurrency && this.waitingJobs.length > 0) {
      this.startNextJob();
    }
  }

  clear(): number {
    const count = this.waitingJobs.length;

    for (let i = 0; i < count; i++) {
      const waitingJob = this.waitingJobs[i];
      const error = new Error("Job was cancelled");
      waitingJob.reject(error);
    }

    this.waitingJobs = [];
    return count;
  }

  whenIdle(): Promise<void> {
    return new Promise<void>(resolve => {
      if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
        resolve();
      } else {
        const checkIdle = () => {
          if (this.runningJobs === 0 && this.waitingJobs.length === 0) {
            resolve();
          } else {
            setTimeout(checkIdle, 10);
          }
        };
        setTimeout(checkIdle, 10);
      }
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const outcomes: JobOutcome<T>[] = [];
    const promises: Promise<void>[] = [];

    for (const job of jobs) {
      const promise = this.add(job).then(value => {
        outcomes.push({ ok: true, value, error: undefined });
      }).catch(error => {
        outcomes.push({ ok: false, value: undefined, error });
      });
      promises.push(promise);
    }

    return Promise.all(promises).then(() => outcomes);
  }
}

enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

interface FieldError {
  path: string;
  message: string;
}

interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

interface ParsedJson {
  [key: string]: any;
}

function parseOrder(text: string): ParseResult {
  let parsed: ParsedJson;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'invalid JSON' }]
    };
  }

  if (typeof parsed !== 'object' || parsed === null) {
    return {
      order: undefined,
      errors: [{ path: '', message: 'expected an object' }]
    };
  }

  const errors: FieldError[] = [];
  const order: Partial<Order> = {};

  // Check id
  if (parsed.id === undefined || parsed.id === null) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof parsed.id !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (parsed.id === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  } else {
    order.id = parsed.id;
  }

  // Check status
  if (parsed.status === undefined || parsed.status === null) {
    order.status = OrderStatus.Draft;
  } else if (typeof parsed.status !== 'string') {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else if (!Object.values(OrderStatus).includes(parsed.status as OrderStatus)) {
    errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
  } else {
    order.status = parsed.status as OrderStatus;
  }

  // Check lines
  if (parsed.lines === undefined || parsed.lines === null) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(parsed.lines)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else if (parsed.lines.length === 0) {
    errors.push({ path: 'lines', message: 'must not be empty' });
  } else {
    order.lines = [];
    for (let i = 0; i < parsed.lines.length; i++) {
      const line = parsed.lines[i];
      const linePath = `lines[${i}]`;

      if (typeof line !== 'object' || line === null) {
        errors.push({ path: linePath, message: 'expected an object' });
        continue;
      }

      // Check sku
      if (line.sku === undefined || line.sku === null) {
        errors.push({ path: `${linePath}.sku`, message: 'required' });
      } else if (typeof line.sku !== 'string') {
        errors.push({ path: `${linePath}.sku`, message: 'expected a string' });
      } else if (line.sku === '') {
        errors.push({ path: `${linePath}.sku`, message: 'must not be empty' });
      }

      // Check quantity
      if (line.quantity === undefined || line.quantity === null) {
        errors.push({ path: `${linePath}.quantity`, message: 'required' });
      } else if (typeof line.quantity !== 'number') {
        errors.push({ path: `${linePath}.quantity`, message: 'expected a number' });
      } else if (line.quantity < 1 || !Number.isInteger(line.quantity)) {
        errors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' });
      }

      // Check unitPrice
      if (line.unitPrice === undefined || line.unitPrice === null) {
        errors.push({ path: `${linePath}.unitPrice`, message: 'required' });
      } else if (typeof line.unitPrice !== 'number') {
        errors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' });
      } else if (line.unitPrice < 0) {
        errors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' });
      }

      // Create OrderLine if all validations pass
      if (
        line.sku !== undefined && line.sku !== null && typeof line.sku === 'string' && line.sku !== '' &&
        line.quantity !== undefined && line.quantity !== null && typeof line.quantity === 'number' && 
        line.quantity >= 1 && Number.isInteger(line.quantity) &&
        line.unitPrice !== undefined && line.unitPrice !== null && typeof line.unitPrice === 'number' && 
        line.unitPrice >= 0
      ) {
        order.lines.push(new OrderLine(line.sku, line.quantity, line.unitPrice));
      }

      // Check unknown fields in line
      const knownFields = ['sku', 'quantity', 'unitPrice'];
      const lineKeys = Object.keys(line);
      for (let j = 0; j < lineKeys.length; j++) {
        const key = lineKeys[j];
        if (!knownFields.includes(key)) {
          errors.push({ path: `${linePath}.${key}`, message: 'unknown field' });
        }
      }
    }
  }

  // Check unknown fields in order
  const knownFields = ['id', 'status', 'lines'];
  const parsedKeys = Object.keys(parsed);
  for (let i = 0; i < parsedKeys.length; i++) {
    const key = parsedKeys[i];
    if (!knownFields.includes(key)) {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    return {
      order: undefined,
      errors
    };
  }

  return {
    order: order as Order,
    errors: []
  };
}

interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

class EditorStore {
  private currentState: EditorState;
  private history: EditorState[] = [];
  private historyLimit: number;
  private listeners: Map<string, Array<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();

  constructor(initial: EditorState, historyLimit: number) {
    if (historyLimit < 1) {
      throw new Error("historyLimit must be 1 or more");
    }
    this.currentState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    return {
      text: this.currentState.text,
      cursor: this.currentState.cursor,
      bold: this.currentState.bold
    };
  }

  private notifyListeners(field: string, newValue: string | number | boolean, oldValue: string | number | boolean): void {
    const fieldListeners = this.listeners.get(field);
    if (fieldListeners) {
      for (const listener of fieldListeners) {
        listener(newValue, oldValue);
      }
    }
  }

  private addToHistory(state: EditorState): void {
    this.history.push({
      text: state.text,
      cursor: state.cursor,
      bold: state.bold
    });
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }
  }

  apply(patch: Partial<EditorState>): boolean {
    const oldState = this.state;
    let changed = false;

    if (patch.text !== undefined && patch.text !== this.currentState.text) {
      this.currentState.text = patch.text;
      changed = true;
    }

    if (patch.cursor !== undefined && patch.cursor !== this.currentState.cursor) {
      this.currentState.cursor = patch.cursor;
      changed = true;
    }

    if (patch.bold !== undefined && patch.bold !== this.currentState.bold) {
      this.currentState.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.addToHistory(oldState);
      this.notifyListeners('text', this.currentState.text, oldState.text);
      this.notifyListeners('cursor', this.currentState.cursor, oldState.cursor);
      this.notifyListeners('bold', this.currentState.bold, oldState.bold);
    }

    return changed;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = this.state;
    const oldState = this.state;
    try {
      run(draft);
      return this.apply(draft);
    } catch (error) {
      // Restore original state on error
      this.currentState = oldState;
      throw new Error(error instanceof Error ? error.message : String(error));
    }
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const prevState = this.history.pop()!;
    const oldState = this.state;

    this.currentState = prevState;

    this.notifyListeners('text', this.currentState.text, oldState.text);
    this.notifyListeners('cursor', this.currentState.cursor, oldState.cursor);
    this.notifyListeners('bold', this.currentState.bold, oldState.bold);

    return true;
  }

  redo(): boolean {
    // Note: In a real implementation, we'd need to track redo history separately
    // For now, we'll just return false since we don't maintain redo history
    return false;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    // Note: In a real implementation, we'd need to track redo history separately
    return false;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    const fieldListeners = this.listeners.get(field)!;
    fieldListeners.push(listener);

    return () => {
      const index = fieldListeners.indexOf(listener);
      if (index !== -1) {
        fieldListeners.splice(index, 1);
      }
    };
  }
}

interface Expense {
  category: string;
  amount: number;
}

function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();
  const seenCategories = new Set<string>();

  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const category = expense.category;
    const amount = expense.amount;

    if (!seenCategories.has(category)) {
      seenCategories.add(category);
      result.set(category, amount);
    } else {
      const currentAmount = result.get(category) || 0;
      result.set(category, currentAmount + amount);
    }
  }

  return result;
}

interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
}

function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading '?' if present
  if (query.startsWith('?')) {
    query = query.substring(1);
  }

  // Handle empty query
  if (query.length === 0) {
    return result;
  }

  // Split by '&' and process each pair
  const pairs = query.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair.length === 0) {
      continue;
    }

    let key: string;
    let value: string;

    // Find first '=' to split key and value
    const equalsIndex = pair.indexOf('=');

    if (equalsIndex === -1) {
      // No '=' found, treat entire string as key with empty value
      key = pair;
      value = '';
    } else {
      // Split at first '='
      key = pair.substring(0, equalsIndex);
      value = pair.substring(equalsIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeURIComponentPlus(key);
    const decodedValue = decodeURIComponentPlus(value);

    // Add to map (last value wins, but keep first position)
    if (!result.has(decodedKey)) {
      result.set(decodedKey, decodedValue);
    } else {
      // Key already exists, update value but keep position
      result.set(decodedKey, decodedValue);
    }
  }

  return result;
}

function decodeURIComponentPlus(str: string): string {
  // Replace '+' with space first
  str = str.replace(/\+/g, ' ');

  // Try to decode percent escapes
  try {
    return decodeURIComponent(str);
  } catch (e) {
    // If decode fails due to malformed escape, return as-is (but with + replaced)
    return str;
  }
}

interface Point {
  x: number;
  y: number;
}

interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const point = points[i];
    if (point.x < minX) {
      minX = point.x;
    }
    if (point.y < minY) {
      minY = point.y;
    }
    if (point.x > maxX) {
      maxX = point.x;
    }
    if (point.y > maxY) {
      maxY = point.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  return {
    min,
    max,
    width: maxX - minX,
    height: maxY - minY
  };
}

interface User {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  let result: User[] = [];

  try {
    const parsed = JSON.parse(json);

    if (!Array.isArray(parsed)) {
      return [];
    }

    for (const item of parsed) {
      if (item === null || typeof item !== 'object') {
        continue;
      }

      if (typeof item.id !== 'number' || !Number.isInteger(item.id)) {
        continue;
      }

      if (typeof item.name !== 'string' || item.name.length === 0) {
        continue;
      }

      if (typeof item.email !== 'string' || !item.email.includes('@')) {
        continue;
      }

      result.push({
        id: item.id,
        name: item.name,
        email: item.email
      });
    }
  } catch (e: any) {
    // Silently ignore parsing errors and return empty array
  }

  return result;
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private tasks: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.tasks = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.tasks) {
      const dependencies = spec[task];
      for (const dependency of dependencies) {
        let found = false;
        const specKeys = Object.keys(spec);
        for (let i = 0; i < specKeys.length; i++) {
          if (specKeys[i] === dependency) {
            found = true;
            break;
          }
        }
        if (!found) {
          throw new MissingDependencyError(task, dependency);
        }
      }
    }

    // Check for cycles
    const visited: Set<string> = new Set();
    const visiting: Set<string> = new Set();
    const path: string[] = [];

    const visit = (task: string): void => {
      if (visiting.has(task)) {
        // Found a cycle
        const cycleStartIndex = path.indexOf(task);
        const cyclePath = path.slice(cycleStartIndex).concat(task);
        throw new CycleError(cyclePath);
      }

      if (visited.has(task)) {
        return;
      }

      visiting.add(task);
      path.push(task);

      const dependencies = spec[task] || [];
      for (const dependency of dependencies) {
        visit(dependency);
      }

      path.pop();
      visiting.delete(task);
      visited.add(task);
    };

    for (const task of this.tasks) {
      if (!visited.has(task)) {
        visit(task);
      }
    }
  }

  order(): string[] {
    const result: string[] = [];
    const visited: Set<string> = new Set();

    const placeTask = (task: string): void => {
      if (visited.has(task)) {
        return;
      }

      const dependencies = this.spec[task] || [];
      for (const dependency of dependencies) {
        placeTask(dependency);
      }

      result.push(task);
      visited.add(task);
    };

    for (const task of this.tasks) {
      placeTask(task);
    }

    return result;
  }

  layers(): string[][] {
    if (this.tasks.length === 0) {
      return [];
    }

    const result: string[][] = [];
    const visited: Set<string> = new Set();
    const layerMap: Map<string, number> = new Map();

    const calculateLayer = (task: string): number => {
      if (visited.has(task)) {
        return layerMap.get(task) || 0;
      }

      const dependencies = this.spec[task] || [];
      let maxLayer = 0;

      for (const dependency of dependencies) {
        const depLayer = calculateLayer(dependency);
        if (depLayer > maxLayer) {
          maxLayer = depLayer;
        }
      }

      const layer = maxLayer + 1;
      layerMap.set(task, layer);
      visited.add(task);
      return layer;
    };

    // Calculate layers for all tasks
    for (const task of this.tasks) {
      calculateLayer(task);
    }

    // Group tasks by layer
    for (const task of this.tasks) {
      const layer = layerMap.get(task) || 0;
      if (result.length <= layer) {
        result.length = layer + 1;
      }
      if (!result[layer]) {
        result[layer] = [];
      }
      result[layer].push(task);
    }

    // Sort each layer by key order
    for (let i = 0; i < result.length; i++) {
      if (result[i]) {
        result[i].sort((a, b) => {
          const indexA = this.tasks.indexOf(a);
          const indexB = this.tasks.indexOf(b);
          return indexA - indexB;
        });
      }
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    const result: string[] = [];
    const placed = new Set<string>();
    const order = this.order();

    // Find all tasks that depend on the given name
    for (const task of this.tasks) {
      if (task !== name) {
        const dependencies = this.spec[task] || [];
        for (const dependency of dependencies) {
          if (dependency === name) {
            result.push(task);
            break;
          }
        }
      }
    }

    // Sort by order
    result.sort((a, b) => {
      const indexA = order.indexOf(a);
      const indexB = order.indexOf(b);
      return indexA - indexB;
    });

    return result;
  }
}

// Define the Listener type as a function that takes a payload of type T and returns nothing
type Listener<T> = (payload: T) => void;

// Generic class EventBus<T> that manages event listeners
class EventBus<T> {
  // Private map to store listeners for each event name
  private listeners: Map<string, Listener<T>[]> = new Map();

  // Register a listener for an event
  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, []);
    }

    const eventListeners = this.listeners.get(event)!;

    // Only add the listener if it's not already registered
    if (!eventListeners.includes(listener)) {
      eventListeners.push(listener);
    }
  }

  // Remove a listener from an event
  off(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      return;
    }

    const eventListeners = this.listeners.get(event)!;
    const index = eventListeners.indexOf(listener);

    // Remove the listener if it exists
    if (index !== -1) {
      eventListeners.splice(index, 1);
    }
  }

  // Emit an event with a payload and return the number of listeners called
  emit(event: string, payload: T): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    const eventListeners = this.listeners.get(event)!;
    // Create a copy of the listeners array to avoid issues with modifications during execution
    const listenersCopy = [...eventListeners];

    // Call each listener with the payload
    for (const listener of listenersCopy) {
      listener(payload);
    }

    return listenersCopy.length;
  }

  // Return the number of listeners registered for an event
  listenerCount(event: string): number {
    if (!this.listeners.has(event)) {
      return 0;
    }

    return this.listeners.get(event)!.length;
  }
}

