export function formatDuration(totalSeconds: number): string {
  if (isNaN(totalSeconds)) {
    return NaN.toString();
  }

  const isNegative = totalSeconds < 0;
  let seconds = Math.abs(totalSeconds);

  const hours = Math.floor(seconds / 3600);
  seconds %= 3600;
  const minutes = Math.floor(seconds / 60);
  seconds %= 60;

  let result = '';
  if (hours > 0) {
    result += `${hours}h `;
  }
  if (minutes > 0 || hours > 0) {
    result += `${minutes.toString().padStart(2, '0')}m `;
  }
  result += `${seconds.toString().padStart(2, '0')}s`;

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  const parts = text.trim().split(' ');
  if (parts.length === 0) {
    return NaN;
  }

  let isNegative = false;
  let totalSeconds = 0;

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];

    // Check for negative sign at the beginning
    if (i === 0 && part === '-') {
      isNegative = true;
      continue;
    }

    // Validate part format
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1]);
    const unit = match[2];

    if (isNaN(value)) {
      return NaN;
    }

    switch (unit) {
      case 'h':
        totalSeconds += value * 3600;
        break;
      case 'm':
        totalSeconds += value * 60;
        break;
      case 's':
        totalSeconds += value;
        break;
      default:
        return NaN;
    }
  }

  return isNegative ? -totalSeconds : totalSeconds;
}

/**
 * Represents a shape with a calculable area.
 */
interface Shape {
  /**
   * Calculates and returns the area of the shape.
   * @returns The area of the shape.
   */
  area(): number;
}

/**
 * Represents a circle shape.
 */
class Circle implements Shape {
  radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

/**
 * Represents a rectangle shape.
 */
class Rectangle implements Shape {
  width: number;
  height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

/**
 * Represents a triangle shape.
 */
class Triangle implements Shape {
  base: number;
  height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return (this.base * this.height) / 2;
  }
}

/**
 * Creates a circle shape.
 * @param radius - The radius of the circle.
 * @returns A Circle instance.
 */
export function circle(radius: number): Shape {
  return new Circle(radius);
}

/**
 * Creates a rectangle shape.
 * @param width - The width of the rectangle.
 * @param height - The height of the rectangle.
 * @returns A Rectangle instance.
 */
export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

/**
 * Creates a triangle shape.
 * @param base - The base of the triangle.
 * @param height - The height of the triangle.
 * @returns A Triangle instance.
 */
export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

/**
 * Calculates the total area of an array of shapes.
 * @param shapes - An array of shapes.
 * @returns The sum of the areas of all shapes, or 0 if the array is empty.
 */
export function totalArea(shapes: Shape[]): number {
  let total = 0;
  for (let i = 0; i < shapes.length; i++) {
    total += shapes[i].area();
  }
  return total;
}

export class LruCache<K, V> {
  private capacity: number;
  private cache: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more");
    }
    this.capacity = capacity;
    this.cache = new Map<K, V>();
    this.order = [];
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      // Key already exists, update its position
      const index = this.order.indexOf(key);
      if (index !== -1) {
        this.order.splice(index, 1);
      }
    } else if (this.cache.size >= this.capacity) {
      // Cache is full, remove the least recently used item
      const oldestKey = this.order.shift();
      if (oldestKey !== undefined) {
        this.cache.delete(oldestKey);
      }
    }

    this.cache.set(key, value);
    this.order.push(key);
  }

  get(key: K): V | undefined {
    if (!this.cache.has(key)) {
      return undefined;
    }

    // Move key to end (most recently used)
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
      this.order.push(key);
    }

    return this.cache.get(key);
  }

  has(key: K): boolean {
    return this.cache.has(key);
  }

  keys(): K[] {
    // Return a copy of the order array (least to most recent)
    return [...this.order];
  }

  get size(): number {
    return this.cache.size;
  }
}

/**
 * A generic type representing a pair of values.
 */
interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits an array into consecutive groups of a specified size.
 * @param items - The array to split.
 * @param size - The size of each group.
 * @returns An array of arrays, where each inner array contains up to `size` elements from the input.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }

  return result;
}

/**
 * Zips two arrays together into an array of pairs.
 * @param a - The first array.
 * @param b - The second array.
 * @returns An array of pairs where each pair contains elements from the corresponding indices of the input arrays.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }

  return result;
}

interface Item {
  id: string;
  name: string;
  quantity: number;
}

interface Change {
  id: string;
  quantity: number;
}

function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  let found = false;

  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        result.push({ id: item.id, name: item.name, quantity: quantity });
      }
      found = true;
    } else {
      result.push(item);
    }
  }

  if (!found) {
    return items;
  }

  return result;
}

function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result: Item[] = [...items];

  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }

  return result;
}

// Type definition for Transform
type Transform = (text: string) => string;

// Interface for pipeline step
interface PipelineStep {
  name: string;
  func: Transform;
}

// Individual transform functions
function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

// Pipeline class
class Pipeline {
  private steps: PipelineStep[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push({ name, func: step });
    return this;
  }

  run(text: string): string {
    return this.steps.reduce((result, step) => step.func(result), text);
  }

  names(): string[] {
    return this.steps.map(step => step.name);
  }

  toFunction(): Transform {
    return (text: string) => this.run(text);
  }
}

// Compose function
function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }
  return (text: string) => steps.reduce((result, step) => step(result), text);
}

// Export everything
export { Transform, trim, lowerCase, collapseSpaces, Pipeline, compose };

