enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

interface OpeningRule {
  day: Weekday,
  openHour: number,
  closeHour: number
}

function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  // Find all days with rules
  const daysWithRules: boolean[] = new Array(7).fill(false);
  for (let i = 0; i < rules.length; i++) {
    const rule = rules[i];
    daysWithRules[rule.day] = true;
  }

  // Start from the day after the given day
  let currentDay = (day + 1) % 7;

  // Check each subsequent day until we find one with a rule or we've checked all days
  while (currentDay !== day) {
    if (daysWithRules[currentDay]) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  // If we get here, no day has a rule, or the only day with a rule is the given day
  // Return undefined if no day has any rules, otherwise return the given day (which is one week later)
  for (let i = 0; i < 7; i++) {
    if (daysWithRules[i]) {
      return day;
    }
  }

  return undefined;
}

