interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    const position = i;

    if (/[0-9]/.test(char)) {
      let numStr = '';
      while (i < source.length && /[0-9]/.test(source[i])) {
        numStr += source[i];
        i++;
      }
      if (i < source.length && source[i] === '.') {
        numStr += '.';
        i++;
        if (i >= source.length || !/[0-9]/.test(source[i])) {
          throw new ExpressionError(`Unexpected character '${source[i]}'`, i);
        }
        while (i < source.length && /[0-9]/.test(source[i])) {
          numStr += source[i];
          i++;
        }
      }
      tokens.push({ kind: 'number', text: numStr, position });
    } else if (/[a-zA-Z_]/.test(char)) {
      let nameStr = '';
      while (i < source.length && /[a-zA-Z0-9_]/.test(source[i])) {
        nameStr += source[i];
        i++;
      }
      tokens.push({ kind: 'name', text: nameStr, position });
    } else if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({ kind: 'operator', text: char, position });
      i++;
    } else {
      throw new ExpressionError(`Unexpected character '${char}'`, position);
    }
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);

  if (tokens.length === 0) {
    throw new ExpressionError("Unexpected end of expression", source.length);
  }

  let pos = 0;
  let currentToken: Token | null = tokens[pos];

  function advance() {
    pos++;
    if (pos < tokens.length) {
      currentToken = tokens[pos];
    } else {
      currentToken = null;
    }
  }

  function peek(): Token | null {
    if (pos < tokens.length) {
      return tokens[pos];
    }
    return null;
  }

  function expect(kind: string, text?: string): Token {
    const token = peek();
    if (!token || token.kind !== kind || (text && token.text !== text)) {
      if (token) {
        throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
      } else {
        throw new ExpressionError("Unexpected end of expression", source.length);
      }
    }
    advance();
    return token;
  }

  function parseExpression(): number {
    return parseAdditive();
  }

  function parseAdditive(): number {
    let result = parseMultiplicative();

    while (currentToken && (currentToken.text === '+' || currentToken.text === '-')) {
      const op = currentToken.text;
      advance();
      const right = parseMultiplicative();

      if (op === '+') {
        result += right;
      } else {
        result -= right;
      }
    }

    return result;
  }

  function parseMultiplicative(): number {
    let result = parseUnary();

    while (currentToken && ['*', '/', '%'].includes(currentToken.text)) {
      const op = currentToken.text;
      advance();
      const right = parseUnary();

      if (op === '*') {
        result *= right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError("Division by zero", currentToken.position);
        }
        result /= right;
      } else if (op === '%') {
        if (right === 0) {
          throw new ExpressionError("Division by zero", currentToken.position);
        }
        result %= right;
      }
    }

    return result;
  }

  function parseUnary(): number {
    if (currentToken && currentToken.text === '-') {
      advance();
      return -parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    if (!currentToken) {
      throw new ExpressionError("Unexpected end of expression", source.length);
    }

    if (currentToken.kind === 'number') {
      const num = parseFloat(currentToken.text);
      advance();
      return num;
    }

    if (currentToken.kind === 'name') {
      const name = currentToken.text;
      let found = false;
      const keys = Object.keys(variables);
      for (let i = 0; i < keys.length; i++) {
        if (keys[i] === name) {
          found = true;
          break;
        }
      }
      if (!found) {
        throw new ExpressionError(`Unknown variable '${name}'`, currentToken.position);
      }
      advance();
      return variables[name];
    }

    if (currentToken.text === '(') {
      advance();
      const result = parseExpression();
      expect('paren', ')');
      return result;
    }

    throw new ExpressionError(`Unexpected token '${currentToken.text}'`, currentToken.position);
  }

  const result = parseExpression();

  if (currentToken) {
    throw new ExpressionError(`Unexpected token '${currentToken.text}'`, currentToken.position);
  }

  return result;
}

