import { http } from '@kit.NetworkKit'

interface Item {
  id: number
  name: string
}

interface HttpRequestOptions {
  url: string
  method: http.RequestMethod
}

@Entry
struct Solution {
  @State items: Array<Item> = []
  @State loading: boolean = false
  @State error: boolean = false

  aboutToAppear() {
    this.loadItems()
  }

  loadItems() {
    this.loading = true
    this.error = false

    const requestOptions: HttpRequestOptions = {
      url: 'https://example.com/api/items',
      method: http.RequestMethod.GET
    }

    const httpRequest = http.createHttp()
    httpRequest.request(requestOptions, (err, data) => {
      if (err) {
        this.error = true
        this.loading = false
        return
      }

      if (data.responseCode !== 200) {
        this.error = true
        this.loading = false
        return
      }

      try {
        const responseData = typeof data.result === 'string' ? data.result : ''
        const parsed = JSON.parse(responseData)
        if (Array.isArray(parsed)) {
          this.items = parsed
        } else {
          this.error = true
        }
      } catch (e) {
        this.error = true
      }
      this.loading = false
    })
  }

  build() {
    Column() {
      if (this.loading) {
        Text('Loading...')
          .fontSize(16)
      } else if (this.error) {
        Text('Could not load the items')
          .fontSize(16)
      } else {
        ForEach(this.items, (item) => {
          Text(item.name)
            .fontSize(16)
        }, (item) => item.id.toString())
      }
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    // Check for number
    if (/\d/.test(char)) {
      let j = i;
      while (j < source.length && /\d/.test(source[j])) {
        j++;
      }
      if (j < source.length && source[j] === '.') {
        if (j + 1 < source.length && /\d/.test(source[j + 1])) {
          j++;
          while (j < source.length && /\d/.test(source[j])) {
            j++;
          }
        } else {
          // Dot not followed by digit, not a number start in this context if we are strict, 
          // but spec says "A . is only part of a number when it has a digit on both sides".
          // So if we have "12.3", we consume "12", see ".", check next is digit.
          // If next is not digit, the dot is invalid? 
          // Re-reading: "A number is one or more digits, optionally followed by . and one or more digits"
          // This implies the pattern is \d+(\.\d+)?
          // And "A . is only part of a number when it has a digit on both sides" is a constraint on validity.
          // So "12." is invalid because no digit after. ".5" is invalid because no digit before.
          // My logic above: if we see digits, then a dot, we check if there is a digit after.
          // If not, we should treat the dot as an unexpected character? 
          // Actually, the spec says "A number is...". If the sequence doesn't match, it's not a number.
          // But we are parsing left to right.
          // Let's refine: 
          // If we start with digits, we consume them.
          // If next is '.', we consume it and MUST have digits after.
