function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  // Convert to AST or use recursive descent. 
  // Given the requirements, a recursive descent parser is suitable.
  // Grammar:
  // expr   -> term (('+' | '-') term)*
  // term   -> factor (('*' | '/' | '%') factor)*
  // factor -> '-' factor | number | name | '(' expr ')'
  // Note: Unary minus binds tighter than binary operators.
  // "A - where an operand is expected negates the operand that follows it... It binds tighter than every two-sided operator."
  // This means -x is parsed as a factor, not a binary op.
  // My grammar above handles this: factor -> '-' factor.

  let pos = 0;

  function peek(): Token | undefined {
    return tokens[pos];
  }

  function consume(): Token {
    if (pos >= tokens.length) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    return tokens[pos++];
  }

  function parseExpr(): number {
    let left = parseTerm();

    while (peek() && peek().kind === 'operator' && ['+', '-'].includes(peek().text)) {
      const op = consume();
      const right = parseTerm();
      if (op.text === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }
    return left;
  }

  function parseTerm(): number {
    let left = parseFactor();

    while (peek() && peek().kind === 'operator' && ['*', '/', '%'].includes(peek().text)) {
      const op = consume();
      const right = parseFactor();
      if (op.text === '*') {
        left = left * right;
      } else if (op.text === '/') {
        if (right === 0) throw new ExpressionError('Division by zero', op.position);
        left = left / right;
      } else { // %
        if (right === 0) throw new ExpressionError('Division by zero', op.position);
        left = left % right;
      }
    }
    return left;
  }

  function parseFactor(): number {
    const token = peek();

    // Handle unary minus
    if (token && token.kind === 'operator' && token.text === '-') {
      consume();
      return -parseFactor();
    }

    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      consume();
      const name = token.text;
      if (!(name in variables)) {
        throw new ExpressionError(`Unknown variable '${name}'`, token.position);
      }
      return variables[name];
    }

    if (token.kind === 'paren') {
      if (token.text === '(') {
        consume();
        const result = parseExpr();
        const close = consume();
        if (close.text !== ')') {
          throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
        }
        return result;
      } else {
        throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
      }
    }

    // If we are here, we have an operator or paren that is not '(' or a number/name/-
    // This is a syntax error in the context of an operand.
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpr();

  // Check for trailing tokens
  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private history: EditorState[] = [];
  private current: EditorState;
  private listeners: Map<string, Set<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();
  private historyLimit: number;

  constructor(initial: EditorState, historyLimit: number) {
    this.historyLimit = historyLimit;
    this.current = { ...initial };
  }

  get state(): EditorState {
    return { ...this.current };
  }

  apply(patch: Partial<EditorState>): boolean {
    const previousState = { ...this.current };
    let changed = false;

    if (patch.text !== undefined) {
      this.current.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined) {
      this.current.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined) {
      this.current.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.saveToHistory(previousState);
      this.notifyListeners(previousState, this.current);
      return true;
    }
    return false;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const previousState = { ...this.current };
    let draft: EditorState;

    try {
      draft = { ...this.current };
      run(draft);
    } catch (error) {
      this.current = previousState;
      throw error;
    }

    const changed = this.apply(draft);
    return changed;
  }

  undo(): boolean {
    if (this.history.length === 0) return false;

    const previousState = this.history.pop()!;
    this.current = previousState;
    this.notifyListeners(this.current, previousState);
    return true;
  }

  redo(): boolean {
    if (this.history.length === 0) return false;

    const nextState = this.history.pop()!;
    const previousState = { ...this.current };
    this.current = nextState;
    this.notifyListeners(this.current, previousState);
    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.history.length > 0;
  }

  private saveToHistory(previousState: EditorState) {
    // If we are at the limit, remove the oldest entry
    if (this.history.length >= this.historyLimit) {
      this.history.shift();
    }
    this.history.push(previousState);
  }

  private notifyListeners(current: EditorState, previous: EditorState) {
    for (const [field, listenerSet] of this.listeners.entries()) {
      const prevValue = previous[field];
      const currValue = current[field];

      if (prevValue !== currValue) {
        for (const listener of listenerSet) {
          listener(currValue, prevValue);
        }
      }
    }
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!['text', 'cursor', 'bold'].includes(field)) {
      throw new Error(`Invalid field: ${field}. Must be 'text', 'cursor', or 'bold'.`);
    }

    if (!this.listeners.has(field)) {
      this.listeners.set(field, new Set());
    }

    this.listeners.get(field)!.add(listener);

    return () => {
      const set = this.listeners.get(field);
      if (set) {
        set.delete(listener);
        if (set.size === 0) {
          this.listeners.delete(field);
        }
      }
    };
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'.`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
