import { router } from '@kit.ArkUI';

// Define the LogEntry class
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

// Define the Row component
@Entry
@Component
struct LogRow {
  @Prop entry: LogEntry;

  build() {
    Column() {
      Row() {
        Text(this.entry.message)
          .fontSize(16)
          .fontWeight(FontWeight.Medium)
        Spacer()
        Text(this.entry.level)
          .fontSize(14)
          .fontWeight(FontWeight.Normal)
          .fontColor(this.getLevelColor())
      }
      .width('100%')
      .padding({ left: 16, right: 16, top: 12, bottom: 12 })
      .backgroundColor('#F5F5F5')
    }
    .width('100%')
  }

  private getLevelColor(): Color {
    switch (this.entry.level) {
      case 'error':
        return '#D32F2F';
      case 'warning':
        return '#F57C00';
      case 'info':
      default:
        return '#757575';
    }
  }
}

// Define the main Page component
@Entry
@Component
struct SolutionPage {
  @State entries: LogEntry[] = [];
  @State isLoading: boolean = false;

  aboutToAppear() {
    // Create initial 3000 entries with ids 1 to 3000
    // Storing in reverse order so the highest id is first in the array
    // but we will sort them descending when building the list to ensure highest id first.
    // Actually, the requirement says "highest id first".
    // If we generate 1..3000, the highest is 3000.
    // Let's generate them and sort descending.
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
    // Sort descending by id
    this.entries.sort((a, b) => b.id - a.id);
  }

  build() {
    Column() {
      // Top text showing count
      Text(`${this.entries.length} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 16 })

      // Pull to refresh list
      List() {
        ForEach(this.entries, (entry: LogEntry, index: number) => {
          LogRow({ entry: entry })
        })
      }
      .pullRefresh({
        onRefresh: async () => {
          this.isLoading = true;
          // Simulate network delay
          await new Promise((resolve) => setTimeout(resolve, 1000));

          // Add 5 new entries
          const highestId = this.entries.length > 0 ? this.entries[0].id : 0;
          const newEntries: LogEntry[] = [];
          for (let i = 1; i <= 5; i++) {
            newEntries.push(new LogEntry(highestId + i));
          }

          // Insert at the top (beginning of the array)
          // Since the list is sorted descending, the new entries (highest ids) 
          // should be at the beginning.
          this.entries = [...newEntries, ...this.entries];

          // Re-sort just in case logic changes, though our generation logic ensures order
          this.entries.sort((a, b) => b.id - a.id);

          this.isLoading = false;
        }
      })
      .scrollBar({ visible: ScrollBarVisibility.Both })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

