// Define the Address data class
class Address {
  id: string;
  label: string;
  street: string;

  constructor(id: string, label: string, street: string) {
    this.id = id;
    this.label = label;
    this.street = street;
  }
}

// Define the Row component
// It reads the 'largeText' property from the page context (this)
// Note: In ArkTS Stage Model, accessing parent context directly like this 
// requires the component to be defined within the scope where the context is available 
// or passed via props. However, the prompt specifically asks for the row to read 
// it from the page by itself without passing it as a parameter to the second screen 
// or the row. This implies the Row component is defined inside the Page component 
// so it has access to the 'largeText' variable in its closure.
function AddressRow(address: Address) {
  return Column() {
    Row() {
      Text(address.label)
        .fontSize(16)
      Text(address.street)
        .fontSize(16)
      if (address.id === 'home') {
        Text('Current')
          .fontSize(16)
          .fontColor('#999999')
      }
    }
    .width('100%')
    .justifyContent(FlexAlign.SpaceBetween)
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .backgroundColor('#FFFFFF')
    .borderRadius(12)
    .onClick(() => {
      // Navigate back to the first screen and pass the selected address ID
      router.back({ data: { addressId: address.id } });
    })
  }
}

