    // If we returned from the second screen with a new address ID, update the selection
    if (this.addressIdFromSecondScreen) {
      this.selectedAddressId = this.addressIdFromSecondScreen;
    }
  }

  build() {
    Column() {
      // First Screen: Checkout
      if (this.selectedAddressId === 'home') {
        // Initial state or if we just returned without changing address
        this.buildCheckoutScreen();
      } else {
        // If we are here, it means we are on the first screen but the ID is not 'home'
        // This shouldn't happen based on logic unless we manually set it, 
        // but we handle the display of the current selected address regardless.
        this.buildCheckoutScreen();
      }
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  buildCheckoutScreen() {
    Column() {
      // Title Bar
      Text('Checkout')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, left: 16, right: 16 })

      // Deliver to section
      Column() {
        Text('Deliver to: ' + this.getChosenAddressLabel())
          .fontSize(18)
          .fontWeight(FontWeight.Medium)
          .margin({ bottom: 20 })
      }

      // Change Address Button
      Button('Change address')
        .width('100%')
        .height(50)
        .backgroundColor('#007DFF')
        .fontSize(16)
        .color('#FFFFFF')
        .borderRadius(25)
        .onClick(() => {
          // Push the second screen, passing the current selected address ID
          router.push({
            url: 'pages/Addresses',
            params: { addressId: this.selectedAddressId }
          });
        })
        .margin({ bottom: 40 })

      // Large Text Section
      Row() {
        Text('Large text')
          .fontSize(16)
        Switch()
          .width(50)
          .onChange((value: boolean) => {
            this.largeText = value;
          })
          .checked(this.largeText)
      }
      .margin({ bottom: 40 })
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }

  getChosenAddressLabel(): string {
    const address = this.addresses.find(a => a.id === this.selectedAddressId);
    return address ? address.label : '';
  }
}

