// --- Data Classes ---

class SizePreset {
  label: string;
  size: number;

  constructor(label: string, size: number) {
    this.label = label;
    this.size = size;
  }
}

// --- Global Settings ---

// App-wide settings. These are read by components and changed by the page.
// In a real app, these might be stored in a global state manager or ViewModel.
// Here we use simple variables to satisfy the requirement that they are app-wide.
let currentFontSize: number = 18;
let currentBold: boolean = false;
let changeCounter: number = 0;

// --- Components ---

// 1. Size Controls Component
@Component
struct SizeControls {
  @Builder
  build() {
    Column() {
      Row() {
        Button('A-') {
          onClick() {
            if (currentFontSize > 14) {
              currentFontSize -= 2;
            }
          }
        }
        .width('50%')
        .height('50%')

        Text(String(currentFontSize))
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .width('20%')
          .textAlign(TextAlign.Center)

        Button('A+') {
          onClick() {
            if (currentFontSize < 30) {
              currentFontSize += 2;
            }
          }
        }
        .width('50%')
        .height('50%')
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 10 })

      Row() {
        ForEach(SizePresets, (preset: SizePreset) => {
          Button(preset.label) {
            onClick() {
              currentFontSize = preset.size;
            }
          }
          .width('33%')
          .height('40px')
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
      .margin({ top: 10 })
    }
    .width('100%')
    .padding(10)
  }
}

// 2. Preview Component
