@Entry
struct SignInPage {
  @State email: string = ''
  @State password: string = ''
  @State emailValid: boolean = false
  @State passwordValid: boolean = false
  @State emailError: boolean = false
  @State passwordError: boolean = false

  build() {
    Column({ space: 20 }) {
      TextInput({ placeholder: 'Email' })
        .onChange((value: string) => {
          this.email = value
          this.validateEmail()
        })
        .width('80%')
        .type(InputType.Email)

      if (this.emailError) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor('#ff0000')
          .width('80%')
      }

      TextInput({ placeholder: 'Password' })
        .onChange((value: string) => {
          this.password = value
          this.validatePassword()
        })
        .width('80%')
        .type(InputType.Password)

      if (this.passwordError) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor('#ff0000')
          .width('80%')
      }

      Button('Sign in')
        .enabled(this.emailValid && this.passwordValid)
        .onClick(() => {
          console.info('Sign in pressed')
        })
        .width('80%')
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }

  validateEmail() {
    if (this.email === '') {
      this.emailValid = false
      this.emailError = false
      return
    }

    const emailRegex = /^[^@]+@[^@]+\.[^@]+$/
    const isValid = emailRegex.test(this.email)

    this.emailValid = isValid

    if (!isValid) {
      this.emailError = true
    } else {
      this.emailError = false
    }
  }

  validatePassword() {
    if (this.password === '') {
      this.passwordValid = false
      this.passwordError = false
      return
    }

    const isValid = this.password.length >= 8
    this.passwordValid = isValid

    if (!isValid) {
      this.passwordError = true
    } else {
      this.passwordError = false
    }
  }
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export type UserSettings = {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
};

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  return {
    theme: user.theme ?? defaults.theme,
    fontSize: user.fontSize ?? defaults.fontSize,
    notifications: user.notifications ?? defaults.notifications,
    language: user.language ?? defaults.language,
  };
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  if (expenses.length === 0) {
    return result;
  }

  for (const expense of expenses) {
    const currentAmount = result.get(expense.category) || 0;
    result.set(expense.category, currentAmount + expense.amount);
  }

  return result;
}

