export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY,
  };
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  if (!query || query.length === 0) {
    return result;
  }

  // Remove leading '?' if present
  let str = query;
  if (str.startsWith('?')) {
    str = str.substring(1);
  }

  if (str.length === 0) {
    return result;
  }

  // Split by '&'
  const parts = str.split('&');

  for (const part of parts) {
    // Skip empty parts (handles trailing & or &&)
    if (part.length === 0) {
      continue;
    }

    // Split at the first '='
    const eqIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found: key is the whole part, value is empty
      key = part;
      value = '';
    } else {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    // Ignore pairs with empty keys
    if (key.length === 0) {
      continue;
    }

    // Decode the value first (key is not decoded per typical URL query behavior, 
    // but the prompt says "Keys and values are decoded", so we decode both)
    const decodedKey = decodeURIComponentSafe(key);
    const decodedValue = decodeURIComponentSafe(value);

    // Set the value; if key exists, it updates the value but keeps the first position
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeURIComponentSafe(str: string): string {
  // Replace '+' with space first
  let result = str.replace(/\+/g, ' ');

  // Process percent-encoded sequences
  // We use a regex to find all %XX patterns. If XX is not a valid hex, we leave it as is.
  // We process from left to right to handle malformed sequences correctly.
  let i = 0;
  const len = result.length;
  let output = '';

  while (i < len) {
    if (result[i] === '%') {
      if (i + 2 < len) {
        const hex = result.substring(i + 1, i + 3);
        // Check if both characters are valid hex digits
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          try {
            // Decode the byte
            const byte = parseInt(hex, 16);
            // Convert byte to string (UTF-8)
            output += String.fromCharCode(byte);
            i += 3;
            continue;
          } catch (e) {
            // If parsing fails for some reason, treat as literal
          }
        }
      }
      // If not a valid hex sequence, keep the '%' and move on
      output += result[i];
      i++;
    } else {
      output += result[i];
      i++;
    }
  }

  return output;
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  try {
    const parsed = JSON.parse(json);
    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed.reduce((acc: User[], item) => {
      if (typeof item !== 'object' || item === null) {
        return acc;
      }

      const id = item.id;
      const name = item.name;
      const email = item.email;

      if (
        typeof id === 'number' &&
        Number.isInteger(id) &&
        typeof name === 'string' &&
        name.length > 0 &&
        typeof email === 'string' &&
        email.includes('@')
      ) {
        acc.push({ id, name, email });
      }

      return acc;
    }, []);
  } catch {
    return [];
  }
}

export class Stack<T> {
  private items: T[];
  private capacity: number;
  private count: number;

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be greater than 0");
    }
    this.capacity = capacity;
    this.items = new Array<T>(capacity);
    this.count = 0;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items[this.count] = item;
    this.count++;
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    this.count--;
    return this.items[this.count];
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.count - 1];
  }

  size(): number {
    return this.count;
  }

  isEmpty(): boolean {
    return this.count === 0;
  }

  isFull(): boolean {
    return this.count === this.capacity;
  }

  clear(): void {
    this.count = 0;
  }

  toArray(): T[] {
    return [...this.items.slice(0, this.count)];
  }
}

export interface Shape {
  type: 'circle' | 'rectangle' | 'triangle';
  radius?: number;
  width?: number;
  height?: number;
  base?: number;
}

export function circle(radius: number): Shape {
  return {
    type: 'circle',
    radius: radius
  };
}

export function rectangle(width: number, height: number): Shape {
  return {
    type: 'rectangle',
    width: width,
    height: height
  };
}

export function triangle(base: number, height: number): Shape {
  return {
    type: 'triangle',
    base: base,
    height: height
  };
}

export function area(shape: Shape): number {
  switch (shape.type) {
    case 'circle':
      return Math.PI * shape.radius! * shape.radius!;
    case 'rectangle':
      return shape.width! * shape.height!;
    case 'triangle':
      return shape.base! * shape.height! / 2;
    default:
      return 0;
  }
}

export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + area(shape), 0);
}

