export function formatDuration(totalSeconds: number): string {
  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);

  const hours = Math.floor(absSeconds / 3600);
  const remainingAfterHours = absSeconds % 3600;
  const minutes = Math.floor(remainingAfterHours / 60);
  const seconds = remainingAfterHours % 60;

  const parts: string[] = [];

  if (hours > 0) {
    parts.push(`${hours}h`);
  }
  if (minutes > 0) {
    parts.push(`${minutes}m`);
  }
  if (seconds > 0) {
    parts.push(`${seconds}s`);
  }

  // Handle the case where totalSeconds is 0
  if (parts.length === 0) {
    return "0s";
  }

  // Format parts: first as is, rest with two digits
  const formattedParts = parts.map((part, index) => {
    if (index === 0) {
      return part;
    }
    // Extract the number and unit
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) return part;
    const num = parseInt(match[1], 10);
    const unit = match[2];
    return `${num.toString().padStart(2, '0')}${unit}`;
  });

  const result = formattedParts.join(' ');

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  const trimmedText = text.trim();
  if (trimmedText === '') {
    return NaN;
  }

  // Check for leading minus sign
  let isNegative = false;
  let remainingText = trimmedText;

  if (remainingText.startsWith('-')) {
    isNegative = true;
    remainingText = remainingText.substring(1).trim();
    if (remainingText === '') {
      return NaN;
    }
  }

  // Split by single spaces
  const parts = remainingText.split(' ');

  // Validate that there are no empty parts (caused by multiple spaces or leading/trailing spaces)
  if (parts.some(p => p === '')) {
    return NaN;
  }

  const totalSeconds: number[] = [];

  for (const part of parts) {
    // Regex: one or more digits followed by h, m, or s
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    let secondsToAdd = 0;
    switch (unit) {
      case 'h':
        secondsToAdd = value * 3600;
        break;
      case 'm':
        secondsToAdd = value * 60;
        break;
      case 's':
        secondsToAdd = value;
        break;
    }

    totalSeconds.push(secondsToAdd);
  }

  const sum = totalSeconds.reduce((acc, curr) => acc + curr, 0);

  return isNegative ? -sum : sum;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  if (quantity <= 0) {
    return items.filter(item => item.id !== id);
  }

  return items.map(item => {
    if (item.id === id) {
      return { ...item, quantity };
    }
    return item;
  });
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let currentItems = items;

  for (const change of changes) {
    currentItems = updateQuantity(currentItems, change.id, change.quantity);
  }

  return currentItems;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Set<Listener<T>>> = new Map();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    const listeners = this.listeners.get(event)!;
    listeners.add(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const listeners = this.listeners.get(event);
    if (listeners) {
      listeners.delete(listener);
    }
  }

  emit(event: string, payload: T): number {
    const listeners = this.listeners.get(event);
    if (!listeners) {
      return 0;
    }

    let count = 0;
    for (const listener of listeners) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const listeners = this.listeners.get(event);
    return listeners ? listeners.size : 0;
  }
}

export type Pair<A, B> = {
  first: A;
  second: B;
};

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  let startIndex = 0;

  while (startIndex < items.length) {
    const endIndex = Math.min(startIndex + size, items.length);
    result.push(items.slice(startIndex, endIndex));
    startIndex = endIndex;
  }

  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    result.push({
      first: a[i],
      second: b[i],
    });
  }

  return result;
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error('Capacity must be at least 1');
    }
    this.capacity = capacity;
    this.map = new Map();
    this.order = [];
  }

  set(key: K, value: V): void {
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.map.set(key, value);
      this.order.splice(index, 1);
    } else {
      this.map.set(key, value);
    }
    this.order.push(key);

    if (this.order.length > this.capacity) {
      const lruKey = this.order.shift()!;
      this.map.delete(lruKey);
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
    }
    this.order.push(key);
    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    return [...this.order];
  }

  get size(): number {
    return this.map.size;
  }
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6,
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  if (rules.length === 0) {
    return undefined;
  }

  const hasRuleOnDay = (d: Weekday): boolean => {
    for (const rule of rules) {
      if (rule.day === d) {
        return true;
      }
    }
    return false;
  };

  const daysWithRules: Weekday[] = [];
  for (const rule of rules) {
    daysWithRules.push(rule.day);
  }

  // Check if the current day has a rule. If it does, we need to find the next occurrence of this day
  // or the next day with a rule.
  // The problem states: "day itself is never the first candidate. It is the last one: if it is the only day with a rule, the answer is day, one week later."
  // This implies we are looking for the next day in the sequence (day+1, day+2, ... Sunday, Monday, ...)
  // that has a rule. If we wrap around and hit the original 'day' again, that is the answer.
  // If we complete a full cycle without finding a rule, return undefined.

  let currentDay = (day + 1) % 7;

  // We need to search at most 7 days.
  // If the only day with a rule is 'day', then after checking day+1 to Sunday, we will check Monday (which is day if day was Sunday? No).
  // Let's trace:
  // If day = Monday (0). Next candidates: Tue, Wed, Thu, Fri, Sat, Sun, Mon.
  // If only Mon has a rule:
  // Check Tue (no), Wed (no), ..., Sun (no), Mon (yes). Return Mon.
  // So we iterate from (day + 1) % 7 up to 7 times.

  for (let i = 0; i < 7; i++) {
    if (hasRuleOnDay(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  return undefined;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

export class Pipeline {
  private steps: Array<{ name: string; step: Transform }> = [];

  add(name: string, step: Transform): this {
    this.steps.push({ name, step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const { step } of this.steps) {
      result = step(result);
    }
    return result;
  }

  names(): string[] {
    return [...this.steps.map(({ name }) => name)];
  }

  toFunction(): Transform {
    return (text: string) => this.run(text);
  }
}

export function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }
  return steps.reduce((acc, step) => (text: string) => step(acc(text)), (text: string) => text);
}

