@Entry
@Component
struct Solution {
  @State email: string = '';
  @State password: string = '';
  @State emailValid: boolean = false;
  @State passwordValid: boolean = false;

  aboutToAppear() {
    // Initial validation check
    this.checkEmail();
    this.checkPassword();
  }

  build() {
    Column() {
      // Email Input
      Column() {
        Input({ placeholder: 'Email' })
          .onChange((value: string) => {
            this.email = value;
            this.checkEmail();
          })
          .keyboardType('email')
          .placeholderColor('#999999')
          .fontSize(16)
          .width('100%')
          .height(40)
          .borderRadius(8)
          .backgroundColor('#FFFFFF')
          .borderWidth(1)
          .borderColor('#E0E0E0')
          .margin({ bottom: 16 });

        if (!this.emailValid && this.email.length > 0) {
          Text('Enter a valid email address')
            .fontSize(12)
            .color('#FF5252')
            .margin({ top: 4 });
        }
      }

      // Password Input
      Column() {
        Input({ placeholder: 'Password' })
          .onChange((value: string) => {
            this.password = value;
            this.checkPassword();
          })
          .keyboardType('password')
          .placeholderColor('#999999')
          .fontSize(16)
          .width('100%')
          .height(40)
          .borderRadius(8)
          .backgroundColor('#FFFFFF')
          .borderWidth(1)
          .borderColor('#E0E0E0')
          .margin({ bottom: 24 });

        if (!this.passwordValid && this.password.length > 0) {
          Text('Password must be at least 8 characters')
            .fontSize(12)
            .color('#FF5252')
            .margin({ top: 4 });
        }
      }

      // Sign In Button
      Button('Sign in')
        .width('100%')
        .height(50)
        .fontSize(16)
        .fontWeight(FontWeight.Bold)
        .backgroundColor(this.emailValid && this.passwordValid ? '#007AFF' : '#E0E0E0')
        .color('#FFFFFF')
        .borderRadius(25)
        .onClick(() => {
          if (this.emailValid && this.passwordValid) {
            console.log('Sign in clicked');
          }
        })
        .margin({ top: 16 });
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
    .backgroundColor('#F5F5F5');
  }

  private checkEmail(): void {
    if (this.email.length === 0) {
      this.emailValid = false;
      return;
    }

    const atIndex = this.email.indexOf('@');
    const dotIndex = this.email.indexOf('.');

    // Check for exactly one '@'
    if (atIndex === -1 || this.email.lastIndexOf('@') !== atIndex) {
      this.emailValid = false;
      return;
    }

    // Check for at least one character before '@'
    if (atIndex <= 0) {
      this.emailValid = false;
      return;
    }

    // Check for at least one character after '@' and before '.'
    if (dotIndex <= atIndex + 1) {
      this.emailValid = false;
      return;
    }

    // Check for at least one character after '.'
    if (dotIndex >= this.email.length - 1) {
      this.emailValid = false;
      return;
    }

    this.emailValid = true;
  }

  private checkPassword(): void {
    if (this.password.length === 0) {
      this.passwordValid = false;
      return;
    }

    this.passwordValid = this.password.length >= 8;
  }
}

