struct Solution {
  @State isLoading: boolean = true;
  @State items: Array<{ id: number; name: string }> = [];
  @State error: boolean = false;

  aboutToAppear() {
    this.fetchItems();
  }

  private async fetchItems() {
    try {
      const response = await common.http.get({
        url: 'https://example.com/api/items',
        method: 'GET',
      });

      if (response.statusCode === 200) {
        const data = response.data as Array<{ id: number; name: string }>;
        this.items = data;
      } else {
        throw new Error(`HTTP error! status: ${response.statusCode}`);
      }
    } catch (e) {
      console.error('Failed to fetch items:', e);
      this.error = true;
    } finally {
      this.isLoading = false;
    }
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 100 })
      } else if (this.error) {
        Text('Could not load the items')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 100 })
      } else if (this.items.length === 0) {
        Text('No items found')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 100 })
      } else {
        List({ space: 10 }) {
          ForEach(this.items, (item: { id: number; name: string }) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .fontWeight(FontWeight.Medium)
            }
          })
        }
        .width('100%')
        .height('100%')
      }
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < source.length && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      let numStr = source.substring(start, i);
      if (i < source.length && source[i] === '.') {
        if (i + 1 < source.length && source[i + 1] >= '0' && source[i + 1] <= '9') {
          i++;
          while (i < source.length && source[i] >= '0' && source[i] <= '9') {
            i++;
          }
          numStr += '.' + source.substring(start + 1, i);
        }
      }
      tokens.push({ kind: 'number', text: numStr, position: start });
      continue;
    }

    if ((char >= 'a' && char <= 'z') || (char >= 'A' && char <= 'Z') || char === '_') {
      let start = i;
      while (i < source.length && ((source[i] >= 'a' && source[i] <= 'z') || (source[i] >= 'A' && source[i] <= 'Z') || source[i] >= '0' && source[i] <= '9' || source[i] === '_')) {
        i++;
      }
      tokens.push({ kind: 'name', text: source.substring(start, i), position: start });
      continue;
    }

    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({ kind: 'operator', text: char, position: i });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({ kind: 'paren', text: char, position: i });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  const pos = 0;
  let currentPos = 0;

  function peek(): Token | undefined {
    return tokens[currentPos];
  }

  function consume(): Token {
    const token = tokens[currentPos];
    currentPos++;
    return token;
  }

  function expect(kind: string): void {
    const token = peek();
    if (!token || token.kind !== kind) {
      throw new ExpressionError(`Unexpected token '${token?.text}'`, token?.position ?? source.length);
    }
    consume();
  }

  function parseOperand(): number {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      consume();
      if (!(token.text in variables)) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return variables[token.text];
    }

    if (token.kind === 'operator' && token.text === '-') {
      consume();
      const value = parseOperand();
      return -value;
    }

    if (token.kind === 'paren' && token.text === '(') {
      consume();
      const value = parseExpression();
      expect(')');
      return value;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  function parseExpression(): number {
    let left = parseTerm();

    while (peek() && peek().kind === 'operator') {
      const opToken = consume();
      const op = opToken.text;

      if (op === '+' || op === '-') {
        const right = parseTerm();
        if (op === '+') {
          left = left + right;
        } else {
          left = left - right;
        }
      } else {
        throw new ExpressionError(`Unexpected token '${opToken.text}'`, opToken.position);
      }
    }

    return left;
  }

  function parseTerm(): number {
    let left = parseFactor();

    while (peek() && peek().kind === 'operator') {
      const opToken = consume();
      const op = opToken.text;

      if (op === '*' || op === '/' || op === '%') {
        const right = parseFactor();
        if (op === '*') {
          left = left * right;
        } else if (op === '/') {
          if (right === 0) {
            throw new ExpressionError('Division by zero', opToken.position);
          }
          left = left / right;
        } else if (op === '%') {
          if (right === 0) {
            throw new ExpressionError('Division by zero', opToken.position);
          }
          left = left % right;
        }
      } else {
        throw new ExpressionError(`Unexpected token '${opToken.text}'`, opToken.position);
      }
    }

    return left;
  }

  function parseFactor(): number {
    return parseOperand();
  }

  return parseExpression();
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private current: EditorState;
  private history: EditorState[];
  private future: EditorState[];
  private historyLimit: number;
  private listeners: Map<string, ((value: string | number | boolean, previous: string | number | boolean) => void)[]>;

  constructor(initial: EditorState, historyLimit: number) {
    this.current = { ...initial };
    this.history = [];
    this.future = [];
    this.historyLimit = historyLimit;
    this.listeners = new Map();
  }

  get state(): EditorState {
    return { ...this.current };
  }

  apply(patch: Partial<EditorState>): boolean {
    const previousState = { ...this.current };
    let changed = false;

    if (patch.text !== undefined) {
      this.current.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined) {
      this.current.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined) {
      this.current.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.history.push(previousState);
      if (this.history.length > this.historyLimit) {
        this.history.shift();
      }
      this.future = [];
      this.notifyListeners(previousState, this.current);
      return true;
    }
    return false;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const previousState = { ...this.current };
    const draft = { ...this.current };

    try {
      run(draft);
    } catch (e) {
      throw e;
    }

    const changed = this.apply(draft);
    if (changed) {
      this.history.push(previousState);
      if (this.history.length > this.historyLimit) {
        this.history.shift();
      }
      this.future = [];
    }

    return changed;
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const previousState = this.history.pop()!;
    this.current = previousState;
    this.future.push(this.current);
    this.notifyListeners(this.current, previousState);
    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    const nextState = this.future.shift()!;
    this.current = nextState;
    this.history.push(this.current);
    this.notifyListeners(this.current, nextState);
    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!['text', 'cursor', 'bold'].includes(field)) {
      throw new Error('Invalid field name');
    }

    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    this.listeners.get(field)!.push(listener);

    return () => {
      const list = this.listeners.get(field);
      if (list) {
        const index = list.indexOf(listener);
        if (index !== -1) {
          list.splice(index, 1);
        }
      }
    };
  }

  private notifyListeners(currentState: EditorState, previousState: EditorState): void {
    for (const [field, listeners] of this.listeners.entries()) {
      const currentValue = currentState[field];
      const previousValue = previousState[field];

      if (currentValue !== previousValue) {
        for (const listener of listeners) {
          listener(currentValue, previousValue);
        }
      }
    }
  }
}

export class MissingDependencyError extends Error {
  public task: string;
  public dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  public path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private taskList: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.taskList = Object.keys(spec);

    // Check for missing dependencies
    for (const task of this.taskList) {
      const dependencies = spec[task];
      for (const dep of dependencies) {
        if (!(dep in this.spec)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Check for cycles
    this.checkCycles();
  }

  private checkCycles(): void {
    const visited = new Set<string>();
    const recursionStack: string[] = [];

    const visit = (task: string): void => {
      if (recursionStack.includes(task)) {
        const cycleIndex = recursionStack.indexOf(task);
        const cyclePath = [...recursionStack.slice(cycleIndex), task];
        throw new CycleError(cyclePath);
      }

      if (visited.has(task)) {
        return;
      }

      visited.add(task);
      recursionStack.push(task);

      const dependencies = this.spec[task];
      for (const dep of dependencies) {
        visit(dep);
      }

      recursionStack.pop();
    };

    for (const task of this.taskList) {
      if (!visited.has(task)) {
        visit(task);
      }
    }
  }

  order(): string[] {
    const result: string[] = [];
    const placed = new Set<string>();

    const placeTask = (task: string): void => {
      if (placed.has(task)) {
        return;
      }

      const dependencies = this.spec[task];
      for (const dep of dependencies) {
        placeTask(dep);
      }

      result.push(task);
      placed.add(task);
    };

    for (const task of this.taskList) {
      placeTask(task);
    }

    return result;
  }

  layers(): string[][] {
    if (this.taskList.length === 0) {
      return [];
    }

    const order = this.order();
    const taskIndex = new Map<string, number>();
    for (let i = 0; i < order.length; i++) {
      taskIndex.set(order[i], i);
    }

    const layers: string[][] = [];
    const taskLayer = new Map<string, number>();

    for (const task of this.taskList) {
      const dependencies = this.spec[task];
      let maxDepLayer = -1;

      for (const dep of dependencies) {
        const depLayer = taskLayer.get(dep);
        if (depLayer !== undefined && depLayer > maxDepLayer) {
          maxDepLayer = depLayer;
        }
      }

      const layer = maxDepLayer + 1;
      taskLayer.set(task, layer);

      while (layers.length <= layer) {
        layers.push([]);
      }

      layers[layer].push(task);
    }

    // Sort tasks within each layer by key order (which is the order in taskList)
    for (const layer of layers) {
      layer.sort((a, b) => this.taskList.indexOf(a) - this.taskList.indexOf(b));
    }

    return layers;
  }

  dependentsOf(name: string): string[] {
    if (!(name in this.spec)) {
      return [];
    }

    const order = this.order();
    const result: string[] = [];

    for (const task of order) {
      if (task === name) {
        continue;
      }

      const dependencies = this.spec[task];
      for (const dep of dependencies) {
        if (dep === name) {
          result.push(task);
          break;
        }
      }
    }

    return result;
  }
}

interface JobOutcome<T> {
  ok: boolean
  value: T | undefined
  error: Error | undefined
}

class JobQueue {
  private concurrency: number
  private runningCount: number
  private waitingQueue: Array<() => Promise<unknown>>
  private completedCount: number
  private failedCount: number
  private paused: boolean
  private idlePromise: Promise<void> | null
  private idleResolve: (() => void) | null
  private runningJobs: Array<Promise<unknown>>

  constructor(concurrency: number) {
    this.concurrency = concurrency
    this.runningCount = 0
    this.waitingQueue = []
    this.completedCount = 0
    this.failedCount = 0
    this.paused = false
    this.idlePromise = null
    this.idleResolve = null
    this.runningJobs = []
  }

  private startNextJob(): void {
    if (this.paused || this.runningCount >= this.concurrency || this.waitingQueue.length === 0) {
      return
    }

    const job = this.waitingQueue.shift()
    if (job === undefined) {
      return
    }

    this.runningCount++
    const promise = job()
    this.runningJobs.push(promise)

    promise.then(
      (value) => {
        this.runningCount--
        this.completedCount++
        this.runningJobs = this.runningJobs.filter((p) => p !== promise)
        this.startNextJob()
      },
      (error) => {
        this.runningCount--
        this.failedCount++
        this.runningJobs = this.runningJobs.filter((p) => p !== promise)
        this.startNextJob()
      }
    )
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    this.waitingQueue.push(job)
    this.startNextJob()
    return job()
  }

  get running(): number {
    return this.runningCount
  }

  get waiting(): number {
    return this.waitingQueue.length
  }

  get completed(): number {
    return this.completedCount
  }

  get failed(): number {
    return this.failedCount
  }

  pause(): void {
    this.paused = true
  }

  resume(): void {
    this.paused = false
    this.startNextJob()
  }

  clear(): number {
    const removedCount = this.waitingQueue.length
    this.waitingQueue = []
    return removedCount
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingQueue.length === 0) {
      if (this.idleResolve === null) {
        this.idleResolve = () => {}
        this.idlePromise = Promise.resolve()
      }
      return this.idlePromise
    }

    if (this.idleResolve === null) {
      this.idleResolve = () => {}
      this.idlePromise = new Promise((resolve) => {
        this.idleResolve = resolve
      })
    }

    const checkIdle = (): void => {
      if (this.runningCount === 0 && this.waitingQueue.length === 0) {
        if (this.idleResolve !== null) {
          this.idleResolve()
          this.idleResolve = null
          this.idlePromise = Promise.resolve()
        }
      }
    }

    const interval = setInterval(checkIdle, 10)

    const clearInterval = (): void => {
      clearInterval(interval)
    }

    this.idlePromise.then(clearInterval)
    this.idlePromise.catch(clearInterval)

    return this.idlePromise
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = []
    const results = new Array<T | undefined | null>(jobs.length)

    for (let i = 0; i < jobs.length; i++) {
      const job = jobs[i]
      this.add(job)
    }

    const checkAllSettled = (): void => {
      if (this.runningCount === 0 && this.waitingQueue.length === 0) {
        const finalOutcomes: JobOutcome<T>[] = []

        for (let i = 0; i < results.length; i++) {
          const result = results[i]
          if (result === null) {
            finalOutcomes.push({
              ok: false,
              value: undefined,
              error: new Error('Job was cancelled')
            })
          } else if (result instanceof Error) {
            finalOutcomes.push({
              ok: false,
              value: undefined,
              error: result
            })
          } else {
            finalOutcomes.push({
              ok: true,
              value: result,
              error: undefined
            })
          }
        }

        Promise.resolve().then(() => {
          resolveOutcomes(finalOutcomes)
        })
      }
    }

    let resolveOutcomes: (outcomes: JobOutcome<T>[]) => void

    const promise = new Promise<JobOutcome<T>[]>((resolve) => {
      resolveOutcomes = resolve
    })

    const interval = setInterval(checkAllSettled, 10)

    const clearInterval = (): void => {
      clearInterval(interval)
    }

    promise.then(clearInterval)
    promise.catch(clearInterval)

    return promise
  }
}

enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
}

class OrderLine {
  sku: string
  quantity: number
  unitPrice: number

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku
    this.quantity = quantity
    this.unitPrice = unitPrice
  }

  total(): number {
    return this.quantity * this.unitPrice
  }
}

interface Order {
  id: string
  status: OrderStatus
  lines: OrderLine[]
}

interface FieldError {
  path: string
  message: string
}

interface ParseResult {
  order: Order | undefined
  errors: FieldError[]
}

function parseOrder(text: string): ParseResult {
  const errors: FieldError[] = []
  let order: Order | undefined = undefined

  try {
    const raw = JSON.parse(text)

    if (typeof raw !== 'object' || raw === null) {
      errors.push({ path: '', message: 'expected an object' })
      return { order: undefined, errors }
    }

    const orderObj: any = raw
    const linesArr: any[] = []

    // Check id
    if (!('id' in orderObj) || orderObj.id === null) {
      errors.push({ path: 'id', message: 'required' })
    } else if (typeof orderObj.id !== 'string') {
      errors.push({ path: 'id', message: 'expected a string' })
    } else if (orderObj.id === '') {
      errors.push({ path: 'id', message: 'must not be empty' })
    }

    // Check status
    if (!('status' in orderObj) || orderObj.status === null) {
      orderObj.status = OrderStatus.Draft
    } else if (typeof orderObj.status !== 'string') {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' })
    } else if (orderObj.status !== 'draft' && orderObj.status !== 'paid' && orderObj.status !== 'shipped') {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' })
    }

    // Check lines
    if (!('lines' in orderObj) || orderObj.lines === null) {
      errors.push({ path: 'lines', message: 'required' })
    } else if (!Array.isArray(orderObj.lines)) {
      errors.push({ path: 'lines', message: 'expected an array' })
    } else if (orderObj.lines.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' })
    } else {
      for (let i = 0; i < orderObj.lines.length; i++) {
        const lineObj = orderObj.lines[i]
        const linePath = `lines[${i}]`

        if (typeof lineObj !== 'object' || lineObj === null) {
          errors.push({ path: linePath, message: 'expected an object' })
          continue
        }

        // Check sku
        if (!('sku' in lineObj) || lineObj.sku === null) {
          errors.push({ path: `${linePath}.sku`, message: 'required' })
        } else if (typeof lineObj.sku !== 'string') {
          errors.push({ path: `${linePath}.sku`, message: 'expected a string' })
        } else if (lineObj.sku === '') {
          errors.push({ path: `${linePath}.sku`, message: 'must not be empty' })
        }

        // Check quantity
        if (!('quantity' in lineObj) || lineObj.quantity === null) {
          errors.push({ path: `${linePath}.quantity`, message: 'required' })
        } else if (typeof lineObj.quantity !== 'number') {
          errors.push({ path: `${linePath}.quantity`, message: 'expected a number' })
        } else if (!Number.isInteger(lineObj.quantity) || lineObj.quantity < 1) {
          errors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' })
        }

        // Check unitPrice
        if (!('unitPrice' in lineObj) || lineObj.unitPrice === null) {
          errors.push({ path: `${linePath}.unitPrice`, message: 'required' })
        } else if (typeof lineObj.unitPrice !== 'number') {
          errors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' })
        } else if (lineObj.unitPrice < 0) {
          errors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' })
        }

        // Check unknown fields in line
        const knownLineFields = ['sku', 'quantity', 'unitPrice']
        for (const key of Object.keys(lineObj)) {
          if (!knownLineFields.includes(key)) {
            errors.push({ path: `${linePath}.${key}`, message: 'unknown field' })
          }
        }
      }
    }

    // Check unknown fields in order
    const knownOrderFields = ['id', 'status', 'lines']
    for (const key of Object.keys(orderObj)) {
      if (!knownOrderFields.includes(key)) {
        errors.push({ path: key, message: 'unknown field' })
      }
    }

    if (errors.length === 0) {
      const lines: OrderLine[] = []
      for (const lineObj of orderObj.lines) {
        lines.push(new OrderLine(lineObj.sku, lineObj.quantity, lineObj.unitPrice))
      }
      order = {
        id: orderObj.id,
        status: orderObj.status as OrderStatus,
        lines: lines,
      }
    }

  } catch (e) {
    errors.push({ path: '', message: 'invalid JSON' })
  }

  return { order, errors }
}

