// Define the LogEntry class with three fields: id, message, and level.
// No destructuring, no object literals without types, no index signatures.
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

// Define the Row component for displaying a single log entry.
// It is a struct with @Component and a build() method.
// No nested functions, no function expressions, no 'this' in standalone functions.
@Component
struct LogRow {
  @ObjectLink entry: LogEntry;

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontColor(Color.Black)
      Text(this.entry.level)
        .fontSize(14)
        .fontColor(this.getColorForLevel(this.entry.level))
        .padding({ left: 8 })
    }
    .width('100%')
    .padding({ top: 8, bottom: 8, left: 16, right: 16 })
    .backgroundColor(Color.White)
  }

  // Helper method to return the correct color based on the level.
  // Methods cannot be reassigned on an object.
  getColorForLevel(level: string): Color {
    if (level === 'error') {
      return Color('#D32F2F');
    } else if (level === 'warning') {
      return Color('#F57C00');
    } else {
      return Color('#757575');
    }
  }
}

// Define the main page component.
// It is a struct with @Entry and a build() method.
// State is declared as fields with decorators.
@Entry
@Component
struct MainPage {
  @State entries: LogEntry[] = [];
  @State highestId: number = 0;
  @State isLoading: boolean = false;

  aboutToAppear() {
    // Create 3000 entries at the start with ids 1 to 3000.
    // No network or file loading.
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
    this.highestId = 3000;
  }

  // Lifecycle method to handle pull-to-refresh.
  onPageShow() {
    // No need to do anything specific here, but good practice to ensure state is ready.
  }

  // Lifecycle method to clean up if needed.
  aboutToDisappear() {
    // No cleanup required for this simple example.
  }

  build() {
    Column() {
      // Top text showing the number of entries.
      Text(`${this.entries.length} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 16 })

      // Scrolling list of all entries, highest id first.
      // Uses LazyForEach to build rows only as they scroll into view.
      // No .map() to produce components, no local variables in build().
      List() {
        LazyForEach(this.entries, (entry: LogEntry) => {
          LogRow() {
            this.entry = entry;
          }
        }, (entry: LogEntry) => entry.id)
      }
      .refreshControl(() => {
        return RefreshControl({
          onRefresh: () => {
            this.isLoading = true;
            // Simulate a network delay of 1 second.
            setTimeout(() => {
              this.addNewEntries();
              this.isLoading = false;
            }, 1000);
          },
        });
      })
      .enablePullToRefresh(true)
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }

  // Method to add five new entries at the top of the list.
  // No function expressions, no nested functions.
  addNewEntries() {
    const newEntries: LogEntry[] = [];
    for (let i = 0; i < 5; i++) {
      const id = this.highestId + 1 + i;
      newEntries.push(new LogEntry(id));
    }
    // Add new entries at the top of the list.
    this.entries = newEntries.concat(this.entries);
    this.highestId = this.highestId + 5;
  }
}

