// Define the interface for the settings
interface ReadingSettings {
  textSize: number;
  bold: boolean;
}

// Initialize default settings in AppStorage
const defaultSettings: ReadingSettings = {
  textSize: 18,
  bold: false,
};

// We use a class to hold the state so it can be observed by components
// Note: In a real app, we might use a singleton or a service, but for this 
// single-file constraint, we define the storage key and access it via AppStorage.
// However, ArkUI's AppStorage works with primitives or simple objects. 
// To ensure reactivity across components, we will store the settings in a 
// global variable that is updated via AppStorage, or simply use AppStorage 
// directly if the components can read it. 
// Since the requirement says "a component on any page... can read and change them",
// we will use AppStorage for the global state.

const TEXT_SIZE_KEY = 'reading_text_size';
const BOLD_KEY = 'reading_bold';

// Helper to get current settings
function getSettings(): ReadingSettings {
  const size = AppStorage.get<number>(TEXT_SIZE_KEY, defaultSettings.textSize);
  const bold = AppStorage.get<boolean>(BOLD_KEY, defaultSettings.bold);
  return { textSize: size, bold };
}

// Helper to update settings
function updateSettings(updates: Partial<ReadingSettings>) {
  if (updates.textSize !== undefined) {
    AppStorage.set(TEXT_SIZE_KEY, updates.textSize);
  }
  if (updates.bold !== undefined) {
    AppStorage.set(BOLD_KEY, updates.bold);
  }
}

// --- Components ---

// 1. Size Controls Component
struct SizeControls {
  build() {
    Column() {
      Row() {
        Button('A-') {
          onClick(() => {
            const current = getSettings();
            const newSize = Math.max(14, current.textSize - 2);
            updateSettings({ textSize: newSize });
          })
        }
        .width('100%')
        .height('100%')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)

        Text(getSettings().textSize.toString())
          .fontSize(20)
          .fontWeight(FontWeight.Bold)
          .margin({ left: 10, right: 10 })

        Button('A+') {
          onClick(() => {
            const current = getSettings();
            const newSize = Math.min(30, current.textSize + 2);
            updateSettings({ textSize: newSize });
          })
        }
        .width('100%')
        .height('100%')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)

      Row() {
        ForEach(SizePresets, (preset: SizePreset) => {
          Button(preset.label) {
            onClick(() => {
              updateSettings({ textSize: preset.size });
            })
          }
          .fontSize(16)
          .width('33%')
        })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceEvenly)
