      .fontSize(getSettings().textSize)
      .fontWeight(getSettings().bold ? FontWeight.Bold : FontWeight.Normal)
      .animation('smoothScale', {
        duration: 300,
        curve: Curve.EaseInOut
      })
      .width('100%')
