// 3. Change Counter Component
struct ChangeCounter {
  private count: number = 0;

  build() {
    Text('Changed ' + this.count.toString() + ' times')
      .fontSize(16)
      .fontWeight(FontWeight.Normal)
      .width('100%')
      .textAlign(TextAlign.Center)
      .margin({ top: 20 })
      .onAppear(() => {
        // Initialize count to 0 on creation
        this.count = 0;
      })
      .onChange(() => {
        // This block runs when the component is redrawn due to state change
        // We need to detect if the text size actually changed.
        // Since we can't easily hook into the AppStorage change event from here 
        // without a complex observer pattern, we rely on the fact that 
        // the parent page will trigger a redraw if we pass a callback, 
        // but the requirement says "reads or changes the settings by itself".
        // 
        // To satisfy "Every time the text size changes... the number goes up",
        // we must observe the global state. However, ArkUI components don't 
        // natively observe AppStorage changes to trigger their own internal logic 
        // unless we use a specific pattern.
        // 
        // Given the constraints, the most robust way in a single file without 
        // external observers is to have the component check the current value 
        // on every render and compare it to a stored "last known" value.
        // But the requirement says "This component has no buttons and never changes a setting."
        // It implies it is passive.
        // 
        // Let's implement a simple observer pattern using a local variable 
        // that we update when we detect a change. But how do we detect?
        // We can't.
        // 
        // Alternative interpretation: The component is part of the page. 
        // The page updates the global state. The component reads the global state.
        // But the counter must increment.
        // 
        // Let's assume the component can access the global state and we will 
        // implement a simple check. Since we cannot use `@StorageLink` for 
        // complex logic easily in a struct without a reference, we will use 
        // a workaround: The component will read the current value. 
        // To make it work as requested ("reads... by itself"), we will assume 
        // the component is re-rendered when the setting changes.
        // We will store the last seen size in a private field.

        const currentSize = getSettings().textSize;
        if (currentSize !== this.lastKnownSize) {
          this.count++;
          this.lastKnownSize = currentSize;
        }
      })
  }

  private lastKnownSize: number = 0;
}

