export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();
  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const category = expense.category;
    const amount = expense.amount;
    if (!result.has(category)) {
      result.set(category, 0);
    }
    result.set(category, result.get(category)! + amount);
  }
  return result;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const result: Settings = {
    theme: defaults.theme,
    fontSize: defaults.fontSize,
    notifications: defaults.notifications,
    language: defaults.language,
  };

  if (user.theme !== undefined) {
    result.theme = user.theme;
  }
  if (user.fontSize !== undefined) {
    result.fontSize = user.fontSize;
  }
  if (user.notifications !== undefined) {
    result.notifications = user.notifications;
  }
  if (user.language !== undefined) {
    result.language = user.language;
  }

  return result;
}

