@Entry
@Component
struct GoalDialog {
  @Prop callback onSave: (value: number) => void;
  @Prop cancelOnClose: boolean = true;

  @State inputText: string = '';
  @State showPresetButtons: boolean = true;

  aboutToAppear() {
    // Focus the input field when the dialog opens
    // Note: In ArkTS Stage Model, direct focus manipulation often requires 
    // specific lifecycle handling or is handled by the system for modals.
    // We rely on the system to focus the first editable field if possible,
    // or the user will tap it.
  }

  build() {
    Column() {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 16 })

      // Input field
      Input()
        .placeholder('Glasses per day')
        .text(this.inputText)
        .onChange((value: string) => {
          this.inputText = value;
        })
        .width('100%')
        .margin({ bottom: 16 })

      // Quick choices
      if (this.showPresetButtons) {
        Column() {
          ForEach([new GoalPreset('Light', 6), new GoalPreset('Standard', 8), new GoalPreset('Active', 12)], (preset: GoalPreset) => {
            return Column() {
              Button(preset.label)
                .width('100%')
                .onClick(() => {
                  this.inputText = preset.glasses.toString();
                  this.showPresetButtons = false;
                })
            }
          })
        }
        .margin({ bottom: 16 })
      }

      // Action buttons
      Row() {
        Button('Cancel')
          .width('50%')
          .onClick(() => {
            this.onCancel();
          })

        Button('Save')
          .width('50%')
          .onClick(() => {
            this.onSave();
          })
      }
    }
    .width('300px')
    .height('auto')
    .padding(16)
    .backgroundColor('#FFFFFF')
    .borderRadius(12)
    .shadow({ color: Color.Gray.opacity(0.1), radius: 8, offsetX: 0, offsetY: 4 })
  }

  private onCancel() {
    if (this.cancelOnClose) {
      router.back();
    }
  }

  private onSave() {
    const value = parseInt(this.inputText);
    if (!isNaN(value) && value >= 1) {
      this.onSave(value);
      router.back();
    }
  }
}

