function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map();

  if (query.length === 0) {
    return result;
  }

  // Remove leading '?' if present
  let currentQuery = query;
  if (currentQuery.startsWith('?')) {
    currentQuery = currentQuery.substring(1);
  }

  // Split by '&'
  const parts = currentQuery.split('&');

  for (const part of parts) {
    // Skip empty parts
    if (part.length === 0) {
      continue;
    }

    // Split at the first '='
    const eqIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found: key is the whole part, value is empty
      key = part;
      value = '';
    } else {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeURIComponentSafe(key);
    const decodedValue = decodeURIComponentSafe(value);

    // Add to map (last value wins, but key keeps first position)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeURIComponentSafe(str: string): string {
  let result = str.replace(/\+/g, ' ');

  // Find all %XX sequences
  let i = 0;
  while (i < result.length) {
    if (result[i] === '%') {
      if (i + 2 < result.length) {
        const hex = result.substring(i + 1, i + 3);
        // Check if hex is valid (0-9, A-F, a-f)
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          try {
            const byte = parseInt(hex, 16);
            result = result.substring(0, i) + String.fromCharCode(byte) + result.substring(i + 3);
          } catch (e) {
            // If parsing fails for some reason, keep as is
          }
        }
        // If invalid hex, we do nothing and keep the '%' and the two chars as they are
      }
      i++;
    } else {
      i++;
    }
  }

  return result;
}

export interface Point {
  x: number
  y: number
}

export interface Box {
  min: Point
  max: Point
  width: number
  height: number
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined
  }

  let minX = points[0].x
  let minY = points[0].y
  let maxX = points[0].x
  let maxY = points[0].y

  for (let i = 1; i < points.length; i++) {
    const p = points[i]
    if (p.x < minX) {
      minX = p.x
    }
    if (p.y < minY) {
      minY = p.y
    }
    if (p.x > maxX) {
      maxX = p.x
    }
    if (p.y > maxY) {
      maxY = p.y
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Set<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const set = this.listeners.get(event);
    if (set) {
      set.delete(listener);
      if (set.size === 0) {
        this.listeners.delete(event);
      }
    }
  }

  emit(event: string, payload: T): number {
    const set = this.listeners.get(event);
    if (!set) {
      return 0;
    }
    let count = 0;
    for (const listener of set) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const set = this.listeners.get(event);
    return set ? set.size : 0;
  }
}

