export class RetryError extends Error {
  attempts: number
  lastError: Error

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`)
    this.attempts = attempts
    this.lastError = lastError
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const effectiveAttempts = attempts < 1 ? 1 : attempts
  let currentAttempt = 0
  let lastError: Error | undefined

  while (currentAttempt < effectiveAttempts) {
    try {
      return await action()
    } catch (e) {
      currentAttempt++
      if (e instanceof Error) {
        lastError = e
      } else {
        lastError = new Error(String(e))
      }
    }
  }

  throw new RetryError(currentAttempt, lastError!)
}

export function formatDuration(totalSeconds: number): string {
  let sign = ''
  if (totalSeconds < 0) {
    sign = '-'
    totalSeconds = -totalSeconds
  }

  const hours = Math.floor(totalSeconds / 3600)
  const remainingAfterHours = totalSeconds % 3600
  const minutes = Math.floor(remainingAfterHours / 60)
  const seconds = remainingAfterHours % 60

  const parts: string[] = []

  if (hours > 0) {
    parts.push(String(hours) + 'h')
  }
  parts.push(String(minutes).padStart(2, '0') + 'm')
  parts.push(String(seconds).padStart(2, '0') + 's')

  return sign + parts.join(' ')
}

export function parseDuration(text: string): number {
  if (text === '') {
    return NaN
  }

  const trimmed = text.trim()
  if (trimmed === '') {
    return NaN
  }

  const parts = trimmed.split(' ')
  if (parts.length === 0) {
    return NaN
  }

  let hasLeadingMinus = false
  if (parts[0] === '-') {
    hasLeadingMinus = true
    parts.shift()
  }

  if (parts.length === 0) {
    return NaN
  }

  let totalSeconds = 0
  let valid = true

  for (const part of parts) {
    if (part === '') {
      valid = false
      break
    }

    const match = part.match(/^(\d+)([hms])$/)
    if (!match) {
      valid = false
      break
    }

    const value = parseInt(match[1], 10)
    const unit = match[2]

    switch (unit) {
      case 'h':
        totalSeconds += value * 3600
        break
      case 'm':
        totalSeconds += value * 60
        break
      case 's':
        totalSeconds += value
        break
    }
  }

  if (!valid) {
    return NaN
  }

  if (hasLeadingMinus) {
    totalSeconds = -totalSeconds
  }

  return totalSeconds
}

export class Stack<T> {
  private items: T[]
  private capacity: number
  private size: number

  constructor(capacity: number) {
    this.capacity = capacity
    this.items = []
    this.size = 0
  }

  push(item: T): boolean {
    if (this.size >= this.capacity) {
      return false
    }
    this.items.push(item)
    this.size++
    return true
  }

  pop(): T | undefined {
    if (this.size === 0) {
      return undefined
    }
    const item = this.items.pop()
    this.size--
    return item
  }

  peek(): T | undefined {
    if (this.size === 0) {
      return undefined
    }
    return this.items[this.size - 1]
  }

  size(): number {
    return this.size
  }

  isEmpty(): boolean {
    return this.size === 0
  }

  isFull(): boolean {
    return this.size >= this.capacity
  }

  clear(): void {
    this.items = []
    this.size = 0
  }

  toArray(): T[] {
    return [...this.items]
  }
}

interface User {
