  email: string
}

function parseUsers(json: string): User[] {
  let result: User[] = []

  try {
    const parsed = JSON.parse(json)

    if (Array.isArray(parsed)) {
      for (let i = 0; i < parsed.length; i++) {
        const item = parsed[i]

        if (item === null || typeof item !== 'object') {
          continue
        }

        const id = item.id
        const name = item.name
        const email = item.email

        if (
          typeof id === 'number' &&
          Number.isInteger(id) &&
          typeof name === 'string' &&
          name.length > 0 &&
          typeof email === 'string' &&
          email.includes('@')
        ) {
