            name: name,
            email: email
          })
        }
      }
    }
  } catch {
    // Invalid JSON, return empty array
  }

  return result
}

interface CacheEntry<K, V> {
  key: K
  value: V
}

class LruCache<K, V> {
  private capacity: number
  private entries: Map<K, CacheEntry<K, V>>
  private order: K[]

  constructor(capacity: number) {
    this.capacity = capacity
    this.entries = new Map<K, CacheEntry<K, V>>()
    this.order = []
  }

  set(key: K, value: V): void {
    const existingEntry = this.entries.get(key)
    if (existingEntry) {
      existingEntry.value = value
      const index = this.order.indexOf(key)
      if (index !== -1) {
        this.order.splice(index, 1)
      }
    } else {
      const entry: CacheEntry<K, V> = { key, value }
      this.entries.set(key, entry)
      this.order.push(key)
    }

    while (this.entries.size > this.capacity) {
      const lruKey = this.order.shift()
      if (lruKey !== undefined) {
        this.entries.delete(lruKey)
      }
    }
  }

  get(key: K): V | undefined {
    const entry = this.entries.get(key)
    if (entry) {
      const index = this.order.indexOf(key)
      if (index !== -1) {
        this.order.splice(index, 1)
        this.order.push(key)
      }
      return entry.value
    }
    return undefined
  }

  has(key: K): boolean {
    return this.entries.has(key)
  }

  keys(): K[] {
    return [...this.order]
  }

  get size(): number {
    return this.entries.size
  }
}

enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

interface OpeningRule {
  day: Weekday
  openHour: number
  closeHour: number
}

function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true
    }
  }
  return false
}

function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  if (rules.length === 0) {
    return undefined
  }

  const hasRuleOnDay = (d: Weekday): boolean => {
    for (const rule of rules) {
      if (rule.day === d) {
        return true
      }
    }
    return false
  }

  const currentDayIndex = day
  const nextDayIndex = (currentDayIndex + 1) % 7

  if (hasRuleOnDay(nextDayIndex)) {
    return nextDayIndex
  }

  for (let i = 1; i < 7; i++) {
    const candidateDayIndex = (nextDayIndex + i) % 7
    if (hasRuleOnDay(candidateDayIndex)) {
      return candidateDayIndex
    }
  }

  return undefined
}

interface Pair<A, B> {
  first: A
  second: B
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return []
  }

  const result: T[][] = []
  let index = 0

  while (index < items.length) {
    const end = index + size
    const chunk: T[] = []
    let i = index
    while (i < end && i < items.length) {
      chunk.push(items[i])
      i++
    }
    result.push(chunk)
    index = end
  }

  return result
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = a.length < b.length ? a.length : b.length
  const result: Pair<A, B>[] = []

  let i = 0
  while (i < minLength) {
    result.push({
      first: a[i],
      second: b[i]
    })
    i++
  }

  return result
}

