export interface Item {
  id: string
  name: string
  quantity: number
}

export interface Change {
  id: string
  quantity: number
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = []
  for (let i = 0; i < items.length; i++) {
    const item = items[i]
    if (item.id === id) {
      if (quantity <= 0) {
        continue
      }
      result.push({ id: item.id, name: item.name, quantity: quantity })
    } else {
      result.push(item)
    }
  }
  return result
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let currentItems: Item[] = []
  for (let i = 0; i < items.length; i++) {
    currentItems.push(items[i])
  }

  for (let j = 0; j < changes.length; j++) {
    currentItems = updateQuantity(currentItems, changes[j].id, changes[j].quantity)
  }

  return currentItems
}

