          .text(this.email)
          .onChange((value: string) => {
            this.email = value;
            this.validateEmail();
          })
          .inputType(InputType.Email)

        if (!this.emailValid && this.email.length > 0) {
          Text('Enter a valid email address')
            .fontSize(14)
            .fontColor(Color.Gray)
            .margin({ bottom: 10 })
        }
      }

      Column() {
        TextInput({ placeholder: 'Password' })
          .text(this.password)
          .onChange((value: string) => {
            this.password = value;
            this.validatePassword();
          })
          .inputType(InputType.Password)

        if (!this.passwordValid && this.password.length > 0) {
          Text('Password must be at least 8 characters')
            .fontSize(14)
            .fontColor(Color.Gray)
            .margin({ bottom: 10 })
        }
      }

      Button('Sign in')
        .width('100%')
        .height(50)
        .fontSize(16)
        .fontWeight(FontWeight.Bold)
        .backgroundColor(Color.Blue)
        .disabled(!this.emailValid || !this.passwordValid)
        .onClick(() => {
          console.log('Sign in clicked');
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(20)
  }

  private validateEmail(): void {
    const atIndex = this.email.indexOf('@');
    const dotIndex = this.email.indexOf('.');

    if (atIndex === -1 || dotIndex === -1) {
      this.emailValid = false;
      return;
    }

    const beforeAt = this.email.substring(0, atIndex);
    const afterAt = this.email.substring(atIndex + 1);

    const dotInHost = afterAt.indexOf('.');
    const hostPart = afterAt.substring(0, dotInHost);
    const tldPart = afterAt.substring(dotInHost + 1);

    this.emailValid =
      beforeAt.length > 0 &&
      hostPart.length > 0 &&
      tldPart.length > 0;
  }

  private validatePassword(): void {
    this.passwordValid = this.password.length >= 8;
  }
}

