export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private history: EditorState[] = [];
  private current: EditorState;
  private listeners: Map<string, Set<(value: string | number | boolean, previous: string | number | boolean) => void>> = new Map();
  private historyLimit: number;

  constructor(initial: EditorState, historyLimit: number) {
    this.historyLimit = historyLimit;
    this.current = { ...initial };
  }

  get state(): EditorState {
    return { ...this.current };
  }

  apply(patch: Partial<EditorState>): boolean {
    const previousState = { ...this.current };
    let changed = false;

    if (patch.text !== undefined) {
      this.current.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined) {
      this.current.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined) {
      this.current.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.saveToHistory(previousState);
      this.notifyListeners(previousState, this.current);
      return true;
    }
    return false;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const previousState = { ...this.current };
    const draft = { ...this.current };

    try {
      run(draft);
      const changed = this.apply(draft);
      if (changed) {
        this.saveToHistory(previousState);
        this.notifyListeners(previousState, this.current);
      }
      return changed;
    } catch (error) {
      this.current = { ...previousState };
      throw error;
    }
  }

  undo(): boolean {
    if (this.history.length === 0) return false;

    const previousState = this.history.pop()!;
    this.current = { ...previousState };
    this.notifyListeners(this.current, previousState);
    return true;
  }

  redo(): boolean {
    if (this.history.length === 0) return false;

    const nextState = this.history.pop()!;
    const previousState = { ...this.current };
    this.current = { ...nextState };
    this.notifyListeners(previousState, this.current);
    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.history.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!['text', 'cursor', 'bold'].includes(field)) {
      throw new Error(`Invalid field: ${field}. Must be 'text', 'cursor', or 'bold'.`);
    }
    if (!this.listeners.has(field)) {
      this.listeners.set(field, new Set());
    }
    this.listeners.get(field)!.add(listener);
    return () => {
      const set = this.listeners.get(field);
      if (set) {
        set.delete(listener);
        if (set.size === 0) {
          this.listeners.delete(field);
        }
      }
    };
  }

  private saveToHistory(previousState: EditorState) {
    // If the new state is identical to the last one in history, don't add it
    if (this.history.length > 0 && this.history[this.history.length - 1] === previousState) {
      return;
    }

    this.history.push({ ...previousState });
    if (this.history.length > this.historyLimit) {
      this.history.shift();
    }
  }

  private notifyListeners(previousState: EditorState, currentState: EditorState) {
    for (const [field, listenerSet] of this.listeners.entries()) {
      const prevValue = previousState[field];
      const currValue = currentState[field];

      if (prevValue !== currValue) {
        for (const listener of listenerSet) {
          listener(currValue, prevValue);
        }
      }
    }
  }
}

