export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'.`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private taskList: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.taskList = Object.keys(spec);

    // Check for missing dependencies in key order
    for (const task of this.taskList) {
      const deps = spec[task];
      for (const dep of deps) {
        if (!(dep in this.spec)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Check for cycles using the specific placement logic
    // We simulate the placement process to detect cycles as they happen
    const placed: string[] = [];
    const inProcess: string[] = []; // Tracks tasks currently being placed (the chain)
    const placedSet = new Set<string>();

    for (const task of this.taskList) {
      if (placedSet.has(task)) continue;

      // Start placing this task and its dependencies
      const chain: string[] = [];
      const stack: string[] = [task];
      const stackSet = new Set<string>();

      while (stack.length > 0) {
        const current = stack.pop()!;

        if (stackSet.has(current)) {
          // Cycle detected: current is already in the chain
          // The path is from the first occurrence of current in chain to the end, plus current again
          const cycleStartIndex = chain.indexOf(current);
          const cyclePath = [...chain.slice(cycleStartIndex), current];
          throw new CycleError(cyclePath);
        }

        if (placedSet.has(current)) {
          continue;
        }

        stackSet.add(current);
        chain.push(current);
        inProcess.push(current);

        const deps = this.spec[current];
        for (const dep of deps) {
          if (!placedSet.has(dep)) {
            stack.push(dep);
          }
        }
      }

      // Mark as placed
      for (const t of chain) {
        placedSet.add(t);
        placed.push(t);
      }
    }

    // If we get here, no cycles were found during the specific traversal
    // However, the problem statement implies we must throw CycleError if a cycle exists.
    // The logic above handles the cycle detection during the "placing" phase described.
    // Let's re-verify the cycle detection logic against the example:
    // { app: ['lib'], lib: ['core'], core: ['lib'] }
    // Key order: app, lib, core
    // 1. Process 'app':
    //    chain = ['app'], stack = ['lib']
    //    Process 'lib':
    //      chain = ['app', 'lib'], stack = ['core']
    //      Process 'core':
    //        chain = ['app', 'lib', 'core'], stack = ['lib']
    //        Process 'lib' (again):
    //          stackSet has 'lib'. Cycle detected.
    //          chain is ['app', 'lib', 'core']. indexOf('lib') is 1.
    //          slice(1) -> ['lib', 'core']. Add 'lib' -> ['lib', 'core', 'lib']. Correct.
  }

  order(): string[] {
    const placed: string[] = [];
    const placedSet = new Set<string>();

    for (const task of this.taskList) {
      if (placedSet.has(task)) continue;

      const stack: string[] = [task];
      const stackSet = new Set<string>();

      while (stack.length > 0) {
        const current = stack.pop()!;

        if (stackSet.has(current)) {
          // This should theoretically not happen if constructor validation passed
          // But for safety in a method that might be called independently or if logic changes:
          // We need to reconstruct the path. Since constructor ensures no cycles,
          // we can assume this path is valid or re-throw if it somehow happens.
          // However, the prompt says "The tasks whose placing has started and not finished form a chain".
          // This implies the cycle check happens during construction.
          // So this block is unreachable if constructor is correct.
          continue;
        }

        if (placedSet.has(current)) {
          continue;
        }

        stackSet.add(current);
        placed.push(current);
        placedSet.add(current);

        const deps = this.spec[current];
        for (const dep of deps) {
          if (!placedSet.has(dep)) {
            stack.push(dep);
          }
        }
      }
    }
    return placed;
  }

  layers(): string[][] {
    if (this.taskList.length === 0) {
      return [];
    }

    const order = this.order();
    const layerMap = new Map<string, number>();
    const layers: string[][] = [];

    // Initialize layer map with -1 (not assigned)
    for (const task of this.taskList) {
      layerMap.set(task, -1);
    }

    // Assign layers based on dependencies
    // Layer 0: tasks with no dependencies
    // Layer L: max(layer of dependencies) + 1
    // We can do this by iterating the order array. Since order guarantees dependencies come before dependents,
    // when we visit a task, all its dependencies have already been assigned a layer.

    for (const task of order) {
      const deps = this.spec[task];
      if (deps.length === 0) {
        layerMap.set(task, 0);
      } else {
        let maxDepLayer = -1;
        for (const dep of deps) {
          const depLayer = layerMap.get(dep);
          if (depLayer === -1) {
            // This implies a cycle or logic error, but constructor should have caught cycles.
            // If a dependency is not in the map, it's a missing dependency (caught in constructor).
            // If a dependency is in the map but -1, it means we haven't processed it yet?
            // But 'order' guarantees dependencies are processed first.
            // So this should not happen.
            continue;
          }
          if (depLayer > maxDepLayer) {
            maxDepLayer = depLayer;
          }
        }
        layerMap.set(task, maxDepLayer + 1);
      }
    }

    // Group tasks into layers
    const maxLayer = Math.max(...Array.from(layerMap.values()));
    for (let i = 0; i <= maxLayer; i++) {
      const currentLayer: string[] = [];
      for (const task of this.taskList) {
        if (layerMap.get(task) === i) {
          currentLayer.push(task);
        }
      }
      layers.push(currentLayer);
    }

    return layers;
  }

  dependentsOf(name: string): string[] {
    if (!(name in this.spec)) {
      return [];
    }

    const order = this.order();
    const result: string[] = [];
    const visited = new Set<string>();

    for (const task of order) {
      if (visited.has(task)) continue;
      visited.add(task);

      // BFS/DFS to find all tasks that depend on 'name'
      const queue: string[] = [task];
      const queueSet = new Set<string>();
      queueSet.add(task);

      while (queue.length > 0) {
        const current = queue.shift()!;

        // Check if current depends on 'name'
        const deps = this.spec[current];
        for (const dep of deps) {
          if (dep === name) {
            if (current !== name) { // name itself is not included
              result.push(current);
            }
          }
          if (!queueSet.has(dep)) {
            queueSet.add(dep);
            queue.push(dep);
          }
        }
      }
    }

    return result;
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function addError(errors: FieldError[], path: string, message: string): void {
  errors.push({ path, message });
}

function checkUnknownFields(
  errors: FieldError[],
  pathPrefix: string,
  obj: Record<string, unknown>
): void {
  const keys = Object.keys(obj);
  for (const key of keys) {
    if (!isNaN(Number(key)) && key.match(/^\d+$/)) {
      continue;
    }
    if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice' && key !== 'id' && key !== 'status' && key !== 'lines') {
      addError(errors, `${pathPrefix}.${key}`, 'unknown field');
    }
  }
}

function parseOrder(text: string): ParseResult {
  const errors: FieldError[] = [];
  let parsed: unknown;

  try {
    parsed = JSON.parse(text);
  } catch {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const orderObj = parsed as Record<string, unknown>;
  const linesRaw = orderObj['lines'];
  const statusRaw = orderObj['status'];
  const idRaw = orderObj['id'];

  // Check id
  if (idRaw === undefined || idRaw === null) {
    addError(errors, 'id', 'required');
  } else if (typeof idRaw !== 'string') {
    addError(errors, 'id', 'expected a string');
  } else if (idRaw === '') {
    addError(errors, 'id', 'must not be empty');
  }

  // Check status
  if (statusRaw === undefined || statusRaw === null) {
    // Optional, defaults to Draft
  } else if (typeof statusRaw !== 'string') {
    addError(errors, 'status', 'expected one of draft, paid, shipped');
  } else if (
    statusRaw !== 'draft' &&
    statusRaw !== 'paid' &&
    statusRaw !== 'shipped'
  ) {
    addError(errors, 'status', 'expected one of draft, paid, shipped');
  }

  // Check lines
  if (linesRaw === undefined || linesRaw === null) {
    addError(errors, 'lines', 'required');
  } else if (!Array.isArray(linesRaw)) {
    addError(errors, 'lines', 'expected an array');
  } else if (linesRaw.length === 0) {
    addError(errors, 'lines', 'must not be empty');
  } else {
    for (let i = 0; i < linesRaw.length; i++) {
      const lineRaw = linesRaw[i];
      const linePath = `lines[${i}]`;
      const lineErrors: FieldError[] = [];

      if (typeof lineRaw !== 'object' || lineRaw === null) {
        addError(lineErrors, linePath, 'expected an object');
      } else {
        const lineObj = lineRaw as Record<string, unknown>;
        const skuRaw = lineObj['sku'];
        const quantityRaw = lineObj['quantity'];
        const unitPriceRaw = lineObj['unitPrice'];

        // Check sku
        if (skuRaw === undefined || skuRaw === null) {
          addError(lineErrors, `${linePath}.sku`, 'required');
        } else if (typeof skuRaw !== 'string') {
          addError(lineErrors, `${linePath}.sku`, 'expected a string');
        } else if (skuRaw === '') {
          addError(lineErrors, `${linePath}.sku`, 'must not be empty');
        }

        // Check quantity
        if (quantityRaw === undefined || quantityRaw === null) {
          addError(lineErrors, `${linePath}.quantity`, 'required');
        } else if (typeof quantityRaw !== 'number') {
          addError(lineErrors, `${linePath}.quantity`, 'expected a number');
        } else if (!Number.isInteger(quantityRaw) || quantityRaw < 1) {
          addError(lineErrors, `${linePath}.quantity`, 'must be a whole number of 1 or more');
        }

        // Check unitPrice
        if (unitPriceRaw === undefined || unitPriceRaw === null) {
          addError(lineErrors, `${linePath}.unitPrice`, 'required');
        } else if (typeof unitPriceRaw !== 'number') {
          addError(lineErrors, `${linePath}.unitPrice`, 'expected a number');
        } else if (unitPriceRaw < 0) {
          addError(lineErrors, `${linePath}.unitPrice`, 'must be 0 or more');
        }

        // Check unknown fields in line
        checkUnknownFields(lineErrors, linePath, lineObj);
      }

      errors.push(...lineErrors);
    }
  }

  // Check unknown fields in order
  checkUnknownFields(errors, '', orderObj);

  if (errors.length > 0) {
    return { order: undefined, errors };
  }

  const status: OrderStatus = statusRaw === undefined || statusRaw === null
    ? OrderStatus.Draft
    : (statusRaw as OrderStatus);

  const lines: OrderLine[] = linesRaw.map((lineRaw) => {
    const lineObj = lineRaw as Record<string, unknown>;
    return new OrderLine(
      lineObj['sku'] as string,
      lineObj['quantity'] as number,
      lineObj['unitPrice'] as number
    );
  });

  return {
    order: {
      id: idRaw as string,
      status,
      lines,
    },
    errors: [],
  };
}

