    // Generate initial 3000 entries with ids 1 to 3000
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
  }

  build() {
    Column() {
      // Top text showing the number of entries
      Text(`${this.entries.length} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .fontColor('#333333')
        .margin({ top: 20, bottom: 10 })

      // Scrolling list
      List(this.entries, {
        refresh: {
          mode: 'pullDown',
          action: () => this.handleRefresh()
        }
      }) {
        // Use LazyForEach to build rows only as they scroll into view
        LazyForEach(this.entries, (entry: LogEntry, index: number) => {
          LogRow({ entry: entry })
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }

  private handleRefresh() {
    this.isLoading = true;

    // Simulate a 1-second delay
    setTimeout(() => {
      // Calculate the next 5 IDs
      const currentMaxId = this.entries.length > 0 ? this.entries[0].id : 0;
      const newEntries: LogEntry[] = [];

      for (let i = 1; i <= 5; i++) {
        const newId = currentMaxId + i;
        newEntries.push(new LogEntry(newId));
      }

      // Add new entries at the top (index 0)
      this.entries.unshift(...newEntries);
      this.isLoading = false;
    }, 1000);
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  try {
    const parsed = jsonParse(json);
    if (!parsed || !Array.isArray(parsed)) {
      return [];
    }

    const result: User[] = [];
    for (const item of parsed) {
      if (isValidUser(item)) {
        result.push({
          id: item.id,
          name: item.name,
          email: item.email
        });
      }
    }
    return result;
  } catch {
    return [];
  }
}

function jsonParse(text: string): Object | null {
  return jsonParse(text, null, null);
}

function isValidUser(item: any): boolean {
  if (typeof item !== 'object' || item === null) {
    return false;
  }

  if (Array.isArray(item)) {
    return false;
  }

  if (typeof item.id !== 'number' || !Number.isInteger(item.id)) {
    return false;
  }

  if (typeof item.name !== 'string' || item.name.length === 0) {
    return false;
  }

  if (typeof item.email !== 'string' || item.email.indexOf('@') === -1) {
    return false;
  }

  return true;
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return [...this.items];
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Set<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const eventListeners = this.listeners.get(event);
    if (eventListeners) {
      eventListeners.delete(listener);
      if (eventListeners.size === 0) {
        this.listeners.delete(event);
      }
    }
  }

  emit(event: string, payload: T): number {
    const eventListeners = this.listeners.get(event);
    if (!eventListeners) {
      return 0;
    }

    let count = 0;
    for (const listener of eventListeners) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const eventListeners = this.listeners.get(event);
    return eventListeners ? eventListeners.size : 0;
  }
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY
  };
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const effectiveAttempts = Math.max(1, attempts);
  let currentAttempt = 0;
  let lastError: Error | null = null;

  while (currentAttempt < effectiveAttempts) {
    try {
      return await action();
    } catch (e) {
      if (!(e instanceof Error)) {
        throw e;
      }
      lastError = e;
      currentAttempt++;
    }
  }

  throw new RetryError(currentAttempt, lastError!);
}

export function formatDuration(totalSeconds: number): string {
  const isNegative = totalSeconds < 0;
  const absSeconds = Math.abs(totalSeconds);

  const hours = Math.floor(absSeconds / 3600);
  const remainingAfterHours = absSeconds % 3600;
  const minutes = Math.floor(remainingAfterHours / 60);
  const seconds = remainingAfterHours % 60;

  const parts: string[] = [];

  if (hours > 0) {
    parts.push(`${hours}h`);
  }
  if (minutes > 0) {
    parts.push(`${minutes}m`);
  }
  if (seconds > 0) {
    parts.push(`${seconds}s`);
  }

  // Handle the case where totalSeconds is 0
  if (parts.length === 0) {
    return "0s";
  }

  // Format parts: first as is, rest with two digits
  const formattedParts = parts.map((part, index) => {
    if (index === 0) {
      return part;
    }
    // Extract the number and unit
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) return part;
    const num = parseInt(match[1], 10);
    const unit = match[2];
    return `${num.toString().padStart(2, '0')}${unit}`;
  });

  const result = formattedParts.join(' ');

  return isNegative ? `-${result}` : result;
}

export function parseDuration(text: string): number {
  if (!text || typeof text !== 'string') {
    return NaN;
  }

  const trimmedText = text.trim();
  if (trimmedText === '') {
    return NaN;
  }

  // Check for leading minus sign
  let isNegative = false;
  let remainingText = trimmedText;

  if (remainingText.startsWith('-')) {
    isNegative = true;
    remainingText = remainingText.substring(1).trim();
    if (remainingText === '') {
      return NaN;
    }
  }

  // Split by single spaces
  const parts = remainingText.split(' ');

  // Validate that there are no empty parts (caused by multiple spaces or leading/trailing spaces)
  if (parts.some(p => p === '')) {
    return NaN;
  }

  const totalSeconds: number[] = [];

  for (const part of parts) {
    // Regex: one or more digits followed by h, m, or s
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    let secondsToAdd = 0;
    switch (unit) {
      case 'h':
        secondsToAdd = value * 3600;
        break;
      case 'm':
        secondsToAdd = value * 60;
        break;
      case 's':
        secondsToAdd = value;
        break;
    }

    totalSeconds.push(secondsToAdd);
  }

  const sum = totalSeconds.reduce((acc, curr) => acc + curr, 0);

  return isNegative ? -sum : sum;
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private lruList: LinkedList<K>;

  constructor(capacity: number) {
    this.capacity = capacity;
    this.map = new Map();
    this.lruList = new LinkedList();
  }

  set(key: K, value: V): void {
    if (this.map.has(key)) {
      this.map.set(key, value);
      this.lruList.moveToEnd(key);
    } else {
      if (this.map.size >= this.capacity) {
        const lruKey = this.lruList.removeFirst();
        this.map.delete(lruKey);
      }
      this.map.set(key, value);
      this.lruList.addLast(key);
    }
  }

  get(key: K): V | undefined {
    if (this.map.has(key)) {
      const value = this.map.get(key);
      this.lruList.moveToEnd(key);
      return value;
    }
    return undefined;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    for (const key of this.lruList) {
      result.push(key);
    }
    return result;
  }

  get size(): number {
    return this.map.size;
  }
}

class LinkedList<K> {
  private head: Node<K> | null = null;
  private tail: Node<K> | null = null;
  private size: number = 0;

  addLast(key: K): void {
    const node = new Node(key);
    if (this.tail === null) {
      this.head = node;
      this.tail = node;
    } else {
      this.tail.next = node;
      node.prev = this.tail;
      this.tail = node;
    }
    this.size++;
  }

  removeFirst(): K {
    if (this.head === null) {
      throw new Error('Cannot remove from empty list');
    }
    const key = this.head.key;
    if (this.head === this.tail) {
      this.head = null;
      this.tail = null;
    } else {
      this.head = this.head.next;
      this.head.prev = null;
    }
    this.size--;
    return key;
  }

  remove(key: K): void {
    let current = this.head;
    while (current !== null) {
      if (current.key === key) {
        if (current === this.head) {
          this.head = current.next;
          if (this.head !== null) {
            this.head.prev = null;
          } else {
            this.tail = null;
          }
        } else if (current === this.tail) {
          this.tail = current.prev;
          if (this.tail !== null) {
            this.tail.next = null;
          }
        } else {
          current.prev.next = current.next;
          current.next.prev = current.prev;
        }
        this.size--;
        return;
      }
      current = current.next;
    }
  }

  moveToEnd(key: K): void {
    this.remove(key);
    this.addLast(key);
  }
}

class Node<K> {
  key: K;
  prev: Node<K> | null = null;
  next: Node<K> | null = null;

  constructor(key: K) {
    this.key = key;
  }
}

export type Pair<A, B> = {
  first: A;
  second: B;
};

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];
  for (let i = 0; i < minLength; i++) {
    result.push({
      first: a[i],
      second: b[i],
    });
  }
  return result;
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentAmount = result.get(expense.category) || 0;
    result.set(expense.category, currentAmount + expense.amount);
  }

  return result;
}

export type Transform = (text: string) => string;

export function trim(text: string): string {
  return text.trim();
}

export function lowerCase(text: string): string {
  return text.toLowerCase();
}

export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ').trim();
}

export class Pipeline {
  private steps: Array<{ name: string; step: Transform }> = [];

  add(name: string, step: Transform): this {
    this.steps.push({ name, step });
    return this;
  }

  run(text: string): string {
    let result = text;
    for (const { step } of this.steps) {
      result = step(result);
    }
    return result;
  }

  names(): string[] {
    return this.steps.map(({ name }) => name);
  }

  toFunction(): Transform {
    const pipeline = this;
    return function (text: string): string {
      return pipeline.run(text);
    };
  }
}

export function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string) => text;
  }
  return steps.reduceRight((acc, step) => (text: string) => step(acc(text)), (text: string) => text);
}

