export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  if (!query || query.length === 0) {
    return result;
  }

  // Remove leading '?' if present
  let str = query;
  if (str.startsWith('?')) {
    str = str.substring(1);
  }

  if (str.length === 0) {
    return result;
  }

  // Split by '&'
  const parts = str.split('&');

  for (const part of parts) {
    // Skip empty parts (handles trailing & or &&)
    if (part.length === 0) {
      continue;
    }

    // Split at the first '='
    const eqIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found: key is the whole part, value is empty
      key = part;
      value = '';
    } else {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    // Ignore pairs with empty keys
    if (key.length === 0) {
      continue;
    }

    // Decode the value first (key is not decoded per typical URL query behavior, 
    // but the prompt says "Keys and values are decoded", so we decode both)
    const decodedKey = decodeURIComponentSafe(key);
    const decodedValue = decodeURIComponentSafe(value);

    // Set the value; if key exists, it updates the value but keeps the first position
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeURIComponentSafe(str: string): string {
  // Replace '+' with space first
  let result = str.replace(/\+/g, ' ');

  // Process percent-encoded sequences
  // We use a regex to find all %XX patterns. If XX is not a valid hex, we leave it as is.
  // We process from left to right to handle malformed sequences correctly.
  let i = 0;
  const len = result.length;
  let output = '';

  while (i < len) {
    if (result[i] === '%') {
      if (i + 2 < len) {
        const hex = result.substring(i + 1, i + 3);
        // Check if both characters are valid hex digits
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          try {
            const codePoint = parseInt(hex, 16);
            // Check for valid UTF-8 sequence start
            if (codePoint >= 0 && codePoint <= 0x10FFFF) {
              // Decode the byte sequence
              const bytes = new Uint8Array(1);
              bytes[0] = codePoint;
              const decoder = new TextDecoder('utf-8');
              output += decoder.decode(bytes);
              i += 3;
              continue;
            }
          } catch (e) {
            // If decoding fails for some reason, keep the original
          }
        }
        // If hex is invalid, keep the '%' and the two chars as is
      }
      // If not enough chars for %XX, keep as is
      output += result[i];
      i++;
    } else {
      output += result[i];
      i++;
    }
  }

  return output;
}

// Entry component for the Todo List app
@Entry
@Component
struct Solution {
  // State to hold the list of todos. Each todo is a string.
  @State todos: string[] = [];

  // State to hold the current text in the input field
  @State inputText: string = '';

  // Build the UI
  build() {
    Column() {
      // Input row
      Row() {
        TextInput({ placeholder: 'New todo' })
          .text(this.inputText)
          .onChange((value: string) => {
            this.inputText = value;
          })
          .submit((event: SubmitEvent) => {
            event.keepEditableState();
            this.handleAddTodo(event.text);
          })

        Button('Add')
          .onClick(() => {
            this.handleAddTodo(this.inputText);
            this.inputText = '';
          })
      }
      .width('100%')
      .margin({ bottom: 20 })

      // List of todos
      ForEach(this.todos, (todo: string, index: number) => {
        ListItem()
          .key({ index: index, value: todo })
          .width('100%')
          .height(40)
          .onClick(() => {
            this.removeTodo(index);
          })
          .text(todo)
          .fontSize(16)
          .fontColor('#333333')
          .margin({ left: 16 })
      })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Start)
    .padding(16)
  }

  // Handle adding a new todo
  handleAddTodo(text: string) {
    // Trim whitespace and check if empty
    const trimmedText = text.trim();
    if (trimmedText.length > 0) {
      this.todos.push(trimmedText);
    }
  }

  // Handle removing a specific todo by index
  removeTodo(index: number) {
    if (index >= 0 && index < this.todos.length) {
      this.todos.splice(index, 1);
    }
  }
}

