export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    // Check for number
    if (/\d/.test(char)) {
      let j = i;
      while (j < source.length && /\d/.test(source[j])) {
        j++;
      }
      if (j < source.length && source[j] === '.') {
        if (j + 1 < source.length && /\d/.test(source[j + 1])) {
          j++;
          while (j < source.length && /\d/.test(source[j])) {
            j++;
          }
        } else {
          // Dot not followed by digit, not a number start in this context if we are strict, 
          // but spec says "A . is only part of a number when it has a digit on both sides".
          // So if we have "12.3", i=1, char='.', j=2. source[1]='2' (digit), source[2]='3' (digit). OK.
          // If we have "12.", i=2, char='.', j=3. source[2]='2' (digit), source[3] is end or not digit. Fail.
          // If we have ".5", i=0, char='.', j=1. source[0] is not digit. Fail.
          // So we need to check if the char before '.' is a digit.
          if (j > i && /\d/.test(source[j - 1])) {
             // Check if there is a digit after
             if (j + 1 < source.length && /\d/.test(source[j + 1])) {
                j++;
                while (j < source.length && /\d/.test(source[j])) {
                  j++;
                }
             } else {
                throw new ExpressionError(`Unexpected character '.'`, j);
             }
          } else {
             throw new ExpressionError(`Unexpected character '.'`, j);
          }
        }
      }
      tokens.push({ kind: 'number', text: source.slice(i, j), position: i });
      i = j;
      continue;
    }

    // Check for name
    if (/[a-zA-Z_]/.test(char)) {
      let j = i;
      while (j < source.length && /[a-zA-Z0-9_]/.test(source[j])) {
        j++;
      }
      tokens.push({ kind: 'name', text: source.slice(i, j), position: i });
      i = j;
      continue;
    }

    // Check for operator or paren
    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      tokens.push({ kind: 'operator' if (['+', '-', '*', '/', '%'].includes(char)) else 'paren', text: char, position: i });
      i++;
      continue;
    }

    // Unknown character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  // Convert tokens to AST nodes
  // Node types: 'number', 'name', 'unaryMinus', 'binaryOp', 'paren'
  // We will build a flat list of nodes and then parse with precedence climbing or recursive descent.
  // Given the requirements, recursive descent is straightforward.

  // Grammar:
  // expr     -> term ( ('+' | '-') term )*
  // term     -> unary ( ('*' | '/' | '%') unary )*
  // unary    -> ('-' unary) | primary
  // primary  -> NUMBER | NAME | '(' expr ')'

  let pos = 0;

  function peek(): Token | undefined {
    return tokens[pos];
  }

  function consume(): Token {
    if (pos >= tokens.length) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    return tokens[pos++];
  }

  function parseExpr(): number {
    let left = parseTerm();

    while (peek() && peek().kind === 'operator' && (peek().text === '+' || peek().text === '-')) {
      const op = consume().text;
      const right = parseTerm();
      if (op === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }
    return left;
  }

  function parseTerm(): number {
    let left = parseUnary();

    while (peek() && peek().kind === 'operator' && (peek().text === '*' || peek().text === '/' || peek().text === '%')) {
      const op = consume().text;
      const right = parseUnary();
      if (op === '*') {
        left = left * right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', right === 0 ? right : 0); // Position logic handled below
        }
        left = left / right;
      } else {
        if (right === 0) {
          throw new ExpressionError('Division by zero', right === 0 ? right : 0);
        }
        left = left % right;
      }
    }
    return left;
  }

  function parseUnary(): number {
    if (peek() && peek().text === '-') {
      consume();
      return -parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = consume();

    if (token.kind === 'number') {
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      if (!(token.text in variables)) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return variables[token.text];
    }

    if (token.kind === 'paren') {
      if (token.text === '(') {
        const result = parseExpr();
        const close = consume();
        if (close.text !== ')') {
          throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
        }
        return result;
      } else {
        throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
      }
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpr();

  if (pos < tokens.length) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

// Entry
@Entry
@Component
struct Solution {
  // State to track the current UI state: 'loading', 'error', or 'loaded'
  @State currentState: string = 'loading';

  // Data to hold the list of articles
  @State articles: string[] = [];

