        this.articles = ['First article', 'Second article', 'Third article'];
        this.currentState = 'loaded';
      })
      .margin({ bottom: 20 })

      Button('Fail loading') {
        Text('Fail loading')
      }
      .onClick(() => {
        this.currentState = 'error';
      })
