export interface Shape {
  type: 'circle' | 'rectangle' | 'triangle';
  area: number;
}

export function circle(radius: number): Shape {
  return {
    type: 'circle',
    area: Math.PI * radius * radius
  };
}

export function rectangle(width: number, height: number): Shape {
  return {
    type: 'rectangle',
    area: width * height
  };
}

export function triangle(base: number, height: number): Shape {
  return {
    type: 'triangle',
    area: base * height / 2
  };
}

export function area(shape: Shape): number {
  return shape.area;
}

export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + shape.area, 0);
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];

  for (const item of items) {
    if (item.id === id) {
      if (quantity <= 0) {
        continue;
      }
      result.push({
        id: item.id,
        name: item.name,
        quantity: quantity
      });
    } else {
      result.push({
        id: item.id,
        name: item.name,
        quantity: item.quantity
      });
    }
  }

  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let currentItems = items;

  for (const change of changes) {
    const wasRemoved = currentItems.some(item => item.id === change.id);

    if (wasRemoved) {
      continue;
    }

    currentItems = updateQuantity(currentItems, change.id, change.quantity);
  }

  return currentItems;
}

