export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    // Check for number
    if (/\d/.test(char)) {
      let j = i;
      while (j < source.length && /\d/.test(source[j])) {
        j++;
      }
      if (j < source.length && source[j] === '.') {
        // Check if there is a digit before the dot
        if (j > i && /\d/.test(source[j - 1])) {
          // Check if there is a digit after the dot
          if (j + 1 < source.length && /\d/.test(source[j + 1])) {
            j++;
            while (j < source.length && /\d/.test(source[j])) {
              j++;
            }
          } else {
            throw new ExpressionError(`Unexpected character '.'`, j);
          }
        } else {
          throw new ExpressionError(`Unexpected character '.'`, j);
        }
      }
      tokens.push({ kind: 'number', text: source.slice(i, j), position: i });
      i = j;
      continue;
    }

    // Check for name
    if (/[a-zA-Z_]/.test(char)) {
      let j = i;
      while (j < source.length && /[a-zA-Z0-9_]/.test(source[j])) {
        j++;
      }
      tokens.push({ kind: 'name', text: source.slice(i, j), position: i });
      i = j;
      continue;
    }

    // Check for operator or paren
    if (['+', '-', '*', '/', '%', '(', ')'].includes(char)) {
      const isOperator = ['+', '-', '*', '/', '%'].includes(char);
      tokens.push({ 
        kind: isOperator ? 'operator' : 'paren', 
        text: char, 
        position: i 
      });
      i++;
      continue;
    }

    // Unknown character
    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  let pos = 0;
  const tokenCount = tokens.length;

  function peek(): Token | undefined {
    if (pos < tokenCount) {
      return tokens[pos];
    }
    return undefined;
  }

  function consume(): Token {
    if (pos >= tokenCount) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    return tokens[pos++];
  }

  function parseExpr(): number {
    let left = parseTerm();

    while (true) {
      const t = peek();
      if (!t || t.kind !== 'operator' || (t.text !== '+' && t.text !== '-')) {
        break;
      }
      const op = consume().text;
      const right = parseTerm();
      if (op === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }
    return left;
  }

  function parseTerm(): number {
    let left = parseUnary();

    while (true) {
      const t = peek();
      if (!t || t.kind !== 'operator' || (t.text !== '*' && t.text !== '/' && t.text !== '%')) {
        break;
      }
      const op = consume().text;
      const right = parseUnary();
      if (op === '*') {
        left = left * right;
      } else if (op === '/') {
        if (right === 0) {
          throw new ExpressionError('Division by zero', 0);
        }
        left = left / right;
      } else {
        if (right === 0) {
          throw new ExpressionError('Division by zero', 0);
        }
        left = left % right;
      }
    }
    return left;
  }

  function parseUnary(): number {
    const t = peek();
    if (t && t.text === '-') {
      consume();
      return -parseUnary();
    }
    return parsePrimary();
  }

  function parsePrimary(): number {
    const token = consume();

    if (token.kind === 'number') {
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      const varName = token.text;
      const varValue = variables[varName];
      if (varValue === undefined) {
        throw new ExpressionError(`Unknown variable '${varName}'`, token.position);
      }
      return varValue;
    }

    if (token.kind === 'paren') {
      if (token.text === '(') {
        const result = parseExpr();
        const close = consume();
        if (close.text !== ')') {
          throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
        }
        return result;
      } else {
        throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
      }
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }

  const result = parseExpr();

  if (pos < tokenCount) {
    throw new ExpressionError(`Unexpected token '${tokens[pos].text}'`, tokens[pos].position);
  }

  return result;
}

