export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private currentState: EditorState;
  private history: EditorState[];
  private redoStack: EditorState[];
  private historyLimit: number;
  private listeners: Map<string, Set<(value: string | number | boolean, previous: string | number | boolean) => void>>;

  constructor(initial: EditorState, historyLimit: number) {
    this.currentState = { text: initial.text, cursor: initial.cursor, bold: initial.bold };
    this.history = [];
    this.redoStack = [];
    this.historyLimit = historyLimit;
    this.listeners = new Map();
  }

  get state(): EditorState {
    return { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
  }

  apply(patch: Partial<EditorState>): boolean {
    const oldState = { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
    let changed = false;

    if (patch.text !== undefined) {
      this.currentState.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined) {
      this.currentState.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined) {
      this.currentState.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.history.push(oldState);
      if (this.history.length > this.historyLimit) {
        this.history.shift();
      }
      this.redoStack = [];
      this.notifyListeners(oldState, this.currentState);
      return true;
    }
    return false;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    try {
      const oldState = { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
      const draft: EditorState = { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
      run(draft);

      let changed = false;
      if (draft.text !== oldState.text) changed = true;
      if (draft.cursor !== oldState.cursor) changed = true;
      if (draft.bold !== oldState.bold) changed = true;

      if (changed) {
        this.history.push(oldState);
        if (this.history.length > this.historyLimit) {
          this.history.shift();
        }
        this.redoStack = [];
        this.currentState = { text: draft.text, cursor: draft.cursor, bold: draft.bold };
        this.notifyListeners(oldState, this.currentState);
        return true;
      }
      return false;
    } catch (error) {
      throw error;
    }
  }

  undo(): boolean {
    if (this.history.length === 0) return false;

    const currentState = { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
    const previousState = this.history.pop();
    this.currentState = { text: previousState.text, cursor: previousState.cursor, bold: previousState.bold };
    this.redoStack.push(currentState);
    this.notifyListeners(currentState, this.currentState);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) return false;

    const currentState = { text: this.currentState.text, cursor: this.currentState.cursor, bold: this.currentState.bold };
    const nextState = this.redoStack.pop();
    this.currentState = { text: nextState.text, cursor: nextState.cursor, bold: nextState.bold };
    this.history.push(currentState);
    this.notifyListeners(currentState, this.currentState);
    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (!this.listeners.has(field)) {
      this.listeners.set(field, new Set());
    }
    this.listeners.get(field)!.add(listener);

    return () => {
      const fieldListeners = this.listeners.get(field);
      if (fieldListeners) {
        fieldListeners.delete(listener);
        if (fieldListeners.size === 0) {
          this.listeners.delete(field);
        }
      }
    };
  }

  private notifyListeners(oldState: EditorState, newState: EditorState) {
    const fieldNames = ['text', 'cursor', 'bold'];
    for (const fieldName of fieldNames) {
      const listeners = this.listeners.get(fieldName);
      if (listeners) {
        const oldValue = oldState[fieldName];
        const newValue = newState[fieldName];
        if (oldValue !== newValue) {
          for (const listener of listeners) {
            listener(newValue, oldValue);
          }
        }
      }
    }
  }
}

