export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

export class JobQueue {
  private readonly concurrency: number;
  private readonly queue: JobItem[] = [];
  private runningCount = 0;
  private completedCount = 0;
  private failedCount = 0;
  private isPaused = false;
  private isIdle = true;
  private resolveIdle: (() => void) | null = null;
  private idlePromise: Promise<void> | null = null;

  private interface JobItem {
    fn: () => Promise<unknown>;
    promise: Promise<unknown>;
  }

  constructor(concurrency: number) {
    if (concurrency < 1) {
      throw new Error('Concurrency must be at least 1');
    }
    this.concurrency = concurrency;
  }

  private startNextJob(): void {
    if (this.isPaused || this.runningCount >= this.concurrency || this.queue.length === 0) {
      return;
    }

    const item = this.queue.shift()!;
    this.runningCount++;
    this.isIdle = false;

    item.fn()
      .then((value) => {
        this.runningCount--;
        this.completedCount++;
        this.checkIdle();
        this.startNextJob();
      })
      .catch((error) => {
        this.runningCount--;
        this.failedCount++;
        this.checkIdle();
        this.startNextJob();
      });
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.queue.length === 0) {
      this.isIdle = true;
      if (this.resolveIdle !== null) {
        this.resolveIdle();
        this.resolveIdle = null;
      }
    }
  }

  public add<T>(job: () => Promise<T>): Promise<T> {
    const p = new Promise<T>((resolve, reject) => {
      const fn = async (): Promise<T> => {
        try {
          const result = await job();
          resolve(result);
        } catch (e) {
          reject(e);
        }
      };
      this.queue.push({ fn, promise: p });
    });

    if (!this.isPaused && this.runningCount < this.concurrency) {
      this.startNextJob();
    }

    return p;
  }

  public get running(): number {
    return this.runningCount;
  }

  public get waiting(): number {
    return this.queue.length;
  }

  public get completed(): number {
    return this.completedCount;
  }

  public get failed(): number {
    return this.failedCount;
  }

  public pause(): void {
    this.isPaused = true;
  }

  public resume(): void {
    this.isPaused = false;
    this.startNextJob();
  }

  public clear(): number {
    const count = this.queue.length;
    for (const item of this.queue) {
      item.promise.catch(() => {});
    }
    this.queue = [];
    this.checkIdle();
    return count;
  }

  public whenIdle(): Promise<void> {
    if (this.isIdle) {
      return Promise.resolve();
    }
    if (this.idlePromise === null) {
      this.idlePromise = new Promise<void>((resolve) => {
        this.resolveIdle = () => {
          resolve();
        };
      });
    }
    return this.idlePromise;
  }

  public async runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = [];
    const promises: Promise<JobOutcome<T>>[] = [];

    for (const job of jobs) {
      const p = this.add(job);
      promises.push(
        p.then((value) => ({ ok: true, value, error: undefined }))
      );
    }

    await Promise.all(promises);
    return outcomes;
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();

  for (const expense of expenses) {
    const currentAmount = result.get(expense.category) || 0;
    result.set(expense.category, currentAmount + expense.amount);
  }

  return result;
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'.`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    let msg = 'Dependency cycle: ';
    for (let i = 0; i < path.length; i++) {
      if (i > 0) {
        msg += ' -> ';
      }
      msg += path[i];
    }
    super(msg);
    this.path = path;
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>;
  private taskList: string[];

  constructor(spec: Record<string, string[]>) {
    this.spec = spec;
    this.taskList = Object.keys(spec);

    // Check for missing dependencies in key order
    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      const deps = spec[task];
      for (let j = 0; j < deps.length; j++) {
        const dep = deps[j];
        if (this.spec[dep] === undefined) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Check for cycles using the specific placement logic
    const placed: string[] = [];
    const inProcess: string[] = [];
    const placedSet = new Set<string>();

    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      if (placedSet.has(task)) continue;

      const chain: string[] = [];
      const stack: string[] = [task];
      const stackSet = new Set<string>();

      while (stack.length > 0) {
        const current = stack.pop()!;

        if (stackSet.has(current)) {
          const cycleStartIndex = chain.indexOf(current);
          const cyclePath: string[] = [];
          for (let k = cycleStartIndex; k < chain.length; k++) {
            cyclePath.push(chain[k]);
          }
          cyclePath.push(current);
          throw new CycleError(cyclePath);
        }

        if (placedSet.has(current)) {
          continue;
        }

        stackSet.add(current);
        chain.push(current);
        inProcess.push(current);

        const deps = this.spec[current];
        for (let j = 0; j < deps.length; j++) {
          const dep = deps[j];
          if (!placedSet.has(dep)) {
            stack.push(dep);
          }
        }
      }

      for (let k = 0; k < chain.length; k++) {
        const t = chain[k];
        placedSet.add(t);
        placed.push(t);
      }
    }
  }

  order(): string[] {
    const result: string[] = [];
    const visited = new Set<string>();

    const processTask = (task: string) => {
      if (visited.has(task)) return;
      visited.add(task);

      const deps = this.spec[task];
      for (let j = 0; j < deps.length; j++) {
        const dep = deps[j];
        processTask(dep);
      }
      result.push(task);
    };

    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      if (visited.has(task) === false) {
        processTask(task);
      }
    }

    return result;
  }

  layers(): string[][] {
    if (this.taskList.length === 0) return [];

    const taskLayer: Record<string, number> = {};

    const getLayer = (task: string): number => {
      if (taskLayer[task] !== undefined) return taskLayer[task];

      const deps = this.spec[task];
      if (deps.length === 0) {
        taskLayer[task] = 0;
        return 0;
      }

      let maxDepLayer = -1;
      for (let j = 0; j < deps.length; j++) {
        const dep = deps[j];
        const depLayer = getLayer(dep);
        if (depLayer > maxDepLayer) {
          maxDepLayer = depLayer;
        }
      }

      taskLayer[task] = maxDepLayer + 1;
      return taskLayer[task];
    };

    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      getLayer(task);
    }

    const layerMap: Record<number, string[]> = {};
    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      const l = taskLayer[task];
      if (layerMap[l] === undefined) {
        layerMap[l] = [];
      }
      layerMap[l].push(task);
    }

    const result: string[][] = [];
    const keys: number[] = [];
    for (let i = 0; i < this.taskList.length; i++) {
      const task = this.taskList[i];
      const l = taskLayer[task];
      if (keys.indexOf(l) === -1) {
        keys.push(l);
      }
    }
    keys.sort((a, b) => a - b);

    for (let k = 0; k < keys.length; k++) {
      const l = keys[k];
      const tasks = layerMap[l];
      // Sort tasks within each layer by key order
      tasks.sort((a, b) => {
        let idxA = -1;
        let idxB = -1;
        for (let i = 0; i < this.taskList.length; i++) {
          if (this.taskList[i] === a) idxA = i;
          if (this.taskList[i] === b) idxB = i;
        }
        return idxA - idxB;
      });
      result.push(tasks);
    }

    return result;
  }

  dependentsOf(name: string): string[] {
    if (this.spec[name] === undefined) return [];

    const result: string[] = [];
    const visited = new Set<string>();

    const fullOrder = this.order();
    for (let i = 0; i < fullOrder.length; i++) {
      const task = fullOrder[i];
      if (task === name) continue;
      if (this.doesDependOn(task, name, visited)) {
        result.push(task);
      }
    }

    return result;
  }

  private doesDependOn(task: string, target: string, visited: Set<string>): boolean {
    if (visited.has(task)) return false;
    visited.add(task);

    const deps = this.spec[task];
    for (let j = 0; j < deps.length; j++) {
      const dep = deps[j];
      if (dep === target) return true;
      if (this.doesDependOn(dep, target, visited)) return true;
    }
    return false;
  }
}

