export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY,
  };
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  try {
    const parsed: unknown = JSON.parse(json);
    if (!Array.isArray(parsed)) {
      return [];
    }

    return parsed.reduce((acc: User[], item: unknown) => {
      if (typeof item !== 'object' || item === null) {
        return acc;
      }

      const obj = item as { id: unknown; name: unknown; email: unknown };
      const id = obj.id;
      const name = obj.name;
      const email = obj.email;

      if (
        typeof id === 'number' &&
        Number.isInteger(id) &&
        typeof name === 'string' &&
        name.length > 0 &&
        typeof email === 'string' &&
        email.includes('@')
      ) {
        acc.push({ id, name, email });
      }

      return acc;
    }, []);
  } catch {
    return [];
  }
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();

  // Remove leading ? if present
  let str = query;
  if (str.startsWith('?')) {
    str = str.substring(1);
  }

  // Split by &
  const pairs = str.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair === '') {
      continue;
    }

    // Split at first =
    const eqIndex = pair.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No = sign, key is the whole string, value is empty
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key === '') {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeURIComponentWithPlus(key);
    const decodedValue = decodeURIComponentWithPlus(value);

    // Add to map (last value wins, but key keeps first position)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeURIComponentWithPlus(str: string): string {
  // Replace + with space first
  let result = str.replace(/\+/g, ' ');

  // Decode percent-encoded sequences
  let i = 0;
  while (i < result.length) {
    if (result[i] === '%' && i + 2 < result.length) {
      const hex = result.substring(i + 1, i + 3);
      // Check if it's a valid hex sequence
      if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
        try {
          const codePoint = parseInt(hex, 16);
          result = result.substring(0, i) + String.fromCodePoint(codePoint) + result.substring(i + 3);
        } catch {
          // Keep as-is if decoding fails
        }
      }
      // If not valid hex, keep as-is
    }
    i++;
  }

  return result;
}

export class Stack<T> {
  private items: T[];
  private capacity: number;
  private count: number;

  constructor(capacity: number) {
    if (capacity <= 0) {
      throw new Error("Capacity must be greater than 0");
    }
    this.capacity = capacity;
    this.items = new Array<T>(capacity);
    this.count = 0;
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false;
    }
    this.items[this.count] = item;
    this.count++;
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    this.count--;
    return this.items[this.count];
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.count - 1];
  }

  size(): number {
    return this.count;
  }

  isEmpty(): boolean {
    return this.count === 0;
  }

  isFull(): boolean {
    return this.count === this.capacity;
  }

  clear(): void {
    this.count = 0;
  }

  toArray(): T[] {
    return [...this.items.slice(0, this.count)];
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Set<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const eventListeners = this.listeners.get(event);
    if (eventListeners) {
      eventListeners.delete(listener);
      if (eventListeners.size === 0) {
        this.listeners.delete(event);
      }
    }
  }

  emit(event: string, payload: T): number {
    const eventListeners = this.listeners.get(event);
    if (!eventListeners) {
      return 0;
    }

    let count = 0;
    for (const listener of eventListeners) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const eventListeners = this.listeners.get(event);
    return eventListeners ? eventListeners.size : 0;
  }
}

// Define the Shape interface to allow for future shape types
export interface Shape {
  type: string;
  area: number;
}

// Create a circle shape
export function circle(radius: number): Shape {
  const area = Math.PI * radius * radius;
  return {
    type: 'circle',
    area: area
  };
}

// Create a rectangle shape
export function rectangle(width: number, height: number): Shape {
  const area = width * height;
  return {
    type: 'rectangle',
    area: area
  };
}

// Create a triangle shape
export function triangle(base: number, height: number): Shape {
  const area = (base * height) / 2;
  return {
    type: 'triangle',
    area: area
  };
}

// Calculate the area of a single shape
export function area(shape: Shape): number {
  return shape.area;
}

// Calculate the total area of an array of shapes
export function totalArea(shapes: Shape[]): number {
  return shapes.reduce((sum, shape) => sum + area(shape), 0);
}

