export class RetryError extends Error {
  public attempts: number;
  public lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const effectiveAttempts = Math.max(1, attempts);
  let currentAttempt = 0;
  let lastError: Error | undefined;

  while (currentAttempt < effectiveAttempts) {
    try {
      return await action();
    } catch (error) {
      if (!(error instanceof Error)) {
        throw error;
      }
      lastError = error;
      currentAttempt++;
    }
  }

  throw new RetryError(currentAttempt, lastError!);
}

export function formatDuration(totalSeconds: number): string {
  const absSeconds = Math.abs(totalSeconds);
  let hours = 0;
  let minutes = 0;
  let seconds = 0;

  if (absSeconds < 60) {
    return `${absSeconds}s`;
  } else if (absSeconds < 3600) {
    minutes = Math.floor(absSeconds / 60);
    seconds = absSeconds % 60;
    return `${minutes}m ${seconds.toString().padStart(2, '0')}s`;
  } else {
    hours = Math.floor(absSeconds / 3600);
    minutes = Math.floor((absSeconds % 3600) / 60);
    seconds = absSeconds % 60;
    return `${hours}h ${minutes.toString().padStart(2, '0')}m ${seconds.toString().padStart(2, '0')}s`;
  }
}

export function parseDuration(text: string): number {
  if (!text || text.trim() === '') {
    return NaN;
  }

  const trimmed = text.trim();
  const parts = trimmed.split(/\s+/);

  if (parts.length === 0) {
    return NaN;
  }

  let negative = false;
  if (parts[0] === '-') {
    negative = true;
    parts.shift();
  }

  if (parts.length === 0) {
    return NaN;
  }

  let totalSeconds = 0;

  for (const part of parts) {
    const match = part.match(/^(\d+)([hms])$/);
    if (!match) {
      return NaN;
    }

    const value = parseInt(match[1], 10);
    const unit = match[2];

    switch (unit) {
      case 'h':
        totalSeconds += value * 3600;
        break;
      case 'm':
        totalSeconds += value * 60;
        break;
      case 's':
        totalSeconds += value;
        break;
    }
  }

  return negative ? -totalSeconds : totalSeconds;
}

export class LruCache<K, V> {
  private capacity: number;
  private map: Map<K, V>;
  private order: K[];

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error('Capacity must be at least 1');
    }
    this.capacity = capacity;
    this.map = new Map();
    this.order = [];
  }

  set(key: K, value: V): void {
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.map.set(key, value);
      this.order.splice(index, 1);
    } else {
      this.map.set(key, value);
    }
    this.order.push(key);

    if (this.order.length > this.capacity) {
      const lruKey = this.order.shift()!;
      this.map.delete(lruKey);
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }
    const index = this.order.indexOf(key);
    if (index !== -1) {
      this.order.splice(index, 1);
    }
    this.order.push(key);
    return this.map.get(key);
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    return [...this.order];
  }

  get size(): number {
    return this.map.size;
  }
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return [];
  }

  const result: T[][] = [];
  let startIndex = 0;

  while (startIndex < items.length) {
    const endIndex = Math.min(startIndex + size, items.length);
    result.push(items.slice(startIndex, endIndex));
    startIndex = endIndex;
  }

  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];

  for (let i = 0; i < minLength; i++) {
    result.push({
      first: a[i],
      second: b[i],
    } as Pair<A, B>);
  }

  return result;
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const daysWithRules = new Set<Weekday>();
  for (const rule of rules) {
    daysWithRules.add(rule.day);
  }

  if (daysWithRules.size === 0) {
    return undefined;
  }

  let currentDay = (day + 1) % 7;
  for (let i = 0; i < 7; i++) {
    if (daysWithRules.has(currentDay)) {
      return currentDay;
    }
    currentDay = (currentDay + 1) % 7;
  }

  return undefined;
}

