export interface Token {
  kind: 'number' | 'name' | 'operator' | 'paren';
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const char = source[i];

    if (char === ' ') {
      i++;
      continue;
    }

    if (char >= '0' && char <= '9') {
      let start = i;
      while (i < source.length && source[i] >= '0' && source[i] <= '9') {
        i++;
      }
      if (i < source.length && source[i] === '.') {
        i++;
        if (i >= source.length || !(source[i] >= '0' && source[i] <= '9')) {
          throw new ExpressionError(`Unexpected character '${source[i]}'`, i);
        }
        while (i < source.length && source[i] >= '0' && source[i] <= '9') {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start,
      });
      continue;
    }

    if (char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' || char === '_') {
      let start = i;
      while (i < source.length && (source[i] >= 'a' && source[i] <= 'z' || source[i] >= 'A' && source[i] <= 'Z' || source[i] >= '0' && source[i] <= '9' || source[i] === '_')) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start,
      });
      continue;
    }

    if (char === '+' || char === '-' || char === '*' || char === '/' || char === '%') {
      tokens.push({
        kind: 'operator',
        text: char,
        position: i,
      });
      i++;
      continue;
    }

    if (char === '(' || char === ')') {
      tokens.push({
        kind: 'paren',
        text: char,
        position: i,
      });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${char}'`, i);
  }

  return tokens;
}

interface VariableMap {
  [key: string]: number;
}

function evaluate(source: string, variables: VariableMap): number {
  const tokens = tokenize(source);
  if (tokens.length === 0) {
    throw new ExpressionError('Unexpected end of expression', source.length);
  }

  const pos = { index: 0 };
  const peek = (): Token | undefined => tokens[pos.index];
  const consume = (): Token => {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }
    return tokens[pos.index++];
  };

  const parseOperand = (): number => {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      consume();
      const name = token.text;
      const value = variables[name];
      if (value === undefined) {
        throw new ExpressionError(`Unknown variable '${name}'`, token.position);
      }
      return value;
    }

    if (token.kind === 'operator' && token.text === '-') {
      consume();
      const value = parseOperand();
      return -value;
    }

    if (token.kind === 'paren' && token.text === '(') {
      consume();
      const value = parseExpression();
      const close = consume();
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      return value;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  };

  const parseExpression = (): number => {
    let left = parseTerm();

    while (true) {
      const token = peek();
      if (!token) break;
      if (token.kind === 'operator' && (token.text === '+' || token.text === '-')) {
        consume();
        const right = parseTerm();
        if (token.text === '+') {
          left = left + right;
        } else {
          left = left - right;
        }
      } else {
        break;
      }
    }

    return left;
  };

  const parseTerm = (): number => {
    let left = parseFactor();

    while (true) {
      const token = peek();
      if (!token) break;
      if (token.kind === 'operator' && (token.text === '*' || token.text === '/' || token.text === '%')) {
        consume();
        const right = parseFactor();
        if (token.text === '*') {
          left = left * right;
        } else if (token.text === '/') {
          if (right === 0) {
            throw new ExpressionError('Division by zero', token.position);
          }
          left = left / right;
        } else {
          if (right === 0) {
            throw new ExpressionError('Division by zero', token.position);
          }
          left = left % right;
        }
      } else {
        break;
      }
    }

    return left;
  };

  const parseFactor = (): number => {
    const token = peek();
    if (!token) {
      throw new ExpressionError('Unexpected end of expression', source.length);
    }

    if (token.kind === 'number') {
      consume();
      return parseFloat(token.text);
    }

    if (token.kind === 'name') {
      consume();
      const name = token.text;
      const value = variables[name];
      if (value === undefined) {
        throw new ExpressionError(`Unknown variable '${name}'`, token.position);
      }
      return value;
    }

    if (token.kind === 'operator' && token.text === '-') {
      consume();
      const value = parseFactor();
      return -value;
    }

    if (token.kind === 'paren' && token.text === '(') {
      consume();
      const value = parseExpression();
      const close = consume();
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      return value;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  };

  return parseExpression();
}

