export interface JobOutcome<T> {
  ok: boolean
  value: T | undefined
  error: Error | undefined
}

interface WaitingItem<T> {
  job: () => Promise<T>
  promise: Promise<T>
}

interface JobOrderItem<T> {
  job: () => Promise<T>
  index: number
  outcomePromise: Promise<JobOutcome<T>>
}

export class JobQueue {
  private concurrency: number
  private waitingJobs: Array<WaitingItem<unknown>>
  private runningPromises: Array<Promise<unknown>>
  private completedCount: number
  private failedCount: number
  private isPaused: boolean
  private idlePromise: Promise<void> | null
  private idleResolve: (() => void) | null

  constructor(concurrency: number) {
    this.concurrency = concurrency
    this.waitingJobs = []
    this.runningPromises = []
    this.completedCount = 0
    this.failedCount = 0
    this.isPaused = false
    this.idlePromise = null
    this.idleResolve = null
  }

  get running(): number {
    return this.runningPromises.length
  }

  get waiting(): number {
    return this.waitingJobs.length
  }

  get completed(): number {
    return this.completedCount
  }

  get failed(): number {
    return this.failedCount
  }

  private startNextJob(): void {
    if (this.isPaused) {
      return
    }
    while (this.runningPromises.length < this.concurrency && this.waitingJobs.length > 0) {
      const waitingItem = this.waitingJobs.shift()!
      const job = waitingItem.job
      const promise = job()
      this.runningPromises.push(promise)
      promise.then(
        (value: unknown) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.completedCount++
          this.checkIdle()
        },
        (error: Error) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.failedCount++
          this.checkIdle()
        }
      )
    }
  }

  private checkIdle(): void {
    if (this.runningPromises.length === 0 && this.waitingJobs.length === 0) {
      if (this.idleResolve !== null) {
        this.idleResolve()
        this.idleResolve = null
      }
      this.idlePromise = null
    }
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    if (this.runningPromises.length < this.concurrency && !this.isPaused) {
      const promise = job()
      this.runningPromises.push(promise)
      promise.then(
        (value: T) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.completedCount++
          this.checkIdle()
          this.startNextJob()
        },
        (error: Error) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.failedCount++
          this.checkIdle()
          this.startNextJob()
        }
      )
      return promise
    } else {
      const waitingItem: WaitingItem<T> = { job, promise: null as unknown as Promise<T> }
      const promise = job()
      waitingItem.promise = promise
      this.waitingJobs.push(waitingItem)
      promise.then(
        (value: T) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.completedCount++
          this.checkIdle()
          this.startNextJob()
        },
        (error: Error) => {
          const index = this.runningPromises.indexOf(promise)
          if (index !== -1) {
            this.runningPromises.splice(index, 1)
          }
          this.failedCount++
          this.checkIdle()
          this.startNextJob()
        }
      )
      return promise
    }
  }

  pause(): void {
    this.isPaused = true
  }

  resume(): void {
    this.isPaused = false
    this.startNextJob()
  }

  clear(): number {
    const removedCount = this.waitingJobs.length
    for (let i = 0; i < this.waitingJobs.length; i++) {
      const waitingItem = this.waitingJobs[i]
      const promise = waitingItem.promise
      if (promise !== null) {
        promise.catch(() => {})
      }
      const cancelError = new Error('Job was cancelled')
      const cancelPromise = new Promise<unknown>((resolve, reject) => {
        reject(cancelError)
      })
      this.waitingJobs[i].promise = cancelPromise
    }
    this.waitingJobs = []
    return removedCount
  }

  whenIdle(): Promise<void> {
    if (this.runningPromises.length === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve()
    }
    if (this.idlePromise !== null) {
      return this.idlePromise
    }
    this.idlePromise = new Promise<void>((resolve) => {
      this.idleResolve = resolve
    })
    return this.idlePromise
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const jobOrder: Array<JobOrderItem<T>> = []
    for (let i = 0; i < jobs.length; i++) {
      const item: JobOrderItem<T> = {
        job: jobs[i],
        index: i,
        outcomePromise: null as unknown as Promise<JobOutcome<T>>
      }
      const promise = item.job()
      const outcomePromise = new Promise<JobOutcome<T>>((resolve) => {
        promise.then(
          (value: T) => {
            resolve({ ok: true, value, error: undefined })
          },
          (error: Error) => {
            resolve({ ok: false, value: undefined, error })
          }
        )
      })
      this.add<T>(item.job)
      item.outcomePromise = outcomePromise
      jobOrder.push(item)
    }
    const allOutcomes = Promise.all(jobOrder.map((item) => item.outcomePromise))
    return allOutcomes.then((results: JobOutcome<T>[]) => {
      const orderedResults: JobOutcome<T>[] = []
      for (let i = 0; i < jobOrder.length; i++) {
        orderedResults.push(results[i])
      }
      return orderedResults
    })
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

export class EditorStore {
  private current: EditorState;
  private history: EditorState[];
  private future: EditorState[];
  private historyLimit: number;
  private listeners: Map<string, ((value: string | number | boolean, previous: string | number | boolean) => void)[]>;

  constructor(initial: EditorState, historyLimit: number) {
    this.current = { text: initial.text, cursor: initial.cursor, bold: initial.bold };
    this.history = [];
    this.future = [];
    this.historyLimit = historyLimit;
    this.listeners = new Map();
  }

  get state(): EditorState {
    return { text: this.current.text, cursor: this.current.cursor, bold: this.current.bold };
  }

  apply(patch: Partial<EditorState>): boolean {
    const previousState = { text: this.current.text, cursor: this.current.cursor, bold: this.current.bold };
    let changed = false;

    if (patch.text !== undefined) {
      this.current.text = patch.text;
      changed = true;
    }
    if (patch.cursor !== undefined) {
      this.current.cursor = patch.cursor;
      changed = true;
    }
    if (patch.bold !== undefined) {
      this.current.bold = patch.bold;
      changed = true;
    }

    if (changed) {
      this.history.push(previousState);
      if (this.history.length > this.historyLimit) {
        this.history.shift();
      }
      this.future = [];
      this.notifyListeners(previousState, this.current);
      return true;
    }
    return false;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const previousState = { text: this.current.text, cursor: this.current.cursor, bold: this.current.bold };
    const draft = { text: this.current.text, cursor: this.current.cursor, bold: this.current.bold };

    try {
      run(draft);
    } catch (e) {
      throw e;
    }

    const changed = this.apply(draft);
    if (changed) {
      this.history.push(previousState);
      if (this.history.length > this.historyLimit) {
        this.history.shift();
      }
      this.future = [];
    }

    return changed;
  }

  undo(): boolean {
    if (this.history.length === 0) {
      return false;
    }

    const previousState = this.history.pop()!;
    this.current = { text: previousState.text, cursor: previousState.cursor, bold: previousState.bold };
    this.future.push(this.current);
    this.notifyListeners(this.current, previousState);
    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }

    const nextState = this.future.shift()!;
    this.current = { text: nextState.text, cursor: nextState.cursor, bold: nextState.bold };
    this.notifyListeners(this.current, nextState);
    return true;
  }

  get canUndo(): boolean {
    return this.history.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  watch(field: string, listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    if (field !== 'text' && field !== 'cursor' && field !== 'bold') {
      throw new Error('Invalid field name');
    }

    if (!this.listeners.has(field)) {
      this.listeners.set(field, []);
    }
    this.listeners.get(field)!.push(listener);

    return () => {
      const list = this.listeners.get(field);
      if (list) {
        const index = list.indexOf(listener);
        if (index > -1) {
          list.splice(index, 1);
        }
      }
    };
  }

  private notifyListeners(currentState: EditorState, previousState: EditorState): void {
    for (const [field, listeners] of this.listeners.entries()) {
      const currentValue = currentState[field];
      const previousValue = previousState[field];

      if (currentValue !== previousValue) {
        for (const listener of listeners) {
          listener(currentValue, previousValue);
        }
      }
    }
  }
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result = new Map<string, number>();
  for (let i = 0; i < expenses.length; i++) {
    const expense = expenses[i];
    const category = expense.category;
    const amount = expense.amount;
    if (!result.has(category)) {
      result.set(category, 0);
    }
    const currentSum = result.get(category)!;
    result.set(category, currentSum + amount);
  }
  return result;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  return {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const result: Settings = {
    theme: defaults.theme,
    fontSize: defaults.fontSize,
    notifications: defaults.notifications,
    language: defaults.language,
  };

  if (user.theme !== undefined) {
    result.theme = user.theme;
  }
  if (user.fontSize !== undefined) {
    result.fontSize = user.fontSize;
  }
  if (user.notifications !== undefined) {
    result.notifications = user.notifications;
  }
  if (user.language !== undefined) {
    result.language = user.language;
  }

  return result;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  return {
    min: { x: minX, y: minY },
    max: { x: maxX, y: maxY },
    width: maxX - minX,
    height: maxY - minY,
  };
}

