export class Stack<T> {
  private items: T[]
  private capacity: number

  constructor(capacity: number) {
    this.capacity = capacity
    this.items = []
  }

  push(item: T): boolean {
    if (this.isFull()) {
      return false
    }
    this.items.push(item)
    return true
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined
    }
    return this.items.pop()
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined
    }
    return this.items[this.items.length - 1]
  }

  size(): number {
    return this.items.length
  }

  isEmpty(): boolean {
    return this.items.length === 0
  }

  isFull(): boolean {
    return this.items.length === this.capacity
  }

  clear(): void {
    this.items = []
  }

  toArray(): T[] {
    return [...this.items]
  }
}

interface User {
  id: number;
  name: string;
  email: string;
}

interface RawUser {
  id: number;
  name: string;
  email: string;
}

function parseUsers(json: string): User[] {
  let parsed: RawUser[];
  try {
    parsed = JSON.parse(json);
  } catch {
    return [];
  }

  if (!Array.isArray(parsed)) {
    return [];
  }

  const result: User[] = [];

  for (let i = 0; i < parsed.length; i++) {
    const item = parsed[i];
    if (item === null || typeof item !== 'object') {
      continue;
    }

    const id = item.id;
    const name = item.name;
    const email = item.email;

    if (
      typeof id === 'number' &&
      Number.isInteger(id) &&
      typeof name === 'string' &&
      name.length > 0 &&
      typeof email === 'string' &&
      email.includes('@')
    ) {
      result.push({
        id: id,
        name: name,
        email: email,
      });
    }
  }

  return result;
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Set<Listener<T>>> = new Map();

  on(event: string, listener: Listener<T>): void {
    if (!this.listeners.has(event)) {
      this.listeners.set(event, new Set());
    }
    this.listeners.get(event)!.add(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const set = this.listeners.get(event);
    if (set) {
      set.delete(listener);
      if (set.size === 0) {
        this.listeners.delete(event);
      }
    }
  }

  emit(event: string, payload: T): number {
    const set = this.listeners.get(event);
    if (!set) {
      return 0;
    }
    let count = 0;
    for (const listener of set) {
      listener(payload);
      count++;
    }
    return count;
  }

  listenerCount(event: string): number {
    const set = this.listeners.get(event);
    return set ? set.size : 0;
  }
}

export class RetryError extends Error {
  attempts: number
  lastError: Error

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`)
    this.attempts = attempts
    this.lastError = lastError
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const effectiveAttempts = attempts < 1 ? 1 : attempts
  let currentAttempt = 0
  let lastError: Error | undefined

  while (currentAttempt < effectiveAttempts) {
    try {
      return await action()
    } catch (e) {
      currentAttempt++
      if (e instanceof Error) {
        lastError = e
      } else {
        lastError = new Error(String(e))
      }
    }
  }

  throw new RetryError(currentAttempt, lastError!)
}

export function formatDuration(totalSeconds: number): string {
  const isNegative = totalSeconds < 0
  const absSeconds = isNegative ? -totalSeconds : totalSeconds

  const hours = Math.floor(absSeconds / 3600)
  const remainingAfterHours = absSeconds % 3600
  const minutes = Math.floor(remainingAfterHours / 60)
  const seconds = remainingAfterHours % 60

  let parts: string[] = []

  if (hours > 0) {
    parts.push(String(hours) + 'h')
  }
  if (minutes > 0 || hours > 0) {
    parts.push(String(minutes).padStart(2, '0') + 'm')
  }
  if (seconds > 0 || hours > 0 || minutes > 0) {
    parts.push(String(seconds).padStart(2, '0') + 's')
  }

  const result = parts.join(' ')
  return isNegative ? '-' + result : result
}

export function parseDuration(text: string): number {
  if (text === '') {
    return NaN
  }

  const trimmed = text.trim()
  if (trimmed === '') {
    return NaN
  }

  const parts = trimmed.split(' ')
  if (parts.length === 0) {
    return NaN
  }

  let hasLeadingMinus = false
  let firstPart = parts[0]

  if (firstPart.startsWith('-')) {
    hasLeadingMinus = true
    firstPart = firstPart.substring(1)
  }

  if (firstPart === '') {
    return NaN
  }

  const regex = /^(\d+)([hms])$/
  let totalSeconds = 0
  let valid = true

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]
    const match = part.match(regex)

    if (!match) {
      valid = false
      break
    }

    const value = parseInt(match[1], 10)
    const unit = match[2]

    if (unit === 'h') {
      totalSeconds += value * 3600
    } else if (unit === 'm') {
      totalSeconds += value * 60
    } else if (unit === 's') {
      totalSeconds += value
    }
  }

  if (!valid) {
    return NaN
  }

  if (hasLeadingMinus) {
    totalSeconds = -totalSeconds
  }

  return totalSeconds
}

