function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map();

  if (query.length === 0) {
    return result;
  }

  // Remove leading '?' if present
  let currentQuery = query;
  if (currentQuery.startsWith('?')) {
    currentQuery = currentQuery.substring(1);
  }

  // Split by '&'
  const parts = currentQuery.split('&');

  for (const part of parts) {
    // Skip empty parts
    if (part.length === 0) {
      continue;
    }

    // Split at the first '='
    const eqIndex = part.indexOf('=');
    let key: string;
    let value: string;

    if (eqIndex === -1) {
      // No '=' found: key is the whole part, value is empty
      key = part;
      value = '';
    } else {
      key = part.substring(0, eqIndex);
      value = part.substring(eqIndex + 1);
    }

    // Skip if key is empty
    if (key.length === 0) {
      continue;
    }

    // Decode key and value
    const decodedKey = decodeURIComponentSafe(key);
    const decodedValue = decodeURIComponentSafe(value);

    // Add to map (last value wins, but key keeps first position)
    result.set(decodedKey, decodedValue);
  }

  return result;
}

function decodeURIComponentSafe(str: string): string {
  let result = str.replace(/\+/g, ' ');

  // Find all %XX sequences
  let i = 0;
  while (i < result.length) {
    if (result[i] === '%') {
      if (i + 2 < result.length) {
        const hex = result.substring(i + 1, i + 3);
        // Check if hex is valid (0-9, A-F, a-f)
        if (/^[0-9A-Fa-f]{2}$/.test(hex)) {
          try {
            const byte = parseInt(hex, 16);
            result = result.substring(0, i) + String.fromCharCode(byte) + result.substring(i + 3);
          } catch (e) {
            // If parsing fails for some reason, keep as is (though regex check should prevent this)
          }
        }
        // If not valid hex, leave it as is (only + was replaced above)
      }
    }
    i++;
  }

  return result;
}

interface Pair<A, B> {
  first: A
  second: B
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1 || items.length === 0) {
    return []
  }

  const result: T[][] = []
  let index = 0

  while (index < items.length) {
    const end = index + size
    const chunk: T[] = []
    let i = index
    while (i < end && i < items.length) {
      chunk.push(items[i])
      i++
    }
    result.push(chunk)
    index = end
  }

  return result
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const minLength = a.length < b.length ? a.length : b.length
  const result: Pair<A, B>[] = []

  let i = 0
  while (i < minLength) {
    result.push({
      first: a[i],
      second: b[i]
    })
    i++
  }

  return result
}

enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

interface OpeningRule {
  day: Weekday,
  openHour: number,
  closeHour: number
}

function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true
    }
  }
  return false
}

function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const days: Weekday[] = [
    Weekday.Monday,
    Weekday.Tuesday,
    Weekday.Wednesday,
    Weekday.Thursday,
    Weekday.Friday,
    Weekday.Saturday,
    Weekday.Sunday
  ]

  const startDay = (day + 1) % 7
  for (let i = 0; i < 7; i++) {
    const candidate = (startDay + i) % 7
    for (const rule of rules) {
      if (rule.day === candidate) {
        return candidate
      }
    }
  }
  return undefined
}

