interface Transform {
  (text: string): string;
}

function trim(text: string): string {
  return text.trim();
}

function lowerCase(text: string): string {
  return text.toLowerCase();
}

function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

class Step {
  name: string;
  step: Transform;

  constructor(name: string, step: Transform) {
    this.name = name;
    this.step = step;
  }
}

class Pipeline {
  private steps: Step[] = [];

  add(name: string, step: Transform): Pipeline {
    this.steps.push(new Step(name, step));
    return this;
  }

  run(text: string): string {
    let result = text;
    for (let i = 0; i < this.steps.length; i++) {
      const s = this.steps[i];
      result = s.step(result);
    }
    return result;
  }

  names(): string[] {
    const result: string[] = [];
    for (let i = 0; i < this.steps.length; i++) {
      result.push(this.steps[i].name);
    }
    return result;
  }

  toFunction(): Transform {
    return (text: string): string => {
      let result = text;
      for (let i = 0; i < this.steps.length; i++) {
        const s = this.steps[i];
        result = s.step(result);
      }
      return result;
    };
  }
}

function compose(...steps: Transform[]): Transform {
  if (steps.length === 0) {
    return (text: string): string => text;
  }
  return (text: string): string => {
    let result = text;
    for (let i = 0; i < steps.length; i++) {
      result = steps[i](result);
    }
    return result;
  };
}

export interface Shape {
  area: number;
}

export function circle(radius: number): Shape {
  return {
    area: Math.PI * radius * radius,
  };
}

export function rectangle(width: number, height: number): Shape {
  return {
    area: width * height,
  };
}

export function triangle(base: number, height: number): Shape {
  return {
    area: base * height / 2,
  };
}

export function area(shape: Shape): number {
  return shape.area;
}

export function totalArea(shapes: Shape[]): number {
  let sum = 0;
  for (let i = 0; i < shapes.length; i++) {
    sum += area(shapes[i]);
  }
  return sum;
}

