// solution.ets

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type FieldValue = string | number | boolean;
type FieldName = 'text' | 'cursor' | 'bold';
type Listener = (value: FieldValue, previous: FieldValue) => void;

const FIELD_NAMES: FieldName[] = ['text', 'cursor', 'bold'];

export class EditorStore {
  private current: EditorState;
  private past: EditorState[] = [];
  private future: EditorState[] = [];
  private limit: number;
  private listeners: Record<string, Listener[]> = {
    text: [],
    cursor: [],
    bold: []
  };

  constructor(initial: EditorState, historyLimit: number) {
    this.current = EditorStore.copyState(initial);
    this.limit = historyLimit;
  }

  get state(): EditorState {
    return EditorStore.copyState(this.current);
  }

  get canUndo(): boolean {
    return this.past.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next = this.buildNext(this.current, patch as Record<string, FieldValue | undefined>);
    if (next === null) {
      return false;
    }
    this.commit(next);
    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = EditorStore.copyState(this.current);
    run(draft);
    return this.apply({
      text: draft.text,
      cursor: draft.cursor,
      bold: draft.bold
    });
  }

  undo(): boolean {
    if (this.past.length === 0) {
      return false;
    }
    const before = EditorStore.copyState(this.current);
    this.future.push(before);
    this.current = this.past.pop() as EditorState;
    this.notifyChanged(before, this.current);
    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }
    const before = EditorStore.copyState(this.current);
    this.current = this.future.pop() as EditorState;
    this.past.push(before);
    this.trimHistory();
    this.notifyChanged(before, this.current);
    return true;
  }

  watch(field: string, listener: Listener): () => void {
    const list: Listener[] = this.listeners[field];
    list.push(listener);
    return () => {
      const index = list.indexOf(listener);
      if (index >= 0) {
        list.splice(index, 1);
      }
    };
  }

  private static copyState(source: EditorState): EditorState {
    return {
      text: source.text,
      cursor: source.cursor,
      bold: source.bold
    };
  }

  private buildNext(currentState: EditorState,
    patch: Record<string, FieldValue | undefined>): EditorState | null {
    const next = EditorStore.copyState(currentState);
    const target = next as Record<string, FieldValue>;
    let changed = false;
    for (const field of FIELD_NAMES) {
      const value = patch[field];
      if (value !== undefined && value !== target[field]) {
        target[field] = value;
        changed = true;
      }
    }
    if (!changed) {
      return null;
    }
    return next;
  }

  private commit(next: EditorState): void {
    this.past.push(EditorStore.copyState(this.current));
    this.trimHistory();
    const before = this.current;
    this.current = next;
    this.future = [];
    this.notifyChanged(before, next);
  }

  private trimHistory(): void {
    while (this.past.length > this.limit) {
      this.past.shift();
    }
  }

  private notifyChanged(before: EditorState, after: EditorState): void {
    const previous = before as Record<string, FieldValue>;
    const current = after as Record<string, FieldValue>;
    for (const field of FIELD_NAMES) {
      if (previous[field] !== current[field]) {
        const list: Listener[] = this.listeners[field];
        const snapshot = list.slice();
        for (const listener of snapshot) {
          listener(current[field], previous[field]);
        }
      }
    }
  }
}

