// solution.ets
// A small calculator for arithmetic expressions with variables,
// e.g. `price * (qty - 1) / 2`. Self-contained, stage model, API 12+.

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigit(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

function isNameStart(ch: string): boolean {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || ch === '_';
}

function isNameChar(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

function isOperatorChar(ch: string): boolean {
  return '+-*/%'.indexOf(ch) !== -1;
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    if (ch === ' ') {
      i += 1;
      continue;
    }
    const start = i;
    if (isDigit(ch)) {
      while (i < source.length && isDigit(source[i])) {
        i += 1;
      }
      // A '.' belongs to the number only when it has a digit on both sides.
      if (i + 1 < source.length && source[i] === '.' && isDigit(source[i + 1])) {
        i += 1;
        while (i < source.length && isDigit(source[i])) {
          i += 1;
        }
      }
      tokens.push({ kind: 'number', text: source.substring(start, i), position: start });
      continue;
    }
    if (isNameStart(ch)) {
      i += 1;
      while (i < source.length && isNameChar(source[i])) {
        i += 1;
      }
      tokens.push({ kind: 'name', text: source.substring(start, i), position: start });
      continue;
    }
    if (isOperatorChar(ch)) {
      tokens.push({ kind: 'operator', text: ch, position: start });
      i += 1;
      continue;
    }
    if (ch === '(' || ch === ')') {
      tokens.push({ kind: 'paren', text: ch, position: start });
      i += 1;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${ch}'`, i);
  }
  return tokens;
}

class Parser {
  private readonly tokens: Token[];
  private readonly sourceLength: number;
  private readonly variables: Record<string, number>;
  private index: number;

  constructor(tokens: Token[], sourceLength: number, variables: Record<string, number>) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
    this.variables = variables;
    this.index = 0;
  }

  atEnd(): boolean {
    return this.index >= this.tokens.length;
  }

  current(): Token {
    return this.tokens[this.index];
  }

  // expr := term (('+' | '-') term)*
  parseExpression(): number {
    let value = this.parseTerm();
    while (!this.atEnd()) {
      const token = this.current();
      if (token.kind === 'operator' && (token.text === '+' || token.text === '-')) {
        this.index += 1;
        const right = this.parseTerm();
        if (token.text === '+') {
          value = value + right;
        } else {
          value = value - right;
        }
      } else {
        break;
      }
    }
    return value;
  }

  // term := factor (('*' | '/' | '%') factor)*
  private parseTerm(): number {
    let value = this.parseFactor();
    while (!this.atEnd()) {
      const token = this.current();
      if (token.kind === 'operator' &&
          (token.text === '*' || token.text === '/' || token.text === '%')) {
        this.index += 1;
        const right = this.parseFactor();
        if (token.text === '*') {
          value = value * right;
        } else if (right === 0) {
          throw new ExpressionError('Division by zero', token.position);
        } else if (token.text === '/') {
          value = value / right;
        } else {
          value = value % right;
        }
      } else {
        break;
      }
    }
    return value;
  }

  // factor := '-' factor | primary
  private parseFactor(): number {
    if (this.atEnd()) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    const token = this.current();
    if (token.kind === 'operator' && token.text === '-') {
      this.index += 1;
      return -this.parseFactor();
    }
    return this.parsePrimary();
  }

  // primary := number | name | '(' expr ')'
  private parsePrimary(): number {
    if (this.atEnd()) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    const token = this.current();
    if (token.kind === 'number') {
      this.index += 1;
      return parseFloat(token.text);
    }
    if (token.kind === 'name') {
      this.index += 1;
      const value: number | undefined = this.variables[token.text];
      if (value === undefined) {
        throw new ExpressionError(`Unknown variable '${token.text}'`, token.position);
      }
      return value;
    }
    if (token.kind === 'paren' && token.text === '(') {
      this.index += 1;
      const value = this.parseExpression();
      if (this.atEnd()) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      const closing = this.current();
      if (closing.kind !== 'paren' || closing.text !== ')') {
        throw new ExpressionError(`Unexpected token '${closing.text}'`, closing.position);
      }
      this.index += 1;
      return value;
    }
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
}

export function evaluate(source: string, variables: Record<string, number>): number {
  // Tokenize completely first: lexical errors come before any syntax errors.
  const parser = new Parser(tokenize(source), source.length, variables);
  const value = parser.parseExpression();
  if (!parser.atEnd()) {
    const token = parser.current();
    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
  return value;
}

