/**
 * Thrown when a task lists a dependency that is not a task of the plan.
 */
export class MissingDependencyError extends Error {
  public readonly task: string;
  public readonly dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

/**
 * Thrown when the dependency graph of the plan contains a cycle.
 */
export class CycleError extends Error {
  public readonly path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

/**
 * A validated build plan: every key of the spec is a task, its value lists
 * the tasks it depends on.
 */
export class BuildPlan {
  private readonly names: string[];
  private readonly deps: Map<string, string[]>;

  constructor(spec: Record<string, string[]>) {
    this.names = Object.keys(spec);
    this.deps = new Map<string, string[]>();
    for (const name of this.names) {
      const list = spec[name] as string[] | undefined;
      this.deps.set(name, list === undefined ? [] : list.slice());
    }

    // First check: every dependency must be a key of the spec. Tasks are
    // checked in key order, each dependency list in its own order.
    for (const name of this.names) {
      for (const dep of this.depsOf(name)) {
        if (!this.deps.has(dep)) {
          throw new MissingDependencyError(name, dep);
        }
      }
    }

    // Second check: place the tasks exactly as described for order().
    // The tasks whose placing has started but not finished form the chain.
    // Reaching a task that is already in the chain means there is a cycle.
    const IN_PROGRESS = 1;
    const DONE = 2;
    const state = new Map<string, number>();
    const chain: string[] = [];
    const visit = (task: string): void => {
      const st = state.get(task);
      if (st === DONE) {
        return;
      }
      if (st === IN_PROGRESS) {
        const path = chain.slice(chain.indexOf(task));
        path.push(task);
        throw new CycleError(path);
      }
      state.set(task, IN_PROGRESS);
      chain.push(task);
      for (const dep of this.depsOf(task)) {
        visit(dep);
      }
      chain.pop();
      state.set(task, DONE);
    };
    for (const name of this.names) {
      visit(name);
    }
  }

  private depsOf(task: string): string[] {
    return this.deps.get(task) as string[];
  }

  /**
   * Every task once, each after all the tasks it depends on: go through the
   * tasks in key order and place each one; placing a task first places each
   * of its dependencies in list order, then the task itself.
   */
  public order(): string[] {
    const result: string[] = [];
    const placed = new Set<string>();
    const place = (task: string): void => {
      if (placed.has(task)) {
        return;
      }
      for (const dep of this.depsOf(task)) {
        place(dep);
      }
      placed.add(task);
      result.push(task);
    };
    for (const name of this.names) {
      place(name);
    }
    return result;
  }

  /**
   * Tasks grouped for parallel running. Layer 0 holds the tasks that depend
   * on nothing; every other task sits right after the highest layer of its
   * dependencies. Within a layer the tasks are in key order.
   */
  public layers(): string[][] {
    const layerOf = new Map<string, number>();
    const computeLayer = (task: string): number => {
      const cached = layerOf.get(task);
      if (cached !== undefined) {
        return cached;
      }
      let layer = 0;
      for (const dep of this.depsOf(task)) {
        const depLayer = computeLayer(dep);
        if (depLayer + 1 > layer) {
          layer = depLayer + 1;
        }
      }
      layerOf.set(task, layer);
      return layer;
    };
    const layers: string[][] = [];
    for (const name of this.names) {
      const layer = computeLayer(name);
      while (layers.length <= layer) {
        layers.push([]);
      }
      layers[layer].push(name);
    }
    return layers;
  }

  /**
   * Every task that depends on `name`, directly or through other tasks, in
   * the order they have in order(). `name` itself is not included. Unknown
   * names yield an empty array.
   */
  public dependentsOf(name: string): string[] {
    if (!this.deps.has(name)) {
      return [];
    }
    // Reverse edges: for each task, the tasks that list it as a dependency.
    const reverse = new Map<string, string[]>();
    for (const task of this.names) {
      for (const dep of this.depsOf(task)) {
        let list: string[] | undefined = reverse.get(dep);
        if (list === undefined) {
          list = [];
          reverse.set(dep, list);
        }
        list.push(task);
      }
    }
    // Collect every task that can reach `name` through dependency edges.
    const found = new Set<string>();
    const queue: string[] = [name];
    let head = 0;
    while (head < queue.length) {
      const current = queue[head];
      head += 1;
      const list = reverse.get(current);
      if (list === undefined) {
        continue;
      }
      for (const task of list) {
        if (!found.has(task)) {
          found.add(task);
          queue.push(task);
        }
      }
    }
    found.delete(name);
    const result: string[] = [];
    for (const task of this.order()) {
      if (found.has(task)) {
        result.push(task);
      }
    }
    return result;
  }
}

/**
 * A single expense record.
 */
export interface Expense {
  category: string;
  amount: number;
}

/**
 * Sums the amounts of all expenses grouped by category.
 *
 * Categories appear in the returned map in the order they first
 * appear in the input array. An empty input yields an empty map.
 *
 * @param expenses the list of expenses to aggregate
 * @returns a map from category name to the total amount for that category
 */
export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();

  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }

  return totals;
}

