/**
 * Modal dialog for changing the daily goal.
 * The dialog never changes the goal itself: on Save it only hands the typed
 * number to the callback that the page handed over.
 */
@CustomDialog
struct GoalDialog {
  controller?: CustomDialogController;
  onGoalChosen: (glasses: number) => void = (glasses: number): void => {};
  @State typedText: string = '';

  aboutToAppear(): void {
    // The field starts empty every time the dialog opens.
    this.typedText = '';
  }

  /**
   * Returns the typed value if it is a whole number of 1 or more, else 0.
   */
  private parseTypedGoal(): number {
    const trimmed: string = this.typedText.trim();
    if (trimmed.length === 0) {
      return 0;
    }
    const value: number = Number(trimmed);
    if (!Number.isInteger(value) || value < 1) {
      return 0;
    }
    return value;
