      TextInput({ placeholder: 'Glasses per day', text: this.typedText })
        .type(InputType.Number)
        .width('100%')
        .onChange((value: string) => {
          this.typedText = value;
        })

      Row({ space: 8 }) {
        ForEach(GOAL_PRESETS, (preset: GoalPreset) => {
          Button(preset.label)
            .layoutWeight(1)
            .backgroundColor('#F1F3F5')
