/**
 * Fully specified application settings.
 */
export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

/**
 * Partial settings a user may override; every field is optional.
 */
export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

/**
 * Returns the default settings.
 * Every call creates and returns a brand-new object.
 */
export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
  return settings;
}

/**
 * Merges user overrides on top of the defaults.
 *
 * - A field present in `user` wins, even when its value is false, 0 or ''.
 * - A field absent from `user` falls back to the value in `defaults`.
 * - Neither argument is modified; a fresh Settings object is returned.
 */
export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications:
      user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language,
  };
  return merged;
}

/**
 * A point in two-dimensional space.
 */
export interface Point {
  x: number;
  y: number;
}

/**
 * An axis-aligned rectangle described by its extreme corners and its size.
 */
export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

/**
 * Computes the smallest axis-aligned rectangle that contains every point.
 *
 * - Returns undefined for an empty input.
 * - The input array is never modified.
 * - The returned min and max are always freshly created objects,
 *   never references to points from the input.
 */
export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = {
    x: minX,
    y: minY
  };

  const max: Point = {
    x: maxX,
    y: maxY
  };

  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };

  return box;
}

/**
 * A fixed-capacity, last-in first-out (LIFO) stack.
 *
 * The bottom of the stack is the start of the internal array and the top
 * of the stack is its end.
 */
export class Stack<T> {
  private capacity: number;
  private items: T[] = [];

  constructor(capacity: number) {
    this.capacity = capacity > 0 ? capacity : 0;
  }

  /**
   * Puts item on top of the stack.
   *
   * @returns true when the item was added; false when the stack is full
   *          (in which case nothing is changed).
   */
  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes the top item and returns it.
   *
   * @returns the former top item, or undefined when the stack is empty.
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it.
   *
   * @returns the top item, or undefined when the stack is empty.
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /** @returns the number of items currently held. */
  size(): number {
    return this.items.length;
  }

  /** @returns true when the stack holds no items. */
  isEmpty(): boolean {
    return this.items.length === 0;
  }

  /** @returns true when the stack holds its maximum number of items. */
  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /** Removes every item from the stack. */
  clear(): void {
    this.items = [];
  }

  /**
   * Returns the items from bottom to top as a new array.
   * Mutating the returned array does not affect the stack.
   */
  toArray(): T[] {
    return this.items.slice();
  }
}

// solution.ets
// Self-contained: no imports required.

/**
 * A listener receives one payload of type T and returns nothing.
 */
export type Listener<T> = (payload: T) => void;

/**
 * EventBus keeps a list of listeners per event name.
 * Events are independent of each other.
 */
export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
    this.listeners = new Map<string, Listener<T>[]>();
  }

  /**
   * Registers `listener` for `event`.
   * Registering the same function again for the same event does nothing.
   */
  on(event: string, listener: Listener<T>): void {
    let list = this.listeners.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.listeners.set(event, list);
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        // Already registered for this event: nothing changes.
        return;
      }
    }
    list.push(listener);
  }

  /**
   * Removes `listener` from `event`.
   * Does nothing when that listener is not registered for that event.
   */
  off(event: string, listener: Listener<T>): void {
    let list = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    for (let i = 0; i < list.length; i++) {
      if (list[i] === listener) {
        list.splice(i, 1);
        return;
      }
    }
  }

  /**
   * Calls every listener registered for `event` with `payload`,
   * in the order they were registered, and returns how many listeners
   * it called. Returns 0 when the event has no listeners.
   *
   * The set of listeners is captured when emit starts: a listener that
   * calls `on` or `off` while it runs only affects later emit calls.
   */
  emit(event: string, payload: T): number {
    let list = this.listeners.get(event);
    if (list === undefined || list.length === 0) {
      return 0;
    }
    // Snapshot taken before the first listener runs.
    let snapshot: Listener<T>[] = list.slice();
    let called = 0;
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
      called++;
    }
    return called;
  }

  /**
   * Returns how many listeners are registered for `event`.
   */
  listenerCount(event: string): number {
    let list = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

// solution.ets
//
// Shapes are modeled with an abstract base class so that new kinds of
// shapes can be added later simply by extending Shape, without changing
// any of the existing code (open/closed principle).

export abstract class Shape {
  public abstract area(): number;
}

class Circle extends Shape {
  private readonly radius: number;

  constructor(radius: number) {
    super();
    this.radius = radius;
  }

  public area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle extends Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    super();
    this.width = width;
    this.height = height;
  }

  public area(): number {
    return this.width * this.height;
  }
}

class Triangle extends Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    super();
    this.base = base;
    this.height = height;
  }

  public area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += shape.area();
  }
  return sum;
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const total: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('unknown');
  for (let i: number = 1; i <= total; i++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }
  throw new RetryError(total, lastError);
}

/**
 * A valid user record that can be produced by parseUsers.
 */
export interface User {
  id: number;
  name: string;
  email: string;
}

/**
 * Parses a JSON text and returns the valid users found in it.
 *
 * The text is expected to be a JSON array. If the text is not valid JSON,
 * or its top-level value is not an array, an empty array is returned.
 * This function never throws.
 *
 * An element of the array is a valid user when it is an object whose `id`
 * is an integer number, whose `name` is a non-empty string and whose
 * `email` is a string containing '@'. All other elements are skipped.
 * Each returned user contains exactly the fields `id`, `name` and `email`,
 * in the order in which they appear in the input.
 */
export function parseUsers(json: string): User[] {
  const result: User[] = [];

  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(json) as Object | null;
  } catch (e) {
    // Invalid JSON: never throw, just report no users.
    return result;
  }

  // The top-level value must be an array.
  if (parsed === null || !Array.isArray(parsed)) {
    return result;
  }

  const items = parsed as Array<Object>;

  for (const item of items) {
    // Skip null, numbers, strings, booleans and nested arrays.
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      continue;
    }

    const obj = item as Record<string, Object>;

    // id: must be an integer number ("7" is a string, not a number).
    const idValue = obj['id'];
    if (typeof idValue !== 'number') {
      continue;
    }
    const id = idValue as number;
    if (!Number.isInteger(id)) {
      continue;
    }

    // name: must be a non-empty string.
    const nameValue = obj['name'];
    if (typeof nameValue !== 'string') {
      continue;
    }
    const name = nameValue as string;
    if (name.length === 0) {
      continue;
    }

    // email: must be a string containing '@'.
    const emailValue = obj['email'];
    if (typeof emailValue !== 'string') {
      continue;
    }
    const email = emailValue as string;
    if (!email.includes('@')) {
      continue;
    }

    // Build a fresh user with exactly the three required fields;
    // any extra fields of the source element are dropped.
    const user: User = { id: id, name: name, email: email };
    result.push(user);
  }

  return result;
}

// solution.ets

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  if (size < 1) {
    return [];
  }
  const result: T[][] = [];
  for (let i = 0; i < items.length; i += size) {
    const group: T[] = [];
    const end: number = Math.min(i + size, items.length);
    for (let j: number = i; j < end; j++) {
      group.push(items[j]);
    }
    result.push(group);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const length: number = Math.min(a.length, b.length);
  const result: Pair<A, B>[] = [];
  for (let i: number = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

