/**
 * The seven days of the week. The week runs from Monday to Sunday.
 */
export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

/**
 * One opening rule: the place is open on `day` from `openHour`
 * (inclusive) up to `closeHour` (exclusive). A day may have several
 * rules; a day with no rule is closed all day.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Returns true when at least one rule covers the given day and hour,
 * i.e. some rule for that day whose openHour <= hour < closeHour.
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the first day strictly after `day` that has at least one rule,
 * walking forward through the week and wrapping from Sunday back to Monday.
 * `day` itself is the last candidate (step 7), so if it is the only day
 * with a rule, it is returned as the answer one week later. If no day has
 * a rule, returns undefined.
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  for (let step = 1; step <= 7; step++) {
    const candidate = ((day + step) % 7) as Weekday;
    for (const rule of rules) {
      if (rule.day === candidate) {
        return candidate;
      }
    }
  }
  return undefined;
}

/*
 * solution.ets
 * Self-contained text transformation utilities with a chainable pipeline.
 * No imports required.
 */

/** A function that takes one string and returns a string. */
export type Transform = (text: string) => string;

/** Removes whitespace from both ends of the text. */
export function trim(text: string): string {
  return text.trim();
}

/** Turns the text into lower case. */
export function lowerCase(text: string): string {
  return text.toLowerCase();
}

/** Replaces every run of whitespace characters (spaces, tabs, line breaks) with one space. */
export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

/** Internal holder for a single named pipeline step. */
class PipelineStep {
  private readonly stepName: string;
  private readonly stepTransform: Transform;

  constructor(name: string, transform: Transform) {
    this.stepName = name;
    this.stepTransform = transform;
  }

  getName(): string {
    return this.stepName;
  }

  apply(text: string): string {
    return this.stepTransform(text);
  }
}

/** An ordered list of named transformation steps. */
export class Pipeline {
  private steps: PipelineStep[] = [];

  /** Adds a step at the end and returns the pipeline itself for chaining. */
  add(name: string, step: Transform): Pipeline {
    this.steps.push(new PipelineStep(name, step));
    return this;
  }

  /** Passes the text through every step in the order they were added. */
  run(text: string): string {
    let result: string = text;
    for (const step of this.steps) {
      result = step.apply(result);
    }
    return result;
  }

  /** Returns the step names in order, as a new array. */
  names(): string[] {
    const result: string[] = [];
    for (const step of this.steps) {
      result.push(step.getName());
    }
    return result;
  }

  /**
   * Returns a standalone function that behaves like `run`.
   * The returned function reads the live step list, so it also
   * applies steps added after it was created.
   */
  toFunction(): Transform {
    return (text: string): string => {
      return this.run(text);
    };
  }
}

/** Returns one function applying the given steps from first to last. */
export function compose(...steps: Transform[]): Transform {
  return (text: string): string => {
    let result: string = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
}

