/**
 * Duration formatting and parsing helpers.
 *
 * Text shape produced/consumed:
 *   below 1 minute : "0s", "59s"
 *   below 1 hour   : "1m 00s", "12m 34s"
 *   1 hour and up  : "1h 05m 09s", "100h 00m 00s"
 * Negative values get a leading "-" in front of the same text.
 */

function padTwo(value: number): string {
  return value < 10 ? `0${value}` : `${value}`;
}

/**
 * Formats a whole number of seconds as a duration text.
 * Hours are never converted into days.
 */
export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const absValue: number = Math.abs(totalSeconds);

  const seconds: number = absValue % 60;
  const totalMinutes: number = Math.floor(absValue / 60);
  const minutes: number = totalMinutes % 60;
  const hours: number = Math.floor(totalMinutes / 60);

  const sign: string = negative ? '-' : '';

  if (hours > 0) {
    return `${sign}${hours}h ${padTwo(minutes)}m ${padTwo(seconds)}s`;
  }
  if (totalMinutes > 0) {
    return `${sign}${totalMinutes}m ${padTwo(seconds)}s`;
  }
  return `${sign}${seconds}s`;
}

/**
 * Parses a duration text and returns the total number of seconds.
 *
 * The text must consist of one or more parts separated by single spaces;
 * every part is one or more digits followed by "h", "m" or "s".
 * A leading "-" makes the result negative. Anything else yields NaN.
 */
export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let body: string = text;
  let sign: number = 1;
  if (body.charAt(0) === '-') {
    sign = -1;
    body = body.substring(1);
  }
  if (body.length === 0) {
    return NaN;
  }

  // Empty entries produced by leading, trailing or doubled spaces fail below.
  const parts: string[] = body.split(' ');
  let total: number = 0;

  for (const part of parts) {
    if (part.length < 2) {
      return NaN;
    }

    const unit: string = part.charAt(part.length - 1);
    let multiplier: number;
    if (unit === 'h') {
      multiplier = 3600;
    } else if (unit === 'm') {
      multiplier = 60;
    } else if (unit === 's') {
      multiplier = 1;
    } else {
      return NaN;
    }

    const digits: string = part.substring(0, part.length - 1);
    for (let i = 0; i < digits.length; i++) {
      const code: number = digits.charCodeAt(i);
      if (code < 48 || code > 57) { // outside '0'..'9'
        return NaN;
      }
    }

    total += parseInt(digits, 10) * multiplier;
  }

  const result: number = sign * total;
  return result === 0 ? 0 : result;
}

