@Entry
@Component
struct Solution {
  @State selectedIndices: number[] = [];

  aboutToAppear() {
    this.selectedIndices = [];
  }

  build() {
    Column() {
      Text('Selected: ' + this.selectedIndices.length)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 20 })

      Grid(columns: [GridItem(.33), GridItem(.33), GridItem(.33)]) {
        ForEach(this.selectedIndices, (index: number) => {
          GridItem() {
            this._buildTile(index + 1)
          }
        }, (index: number) => index)
      }
