    const isSelected = this.selectedIndices.includes(number);
    const backgroundColor = isSelected ? Color.Blue : Color.White;
    const textColor = isSelected ? Color.White : Color.Black;

    GridItem() {
      Column() {
        Text('' + number)
          .fontSize(24)
          .fontWeight(FontWeight.Bold)
          .color(textColor)
          .textAlign(TextAlign.Center)
