      .width('100%')
      .height('100%')
      .backgroundColor(backgroundColor)
      .borderRadius(BorderRadius.Circle)
      .onClick(() => {
        if (isSelected) {
          const newIndices = this.selectedIndices.filter((i) => i !== number);
          this.selectedIndices = newIndices;
        } else {
          this.selectedIndices.push(number);
        }
      })
    }
  }
}

