// solution.ets
// Self-contained: no imports required.

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

/**
 * Returns a new array with the same items in the same order, where the item
 * with the given `id` carries the new `quantity` as a fresh object.
 * If `quantity` is 0 or less, that item is left out of the result.
 * If no item has the given `id`, the result simply holds the same items.
 * Never mutates `items` or any object inside it.
 */
export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (let i = 0; i < items.length; i++) {
    const item: Item = items[i];
    if (item.id !== id) {
      // Unchanged items keep their identity (same object references).
      result.push(item);
    } else if (quantity > 0) {
      // The changed item is a brand-new object; the original is untouched.
      const updated: Item = {
        id: item.id,
        name: item.name,
        quantity: quantity
      };
      result.push(updated);
    }
    // If the id matches and quantity <= 0, the item is omitted entirely.
  }
  return result;
}

/**
 * Applies the changes one after another, each following the rules of
 * updateQuantity, and returns the final list.
 * Once a change has removed an item, later changes to the same `id` do
 * nothing, because the item is no longer present in the list.
 * Never mutates `items`, `changes` or any object inside them.
 */
export function applyChanges(items: Item[], changes: Change[]): Item[] {
  // Start from a copy so the returned array never aliases the input array.
  let current: Item[] = items.slice();
  for (let i = 0; i < changes.length; i++) {
    const change: Change = changes[i];
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

