// solution.ets
// Entry page: fetches https://example.com/api/items and displays the item names.

import http from '@ohos.net.http';

interface Item {
  id: number;
  name: string;
}

type LoadState = 'loading' | 'success' | 'error';

@Entry
@Component
struct Index {
  @State private items: Item[] = [];
  @State private state: LoadState = 'loading';

  aboutToAppear(): void {
    this.fetchItems();
  }

  private fetchItems(): void {
    const client: http.HttpRequest = http.createHttp();

    client.request(
      'https://example.com/api/items',
      {
        method: http.RequestMethod.GET,
        connectTimeout: 10000,
        readTimeout: 10000
      }
    )
      .then((response: http.HttpResponse) => {
        if (response.responseCode === 200) {
          const body: string = response.result as string;
          try {
            const parsed: Item[] = JSON.parse(body) as Item[];
            this.items = parsed;
            this.state = 'success';
          } catch (e) {
            this.state = 'error';
          }
        } else {
          this.state = 'error';
        }
      })
      .catch(() => {
        this.state = 'error';
      })
      .finally(() => {
        client.destroy();
      });
  }

  build() {
    Column() {
      if (this.state === 'loading') {
        Text('Loading...')
          .fontSize(20)
          .margin(20)
      } else if (this.state === 'error') {
        Text('Could not load the items')
          .fontSize(20)
          .fontColor('#C52828')
          .margin(20)
      } else {
        List() {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(18)
                .width('100%')
                .padding(12)
            }
          }, (item: Item) => item.id.toString())
        }
        .layoutWeight(1)
        .width('100%')
      }
    }
    .width('100%')
    .height('100%')
  }
}

