// solution.ets
// Entry page: shows the persisted name, lets the user type a new one and save it.
// The name is stored with data preferences, so it survives closing and reopening the app.

import { preferences } from '@kit.ArkData';
import { hilog } from '@kit.PerformanceAnalysisKit';

const DOMAIN: number = 0x0001;
const TAG: string = 'NamePage';
const PREF_STORE: string = 'name_store';
const KEY_NAME: string = 'name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State typedName: string = '';
  private prefs: preferences.Preferences | null = null;

  aboutToAppear(): void {
    this.initPreferences();
    this.readSavedName();
  }

  private initPreferences(): void {
    try {
      const context = getContext(this);
      this.prefs = preferences.getPreferencesSync(context, { name: PREF_STORE });
    } catch (err) {
      hilog.error(DOMAIN, TAG, 'Failed to open preferences: %{public}s', JSON.stringify(err));
      this.prefs = null;
    }
  }

  private readSavedName(): void {
    if (this.prefs === null) {
      return;
    }
    try {
      const value: preferences.ValueType = this.prefs.getSync(KEY_NAME, '');
      this.savedName = typeof value === 'string' ? value : '';
    } catch (err) {
      hilog.error(DOMAIN, TAG, 'Failed to read name: %{public}s', JSON.stringify(err));
    }
  }

  private saveName(): void {
    const name: string = this.typedName.trim();
    if (name.length === 0 || this.prefs === null) {
      return;
    }
    try {
      this.prefs.putSync(KEY_NAME, name);
      this.prefs.flushSync();
      this.savedName = name;
    } catch (err) {
      hilog.error(DOMAIN, TAG, 'Failed to save name: %{public}s', JSON.stringify(err));
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Medium)
        .textAlign(TextAlign.Center)

      TextInput({ placeholder: 'Type your name here' })
        .type(InputType.Normal)
        .height(48)
        .onChange((value: string) => {
          this.typedName = value;
        })

      Button('Save')
        .width(120)
        .height(40)
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(16)
  }
}

