export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueEntry {
  run: (() => Promise<Object>) | undefined = undefined;
  resolve: ((value: Object) => void) | undefined = undefined;
  reject: ((err: Error) => void) | undefined = undefined;
}

export class JobQueue {
  private limit: number;
  private queue: Array<QueueEntry> = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private pausedFlag: boolean = false;
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (!Number.isInteger(concurrency) || concurrency < 1) {
      throw new Error('concurrency must be a whole number of at least 1');
    }
    this.limit = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.queue.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    const entry: QueueEntry = new QueueEntry();
    const promise = new Promise<T>((resolve: (value: T) => void, reject: (err: Error) => void) => {
      entry.run = job as Object as () => Promise<Object>;
      entry.resolve = resolve as Object as (value: Object) => void;
      entry.reject = reject;
    });
    this.queue.push(entry);
    this.pump();
    return promise;
  }

  pause(): void {
    this.pausedFlag = true;
  }

  resume(): void {
    this.pausedFlag = false;
    this.pump();
  }

  clear(): number {
    const removed: Array<QueueEntry> = this.queue;
    this.queue = [];
    for (const entry of removed) {
      const reject = entry.reject;
      if (reject !== undefined) {
        reject(new Error('Job was cancelled'));
      }
    }
    this.checkIdle();
    return removed.length;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.queue.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve: () => void) => {
      this.idleResolvers.push(resolve);
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const promises: Array<Promise<JobOutcome<T>>> = [];
    for (const job of jobs) {
      const p: Promise<JobOutcome<T>> = this.add<T>(job)
        .then((value: T): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          return outcome;
        })
        .catch((err: Object): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: err as Error };
          return outcome;
        });
      promises.push(p);
    }
    return Promise.all(promises);
  }

  private pump(): void {
    while (!this.pausedFlag && this.runningCount < this.limit && this.queue.length > 0) {
      const entry: QueueEntry | undefined = this.queue.shift();
      if (entry === undefined) {
        break;
      }
      this.startEntry(entry);
    }
  }

  private startEntry(entry: QueueEntry): void {
    const run = entry.run;
    const resolve = entry.resolve;
    const reject = entry.reject;
    if (run === undefined || resolve === undefined || reject === undefined) {
      return;
    }
    this.runningCount++;
    run().then((value: Object): void => {
      this.runningCount--;
      this.completedCount++;
      resolve(value);
      this.pump();
      this.checkIdle();
    }).catch((err: Object): void => {
      this.runningCount--;
      this.failedCount++;
      reject(err as Error);
      this.pump();
      this.checkIdle();
    });
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.queue.length === 0) {
      const resolvers: Array<() => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (const r of resolvers) {
        r();
      }
    }
  }
}

/**
 * Least-recently-used cache.
 *
 * Recency order is tracked with a doubly linked list: `least` points to the
 * least recently used entry and `most` to the most recently used one. A Map
 * gives O(1) lookup and provides the required key identity semantics:
 * the number 1 and the string '1' are different keys, and objects are the
 * same key only when they are the same object.
 */

class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private readonly capacity: number;
  private readonly nodes: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  private least: LruNode<K, V> | null = null;
  private most: LruNode<K, V> | null = null;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  get size(): number {
    return this.nodes.size;
  }

  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.nodes.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.touch(existing);
      return;
    }
    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.nodes.set(key, node);
    this.append(node);
    if (this.nodes.size > this.capacity) {
      this.evictLeast();
    }
  }

  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.nodes.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.touch(node);
    return node.value;
  }

  has(key: K): boolean {
    return this.nodes.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    let current: LruNode<K, V> | null = this.least;
    while (current !== null) {
      result.push(current.key);
      current = current.next;
    }
    return result;
  }

  private touch(node: LruNode<K, V>): void {
    this.unlink(node);
    this.append(node);
  }

  private unlink(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | null = node.prev;
    const next: LruNode<K, V> | null = node.next;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.least = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.most = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private append(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | null = this.most;
    node.prev = prev;
    node.next = null;
    if (prev !== null) {
      prev.next = node;
    } else {
      this.least = node;
    }
    this.most = node;
  }

  private evictLeast(): void {
    const node: LruNode<K, V> | null = this.least;
    if (node !== null) {
      this.unlink(node);
      this.nodes.delete(node.key);
    }
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

function isJsonObject(v: Object | null): boolean {
  return v !== null && !Array.isArray(v) && typeof v === 'object';
}

export function parseOrder(text: string): ParseResult {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(text) as Object;
  } catch (e) {
    const err: FieldError = { path: '', message: 'invalid JSON' };
    const errs: FieldError[] = [err];
    const res: ParseResult = { order: undefined, errors: errs };
    return res;
  }
  if (!isJsonObject(parsed)) {
    const err: FieldError = { path: '', message: 'expected an object' };
    const errs: FieldError[] = [err];
    const res: ParseResult = { order: undefined, errors: errs };
    return res;
  }

  const errors: FieldError[] = [];
  const add = (path: string, message: string): void => {
    const fe: FieldError = { path: path, message: message };
    errors.push(fe);
  };

  const rec: Record<string, Object | null> = parsed as Record<string, Object | null>;
  const keys: string[] = Object.keys(rec);

  let idValue: string = '';
  if (!keys.includes('id') || rec['id'] === null) {
    add('id', 'required');
  } else {
    const v: Object | null = rec['id'];
    if (typeof v !== 'string') {
      add('id', 'expected a string');
    } else {
      const s: string = v as string;
      if (s === '') {
        add('id', 'must not be empty');
      } else {
        idValue = s;
      }
    }
  }

  let statusValue: OrderStatus = OrderStatus.Draft;
  if (keys.includes('status') && rec['status'] !== null) {
    const v: Object | null = rec['status'];
    let recognized: boolean = false;
    if (typeof v === 'string') {
      const s: string = v as string;
      if (s === 'draft') {
        statusValue = OrderStatus.Draft;
        recognized = true;
      } else if (s === 'paid') {
        statusValue = OrderStatus.Paid;
        recognized = true;
      } else if (s === 'shipped') {
        statusValue = OrderStatus.Shipped;
        recognized = true;
      }
    }
    if (!recognized) {
      add('status', 'expected one of draft, paid, shipped');
    }
  }

  let linesArr: Object[] = [];
  if (!keys.includes('lines') || rec['lines'] === null) {
    add('lines', 'required');
  } else {
    const lv: Object | null = rec['lines'];
    if (!Array.isArray(lv)) {
      add('lines', 'expected an array');
    } else {
      const arr: Object[] = lv as Object[];
      if (arr.length === 0) {
        add('lines', 'must not be empty');
      } else {
        linesArr = arr;
        for (let i = 0; i < arr.length; i++) {
          const el: Object | null = arr[i];
          if (!isJsonObject(el)) {
            add(`lines[${i}]`, 'expected an object');
          } else {
            const lrec: Record<string, Object | null> = el as Record<string, Object | null>;
            const lkeys: string[] = Object.keys(lrec);
            const prefix: string = `lines[${i}]`;

            if (!lkeys.includes('sku') || lrec['sku'] === null) {
              add(`${prefix}.sku`, 'required');
            } else {
              const sv: Object | null = lrec['sku'];
              if (typeof sv !== 'string') {
                add(`${prefix}.sku`, 'expected a string');
              } else if ((sv as string) === '') {
                add(`${prefix}.sku`, 'must not be empty');
              }
            }

            if (!lkeys.includes('quantity') || lrec['quantity'] === null) {
              add(`${prefix}.quantity`, 'required');
            } else {
              const qv: Object | null = lrec['quantity'];
              if (typeof qv !== 'number') {
                add(`${prefix}.quantity`, 'expected a number');
              } else {
                const q: number = qv as number;
                if (!Number.isInteger(q) || q < 1) {
                  add(`${prefix}.quantity`, 'must be a whole number of 1 or more');
                }
              }
            }

            if (!lkeys.includes('unitPrice') || lrec['unitPrice'] === null) {
              add(`${prefix}.unitPrice`, 'required');
            } else {
              const uv: Object | null = lrec['unitPrice'];
              if (typeof uv !== 'number') {
                add(`${prefix}.unitPrice`, 'expected a number');
              } else {
                const up: number = uv as number;
                if (up < 0) {
                  add(`${prefix}.unitPrice`, 'must be 0 or more');
                }
              }
            }

            for (const k of lkeys) {
              if (k !== 'sku' && k !== 'quantity' && k !== 'unitPrice') {
                add(`${prefix}.${k}`, 'unknown field');
              }
            }
          }
        }
      }
    }
  }

  for (const k of keys) {
    if (k !== 'id' && k !== 'status' && k !== 'lines') {
      add(k, 'unknown field');
    }
  }

  if (errors.length > 0) {
    const res: ParseResult = { order: undefined, errors: errors };
    return res;
  }

  const lines: OrderLine[] = [];
  for (let i = 0; i < linesArr.length; i++) {
    const lrec: Record<string, Object | null> = linesArr[i] as Record<string, Object | null>;
    const sku: string = lrec['sku'] as string;
    const quantity: number = lrec['quantity'] as number;
    const unitPrice: number = lrec['unitPrice'] as number;
    lines.push(new OrderLine(sku, quantity, unitPrice));
  }

  const order: Order = { id: idValue, status: statusValue, lines: lines };
  const res: ParseResult = { order: order, errors: errors };
  return res;
}

/**
 * Entry page of the app.
 *
 * The dark mode setting is app-wide state kept in AppStorage under the
 * 'darkMode' key (off by default). The page binds to it with @StorageLink
 * (read/write) and the child components read it on their own with
 * @StorageProp (read-only), so every reader is re-rendered as soon as the
 * switch is flipped — no parameters are passed down.
 */

@Entry
@Component
struct DarkModePage {
  // Two-way binding with AppStorage. If the key does not exist yet, it is
  // created with the initial value `false` (dark mode off at the start).
  @StorageLink('darkMode') isDarkMode: boolean = false;

  build() {
    Column({ space: 24 }) {
      // Label with the switch next to it.
      Row() {
        Text('Dark mode')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .fontColor(this.isDarkMode ? '#E0E0E0' : '#1A1A1A')

        Toggle({ type: ToggleType.Switch, isOn: this.isDarkMode })
          .selectedColor('#0A59F7')
          .onChange((isOn: boolean) => {
            // Writing the @StorageLink variable updates AppStorage,
            // notifying every component that reads the setting.
            this.isDarkMode = isOn;
          })
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .alignItems(VerticalAlign.Center)

      // Reads the app-wide setting by itself.
      DarkModeTitle()

      // Reads the app-wide setting by itself.
      SampleCard()
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
    .padding({ left: 24, right: 24, top: 56 })
    .backgroundColor(this.isDarkMode ? '#121212' : '#F1F3F5')
  }
}

/**
 * Title that reflects the current dark mode setting.
 * Takes no parameters: it subscribes to AppStorage directly.
 */
@Component
struct DarkModeTitle {
  @StorageProp('darkMode') isDarkMode: boolean = false;

  build() {
    Text(this.isDarkMode ? 'Dark mode is on' : 'Dark mode is off')
      .fontSize(18)
      .fontColor(this.isDarkMode ? '#E0E0E0' : '#333333')
  }
}

/**
 * Card whose colors follow the current dark mode setting.
 * Takes no parameters: it subscribes to AppStorage directly.
 */
@Component
struct SampleCard {
  @StorageProp('darkMode') isDarkMode: boolean = false;

  build() {
    Column() {
      Text('Sample content')
        .fontSize(16)
        .fontColor(this.isDarkMode ? '#FFFFFF' : '#1A1A1A')
    }
