  }
}

@Observed
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    this.level = LogEntry.levelFor(id);
  }

  static levelFor(n: number): string {
    if (n % 50 === 0) {
      return 'error';
    }
    if (n % 10 === 0) {
      return 'warning';
    }
    return 'info';
  }
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  constructor(initial: LogEntry[]) {
    this.entries = initial;
  }

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataListener(listener: DataChangeListener): void {
    this.listeners.push(listener);
  }

  unregisterDataListener(listener: DataChangeListener): void {
    const index = this.listeners.indexOf(listener);
    if (index >= 0) {
      this.listeners.splice(index, 1);
    }
  }

  prepend(newEntries: LogEntry[]): void {
    this.entries = newEntries.concat(this.entries);
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataReloaded();
    });
  }
}

function makeDescendingEntries(highest: number): LogEntry[] {
  const result: LogEntry[] = [];
  for (let n = highest; n >= 1; n--) {
    result.push(new LogEntry(n));
  }
  return result;
}

@Component
