      return '#F57C00';
    }
    return '#757575';
  }

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontColor('#212121')
        .layoutWeight(1)
      Text(this.entry.level)
        .fontSize(14)
        .fontWeight(FontWeight.Medium)
        .fontColor(this.levelColor(this.entry.level))
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
  }
}

@Entry
@Component
struct LogPage {
  @State isRefreshing: boolean = false;
  @State entryCount: number = 3000;
  private dataSource: LogDataSource = new LogDataSource(makeDescendingEntries(3000));
  private nextId: number = 3001;

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .padding(16)

      Refresh({ refreshing: $$this.isRefreshing }) {
        List() {
          LazyForEach(this.dataSource, (entry: LogEntry) => {
            ListItem() {
              LogRow({ entry: entry })
            }
          }, (entry: LogEntry) => entry.id.toString())
        }
        .width('100%')
        .height('100%')
        .cachedCount(5)
        .divider({ strokeWidth: 1, color: '#E0E0E0', startMargin: 16, endMargin: 16 })
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        setTimeout(() => {
          const added: LogEntry[] = [];
          for (let i = 0; i < 5; i++) {
            added.push(new LogEntry(this.nextId));
            this.nextId += 1;
          }
          added.reverse();
          this.dataSource.prepend(added);
          this.entryCount = this.dataSource.totalCount();
          this.isRefreshing = false;
        }, 1000);
      })
    }
    .width('100%')
    .height('100%')
  }
}

