export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  const first: Point = points[0];
  let minX: number = first.x;
  let minY: number = first.y;
  let maxX: number = first.x;
  let maxY: number = first.y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };
  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };
  return box;
}

function isHexDigit(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function decodeUtf8Bytes(bytes: number[]): string {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b: number = bytes[i];
    if (b < 0x80) {
      out += String.fromCharCode(b);
      i += 1;
    } else if (b >= 0xC2 && b <= 0xDF && i + 1 < bytes.length &&
               bytes[i + 1] >= 0x80 && bytes[i + 1] <= 0xBF) {
      const cp: number = ((b - 0xC0) << 6) + (bytes[i + 1] - 0x80);
      out += String.fromCharCode(cp);
      i += 2;
    } else if (b >= 0xE0 && b <= 0xEF && i + 2 < bytes.length &&
               bytes[i + 1] >= 0x80 && bytes[i + 1] <= 0xBF &&
               bytes[i + 2] >= 0x80 && bytes[i + 2] <= 0xBF) {
      const cp: number = ((b - 0xE0) << 12) + ((bytes[i + 1] - 0x80) << 6) + (bytes[i + 2] - 0x80);
      out += String.fromCharCode(cp);
      i += 3;
    } else if (b >= 0xF0 && b <= 0xF4 && i + 3 < bytes.length &&
               bytes[i + 1] >= 0x80 && bytes[i + 1] <= 0xBF &&
               bytes[i + 2] >= 0x80 && bytes[i + 2] <= 0xBF &&
               bytes[i + 3] >= 0x80 && bytes[i + 3] <= 0xBF) {
      const cp: number = ((b - 0xF0) << 18) + ((bytes[i + 1] - 0x80) << 12) +
                         ((bytes[i + 2] - 0x80) << 6) + (bytes[i + 3] - 0x80);
      if (cp > 0xFFFF) {
        const v: number = cp - 0x10000;
        out += String.fromCharCode(0xD800 + (v >> 10));
        out += String.fromCharCode(0xDC00 + (v & 0x3FF));
      } else {
        out += String.fromCharCode(cp);
      }
      i += 4;
    } else {
      out += String.fromCharCode(0xFFFD);
      i += 1;
    }
  }
  return out;
}

function decodePart(raw: string): string {
  const plusReplaced: string = raw.split('+').join(' ');
  let out = '';
  let bytes: number[] = [];
  let i = 0;
  while (i < plusReplaced.length) {
    const c: string = plusReplaced.charAt(i);
    if (c === '%' && i + 2 < plusReplaced.length &&
        isHexDigit(plusReplaced.charAt(i + 1)) &&
        isHexDigit(plusReplaced.charAt(i + 2))) {
      const hex: string = plusReplaced.substring(i + 1, i + 3);
      bytes.push(parseInt(hex, 16));
      i += 3;
    } else {
      if (bytes.length > 0) {
        out += decodeUtf8Bytes(bytes);
        bytes = [];
      }
      out += c;
      i += 1;
    }
  }
  if (bytes.length > 0) {
    out += decodeUtf8Bytes(bytes);
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let q: string = query;
  if (q.startsWith('?')) {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }
  const parts: string[] = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq: number = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq === -1) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key: string = decodePart(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value: string = decodePart(rawValue);
    result.set(key, value);
  }
  return result;
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return settings;
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: defaults.theme,
    fontSize: defaults.fontSize,
    notifications: defaults.notifications,
    language: defaults.language
  };

  const userTheme = user.theme;
  if (userTheme !== undefined) {
    merged.theme = userTheme;
  }

  const userFontSize = user.fontSize;
  if (userFontSize !== undefined) {
    merged.fontSize = userFontSize;
  }

  const userNotifications = user.notifications;
  if (userNotifications !== undefined) {
    merged.notifications = userNotifications;
  }

  const userLanguage = user.language;
  if (userLanguage !== undefined) {
    merged.language = userLanguage;
  }

  return merged;
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return this.items.slice();
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let list: Listener<T>[] | undefined = this.listeners.get(event);
    if (list === undefined) {
      list = [];
      this.listeners.set(event, list);
    }
    if (list.indexOf(listener) < 0) {
      list.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const list: Listener<T>[] | undefined = this.listeners.get(event);
    if (list === undefined) {
      return;
    }
    const index: number = list.indexOf(listener);
    if (index >= 0) {
      list.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    const list: Listener<T>[] | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    const snapshot: Listener<T>[] = list.slice();
    for (const listener of snapshot) {
      listener(payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const list: Listener<T>[] | undefined = this.listeners.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

const PI: number = Math.PI;

// `Shape` is an abstract base class: every concrete shape extends it and
// provides its own area computation, so new kinds of shapes can be added
// later without changing existing code.
export abstract class Shape {
  public abstract area(): number;
}

export class Circle extends Shape {
  private readonly radius: number;

  constructor(radius: number) {
    super();
    this.radius = radius;
  }

  area(): number {
    return PI * this.radius * this.radius;
  }
}

export class Rectangle extends Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    super();
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

export class Triangle extends Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    super();
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

export function circle(radius: number): Shape {
  return new Circle(radius);
}

export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

export function area(shape: Shape): number {
  return shape.area();
}

export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += shape.area();
  }
  return sum;
}

function pad2(value: number): string {
  if (value < 10) {
    return `0${value}`;
  }
  return `${value}`;
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const abs: number = negative ? -totalSeconds : totalSeconds;
  const hours: number = Math.floor(abs / 3600);
  const minutes: number = Math.floor((abs % 3600) / 60);
  const seconds: number = abs % 60;

  let text: string;
  if (hours > 0) {
    text = `${hours}h ${pad2(minutes)}m ${pad2(seconds)}s`;
  } else if (minutes > 0) {
    text = `${minutes}m ${pad2(seconds)}s`;
  } else {
    text = `${seconds}s`;
  }

  if (negative) {
    return `-${text}`;
  }
  return text;
}

function isAllDigits(text: string): boolean {
  if (text.length === 0) {
    return false;
  }
  for (let i = 0; i < text.length; i++) {
    const c: string = text.charAt(i);
    if (c < '0' || c > '9') {
      return false;
    }
  }
  return true;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  const parts: string[] = text.split(' ');
  let total: number = 0;
  let negative: boolean = false;

  for (let i = 0; i < parts.length; i++) {
    let part: string = parts[i];
    if (part.length === 0) {
      return NaN;
    }
    if (i === 0 && part.startsWith('-')) {
      negative = true;
      part = part.substring(1);
    }
    if (part.length < 2) {
      return NaN;
    }
    const unit: string = part.charAt(part.length - 1);
    const digits: string = part.substring(0, part.length - 1);
    if (!isAllDigits(digits)) {
      return NaN;
    }
    const value: number = Number(digits);
    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else if (unit === 's') {
      total += value;
    } else {
      return NaN;
    }
  }

  if (negative) {
    return -total;
  }
  return total;
}

export class RetryError extends Error {
  public attempts: number;
  public lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const totalAttempts: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('action failed');
  for (let i: number = 0; i < totalAttempts; i++) {
    try {
      const result: T = await action();
      return result;
    } catch (e) {
      lastError = e as Error;
    }
  }
  throw new RetryError(totalAttempts, lastError);
}

/**
 * A pair of two values, possibly of different types.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits items into consecutive groups of `size` elements, in order.
 * The last group holds whatever is left and may be shorter.
 *
 * Returns an empty array when `items` is empty or when `size` is below 1.
 * The input array is not modified; every group is a new array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const groups: T[][] = [];
  const step: number = Math.floor(size);
  if (step < 1) {
    return groups;
  }
  for (let i = 0; i < items.length; i += step) {
    // slice copies the range into a fresh array, leaving items untouched.
    groups.push(items.slice(i, i + step));
  }
  return groups;
}

/**
 * Combines two arrays element by element into pairs.
 * Element i of the result pairs a[i] with b[i].
 * The result has the length of the shorter input.
 * Neither input array is modified.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updated);
      }
      // quantity <= 0: the item is left out of the result entirely.
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items.slice();
  for (const change of changes) {
    // A removed item is simply absent from `current`, so later changes
    // to the same id find no matching item and do nothing.
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

function hasRuleOn(rules: OpeningRule[], day: Weekday): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  for (let i = 1; i <= 7; i++) {
    const candidate: Weekday = (((day as number) + i) % 7) as Weekday;
    if (hasRuleOn(rules, candidate)) {
      return candidate;
    }
  }
  if (hasRuleOn(rules, day)) {
    return day;
  }
  return undefined;
}

