/**
 * A function that transforms a string into another string.
 */
export type Transform = (text: string) => string;

/**
 * Removes whitespace from both ends of the text.
 */
export function trim(text: string): string {
  return text.trim();
}

/**
 * Turns the text into lower case.
 */
export function lowerCase(text: string): string {
  return text.toLowerCase();
}

/**
 * Replaces every run of whitespace characters (spaces, tabs, line breaks)
 * with a single space.
 */
export function collapseSpaces(text: string): string {
  return text.replace(/\s+/g, ' ');
}

/**
 * One named step stored inside a pipeline.
 */
class PipelineStep {
  name: string;
  apply: Transform;

  constructor(name: string, apply: Transform) {
    this.name = name;
    this.apply = apply;
  }
}

/**
 * An ordered list of named transform steps.
 */
export class Pipeline {
  private steps: PipelineStep[] = [];

  /**
   * Appends a step to the end of the pipeline and returns the pipeline
   * itself so that calls can be chained. The same name may be added
   * more than once.
   */
  add(name: string, step: Transform): Pipeline {
    this.steps.push(new PipelineStep(name, step));
    return this;
  }

  /**
   * Passes the text through every step in the order they were added.
   * With no steps it returns the text unchanged.
   */
  run(text: string): string {
    let result: string = text;
    for (const step of this.steps) {
      result = step.apply(result);
    }
    return result;
  }

  /**
   * Returns the step names in order, as a new array.
   */
  names(): string[] {
    const result: string[] = [];
    for (const step of this.steps) {
      result.push(step.name);
    }
    return result;
  }

  /**
   * Returns a function that applies every step currently in the pipeline.
   * The function keeps a reference to this pipeline, so it also runs any
   * steps added after it was created.
   */
  toFunction(): Transform {
    const pipeline: Pipeline = this;
    const runAll: Transform = (text: string): string => pipeline.run(text);
    return runAll;
  }
}

/**
 * Combines the given steps into a single function that applies them from
 * first to last. With no steps it returns its input unchanged.
 */
export function compose(...steps: Transform[]): Transform {
  const runAll: Transform = (text: string): string => {
    let result: string = text;
    for (const step of steps) {
      result = step(result);
    }
    return result;
  };
  return runAll;
}

