// Sign-in page for HarmonyOS (stage model, ArkTS, API 12+).

function isValidEmail(email: string): boolean {
  let atCount: number = 0
  for (let i = 0; i < email.length; i++) {
    if (email.charAt(i) === '@') {
      atCount++
    }
  }
  if (atCount !== 1) {
    return false
  }
  const at: number = email.indexOf('@')
  // At least one character before the '@'.
  if (at < 1) {
    return false
  }
  const domain: string = email.substring(at + 1)
  const dot: number = domain.indexOf('.')
  // A '.' with at least one character on each side of it: "host.tld".
  if (dot < 1 || dot === domain.length - 1) {
    return false
  }
  return true
}

function isValidPassword(password: string): boolean {
  return password.length >= 8
}

