@Entry
@Component
struct ItemsPage {
  @State loadState: LoadState = LoadState.Loading;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.fetchItems();
  }

  private async fetchItems(): Promise<void> {
    const client: http.HttpRequest = http.createHttp();
    const options: http.HttpRequestOptions = {
      method: http.RequestMethod.GET,
      expectDataType: http.HttpDataType.STRING,
      connectTimeout: 10000,
      readTimeout: 10000
    };
    try {
      const response: http.HttpResponse = await client.request(ITEMS_URL, options);
      if (response.responseCode !== 200) {
        this.loadState = LoadState.Failed;
        return;
      }
      const body: string = response.result as string;
      const parsed: Item[] = JSON.parse(body) as Item[];
      this.items = parsed;
      this.loadState = LoadState.Success;
    } catch (e) {
      console.error('Failed to load items');
      this.loadState = LoadState.Failed;
    } finally {
      client.destroy();
    }
  }

  build() {
    Column() {
      if (this.loadState === LoadState.Loading) {
        Text('Loading...')
          .fontSize(20)
          .margin({ top: 48 })
      } else if (this.loadState === LoadState.Success) {
        List() {
          ForEach(this.items, (item: Item) => {
