// solution.ets
// Entry page: shows the persisted name, lets the user type a new one and save it.
// The name is stored with the preferences kit so it survives closing the app.

import { common } from '@kit.AbilityKit';
import { promptAction } from '@kit.ArkUI';
import { preferences } from '@kit.ArkData';

const STORE_NAME: string = 'nameStore';
const NAME_KEY: string = 'name';

@Entry
@Component
struct NamePage {
  // Name currently persisted, shown in the first line of text.
  @State savedName: string = '';
  // What the user is typing right now.
  @State typedName: string = '';
  // Opened preferences store, kept for later writes.
  private store: preferences.Preferences | null = null;

  aboutToAppear(): void {
    // Runs every time the page is created, including after the app was closed
    // and started again, so the saved name is read back and shown.
    this.loadSavedName();
  }

  private async loadSavedName(): Promise<void> {
    const context: common.Context = getContext(this) as common.Context;
    const store: preferences.Preferences = await preferences.getPreferences(context, STORE_NAME);
    this.store = store;
    const value: preferences.ValueType = await store.get(NAME_KEY, '');
    if (typeof value === 'string') {
      this.savedName = value;
    }
  }

  private async saveName(): Promise<void> {
    const name: string = this.typedName.trim();
    if (name.length === 0) {
      promptAction.showToast({ message: 'Type a name first' });
      return;
    }
    let store: preferences.Preferences | null = this.store;
    if (store === null) {
      const context: common.Context = getContext(this) as common.Context;
      store = await preferences.getPreferences(context, STORE_NAME);
      this.store = store;
    }
    await store.put(NAME_KEY, name);
    await store.flush();
    this.savedName = name;
    this.typedName = '';
  }

  build() {
    Column({ space: 16 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(22)
        .fontWeight(FontWeight.Bold)

      TextInput({ placeholder: 'Type your name', text: this.typedName })
        .width('100%')
        .onChange((value: string) => {
          this.typedName = value;
        })

      Button('Save')
        .width('100%')
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
    .padding(16)
  }
