// solution.ets
// A small calculator for arithmetic expressions with variables.
// Self-contained: no imports.

export interface Token {
  kind: string;    // 'number' | 'name' | 'operator' | 'paren'
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  readonly position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function isDigit(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

function isNameStart(ch: string): boolean {
  const code = ch.charCodeAt(0);
  return (code >= 97 && code <= 122) || (code >= 65 && code <= 90) || code === 95;
}

function isNamePart(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < source.length) {
    const ch = source[i];
    if (ch === ' ') {
      i++;
      continue;
    }
    if (isDigit(ch)) {
      const start = i;
      while (i < source.length && isDigit(source[i])) {
        i++;
      }
      // A '.' is only part of the number when it has a digit on both sides.
      if (i + 1 < source.length && source[i] === '.' && isDigit(source[i + 1])) {
        i += 2;
        while (i < source.length && isDigit(source[i])) {
          i++;
        }
      }
      tokens.push({ kind: 'number', text: source.substring(start, i), position: start });
      continue;
    }
    if (isNameStart(ch)) {
      const start = i;
      i++;
      while (i < source.length && isNamePart(source[i])) {
        i++;
      }
      tokens.push({ kind: 'name', text: source.substring(start, i), position: start });
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%') {
      tokens.push({ kind: 'operator', text: ch, position: i });
      i++;
      continue;
    }
    if (ch === '(' || ch === ')') {
      tokens.push({ kind: 'paren', text: ch, position: i });
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${ch}'`, i);
  }
  return tokens;
}

// ---------------------------------------------------------------------------
// Abstract syntax tree
// ---------------------------------------------------------------------------

abstract class AstNode {
  readonly position: number;

  constructor(position: number) {
    this.position = position;
  }

  abstract eval(variables: Record<string, number>): number;
}

class NumberNode extends AstNode {
  readonly value: number;

  constructor(value: number, position: number) {
    super(position);
    this.value = value;
  }

  eval(variables: Record<string, number>): number {
    return this.value;
  }
}

class VariableNode extends AstNode {
  readonly name: string;

  constructor(name: string, position: number) {
    super(position);
    this.name = name;
  }

  eval(variables: Record<string, number>): number {
    const value = variables[this.name];
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${this.name}'`, this.position);
    }
    return value;
  }
}

class NegationNode extends AstNode {
  readonly operand: AstNode;

  constructor(operand: AstNode, position: number) {
    super(position);
    this.operand = operand;
  }

  eval(variables: Record<string, number>): number {
    return -this.operand.eval(variables);
  }
}

class BinaryNode extends AstNode {
  readonly op: string;
  readonly opPosition: number;
  readonly left: AstNode;
  readonly right: AstNode;

  constructor(op: string, opPosition: number, left: AstNode, right: AstNode) {
    super(opPosition);
    this.op = op;
    this.opPosition = opPosition;
    this.left = left;
    this.right = right;
  }

  eval(variables: Record<string, number>): number {
    // Evaluation order: left completely, then right, then the operator.
    const l = this.left.eval(variables);
    const r = this.right.eval(variables);
    if (this.op === '+') {
      return l + r;
    }
    if (this.op === '-') {
      return l - r;
    }
    if (this.op === '*') {
      return l * r;
    }
    if (this.op === '/') {
      if (r === 0) {
        throw new ExpressionError('Division by zero', this.opPosition);
      }
      return l / r;
    }
    if (this.op === '%') {
      if (r === 0) {
        throw new ExpressionError('Division by zero', this.opPosition);
      }
      return l % r;
    }
    throw new ExpressionError(`Unexpected token '${this.op}'`, this.opPosition);
  }
}

// ---------------------------------------------------------------------------
// Parser (recursive descent)
// ---------------------------------------------------------------------------

class Parser {
  private readonly tokens: Token[];
  private readonly sourceLength: number;
  private index: number = 0;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
  }

  private current(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return undefined;
  }

  private isOperator(tok: Token, op: string): boolean {
    return tok.kind === 'operator' && tok.text === op;
  }

  parse(): AstNode {
    const node = this.parseExpression();
    const trailing = this.current();
    if (trailing !== undefined) {
      throw new ExpressionError(`Unexpected token '${trailing.text}'`, trailing.position);
    }
    return node;
  }

  private parseExpression(): AstNode {
    let left = this.parseTerm();
    for (;;) {
      const tok = this.current();
      if (tok === undefined || !(this.isOperator(tok, '+') || this.isOperator(tok, '-'))) {
        return left;
      }
      this.index++;
      const right = this.parseTerm();
      left = new BinaryNode(tok.text, tok.position, left, right);
    }
  }

  private parseTerm(): AstNode {
    let left = this.parseFactor();
    for (;;) {
      const tok = this.current();
      if (tok === undefined ||
        !(this.isOperator(tok, '*') || this.isOperator(tok, '/') || this.isOperator(tok, '%'))) {
        return left;
      }
      this.index++;
      const right = this.parseFactor();
      left = new BinaryNode(tok.text, tok.position, left, right);
    }
  }

  private parseFactor(): AstNode {
    const tok = this.current();
    if (tok !== undefined && this.isOperator(tok, '-')) {
      this.index++;
      const operand = this.parseFactor();
      return new NegationNode(operand, tok.position);
    }
    return this.parsePrimary();
  }

  private parsePrimary(): AstNode {
    const tok = this.current();
    if (tok === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (tok.kind === 'number') {
      this.index++;
      return new NumberNode(parseFloat(tok.text), tok.position);
    }
    if (tok.kind === 'name') {
      this.index++;
      return new VariableNode(tok.text, tok.position);
    }
    if (tok.kind === 'paren' && tok.text === '(') {
      this.index++;
      const node = this.parseExpression();
      const close = this.current();
      if (close === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.index++;
      return node;
    }
    throw new ExpressionError(`Unexpected token '${tok.text}'`, tok.position);
  }
}

// ---------------------------------------------------------------------------
// Public evaluation entry point
// ---------------------------------------------------------------------------

export function evaluate(source: string, variables: Record<string, number>): number {
  // Tokenize errors come first, then syntax errors; only a fully parsed
  // (i.e. syntactically correct) expression is evaluated.
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const ast = parser.parse();
  return ast.eval(variables);
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const result: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = result.get(expense.category);
    if (current === undefined) {
      result.set(expense.category, expense.amount);
    } else {
      result.set(expense.category, current + expense.amount);
    }
  }
  return result;
}

// solution.ets
// Self-contained settings helpers for a HarmonyOS (stage model) application.

/**
 * Fully resolved application settings.
 */
export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

/**
 * Partial settings supplied by the user: every field is optional.
 */
export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

/**
 * Creates a brand-new Settings object with the default values.
 * Each invocation returns a fresh object, so callers may freely mutate it.
 */
export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return settings;
}

/**
 * Merges user-provided (partial) settings on top of the defaults.
 *
 * - If `user` contains a field, its value wins — even when the value is
 *   `false`, `0` or `''` (presence is detected via `!== undefined`).
 * - If `user` does not contain a field, the value from `defaults` is used.
 * - A new object is returned; neither `defaults` nor `user` is modified.
 */
export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language
  };
  return merged;
}

/**
 * A point in a two-dimensional plane.
 */
export interface Point {
  x: number;
  y: number;
}

/**
 * An axis-aligned rectangle described by its extreme corners and its size.
 */
export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

/**
 * Computes the smallest axis-aligned rectangle that contains every point
 * of the given array.
 *
 * @param points the points to enclose; must not be modified
 * @returns a Box whose min/max are freshly created objects, or undefined
 *          when the input array is empty
 */
export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };

  return box;
}

// solution.ets
// Self-contained order parser: reads order JSON text, validates every field,
// and returns either the parsed order or a list of everything that is wrong.

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

type Json = Object | null | undefined;

function addError(errors: FieldError[], path: string, message: string): void {
  const error: FieldError = { path: path, message: message };
  errors.push(error);
}

function failWithSingleError(path: string, message: string): ParseResult {
  const error: FieldError = { path: path, message: message };
  const list: FieldError[] = [error];
  const result: ParseResult = { order: undefined, errors: list };
  return result;
}

function isJsonObject(value: Json): boolean {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isKnownOrderField(name: string): boolean {
  return name === 'id' || name === 'status' || name === 'lines';
}

function isKnownLineField(name: string): boolean {
  return name === 'sku' || name === 'quantity' || name === 'unitPrice';
}

export function parseOrder(text: string): ParseResult {
  let parsed: Json = undefined;
  try {
    parsed = JSON.parse(text) as Json;
  } catch (e) {
    return failWithSingleError('', 'invalid JSON');
  }

  if (parsed === undefined || parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return failWithSingleError('', 'expected an object');
  }

  const root = parsed as Record<string, Json>;
  const errors: FieldError[] = [];
  const parsedLines: OrderLine[] = [];

  // id
  let idValue = '';
  const idField = root['id'];
  if (idField === undefined || idField === null) {
    addError(errors, 'id', 'required');
  } else if (typeof idField !== 'string') {
    addError(errors, 'id', 'expected a string');
  } else if (idField === '') {
    addError(errors, 'id', 'must not be empty');
  } else {
    idValue = idField;
  }

  // status (optional, defaults to Draft)
  let statusValue: OrderStatus = OrderStatus.Draft;
  const statusField = root['status'];
  if (!(statusField === undefined || statusField === null)) {
    if (typeof statusField !== 'string') {
      addError(errors, 'status', 'expected one of draft, paid, shipped');
    } else if (statusField === 'draft') {
      statusValue = OrderStatus.Draft;
    } else if (statusField === 'paid') {
      statusValue = OrderStatus.Paid;
    } else if (statusField === 'shipped') {
      statusValue = OrderStatus.Shipped;
    } else {
      addError(errors, 'status', 'expected one of draft, paid, shipped');
    }
  }

  // lines
  const linesField = root['lines'];
  if (linesField === undefined || linesField === null) {
    addError(errors, 'lines', 'required');
  } else if (!Array.isArray(linesField)) {
    addError(errors, 'lines', 'expected an array');
  } else if (linesField.length === 0) {
    addError(errors, 'lines', 'must not be empty');
  } else {
    const arr = linesField as Json[];
    for (let i = 0; i < arr.length; i++) {
      const element = arr[i];
      const elementPath = `lines[${i}]`;
      if (!isJsonObject(element)) {
        addError(errors, elementPath, 'expected an object');
        continue;
      }
      const lineRecord = element as Record<string, Json>;
      let lineValid = true;
      let skuValue = '';
      let quantityValue = 0;
      let unitPriceValue = 0;

      // lines[i].sku
      const skuField = lineRecord['sku'];
      if (skuField === undefined || skuField === null) {
        addError(errors, `${elementPath}.sku`, 'required');
        lineValid = false;
      } else if (typeof skuField !== 'string') {
        addError(errors, `${elementPath}.sku`, 'expected a string');
        lineValid = false;
      } else if (skuField === '') {
        addError(errors, `${elementPath}.sku`, 'must not be empty');
        lineValid = false;
      } else {
        skuValue = skuField;
      }

      // lines[i].quantity
      const quantityField = lineRecord['quantity'];
      if (quantityField === undefined || quantityField === null) {
        addError(errors, `${elementPath}.quantity`, 'required');
        lineValid = false;
      } else if (typeof quantityField !== 'number') {
        addError(errors, `${elementPath}.quantity`, 'expected a number');
        lineValid = false;
      } else if (!Number.isInteger(quantityField) || quantityField < 1) {
        addError(errors, `${elementPath}.quantity`, 'must be a whole number of 1 or more');
        lineValid = false;
      } else {
        quantityValue = quantityField;
      }

      // lines[i].unitPrice
      const unitPriceField = lineRecord['unitPrice'];
      if (unitPriceField === undefined || unitPriceField === null) {
        addError(errors, `${elementPath}.unitPrice`, 'required');
        lineValid = false;
      } else if (typeof unitPriceField !== 'number') {
        addError(errors, `${elementPath}.unitPrice`, 'expected a number');
        lineValid = false;
      } else if (unitPriceField < 0) {
        addError(errors, `${elementPath}.unitPrice`, 'must be 0 or more');
        lineValid = false;
      } else {
        unitPriceValue = unitPriceField;
      }

      // unknown fields of this line, in the order they appear in the text
      const lineKeys = Object.keys(lineRecord);
      for (let j = 0; j < lineKeys.length; j++) {
        const name = lineKeys[j];
        if (!isKnownLineField(name)) {
          addError(errors, `${elementPath}.${name}`, 'unknown field');
        }
      }

      if (lineValid) {
        parsedLines.push(new OrderLine(skuValue, quantityValue, unitPriceValue));
      }
    }
  }

  // unknown fields of the order, in the order they appear in the text
  const orderKeys = Object.keys(root);
  for (let i = 0; i < orderKeys.length; i++) {
    const name = orderKeys[i];
    if (!isKnownOrderField(name)) {
      addError(errors, name, 'unknown field');
    }
  }

  if (errors.length > 0) {
    const result: ParseResult = { order: undefined, errors: errors };
    return result;
  }

  const order: Order = { id: idValue, status: statusValue, lines: parsedLines };
  const ok: ParseResult = { order: order, errors: [] };
  return ok;
}

// solution.ets
// Self-contained URL query string parser.

function isHexDigit(c: string): boolean {
  const code = c.charCodeAt(0);
  return (code >= 0x30 && code <= 0x39) || (code >= 0x41 && code <= 0x46) || (code >= 0x61 && code <= 0x66);
}

function hexValue(c: string): number {
  const code = c.charCodeAt(0);
  if (code >= 0x30 && code <= 0x39) {
    return code - 0x30;
  }
  if (code >= 0x41 && code <= 0x46) {
    return code - 0x41 + 10;
  }
  return code - 0x61 + 10;
}

// Decode an array of byte values as a UTF-8 encoded string.
// Malformed sequences are replaced with the replacement character.
function bytesToString(bytes: number[]): string {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b = bytes[i];
    if (b < 0x80) {
      out += String.fromCharCode(b);
      i += 1;
      continue;
    }
    let len = 0;
    let cp = 0;
    if (b >= 0xC0 && b < 0xE0) {
      len = 2;
      cp = b & 0x1F;
    } else if (b >= 0xE0 && b < 0xF0) {
      len = 3;
      cp = b & 0x0F;
    } else if (b >= 0xF0 && b < 0xF8) {
      len = 4;
      cp = b & 0x07;
    }
    let ok = len > 0;
    for (let j = 1; ok && j < len; j++) {
      const c = i + j < bytes.length ? bytes[i + j] : -1;
      if (c < 0x80 || c > 0xBF) {
        ok = false;
      } else {
        cp = (cp << 6) | (c & 0x3F);
      }
    }
    if (ok && cp <= 0x10FFFF && !(cp >= 0xD800 && cp <= 0xDFFF)) {
      if (cp > 0xFFFF) {
        const v = cp - 0x10000;
        out += String.fromCharCode(0xD800 + (v >> 10), 0xDC00 + (v & 0x3FF));
      } else {
        out += String.fromCharCode(cp);
      }
      i += len;
    } else {
      out += '\uFFFD';
      i += 1;
    }
  }
  return out;
}

// Decode one key or value component:
// '+' becomes a space, well-formed percent escapes are decoded as UTF-8,
// malformed escapes are kept literally.
function decodeComponent(s: string): string {
  const plusFixed = s.split('+').join(' ');
  let out = '';
  let bytes: number[] = [];
  let i = 0;
  while (i < plusFixed.length) {
    const ch = plusFixed.charAt(i);
    if (ch === '%' && i + 2 < plusFixed.length && isHexDigit(plusFixed.charAt(i + 1)) && isHexDigit(plusFixed.charAt(i + 2))) {
      bytes.push(hexValue(plusFixed.charAt(i + 1)) * 16 + hexValue(plusFixed.charAt(i + 2)));
      i += 3;
    } else {
      if (bytes.length > 0) {
        out += bytesToString(bytes);
        bytes = [];
      }
      out += ch;
      i += 1;
    }
  }
  if (bytes.length > 0) {
    out += bytesToString(bytes);
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();
  let q = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }
  const parts = q.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq === -1) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    if (rawKey.length === 0) {
      continue;
    }
    // Map.set on an existing key updates the value but keeps the
    // original insertion position, so the first occurrence decides
    // the order and the last occurrence decides the value.
    result.set(decodeComponent(rawKey), decodeComponent(rawValue));
  }
  return result;
}

/**
 * A generic last-in, first-out (LIFO) stack with a fixed maximum capacity.
 *
 * When the stack is full, push() refuses new items; when it is empty,
 * pop() and peek() return undefined.
 */
export class Stack<T> {
  private items: Array<T> = [];
  private capacity: number;

  /**
   * Creates a stack that can hold at most `capacity` items.
   *
   * @param capacity the largest number of items the stack can hold
   */
  constructor(capacity: number) {
    this.capacity = capacity;
  }

  /**
   * Puts an item on top of the stack.
   *
   * @param item the item to add
   * @returns true if the item was added; false when the stack is full
   */
  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  /**
   * Removes the top item from the stack and returns it.
   *
   * @returns the former top item, or undefined when the stack is empty
   */
  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  /**
   * Returns the top item without removing it.
   *
   * @returns the top item, or undefined when the stack is empty
   */
  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  /**
   * @returns the number of items currently held in the stack
   */
  size(): number {
    return this.items.length;
  }

  /**
   * @returns true when the stack holds no items
   */
  isEmpty(): boolean {
    return this.items.length === 0;
  }

  /**
   * @returns true when the stack holds its maximum number of items
   */
  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  /**
   * Removes every item from the stack.
   */
  clear(): void {
    this.items = [];
  }

  /**
   * Returns the items from bottom to top as a new array.
   * Mutating the returned array does not affect the stack.
   *
   * @returns a new array containing the stack items, bottom to top
   */
  toArray(): Array<T> {
    return this.items.slice();
  }
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const maxAttempts: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('');
  for (let call: number = 1; call <= maxAttempts; call++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }
  throw new RetryError(maxAttempts, lastError);
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private registry: Map<string, Array<Listener<T>>> = new Map<string, Array<Listener<T>>>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let list = this.registry.get(event);
    if (list === undefined) {
      list = new Array<Listener<T>>();
      this.registry.set(event, list);
    }
    if (list.indexOf(listener) < 0) {
      list.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const list = this.registry.get(event);
    if (list === undefined) {
      return;
    }
    const index = list.indexOf(listener);
    if (index >= 0) {
      list.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    const list = this.registry.get(event);
    if (list === undefined) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = list.slice();
    for (let i = 0; i < snapshot.length; i++) {
      const listener: Listener<T> = snapshot[i];
      listener(payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const list = this.registry.get(event);
    if (list === undefined) {
      return 0;
    }
    return list.length;
  }
}

/**
 * An item in the inventory list.
 */
export interface Item {
  id: string;
  name: string;
  quantity: number;
}

/**
 * A requested change to the quantity of the item with the given id.
 */
export interface Change {
  id: string;
  quantity: number;
}

/**
 * Returns a new array with the same items in the same order, where the item
 * with the given id has the new quantity.
 *
 * - If quantity is 0 or less, that item is left out of the result instead.
 * - If no item has that id, the result holds the same items as the input.
 * - Never modifies `items` or any object inside it; the changed item in the
 *   result is a new object.
 */
export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (const item of items) {
    if (item.id === id) {
      // Only keep the item when the new quantity is positive, and always
      // create a fresh object so the original is never touched.
      if (quantity > 0) {
        const updated: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updated);
      }
      // If quantity <= 0 the item is simply omitted from the result.
    } else {
      result.push(item);
    }
  }
  return result;
}

/**
 * Applies the changes one after another, each with the rules of
 * `updateQuantity`, and returns the final list.
 *
 * - Once a change has removed an item, later changes to the same id do
 *   nothing (the id is simply no longer present in the working list).
 * - Never modifies `items`, `changes` or any object inside them.
 */
export function applyChanges(items: Item[], changes: Change[]): Item[] {
  // Start from a shallow copy so the original array is never mutated.
  let current: Item[] = items.slice();
  for (const change of changes) {
    current = updateQuantity(current, change.id, change.quantity);
  }
  return current;
}

/**
 * Formats a duration given in whole seconds.
 *
 * - Below one minute: "0s", "59s".
 * - Below one hour:   "1m 00s", "12m 34s".
 * - One hour and up:  "1h 05m 09s", "100h 00m 00s" (hours never become days).
 * - The first number is written as it is; every following number has two
 *   digits with a leading zero when needed. Parts are separated by one space.
 * - A negative value yields "-" followed by the text of the absolute value.
 */
export function formatDuration(totalSeconds: number): string {
  const sign: string = totalSeconds < 0 ? '-' : '';
  const seconds: number = Math.abs(totalSeconds);

  const sec: number = seconds % 60;
  const totalMinutes: number = Math.floor(seconds / 60);
  const min: number = totalMinutes % 60;
  const hours: number = Math.floor(totalMinutes / 60);

  const twoDigits = (value: number): string => {
    const text: string = value.toString();
    return text.length === 1 ? '0' + text : text;
  };

  if (hours > 0) {
    return `${sign}${hours}h ${twoDigits(min)}m ${twoDigits(sec)}s`;
  }
  if (totalMinutes > 0) {
    return `${sign}${totalMinutes}m ${twoDigits(sec)}s`;
  }
  return `${sign}${sec}s`;
}

/**
 * Parses a duration text and returns the total number of seconds.
 *
 * - The text is one or more parts separated by single spaces.
 * - A part is one or more digits followed by "h", "m" or "s".
 * - Parts are added up regardless of order: "30s 2m" is 150.
 * - A leading "-" makes the result negative: "-1m 30s" is -90.
 * - Anything else (empty text, malformed part such as "12", "5x", "1.5h",
 *   or a space at either end / two spaces in a row) yields NaN.
 */
export function parseDuration(text: string): number {
  let body: string = text;
  let negative: boolean = false;
  if (body.startsWith('-')) {
    negative = true;
    body = body.substring(1);
  }
  if (body.length === 0) {
    return NaN;
  }

  const parts: string[] = body.split(' ');
  let total: number = 0;
  for (const part of parts) {
    // An empty part means a leading space, a trailing space or two
    // consecutive spaces; a one-character part cannot be "<digits><unit>".
    if (part.length < 2) {
      return NaN;
    }
    const unit: string = part.charAt(part.length - 1);
    let multiplier: number;
    if (unit === 'h') {
      multiplier = 3600;
    } else if (unit === 'm') {
      multiplier = 60;
    } else if (unit === 's') {
      multiplier = 1;
    } else {
      return NaN;
    }
    const digits: string = part.substring(0, part.length - 1);
    let value: number = 0;
    for (let i = 0; i < digits.length; i++) {
      const code: number = digits.charCodeAt(i);
      if (code < 48 || code > 57) {
        return NaN;
      }
      value = value * 10 + (code - 48);
    }
    total += value * multiplier;
  }
  return negative ? -total : total;
}

/**
 * Days of the week, in order from Monday to Sunday.
 */
export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

/**
 * A rule stating that a place is open on `day` from `openHour`
 * up to, but not including, `closeHour`.
 * `openHour` is always lower than `closeHour`.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Returns true if some rule covers the given day and hour,
 * i.e. the hour is within [openHour, closeHour) of a rule for that day.
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (let i = 0; i < rules.length; i++) {
    const rule: OpeningRule = rules[i];
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the first day after `day` that has at least one rule,
 * going forward through the week and wrapping from Sunday to Monday.
 * `day` itself is checked last, so if it is the only day with a rule,
 * it is returned (one week later). If no day has a rule, returns undefined.
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const startIndex: number = day as number;
  for (let offset = 1; offset <= 7; offset++) {
    const candidateIndex: number = (startIndex + offset) % 7;
    const candidate: Weekday = candidateIndex as Weekday;
    for (let i = 0; i < rules.length; i++) {
      if (rules[i].day === candidate) {
        return candidate;
      }
    }
  }
  return undefined;
}

