/**
 * A generic pair holding two values of possibly different types.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements, in order.
 * The last group holds whatever is left and may be shorter than `size`.
 *
 * - An empty input yields an empty array.
 * - A `size` below 1 yields an empty array.
 * - `items` is never modified, and every returned group is a new array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const groups: T[][] = [];
  if (size < 1) {
    return groups;
  }
  for (let start = 0; start < items.length; start += size) {
    const end = Math.min(start + size, items.length);
    const group: T[] = [];
    for (let i = start; i < end; i++) {
      group.push(items[i]);
    }
    groups.push(group);
  }
  return groups;
}

/**
 * Combines two arrays element-wise into pairs.
 *
 * Element `i` of the result has `first` equal to `a[i]` and `second` equal
 * to `b[i]`. The result is as long as the shorter of the two inputs, and
 * neither input is modified.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const pairs: Pair<A, B>[] = [];
  const length = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    pairs.push(pair);
  }
  return pairs;
}

