/**
 * Any shape that can report its own area.
 *
 * `Shape` is modeled as an interface on purpose: a new kind of shape can
 * be added later simply by writing another class that implements it.
 * The `area` and `totalArea` functions keep working unchanged for every
 * implementation, present or future (open/closed principle).
 */
export interface Shape {
  /** Area of this shape. */
  area(): number;
}

/** Circle, given by its radius. */
class Circle implements Shape {
  private readonly radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

/** Rectangle, given by width and height. */
class Rectangle implements Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

/** Triangle, given by one side (the base) and the height measured on that side. */
class Triangle implements Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

/** Creates a circle shape with the given radius. */
export function circle(radius: number): Shape {
  return new Circle(radius);
}

/** Creates a rectangle shape with the given width and height. */
export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

/** Creates a triangle shape from a side (base) and the height on that side. */
export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

/** Returns the area of a single shape. */
export function area(shape: Shape): number {
  return shape.area();
}

/**
 * Returns the sum of the areas of all the given shapes,
 * or 0 when the list is empty.
 */
export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += area(shape);
  }
  return sum;
}

