// Todo list entry page (stage model, ArkTS, API 12+).
//
// - Top row: single-line TextInput ("New todo") + "Add" button.
// - Below: one line of text per todo, in insertion order.
// - Add: appends the typed text (empty / whitespace-only adds nothing) and clears the input.
// - Tap a todo: removes exactly that todo (unique id per item, even for duplicate texts).
// - ForEach uses a stable, unique key per item so removing one todo does not rebuild the others.

class TodoItem {
  id: string;
  text: string;

  constructor(id: string, text: string) {
    this.id = id;
    this.text = text;
  }
}

@Entry
@Component
struct Index {
  @State todos: Array<TodoItem> = [];
  // Two-way bound to TextInput ($$), so assigning '' reliably clears the input box.
  @State inputText: string = '';
  // Monotonic counter -> every todo ever created gets a unique, stable id.
  private nextId: number = 1;

  private addTodo(): void {
    const text: string = this.inputText.trim();
    if (text.length === 0) {
      // Empty or whitespace-only input: add nothing (and do not clear the field).
      return;
    }
    this.todos.push(new TodoItem(this.nextId.toString(), text));
    this.nextId = this.nextId + 1;
    this.inputText = '';
  }

  private removeTodo(id: string): void {
    // Remove only the item with the matching unique id.
    this.todos = this.todos.filter((item: TodoItem): boolean => item.id !== id);
  }

  build() {
    Column() {
      // Input row: text input + Add button
      Row({ space: 12 }) {
        TextInput({ placeholder: 'New todo', text: $$this.inputText })
          .height(44)
          .layoutWeight(1)
          .onChange((value: string) => {
            this.inputText = value;
          })
          .onSubmit(() => {
            this.addTodo();
          })

        Button('Add')
          .height(44)
          .onClick(() => {
            this.addTodo();
          })
      }
      .width('100%')
      .padding({ left: 16, right: 16, top: 16, bottom: 8 })

      // Todo list: one line per todo, in the order they were added
      List({ space: 2 }) {
        ForEach(this.todos, (todo: TodoItem) => {
          ListItem() {
            Text(todo.text)
              .fontSize(18)
              .maxLines(1)
              .textOverflow({ overflow: TextOverflow.Ellipsis })
              .width('100%')
              .padding(14)
              .onClick(() => {
                this.removeTodo(todo.id);
              })
          }
        }, (todo: TodoItem) => todo.id)
      }
      .width('100%')
      .layoutWeight(1)
      .padding({ left: 16, right: 16 })
      .divider({ strokeWidth: 1, color: '#E5E5E5', startMargin: 14, endMargin: 14 })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

