export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

type FieldListener = (value: string | number | boolean, previous: string | number | boolean) => void;

export class EditorStore {
  private current: EditorState;
  private past: EditorState[] = [];
  private future: EditorState[] = [];
  private limit: number;
  private listeners: Map<string, FieldListener[]> = new Map<string, FieldListener[]>();

  constructor(initial: EditorState, historyLimit: number) {
    this.current = EditorStore.copyOf(initial);
    this.limit = historyLimit;
  }

  get state(): EditorState {
    return EditorStore.copyOf(this.current);
  }

  get canUndo(): boolean {
    return this.past.length > 0;
  }

  get canRedo(): boolean {
    return this.future.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const next = EditorStore.copyOf(this.current);
    if (patch.text !== undefined) {
      next.text = patch.text;
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold;
    }
    return this.commit(next);
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft = EditorStore.copyOf(this.current);
    run(draft);
    return this.commit(draft);
  }

  undo(): boolean {
    if (this.past.length === 0) {
      return false;
    }
    const before = this.current;
    const previous = this.past.pop() as EditorState;
    this.future.push(before);
    this.current = previous;
    this.notify(before);
    return true;
  }

  redo(): boolean {
    if (this.future.length === 0) {
      return false;
    }
    const before = this.current;
    const next = this.future.pop() as EditorState;
    this.pushPast(before);
    this.current = next;
    this.notify(before);
    return true;
  }

  watch(field: string, listener: FieldListener): () => void {
    let list = this.listeners.get(field);
    if (list === undefined) {
      list = [];
      this.listeners.set(field, list);
    }
    list.push(listener);
    let active = true;
    return (): void => {
      if (!active) {
        return;
      }
      active = false;
      const arr = this.listeners.get(field);
      if (arr !== undefined) {
        const idx = arr.indexOf(listener);
        if (idx >= 0) {
          arr.splice(idx, 1);
        }
      }
    };
  }

  private static copyOf(s: EditorState): EditorState {
    return { text: s.text, cursor: s.cursor, bold: s.bold };
  }

  private pushPast(state: EditorState): void {
    this.past.push(state);
    if (this.past.length > this.limit) {
      this.past.shift();
    }
  }

  private commit(next: EditorState): boolean {
    const before = this.current;
    const changed: boolean = next.text !== before.text
      || next.cursor !== before.cursor
      || next.bold !== before.bold;
    if (!changed) {
      return false;
    }
    this.pushPast(before);
    this.future = [];
    this.current = next;
    this.notify(before);
    return true;
  }

  private notify(before: EditorState): void {
    const after = this.current;
    if (after.text !== before.text) {
      this.notifyField('text', after.text, before.text);
    }
    if (after.cursor !== before.cursor) {
      this.notifyField('cursor', after.cursor, before.cursor);
    }
    if (after.bold !== before.bold) {
      this.notifyField('bold', after.bold, before.bold);
    }
  }

  private notifyField(field: string, value: string | number | boolean, previous: string | number | boolean): void {
    const list = this.listeners.get(field);
    if (list === undefined) {
      return;
    }
    const snapshot: FieldListener[] = list.slice();
    for (const l of snapshot) {
      l(value, previous);
    }
  }
}

