export class MissingDependencyError extends Error {
  task: string
  dependency: string

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`)
    this.task = task
    this.dependency = dependency
  }
}

export class CycleError extends Error {
  path: string[]

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`)
    this.path = path
  }
}

export class BuildPlan {
  private taskNames: string[]
  private deps: Map<string, string[]>

  constructor(spec: Record<string, string[]>) {
    const names: string[] = Object.keys(spec)
    const known: Set<string> = new Set(names)

    // First check: every dependency must be a known task.
    for (const task of names) {
      const list: string[] = spec[task]
      for (const dep of list) {
        if (!known.has(dep)) {
          throw new MissingDependencyError(task, dep)
        }
      }
    }

    // Then check for cycles by placing tasks as order() does.
    const placed: Set<string> = new Set()
    const inChain: Set<string> = new Set()
    const chain: string[] = []
    const visit = (task: string): void => {
      if (placed.has(task)) {
        return
      }
      if (inChain.has(task)) {
        const idx: number = chain.indexOf(task)
        const path: string[] = chain.slice(idx)
        path.push(task)
        throw new CycleError(path)
      }
      inChain.add(task)
      chain.push(task)
      for (const dep of spec[task]) {
        visit(dep)
      }
      chain.pop()
      inChain.delete(task)
      placed.add(task)
    }
    for (const task of names) {
      visit(task)
    }

    this.taskNames = names
    this.deps = new Map<string, string[]>()
    for (const task of names) {
      this.deps.set(task, spec[task])
    }
  }

  order(): string[] {
    const result: string[] = []
    const placed: Set<string> = new Set()
    const visit = (task: string): void => {
      if (placed.has(task)) {
        return
      }
      for (const dep of this.deps.get(task)!) {
        visit(dep)
      }
      placed.add(task)
      result.push(task)
    }
    for (const task of this.taskNames) {
      visit(task)
    }
    return result
  }

  layers(): string[][] {
    const result: string[][] = []
    const layerOf: Map<string, number> = new Map<string, number>()
    const compute = (task: string): number => {
      if (layerOf.has(task)) {
        return layerOf.get(task)!
      }
      let layer: number = 0
      for (const dep of this.deps.get(task)!) {
        const depLayer: number = compute(dep)
        if (depLayer + 1 > layer) {
          layer = depLayer + 1
        }
      }
      layerOf.set(task, layer)
      return layer
    }
    for (const task of this.taskNames) {
      const layer: number = compute(task)
      while (result.length <= layer) {
        result.push([])
      }
      result[layer].push(task)
    }
    return result
  }

  dependentsOf(name: string): string[] {
    if (!this.taskNames.includes(name)) {
      return []
    }
    // Build the reverse graph: for each task, the tasks that depend on it.
    const reverse: Map<string, Set<string>> = new Map<string, Set<string>>()
    for (const task of this.taskNames) {
      reverse.set(task, new Set<string>())
    }
    for (const task of this.taskNames) {
      for (const dep of this.deps.get(task)!) {
        reverse.get(dep)!.add(task)
      }
    }
    // Collect everything reachable from name through the reverse graph.
    const reach: Set<string> = new Set<string>()
    const stack: string[] = [name]
    while (stack.length > 0) {
      const current: string = stack.pop()!
      for (const task of reverse.get(current)!) {
        if (!reach.has(task)) {
          reach.add(task)
          stack.push(task)
        }
      }
    }
    reach.delete(name)
    return this.order().filter((task: string): boolean => reach.has(task))
  }
}

