/**
 * Entry page: a sign-in form laid out vertically.
 *
 * - Email input (brings up the email keyboard).
 * - Password input (typed characters are masked).
 * - "Sign in" button, disabled until both fields are valid.
 *
 * Validation is re-checked on every keystroke. While a field is non-empty and
 * invalid, an error message is shown under it; the message disappears as soon
 * as the field becomes valid or empty. Tapping the enabled button only writes
 * one line to the log; there is no network access.
 */

@Entry
@Component
struct SignInPage {
  // Content of the two inputs, updated on every keystroke.
  @State email: string = '';
  @State password: string = '';
  // Validation results, re-checked on every keystroke (see onChange below).
  @State emailValid: boolean = false;
  @State passwordValid: boolean = false;

  /**
   * An email is valid when it has exactly one "@", at least one character
   * before it, and after it a "." with at least one character on each side
   * (name@host.tld).
   */
  private isValidEmail(value: string): boolean {
    const atIndex: number = value.indexOf('@');
    if (atIndex < 0) {
      return false; // no "@" at all
    }
    if (value.indexOf('@', atIndex + 1) >= 0) {
      return false; // more than one "@"
    }
    if (atIndex === 0) {
      return false; // no character before "@"
    }
    const domain: string = value.substring(atIndex + 1);
    const dotIndex: number = domain.indexOf('.');
    if (dotIndex <= 0) {
      return false; // no "." after "@" or nothing between "@" and "."
    }
    if (dotIndex >= domain.length - 1) {
      return false; // nothing after the "."
    }
    return true;
  }

  /**
   * A password is valid when it has at least 8 characters.
   */
  private isValidPassword(value: string): boolean {
    return value.length >= 8;
  }

  build() {
    Column({ space: 16 }) {
      // Email field with its validation message underneath.
      Column({ space: 4 }) {
        TextInput({ placeholder: 'Email' })
          .type(InputType.Email)
          .width('100%')
          .height(48)
          .onChange((value: string) => {
            this.email = value;
            this.emailValid = this.isValidEmail(value);
          })
        if (this.email !== '' && !this.emailValid) {
          Text('Enter a valid email address')
            .fontSize(12)
            .fontColor('#D32F2F')
            .width('100%')
        }
      }
      .width('100%')
      .alignItems(HorizontalAlign.Start)

      // Password field with its validation message underneath.
      Column({ space: 4 }) {
        TextInput({ placeholder: 'Password' })
          .type(InputType.Password)
          .width('100%')
          .height(48)
          .onChange((value: string) => {
            this.password = value;
            this.passwordValid = this.isValidPassword(value);
          })
        if (this.password !== '' && !this.passwordValid) {
          Text('Password must be at least 8 characters')
            .fontSize(12)
            .fontColor('#D32F2F')
            .width('100%')
        }
      }
      .width('100%')
      .alignItems(HorizontalAlign.Start)

      // Enabled (tappable) only when both fields are valid.
      Button('Sign in')
        .width('100%')
        .height(44)
        .enabled(this.emailValid && this.passwordValid)
        .opacity(this.emailValid && this.passwordValid ? 1 : 0.5)
        .onClick(() => {
          // No network here: just write one line to the log.
          console.info('Sign in tapped, email: ' + this.email);
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .justifyContent(FlexAlign.Center)
  }
}

