export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

/**
 * solution.ets
 *
 * A queue that runs asynchronous jobs with a limited concurrency.
 * Self-contained: imports nothing.
 */

/**
 * The final result of a single job, as reported by `runAll`.
 */
export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

/**
 * Internal bookkeeping for one queued job. The queue never inspects the
 * job's result type: `start` and `cancel` are closures created inside
 * `add` that already know how to settle the promise `add` returned.
 */
class WaitingJob {
  public readonly start: () => void;
  public readonly cancel: () => void;

  constructor(start: () => void, cancel: () => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

export class JobQueue {
  private limit: number;
  private pausedFlag: boolean;
  private queue: WaitingJob[];
  private runningCount: number;
  private completedCount: number;
  private failedCount: number;
  private idleResolvers: Array<() => void>;

  constructor(concurrency: number) {
    this.limit = concurrency;
    this.pausedFlag = false;
    this.queue = [];
    this.runningCount = 0;
    this.completedCount = 0;
    this.failedCount = 0;
    this.idleResolvers = [];
  }

  public get running(): number {
    return this.runningCount;
  }

  public get waiting(): number {
    return this.queue.length;
  }

  public get completed(): number {
    return this.completedCount;
  }

  public get failed(): number {
    return this.failedCount;
  }

  /**
   * Adds a job to the end of the queue. If the queue is not paused and
   * has free capacity, the job is called before `add` returns.
   */
  public add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve: (value: T) => void,
                           reject: (reason: Error) => void) => {
      let started: boolean = false;
      let cancelled: boolean = false;

      const startJob = (): void => {
        if (started || cancelled) {
          return;
        }
        started = true;
        this.runningCount += 1;
        job().then((value: T): void => {
          this.onSettled(true);
          resolve(value);
        }, (err: Error): void => {
          this.onSettled(false);
          reject(err);
        });
      };

      const cancelJob = (): void => {
        if (cancelled || started) {
          return;
        }
        cancelled = true;
        reject(new Error('Job was cancelled'));
      };

      this.queue.push(new WaitingJob(startJob, cancelJob));
      if (!this.pausedFlag && this.runningCount < this.limit) {
        this.tryStartNext();
      }
    });
  }

  /**
   * Stops starting waiting jobs. Running jobs continue undisturbed.
   */
  public pause(): void {
    this.pausedFlag = true;
  }

  /**
   * Ends the pause and starts as many waiting jobs as the limit allows,
   * before returning.
   */
  public resume(): void {
    this.pausedFlag = false;
    this.tryStartNext();
  }

  /**
   * Removes every waiting job. Their `add` promises reject with
   * `Error('Job was cancelled')`. Running jobs are not affected.
   * Returns the number of removed jobs.
   */
  public clear(): number {
    const count: number = this.queue.length;
    const removed: WaitingJob[] = this.queue;
    this.queue = [];
    for (const entry of removed) {
      entry.cancel();
    }
    this.checkIdle();
    return count;
  }

  /**
   * A promise that fulfils as soon as no job is running and no job is
   * waiting. Already fulfilled if the queue is idle right now.
   */
  public whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.queue.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve: () => void) => {
      this.idleResolvers.push(resolve);
    });
  }

  /**
   * Adds every job in order (exactly as `add` does) and fulfils with one
   * `JobOutcome` per job, in the original order. Never rejects.
   */
  public runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const pending: Array<Promise<JobOutcome<T>>> = [];
    for (const job of jobs) {
      pending.push(this.add<T>(job).then<JobOutcome<T>, JobOutcome<T>>(
        (value: T): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          return outcome;
        },
        (err: Error): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: err };
          return outcome;
        }
      ));
    }
    return Promise.all(pending);
  }

  /**
   * Starts waiting jobs while the queue is not paused and there is free
   * capacity. Jobs are started strictly from the front of the queue, so
   * they run in the order they were added.
   */
  private tryStartNext(): void {
    while (!this.pausedFlag && this.runningCount < this.limit
           && this.queue.length > 0) {
      const job: WaitingJob = this.queue[0];
      this.queue.splice(0, 1);
      job.start();
    }
  }

  /**
   * Called when a running job's promise settles.
   */
  private onSettled(fulfilled: boolean): void {
    this.runningCount -= 1;
    if (fulfilled) {
      this.completedCount += 1;
    } else {
      this.failedCount += 1;
    }
    this.tryStartNext();
    this.checkIdle();
  }

  /**
   * Fulfils every pending `whenIdle` promise if nothing is running or
   * waiting.
   */
  private checkIdle(): void {
    if (this.runningCount === 0 && this.queue.length === 0) {
      const resolvers: Array<() => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (const resolve of resolvers) {
        resolve();
      }
    }
  }
}

