/**
 * solution.ets
 *
 * Self-contained settings module: no imports required.
 */

/** Fully specified user preferences. */
export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

/** Same shape as Settings, but every field is optional. */
export type UserSettings = Partial<Settings>;

/**
 * Builds a fresh Settings object with the default values.
 * A new object is allocated on every call.
 */
export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en',
  };
  return settings;
}

/**
 * Merges user overrides on top of the defaults.
 *
 * A field that is defined in `user` wins, even when its value is falsy
 * (false, 0 or ''). A field absent from `user` falls back to the value
 * in `defaults`. Neither argument is mutated; a brand-new Settings
 * object is returned.
 */
export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: user.theme !== undefined ? user.theme : defaults.theme,
    fontSize: user.fontSize !== undefined ? user.fontSize : defaults.fontSize,
    notifications: user.notifications !== undefined ? user.notifications : defaults.notifications,
    language: user.language !== undefined ? user.language : defaults.language,
  };
  return merged;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX = points[0].x;
  let minY = points[0].y;
  let maxX = points[0].x;
  let maxY = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };

  const box: Box = {
    min: min,
    max: max,
    width: maxX - minX,
    height: maxY - minY
  };

  return box;
}

// solution.ets

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private events: Map<string, Listener<T>[]> = new Map<string, Listener<T>[]>();

  constructor() {
  }

  on(event: string, listener: Listener<T>): void {
    let listeners: Listener<T>[] | undefined = this.events.get(event);
    if (listeners === undefined) {
      listeners = [];
      this.events.set(event, listeners);
    }
    if (listeners.indexOf(listener) === -1) {
      listeners.push(listener);
    }
  }

  off(event: string, listener: Listener<T>): void {
    const listeners: Listener<T>[] | undefined = this.events.get(event);
    if (listeners === undefined) {
      return;
    }
    const index: number = listeners.indexOf(listener);
    if (index !== -1) {
      listeners.splice(index, 1);
    }
  }

  emit(event: string, payload: T): number {
    const listeners: Listener<T>[] | undefined = this.events.get(event);
    if (listeners === undefined) {
      return 0;
    }
    // Snapshot: listeners registered at the start of this emit are called,
    // even if a listener modifies the registration list while running.
    const snapshot: Listener<T>[] = listeners.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const listeners: Listener<T>[] | undefined = this.events.get(event);
    if (listeners === undefined) {
      return 0;
    }
    return listeners.length;
  }
}

export class Stack<T> {
  private items: T[] = [];
  private capacity: number;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.items.length === 0) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): T[] {
    return this.items.slice();
  }
}

function isHexChar(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function hexValue(c: string): number {
  if (c >= '0' && c <= '9') {
    return c.charCodeAt(0) - 0x30;
  }
  if (c >= 'a' && c <= 'f') {
    return c.charCodeAt(0) - 0x61 + 10;
  }
  return c.charCodeAt(0) - 0x41 + 10;
}

function utf8Decode(bytes: number[]): string {
  let out = '';
  let i = 0;
  while (i < bytes.length) {
    const b = bytes[i];
    let cp = 0;
    let len = 0;
    if (b < 0x80) {
      cp = b;
      len = 1;
    } else if ((b & 0xE0) === 0xC0) {
      cp = b & 0x1F;
      len = 2;
    } else if ((b & 0xF0) === 0xE0) {
      cp = b & 0x0F;
      len = 3;
    } else if ((b & 0xF8) === 0xF0) {
      cp = b & 0x07;
      len = 4;
    } else {
      out += '\uFFFD';
      i++;
      continue;
    }
    if (i + len > bytes.length) {
      out += '\uFFFD';
      i++;
      continue;
    }
    let ok = true;
    for (let j = 1; j < len; j++) {
      const cb = bytes[i + j];
      if ((cb & 0xC0) !== 0x80) {
        ok = false;
        break;
      }
      cp = (cp << 6) | (cb & 0x3F);
    }
    if (ok) {
      out += String.fromCodePoint(cp);
      i += len;
    } else {
      out += '\uFFFD';
      i++;
    }
  }
  return out;
}

function decodeComponent(s: string): string {
  let out = '';
  let bytes: number[] = [];
  const flushBytes = (): void => {
    if (bytes.length > 0) {
      out += utf8Decode(bytes);
      bytes = [];
    }
  };
  let i = 0;
  while (i < s.length) {
    const c = s.charAt(i);
    if (c === '+') {
      flushBytes();
      out += ' ';
      i++;
      continue;
    }
    if (c === '%') {
      const h = i + 1 < s.length ? s.charAt(i + 1) : '';
      const l = i + 2 < s.length ? s.charAt(i + 2) : '';
      if (h !== '' && l !== '' && isHexChar(h) && isHexChar(l)) {
        bytes.push((hexValue(h) << 4) | hexValue(l));
        i += 3;
        continue;
      }
      flushBytes();
      out += '%';
      i++;
      continue;
    }
    flushBytes();
    out += c;
    i++;
  }
  flushBytes();
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result = new Map<string, string>();
  if (query === undefined || query === null || query.length === 0) {
    return result;
  }
  let s = query;
  if (s.charAt(0) === '?') {
    s = s.substring(1);
  }
  if (s.length === 0) {
    return result;
  }
  const parts = s.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part = parts[i];
    if (part.length === 0) {
      continue;
    }
    const eq = part.indexOf('=');
    let rawKey = '';
    let rawValue = '';
    if (eq === -1) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    if (rawKey.length === 0) {
      continue;
    }
    const key = decodeComponent(rawKey);
    const value = decodeComponent(rawValue);
    // Map.set on an existing key keeps the key's original insertion position,
    // so first-appearance order is preserved while the last value wins.
    result.set(key, value);
  }
  return result;
}

/**
 * A geometric shape.
 *
 * Modeled as an interface so that new kinds of shapes can be added later:
 * any class implementing `Shape` (providing its own area computation) works
 * with `area()` and `totalArea()` without modifying existing code.
 */
export interface Shape {
  area(): number;
}

class Circle implements Shape {
  private readonly radius: number;

  constructor(radius: number) {
    this.radius = radius;
  }

  area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

class Rectangle implements Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    this.width = width;
    this.height = height;
  }

  area(): number {
    return this.width * this.height;
  }
}

class Triangle implements Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    this.base = base;
    this.height = height;
  }

  area(): number {
    return this.base * this.height / 2;
  }
}

/** Creates a circle from its radius. */
export function circle(radius: number): Shape {
  return new Circle(radius);
}

/** Creates a rectangle from its width and height. */
export function rectangle(width: number, height: number): Shape {
  return new Rectangle(width, height);
}

/** Creates a triangle from one side (base) and the height on that side. */
export function triangle(base: number, height: number): Shape {
  return new Triangle(base, height);
}

/** Returns the area of a single shape. */
export function area(shape: Shape): number {
  return shape.area();
}

/** Returns the sum of the areas of all shapes; 0 for an empty list. */
export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += shape.area();
  }
  return sum;
}

/**
 * Duration formatting and parsing.
 *
 * Text shape:
 *   - under a minute:            "0s", "59s"
 *   - under an hour:             "1m 00s", "12m 34s"
 *   - an hour and above:         "1h 05m 09s", "100h 00m 00s"
 *   - negative values:           "-1m 30s"
 *
 * The leading number is written plainly; every following number uses two
 * digits with a leading zero when needed. Hours never roll over into days.
 */

function padTwo(value: number): string {
  return value < 10 ? `0${value}` : `${value}`;
}

/**
 * Formats a whole number of seconds as human-readable duration text.
 */
export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const magnitude: number = negative ? -totalSeconds : totalSeconds;

  const hours: number = Math.floor(magnitude / 3600);
  const minutes: number = Math.floor((magnitude % 3600) / 60);
  const seconds: number = magnitude % 60;

  let text: string;
  if (hours > 0) {
    text = `${hours}h ${padTwo(minutes)}m ${padTwo(seconds)}s`;
  } else if (minutes > 0) {
    text = `${minutes}m ${padTwo(seconds)}s`;
  } else {
    text = `${seconds}s`;
  }
  return negative ? `-${text}` : text;
}

const PART_REGEX: RegExp = /^\d+[hms]$/;

/**
 * Parses duration text back into a whole number of seconds.
 *
 * Parts are added up regardless of order or size ("30s 2m" is 150). A "-"
 * in front of the first part negates the result. Anything malformed —
 * empty text, a part without the "<digits><h|m|s>" shape, or a space at
 * either end or doubled up — yields NaN.
 */
export function parseDuration(text: string): number {
  if (text.length === 0) {
    return Number.NaN;
  }

  const parts: string[] = text.split(' ');
  let negative: boolean = false;
  let total: number = 0;

  for (let i = 0; i < parts.length; i++) {
    let part: string = parts[i];

    // A "-" is only allowed in front of the very first part.
    if (i === 0 && part.startsWith('-')) {
      negative = true;
      part = part.substring(1);
    }

    // Rejects empty parts (leading/trailing/double spaces) and any part
    // that is not one or more digits followed by "h", "m" or "s".
    if (!PART_REGEX.test(part)) {
      return Number.NaN;
    }

    const unit: string = part.charAt(part.length - 1);
    const digits: string = part.substring(0, part.length - 1);
    const value: number = Number.parseInt(digits, 10);

    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
  }

  return negative ? -total : total;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  let found: boolean = false;
  for (const item of items) {
    if (item.id === id) {
      found = true;
      break;
    }
  }
  if (!found) {
    return items.slice();
  }

  const result: Item[] = [];
  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = { id: item.id, name: item.name, quantity: quantity };
        result.push(updated);
      }
      // quantity <= 0: the item is left out of the result
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let result: Item[] = items.slice();
  for (const change of changes) {
    result = updateQuantity(result, change.id, change.quantity);
  }
  return result;
}

export enum Weekday {
  Monday,
  Tuesday,
  Wednesday,
  Thursday,
  Friday,
  Saturday,
  Sunday
}

export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const daysWithRules: boolean[] = new Array(7).fill(false);
  for (const rule of rules) {
    daysWithRules[rule.day] = true;
  }

  // Search forward through the week, wrapping from Sunday to Monday.
  // `day` itself is checked last, so if it is the only day with a rule
  // the answer is `day` one week later.
  for (let offset = 1; offset <= 7; offset++) {
    const candidate: Weekday = ((day + offset) % 7) as Weekday;
    if (daysWithRules[candidate]) {
      return candidate;
    }
  }
  return undefined;
}

