/**
 * A pair of two values with independent types.
 */
export interface Pair<A, B> {
  first: A;
  second: B;
}

/**
 * Splits `items` into consecutive groups of `size` elements, in order.
 * The last group holds whatever is left and may be shorter.
 * Returns an empty array when the input is empty or `size` is below 1.
 * The input array is not modified; every group is a new array.
 */
export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  for (let i = 0; i < items.length; i += size) {
    result.push(items.slice(i, i + size));
  }
  return result;
}

/**
 * Combines two arrays element-wise into pairs.
 * Element `i` of the result has `first` equal to `a[i]` and `second` equal to `b[i]`.
 * The result is as long as the shorter of the two inputs.
 * Neither input array is modified.
 */
export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = Math.min(a.length, b.length);
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = {
      first: a[i],
      second: b[i]
    };
    result.push(pair);
  }
  return result;
}

/**
 * Least-recently-used (LRU) cache with a fixed capacity.
 *
 * Key identity follows the semantics of the built-in Map:
 * - the number 1 and the string '1' are different keys,
 * - two objects are the same key only when they are the same object.
 *
 * Entries are kept in a doubly linked list ordered from the least recently
 * used entry (tail) to the most recently used entry (head), with a Map from
 * key to list node for O(1) lookups, inserts and removals.
 */

class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

export class LruCache<K, V> {
  private readonly capacity: number;
  private readonly lookup: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  private head: LruNode<K, V> | null = null; // most recently used
  private tail: LruNode<K, V> | null = null; // least recently used
  private count: number = 0;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  /** How many keys are stored. */
  get size(): number {
    return this.count;
  }

  /**
   * Stores the value and makes `key` the most recently used key.
   * Setting a key that is already stored replaces its value.
   * If the cache then holds more than `capacity` keys, the least
   * recently used key is removed.
   */
  set(key: K, value: V): void {
    const existing = this.lookup.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToFront(existing);
      return;
    }
    const node = new LruNode<K, V>(key, value);
    this.lookup.set(key, node);
    this.prepend(node);
    this.count++;
    if (this.count > this.capacity) {
      this.evictLeastRecentlyUsed();
    }
  }

  /**
   * Returns the stored value and makes `key` the most recently used key.
   * For a key that is not stored it returns `undefined`.
   */
  get(key: K): V | undefined {
    const node = this.lookup.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToFront(node);
    return node.value;
  }

  /** Says whether the key is stored; does not count as a use. */
  has(key: K): boolean {
    return this.lookup.has(key);
  }

  /**
   * Returns the stored keys in a new array, from the least recently used
   * to the most recently used; does not count as a use.
   */
  keys(): K[] {
    const result: K[] = [];
    let node = this.tail;
    while (node !== null) {
      result.push(node.key);
      node = node.next;
    }
    return result;
  }

  private prepend(node: LruNode<K, V>): void {
    node.prev = null;
    node.next = this.head;
    if (this.head !== null) {
      this.head.prev = node;
    }
    this.head = node;
    if (this.tail === null) {
      this.tail = node;
    }
  }

  private unlink(node: LruNode<K, V>): void {
    const prev = node.prev;
    const next = node.next;
    if (prev !== null) {
      prev.next = next;
    } else {
      this.head = next;
    }
    if (next !== null) {
      next.prev = prev;
    } else {
      this.tail = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private moveToFront(node: LruNode<K, V>): void {
    if (this.head === node) {
      return;
    }
    this.unlink(node);
    this.prepend(node);
  }

  private evictLeastRecentlyUsed(): void {
    const lru = this.tail;
    if (lru === null) {
      return;
    }
    this.unlink(lru);
    this.lookup.delete(lru.key);
    this.count--;
  }
}

