struct SignIn {
  @State private email: string = ''
  @State private password: string = ''

  private isValidEmail(email: string): boolean {
    // Exactly one "@", at least one character before it, and after it a "."
    // with at least one character on each side: name@host.tld
    return /^[^@]+@[^@]+\.[^@]+$/.test(email)
