// solution.ets
// Entry page: shows the persisted name, lets the user type a new one and save it.
// The name is stored with Preferences (persistent key-value storage in the app
// sandbox), so it survives closing and reopening the app.

import { preferences } from '@kit.ArkData';
import { common } from '@kit.AbilityKit';
import { BusinessError } from '@kit.BasicServicesKit';
import { hilog } from '@kit.PerformanceAnalysisKit';

const HILOG_DOMAIN: number = 0x0000;
const TAG: string = 'SolutionPage';
const PREFERENCES_NAME: string = 'user_prefs';
const KEY_SAVED_NAME: string = 'saved_name';

@Entry
@Component
struct Index {
  @State savedName: string = '';
  @State inputName: string = '';

  aboutToAppear(): void {
    this.loadSavedName();
  }

  onPageShow(): void {
    // Re-read the persisted value every time the page appears,
    // including after the app has been closed and opened again.
    this.loadSavedName();
  }

  private getStore(): preferences.Preferences {
    const context: common.Context = getContext(this) as common.Context;
    return preferences.getPreferencesSync(context, { name: PREFERENCES_NAME });
  }

  private loadSavedName(): void {
    try {
      const store: preferences.Preferences = this.getStore();
      const value: preferences.ValueType = store.getSync(KEY_SAVED_NAME, '');
      this.savedName = typeof value === 'string' ? value : '';
    } catch (err) {
      const e: BusinessError = err as BusinessError;
      hilog.error(HILOG_DOMAIN, TAG, 'Failed to read saved name: %{public}d %{public}s', e.code, e.message);
    }
  }

  private saveName(): void {
    const name: string = this.inputName.trim();
    if (name.length === 0) {
      // Nothing typed: keep the current state.
      return;
    }
    try {
      const store: preferences.Preferences = this.getStore();
      store.putSync(KEY_SAVED_NAME, name);
      // flush() is asynchronous only; it persists the data to disk so the
      // name survives closing the app.
      store.flush().catch((err: BusinessError) => {
        hilog.error(HILOG_DOMAIN, TAG, 'Failed to flush preferences: %{public}d %{public}s', err.code, err.message);
      });
      this.savedName = name;
    } catch (err) {
      const e: BusinessError = err as BusinessError;
      hilog.error(HILOG_DOMAIN, TAG, 'Failed to save name: %{public}d %{public}s', e.code, e.message);
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)

      TextInput({ placeholder: 'Type your name', text: this.inputName })
        .width('80%')
        .height(48)
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('80%')
        .height(48)
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
    .padding(16)
  }
}

// solution.ets
// Log viewer page: LazyForEach list inside a Refresh container.

@Observed
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = 'error';
    } else if (id % 10 === 0) {
      this.level = 'warning';
    } else {
      this.level = 'info';
    }
  }
}

function levelColor(level: string): string {
  if (level === 'error') {
    return '#D32F2F';
  }
  if (level === 'warning') {
    return '#F57C00';
  }
  return '#757575';
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const index: number = this.listeners.indexOf(listener);
    if (index >= 0) {
      this.listeners.splice(index, 1);
    }
  }

  addEntryAtTop(entry: LogEntry): void {
    this.entries.unshift(entry);
    for (let i = 0; i < this.listeners.length; i++) {
      this.listeners[i].onDataAdd(0);
    }
  }
}

@Component
struct LogRow {
  @ObjectLink entry: LogEntry;

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontColor('#212121')
        .layoutWeight(1)
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis })

      Text(this.entry.level)
        .fontSize(14)
        .fontColor(levelColor(this.entry.level))
        .fontWeight(FontWeight.Medium)
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .alignItems(VerticalAlign.Center)
  }
}

@Entry
@Component
struct LogPage {
  @State isRefreshing: boolean = false;
  @State entryCount: number = 0;
  private dataSource: LogDataSource = new LogDataSource();
  private nextId: number = 0;

  aboutToAppear(): void {
    for (let i = 1; i <= 3000; i++) {
      this.dataSource.addEntryAtTop(new LogEntry(i));
    }
    // Entries were added highest-id-first so the array is 3000..1;
    // the next id to generate is 3001.
    this.nextId = 3001;
    this.entryCount = this.dataSource.totalCount();
  }

  addFiveEntries(): void {
    for (let i = 0; i < 5; i++) {
      this.dataSource.addEntryAtTop(new LogEntry(this.nextId));
      this.nextId++;
    }
    this.entryCount = this.dataSource.totalCount();
    this.isRefreshing = false;
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .width('100%')
        .padding({ left: 16, right: 16, top: 12, bottom: 8 })

      Refresh({ refreshing: this.isRefreshing }) {
        List() {
          LazyForEach(this.dataSource, (item: LogEntry) => {
            ListItem() {
              LogRow({ entry: item })
            }
          }, (item: LogEntry) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .scrollBar(BarState.Auto)
        .edgeEffect(EdgeEffect.Spring)
      }
      .width('100%')
      .layoutWeight(1)
      .refreshOffset(64)
      .pullToRefresh(true)
      .onRefreshing(() => {
        setTimeout(() => {
          this.addFiveEntries();
        }, 1000);
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

