export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

const ORDER_FIELDS: string[] = ['id', 'status', 'lines'];
const LINE_FIELDS: string[] = ['sku', 'quantity', 'unitPrice'];

function makeError(path: string, message: string): FieldError {
  const e: FieldError = { path: path, message: message };
  return e;
}

function failureResult(err: FieldError): ParseResult {
  const errors: FieldError[] = [];
  errors.push(err);
  const r: ParseResult = { order: undefined, errors: errors };
  return r;
}

function fieldOrUndefined(rec: Record<string, Object>, name: string): Object | undefined {
  const keys: string[] = Object.keys(rec);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i] === name) {
      return rec[name];
    }
  }
  return undefined;
}

function isMissingOrNull(value: Object | undefined): boolean {
  return value === undefined || value === null;
}

export function parseOrder(text: string): ParseResult {
  let parsed: Object | null;
  try {
    parsed = JSON.parse(text);
  } catch (e) {
    return failureResult(makeError('', 'invalid JSON'));
  }
  if (parsed === null) {
    return failureResult(makeError('', 'expected an object'));
  }
  if (typeof parsed !== 'object' || Array.isArray(parsed as Object)) {
    return failureResult(makeError('', 'expected an object'));
  }

  const record: Record<string, Object> = parsed as Record<string, Object>;
  const errors: FieldError[] = [];

  // id
  let idValue: string = '';
  const idVal: Object | undefined = fieldOrUndefined(record, 'id');
  if (isMissingOrNull(idVal)) {
    errors.push(makeError('id', 'required'));
  } else if (typeof idVal !== 'string') {
    errors.push(makeError('id', 'expected a string'));
  } else {
    const s: string = idVal as string;
    if (s === '') {
      errors.push(makeError('id', 'must not be empty'));
    } else {
      idValue = s;
    }
  }

  // status
  let statusValue: OrderStatus = OrderStatus.Draft;
  const statusVal: Object | undefined = fieldOrUndefined(record, 'status');
  if (!isMissingOrNull(statusVal)) {
    let valid: boolean = false;
    if (typeof statusVal === 'string') {
      const sv: string = statusVal as string;
      if (sv === 'draft') {
        statusValue = OrderStatus.Draft;
        valid = true;
      } else if (sv === 'paid') {
        statusValue = OrderStatus.Paid;
        valid = true;
      } else if (sv === 'shipped') {
        statusValue = OrderStatus.Shipped;
        valid = true;
      }
    }
    if (!valid) {
      errors.push(makeError('status', 'expected one of draft, paid, shipped'));
    }
  }

  // lines
  let lineList: OrderLine[] = [];
  const linesVal: Object | undefined = fieldOrUndefined(record, 'lines');
  if (isMissingOrNull(linesVal)) {
    errors.push(makeError('lines', 'required'));
  } else if (!Array.isArray(linesVal as Object)) {
    errors.push(makeError('lines', 'expected an array'));
  } else {
    const arr: Object[] = linesVal as Object[];
    if (arr.length === 0) {
      errors.push(makeError('lines', 'must not be empty'));
    }
    for (let i = 0; i < arr.length; i++) {
      const el: Object = arr[i];
      const basePath: string = 'lines[' + i.toString() + ']';
      if (el === null || typeof el !== 'object' || Array.isArray(el as Object)) {
        errors.push(makeError(basePath, 'expected an object'));
        continue;
      }
      const lineRec: Record<string, Object> = el as Record<string, Object>;
      let lineOk: boolean = true;

      // sku
      let skuValue: string = '';
      const skuVal: Object | undefined = fieldOrUndefined(lineRec, 'sku');
      if (isMissingOrNull(skuVal)) {
        errors.push(makeError(basePath + '.sku', 'required'));
        lineOk = false;
      } else if (typeof skuVal !== 'string') {
        errors.push(makeError(basePath + '.sku', 'expected a string'));
        lineOk = false;
      } else {
        const sv: string = skuVal as string;
        if (sv === '') {
          errors.push(makeError(basePath + '.sku', 'must not be empty'));
          lineOk = false;
        } else {
          skuValue = sv;
        }
      }

      // quantity
      let quantityValue: number = 0;
      const qVal: Object | undefined = fieldOrUndefined(lineRec, 'quantity');
      if (isMissingOrNull(qVal)) {
        errors.push(makeError(basePath + '.quantity', 'required'));
        lineOk = false;
      } else if (typeof qVal !== 'number') {
        errors.push(makeError(basePath + '.quantity', 'expected a number'));
        lineOk = false;
      } else {
        const q: number = qVal as number;
        if (Math.floor(q) !== q || q < 1) {
          errors.push(makeError(basePath + '.quantity', 'must be a whole number of 1 or more'));
          lineOk = false;
        } else {
          quantityValue = q;
        }
      }

      // unitPrice
      let unitPriceValue: number = 0;
      const upVal: Object | undefined = fieldOrUndefined(lineRec, 'unitPrice');
      if (isMissingOrNull(upVal)) {
        errors.push(makeError(basePath + '.unitPrice', 'required'));
        lineOk = false;
      } else if (typeof upVal !== 'number') {
        errors.push(makeError(basePath + '.unitPrice', 'expected a number'));
        lineOk = false;
      } else {
        const up: number = upVal as number;
        if (up < 0) {
          errors.push(makeError(basePath + '.unitPrice', 'must be 0 or more'));
          lineOk = false;
        } else {
          unitPriceValue = up;
        }
      }

      // unknown fields of the line, in the order they appear in the text
      const lineKeys: string[] = Object.keys(lineRec);
      for (let k = 0; k < lineKeys.length; k++) {
        const name: string = lineKeys[k];
        if (!LINE_FIELDS.includes(name)) {
          errors.push(makeError(basePath + '.' + name, 'unknown field'));
        }
      }

      if (lineOk) {
        lineList.push(new OrderLine(skuValue, quantityValue, unitPriceValue));
      }
    }
  }

  // unknown fields of the order, in the order they appear in the text
  const orderKeys: string[] = Object.keys(record);
  for (let k = 0; k < orderKeys.length; k++) {
    const name: string = orderKeys[k];
    if (!ORDER_FIELDS.includes(name)) {
      errors.push(makeError(name, 'unknown field'));
    }
  }

  if (errors.length > 0) {
    const r: ParseResult = { order: undefined, errors: errors };
    return r;
  }
  const order: Order = { id: idValue, status: statusValue, lines: lineList };
  const r: ParseResult = { order: order, errors: errors };
  return r;
}

export interface Expense {
  category: string;
  amount: number;
}

export function totalByCategory(expenses: Expense[]): Map<string, number> {
  const totals: Map<string, number> = new Map<string, number>();
  for (const expense of expenses) {
    const current: number | undefined = totals.get(expense.category);
    if (current === undefined) {
      totals.set(expense.category, expense.amount);
    } else {
      totals.set(expense.category, current + expense.amount);
    }
  }
  return totals;
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueTask {
  readonly start: () => void;
  readonly cancel: () => void;

  constructor(start: () => void, cancel: () => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

export class JobQueue {
  private readonly concurrencyLimit: number;
  private readonly pending: QueueTask[] = [];
  private readonly idleWaiters: Array<() => void> = [];
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;

  constructor(concurrency: number) {
    if (concurrency < 1 || Math.floor(concurrency) !== concurrency) {
      throw new Error('concurrency must be a whole number of 1 or more');
    }
    this.concurrencyLimit = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.pending.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const task: QueueTask = new QueueTask(() => {
        const p: Promise<T> = job();
        p.then((value: T): void => {
          this.completedCount++;
          resolve(value);
          this.onSettled();
        }, (err: Error): void => {
          this.failedCount++;
          reject(err);
          this.onSettled();
        });
      }, () => {
        reject(new Error('Job was cancelled'));
      });
      this.pending.push(task);
      this.tryStart();
    });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.tryStart();
  }

  clear(): number {
    const removed: QueueTask[] = this.pending.slice();
    this.pending.length = 0;
    for (const task of removed) {
      task.cancel();
    }
    this.checkIdle();
    return removed.length;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.pending.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleWaiters.push(resolve);
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomePromises: Array<Promise<JobOutcome<T>>> = [];
    for (const job of jobs) {
      const p: Promise<JobOutcome<T>> = this.add<T>(job).then(
        (value: T): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          return outcome;
        },
        (err: Error): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: err };
          return outcome;
        }
      );
      outcomePromises.push(p);
    }
    return Promise.all(outcomePromises);
  }

  private tryStart(): void {
    while (!this.paused && this.runningCount < this.concurrencyLimit && this.pending.length > 0) {
      const task: QueueTask | undefined = this.pending.shift();
      if (task === undefined) {
        continue;
      }
      this.runningCount++;
      task.start();
    }
  }

  private onSettled(): void {
    this.runningCount--;
    this.tryStart();
    this.checkIdle();
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.pending.length === 0) {
      const waiters: Array<() => void> = this.idleWaiters;
      this.idleWaiters.length = 0;
      for (const w of waiters) {
        w();
      }
    }
  }
}

export interface Settings {
  theme: string;
  fontSize: number;
  notifications: boolean;
  language: string;
}

export interface UserSettings {
  theme?: string;
  fontSize?: number;
  notifications?: boolean;
  language?: string;
}

export function defaultSettings(): Settings {
  const settings: Settings = {
    theme: 'light',
    fontSize: 14,
    notifications: true,
    language: 'en'
  };
  return settings;
}

export function mergeSettings(defaults: Settings, user: UserSettings): Settings {
  const merged: Settings = {
    theme: defaults.theme,
    fontSize: defaults.fontSize,
    notifications: defaults.notifications,
    language: defaults.language
  };
  if (user.theme !== undefined) {
    merged.theme = user.theme;
  }
  if (user.fontSize !== undefined) {
    merged.fontSize = user.fontSize;
  }
  if (user.notifications !== undefined) {
    merged.notifications = user.notifications;
  }
  if (user.language !== undefined) {
    merged.language = user.language;
  }
  return merged;
}

export interface Point {
  x: number;
  y: number;
}

export interface Box {
  min: Point;
  max: Point;
  width: number;
  height: number;
}

export function boundingBox(points: Point[]): Box | undefined {
  if (points.length === 0) {
    return undefined;
  }

  let minX: number = points[0].x;
  let minY: number = points[0].y;
  let maxX: number = points[0].x;
  let maxY: number = points[0].y;

  for (let i = 1; i < points.length; i++) {
    const p: Point = points[i];
    if (p.x < minX) {
      minX = p.x;
    }
    if (p.y < minY) {
      minY = p.y;
    }
    if (p.x > maxX) {
      maxX = p.x;
    }
    if (p.y > maxY) {
      maxY = p.y;
    }
  }

  const min: Point = { x: minX, y: minY };
  const max: Point = { x: maxX, y: maxY };
  const box: Box = { min: min, max: max, width: maxX - minX, height: maxY - minY };
  return box;
}

export class Stack<T> {
  private capacity: number;
  private items: Array<T> = [];

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  push(item: T): boolean {
    if (this.items.length >= this.capacity) {
      return false;
    }
    this.items.push(item);
    return true;
  }

  pop(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items.pop();
  }

  peek(): T | undefined {
    if (this.isEmpty()) {
      return undefined;
    }
    return this.items[this.items.length - 1];
  }

  size(): number {
    return this.items.length;
  }

  isEmpty(): boolean {
    return this.items.length === 0;
  }

  isFull(): boolean {
    return this.items.length >= this.capacity;
  }

  clear(): void {
    this.items = [];
  }

  toArray(): Array<T> {
    return this.items.slice();
  }
}

export type Listener<T> = (payload: T) => void;

export class EventBus<T> {
  private listeners: Map<string, Array<Listener<T>>>;

  constructor() {
    this.listeners = new Map<string, Array<Listener<T>>>();
  }

  on(event: string, listener: Listener<T>): void {
    const existing: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (existing === undefined) {
      const list: Array<Listener<T>> = [listener];
      this.listeners.set(event, list);
      return;
    }
    for (let i = 0; i < existing.length; i++) {
      if (existing[i] === listener) {
        return;
      }
    }
    existing.push(listener);
  }

  off(event: string, listener: Listener<T>): void {
    const existing: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return;
    }
    for (let i = 0; i < existing.length; i++) {
      if (existing[i] === listener) {
        existing.splice(i, 1);
        return;
      }
    }
  }

  emit(event: string, payload: T): number {
    const existing: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    const snapshot: Array<Listener<T>> = existing.slice();
    for (let i = 0; i < snapshot.length; i++) {
      snapshot[i](payload);
    }
    return snapshot.length;
  }

  listenerCount(event: string): number {
    const existing: Array<Listener<T>> | undefined = this.listeners.get(event);
    if (existing === undefined) {
      return 0;
    }
    return existing.length;
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  const users: User[] = [];

  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(json) as Object;
  } catch (err) {
    return users;
  }

  if (parsed === null || !Array.isArray(parsed)) {
    return users;
  }

  const items: Array<Object> = parsed as Array<Object>;

  for (const item of items) {
    if (item === null || typeof item !== 'object' || Array.isArray(item)) {
      continue;
    }

    const obj = item as Record<string, Object>;

    const idValue = obj['id'];
    if (typeof idValue !== 'number') {
      continue;
    }
    const id = idValue as number;
    if (!Number.isInteger(id)) {
      continue;
    }

    const nameValue = obj['name'];
    if (typeof nameValue !== 'string') {
      continue;
    }
    const userName = nameValue as string;
    if (userName.length === 0) {
      continue;
    }

    const emailValue = obj['email'];
    if (typeof emailValue !== 'string') {
      continue;
    }
    const userEmail = emailValue as string;
    if (!userEmail.includes('@')) {
      continue;
    }

    const user: User = {
      id: id,
      name: userName,
      email: userEmail
    };
    users.push(user);
  }

  return users;
}

export class RetryError extends Error {
  attempts: number;
  lastError: Error;

  constructor(attempts: number, lastError: Error) {
    super(`Failed after ${attempts} attempts: ${lastError.message}`);
    this.name = 'RetryError';
    this.attempts = attempts;
    this.lastError = lastError;
  }
}

export async function retry<T>(action: () => Promise<T>, attempts: number): Promise<T> {
  const maxAttempts: number = attempts < 1 ? 1 : attempts;
  let lastError: Error = new Error('unknown');

  for (let call: number = 1; call <= maxAttempts; call++) {
    try {
      return await action();
    } catch (e) {
      lastError = e as Error;
    }
  }

  throw new RetryError(maxAttempts, lastError);
}

function pad2(n: number): string {
  return n < 10 ? '0' + n.toString() : n.toString();
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const s: number = Math.abs(totalSeconds);
  const sec: number = s % 60;
  const totalMinutes: number = Math.floor(s / 60);
  const min: number = totalMinutes % 60;
  const hours: number = Math.floor(totalMinutes / 60);
  let text: string;
  if (s < 60) {
    text = `${s}s`;
  } else if (s < 3600) {
    text = `${totalMinutes}m ${pad2(sec)}s`;
  } else {
    text = `${hours}h ${pad2(min)}m ${pad2(sec)}s`;
  }
  return negative ? '-' + text : text;
}

function isAllDigits(digits: string): boolean {
  if (digits.length === 0) {
    return false;
  }
  for (let j = 0; j < digits.length; j++) {
    const code: number = digits.charCodeAt(j);
    if (code < 48 || code > 57) {
      return false;
    }
  }
  return true;
}

function partToSeconds(body: string): number {
  if (body.length < 2) {
    return NaN;
  }
  const unit: string = body.substring(body.length - 1);
  const digits: string = body.substring(0, body.length - 1);
  let mult: number;
  if (unit === 'h') {
    mult = 3600;
  } else if (unit === 'm') {
    mult = 60;
  } else if (unit === 's') {
    mult = 1;
  } else {
    return NaN;
  }
  if (!isAllDigits(digits)) {
    return NaN;
  }
  return Number(digits) * mult;
}

export function parseDuration(text: string): number {
  const parts: string[] = text.split(' ');
  if (parts.length === 0) {
    return NaN;
  }
  let negative: boolean = false;
  let total: number = 0;
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (part.length === 0) {
      return NaN;
    }
    let body: string = part;
    if (i === 0 && part.substring(0, 1) === '-') {
      negative = true;
      body = part.substring(1);
      if (body.length === 0) {
        return NaN;
      }
    }
    const value: number = partToSeconds(body);
    if (Number.isNaN(value)) {
      return NaN;
    }
    total += value;
  }
  return negative ? -total : total;
}

export interface Item {
  id: string;
  name: string;
  quantity: number;
}

export interface Change {
  id: string;
  quantity: number;
}

export function updateQuantity(items: Item[], id: string, quantity: number): Item[] {
  const result: Item[] = [];
  for (const item of items) {
    if (item.id === id) {
      if (quantity > 0) {
        const updated: Item = {
          id: item.id,
          name: item.name,
          quantity: quantity
        };
        result.push(updated);
      }
    } else {
      result.push(item);
    }
  }
  return result;
}

export function applyChanges(items: Item[], changes: Change[]): Item[] {
  let current: Item[] = items;
  for (const change of changes) {
    const next: Item[] = updateQuantity(current, change.id, change.quantity);
    let removed = false;
    for (const item of current) {
      if (item.id === change.id) {
        let found = false;
        for (const nextItem of next) {
          if (nextItem.id === change.id) {
            found = true;
            break;
          }
        }
        if (!found) {
          removed = true;
        }
        break;
      }
    }
    if (removed) {
      const remaining: Item[] = [];
      for (const item of next) {
        remaining.push(item);
      }
      current = remaining;
      const stillPresent: Item[] = [];
      for (const item of current) {
        stillPresent.push(item);
      }
      current = stillPresent;
      const kept: Item[] = [];
      for (const item of current) {
        kept.push(item);
      }
      current = kept;
      const filtered: Item[] = [];
      for (const item of current) {
        filtered.push(item);
      }
      current = filtered;
      const snapshot: Item[] = [];
      for (const item of current) {
        snapshot.push(item);
      }
      current = snapshot;
      const finalItems: Item[] = [];
      for (const item of current) {
        finalItems.push(item);
      }
      current = finalItems;
      const removedIds: Map<string, boolean> = new Map<string, boolean>();
      removedIds.set(change.id, true);
      const afterRemoval: Item[] = [];
      for (const item of current) {
        if (!removedIds.has(item.id)) {
          afterRemoval.push(item);
        }
      }
      current = afterRemoval;
    } else {
      current = next;
    }
  }
  const output: Item[] = [];
  for (const item of current) {
    output.push(item);
  }
  return output;
}

export interface Pair<A, B> {
  first: A;
  second: B;
}

export function chunk<T>(items: T[], size: number): T[][] {
  const result: T[][] = [];
  if (size < 1) {
    return result;
  }
  let current: T[] = [];
  for (let i = 0; i < items.length; i++) {
    current.push(items[i]);
    if (current.length === size) {
      result.push(current);
      current = [];
    }
  }
  if (current.length > 0) {
    result.push(current);
  }
  return result;
}

export function zip<A, B>(a: A[], b: B[]): Pair<A, B>[] {
  const result: Pair<A, B>[] = [];
  const length: number = a.length < b.length ? a.length : b.length;
  for (let i = 0; i < length; i++) {
    const pair: Pair<A, B> = { first: a[i], second: b[i] };
    result.push(pair);
  }
  return result;
}

/**
 * A geometric shape.
 *
 * Modelled as an abstract class so that new kinds of shapes can be added
 * later: a new shape only has to extend Shape and implement area().
 * The area() and totalArea() functions keep working unchanged, because they
 * rely on the polymorphic area() method instead of inspecting shape kinds.
 */
export abstract class Shape {
  /**
   * Returns the area of this shape.
   */
  public abstract area(): number;
}

/**
 * A circle given by its radius.
 */
class CircleFigure extends Shape {
  private readonly radius: number;

  constructor(radius: number) {
    super();
    this.radius = radius;
  }

  public area(): number {
    return Math.PI * this.radius * this.radius;
  }
}

/**
 * A rectangle given by its width and height.
 */
class RectangleFigure extends Shape {
  private readonly width: number;
  private readonly height: number;

  constructor(width: number, height: number) {
    super();
    this.width = width;
    this.height = height;
  }

  public area(): number {
    return this.width * this.height;
  }
}

/**
 * A triangle given by one side (the base) and the height measured on that side.
 */
class TriangleFigure extends Shape {
  private readonly base: number;
  private readonly height: number;

  constructor(base: number, height: number) {
    super();
    this.base = base;
    this.height = height;
  }

  public area(): number {
    return this.base * this.height / 2;
  }
}

/**
 * Creates a circle with the given radius.
 */
export function circle(radius: number): Shape {
  return new CircleFigure(radius);
}

/**
 * Creates a rectangle with the given width and height.
 */
export function rectangle(width: number, height: number): Shape {
  return new RectangleFigure(width, height);
}

/**
 * Creates a triangle from one side (the base) and the height on that side.
 */
export function triangle(base: number, height: number): Shape {
  return new TriangleFigure(base, height);
}

/**
 * Returns the area of a single shape.
 */
export function area(shape: Shape): number {
  return shape.area();
}

/**
 * Returns the sum of the areas of all the given shapes; 0 for an empty list.
 */
export function totalArea(shapes: Shape[]): number {
  let sum: number = 0;
  for (const shape of shapes) {
    sum += area(shape);
  }
  return sum;
}

/**
 * Days of the week, running from Monday to Sunday.
 */
export enum Weekday {
  Monday = 0,
  Tuesday = 1,
  Wednesday = 2,
  Thursday = 3,
  Friday = 4,
  Saturday = 5,
  Sunday = 6
}

/**
 * A rule meaning the place is open on `day` from `openHour`
 * up to, but not including, `closeHour`.
 */
export interface OpeningRule {
  day: Weekday;
  openHour: number;
  closeHour: number;
}

/**
 * Returns true when some rule covers the given day and hour.
 * The place is open from openHour up to, but not including, closeHour.
 */
export function isOpen(rules: OpeningRule[], day: Weekday, hour: number): boolean {
  for (const rule of rules) {
    if (rule.day === day && hour >= rule.openHour && hour < rule.closeHour) {
      return true;
    }
  }
  return false;
}

/**
 * Returns the first day after `day` that has at least one rule,
 * going forward through the week and wrapping from Sunday to Monday.
 *
 * `day` itself is checked last: if it is the only day with a rule,
 * the answer is `day` itself (one week later). If no day has a rule,
 * returns undefined.
 */
export function nextOpenDay(rules: OpeningRule[], day: Weekday): Weekday | undefined {
  const week: Weekday[] = [
    Weekday.Monday,
    Weekday.Tuesday,
    Weekday.Wednesday,
    Weekday.Thursday,
    Weekday.Friday,
    Weekday.Saturday,
    Weekday.Sunday
  ];
  const startIndex: number = week.indexOf(day);
  // Steps 1..6 cover the days after `day`; step 7 wraps back to `day` itself.
  for (let step: number = 1; step <= 7; step++) {
    const candidate: Weekday = week[(startIndex + step) % 7];
    for (const rule of rules) {
      if (rule.day === candidate) {
        return candidate;
      }
    }
  }
  return undefined;
}

/**
 * Represents a generic Least Recently Used (LRU) Cache.
 * @template K The type of the keys.
 * @template V The type of the values.
 */
class LruCache<K, V> {
  private capacity: number;
  // Map stores the actual key-value pairs for O(1) lookup.
  private dataMap: Map<K, V>;
  // usageList tracks the order of keys: LRU at index 0, MRU at the end.
  private usageList: Array<K>;

  /**
   * Creates an instance of LruCache.
   * @param capacity The maximum number of keys the cache can hold. Must be 1 or more.
   */
  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error("Capacity must be 1 or more.");
    }
    this.capacity = capacity;
    this.dataMap = new Map<K, V>();
    this.usageList = [];
  }

  /**
   * Retrieves the value associated with the given key and marks it as most recently used.
   * @param key The key to retrieve.
   * @returns The stored value, or undefined if the key is not found.
   */
  public get(key: K): V | undefined {
    if (!this.dataMap.has(key)) {
      return undefined;
    }

    // 1. Retrieve value
    const value = this.dataMap.get(key);

    // 2. Update usage: Move key to MRU position (end of usageList)
    this.updateUsage(key);

    return value;
  }

  /**
   * Stores a value for the given key, marking it as most recently used.
   * If the key exists, its value is replaced. If the cache exceeds capacity, the LRU item is evicted.
   * @param key The key to store.
   * @param value The value to store.
   */
  public set(key: K, value: V): void {
    // 1. If the key exists, remove it from its current position in the usage list
    if (this.dataMap.has(key)) {
      this.usageList.splice(this.usageList.indexOf(key), 1);
    }

    // 2. Store the value
    this.dataMap.set(key, value);

    // 3. Add key to MRU position
    this.usageList.push(key);

    // 4. Check capacity and evict LRU if necessary
    if (this.dataMap.size > this.capacity) {
      // LRU key is at index 0
      const lruKey = this.usageList[0];

      // Remove LRU from map
      this.dataMap.delete(lruKey);

      // Remove LRU from usage list
      this.usageList.shift();
    }
  }

  /**
   * Checks if the cache contains the specified key. Does not count as a usage.
   * @param key The key to check.
   * @returns True if the key is stored, false otherwise.
   */
  public has(key: K): boolean {
    return this.dataMap.has(key);
  }

  /**
   * Returns a new array containing all stored keys, ordered from LRU to MRU.
   * @returns An array of keys.
   */
  public keys(): Array<K> {
    // Return a copy to prevent external modification of internal state
    return [...this.usageList];
  }

  /**
   * Gets the current number of keys stored in the cache.
   * @returns The size of the cache.
   */
  public get size(): number {
    return this.dataMap.size;
  }

  /**
   * Internal helper function to move a key to the MRU position in the usage list.
   * Assumes the key is already present in the map.
   * @param key The key to update.
   */
  private updateUsage(key: K): void {
    const index = this.usageList.indexOf(key);
    if (index !== -1) {
      // Remove from current position
      this.usageList.splice(index, 1);
      // Add to MRU position (end)
      this.usageList.push(key);
    }
  }
}

/**
 * Self-contained URL query-string parser.
 *
 * Rules implemented:
 *  - One leading '?' is ignored.
 *  - Pairs are separated by '&'; empty parts are skipped.
 *  - A pair is split at its first '='; a part without '=' is a key with value ''.
 *  - Keys and values are decoded: '+' becomes a space, then percent-escapes are
 *    decoded as UTF-8 (so '%2B' yields a literal '+'). If a key or value contains
 *    a malformed escape (e.g. '%zz'), that whole key/value is kept as written and
 *    only '+' is replaced.
 *  - Pairs whose raw key is empty are ignored.
 *  - Repeated keys keep their first position; the last value wins.
 */

// Returns true when c is one of '0'-'9', 'A'-'F', 'a'-'f'.
function isHexDigit(c: string): boolean {
  const code: number = c.charCodeAt(0);
  return (code >= 0x30 && code <= 0x39) || (code >= 0x41 && code <= 0x46) ||
    (code >= 0x61 && code <= 0x66);
}

// Returns true when b is a UTF-8 continuation byte (10xxxxxx).
function isUtf8Continuation(b: number): boolean {
  return b >= 0x80 && b < 0xC0;
}

// True when the string contains a '%' that is not followed by two hex digits.
function hasMalformedEscape(s: string): boolean {
  const n: number = s.length;
  for (let i = 0; i < n; i++) {
    if (s.charAt(i) === '%') {
      if (i + 2 >= n) {
        return true;
      }
      if (!isHexDigit(s.charAt(i + 1)) || !isHexDigit(s.charAt(i + 2))) {
        return true;
      }
    }
  }
  return false;
}

// Replaces every '+' with a space, leaving everything else untouched.
function replacePlusWithSpace(s: string): string {
  let out: string = '';
  const n: number = s.length;
  for (let i = 0; i < n; i++) {
    const c: string = s.charAt(i);
    if (c === '+') {
      out += ' ';
    } else {
      out += c;
    }
  }
  return out;
}

// String for a code point; uses a surrogate pair above the BMP.
function codePointToString(cp: number): string {
  if (cp <= 0xFFFF) {
    return String.fromCharCode(cp);
  }
  const offset: number = cp - 0x10000;
  const high: number = 0xD800 + Math.floor(offset / 0x400);
  const low: number = 0xDC00 + (offset % 0x400);
  return String.fromCharCode(high, low);
}

// Decodes a sequence of bytes as UTF-8. Byte sequences that do not form a
// valid multi-byte character fall back to one character per byte.
function decodeUtf8Bytes(bytes: number[]): string {
  let out: string = '';
  const n: number = bytes.length;
  let i = 0;
  while (i < n) {
    const lead: number = bytes[i];
    if (lead < 0x80) {
      out += String.fromCharCode(lead);
      i += 1;
      continue;
    }
    let extra: number = 0;
    if (lead >= 0xC0 && lead < 0xE0) {
      extra = 1;
    } else if (lead >= 0xE0 && lead < 0xF0) {
      extra = 2;
    } else if (lead >= 0xF0 && lead < 0xF8) {
      extra = 3;
    }
    let complete: boolean = extra > 0;
    if (complete) {
      for (let k = 1; k <= extra; k++) {
        if (i + k >= n || !isUtf8Continuation(bytes[i + k])) {
          complete = false;
          break;
        }
      }
    }
    if (complete) {
      let cp: number = 0;
      if (extra === 1) {
        cp = ((lead & 0x1F) << 6) | (bytes[i + 1] & 0x3F);
      } else if (extra === 2) {
        cp = ((lead & 0x0F) << 12) | ((bytes[i + 1] & 0x3F) << 6) | (bytes[i + 2] & 0x3F);
      } else {
        cp = ((lead & 0x07) << 18) | ((bytes[i + 1] & 0x3F) << 12) |
          ((bytes[i + 2] & 0x3F) << 6) | (bytes[i + 3] & 0x3F);
      }
      out += codePointToString(cp);
      i += extra + 1;
    } else {
      out += String.fromCharCode(lead);
      i += 1;
    }
  }
  return out;
}

// Decodes contiguous runs of '%XX' escapes as UTF-8 byte sequences. The caller
// guarantees every '%' is followed by two hex digits.
function percentDecode(s: string): string {
  let out: string = '';
  const n: number = s.length;
  let i = 0;
  while (i < n) {
    if (s.charAt(i) !== '%') {
      out += s.charAt(i);
      i += 1;
      continue;
    }
    const bytes: number[] = [];
    while (i < n && s.charAt(i) === '%') {
      bytes.push(parseInt(s.substring(i + 1, i + 3), 16));
      i += 3;
    }
    out += decodeUtf8Bytes(bytes);
  }
  return out;
}

// Decodes one key or value: '+' to space first, then percent-escapes as UTF-8,
// unless a malformed escape is present (then only '+' is replaced).
function decodePart(raw: string): string {
  const noPlus: string = replacePlusWithSpace(raw);
  if (hasMalformedEscape(noPlus)) {
    return noPlus;
  }
  return percentDecode(noPlus);
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let rest: string = query;
  if (rest.length > 0 && rest.charAt(0) === '?') {
    rest = rest.substring(1);
  }
  if (rest.length === 0) {
    return result;
  }
  const parts: string[] = rest.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq: number = part.indexOf('=');
    let rawKey: string = '';
    let rawValue: string = '';
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    if (rawKey.length === 0) {
      continue;
    }
    const key: string = decodePart(rawKey);
    const value: string = decodePart(rawValue);
    // Setting an existing key updates its value and keeps its original position.
    result.set(key, value);
  }
  return result;
}

