    this.text = text;
  }
}

@Entry
@Component
struct TodoPage {
  // The list of todos; the array itself is observed, so push/reassign refresh the UI.
  @State todos: Array<TodoItem> = [];
  // Current content of the input field.
  @State inputText: string = '';
  // Monotonic id source so every todo has a unique, stable key.
  private nextId: number = 1;

  addTodo(): void {
    const text: string = this.inputText.trim();
    if (text.length === 0) {
      return;
    }
    this.todos.push(new TodoItem(this.nextId, text));
    this.nextId = this.nextId + 1;
    // Clear the input; the TextInput re-renders from this state.
    this.inputText = '';
  }

  removeTodo(id: number): void {
    // Remove only the todo with the matching id, even if texts are identical.
    this.todos = this.todos.filter((item: TodoItem) => item.id !== id);
  }

  build() {
    Column() {
      Row() {
        TextInput({ placeholder: 'New todo', text: this.inputText })
          .onChange((value: string) => {
            this.inputText = value;
          })
          .layoutWeight(1)
          .padding(8)

        Button('Add')
          .margin({ left: 8 })
          .onClick(() => {
            this.addTodo();
          })
      }
      .width('100%')
      .alignItems(VerticalAlign.Center)

      List() {
        ForEach(
          this.todos,
          (item: TodoItem) => {
            ListItem() {
              Text(item.text)
                .fontSize(18)
                .width('100%')
                .padding(12)
                .onClick(() => {
                  this.removeTodo(item.id);
                })
            }
          },
          (item: TodoItem) => item.id.toString()
        )
      }
      .layoutWeight(1)
      .width('100%')
      .margin({ top: 8 })
      .divider({
        strokeWidth: 1,
        color: '#E0E0E0',
        startMargin: 12,
        endMargin: 12
      })
    }
    .width('100%')
    .height('100%')
    .padding(16)
  }
}

