import { hilog } from '@kit.PerformanceAnalysisKit';

const LOG_DOMAIN: number = 0x0000;
const LOG_TAG: string = 'SignInPage';

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  private isEmailValid(value: string): boolean {
    const parts: string[] = value.split('@');
    if (parts.length !== 2) {
      return false;
    }
    const localPart: string = parts[0];
    const domainPart: string = parts[1];
    if (localPart.length < 1) {
      return false;
    }
    const dotIndex: number = domainPart.indexOf('.');
    return dotIndex >= 1 && dotIndex <= domainPart.length - 2;
  }

  private isPasswordValid(value: string): boolean {
    return value.length >= 8;
  }

  private canSubmit(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  build() {
    Column({ space: 12 }) {
      TextInput({ placeholder: 'Email' })
        .type(InputType.Email)
        .width('100%')
        .onChange((value: string) => {
          this.email = value;
        })

      if (this.email.length > 0 && !this.isEmailValid(this.email)) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
      }

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .width('100%')
        .onChange((value: string) => {
          this.password = value;
        })

      if (this.password.length > 0 && !this.isPasswordValid(this.password)) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor(Color.Red)
          .width('100%')
      }

      Button('Sign in')
        .width('100%')
        .enabled(this.canSubmit())
        .opacity(this.canSubmit() ? 1 : 0.5)
        .onClick(() => {
          hilog.info(LOG_DOMAIN, LOG_TAG, 'Sign in tapped, email: %{public}s', this.email);
        })
    }
    .width('100%')
    .height('100%')
    .padding(24)
    .justifyContent(FlexAlign.Center)
  }
}

