// solution.ets
// Entry page: shows the persisted name, lets the user type a new one and save it.
// The name is stored with the preferences kit so it survives closing the app.

import { preferences } from '@kit.ArkData';

const PREFS_FILE: string = 'user_prefs';
const KEY_SAVED_NAME: string = 'saved_name';

@Entry
@Component
struct NameSaverPage {
  @State savedName: string = '';
  @State inputName: string = '';

  aboutToAppear(): void {
    this.loadSavedName();
  }

  onPageShow(): void {
    this.loadSavedName();
  }

  private async loadSavedName(): Promise<void> {
    try {
      const context = getContext(this);
      const prefs = await preferences.getPreferences(context, PREFS_FILE);
      const value: preferences.ValueType = await prefs.get(KEY_SAVED_NAME, '');
      if (typeof value === 'string' && value.length > 0) {
        this.savedName = value;
      } else {
        this.savedName = '';
      }
    } catch (e) {
      this.savedName = '';
    }
  }

  private async saveName(): Promise<void> {
    const name: string = this.inputName.trim();
    if (name.length === 0) {
      return;
    }
    try {
      const context = getContext(this);
      const prefs = await preferences.getPreferences(context, PREFS_FILE);
      await prefs.put(KEY_SAVED_NAME, name);
      await prefs.flush();
      this.savedName = name;
      this.inputName = '';
    } catch (e) {
      // Saving failed: keep showing the previously stored name.
    }
  }

  build() {
    Column({ space: 20 }) {
      Text(this.savedName.length > 0 ? `Hello, ${this.savedName}` : 'No name saved')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .textAlign(TextAlign.Center)

      TextInput({ placeholder: 'Type your name', text: this.inputName })
        .width('100%')
        .height(48)
        .onChange((value: string) => {
          this.inputName = value;
        })

      Button('Save')
        .width('100%')
        .height(48)
        .fontSize(18)
        .onClick(() => {
          this.saveName();
        })
    }
    .width('100%')
    .height('100%')
    .padding(20)
    .justifyContent(FlexAlign.Center)
    .alignItems(HorizontalAlign.Center)
  }
}

/**
 * Parses a URL query string (e.g. "a=1&b=two") into a Map.
 *
 * Rules implemented:
 *  - One leading '?' is ignored.
 *  - Pairs are separated by '&'; empty parts are skipped.
 *  - A pair is split at its first '='; a part without '=' has value ''.
 *  - Keys and values are decoded: '+' -> space, percent-escapes -> UTF-8.
 *    A key/value containing a malformed escape is kept as written, with
 *    only '+' replaced by a space.
 *  - Pairs whose (decoded) key is empty are ignored.
 *  - Keys keep their first-appearance order; the last value wins.
 */

function isHexDigit(code: number): boolean {
  return (code >= 0x30 && code <= 0x39)
    || (code >= 0x41 && code <= 0x46)
    || (code >= 0x61 && code <= 0x66);
}

function hexValue(code: number): number {
  if (code <= 0x39) {
    return code - 0x30;
  }
  if (code <= 0x46) {
    return code - 0x41 + 10;
  }
  return code - 0x61 + 10;
}

function replacePlusWithSpace(s: string): string {
  return s.split('+').join(' ');
}

function codePointToString(cp: number): string {
  if (cp <= 0xFFFF) {
    return String.fromCharCode(cp);
  }
  const offset = cp - 0x10000;
  return String.fromCharCode(0xD800 + (offset >> 10), 0xDC00 + (offset & 0x3FF));
}

// Strict UTF-8 decoding of a byte sequence; returns null when invalid.
function decodeUtf8Bytes(bytes: number[]): string | null {
  const out: string[] = [];
  const size = bytes.length;
  let i = 0;
  while (i < size) {
    const lead = bytes[i];
    let cp: number;
    let extra: number;
    if (lead < 0x80) {
      cp = lead;
      extra = 0;
    } else if (lead >= 0xC2 && lead <= 0xDF) {
      cp = lead & 0x1F;
      extra = 1;
    } else if (lead >= 0xE0 && lead <= 0xEF) {
      cp = lead & 0x0F;
      extra = 2;
    } else if (lead >= 0xF0 && lead <= 0xF4) {
      cp = lead & 0x07;
      extra = 3;
    } else {
      return null;
    }
    if (i + extra >= size) {
      return null;
    }
    for (let k = 1; k <= extra; k++) {
      const cont = bytes[i + k];
      if (cont < 0x80 || cont > 0xBF) {
        return null;
      }
      if (k === 1) {
        if (lead === 0xE0 && cont < 0xA0) {
          return null;
        }
        if (lead === 0xED && cont > 0x9F) {
          return null;
        }
        if (lead === 0xF0 && cont < 0x90) {
          return null;
        }
        if (lead === 0xF4 && cont > 0x8F) {
          return null;
        }
      }
      cp = (cp << 6) | (cont & 0x3F);
    }
    out.push(codePointToString(cp));
    i += extra + 1;
  }
  return out.join('');
}

// Decodes one key or value. On any malformed escape or invalid UTF-8
// sequence, the original text is kept, with only '+' replaced by a space.
function decodePart(part: string): string {
  let result = '';
  let pending: number[] = [];
  let inEscapeRun = false;
  const size = part.length;
  let i = 0;
  while (i < size) {
    const ch = part.charAt(i);
    if (ch === '%') {
      if (i + 2 < size && isHexDigit(part.charCodeAt(i + 1)) && isHexDigit(part.charCodeAt(i + 2))) {
        const high = hexValue(part.charCodeAt(i + 1));
        const low = hexValue(part.charCodeAt(i + 2));
        pending.push(high * 16 + low);
        inEscapeRun = true;
        i += 3;
      } else {
        return replacePlusWithSpace(part);
      }
    } else {
      if (inEscapeRun) {
        const decoded = decodeUtf8Bytes(pending);
        if (decoded === null) {
          return replacePlusWithSpace(part);
        }
        result += decoded;
        pending = [];
        inEscapeRun = false;
      }
      result += ch === '+' ? ' ' : ch;
      i += 1;
    }
  }
  if (inEscapeRun) {
    const decoded = decodeUtf8Bytes(pending);
    if (decoded === null) {
      return replacePlusWithSpace(part);
    }
    result += decoded;
  }
  return result;
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  if (!query) {
    return result;
  }
  let body = query;
  if (body.charAt(0) === '?') {
    body = body.substring(1);
  }
  if (body.length === 0) {
    return result;
  }
  const parts = body.split('&');
  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }
    const eq = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key = decodePart(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value = decodePart(rawValue);
    // Map.set keeps the key's original insertion position while the
    // new value overwrites any previous one.
    result.set(key, value);
  }
  return result;
}

/**
 * Entry page of the app: a sign-in form in a vertical layout.
 *
 * - The email field brings up the keyboard for typing email addresses.
 * - The password field masks what the user types.
 * - Both fields are re-validated on every keystroke; an error message is
 *   shown under a field only while that field is non-empty and invalid.
 * - "Sign in" stays disabled until both fields are valid and, when tapped,
 *   only writes a line to the log (no network access).
 */

@Entry
@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';

  /**
   * An email is valid when it has exactly one '@', at least one character
   * before it, and after it a '.' with at least one character on each side
   * (name@host.tld).
   */
  private isEmailValid(value: string): boolean {
    const atCount = value.split('@').length - 1;
    if (atCount !== 1) {
      return false; // must be exactly one '@'
    }
    const at = value.indexOf('@');
    if (at === 0) {
      return false; // nothing before '@'
    }
    const domain = value.substring(at + 1);
    const dot = domain.indexOf('.');
    // At least one character between '@' and the '.',
    // and at least one character after the '.'.
    return dot > 0 && dot < domain.length - 1;
  }

  /** A password is valid when it has at least 8 characters. */
  private isPasswordValid(value: string): boolean {
    return value.length >= 8;
  }

  /** The button may be tapped only when both fields are valid. */
  private canSignIn(): boolean {
    return this.isEmailValid(this.email) && this.isPasswordValid(this.password);
  }

  build() {
    Column({ space: 12 }) {
      TextInput({ placeholder: 'Email' })
        .type(InputType.Email)
        .height(48)
        .width('100%')
        .onChange((value: string) => {
          this.email = value;
        })

      if (this.email.length > 0 && !this.isEmailValid(this.email)) {
        Text('Enter a valid email address')
          .fontSize(12)
          .fontColor('#D32F2F')
          .width('100%')
      }

      TextInput({ placeholder: 'Password' })
        .type(InputType.Password)
        .height(48)
        .width('100%')
        .onChange((value: string) => {
          this.password = value;
        })

      if (this.password.length > 0 && !this.isPasswordValid(this.password)) {
        Text('Password must be at least 8 characters')
          .fontSize(12)
          .fontColor('#D32F2F')
          .width('100%')
      }

      Button('Sign in')
        .width('100%')
        .height(40)
        .enabled(this.canSignIn())
        .onClick(() => {
          if (this.canSignIn()) {
            console.info('Sign in tapped');
          }
        })
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .alignItems(HorizontalAlign.Start)
  }
}

/*
 * A small calculator for arithmetic expressions with variables,
 * e.g. price * (qty - 1) / 2.
 *
 * Pipeline: tokenize -> parse into a tree (all syntax errors reported here)
 * -> evaluate the tree left to right (name and division errors here).
 */

export interface Token {
  kind: string; // 'number' | 'name' | 'operator' | 'paren'
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigit(ch: string): boolean {
  const code: number = ch.charCodeAt(0);
  return code >= 48 && code <= 57; // '0'..'9'
}

function isNameStart(ch: string): boolean {
  const code: number = ch.charCodeAt(0);
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122) || code === 95; // A-Z, a-z, _
}

function isNamePart(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let index: number = 0;
  while (index < source.length) {
    const ch: string = source.charAt(index);
    if (ch === ' ') {
      index++;
      continue;
    }
    if (isDigit(ch)) {
      const start: number = index;
      while (index < source.length && isDigit(source.charAt(index))) {
        index++;
      }
      // A '.' belongs to the number only with a digit on both sides.
      if (source.charAt(index) === '.' && isDigit(source.charAt(index + 1))) {
        index++;
        while (index < source.length && isDigit(source.charAt(index))) {
          index++;
        }
      }
      const token: Token = { kind: 'number', text: source.substring(start, index), position: start };
      tokens.push(token);
      continue;
    }
    if (isNameStart(ch)) {
      const start: number = index;
      while (index < source.length && isNamePart(source.charAt(index))) {
        index++;
      }
      const token: Token = { kind: 'name', text: source.substring(start, index), position: start };
      tokens.push(token);
      continue;
    }
    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%') {
      const token: Token = { kind: 'operator', text: ch, position: index };
      tokens.push(token);
      index++;
      continue;
    }
    if (ch === '(' || ch === ')') {
      const token: Token = { kind: 'paren', text: ch, position: index };
      tokens.push(token);
      index++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${ch}'`, index);
  }
  return tokens;
}

// Parse tree nodes.

class ExprNode {
}

class NumberNode extends ExprNode {
  value: number;

  constructor(token: Token) {
    super();
    this.value = Number(token.text);
  }
}

class NameNode extends ExprNode {
  name: string;
  position: number;

  constructor(token: Token) {
    super();
    this.name = token.text;
    this.position = token.position;
  }
}

class UnaryNode extends ExprNode {
  operand: ExprNode;

  constructor(operand: ExprNode) {
    super();
    this.operand = operand;
  }
}

class BinaryNode extends ExprNode {
  operator: Token;
  left: ExprNode;
  right: ExprNode;

  constructor(operator: Token, left: ExprNode, right: ExprNode) {
    super();
    this.operator = operator;
    this.left = left;
    this.right = right;
  }
}

// Recursive descent parser. It only builds the tree, so every syntax error
// is reported before any evaluation happens.

class Parser {
  private tokens: Token[];
  private sourceLength: number;
  private index: number;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
    this.index = 0;
  }

  parse(): ExprNode {
    const node: ExprNode = this.parseExpression();
    const extra: Token | undefined = this.peek();
    if (extra !== undefined) {
      throw new ExpressionError(`Unexpected token '${extra.text}'`, extra.position);
    }
    return node;
  }

  private peek(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return undefined;
  }

  private parseExpression(): ExprNode {
    let node: ExprNode = this.parseTerm();
    while (true) {
      const tok: Token | undefined = this.peek();
      if (tok === undefined) {
        break;
      }
      if (tok.kind === 'operator' && (tok.text === '+' || tok.text === '-')) {
        this.index++;
        const right: ExprNode = this.parseTerm();
        node = new BinaryNode(tok, node, right);
      } else {
        break;
      }
    }
    return node;
  }

  private parseTerm(): ExprNode {
    let node: ExprNode = this.parseUnary();
    while (true) {
      const tok: Token | undefined = this.peek();
      if (tok === undefined) {
        break;
      }
      if (tok.kind === 'operator' && (tok.text === '*' || tok.text === '/' || tok.text === '%')) {
        this.index++;
        const right: ExprNode = this.parseUnary();
        node = new BinaryNode(tok, node, right);
      } else {
        break;
      }
    }
    return node;
  }

  private parseUnary(): ExprNode {
    const tok: Token | undefined = this.peek();
    if (tok === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (tok.kind === 'operator' && tok.text === '-') {
      this.index++;
      const operand: ExprNode = this.parseUnary();
      return new UnaryNode(operand);
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ExprNode {
    const tok: Token | undefined = this.peek();
    if (tok === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (tok.kind === 'number') {
      this.index++;
      return new NumberNode(tok);
    }
    if (tok.kind === 'name') {
      this.index++;
      return new NameNode(tok);
    }
    if (tok.kind === 'paren' && tok.text === '(') {
      this.index++;
      const inner: ExprNode = this.parseExpression();
      const closing: Token | undefined = this.peek();
      if (closing === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (closing.kind !== 'paren' || closing.text !== ')') {
        throw new ExpressionError(`Unexpected token '${closing.text}'`, closing.position);
      }
      this.index++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${tok.text}'`, tok.position);
  }
}

function evalNode(node: ExprNode, vars: Map<string, number>): number {
  if (node instanceof NumberNode) {
    return node.value;
  }
  if (node instanceof NameNode) {
    const value: number | undefined = vars.get(node.name);
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return value;
  }
  if (node instanceof UnaryNode) {
    return -evalNode(node.operand, vars);
  }
  if (node instanceof BinaryNode) {
    const left: number = evalNode(node.left, vars);
    const right: number = evalNode(node.right, vars);
    const op: string = node.operator.text;
    if (op === '+') {
      return left + right;
    }
    if (op === '-') {
      return left - right;
    }
    if (op === '*') {
      return left * right;
    }
    if (right === 0) {
      throw new ExpressionError('Division by zero', node.operator.position);
    }
    if (op === '/') {
      return left / right;
    }
    return left % right;
  }
  throw new ExpressionError('Unknown expression node', 0);
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens: Token[] = tokenize(source);
  const parser: Parser = new Parser(tokens, source.length);
  const root: ExprNode = parser.parse();
  const vars: Map<string, number> = new Map<string, number>();
  const keys: string[] = Object.keys(variables);
  for (const key of keys) {
    const value: number | undefined = variables[key];
    if (value !== undefined) {
      vars.set(key, value);
    }
  }
  return evalNode(root, vars);
}

/**
 * The observable fields of a small text editor.
 */
export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

/**
 * Listener invoked with (newValue, previousValue) for one watched field.
 */
export type EditorListener = (value: string | number | boolean,
  previous: string | number | boolean) => void;

/**
 * Internal registration record; entry identity makes unsubscription safe
 * even when the same listener function is registered more than once.
 */
class ListenerEntry {
  listener: EditorListener;

  constructor(listener: EditorListener) {
    this.listener = listener;
  }
}

/**
 * EditorStore: current editor state, bounded undo/redo history and
 * per-field change listeners. Patches change single fields; every accepted
 * change is one history step.
 */
export class EditorStore {
  private historyLimit: number = 1;
  private snapshots: EditorState[] = [];
  private histIndex: number = 0;
  private textListeners: ListenerEntry[] = [];
  private cursorListeners: ListenerEntry[] = [];
  private boldListeners: ListenerEntry[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    // Store a private copy so later edits to `initial` do not affect the store.
    const copy: EditorState = { text: initial.text, cursor: initial.cursor, bold: initial.bold };
    this.snapshots = [copy];
    this.histIndex = 0;
    this.historyLimit = historyLimit;
  }

  /**
   * A fresh object with the current values on every read.
   */
  get state(): EditorState {
    const current: EditorState = this.snapshots[this.histIndex];
    const copy: EditorState = { text: current.text, cursor: current.cursor, bold: current.bold };
    return copy;
  }

  /**
   * Applies every present (non-undefined) field of the patch. Returns false
   * (and changes nothing, keeping the redo branch) when no value differs.
   */
  apply(patch: Partial<EditorState>): boolean {
    const current: EditorState = this.snapshots[this.histIndex];
    let nextText: string = current.text;
    let nextCursor: number = current.cursor;
    let nextBold: boolean = current.bold;
    if (patch.text !== undefined) {
      nextText = patch.text;
    }
    if (patch.cursor !== undefined) {
      nextCursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      nextBold = patch.bold;
    }
    return this.applyValues(nextText, nextCursor, nextBold);
  }

  /**
   * Runs `run` once with a private copy of the current state. When it returns,
   * the draft's values are applied as one step. If `run` throws, the store is
   * untouched (the draft is only a copy) and the error reaches the caller.
   */
  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = this.state;
    run(draft);
    return this.applyValues(draft.text, draft.cursor, draft.bold);
  }

  /**
   * Goes back one step, notifying listeners for every field whose value changed.
   */
  undo(): boolean {
    if (this.histIndex <= 0) {
      return false;
    }
    const before: EditorState = this.snapshots[this.histIndex];
    this.histIndex = this.histIndex - 1;
    const after: EditorState = this.snapshots[this.histIndex];
    this.notifyChange(before, after);
    return true;
  }

  /**
   * Re-applies the step the last undo took back.
   */
  redo(): boolean {
    if (this.histIndex >= this.snapshots.length - 1) {
      return false;
    }
    const before: EditorState = this.snapshots[this.histIndex];
    this.histIndex = this.histIndex + 1;
    const after: EditorState = this.snapshots[this.histIndex];
    this.notifyChange(before, after);
    return true;
  }

  get canUndo(): boolean {
    return this.histIndex > 0;
  }

  get canRedo(): boolean {
    return this.histIndex < this.snapshots.length - 1;
  }

  /**
   * Registers a listener for 'text', 'cursor' or 'bold'. Returns a function
   * that removes exactly that registration; calling it again does nothing.
   */
  watch(field: string, listener: EditorListener): () => void {
    const entry: ListenerEntry = new ListenerEntry(listener);
    const list: ListenerEntry[] | undefined = this.listenersFor(field);
    if (list !== undefined) {
      list.push(entry);
    }
    return () => {
      if (list === undefined) {
        return;
      }
      const index: number = list.indexOf(entry);
      if (index >= 0) {
        list.splice(index, 1);
      }
    };
  }

  private listenersFor(field: string): ListenerEntry[] | undefined {
    if (field === 'text') {
      return this.textListeners;
    }
    if (field === 'cursor') {
      return this.cursorListeners;
    }
    if (field === 'bold') {
      return this.boldListeners;
    }
    return undefined;
  }

  /**
   * Commits one step unless the values are identical to the current ones.
   */
  private applyValues(nextText: string, nextCursor: number, nextBold: boolean): boolean {
    const current: EditorState = this.snapshots[this.histIndex];
    if (nextText === current.text && nextCursor === current.cursor && nextBold === current.bold) {
      return false;
    }
    const next: EditorState = { text: nextText, cursor: nextCursor, bold: nextBold };
    this.commit(next);
    return true;
  }

  /**
   * Drops the redo branch, records the new state (forgetting the oldest step
   * when the limit is exceeded) and then notifies listeners, so they observe
   * the store already in its new state.
   */
  private commit(next: EditorState): void {
    const before: EditorState = this.snapshots[this.histIndex];
    this.snapshots.splice(this.histIndex + 1, this.snapshots.length - this.histIndex - 1);
    this.snapshots.push(next);
    this.histIndex = this.histIndex + 1;
    while (this.snapshots.length > this.historyLimit + 1) {
      this.snapshots.shift();
      this.histIndex = this.histIndex - 1;
    }
    this.notifyChange(before, next);
  }

  private notifyChange(before: EditorState, after: EditorState): void {
    if (after.text !== before.text) {
      this.fireListeners(this.textListeners, after.text, before.text);
    }
    if (after.cursor !== before.cursor) {
      this.fireListeners(this.cursorListeners, after.cursor, before.cursor);
    }
    if (after.bold !== before.bold) {
      this.fireListeners(this.boldListeners, after.bold, before.bold);
    }
  }

  private fireListeners(list: ListenerEntry[], value: string | number | boolean,
    previous: string | number | boolean): void {
    // Iterate a snapshot so listeners may subscribe or unsubscribe safely.
    const copy: ListenerEntry[] = list.slice();
    for (const entry of copy) {
      entry.listener(value, previous);
    }
  }
}

export class LruCache<K, V> {
  private map: Map<K, V> = new Map<K, V>();
  private cap: number;

  constructor(capacity: number) {
    if (!Number.isInteger(capacity) || capacity < 1) {
      throw new Error('capacity must be a whole number of at least 1');
    }
    this.cap = capacity;
  }

  get size(): number {
    return this.map.size;
  }

  set(key: K, value: V): void {
    if (this.map.has(key)) {
      this.map.delete(key);
    }
    this.map.set(key, value);
    if (this.map.size > this.cap) {
      const iterator: IterableIterator<K> = this.map.keys();
      const oldest: K = iterator.next().value as K;
      this.map.delete(oldest);
    }
  }

  get(key: K): V | undefined {
    if (!this.map.has(key)) {
      return undefined;
    }
    const value: V = this.map.get(key) as V;
    this.map.delete(key);
    this.map.set(key, value);
    return value;
  }

  has(key: K): boolean {
    return this.map.has(key);
  }

  keys(): K[] {
    const result: K[] = [];
    const iterator: IterableIterator<K> = this.map.keys();
    let step: IteratorResult<K> = iterator.next();
    while (!step.done) {
      result.push(step.value as K);
      step = iterator.next();
    }
    return result;
  }
}

