// Log viewer page: a lazy-loaded list of log entries with pull-to-refresh.
// Stage model, ArkTS (HarmonyOS NEXT, API 12+). No network or file access.

// One log entry. Level is "error" for multiples of 50, "warning" for
// multiples of 10, "info" otherwise.
class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number, message: string, level: string) {
    this.id = id;
    this.message = message;
    this.level = level;
  }
}

function levelForId(id: number): string {
  if (id % 50 === 0) {
    return 'error';
  }
  if (id % 10 === 0) {
    return 'warning';
  }
  return 'info';
}

function makeEntry(id: number): LogEntry {
  return new LogEntry(id, `Event ${id}`, levelForId(id));
}

// Data source for LazyForEach. Entries are kept with the highest id at
// index 0, so the list renders highest id first.
class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  public totalCount(): number {
    return this.entries.length;
  }

  public getData(index: number): LogEntry {
    return this.entries[index];
  }

  public registerDataListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  public unregisterDataListener(listener: DataChangeListener): void {
    const pos: number = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  public replaceAll(entries: LogEntry[]): void {
    this.entries = entries;
    this.notifyDataReloaded();
  }

  // Puts the new entries on top of the list, one at a time, notifying the
  // LazyForEach after each insertion so it stays in sync incrementally.
  public prepend(newEntries: LogEntry[]): void {
    for (let i = 0; i < newEntries.length; i++) {
      this.entries.unshift(newEntries[i]);
      this.notifyDataAdd(0);
    }
  }

  private notifyDataReloaded(): void {
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataReloaded();
    });
  }

  private notifyDataAdd(index: number): void {
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataAdd(index);
    });
  }
}

