@Entry
@Component
struct LogPage {
  @State isRefreshing: boolean = false;
  @State entryCount: number = 0;
  private dataSource: LogDataSource = new LogDataSource();
  private nextId: number = 3001;

  aboutToAppear(): void {
    // Create the 3000 initial entries once, highest id first.
    const initial: LogEntry[] = [];
    for (let n = 3000; n >= 1; n--) {
      initial.push(makeEntry(n));
    }
    this.dataSource.replaceAll(initial);
    this.entryCount = this.dataSource.totalCount();
  }

  private addFiveNewEntries(): void {
    const fresh: LogEntry[] = [];
    for (let i = 0; i < 5; i++) {
      fresh.push(makeEntry(this.nextId));
      this.nextId = this.nextId + 1;
    }
    this.dataSource.prepend(fresh);
    this.entryCount = this.dataSource.totalCount();
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .width('100%')
        .textAlign(TextAlign.Start)
        .padding({ left: 16, right: 16, top: 16, bottom: 8 })

      Refresh({ refreshing: $$this.isRefreshing }) {
        List() {
          // Rows are created on demand while scrolling; never all up front.
          LazyForEach(this.dataSource, (entry: LogEntry) => {
            ListItem() {
              LogRow({ entry: entry })
            }
          }, (entry: LogEntry) => entry.id.toString())
        }
        .width('100%')
        .height('100%')
        .edgeEffect(EdgeEffect.Spring)
        .scrollBar(BarState.Auto)
        .cachedCount(5)
        .divider({ strokeWidth: 1, color: '#EEEEEE', startMargin: 16, endMargin: 16 })
      }
      .layoutWeight(1)
      .onRefreshing(() => {
        // The standard indicator is visible; after one second add the next
        // five ids on top of the list, then hide the indicator.
        setTimeout(() => {
          this.addFiveNewEntries();
          this.isRefreshing = false;
        }, 1000);
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

