// Log entry data model.
class LogEntry {
  public id: number;
  public message: string;
  public level: string; // "info" | "warning" | "error"

  constructor(id: number, message: string, level: string) {
    this.id = id;
    this.message = message;
    this.level = level;
  }
}

const INITIAL_COUNT: number = 3000;
const REFRESH_BATCH: number = 5;
const REFRESH_DELAY_MS: number = 1000;

// Level rule: "error" on every 50th id, "warning" on every 10th, "info" otherwise.
function levelForId(id: number): string {
  if (id % 50 === 0) {
    return 'error';
  }
  if (id % 10 === 0) {
    return 'warning';
  }
  return 'info';
}

function makeEntry(id: number): LogEntry {
  return new LogEntry(id, `Event ${id}`, levelForId(id));
}

// Initial data, generated highest id first so the list starts with id 3000.
function createInitialEntries(): LogEntry[] {
  const entries: LogEntry[] = [];
  for (let id = INITIAL_COUNT; id >= 1; id--) {
    entries.push(makeEntry(id));
  }
  return entries;
}

// Data source consumed by LazyForEach: the list asks this object for rows
// on demand while scrolling, so only the rows that scroll into view are built.
class LogDataSource implements IDataSource {
  private entries: LogEntry[];
  private listeners: DataChangeListener[];

  constructor(entries: LogEntry[]) {
    this.entries = entries;
    this.listeners = [];
  }

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos: number = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  // New entries carry the highest ids, so they belong at the top of the list.
  // Each insertion is announced to the list so only the affected row slot
  // is (re)built.
  prepend(newEntries: LogEntry[]): void {
    for (let i = 0; i < newEntries.length; i++) {
      this.entries.unshift(newEntries[i]);
      this.listeners.forEach((listener: DataChangeListener) => {
        listener.onDataAdd(0);
      });
    }
  }
}

