  @State isRefreshing: boolean = false;
  @State entryCount: number = INITIAL_COUNT;
  private data: LogDataSource = new LogDataSource(createInitialEntries());
  private nextId: number = INITIAL_COUNT + 1;

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .width('100%')
        .padding({ left: 16, right: 16, top: 16, bottom: 8 })

      Refresh({ refreshing: $$this.isRefreshing }) {
        List({ space: 4 }) {
          LazyForEach(this.data, (entry: LogEntry) => {
            ListItem() {
              LogRow({ entry: entry })
            }
          }, (entry: LogEntry) => entry.id.toString())
        }
        .width('100%')
        .height('100%')
        .edgeEffect(EdgeEffect.Spring)
        .scrollBar(BarState.Auto)
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        setTimeout(() => {
          const newEntries: LogEntry[] = [];
          for (let i = 0; i < REFRESH_BATCH; i++) {
            newEntries.push(makeEntry(this.nextId));
            this.nextId++;
          }
          this.data.prepend(newEntries);
          this.entryCount = this.data.totalCount();
          this.isRefreshing = false;
        }, REFRESH_DELAY_MS);
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#F5F5F5')
  }
}

export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

export class BuildPlan {
  private tasks: string[];
  private deps: Map<string, string[]>;

  constructor(spec: Record<string, string[]>) {
    this.tasks = Object.keys(spec);
    this.deps = new Map<string, string[]>();
    for (const task of this.tasks) {
      const source: string[] = spec[task];
      const copy: string[] = [];
      for (const dep of source) {
        copy.push(dep);
      }
      this.deps.set(task, copy);
    }

    // First check: every dependency must be a known task.
    for (const task of this.tasks) {
      const list = this.deps.get(task);
      if (list === undefined) {
        continue;
      }
      for (const dep of list) {
        if (!this.deps.has(dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }

    // Second check: place every task; this detects dependency cycles.
    this.computeOrder();
  }

  private computeOrder(): string[] {
    const result: string[] = [];
    const placed = new Set<string>();
    const chain: string[] = [];
    const onChain = new Set<string>();

    const place = (task: string): void => {
      if (placed.has(task)) {
        return;
      }
      if (onChain.has(task)) {
        const start = chain.indexOf(task);
        const path: string[] = [];
        for (let i = start; i < chain.length; i++) {
          path.push(chain[i]);
        }
        path.push(task);
        throw new CycleError(path);
      }
      chain.push(task);
      onChain.add(task);
      const list = this.deps.get(task);
      if (list !== undefined) {
        for (const dep of list) {
          place(dep);
        }
      }
      onChain.delete(task);
      chain.pop();
      placed.add(task);
      result.push(task);
    };

    for (const task of this.tasks) {
      place(task);
    }
    return result;
  }

  order(): string[] {
    return this.computeOrder();
  }

  layers(): string[][] {
    const layerOf = new Map<string, number>();
    const layers: string[][] = [];
    for (const task of this.tasks) {
      const layer = this.computeLayer(task, layerOf);
      while (layers.length <= layer) {
        layers.push([]);
      }
      layers[layer].push(task);
    }
    return layers;
  }

  private computeLayer(task: string, layerOf: Map<string, number>): number {
    const known = layerOf.get(task);
    if (known !== undefined) {
      return known;
    }
    let layer = 0;
    const list = this.deps.get(task);
    if (list !== undefined) {
      for (const dep of list) {
        const depLayer = this.computeLayer(dep, layerOf);
        if (depLayer >= layer) {
          layer = depLayer + 1;
        }
      }
    }
    layerOf.set(task, layer);
    return layer;
  }

  dependentsOf(name: string): string[] {
    const dependents = new Set<string>();
    const result: string[] = [];
    for (const task of this.order()) {
      let isDependent = false;
      const list = this.deps.get(task);
      if (list !== undefined) {
        for (const dep of list) {
          if (dep === name || dependents.has(dep)) {
            isDependent = true;
            break;
          }
        }
      }
      if (isDependent) {
        dependents.add(task);
        result.push(task);
      }
    }
    return result;
  }
}

// solution.ets
// A small text-editor state store with patch application, undo/redo
// (with a bounded history) and per-field listeners. Self-contained.

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

interface WatchEntry {
  field: string;
  listener: (value: string | number | boolean, previous: string | number | boolean) => void;
}

export class EditorStore {
  private current: EditorState;
  private limit: number;
  private undoStack: EditorState[];
  private redoStack: EditorState[];
  private watchers: WatchEntry[];

  constructor(initial: EditorState, historyLimit: number) {
    // Take a full copy so later changes to the passed-in object have no effect.
    const start: EditorState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.current = start;
    this.limit = historyLimit;
    this.undoStack = [];
    this.redoStack = [];
    this.watchers = [];
  }

  // A fresh object on every read; mutating it never touches the store.
  get state(): EditorState {
    return this.copyState(this.current);
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const before: EditorState = this.copyState(this.current);
    let nextText: string = before.text;
    let nextCursor: number = before.cursor;
    let nextBold: boolean = before.bold;

    const patchText: string | undefined = patch.text;
    if (patchText !== undefined) {
      nextText = patchText;
    }
    const patchCursor: number | undefined = patch.cursor;
    if (patchCursor !== undefined) {
      nextCursor = patchCursor;
    }
    const patchBold: boolean | undefined = patch.bold;
    if (patchBold !== undefined) {
      nextBold = patchBold;
    }

    // No field ends up with a different value: nothing happens at all.
    if (nextText === before.text && nextCursor === before.cursor && nextBold === before.bold) {
      return false;
    }

    const next: EditorState = {
      text: nextText,
      cursor: nextCursor,
      bold: nextBold
    };
    this.commit(next, before);
    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    // The draft is a copy; mutating it does not touch the store until run returns.
    const draft: EditorState = this.copyState(this.current);
    run(draft);
    // If run threw, we never get here: the store is unchanged and the error
    // propagates to the caller. Otherwise the draft is applied as one step.
    return this.apply(draft);
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }
    const before: EditorState = this.copyState(this.current);
    const restored: EditorState = this.undoStack[this.undoStack.length - 1];
    this.undoStack.splice(this.undoStack.length - 1, 1);
    this.redoStack.push(before);
    this.current = restored;
    this.notifyListeners(before, restored);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }
    const before: EditorState = this.copyState(this.current);
    const next: EditorState = this.redoStack[this.redoStack.length - 1];
    this.redoStack.splice(this.redoStack.length - 1, 1);
    this.pushUndo(before);
    this.current = next;
    this.notifyListeners(before, next);
    return true;
  }

  watch(field: string,
    listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    const entry: WatchEntry = {
      field: field,
      listener: listener
    };
    this.watchers.push(entry);
    return (): void => {
      const index: number = this.watchers.indexOf(entry);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
      // Calling the returned function again finds nothing and does nothing.
    };
  }

  private copyState(source: EditorState): EditorState {
    const copy: EditorState = {
      text: source.text,
      cursor: source.cursor,
      bold: source.bold
    };
    return copy;
  }

  private pushUndo(snapshot: EditorState): void {
    this.undoStack.push(snapshot);
    // Keep at most historyLimit steps to undo; forget the oldest ones.
    while (this.undoStack.length > this.limit) {
      this.undoStack.splice(0, 1);
    }
  }

  // One committed step: the state before it becomes undoable, everything
  // redoable is forgotten, the store takes the new state, then listeners run.
  private commit(next: EditorState, before: EditorState): void {
    this.pushUndo(before);
    this.redoStack.splice(0, this.redoStack.length);
    this.current = next;
    this.notifyListeners(before, next);
  }

  private notifyListeners(before: EditorState, after: EditorState): void {
    if (before.text !== after.text) {
      this.emit('text', after.text, before.text);
    }
    if (before.cursor !== after.cursor) {
      this.emit('cursor', after.cursor, before.cursor);
    }
    if (before.bold !== after.bold) {
      this.emit('bold', after.bold, before.bold);
    }
  }

  private emit(field: string, value: string | number | boolean, previous: string | number | boolean): void {
    // Iterate over a snapshot so listeners may safely subscribe/unsubscribe.
    const snapshot: WatchEntry[] = this.watchers.slice();
    for (const entry of snapshot) {
      if (entry.field === field) {
        entry.listener(value, previous);
      }
    }
  }
}

// solution.ets — Water tracker entry page with a goal-changing modal dialog.
// Stage model, ArkTS (HarmonyOS NEXT, API 12+).

import { preferences } from '@kit.ArkData';

// Names/keys used to keep the tracker state on the device.
const PREFERENCES_NAME: string = 'water_tracker_store';
const KEY_COUNT: string = 'glasses_drunk';
const KEY_GOAL: string = 'daily_goal';

// Values shown on the very first run.
const DEFAULT_COUNT: number = 0;
const DEFAULT_GOAL: number = 8;

// A quick choice of the goal dialog: pressing it fills the field.
class GoalPreset {
  label: string;
  glasses: number;

  constructor(label: string, glasses: number) {
    this.label = label;
    this.glasses = glasses;
  }
}

// The three quick choices held by this file.
const GOAL_PRESETS: GoalPreset[] = [
  new GoalPreset('Light', 6),
  new GoalPreset('Standard', 8),
  new GoalPreset('Active', 12)
];

// Returns the field content as a whole number of 1 or more,
// or null when the field does not hold such a number.
function parseGoalInput(text: string): number | null {
  const trimmed: string = text.trim();
  if (trimmed.length === 0) {
    return null;
  }
  const value: number = Number(trimmed);
  if (Number.isNaN(value) || !Number.isInteger(value) || value < 1) {
    return null;
  }
  return value;
}

// Modal dialog for changing the daily goal. It never touches the goal
// itself: on Save it only reports the typed number back through the
// callback that the page handed over.
@CustomDialog
struct GoalDialog {
  controller?: CustomDialogController;
  onSave?: (glasses: number) => void;
  @State inputText: string = '';
  private presets: GoalPreset[] = GOAL_PRESETS;

  aboutToAppear(): void {
    // The field is empty whenever the dialog is shown.
    this.inputText = '';
  }

  aboutToDisappear(): void {
    // Also clear on close, so the next opening shows an empty field.
    this.inputText = '';
  }

  build() {
    Column({ space: 16 }) {
      Text('Daily goal')
        .fontSize(20)
        .fontWeight(FontWeight.Bold)

      TextInput({
        placeholder: 'Glasses per day',
        text: this.inputText
      })
        .type(InputType.Number)
        .width('100%')
        .onChange((value: string) => {
          this.inputText = value;
        })

      Row({ space: 12 }) {
        ForEach(this.presets, (preset: GoalPreset) => {
          Button(preset.label)
            .layoutWeight(1)
            .onClick(() => {
              this.inputText = preset.glasses.toString();
            })
        }, (preset: GoalPreset) => preset.label)
      }
      .width('100%')

      Row({ space: 12 }) {
        Button('Cancel')
          .layoutWeight(1)
          .onClick(() => {
            this.controller?.close();
          })

        Button('Save')
          .layoutWeight(1)
          .onClick(() => {
            const value: number | null = parseGoalInput(this.inputText);
            if (value === null) {
              // Not a whole number of 1 or more: Save does nothing.
              return;
            }
            this.controller?.close();
            if (this.onSave !== undefined) {
              this.onSave(value);
            }
          })
      }
      .width('100%')
    }
    .padding(24)
    .width(320)
  }
}

// Entry page: water tracker with the glasses drunk and the daily goal.
@Entry
@Component
struct WaterTracker {
  @State count: number = DEFAULT_COUNT;
  @State goal: number = DEFAULT_GOAL;
  private store: preferences.Preferences | null = null;

  dialogController: CustomDialogController = new CustomDialogController({
    builder: GoalDialog({
      onSave: (glasses: number) => {
        this.applyGoal(glasses);
      }
    }),
    autoCancel: true,
    alignment: DialogAlignment.Center
  });

  aboutToAppear(): void {
    // Load what the page showed last time; on the first run this yields
    // the defaults 0 and 8.
    const store: preferences.Preferences =
      preferences.getPreferencesSync(getContext(this), { name: PREFERENCES_NAME });
    this.store = store;
    const storedCount: number = Number(store.getSync(KEY_COUNT, DEFAULT_COUNT));
    const storedGoal: number = Number(store.getSync(KEY_GOAL, DEFAULT_GOAL));
    this.count = (Number.isInteger(storedCount) && storedCount >= 0) ? storedCount : DEFAULT_COUNT;
    this.goal = (Number.isInteger(storedGoal) && storedGoal >= 1) ? storedGoal : DEFAULT_GOAL;
  }

  private addGlass(): void {
    this.count += 1;
    this.persist();
  }

  // Called by the dialog through the callback the page handed over.
  private applyGoal(glasses: number): void {
    const nextGoal: number = Math.floor(glasses);
    this.goal = nextGoal >= 1 ? nextGoal : DEFAULT_GOAL;
    this.persist();
  }

  private persist(): void {
    const store = this.store;
    if (store === null) {
      return;
    }
    store.putSync(KEY_COUNT, this.count);
    store.putSync(KEY_GOAL, this.goal);
    store.flushSync();
  }

  build() {
    Column({ space: 20 }) {
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(24)
        .fontWeight(FontWeight.Medium)

      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(16)
          .fontColor('#2E7D32')
      }

      Button('Add a glass')
        .width(220)
        .onClick(() => {
          this.addGlass();
        })

      Button('Change goal')
        .width(220)
        .onClick(() => {
          this.dialogController.open();
        })
    }
    .width('100%')
    .height('100%')
    .justifyContent(FlexAlign.Center)
  }
}

// solution.ets
//
// Reading settings demo (stage model, ArkTS).
//
// The two app-wide settings live in AppStorage, so any component on any page
// of the app can read or change them and is redrawn automatically when they
// change:
//   - 'readingTextSize': whole number in [14, 30], starts at 18
//   - 'readingBold'    : on/off flag, starts at false

const MIN_TEXT_SIZE: number = 14;
const MAX_TEXT_SIZE: number = 30;
const SIZE_STEP: number = 2;
const DEFAULT_TEXT_SIZE: number = 18;

// Seed the app-wide settings up front so they exist for every page/component.
AppStorage.setOrCreate<number>('readingTextSize', DEFAULT_TEXT_SIZE);
AppStorage.setOrCreate<boolean>('readingBold', false);

// Data describing one size preset button.
class SizePreset {
  label: string;
  size: number;

  constructor(label: string, size: number) {
    this.label = label;
    this.size = size;
  }
}

// The three presets held by this file.
const SIZE_PRESETS: Array<SizePreset> = [
  new SizePreset('Small', MIN_TEXT_SIZE),
  new SizePreset('Medium', DEFAULT_TEXT_SIZE),
  new SizePreset('Large', 24)
];

// First extra component: the size controls (A- / size / A+ and the presets).
// It changes the app-wide text size by itself; the page passes nothing in.
@Component
struct SizeControls {
  @StorageLink('readingTextSize') textSize: number = DEFAULT_TEXT_SIZE;

  private clampSize(value: number): number {
    if (value < MIN_TEXT_SIZE) {
      return MIN_TEXT_SIZE;
    }
    if (value > MAX_TEXT_SIZE) {
      return MAX_TEXT_SIZE;
    }
    return value;
  }

  private changeBy(delta: number): void {
    const next: number = this.clampSize(this.textSize + delta);
    // Only write when the value really changes.
    if (next !== this.textSize) {
      this.textSize = next;
    }
  }

  private applyPreset(preset: SizePreset): void {
    if (preset.size !== this.textSize) {
      this.textSize = preset.size;
    }
  }

  build() {
    Column({ space: 12 }) {
      Row({ space: 12 }) {
        Button('A-')
          .onClick(() => {
            this.changeBy(-SIZE_STEP);
          })
        Text(`${this.textSize}`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
        Button('A+')
          .onClick(() => {
            this.changeBy(SIZE_STEP);
          })
      }
      .alignItems(VerticalAlign.Center)

      Row({ space: 8 }) {
        ForEach(SIZE_PRESETS, (preset: SizePreset) => {
          Button(preset.label)
            .onClick(() => {
              this.applyPreset(preset);
            })
        }, (preset: SizePreset) => preset.label)
      }
      .alignItems(VerticalAlign.Center)
    }
    .alignItems(HorizontalAlign.Start)
  }
}

// Second extra component: the preview sentence. It only reads the settings.
@Component
struct TextPreview {
  @StorageProp('readingTextSize') textSize: number = DEFAULT_TEXT_SIZE;
  @StorageProp('readingBold') bold: boolean = false;

  build() {
    Text('The quick brown fox')
      .fontSize(this.textSize)
      // The sentence grows/shrinks smoothly over 300 ms when the size changes.
      .animation({ duration: 300, curve: Curve.EaseInOut })
      .fontWeight(this.bold ? FontWeight.Bold : FontWeight.Normal)
  }
}

// Third extra component: counts how often the text size actually changes.
// It has no buttons and never changes a setting; the count is its own.
@Component
struct ChangeCounter {
  @StorageProp('readingTextSize') @Watch('onTextSizeChanged') textSize: number = DEFAULT_TEXT_SIZE;
  @State count: number = 0;
  private lastSeenSize: number = DEFAULT_TEXT_SIZE;

  aboutToAppear(): void {
    this.lastSeenSize = this.textSize;
  }

  onTextSizeChanged(): void {
    // Count only real changes to the text size (bold changes are not watched).
    if (this.textSize !== this.lastSeenSize) {
      this.lastSeenSize = this.textSize;
      this.count = this.count + 1;
    }
  }

  build() {
    Text(`Changed ${this.count} times`)
      .fontSize(16)
  }
}

// Entry page: the "Bold" switch row, then the three components.
@Entry
@Component
struct Index {
  @StorageLink('readingBold') bold: boolean = false;

  build() {
    Column({ space: 20 }) {
      Row({ space: 12 }) {
        Text('Bold')
          .fontSize(18)
        Toggle({ type: ToggleType.Switch, isOn: this.bold })
          .onChange((isOn: boolean) => {
            this.bold = isOn;
          })
      }
      .alignItems(VerticalAlign.Center)

      SizeControls()
      TextPreview()
      ChangeCounter()
    }
    .width('100%')
    .height('100%')
    .padding(16)
    .alignItems(HorizontalAlign.Start)
    .justifyContent(FlexAlign.Start)
  }
}

export interface User {
  id: number;
  name: string;
  email: string;
}

export function parseUsers(json: string): User[] {
  const result: User[] = [];

  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(json) as Object | null;
  } catch (err) {
    return result;
  }

  if (parsed === null || !Array.isArray(parsed)) {
    return result;
  }

  const arr = parsed as Array<Object | null>;
  for (const item of arr) {
    if (item === null || typeof item !== 'object') {
      continue;
    }
    if (Array.isArray(item)) {
      continue;
    }

    const obj = item as Record<string, Object | null>;

    const idVal = obj['id'];
    if (typeof idVal !== 'number') {
      continue;
    }
    if (!Number.isFinite(idVal) || Math.floor(idVal) !== idVal) {
      continue;
    }

    const nameVal = obj['name'];
    if (typeof nameVal !== 'string') {
      continue;
    }
    if (nameVal.length === 0) {
      continue;
    }

    const emailVal = obj['email'];
    if (typeof emailVal !== 'string') {
      continue;
    }
    if (!emailVal.includes('@')) {
      continue;
    }

    const user: User = {
      id: idVal,
      name: nameVal,
      email: emailVal
    };
    result.push(user);
  }

  return result;
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStart(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNameChar(c: string): boolean {
  return isNameStart(c) || isDigit(c);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;
  while (i < source.length) {
    const c = source[i];
    if (c === ' ') {
      i++;
      continue;
    }
    if (isDigit(c)) {
      const start = i;
      while (i < source.length && isDigit(source[i])) {
        i++;
      }
      if (i + 1 < source.length && source[i] === '.' && isDigit(source[i + 1])) {
        i++;
        while (i < source.length && isDigit(source[i])) {
          i++;
        }
      }
      tokens.push({ kind: 'number', text: source.substring(start, i), position: start });
      continue;
    }
    if (isNameStart(c)) {
      const start = i;
      while (i < source.length && isNameChar(source[i])) {
        i++;
      }
      tokens.push({ kind: 'name', text: source.substring(start, i), position: start });
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      tokens.push({ kind: 'operator', text: c, position: i });
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push({ kind: 'paren', text: c, position: i });
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class Node {
  kind: string;
  value: number = 0;
  name: string = '';
  op: string = '';
  position: number;
  left: Node | null = null;
  right: Node | null = null;

  constructor(kind: string, position: number) {
    this.kind = kind;
    this.position = position;
  }
}

class Parser {
  private tokens: Token[];
  private source: string;
  private pos: number = 0;

  constructor(tokens: Token[], source: string) {
    this.tokens = tokens;
    this.source = source;
  }

  private endError(): ExpressionError {
    return new ExpressionError('Unexpected end of expression', this.source.length);
  }

  peek(): Token | null {
    if (this.pos < this.tokens.length) {
      return this.tokens[this.pos];
    }
    return null;
  }

  private isOperator(t: Token, op: string): boolean {
    return t.kind === 'operator' && t.text === op;
  }

  parseExpression(): Node {
    let node = this.parseTerm();
    while (true) {
      const t = this.peek();
      if (t === null) {
        break;
      }
      if (t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.pos++;
        const right = this.parseTerm();
        const bin = new Node('binary', t.position);
        bin.op = t.text;
        bin.left = node;
        bin.right = right;
        node = bin;
      } else {
        break;
      }
    }
    return node;
  }

  private parseTerm(): Node {
    let node = this.parseUnary();
    while (true) {
      const t = this.peek();
      if (t === null) {
        break;
      }
      if (t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.pos++;
        const right = this.parseUnary();
        const bin = new Node('binary', t.position);
        bin.op = t.text;
        bin.left = node;
        bin.right = right;
        node = bin;
      } else {
        break;
      }
    }
    return node;
  }

  private parseUnary(): Node {
    const t = this.peek();
    if (t !== null && this.isOperator(t, '-')) {
      this.pos++;
      const child = this.parseUnary();
      const node = new Node('unary', t.position);
      node.left = child;
      return node;
    }
    return this.parsePrimary();
  }

  private parsePrimary(): Node {
    const t = this.peek();
    if (t === null) {
      throw this.endError();
    }
    if (t.kind === 'number') {
      this.pos++;
      const node = new Node('num', t.position);
      node.value = parseFloat(t.text);
      return node;
    }
    if (t.kind === 'name') {
      this.pos++;
      const node = new Node('name', t.position);
      node.name = t.text;
      return node;
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.pos++;
      const inner = this.parseExpression();
      const close = this.peek();
      if (close === null) {
        throw this.endError();
      }
      if (!(close.kind === 'paren' && close.text === ')')) {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.pos++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function hasVariable(variables: Record<string, number>, name: string): boolean {
  return Object.keys(variables).indexOf(name) >= 0;
}

function evalNode(node: Node, variables: Record<string, number>): number {
  if (node.kind === 'num') {
    return node.value;
  }
  if (node.kind === 'name') {
    if (!hasVariable(variables, node.name)) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return variables[node.name];
  }
  if (node.kind === 'unary') {
    return -evalNode(node.left as Node, variables);
  }
  const left = evalNode(node.left as Node, variables);
  const right = evalNode(node.right as Node, variables);
  if (node.op === '+') {
    return left + right;
  }
  if (node.op === '-') {
    return left - right;
  }
  if (node.op === '*') {
    return left * right;
  }
  if (node.op === '/') {
    if (right === 0) {
      throw new ExpressionError('Division by zero', node.position);
    }
    return left / right;
  }
  if (right === 0) {
    throw new ExpressionError('Division by zero', node.position);
  }
  return left % right;
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source);
  const ast = parser.parseExpression();
  const trailing = parser.peek();
  if (trailing !== null) {
    throw new ExpressionError(`Unexpected token '${trailing.text}'`, trailing.position);
  }
  return evalNode(ast, variables);
}

/**
 * Internal doubly linked list node used by LruCache to keep track of usage order.
 */
class LruNode<K, V> {
  key: K;
  value: V;
  prev: LruNode<K, V> | null = null;
  next: LruNode<K, V> | null = null;

  constructor(key: K, value: V) {
    this.key = key;
    this.value = value;
  }
}

/**
 * A least-recently-used (LRU) cache that holds at most `capacity` keys and,
 * when full, drops the key that was used least recently.
 *
 * Keys may be of any type. Key identity follows Map semantics: the number 1
 * and the string '1' are different keys, and two objects are the same key
 * only when they are the same object.
 */
export class LruCache<K, V> {
  private readonly capacity: number;
  private readonly nodes: Map<K, LruNode<K, V>> = new Map<K, LruNode<K, V>>();
  // Head of the list is the least recently used entry;
  // tail of the list is the most recently used entry.
  private head: LruNode<K, V> | null = null;
  private tail: LruNode<K, V> | null = null;

  constructor(capacity: number) {
    this.capacity = capacity;
  }

  /** How many keys are stored. */
  get size(): number {
    return this.nodes.size;
  }

  /**
   * Stores the value and makes `key` the most recently used key.
   * Setting a key that is already stored replaces its value. If the cache
   * then holds more than `capacity` keys, the least recently used key is
   * removed.
   */
  set(key: K, value: V): void {
    const existing: LruNode<K, V> | undefined = this.nodes.get(key);
    if (existing !== undefined) {
      existing.value = value;
      this.moveToTail(existing);
      return;
    }
    const node: LruNode<K, V> = new LruNode<K, V>(key, value);
    this.nodes.set(key, node);
    this.appendToTail(node);
    while (this.nodes.size > this.capacity) {
      const lru: LruNode<K, V> | null = this.head;
      if (lru === null) {
        break;
      }
      this.unlink(lru);
      this.nodes.delete(lru.key);
    }
  }

  /**
   * Returns the stored value and makes `key` the most recently used key.
   * Returns undefined for a key that is not stored.
   */
  get(key: K): V | undefined {
    const node: LruNode<K, V> | undefined = this.nodes.get(key);
    if (node === undefined) {
      return undefined;
    }
    this.moveToTail(node);
    return node.value;
  }

  /** Says whether the key is stored. Does not count as a use. */
  has(key: K): boolean {
    return this.nodes.has(key);
  }

  /**
   * Returns the stored keys as a new array, from the least recently used to
   * the most recently used. Does not count as a use.
   */
  keys(): K[] {
    const result: K[] = [];
    let node: LruNode<K, V> | null = this.head;
    while (node !== null) {
      result.push(node.key);
      node = node.next;
    }
    return result;
  }

  private appendToTail(node: LruNode<K, V>): void {
    node.prev = this.tail;
    node.next = null;
    if (this.tail === null) {
      this.head = node;
    } else {
      this.tail.next = node;
    }
    this.tail = node;
  }

  private unlink(node: LruNode<K, V>): void {
    const prev: LruNode<K, V> | null = node.prev;
    const next: LruNode<K, V> | null = node.next;
    if (prev === null) {
      this.head = next;
    } else {
      prev.next = next;
    }
    if (next === null) {
      this.tail = prev;
    } else {
      next.prev = prev;
    }
    node.prev = null;
    node.next = null;
  }

  private moveToTail(node: LruNode<K, V>): void {
    if (this.tail === node) {
      return;
    }
    this.unlink(node);
    this.appendToTail(node);
  }
}

/**
 * The result of one job as reported by JobQueue.runAll.
 */
export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

/**
 * One waiting job. The job function and the callbacks of the promise that
 * add() returned are kept in closures, so entries for jobs with different
 * result types can share one queue.
 */
class QueueEntry {
  public readonly start: () => void;
  public readonly cancel: () => void;

  constructor(start: () => void, cancel: () => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

/**
 * A queue that runs asynchronous jobs and never lets more than a fixed
 * number of them (the concurrency) run at the same time.
 */
export class JobQueue {
  private readonly concurrency: number;
  private paused: boolean = false;
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private waitingJobs: Array<QueueEntry> = [];
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    if (concurrency < 1 || Math.floor(concurrency) !== concurrency) {
      throw new Error('concurrency must be a whole number of 1 or more');
    }
    this.concurrency = concurrency;
  }

  /** Jobs that are running right now. */
  get running(): number {
    return this.runningCount;
  }

  /** Jobs that are waiting right now. */
  get waiting(): number {
    return this.waitingJobs.length;
  }

  /** Jobs whose promise has fulfilled so far. */
  get completed(): number {
    return this.completedCount;
  }

  /** Jobs whose promise has rejected so far. */
  get failed(): number {
    return this.failedCount;
  }

  /**
   * Puts the job at the end of the queue. The returned promise fulfils with
   * the value of the job or rejects with the error of the job (the same
   * object). While the queue is not paused and fewer jobs than the
   * concurrency are running, the job is called before add() returns.
   */
  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const entry: QueueEntry = new QueueEntry(
        (): void => {
          this.runningCount++;
          job().then((value: T): void => {
            this.runningCount--;
            this.completedCount++;
            resolve(value);
            this.afterJobSettled();
          }, (reason: Error): void => {
            this.runningCount--;
            this.failedCount++;
            reject(reason);
            this.afterJobSettled();
          });
        },
        (): void => {
          reject(new Error('Job was cancelled'));
        }
      );
      this.waitingJobs.push(entry);
      this.pump();
    });
  }

  /**
   * From now on no waiting job is started. Jobs that are running go on.
   */
  pause(): void {
    this.paused = true;
  }

  /**
   * Ends the pause and, before it returns, starts as many waiting jobs as
   * the limit allows.
   */
  resume(): void {
    this.paused = false;
    this.pump();
  }

  /**
   * Removes every waiting job and returns how many were removed. The
   * promise that add() returned for each of them rejects with a new Error
   * whose message is 'Job was cancelled'. Removed jobs are never called and
   * count neither as completed nor as failed. Running jobs are not affected.
   */
  clear(): number {
    const removed: number = this.waitingJobs.length;
    if (removed > 0) {
      const entries: Array<QueueEntry> = this.waitingJobs;
      this.waitingJobs = [];
      for (const entry of entries) {
        entry.cancel();
      }
    }
    if (this.runningCount === 0) {
      this.fireIdleResolvers();
    }
    return removed;
  }

  /**
   * Fulfils as soon as no job is running and no job is waiting. That moment
   * can come when the last running job settles or when clear() empties the
   * queue. When the queue is already in that state, the returned promise is
   * already fulfilled.
   */
  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleResolvers.push((): void => {
        resolve();
      });
    });
  }

  /**
   * Adds every job to the queue, in the order of the given jobs, exactly as
   * add() does. Fulfils with one outcome per job, in the same order, once
   * all of them have settled. Never rejects.
   */
  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const promises: Array<Promise<T>> = [];
    for (const job of jobs) {
      promises.push(this.add<T>(job));
    }
    const outcomes: Array<Promise<JobOutcome<T>>> = [];
    for (const promise of promises) {
      outcomes.push(promise.then((value: T): JobOutcome<T> => {
        const fulfilled: JobOutcome<T> = { ok: true, value: value, error: undefined };
        return fulfilled;
      }, (reason: Error): JobOutcome<T> => {
        const rejected: JobOutcome<T> = { ok: false, value: undefined, error: reason };
        return rejected;
      }));
    }
    return Promise.all<JobOutcome<T>>(outcomes);
  }

  /**
   * Starts waiting jobs, in the order in which they were added, while the
   * queue is not paused and fewer jobs than the concurrency are running.
   */
  private pump(): void {
    while (!this.paused && this.runningCount < this.concurrency && this.waitingJobs.length > 0) {
      const entry: QueueEntry = this.waitingJobs.shift() as QueueEntry;
      entry.start();
    }
  }

  /**
   * Called when a running job has settled: starts the next waiting jobs
   * unless the queue is paused and, when the queue has become idle,
   * resolves the pending whenIdle() promises.
   */
  private afterJobSettled(): void {
    this.pump();
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      this.fireIdleResolvers();
    }
  }

  /** Resolves every pending whenIdle() promise. */
  private fireIdleResolvers(): void {
    const resolvers: Array<() => void> = this.idleResolvers;
    this.idleResolvers = [];
    for (const resolve of resolvers) {
      resolve();
    }
  }
}

/*
 * Log viewer page (stage model, ArkTS).
 *
 * - 3000 LogEntry objects are generated in memory when the page is created
 *   (ids 1..3000, highest id shown first).
 * - The list is rendered with LazyForEach, so rows are only built when they
 *   scroll into (or near) the visible area - never all 3000 up front.
 * - Pulling the list down shows the system refresh indicator; one second
 *   later the next five ids are inserted at the top of the list, the
 *   indicator hides and the header shows the new entry count.
 */

const INITIAL_COUNT: number = 3000
const REFRESH_BATCH_SIZE: number = 5
const REFRESH_DELAY_MS: number = 1000

const LEVEL_INFO: string = 'info'
const LEVEL_WARNING: string = 'warning'
const LEVEL_ERROR: string = 'error'

const COLOR_ERROR: string = '#D32F2F'
const COLOR_WARNING: string = '#F57C00'
const COLOR_INFO: string = '#757575'

/** Data for one log entry. */
class LogEntry {
  id: number
  message: string
  level: string

  constructor(id: number, message: string, level: string) {
    this.id = id
    this.message = message
    this.level = level
  }
}

function levelForId(id: number): string {
  if (id % 50 === 0) {
    return LEVEL_ERROR
  }
  if (id % 10 === 0) {
    return LEVEL_WARNING
  }
  return LEVEL_INFO
}

function makeEntry(id: number): LogEntry {
  return new LogEntry(id, `Event ${id}`, levelForId(id))
}

function colorForLevel(level: string): string {
  if (level === LEVEL_ERROR) {
    return COLOR_ERROR
  }
  if (level === LEVEL_WARNING) {
    return COLOR_WARNING
  }
  return COLOR_INFO
}

/** Initial data: ids 3000..1 so the list starts with the highest id first. */
function createInitialEntries(): LogEntry[] {
  const entries: LogEntry[] = []
  for (let id = INITIAL_COUNT; id >= 1; id--) {
    entries.push(makeEntry(id))
  }
  return entries
}

/**
 * IDataSource for LazyForEach. Keeps the entries in display order (highest
 * id first) and reports head insertions item by item, so LazyForEach only
 * touches the rows that are actually affected.
 */
class LogDataSource implements IDataSource {
  private entries: LogEntry[]
  private listeners: DataChangeListener[]

  constructor(entries: LogEntry[]) {
    this.entries = entries
    this.listeners = []
  }

  totalCount(): number {
    return this.entries.length
  }

  getData(index: number): LogEntry {
    return this.entries[index]
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener)
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const index: number = this.listeners.indexOf(listener)
    if (index >= 0) {
      this.listeners.splice(index, 1)
    }
  }

  /** Inserts new entries at the top of the list (highest id first). */
  prepend(newEntries: LogEntry[]): void {
    if (newEntries.length === 0) {
      return
    }
    for (let i = 0; i < newEntries.length; i++) {
      this.entries.unshift(newEntries[i])
    }
    for (let i = 0; i < newEntries.length; i++) {
      this.notifyDataAdd(i)
    }
  }

  private notifyDataAdd(index: number): void {
    for (let i = 0; i < this.listeners.length; i++) {
      this.listeners[i].onDataAdd(index)
    }
  }
}

/** One list row: the entry's message with its level right next to it. */
@Component
struct LogRow {
  entry: LogEntry = new LogEntry(0, '', LEVEL_INFO)

  build() {
    Row() {
      Text(this.entry.message)
        .fontSize(16)
        .fontColor('#212121')
        .maxLines(1)
        .textOverflow({ overflow: TextOverflow.Ellipsis })
        .layoutWeight(1)

      Text(this.entry.level)
        .fontSize(13)
        .fontWeight(FontWeight.Medium)
        .fontColor(colorForLevel(this.entry.level))
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 13, bottom: 13 })
    .alignItems(VerticalAlign.Center)
  }
}

@Entry
@Component
struct LogPage {
  @State isRefreshing: boolean = false
  @State entryCount: number = INITIAL_COUNT
  private dataSource: LogDataSource = new LogDataSource(createInitialEntries())
  private nextId: number = INITIAL_COUNT + 1

  aboutToAppear() {
    this.entryCount = this.dataSource.totalCount()
  }

  build() {
    Column() {
      Text(`${this.entryCount} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Medium)
        .fontColor('#212121')
        .width('100%')
        .padding({ left: 16, right: 16, top: 14, bottom: 8 })

      Refresh({ refreshing: $$this.isRefreshing }) {
        List() {
          LazyForEach(this.dataSource, (entry: LogEntry) => {
            ListItem() {
              LogRow({ entry: entry })
            }
          }, (entry: LogEntry) => entry.id.toString())
        }
        .width('100%')
        .height('100%')
        .cachedCount(10)
        .scrollBar(BarState.Auto)
        .divider({
          strokeWidth: 1,
          color: '#EEEEEE',
          startMargin: 16,
          endMargin: 16
        })
      }
      .width('100%')
      .layoutWeight(1)
      .onRefreshing(() => {
        setTimeout(() => {
          this.addNextEntries(REFRESH_BATCH_SIZE)
          this.isRefreshing = false
        }, REFRESH_DELAY_MS)
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }

  private addNextEntries(count: number): void {
    const newEntries: LogEntry[] = []
    for (let i = 0; i < count; i++) {
      newEntries.push(makeEntry(this.nextId))
      this.nextId++
    }
    this.dataSource.prepend(newEntries)
    this.entryCount = this.dataSource.totalCount()
  }
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

const VALID_STATUSES: string[] = ['draft', 'paid', 'shipped'];

function isJsonObject(v: Object | null): boolean {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

export function parseOrder(text: string): ParseResult {
  let parsed: Object | null = null;
  try {
    parsed = JSON.parse(text) as Object | null;
  } catch {
    return { order: undefined, errors: [{ path: '', message: 'invalid JSON' }] };
  }
  if (!isJsonObject(parsed)) {
    return { order: undefined, errors: [{ path: '', message: 'expected an object' }] };
  }

  const obj = parsed as Record<string, Object>;
  const errors: FieldError[] = [];

  // id
  let id = '';
  const idVal: Object | null = obj['id'];
  if (idVal === undefined || idVal === null) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof idVal !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else if (idVal === '') {
    errors.push({ path: 'id', message: 'must not be empty' });
  } else {
    id = idVal as string;
  }

  // status
  let status: OrderStatus = OrderStatus.Draft;
  const statusVal: Object | null = obj['status'];
  if (statusVal !== undefined && statusVal !== null) {
    const s = statusVal as string;
    if (typeof statusVal !== 'string' || VALID_STATUSES.indexOf(s) < 0) {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    } else {
      status = s as OrderStatus;
    }
  }

  // lines
  let lines: OrderLine[] = [];
  const linesVal: Object | null = obj['lines'];
  if (linesVal === undefined || linesVal === null) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(linesVal)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else {
    const arr = linesVal as Object[];
    if (arr.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
      for (let i = 0; i < arr.length; i++) {
        const el: Object | null = arr[i];
        const prefix = `lines[${i}]`;
        if (!isJsonObject(el)) {
          errors.push({ path: prefix, message: 'expected an object' });
          continue;
        }
        const lineObj = el as Record<string, Object>;

        // sku
        let sku = '';
        const skuVal: Object | null = lineObj['sku'];
        if (skuVal === undefined || skuVal === null) {
          errors.push({ path: `${prefix}.sku`, message: 'required' });
        } else if (typeof skuVal !== 'string') {
          errors.push({ path: `${prefix}.sku`, message: 'expected a string' });
        } else if (skuVal === '') {
          errors.push({ path: `${prefix}.sku`, message: 'must not be empty' });
        } else {
          sku = skuVal as string;
        }

        // quantity
        let quantity = 0;
        const qtyVal: Object | null = lineObj['quantity'];
        if (qtyVal === undefined || qtyVal === null) {
          errors.push({ path: `${prefix}.quantity`, message: 'required' });
        } else if (typeof qtyVal !== 'number') {
          errors.push({ path: `${prefix}.quantity`, message: 'expected a number' });
        } else {
          const q = qtyVal as number;
          if (q % 1 !== 0 || q < 1) {
            errors.push({ path: `${prefix}.quantity`, message: 'must be a whole number of 1 or more' });
          } else {
            quantity = q;
          }
        }

        // unitPrice
        let unitPrice = 0;
        const priceVal: Object | null = lineObj['unitPrice'];
        if (priceVal === undefined || priceVal === null) {
          errors.push({ path: `${prefix}.unitPrice`, message: 'required' });
        } else if (typeof priceVal !== 'number') {
          errors.push({ path: `${prefix}.unitPrice`, message: 'expected a number' });
        } else {
          const p = priceVal as number;
          if (p < 0) {
            errors.push({ path: `${prefix}.unitPrice`, message: 'must be 0 or more' });
          } else {
            unitPrice = p;
          }
        }

        // unknown fields of the line
        const lineKeys = Object.keys(lineObj);
        for (const key of lineKeys) {
          if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
            errors.push({ path: `${prefix}.${key}`, message: 'unknown field' });
          }
        }

        lines.push(new OrderLine(sku, quantity, unitPrice));
      }
    }
  }

  // unknown fields of the order
  const orderKeys = Object.keys(obj);
  for (const key of orderKeys) {
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  }
  const order: Order = { id: id, status: status, lines: lines };
  return { order: order, errors: [] };
}

// Shopping list — entry page (HarmonyOS stage model, ArkTS, API 12+).

// Data for one grocery item.
@Observed
class GroceryItem {
  id: number;
  name: string;
  bought: boolean;

  constructor(id: number, name: string, bought: boolean) {
    this.id = id;
    this.name = name;
    this.bought = bought;
  }
}

// One row of the list: shows the item's name. Bought items are struck
// through and grey. Holding the row for half a second flips "bought";
// a short tap does nothing.
@Component
struct GroceryRow {
  @ObjectLink item: GroceryItem;
  onToggleBought: (id: number) => void = (id: number): void => {};

  build() {
    Row() {
      Text(this.item.name)
        .fontSize(18)
        .fontColor(this.item.bought ? '#9E9E9E' : '#000000')
        .decoration({
          type: this.item.bought ? TextDecorationType.LineThrough : TextDecorationType.None
        })
    }
    .width('100%')
    .height(56)
    .padding({ left: 16, right: 16 })
    .alignItems(VerticalAlign.Center)
    .gesture(
      LongPressGesture({ repeat: false, duration: 500 })
        .onAction(() => {
          this.onToggleBought(this.item.id);
        })
    )
  }
}

@Entry
@Component
struct ShoppingList {
  @State items: GroceryItem[] = [
    new GroceryItem(1, 'Milk', false),
    new GroceryItem(2, 'Bread', false),
    new GroceryItem(3, 'Eggs', false),
    new GroceryItem(4, 'Apples', false)
  ];
  @State boughtCount: number = 0;
  @State newItemName: string = '';
  private nextId: number = 5;

  private refreshBoughtCount(): void {
    this.boughtCount = this.items.filter((item: GroceryItem): boolean => item.bought).length;
  }

  private toggleBought(id: number): void {
    const item: GroceryItem | undefined =
      this.items.find((candidate: GroceryItem): boolean => candidate.id === id);
    if (item !== undefined) {
      item.bought = !item.bought;
      this.refreshBoughtCount();
    }
  }

  private removeItem(id: number): void {
    this.items = this.items.filter((item: GroceryItem): boolean => item.id !== id);
    this.refreshBoughtCount();
  }

  private addItem(): void {
    const name: string = this.newItemName.trim();
    if (name.length === 0) {
      return;
    }
    this.items.push(new GroceryItem(this.nextId, name, false));
    this.nextId = this.nextId + 1;
    this.newItemName = '';
    this.refreshBoughtCount();
  }

  // Revealed behind a row that is swiped to the left.
  @Builder
  deleteButton(item: GroceryItem) {
    Button('Delete')
      .type(ButtonType.Normal)
      .backgroundColor('#D32F2F')
      .fontColor('#FFFFFF')
      .fontSize(16)
      .width(80)
      .height(56)
      .onClick(() => {
        this.removeItem(item.id);
      })
  }

  build() {
    Column() {
      Text(`${this.items.length} items, ${this.boughtCount} bought`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .width('100%')
        .padding({ left: 16, right: 16, top: 16, bottom: 8 })

      List({ space: 4 }) {
        ForEach(this.items, (item: GroceryItem) => {
          ListItem() {
            GroceryRow({
              item: item,
              onToggleBought: (id: number): void => {
                this.toggleBought(id);
              }
            })
          }
          .swipeAction({
            end: {
              builder: (): void => {
                this.deleteButton(item)
              }
            }
          })
        }, (item: GroceryItem): string => item.id.toString())
      }
      .width('100%')
      .layoutWeight(1)
      .scrollBar(BarState.Off)
      .divider({ strokeWidth: 1, color: '#EEEEEE', startMargin: 16, endMargin: 16 })

      Row() {
        TextInput({ text: this.newItemName, placeholder: 'New item' })
          .layoutWeight(1)
          .height(44)
          .onChange((value: string) => {
            this.newItemName = value;
          })
          .onSubmit(() => {
            this.addItem();
          })

        Button('Add')
          .height(44)
          .margin({ left: 8 })
          .onClick(() => {
            this.addItem();
          })
      }
      .width('100%')
      .padding(12)
    }
    .width('100%')
    .height('100%')
  }
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigitChar(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStartChar(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNameChar(c: string): boolean {
  return isNameStartChar(c) || isDigitChar(c);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i: number = 0;
  while (i < source.length) {
    const c: string = source.charAt(i);
    if (c === ' ') {
      i++;
      continue;
    }
    if (isDigitChar(c)) {
      const start: number = i;
      while (i < source.length && isDigitChar(source.charAt(i))) {
        i++;
      }
      if (i + 1 < source.length && source.charAt(i) === '.' && isDigitChar(source.charAt(i + 1))) {
        i++;
        while (i < source.length && isDigitChar(source.charAt(i))) {
          i++;
        }
      }
      const token: Token = { kind: 'number', text: source.substring(start, i), position: start };
      tokens.push(token);
      continue;
    }
    if (isNameStartChar(c)) {
      const start: number = i;
      while (i < source.length && isNameChar(source.charAt(i))) {
        i++;
      }
      const token: Token = { kind: 'name', text: source.substring(start, i), position: start };
      tokens.push(token);
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      const token: Token = { kind: 'operator', text: c, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      const token: Token = { kind: 'paren', text: c, position: i };
      tokens.push(token);
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class Parser {
  private tokens: Token[];
  private pos: number;
  private source: string;
  private vars: Map<string, number>;

  constructor(tokens: Token[], source: string, variables: Record<string, number>) {
    this.tokens = tokens;
    this.pos = 0;
    this.source = source;
    this.vars = new Map<string, number>();
    const keys: string[] = Object.keys(variables);
    for (let i = 0; i < keys.length; i++) {
      const key: string = keys[i];
      this.vars.set(key, variables[key]);
    }
  }

  hasMore(): boolean {
    return this.pos < this.tokens.length;
  }

  currentToken(): Token {
    return this.tokens[this.pos];
  }

  parseExpression(): number {
    let left: number = this.parseTerm();
    while (true) {
      if (!this.hasMore()) {
        break;
      }
      const op: Token = this.currentToken();
      if (op.kind !== 'operator' || (op.text !== '+' && op.text !== '-')) {
        break;
      }
      this.pos++;
      const right: number = this.parseTerm();
      if (op.text === '+') {
        left = left + right;
      } else {
        left = left - right;
      }
    }
    return left;
  }

  private parseTerm(): number {
    let left: number = this.parseUnary();
    while (true) {
      if (!this.hasMore()) {
        break;
      }
      const op: Token = this.currentToken();
      if (op.kind !== 'operator' || (op.text !== '*' && op.text !== '/' && op.text !== '%')) {
        break;
      }
      this.pos++;
      const right: number = this.parseUnary();
      if (op.text === '*') {
        left = left * right;
      } else {
        if (right === 0) {
          throw new ExpressionError('Division by zero', op.position);
        }
        if (op.text === '/') {
          left = left / right;
        } else {
          left = left % right;
        }
      }
    }
    return left;
  }

  private parseUnary(): number {
    if (!this.hasMore()) {
      throw new ExpressionError('Unexpected end of expression', this.source.length);
    }
    const t: Token = this.currentToken();
    if (t.kind === 'operator' && t.text === '-') {
      this.pos++;
      return -this.parseUnary();
    }
    return this.parsePrimary();
  }

  private parsePrimary(): number {
    if (!this.hasMore()) {
      throw new ExpressionError('Unexpected end of expression', this.source.length);
    }
    const t: Token = this.currentToken();
    if (t.kind === 'number') {
      this.pos++;
      return Number(t.text);
    }
    if (t.kind === 'name') {
      this.pos++;
      if (!this.vars.has(t.text)) {
        throw new ExpressionError(`Unknown variable '${t.text}'`, t.position);
      }
      const value: number | undefined = this.vars.get(t.text);
      return value as number;
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.pos++;
      const value: number = this.parseExpression();
      if (!this.hasMore()) {
        throw new ExpressionError('Unexpected end of expression', this.source.length);
      }
      const close: Token = this.currentToken();
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.pos++;
      return value;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens: Token[] = tokenize(source);
  const parser: Parser = new Parser(tokens, source, variables);
  const value: number = parser.parseExpression();
  if (parser.hasMore()) {
    const extra: Token = parser.currentToken();
    throw new ExpressionError(`Unexpected token '${extra.text}'`, extra.position);
  }
  return value;
}

