/**
 * EditorState: the observable state of a small text editor.
 */
export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

/**
 * One watcher registered through watch().
 */
interface WatcherEntry {
  field: string;
  listener: (value: string | number | boolean, previous: string | number | boolean) => void;
}

/**
 * EditorStore holds the current editor state, a bounded undo/redo history
 * and per-field listeners.
 */
export class EditorStore {
  private current: EditorState;
  private historyLimit: number;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private watchers: WatcherEntry[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    // Copy the initial state so later changes to the argument do not affect the store.
    const copy: EditorState = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.current = copy;
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    // A fresh object on every read; mutating it cannot affect the store.
    const snapshot: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
    return snapshot;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  apply(patch: Partial<EditorState>): boolean {
    const before: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
    const next: EditorState = {
      text: before.text,
      cursor: before.cursor,
      bold: before.bold
    };
    if (patch.text !== undefined) {
      next.text = patch.text;
    }
    if (patch.cursor !== undefined) {
      next.cursor = patch.cursor;
    }
    if (patch.bold !== undefined) {
      next.bold = patch.bold;
    }
    if (next.text === before.text && next.cursor === before.cursor && next.bold === before.bold) {
      return false;
    }
    this.pushHistory(before);
    this.redoStack = [];
    this.current = next;
    this.notifyChange(before, next);
    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
    // If run throws, nothing has been applied and the error reaches the caller.
    run(draft);
    const patch: Partial<EditorState> = {
      text: draft.text,
      cursor: draft.cursor,
      bold: draft.bold
    };
    return this.apply(patch);
  }

  undo(): boolean {
    const restored: EditorState | undefined = this.undoStack.pop();
    if (restored === undefined) {
      return false;
    }
    const before: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
    this.redoStack.push(before);
    this.current = restored;
    this.notifyChange(before, restored);
    return true;
  }

  redo(): boolean {
    const restored: EditorState | undefined = this.redoStack.pop();
    if (restored === undefined) {
      return false;
    }
    const before: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
    this.pushHistory(before);
    this.current = restored;
    this.notifyChange(before, restored);
    return true;
  }

  watch(field: string,
        listener: (value: string | number | boolean, previous: string | number | boolean) => void): () => void {
    const entry: WatcherEntry = {
      field: field,
      listener: listener
    };
    this.watchers.push(entry);
    const unsubscribe = (): void => {
      const index: number = this.watchers.indexOf(entry);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
    return unsubscribe;
  }

  private pushHistory(before: EditorState): void {
    this.undoStack.push(before);
    while (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }
  }

  private notifyChange(before: EditorState, after: EditorState): void {
    const textChanged: boolean = after.text !== before.text;
    const cursorChanged: boolean = after.cursor !== before.cursor;
    const boldChanged: boolean = after.bold !== before.bold;
    if (!textChanged && !cursorChanged && !boldChanged) {
      return;
    }
    // Snapshot so listeners may unsubscribe safely while being notified.
    const snapshot: WatcherEntry[] = this.watchers.slice();
    for (let i = 0; i < snapshot.length; i++) {
      const entry: WatcherEntry = snapshot[i];
      if (entry.field === 'text' && textChanged) {
        entry.listener(after.text, before.text);
      } else if (entry.field === 'cursor' && cursorChanged) {
        entry.listener(after.cursor, before.cursor);
      } else if (entry.field === 'bold' && boldChanged) {
        entry.listener(after.bold, before.bold);
      }
    }
  }
}

// solution.ets
// Entry page: fetches a JSON array of items over HTTP and renders them.

import { http } from '@kit.NetworkKit';

interface Item {
  id: number;
  name: string;
}

@Entry
@Component
struct ItemListPage {
  @State isLoading: boolean = true;
  @State loadFailed: boolean = false;
  @State items: Item[] = [];

  aboutToAppear(): void {
    this.fetchItems();
  }

  fetchItems(): void {
    const httpRequest: http.HttpRequest = http.createHttp();
    httpRequest
      .request('https://example.com/api/items', {
        method: http.RequestMethod.GET,
        expectDataType: http.HttpDataType.STRING,
        readTimeout: 10000,
        connectTimeout: 10000
      })
      .then((response: http.HttpResponse) => {
        if (response.responseCode === 200) {
          const body: string = response.result as string;
          try {
            const parsed: Item[] = JSON.parse(body) as Item[];
            this.items = parsed;
            this.loadFailed = false;
          } catch (e) {
            this.items = [];
            this.loadFailed = true;
          }
        } else {
          this.items = [];
          this.loadFailed = true;
        }
        this.isLoading = false;
        httpRequest.destroy();
      })
      .catch(() => {
        this.items = [];
        this.loadFailed = true;
        this.isLoading = false;
        httpRequest.destroy();
      });
  }

  build() {
    Column() {
      if (this.isLoading) {
        Text('Loading...')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .margin({ top: 40 })
      } else if (this.loadFailed) {
        Text('Could not load the items')
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
          .fontColor(Color.Red)
          .margin({ top: 40 })
      } else {
        List({ space: 8 }) {
          ForEach(this.items, (item: Item) => {
            ListItem() {
              Text(item.name)
                .fontSize(16)
                .padding(16)
                .width('100%')
            }
            .borderRadius(8)
            .backgroundColor('#F1F3F5')
          }, (item: Item) => `${item.id}`)
        }
        .width('100%')
        .layoutWeight(1)
        .padding(12)
      }
    }
    .width('100%')
    .height('100%')
    .alignItems(HorizontalAlign.Center)
  }
}

/**
 * Reading settings page (stage model, ArkTS).
 *
 * The two settings are app-wide values kept in AppStorage, so any component
 * on any page of the app can read and change them and is redrawn on change:
 *   - 'textSize' : number, whole value in [14, 30], starts at 18
 *   - 'boldText' : boolean, starts at false
 */

const MIN_TEXT_SIZE: number = 14;
const MAX_TEXT_SIZE: number = 30;
const DEFAULT_TEXT_SIZE: number = 18;
const SIZE_STEP: number = 2;
const SIZE_ANIMATION_MS: number = 300;

// Create the app-wide settings before any component runs.
AppStorage.setOrCreate<number>('textSize', DEFAULT_TEXT_SIZE);
AppStorage.setOrCreate<boolean>('boldText', false);

// A preset is plain data: the button label and the size it applies.
class SizePreset {
  public label: string;
  public size: number;

  constructor(label: string, size: number) {
    this.label = label;
    this.size = size;
  }
}

// The three presets held by this file.
const SIZE_PRESETS: Array<SizePreset> = [
  new SizePreset('Small', MIN_TEXT_SIZE),
  new SizePreset('Medium', DEFAULT_TEXT_SIZE),
  new SizePreset('Large', 24)
];

// Size controls: A- / current size / A+ and the three preset buttons.
@Component
struct SizeControls {
  @StorageLink('textSize') textSize: number = DEFAULT_TEXT_SIZE;

  private applySize(value: number): void {
    let next: number = value;
    if (next < MIN_TEXT_SIZE) {
      next = MIN_TEXT_SIZE;
    } else if (next > MAX_TEXT_SIZE) {
      next = MAX_TEXT_SIZE;
    }
    // Only real changes are written, so a clamped press is not a change.
    if (next !== this.textSize) {
      this.textSize = next;
    }
  }

  build() {
    Column({ space: 12 }) {
      Row({ space: 12 }) {
        Button('A-')
          .onClick(() => {
            this.applySize(this.textSize - SIZE_STEP);
          })
        Text(`${this.textSize}`)
          .fontSize(20)
          .fontWeight(FontWeight.Medium)
        Button('A+')
          .onClick(() => {
            this.applySize(this.textSize + SIZE_STEP);
          })
      }
      .alignItems(VerticalAlign.Center)

      Row({ space: 8 }) {
        ForEach(SIZE_PRESETS, (preset: SizePreset) => {
          Button(preset.label)
            .onClick(() => {
              this.applySize(preset.size);
            })
        }, (preset: SizePreset) => preset.label)
      }
      .alignItems(VerticalAlign.Center)
    }
    .width('100%')
    .alignItems(HorizontalAlign.Center)
  }
}

// Preview sentence: drawn at the current size and weight; size changes animate.
// (Named TextPreview so it does not clash with the built-in PreviewText type.)
@Component
struct TextPreview {
  @StorageProp('textSize') textSize: number = DEFAULT_TEXT_SIZE;
  @StorageProp('boldText') boldText: boolean = false;

  build() {
    Text('The quick brown fox')
      .fontSize(this.textSize)
      .fontWeight(this.boldText ? FontWeight.Bold : FontWeight.Normal)
      .textAlign(TextAlign.Center)
      .animation({ duration: SIZE_ANIMATION_MS, curve: Curve.EaseInOut })
  }
}

// Change counter: counts how often the text size took a new value. Read-only.
@Component
struct ChangeCounter {
  @State count: number = 0;
  @StorageProp('textSize') @Watch('onTextSizeChanged') textSize: number = DEFAULT_TEXT_SIZE;
  private lastSeenSize: number = DEFAULT_TEXT_SIZE;

  aboutToAppear(): void {
    this.lastSeenSize = this.textSize;
  }

  onTextSizeChanged(): void {
    if (this.textSize !== this.lastSeenSize) {
      this.lastSeenSize = this.textSize;
      this.count += 1;
    }
  }

  build() {
    Text(`Changed ${this.count} times`)
      .fontSize(16)
  }
}

// Entry page: the bold switch lives here, the three settings components below.
@Entry
@Component
struct ReadingSettingsPage {
  @StorageLink('boldText') boldText: boolean = false;

  build() {
    Column({ space: 24 }) {
      Row({ space: 12 }) {
        Text('Bold')
          .fontSize(18)
        Toggle({ type: ToggleType.Switch, isOn: this.boldText })
          .onChange((isOn: boolean) => {
            this.boldText = isOn;
          })
      }
      .alignItems(VerticalAlign.Center)

      SizeControls()
      TextPreview()
      ChangeCounter()
    }
    .width('100%')
    .height('100%')
    .padding(20)
  }
}

/*
 * solution.ets
 * A build plan made of tasks that depend on each other.
 * Self-contained: no imports.
 */

/** Thrown when a task lists a dependency that is not a task of the plan. */
export class MissingDependencyError extends Error {
  task: string;
  dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

/** Thrown when the dependencies of the tasks form a cycle. */
export class CycleError extends Error {
  path: string[];

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`);
    this.path = path;
  }
}

/** A plan of tasks, each with the list of tasks it depends on. */
export class BuildPlan {
  private readonly taskNames: string[];
  private readonly deps: Map<string, string[]>;

  constructor(spec: Record<string, string[]>) {
    this.taskNames = [];
    this.deps = new Map<string, string[]>();
    const keys: string[] = Object.keys(spec);
    for (const key of keys) {
      this.taskNames.push(key);
      const list: string[] = spec[key];
      this.deps.set(key, list.slice());
    }
    // First check: every dependency must be a task of the plan.
    for (const task of this.taskNames) {
      const list: string[] = this.depsOf(task);
      for (const dep of list) {
        if (!this.deps.has(dep)) {
          throw new MissingDependencyError(task, dep);
        }
      }
    }
    // Second check: the plan must be free of dependency cycles.
    const placed: Set<string> = new Set<string>();
    const chain: string[] = [];
    for (const task of this.taskNames) {
      this.checkCyclesFrom(task, placed, chain);
    }
  }

  /** Dependencies of a task; empty for an unknown task. */
  private depsOf(task: string): string[] {
    const list: string[] | undefined = this.deps.get(task);
    if (list === undefined) {
      return [];
    }
    return list;
  }

  /** Places one task as described for order(), detecting cycles on the way. */
  private checkCyclesFrom(task: string, placed: Set<string>, chain: string[]): void {
    if (placed.has(task)) {
      return;
    }
    const index: number = chain.indexOf(task);
    if (index >= 0) {
      const path: string[] = chain.slice(index);
      path.push(task);
      throw new CycleError(path);
    }
    chain.push(task);
    const list: string[] = this.depsOf(task);
    for (const dep of list) {
      this.checkCyclesFrom(dep, placed, chain);
    }
    chain.pop();
    placed.add(task);
  }

  /** Places one task: first its dependencies in listed order, then the task itself. */
  private placeTask(task: string, result: string[], placed: Set<string>): void {
    if (placed.has(task)) {
      return;
    }
    placed.add(task);
    const list: string[] = this.depsOf(task);
    for (const dep of list) {
      this.placeTask(dep, result, placed);
    }
    result.push(task);
  }

  /** Every task once, each one after all the tasks it depends on. */
  order(): string[] {
    const result: string[] = [];
    const placed: Set<string> = new Set<string>();
    for (const task of this.taskNames) {
      this.placeTask(task, result, placed);
    }
    return result;
  }

  /** Highest layer of the dependencies of a task plus one; 0 for a task without dependencies. */
  private layerOf(task: string, memo: Map<string, number>): number {
    const cached: number | undefined = memo.get(task);
    if (cached !== undefined) {
      return cached;
    }
    let layer: number = 0;
    const list: string[] = this.depsOf(task);
    for (const dep of list) {
      const depLayer: number = this.layerOf(dep, memo);
      if (depLayer + 1 > layer) {
        layer = depLayer + 1;
      }
    }
    memo.set(task, layer);
    return layer;
  }

  /** Tasks grouped for running in parallel; layer 0 holds the tasks that depend on nothing. */
  layers(): string[][] {
    if (this.taskNames.length === 0) {
      return [];
    }
    const memo: Map<string, number> = new Map<string, number>();
    const layerOfTask: number[] = [];
    let maxLayer: number = 0;
    for (let i = 0; i < this.taskNames.length; i++) {
      const layer: number = this.layerOf(this.taskNames[i], memo);
      layerOfTask.push(layer);
      if (layer > maxLayer) {
        maxLayer = layer;
      }
    }
    const layers: string[][] = [];
    for (let i = 0; i <= maxLayer; i++) {
      layers.push([]);
    }
    for (let i = 0; i < this.taskNames.length; i++) {
      const layer: number = layerOfTask[i];
      layers[layer].push(this.taskNames[i]);
    }
    return layers;
  }

  /** Adds value to the list kept for key, without duplicates. */
  private addToMapList(map: Map<string, string[]>, key: string, value: string): void {
    const list: string[] | undefined = map.get(key);
    if (list === undefined) {
      const fresh: string[] = [value];
      map.set(key, fresh);
      return;
    }
    if (list.indexOf(value) < 0) {
      list.push(value);
    }
  }

  /** Every task that depends on name, directly or through other tasks, in order() order. */
  dependentsOf(name: string): string[] {
    if (!this.deps.has(name)) {
      return [];
    }
    const direct: Map<string, string[]> = new Map<string, string[]>();
    for (const task of this.taskNames) {
      const list: string[] = this.depsOf(task);
      for (const dep of list) {
        this.addToMapList(direct, dep, task);
      }
    }
    const found: Set<string> = new Set<string>();
    const queue: string[] = [name];
    let head: number = 0;
    while (head < queue.length) {
      const current: string = queue[head];
      head++;
      const arr: string[] | undefined = direct.get(current);
      if (arr === undefined) {
        continue;
      }
      for (const next of arr) {
        if (next !== name && !found.has(next)) {
          found.add(next);
          queue.push(next);
        }
      }
    }
    const ord: string[] = this.order();
    const result: string[] = [];
    for (const task of ord) {
      if (found.has(task)) {
        result.push(task);
      }
    }
    return result;
  }
}

// Data model. @Observed lets the row component (via @ObjectLink) react to
// changes of an item's properties, e.g. when "bought" is flipped.
@Observed
class GroceryItem {
  id: number;
  name: string;
  bought: boolean;

  constructor(id: number, name: string, bought: boolean) {
    this.id = id;
    this.name = name;
    this.bought = bought;
  }
}

// One row of the shopping list: shows the name, toggles on a long press
// and offers a Delete button behind it when swiped to the left.
@Component
struct GroceryRow {
  @ObjectLink item: GroceryItem;
  onToggle: (item: GroceryItem) => void = (_item: GroceryItem) => {
  };
  onDelete: (item: GroceryItem) => void = (_item: GroceryItem) => {
  };

  // Revealed at the right edge when the row is swiped to the left.
  @Builder
  deleteButton() {
    Button('Delete')
      .type(ButtonType.Normal)
      .fontColor('#FFFFFF')
      .fontSize(16)
      .backgroundColor('#D32F2F')
      .width(84)
      .height(56)
      .onClick(() => {
        this.onDelete(this.item);
      })
  }

  build() {
    ListItem() {
      Row() {
        Text(this.item.name)
          .fontSize(18)
          .maxLines(1)
          .fontColor(this.item.bought ? '#9E9E9E' : '#000000')
          .decoration({
            type: this.item.bought ? TextDecorationType.LineThrough : TextDecorationType.None,
            color: '#9E9E9E'
          })
          .layoutWeight(1)
      }
      .width('100%')
      .height(56)
      .padding({ left: 16, right: 16 })
      .backgroundColor('#FFFFFF')
      // Hold for half a second flips bought/not bought; a short tap does
      // nothing because there is no click handler on the row.
      .gesture(LongPressGesture({ fingers: 1, repeat: false, duration: 500 })
        .onAction(() => {
          this.onToggle(this.item);
        }))
    }
    .swipeAction({
      end: {
        builder: (): void => {
          this.deleteButton();
        }
      },
      edgeEffect: SwipeEdgeEffect.Spring
    })
  }
}

@Entry
@Component
struct Index {
  @State items: GroceryItem[] = [
    new GroceryItem(1, 'Milk', false),
    new GroceryItem(2, 'Bread', false),
    new GroceryItem(3, 'Eggs', false),
    new GroceryItem(4, 'Apples', false)
  ];
  @State newName: string = '';
  @State boughtCount: number = 0;
  // Monotonic counter: ids of deleted items are never handed out again.
  private nextId: number = 5;
  private scroller: ListScroller = new ListScroller();

  addItem(): void {
    const name: string = this.newName.trim();
    if (name.length === 0) {
      return;
    }
    this.items.push(new GroceryItem(this.nextId++, name, false));
    this.newName = '';
  }

  toggleItem(item: GroceryItem): void {
    item.bought = !item.bought;
    this.boughtCount = item.bought ? this.boughtCount + 1 : this.boughtCount - 1;
  }

  deleteItem(item: GroceryItem): void {
    const index: number = this.items.indexOf(item);
    if (index < 0) {
      return;
    }
    this.scroller.closeAllSwipeActions();
    if (item.bought) {
      this.boughtCount = this.boughtCount - 1;
    }
    this.items.splice(index, 1);
  }

  build() {
    Column() {
      Text(`${this.items.length} items, ${this.boughtCount} bought`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .padding({ left: 16, right: 16, top: 12, bottom: 12 })

      List() {
        ForEach(this.items, (item: GroceryItem) => {
          GroceryRow({
            item: item,
            onToggle: (it: GroceryItem): void => {
              this.toggleItem(it);
            },
            onDelete: (it: GroceryItem): void => {
              this.deleteItem(it);
            }
          })
        }, (item: GroceryItem): string => item.id.toString())
      }
      .width('100%')
      .layoutWeight(1)
      .scroller(this.scroller)
      .divider({ strokeWidth: 1, color: '#E0E0E0', startMargin: 16, endMargin: 16 })

      Row() {
        TextInput({ placeholder: 'New item', text: this.newName })
          .layoutWeight(1)
          .onChange((value: string) => {
            this.newName = value;
          })
          .onSubmit(() => {
            this.addItem();
          })

        Button('Add')
          .margin({ left: 12 })
          .onClick(() => {
            this.addItem();
          })
      }
      .width('100%')
      .padding(16)
    }
    .width('100%')
    .height('100%')
  }
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface QueuedJob {
  start: () => void;
  cancel: (error: Error) => void;
}

export class JobQueue {
  private concurrency: number;
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private waitingJobs: Array<QueuedJob> = [];
  private idleResolvers: Array<() => void> = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingJobs.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    let resolvePromise: (value: T) => void = () => {};
    let rejectPromise: (error: Error) => void = () => {};

    const promise: Promise<T> = new Promise<T>((resolve, reject) => {
      resolvePromise = (value: T) => {
        resolve(value);
      };
      rejectPromise = (error: Error) => {
        reject(error);
      };
    });

    const task: QueuedJob = {
      start: () => {
        this.runningCount++;
        const jobPromise: Promise<T> = job();
        jobPromise.then((value: T) => {
          this.runningCount--;
          this.completedCount++;
          resolvePromise(value);
          this.pump();
          this.checkIdle();
        }, (error: Error) => {
          this.runningCount--;
          this.failedCount++;
          rejectPromise(error);
          this.pump();
          this.checkIdle();
        });
      },
      cancel: (error: Error) => {
        rejectPromise(error);
      }
    };

    this.waitingJobs.push(task);
    this.pump();
    return promise;
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.pump();
  }

  clear(): number {
    const removed: number = this.waitingJobs.length;
    const tasks: Array<QueuedJob> = this.waitingJobs;
    this.waitingJobs = [];
    for (let i = 0; i < tasks.length; i++) {
      tasks[i].cancel(new Error("Job was cancelled"));
    }
    this.checkIdle();
    return removed;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleResolvers.push(() => {
        resolve();
      });
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: Array<JobOutcome<T>> = [];
    const promises: Array<Promise<void>> = [];

    for (let i = 0; i < jobs.length; i++) {
      const index: number = i;
      const job: () => Promise<T> = jobs[i];
      const promise: Promise<void> = this.add<T>(job).then((value: T) => {
        const outcome: JobOutcome<T> = {
          ok: true,
          value: value,
          error: undefined
        };
        outcomes[index] = outcome;
      }, (error: Error) => {
        const outcome: JobOutcome<T> = {
          ok: false,
          value: undefined,
          error: error
        };
        outcomes[index] = outcome;
      });
      promises.push(promise);
    }

    return Promise.all(promises).then(() => {
      return outcomes;
    });
  }

  private pump(): void {
    if (this.paused) {
      return;
    }
    while (this.runningCount < this.concurrency && this.waitingJobs.length > 0) {
      const task: QueuedJob | undefined = this.waitingJobs.shift();
      if (task !== undefined) {
        task.start();
      }
    }
    this.checkIdle();
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.waitingJobs.length === 0) {
      const resolvers: Array<() => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (let i = 0; i < resolvers.length; i++) {
        resolvers[i]();
      }
    }
  }
}

class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number, message: string, level: string) {
    this.id = id;
    this.message = message;
    this.level = level;
  }
}

function levelForId(id: number): string {
  if (id % 50 === 0) {
    return 'error';
  }
  if (id % 10 === 0) {
    return 'warning';
  }
  return 'info';
}

function colorForLevel(level: string): string {
  if (level === 'error') {
    return '#D32F2F';
  }
  if (level === 'warning') {
    return '#F57C00';
  }
  return '#757575';
}

class LogDataSource implements IDataSource {
  private entries: LogEntry[] = [];
  private listeners: DataChangeListener[] = [];

  totalCount(): number {
    return this.entries.length;
  }

  getData(index: number): LogEntry {
    return this.entries[index];
  }

  registerDataChangeListener(listener: DataChangeListener): void {
    if (this.listeners.indexOf(listener) < 0) {
      this.listeners.push(listener);
    }
  }

  unregisterDataChangeListener(listener: DataChangeListener): void {
    const pos: number = this.listeners.indexOf(listener);
    if (pos >= 0) {
      this.listeners.splice(pos, 1);
    }
  }

  setAll(items: LogEntry[]): void {
    this.entries = items;
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataReloaded();
    });
  }

  addToFront(entry: LogEntry): void {
    this.entries.unshift(entry);
    this.listeners.forEach((listener: DataChangeListener) => {
      listener.onDataAdd(0);
    });
  }

  highestId(): number {
    if (this.entries.length === 0) {
      return 0;
    }
    return this.entries[0].id;
  }
}

