  }
}

@Entry
@Component
struct LogPage {
  private source: LogDataSource = new LogDataSource();
  @State count: number = 0;
  @State refreshing: boolean = false;

  aboutToAppear(): void {
    const items: LogEntry[] = [];
    for (let id = 3000; id >= 1; id--) {
      items.push(new LogEntry(id, 'Event ' + id, levelForId(id)));
    }
    this.source.setAll(items);
    this.count = items.length;
  }

  addNewEntries(): void {
    const highest: number = this.source.highestId();
    for (let i = 1; i <= 5; i++) {
      const id: number = highest + i;
      this.source.addToFront(new LogEntry(id, 'Event ' + id, levelForId(id)));
    }
    this.count = this.source.totalCount();
  }

  build() {
    Column() {
      Text(this.count + ' entries')
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .fontColor('#212121')
        .width('100%')
        .padding({ left: 16, right: 16, top: 12, bottom: 12 })

      Refresh({ refreshing: $$this.refreshing }) {
        List() {
          LazyForEach(this.source, (item: LogEntry) => {
            ListItem() {
              LogRow({ entry: item })
            }
          }, (item: LogEntry) => item.id.toString())
        }
        .width('100%')
        .height('100%')
        .cachedCount(5)
        .divider({ strokeWidth: 1, color: '#EEEEEE' })
      }
      .onRefreshing(() => {
        this.refreshing = true;
        setTimeout(() => {
          this.addNewEntries();
          this.refreshing = false;
        }, 1000);
      })
      .layoutWeight(1)
      .width('100%')
    }
    .width('100%')
    .height('100%')
    .backgroundColor('#FFFFFF')
  }
}

export interface EditorState {
  text: string;
  cursor: number;
  bold: boolean;
}

interface Watcher {
  field: string;
  listener: (value: string | number | boolean, previous: string | number | boolean) => void;
  active: boolean;
}

export class EditorStore {
  private current: EditorState;
  private undoStack: EditorState[] = [];
  private redoStack: EditorState[] = [];
  private historyLimit: number;
  private watchers: Watcher[] = [];

  constructor(initial: EditorState, historyLimit: number) {
    this.current = {
      text: initial.text,
      cursor: initial.cursor,
      bold: initial.bold
    };
    this.historyLimit = historyLimit;
  }

  get state(): EditorState {
    return {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };
  }

  apply(patch: Partial<EditorState>): boolean {
    const current = this.current;
    let nextText: string = current.text;
    let nextCursor: number = current.cursor;
    let nextBold: boolean = current.bold;

    const patchText = patch.text;
    if (patchText !== undefined) {
      nextText = patchText;
    }

    const patchCursor = patch.cursor;
    if (patchCursor !== undefined) {
      nextCursor = patchCursor;
    }

    const patchBold = patch.bold;
    if (patchBold !== undefined) {
      nextBold = patchBold;
    }

    if (nextText === current.text && nextCursor === current.cursor && nextBold === current.bold) {
      return false;
    }

    const next: EditorState = {
      text: nextText,
      cursor: nextCursor,
      bold: nextBold
    };

    this.commit(next, current);
    return true;
  }

  transaction(run: (draft: EditorState) => void): boolean {
    const draft: EditorState = {
      text: this.current.text,
      cursor: this.current.cursor,
      bold: this.current.bold
    };

    run(draft);

    return this.apply({
      text: draft.text,
      cursor: draft.cursor,
      bold: draft.bold
    });
  }

  undo(): boolean {
    if (this.undoStack.length === 0) {
      return false;
    }

    const previous = this.undoStack.pop();
    if (previous === undefined) {
      return false;
    }

    const current = this.current;
    this.redoStack.push(current);
    this.current = previous;
    this.notify(current, previous);
    return true;
  }

  redo(): boolean {
    if (this.redoStack.length === 0) {
      return false;
    }

    const next = this.redoStack.pop();
    if (next === undefined) {
      return false;
    }

    const current = this.current;
    this.undoStack.push(current);
    if (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }

    this.current = next;
    this.notify(current, next);
    return true;
  }

  get canUndo(): boolean {
    return this.undoStack.length > 0;
  }

  get canRedo(): boolean {
    return this.redoStack.length > 0;
  }

  watch(
    field: string,
    listener: (value: string | number | boolean, previous: string | number | boolean) => void
  ): () => void {
    const watcher: Watcher = {
      field: field,
      listener: listener,
      active: true
    };

    this.watchers.push(watcher);

    return () => {
      if (!watcher.active) {
        return;
      }

      watcher.active = false;
      const index = this.watchers.indexOf(watcher);
      if (index >= 0) {
        this.watchers.splice(index, 1);
      }
    };
  }

  private commit(next: EditorState, previous: EditorState): void {
    this.undoStack.push(previous);
    if (this.undoStack.length > this.historyLimit) {
      this.undoStack.shift();
    }

    this.redoStack.length = 0;
    this.current = next;
    this.notify(previous, next);
  }

  private notify(previous: EditorState, next: EditorState): void {
    const changedText = previous.text !== next.text;
    const changedCursor = previous.cursor !== next.cursor;
    const changedBold = previous.bold !== next.bold;

    if (!changedText && !changedCursor && !changedBold) {
      return;
    }

    const snapshot = this.watchers.slice();

    for (let i = 0; i < snapshot.length; i++) {
      const watcher = snapshot[i];
      if (!watcher.active) {
        continue;
      }

      let newValue: string | number | boolean = next.text;
      let oldValue: string | number | boolean = previous.text;

      if (watcher.field === 'text') {
        if (!changedText) {
          continue;
        }
        newValue = next.text;
        oldValue = previous.text;
      } else if (watcher.field === 'cursor') {
        if (!changedCursor) {
          continue;
        }
        newValue = next.cursor;
        oldValue = previous.cursor;
      } else if (watcher.field === 'bold') {
        if (!changedBold) {
          continue;
        }
        newValue = next.bold;
        oldValue = previous.bold;
      } else {
        continue;
      }

      watcher.listener(newValue, oldValue);
    }
  }
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number = 0;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
    this.name = 'ExpressionError';
  }
}

function isDigit(ch: string): boolean {
  const code = ch.charCodeAt(0);
  return code >= 48 && code <= 57;
}

function isLetter(ch: string): boolean {
  const code = ch.charCodeAt(0);
  return (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}

function isNameStart(ch: string): boolean {
  return isLetter(ch) || ch === '_';
}

function isNamePart(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const ch = source.charAt(i);

    if (ch === ' ') {
      i++;
      continue;
    }

    if (isDigit(ch)) {
      const start = i;
      while (i < source.length && isDigit(source.charAt(i))) {
        i++;
      }
      if (i < source.length && source.charAt(i) === '.' && i + 1 < source.length && isDigit(source.charAt(i + 1))) {
        i++;
        while (i < source.length && isDigit(source.charAt(i))) {
          i++;
        }
      }
      const text = source.substring(start, i);
      const token: Token = { kind: 'number', text: text, position: start };
      tokens.push(token);
      continue;
    }

    if (isNameStart(ch)) {
      const start = i;
      i++;
      while (i < source.length && isNamePart(source.charAt(i))) {
        i++;
      }
      const text = source.substring(start, i);
      const token: Token = { kind: 'name', text: text, position: start };
      tokens.push(token);
      continue;
    }

    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%') {
      const token: Token = { kind: 'operator', text: ch, position: i };
      tokens.push(token);
      i++;
      continue;
    }

    if (ch === '(' || ch === ')') {
      const token: Token = { kind: 'paren', text: ch, position: i };
      tokens.push(token);
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${ch}'`, i);
  }

  return tokens;
}

abstract class Expr {
  abstract evaluate(variables: Record<string, number>): number;
}

class NumberExpr extends Expr {
  private value: number = 0;

  constructor(value: number) {
    super();
    this.value = value;
  }

  evaluate(_variables: Record<string, number>): number {
    return this.value;
  }
}

class NameExpr extends Expr {
  private name: string = '';
  private position: number = 0;

  constructor(name: string, position: number) {
    super();
    this.name = name;
    this.position = position;
  }

  evaluate(variables: Record<string, number>): number {
    const keys: string[] = Object.keys(variables);
    if (keys.indexOf(this.name) < 0) {
      throw new ExpressionError(`Unknown variable '${this.name}'`, this.position);
    }
    return variables[this.name];
  }
}

class UnaryExpr extends Expr {
  private operand: Expr;

  constructor(operand: Expr) {
    super();
    this.operand = operand;
  }

  evaluate(variables: Record<string, number>): number {
    const value = this.operand.evaluate(variables);
    return -value;
  }
}

class BinaryExpr extends Expr {
  private left: Expr;
  private right: Expr;
  private operator: string = '';
  private position: number = 0;

  constructor(left: Expr, right: Expr, operator: string, position: number) {
    super();
    this.left = left;
    this.right = right;
    this.operator = operator;
    this.position = position;
  }

  evaluate(variables: Record<string, number>): number {
    const leftValue = this.left.evaluate(variables);
    const rightValue = this.right.evaluate(variables);

    if (this.operator === '+') {
      return leftValue + rightValue;
    }
    if (this.operator === '-') {
      return leftValue - rightValue;
    }
    if (this.operator === '*') {
      return leftValue * rightValue;
    }
    if (this.operator === '/') {
      if (rightValue === 0) {
        throw new ExpressionError('Division by zero', this.position);
      }
      return leftValue / rightValue;
    }
    if (this.operator === '%') {
      if (rightValue === 0) {
        throw new ExpressionError('Division by zero', this.position);
      }
      return leftValue % rightValue;
    }

    throw new ExpressionError(`Unexpected token '${this.operator}'`, this.position);
  }
}

class Parser {
  private tokens: Token[] = [];
  private index: number = 0;
  private sourceLength: number = 0;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
  }

  parse(): Expr {
    const expr = this.parseExpression();
    if (this.index < this.tokens.length) {
      const token = this.tokens[this.index];
      throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
    }
    return expr;
  }

  private current(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return undefined;
  }

  private parseExpression(): Expr {
    return this.parseAdditive();
  }

  private parseAdditive(): Expr {
    let left = this.parseMultiplicative();

    while (true) {
      const token = this.current();
      if (token === undefined) {
        break;
      }
      if (token.kind === 'operator' && (token.text === '+' || token.text === '-')) {
        this.index++;
        const right = this.parseMultiplicative();
        left = new BinaryExpr(left, right, token.text, token.position);
      } else {
        break;
      }
    }

    return left;
  }

  private parseMultiplicative(): Expr {
    let left = this.parseUnary();

    while (true) {
      const token = this.current();
      if (token === undefined) {
        break;
      }
      if (token.kind === 'operator' && (token.text === '*' || token.text === '/' || token.text === '%')) {
        this.index++;
        const right = this.parseUnary();
        left = new BinaryExpr(left, right, token.text, token.position);
      } else {
        break;
      }
    }

    return left;
  }

  private parseUnary(): Expr {
    const token = this.current();
    if (token !== undefined && token.kind === 'operator' && token.text === '-') {
      this.index++;
      const operand = this.parseUnary();
      return new UnaryExpr(operand);
    }
    return this.parsePrimary();
  }

  private parsePrimary(): Expr {
    const token = this.current();

    if (token === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }

    if (token.kind === 'number') {
      this.index++;
      return new NumberExpr(Number(token.text));
    }

    if (token.kind === 'name') {
      this.index++;
      return new NameExpr(token.text, token.position);
    }

    if (token.kind === 'paren' && token.text === '(') {
      this.index++;
      const expr = this.parseExpression();
      const close = this.current();

      if (close === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }

      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }

      this.index++;
      return expr;
    }

    throw new ExpressionError(`Unexpected token '${token.text}'`, token.position);
  }
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const expr = parser.parse();
  return expr.evaluate(variables);
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

type JsonObject = Record<string, Object | null>;

function isMissing(value: Object | null | undefined): boolean {
  return value === null || value === undefined;
}

function isJsonObject(value: Object | null | undefined): boolean {
  if (value === null || value === undefined) {
    return false;
  }
  if (typeof value !== 'object') {
    return false;
  }
  return !Array.isArray(value);
}

function getField(obj: JsonObject, key: string): Object | null | undefined {
  return obj[key];
}

export function parseOrder(text: string): ParseResult {
  const errors: FieldError[] = [];

  let parsed: Object | null = null;
  let parseOk: boolean = true;
  try {
    parsed = JSON.parse(text) as Object | null;
  } catch (e) {
    parseOk = false;
  }

  if (!parseOk) {
    errors.push({ path: '', message: 'invalid JSON' });
    return { order: undefined, errors: errors };
  }

  if (parsed === null || !isJsonObject(parsed)) {
    errors.push({ path: '', message: 'expected an object' });
    return { order: undefined, errors: errors };
  }

  const root: JsonObject = parsed as JsonObject;

  let id: string = '';
  const idValue: Object | null | undefined = getField(root, 'id');
  if (isMissing(idValue)) {
    errors.push({ path: 'id', message: 'required' });
  } else if (typeof idValue !== 'string') {
    errors.push({ path: 'id', message: 'expected a string' });
  } else {
    const idStr: string = idValue as string;
    if (idStr === '') {
      errors.push({ path: 'id', message: 'must not be empty' });
    } else {
      id = idStr;
    }
  }

  let status: OrderStatus = OrderStatus.Draft;
  const statusValue: Object | null | undefined = getField(root, 'status');
  if (!isMissing(statusValue)) {
    let statusOk: boolean = false;
    if (typeof statusValue === 'string') {
      const statusStr: string = statusValue as string;
      if (statusStr === 'draft') {
        status = OrderStatus.Draft;
        statusOk = true;
      } else if (statusStr === 'paid') {
        status = OrderStatus.Paid;
        statusOk = true;
      } else if (statusStr === 'shipped') {
        status = OrderStatus.Shipped;
        statusOk = true;
      }
    }
    if (!statusOk) {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' });
    }
  }

  const lines: OrderLine[] = [];
  const linesValue: Object | null | undefined = getField(root, 'lines');
  if (isMissing(linesValue)) {
    errors.push({ path: 'lines', message: 'required' });
  } else if (!Array.isArray(linesValue)) {
    errors.push({ path: 'lines', message: 'expected an array' });
  } else {
    const lineArray: Object[] = linesValue as Object[];
    if (lineArray.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' });
    } else {
      for (let i = 0; i < lineArray.length; i++) {
        const element: Object = lineArray[i];
        const prefix: string = `lines[${i}]`;
        if (!isJsonObject(element)) {
          errors.push({ path: prefix, message: 'expected an object' });
          continue;
        }
        const lineObj: JsonObject = element as JsonObject;

        let sku: string = '';
        const skuValue: Object | null | undefined = getField(lineObj, 'sku');
        if (isMissing(skuValue)) {
          errors.push({ path: `${prefix}.sku`, message: 'required' });
        } else if (typeof skuValue !== 'string') {
          errors.push({ path: `${prefix}.sku`, message: 'expected a string' });
        } else {
          const skuStr: string = skuValue as string;
          if (skuStr === '') {
            errors.push({ path: `${prefix}.sku`, message: 'must not be empty' });
          } else {
            sku = skuStr;
          }
        }

        let quantity: number = 0;
        const quantityValue: Object | null | undefined = getField(lineObj, 'quantity');
        if (isMissing(quantityValue)) {
          errors.push({ path: `${prefix}.quantity`, message: 'required' });
        } else if (typeof quantityValue !== 'number') {
          errors.push({ path: `${prefix}.quantity`, message: 'expected a number' });
        } else {
          const q: number = quantityValue as number;
          if (!Number.isInteger(q) || q < 1) {
            errors.push({ path: `${prefix}.quantity`, message: 'must be a whole number of 1 or more' });
          } else {
            quantity = q;
          }
        }

        let unitPrice: number = 0;
        const priceValue: Object | null | undefined = getField(lineObj, 'unitPrice');
        if (isMissing(priceValue)) {
          errors.push({ path: `${prefix}.unitPrice`, message: 'required' });
        } else if (typeof priceValue !== 'number') {
          errors.push({ path: `${prefix}.unitPrice`, message: 'expected a number' });
        } else {
          const p: number = priceValue as number;
          if (p < 0) {
            errors.push({ path: `${prefix}.unitPrice`, message: 'must be 0 or more' });
          } else {
            unitPrice = p;
          }
        }

        const lineKeys: string[] = Object.keys(lineObj);
        for (let k = 0; k < lineKeys.length; k++) {
          const key: string = lineKeys[k];
          if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
            errors.push({ path: `${prefix}.${key}`, message: 'unknown field' });
          }
        }

        lines.push(new OrderLine(sku, quantity, unitPrice));
      }
    }
  }

  const rootKeys: string[] = Object.keys(root);
  for (let k = 0; k < rootKeys.length; k++) {
    const key: string = rootKeys[k];
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push({ path: key, message: 'unknown field' });
    }
  }

  if (errors.length > 0) {
    return { order: undefined, errors: errors };
  }

  const order: Order = { id: id, status: status, lines: lines };
  return { order: order, errors: errors };
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.name = 'ExpressionError';
    this.position = position;
  }
}

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function isNameStart(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_';
}

function isNamePart(c: string): boolean {
  return isNameStart(c) || isDigit(c);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  const n: number = source.length;
  let i: number = 0;
  while (i < n) {
    const c: string = source.charAt(i);
    if (c === ' ') {
      i++;
      continue;
    }
    if (isDigit(c)) {
      let j: number = i;
      while (j < n && isDigit(source.charAt(j))) {
        j++;
      }
      if (j < n && source.charAt(j) === '.' && j + 1 < n && isDigit(source.charAt(j + 1))) {
        j++;
        while (j < n && isDigit(source.charAt(j))) {
          j++;
        }
      }
      tokens.push({ kind: 'number', text: source.substring(i, j), position: i });
      i = j;
      continue;
    }
    if (isNameStart(c)) {
      let j: number = i + 1;
      while (j < n && isNamePart(source.charAt(j))) {
        j++;
      }
      tokens.push({ kind: 'name', text: source.substring(i, j), position: i });
      i = j;
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      tokens.push({ kind: 'operator', text: c, position: i });
      i++;
      continue;
    }
    if (c === '(' || c === ')') {
      tokens.push({ kind: 'paren', text: c, position: i });
      i++;
      continue;
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i);
  }
  return tokens;
}

class Node {
  kind: string = '';
  value: number = 0;
  name: string = '';
  op: string = '';
  pos: number = 0;
  left: Node | null = null;
  right: Node | null = null;
}

class Parser {
  private tokens: Token[];
  private index: number;
  private sourceLength: number;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.index = 0;
    this.sourceLength = sourceLength;
  }

  parse(): Node {
    const node: Node = this.parseExpression();
    const t: Token | null = this.peek();
    if (t !== null) {
      throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
    }
    return node;
  }

  private peek(): Token | null {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return null;
  }

  private parseExpression(): Node {
    let left: Node = this.parseTerm();
    while (true) {
      const t: Token | null = this.peek();
      if (t !== null && t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.index++;
        const right: Node = this.parseTerm();
        const node: Node = new Node();
        node.kind = 'bin';
        node.op = t.text;
        node.pos = t.position;
        node.left = left;
        node.right = right;
        left = node;
      } else {
        break;
      }
    }
    return left;
  }

  private parseTerm(): Node {
    let left: Node = this.parseUnary();
    while (true) {
      const t: Token | null = this.peek();
      if (t !== null && t.kind === 'operator' && (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.index++;
        const right: Node = this.parseUnary();
        const node: Node = new Node();
        node.kind = 'bin';
        node.op = t.text;
        node.pos = t.position;
        node.left = left;
        node.right = right;
        left = node;
      } else {
        break;
      }
    }
    return left;
  }

  private parseUnary(): Node {
    const t: Token | null = this.peek();
    if (t !== null && t.kind === 'operator' && t.text === '-') {
      this.index++;
      const operand: Node = this.parseUnary();
      const node: Node = new Node();
      node.kind = 'neg';
      node.pos = t.position;
      node.left = operand;
      return node;
    }
    return this.parsePrimary();
  }

  private parsePrimary(): Node {
    const t: Token | null = this.peek();
    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }
    if (t.kind === 'number') {
      this.index++;
      const node: Node = new Node();
      node.kind = 'num';
      node.value = Number.parseFloat(t.text);
      node.pos = t.position;
      return node;
    }
    if (t.kind === 'name') {
      this.index++;
      const node: Node = new Node();
      node.kind = 'var';
      node.name = t.text;
      node.pos = t.position;
      return node;
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.index++;
      const inner: Node = this.parseExpression();
      const close: Token | null = this.peek();
      if (close === null) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }
      if (!(close.kind === 'paren' && close.text === ')')) {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }
      this.index++;
      return inner;
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function evalNode(node: Node, variables: Record<string, number>): number {
  if (node.kind === 'num') {
    return node.value;
  }
  if (node.kind === 'var') {
    const value: number | undefined = variables[node.name];
    if (value === undefined) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.pos);
    }
    return value;
  }
  if (node.kind === 'neg') {
    const operand: Node | null = node.left;
    if (operand === null) {
      return 0;
    }
    return -evalNode(operand, variables);
  }
  const leftNode: Node | null = node.left;
  const rightNode: Node | null = node.right;
  if (leftNode === null || rightNode === null) {
    return 0;
  }
  const l: number = evalNode(leftNode, variables);
  const r: number = evalNode(rightNode, variables);
  if (node.op === '+') {
    return l + r;
  }
  if (node.op === '-') {
    return l - r;
  }
  if (node.op === '*') {
    return l * r;
  }
  if (node.op === '/') {
    if (r === 0) {
      throw new ExpressionError('Division by zero', node.pos);
    }
    return l / r;
  }
  if (node.op === '%') {
    if (r === 0) {
      throw new ExpressionError('Division by zero', node.pos);
    }
    return l % r;
  }
  return 0;
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens: Token[] = tokenize(source);
  const parser: Parser = new Parser(tokens, source.length);
  const ast: Node = parser.parse();
  return evalNode(ast, variables);
}

function isHexDigit(c: string): boolean {
  return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

function hexValue(c: string): number {
  if (c >= '0' && c <= '9') {
    return c.charCodeAt(0) - 48;
  }
  if (c >= 'a' && c <= 'f') {
    return c.charCodeAt(0) - 87;
  }
  return c.charCodeAt(0) - 55;
}

function bytesToString(bytes: number[]): string {
  let out: string = '';
  let i: number = 0;
  const n: number = bytes.length;
  while (i < n) {
    const b0: number = bytes[i];
    if (b0 < 0x80) {
      out += String.fromCharCode(b0);
      i += 1;
    } else if (b0 >= 0xC2 && b0 <= 0xDF) {
      if (i + 1 < n && (bytes[i + 1] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x1F) << 6) | (bytes[i + 1] & 0x3F);
        out += String.fromCharCode(cp);
        i += 2;
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else if (b0 >= 0xE0 && b0 <= 0xEF) {
      if (i + 2 < n && (bytes[i + 1] & 0xC0) === 0x80 && (bytes[i + 2] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x0F) << 12) | ((bytes[i + 1] & 0x3F) << 6) | (bytes[i + 2] & 0x3F);
        if (cp < 0x800 || (cp >= 0xD800 && cp <= 0xDFFF)) {
          out += '\uFFFD';
        } else {
          out += String.fromCharCode(cp);
        }
        i += 3;
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else if (b0 >= 0xF0 && b0 <= 0xF4) {
      if (i + 3 < n && (bytes[i + 1] & 0xC0) === 0x80 && (bytes[i + 2] & 0xC0) === 0x80 &&
        (bytes[i + 3] & 0xC0) === 0x80) {
        const cp: number = ((b0 & 0x07) << 18) | ((bytes[i + 1] & 0x3F) << 12) |
          ((bytes[i + 2] & 0x3F) << 6) | (bytes[i + 3] & 0x3F);
        if (cp < 0x10000 || cp > 0x10FFFF) {
          out += '\uFFFD';
        } else {
          const v: number = cp - 0x10000;
          out += String.fromCharCode(0xD800 + (v >> 10));
          out += String.fromCharCode(0xDC00 + (v & 0x3FF));
        }
        i += 4;
      } else {
        out += '\uFFFD';
        i += 1;
      }
    } else {
      out += '\uFFFD';
      i += 1;
    }
  }
  return out;
}

function decodeComponent(s: string): string {
  // First pass: verify that every '%' starts a well-formed escape.
  let i: number = 0;
  while (i < s.length) {
    const c: string = s.charAt(i);
    if (c === '%') {
      if (i + 2 < s.length && isHexDigit(s.charAt(i + 1)) && isHexDigit(s.charAt(i + 2))) {
        i += 3;
      } else {
        // Malformed escape: keep the whole component as written, only '+' replaced.
        return s.split('+').join(' ');
      }
    } else {
      i += 1;
    }
  }

  // Second pass: decode percent-escapes as UTF-8, '+' as space.
  let out: string = '';
  let bytes: number[] = [];
  i = 0;
  while (i < s.length) {
    const c: string = s.charAt(i);
    if (c === '%') {
      const hi: number = hexValue(s.charAt(i + 1));
      const lo: number = hexValue(s.charAt(i + 2));
      bytes.push(hi * 16 + lo);
      i += 3;
    } else {
      if (bytes.length > 0) {
        out += bytesToString(bytes);
        bytes = [];
      }
      if (c === '+') {
        out += ' ';
      } else {
        out += c;
      }
      i += 1;
    }
  }
  if (bytes.length > 0) {
    out += bytesToString(bytes);
  }
  return out;
}

export function parseQuery(query: string): Map<string, string> {
  const result: Map<string, string> = new Map<string, string>();
  let q: string = query;
  if (q.length > 0 && q.charAt(0) === '?') {
    q = q.substring(1);
  }
  if (q.length === 0) {
    return result;
  }

  const parts: string[] = q.split('&');
  for (let i = 0; i < parts.length; i++) {
    const part: string = parts[i];
    if (part.length === 0) {
      continue;
    }
    const eq: number = part.indexOf('=');
    let rawKey: string;
    let rawValue: string;
    if (eq < 0) {
      rawKey = part;
      rawValue = '';
    } else {
      rawKey = part.substring(0, eq);
      rawValue = part.substring(eq + 1);
    }
    const key: string = decodeComponent(rawKey);
    if (key.length === 0) {
      continue;
    }
    const value: string = decodeComponent(rawValue);
    result.set(key, value);
  }
  return result;
}

