function pad2(value: number): string {
  if (value < 10) {
    return '0' + value.toString();
  }
  return value.toString();
}

export function formatDuration(totalSeconds: number): string {
  if (totalSeconds < 0) {
    return '-' + formatDuration(-totalSeconds);
  }
  if (totalSeconds < 60) {
    return totalSeconds.toString() + 's';
  }
  if (totalSeconds < 3600) {
    const minutes: number = Math.floor(totalSeconds / 60);
    const seconds: number = totalSeconds % 60;
    return minutes.toString() + 'm ' + pad2(seconds) + 's';
  }
  const hours: number = Math.floor(totalSeconds / 3600);
  const remaining: number = totalSeconds % 3600;
  const minutes: number = Math.floor(remaining / 60);
  const seconds: number = remaining % 60;
  return hours.toString() + 'h ' + pad2(minutes) + 'm ' + pad2(seconds) + 's';
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let negative: boolean = false;
  let i: number = 0;
  if (text.charAt(0) === '-') {
    negative = true;
    i = 1;
    if (i >= text.length) {
      return NaN;
    }
  }

  let total: number = 0;
  let partCount: number = 0;

  while (i < text.length) {
    const digitStart: number = i;
    while (i < text.length) {
      const code: number = text.charCodeAt(i);
      if (code < 48 || code > 57) {
        break;
      }
      i++;
    }

    if (i === digitStart) {
      return NaN;
    }

    let value: number = 0;
    for (let j: number = digitStart; j < i; j++) {
      value = value * 10 + (text.charCodeAt(j) - 48);
    }

    if (i >= text.length) {
      return NaN;
    }

    const unit: string = text.charAt(i);
    if (unit !== 'h' && unit !== 'm' && unit !== 's') {
      return NaN;
    }
    i++;

    if (unit === 'h') {
      total += value * 3600;
    } else if (unit === 'm') {
      total += value * 60;
    } else {
      total += value;
    }
    partCount++;

    if (i < text.length) {
      if (text.charAt(i) !== ' ') {
        return NaN;
      }
      i++;
      if (i >= text.length) {
        return NaN;
      }
      const nextCode: number = text.charCodeAt(i);
      if (nextCode < 48 || nextCode > 57) {
        return NaN;
      }
    }
  }

  if (partCount === 0) {
    return NaN;
  }

  return negative ? -total : total;
}

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

type JsonValue = Object | null | undefined;
type JsonObject = Record<string, JsonValue>;

function isJsonObject(value: JsonValue): boolean {
  return value !== null && value !== undefined && typeof value === 'object' && !Array.isArray(value);
}

function getField(obj: JsonObject, name: string): JsonValue {
  const value: JsonValue = obj[name];
  if (value === undefined || value === null) {
    return undefined;
  }
  return value;
}

function makeError(path: string, message: string): FieldError {
  return { path: path, message: message };
}

function fail(errors: FieldError[]): ParseResult {
  return { order: undefined, errors: errors };
}

function success(order: Order): ParseResult {
  return { order: order, errors: [] };
}

export function parseOrder(text: string): ParseResult {
  let parsedValue: Object | null;
  try {
    parsedValue = JSON.parse(text);
  } catch (e) {
    return fail([makeError('', 'invalid JSON')]);
  }

  if (!isJsonObject(parsedValue)) {
    return fail([makeError('', 'expected an object')]);
  }

  const parsed: JsonObject = parsedValue as JsonObject;
  const errors: FieldError[] = [];

  // id
  let idValue: string = '';
  const rawId: JsonValue = getField(parsed, 'id');
  if (rawId === undefined) {
    errors.push(makeError('id', 'required'));
  } else if (typeof rawId !== 'string') {
    errors.push(makeError('id', 'expected a string'));
  } else if ((rawId as string) === '') {
    errors.push(makeError('id', 'must not be empty'));
  } else {
    idValue = rawId as string;
  }

  // status
  let statusValue: OrderStatus = OrderStatus.Draft;
  const rawStatus: JsonValue = getField(parsed, 'status');
  if (rawStatus !== undefined) {
    if (typeof rawStatus === 'string') {
      const statusText: string = rawStatus as string;
      if (statusText === 'draft') {
        statusValue = OrderStatus.Draft;
      } else if (statusText === 'paid') {
        statusValue = OrderStatus.Paid;
      } else if (statusText === 'shipped') {
        statusValue = OrderStatus.Shipped;
      } else {
        errors.push(makeError('status', 'expected one of draft, paid, shipped'));
      }
    } else {
      errors.push(makeError('status', 'expected one of draft, paid, shipped'));
    }
  }

  // lines
  const lines: OrderLine[] = [];
  const rawLines: JsonValue = getField(parsed, 'lines');
  if (rawLines === undefined) {
    errors.push(makeError('lines', 'required'));
  } else if (!Array.isArray(rawLines)) {
    errors.push(makeError('lines', 'expected an array'));
  } else {
    const lineArray: JsonValue[] = rawLines as JsonValue[];
    if (lineArray.length === 0) {
      errors.push(makeError('lines', 'must not be empty'));
    } else {
      for (let i = 0; i < lineArray.length; i++) {
        const element: JsonValue = lineArray[i];
        const basePath: string = 'lines[' + i.toString() + ']';
        if (!isJsonObject(element)) {
          errors.push(makeError(basePath, 'expected an object'));
          continue;
        }
        const lineObj: JsonObject = element as JsonObject;
        const errorsBeforeLine: number = errors.length;

        // sku
        let skuValue: string = '';
        const rawSku: JsonValue = getField(lineObj, 'sku');
        if (rawSku === undefined) {
          errors.push(makeError(basePath + '.sku', 'required'));
        } else if (typeof rawSku !== 'string') {
          errors.push(makeError(basePath + '.sku', 'expected a string'));
        } else if ((rawSku as string) === '') {
          errors.push(makeError(basePath + '.sku', 'must not be empty'));
        } else {
          skuValue = rawSku as string;
        }

        // quantity
        let quantityValue: number = 0;
        const rawQuantity: JsonValue = getField(lineObj, 'quantity');
        if (rawQuantity === undefined) {
          errors.push(makeError(basePath + '.quantity', 'required'));
        } else if (typeof rawQuantity !== 'number') {
          errors.push(makeError(basePath + '.quantity', 'expected a number'));
        } else {
          const quantityNumber: number = rawQuantity as number;
          if (!Number.isInteger(quantityNumber) || quantityNumber < 1) {
            errors.push(makeError(basePath + '.quantity', 'must be a whole number of 1 or more'));
          } else {
            quantityValue = quantityNumber;
          }
        }

        // unitPrice
        let unitPriceValue: number = 0;
        const rawUnitPrice: JsonValue = getField(lineObj, 'unitPrice');
        if (rawUnitPrice === undefined) {
          errors.push(makeError(basePath + '.unitPrice', 'required'));
        } else if (typeof rawUnitPrice !== 'number') {
          errors.push(makeError(basePath + '.unitPrice', 'expected a number'));
        } else {
          const unitPriceNumber: number = rawUnitPrice as number;
          if (unitPriceNumber < 0) {
            errors.push(makeError(basePath + '.unitPrice', 'must be 0 or more'));
          } else {
            unitPriceValue = unitPriceNumber;
          }
        }

        // unknown fields of the line
        const lineKeys: string[] = Object.keys(lineObj);
        for (let k = 0; k < lineKeys.length; k++) {
          const key: string = lineKeys[k];
          if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
            errors.push(makeError(basePath + '.' + key, 'unknown field'));
          }
        }

        if (errors.length === errorsBeforeLine) {
          lines.push(new OrderLine(skuValue, quantityValue, unitPriceValue));
        }
      }
    }
  }

  // unknown fields of the order
  const orderKeys: string[] = Object.keys(parsed);
  for (let k = 0; k < orderKeys.length; k++) {
    const key: string = orderKeys[k];
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push(makeError(key, 'unknown field'));
    }
  }

  if (errors.length > 0) {
    return fail(errors);
  }

  const order: Order = {
    id: idValue,
    status: statusValue,
    lines: lines
  };
  return success(order);
}

