function pad2(value: number): string {
  return value < 10 ? "0" + value.toString() : value.toString();
}

export function formatDuration(totalSeconds: number): string {
  const negative: boolean = totalSeconds < 0;
  const abs: number = Math.abs(totalSeconds);
  const hours: number = Math.floor(abs / 3600);
  const minutes: number = Math.floor((abs % 3600) / 60);
  const seconds: number = abs % 60;

  let result: string;
  if (hours > 0) {
    result = hours.toString() + "h " + pad2(minutes) + "m " + pad2(seconds) + "s";
  } else if (minutes > 0) {
    result = minutes.toString() + "m " + pad2(seconds) + "s";
  } else {
    result = seconds.toString() + "s";
  }

  return negative ? "-" + result : result;
}

function isDigitChar(c: string): boolean {
  if (c.length !== 1) {
    return false;
  }
  const code: number = c.charCodeAt(0);
  return code >= 48 && code <= 57;
}

export function parseDuration(text: string): number {
  if (text.length === 0) {
    return NaN;
  }

  let negative: boolean = false;
  let i: number = 0;

  if (text.charAt(0) === "-") {
    negative = true;
    i = 1;
    if (i >= text.length) {
      return NaN;
    }
  }

  let total: number = 0;
  let parts: number = 0;

  while (i < text.length) {
    const digitStart: number = i;
    while (i < text.length && isDigitChar(text.charAt(i))) {
      i++;
    }

    if (i === digitStart) {
      return NaN;
    }

    const digits: string = text.substring(digitStart, i);

    if (i >= text.length) {
      return NaN;
    }

    const unit: string = text.charAt(i);
    if (unit !== "h" && unit !== "m" && unit !== "s") {
      return NaN;
    }
    i++;

    let value: number = 0;
    for (let j: number = 0; j < digits.length; j++) {
      value = value * 10 + (digits.charCodeAt(j) - 48);
    }

    if (unit === "h") {
      total += value * 3600;
    } else if (unit === "m") {
      total += value * 60;
    } else {
      total += value;
    }

    parts++;

    if (i < text.length) {
      if (text.charAt(i) !== " ") {
        return NaN;
      }
      i++;
      if (i >= text.length) {
        return NaN;
      }
    }
  }

  if (parts === 0) {
    return NaN;
  }

  if (negative && total !== 0) {
    return -total;
  }
  return total;
}

