/*
 * solution.ets
 *
 * Self-contained order parser / validator.
 * No imports: JSON is parsed by a small hand-written recursive-descent parser.
 */

export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

/* ------------------------------------------------------------------ */
/* Minimal JSON value model                                            */
/* ------------------------------------------------------------------ */

class JsonValue {
}

class JsonNull extends JsonValue {
}

class JsonBool extends JsonValue {
  value: boolean;

  constructor(value: boolean) {
    super();
    this.value = value;
  }
}

class JsonNumber extends JsonValue {
  value: number;

  constructor(value: number) {
    super();
    this.value = value;
  }
}

class JsonString extends JsonValue {
  value: string;

  constructor(value: string) {
    super();
    this.value = value;
  }
}

class JsonArray extends JsonValue {
  items: JsonValue[] = [];

  constructor() {
    super();
  }
}

class JsonObject extends JsonValue {
  keys: string[] = [];
  values: JsonValue[] = [];

  constructor() {
    super();
  }

  add(key: string, value: JsonValue): void {
    this.keys.push(key);
    this.values.push(value);
  }

  get(key: string): JsonValue | undefined {
    const idx = this.keys.indexOf(key);
    if (idx < 0) {
      return undefined;
    }
    return this.values[idx];
  }
}

/* ------------------------------------------------------------------ */
/* JSON parser                                                         */
/* ------------------------------------------------------------------ */

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9';
}

function hexDigit(c: string): number {
  const code = c.charCodeAt(0);
  if (code >= 48 && code <= 57) {
    return code - 48;
  }
  if (code >= 97 && code <= 102) {
    return code - 87;
  }
  if (code >= 65 && code <= 70) {
    return code - 55;
  }
  return -1;
}

class JsonParser {
  private s: string;
  private i: number = 0;

  constructor(s: string) {
    this.s = s;
  }

  parse(): JsonValue {
    this.skipWs();
    const v = this.parseValue();
    this.skipWs();
    if (this.i < this.s.length) {
      throw new Error('trailing characters');
    }
    return v;
  }

  private skipWs(): void {
    while (this.i < this.s.length) {
      const c = this.s.charAt(this.i);
      if (c === ' ' || c === '\t' || c === '\n' || c === '\r') {
        this.i = this.i + 1;
      } else {
        break;
      }
    }
  }

  private expectWord(word: string): void {
    if (this.i + word.length > this.s.length) {
      throw new Error('unexpected end of input');
    }
    if (this.s.substring(this.i, this.i + word.length) !== word) {
      throw new Error('unexpected token');
    }
    this.i = this.i + word.length;
  }

  private parseValue(): JsonValue {
    if (this.i >= this.s.length) {
      throw new Error('unexpected end of input');
    }
    const c = this.s.charAt(this.i);
    if (c === '{') {
      return this.parseObject();
    }
    if (c === '[') {
      return this.parseArray();
    }
    if (c === '"') {
      return new JsonString(this.parseString());
    }
    if (c === 't') {
      this.expectWord('true');
      return new JsonBool(true);
    }
    if (c === 'f') {
      this.expectWord('false');
      return new JsonBool(false);
    }
    if (c === 'n') {
      this.expectWord('null');
      return new JsonNull();
    }
    if (c === '-' || isDigit(c)) {
      return this.parseNumber();
    }
    throw new Error('unexpected character');
  }

  private parseObject(): JsonValue {
    this.i = this.i + 1; // '{'
    const obj = new JsonObject();
    this.skipWs();
    if (this.i < this.s.length && this.s.charAt(this.i) === '}') {
      this.i = this.i + 1;
      return obj;
    }
    while (true) {
      this.skipWs();
      if (this.i >= this.s.length || this.s.charAt(this.i) !== '"') {
        throw new Error('expected a key');
      }
      const key = this.parseString();
      this.skipWs();
      if (this.i >= this.s.length || this.s.charAt(this.i) !== ':') {
        throw new Error('expected a colon');
      }
      this.i = this.i + 1;
      this.skipWs();
      const val = this.parseValue();
      obj.add(key, val);
      this.skipWs();
      if (this.i >= this.s.length) {
        throw new Error('unexpected end of input');
      }
      const c = this.s.charAt(this.i);
      if (c === ',') {
        this.i = this.i + 1;
        continue;
      }
      if (c === '}') {
        this.i = this.i + 1;
        return obj;
      }
      throw new Error('expected , or }');
    }
  }

  private parseArray(): JsonValue {
    this.i = this.i + 1; // '['
    const arr = new JsonArray();
    this.skipWs();
    if (this.i < this.s.length && this.s.charAt(this.i) === ']') {
      this.i = this.i + 1;
      return arr;
    }
    while (true) {
      this.skipWs();
      const v = this.parseValue();
      arr.items.push(v);
      this.skipWs();
      if (this.i >= this.s.length) {
        throw new Error('unexpected end of input');
      }
      const c = this.s.charAt(this.i);
      if (c === ',') {
        this.i = this.i + 1;
        continue;
      }
      if (c === ']') {
        this.i = this.i + 1;
        return arr;
      }
      throw new Error('expected , or ]');
    }
  }

  private parseString(): string {
    // current character is '"'
    this.i = this.i + 1;
    let out = '';
    while (true) {
      if (this.i >= this.s.length) {
        throw new Error('unterminated string');
      }
      const c = this.s.charAt(this.i);
      if (c === '"') {
        this.i = this.i + 1;
        return out;
      }
      if (c === '\\') {
        this.i = this.i + 1;
        if (this.i >= this.s.length) {
          throw new Error('bad escape');
        }
        const e = this.s.charAt(this.i);
        if (e === '"') {
          out = out + '"';
          this.i = this.i + 1;
        } else if (e === '\\') {
          out = out + '\\';
          this.i = this.i + 1;
        } else if (e === '/') {
          out = out + '/';
          this.i = this.i + 1;
        } else if (e === 'b') {
          out = out + '\b';
          this.i = this.i + 1;
        } else if (e === 'f') {
          out = out + '\f';
          this.i = this.i + 1;
        } else if (e === 'n') {
          out = out + '\n';
          this.i = this.i + 1;
        } else if (e === 'r') {
          out = out + '\r';
          this.i = this.i + 1;
        } else if (e === 't') {
          out = out + '\t';
          this.i = this.i + 1;
        } else if (e === 'u') {
          this.i = this.i + 1;
          if (this.i + 4 > this.s.length) {
            throw new Error('bad unicode escape');
          }
          let code = 0;
          for (let k = 0; k < 4; k++) {
            const hv = hexDigit(this.s.charAt(this.i + k));
            if (hv < 0) {
              throw new Error('bad unicode escape');
            }
            code = code * 16 + hv;
          }
          out = out + String.fromCharCode(code);
          this.i = this.i + 4;
        } else {
          throw new Error('bad escape');
        }
      } else if (c.charCodeAt(0) < 0x20) {
        throw new Error('control character in string');
      } else {
        out = out + c;
        this.i = this.i + 1;
      }
    }
  }

  private parseNumber(): JsonValue {
    const start = this.i;
    if (this.i < this.s.length && this.s.charAt(this.i) === '-') {
      this.i = this.i + 1;
    }
    if (this.i >= this.s.length) {
      throw new Error('bad number');
    }
    const first = this.s.charAt(this.i);
    if (first === '0') {
      this.i = this.i + 1;
    } else if (first >= '1' && first <= '9') {
      while (this.i < this.s.length && isDigit(this.s.charAt(this.i))) {
        this.i = this.i + 1;
      }
    } else {
      throw new Error('bad number');
    }
    if (this.i < this.s.length && this.s.charAt(this.i) === '.') {
      this.i = this.i + 1;
      if (this.i >= this.s.length || !isDigit(this.s.charAt(this.i))) {
        throw new Error('bad number');
      }
      while (this.i < this.s.length && isDigit(this.s.charAt(this.i))) {
        this.i = this.i + 1;
      }
    }
    if (this.i < this.s.length) {
      const ec = this.s.charAt(this.i);
      if (ec === 'e' || ec === 'E') {
        this.i = this.i + 1;
        if (this.i < this.s.length) {
          const sc = this.s.charAt(this.i);
          if (sc === '+' || sc === '-') {
            this.i = this.i + 1;
          }
        }
        if (this.i >= this.s.length || !isDigit(this.s.charAt(this.i))) {
          throw new Error('bad number');
        }
        while (this.i < this.s.length && isDigit(this.s.charAt(this.i))) {
          this.i = this.i + 1;
        }
      }
    }
    const numText = this.s.substring(start, this.i);
    const n = Number(numText);
    return new JsonNumber(n);
  }
}

/* ------------------------------------------------------------------ */
/* Validation helpers                                                  */
/* ------------------------------------------------------------------ */

function makeFieldError(path: string, message: string): FieldError {
  const e: FieldError = { path: path, message: message };
  return e;
}

function singleError(path: string, message: string): ParseResult {
  const errs: FieldError[] = [];
  errs.push(makeFieldError(path, message));
  const r: ParseResult = { order: undefined, errors: errs };
  return r;
}

function tryParseJson(text: string): JsonValue | undefined {
  try {
    const parser = new JsonParser(text);
    return parser.parse();
  } catch (e) {
    return undefined;
  }
}

/* ------------------------------------------------------------------ */
/* parseOrder                                                          */
/* ------------------------------------------------------------------ */

export function parseOrder(text: string): ParseResult {
  const rootVal = tryParseJson(text);
  if (rootVal === undefined) {
    return singleError('', 'invalid JSON');
  }
  if (!(rootVal instanceof JsonObject)) {
    return singleError('', 'expected an object');
  }
  const obj = rootVal as JsonObject;

  const errors: FieldError[] = [];

  /* ---- id ---- */
  let id = '';
  const idVal = obj.get('id');
  if (idVal === undefined || idVal instanceof JsonNull) {
    errors.push(makeFieldError('id', 'required'));
  } else if (!(idVal instanceof JsonString)) {
    errors.push(makeFieldError('id', 'expected a string'));
  } else {
    const idStr = (idVal as JsonString).value;
    if (idStr === '') {
      errors.push(makeFieldError('id', 'must not be empty'));
    } else {
      id = idStr;
    }
  }

  /* ---- status ---- */
  let status: OrderStatus = OrderStatus.Draft;
  const statusVal = obj.get('status');
  if (statusVal !== undefined && !(statusVal instanceof JsonNull)) {
    let ok = false;
    if (statusVal instanceof JsonString) {
      const sv = (statusVal as JsonString).value;
      if (sv === 'draft') {
        status = OrderStatus.Draft;
        ok = true;
      } else if (sv === 'paid') {
        status = OrderStatus.Paid;
        ok = true;
      } else if (sv === 'shipped') {
        status = OrderStatus.Shipped;
        ok = true;
      }
    }
    if (!ok) {
      errors.push(makeFieldError('status', 'expected one of draft, paid, shipped'));
    }
  }

  /* ---- lines ---- */
  const lines: OrderLine[] = [];
  const linesVal = obj.get('lines');
  if (linesVal === undefined || linesVal instanceof JsonNull) {
    errors.push(makeFieldError('lines', 'required'));
  } else if (!(linesVal instanceof JsonArray)) {
    errors.push(makeFieldError('lines', 'expected an array'));
  } else {
    const arr = linesVal as JsonArray;
    if (arr.items.length === 0) {
      errors.push(makeFieldError('lines', 'must not be empty'));
    } else {
      for (let idx = 0; idx < arr.items.length; idx++) {
        const item = arr.items[idx];
        const p = 'lines[' + idx.toString() + ']';
        if (!(item instanceof JsonObject)) {
          errors.push(makeFieldError(p, 'expected an object'));
          continue;
        }
        const lineObj = item as JsonObject;

        /* sku */
        let sku = '';
        const skuVal = lineObj.get('sku');
        if (skuVal === undefined || skuVal instanceof JsonNull) {
          errors.push(makeFieldError(p + '.sku', 'required'));
        } else if (!(skuVal instanceof JsonString)) {
          errors.push(makeFieldError(p + '.sku', 'expected a string'));
        } else {
          const skuStr = (skuVal as JsonString).value;
          if (skuStr === '') {
            errors.push(makeFieldError(p + '.sku', 'must not be empty'));
          } else {
            sku = skuStr;
          }
        }

        /* quantity */
        let quantity = 0;
        const qtyVal = lineObj.get('quantity');
        if (qtyVal === undefined || qtyVal instanceof JsonNull) {
          errors.push(makeFieldError(p + '.quantity', 'required'));
        } else if (!(qtyVal instanceof JsonNumber)) {
          errors.push(makeFieldError(p + '.quantity', 'expected a number'));
        } else {
          const q = (qtyVal as JsonNumber).value;
          if (!Number.isInteger(q) || q < 1) {
            errors.push(makeFieldError(p + '.quantity', 'must be a whole number of 1 or more'));
          } else {
            quantity = q;
          }
        }

        /* unitPrice */
        let unitPrice = 0;
        const priceVal = lineObj.get('unitPrice');
        if (priceVal === undefined || priceVal instanceof JsonNull) {
          errors.push(makeFieldError(p + '.unitPrice', 'required'));
        } else if (!(priceVal instanceof JsonNumber)) {
          errors.push(makeFieldError(p + '.unitPrice', 'expected a number'));
        } else {
          const up = (priceVal as JsonNumber).value;
          if (up < 0) {
            errors.push(makeFieldError(p + '.unitPrice', 'must be 0 or more'));
          } else {
            unitPrice = up;
          }
        }

        /* unknown fields of this line, in text order */
        for (let k = 0; k < lineObj.keys.length; k++) {
          const key = lineObj.keys[k];
          if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
            errors.push(makeFieldError(p + '.' + key, 'unknown field'));
          }
        }

        lines.push(new OrderLine(sku, quantity, unitPrice));
      }
    }
  }

  /* ---- unknown fields of the order, in text order ---- */
  for (let k = 0; k < obj.keys.length; k++) {
    const key = obj.keys[k];
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      errors.push(makeFieldError(key, 'unknown field'));
    }
  }

  if (errors.length > 0) {
    const bad: ParseResult = { order: undefined, errors: errors };
    return bad;
  }

  const order: Order = { id: id, status: status, lines: lines };
  const good: ParseResult = { order: order, errors: errors };
  return good;
}

class Address {
  id: string;
  label: string;
  street: string;

  constructor(id: string, label: string, street: string) {
    this.id = id;
    this.label = label;
    this.street = street;
  }
}

const ADDRESSES: Address[] = [
  new Address('home', 'Home', '12 Elm Street'),
  new Address('work', 'Work', '400 Harbour Road'),
  new Address('gym', 'Gym', '7 Mill Lane')
];

class AddressesParam {
  currentId: string;

  constructor(currentId: string) {
    this.currentId = currentId;
  }
}

class AddressResult {
  id: string;

  constructor(id: string) {
    this.id = id;
  }
}

@Component
struct AddressRow {
  address: Address = new Address('', '', '');
  isCurrent: boolean = false;
  onSelect: (id: string) => void = () => {};
  @Consume largeText: boolean;

  build() {
    Row() {
      Column() {
        Text(this.address.label)
          .fontSize(this.largeText ? 24 : 16)
          .fontWeight(FontWeight.Medium)
        Text(this.address.street)
          .fontSize(this.largeText ? 24 : 16)
          .fontColor('#666666')
          .margin({ top: 4 })
      }
      .alignItems(HorizontalAlign.Start)
      .layoutWeight(1)

      if (this.isCurrent) {
        Text('Current')
          .fontSize(this.largeText ? 24 : 16)
          .fontColor('#007DFF')
      }
    }
    .width('100%')
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .onClick(() => {
      this.onSelect(this.address.id);
    })
  }
}

@Component
struct AddressListScreen {
  currentId: string = '';
  pathStack: NavPathStack = new NavPathStack();

  build() {
    List() {
      ForEach(ADDRESSES, (item: Address) => {
        ListItem() {
          AddressRow({
            address: item,
            isCurrent: item.id === this.currentId,
            onSelect: (id: string) => {
              this.pathStack.pop(new AddressResult(id));
            }
          })
        }
      }, (item: Address) => item.id)
    }
    .width('100%')
    .height('100%')
    .divider({ strokeWidth: 1, color: '#E5E5E5', startMargin: 16, endMargin: 16 })
  }
}

@Entry
@Component
struct CheckoutPage {
  @Provide largeText: boolean = false;
  @State selectedId: string = 'home';
  pathStack: NavPathStack = new NavPathStack();

  private labelOf(id: string): string {
    for (let i = 0; i < ADDRESSES.length; i++) {
      if (ADDRESSES[i].id === id) {
        return ADDRESSES[i].label;
      }
    }
    return '';
  }

  @Builder
  destBuilder(name: string, param: Object) {
    if (name === 'Addresses') {
      NavDestination() {
        AddressListScreen({
          currentId: (param as AddressesParam).currentId,
          pathStack: this.pathStack
        })
      }
      .title('Addresses')
    }
  }

  build() {
    Navigation(this.pathStack) {
      Column({ space: 16 }) {
        Text('Deliver to: ' + this.labelOf(this.selectedId))
          .fontSize(20)

        Button('Change address')
          .onClick(() => {
            this.pathStack.pushPathByName('Addresses', new AddressesParam(this.selectedId),
              (info: PopInfo) => {
                const res: Object = info.result;
                if (res instanceof AddressResult) {
                  this.selectedId = res.id;
                }
              });
          })

        Row({ space: 12 }) {
          Text('Large text')
            .fontSize(20)
          Toggle({ type: ToggleType.Switch, isOn: this.largeText })
            .onChange((isOn: boolean) => {
              this.largeText = isOn;
            })
        }
        .alignItems(VerticalAlign.Center)
      }
      .width('100%')
      .height('100%')
      .padding(16)
      .alignItems(HorizontalAlign.Start)
    }
    .title('Checkout')
    .titleMode(NavigationTitleMode.Mini)
    .mode(NavigationMode.Stack)
    .navDestination(this.destBuilder)
  }
}

export interface Token {
  kind: string;
  text: string;
  position: number;
}

export class ExpressionError extends Error {
  position: number;

  constructor(message: string, position: number) {
    super(message);
    this.position = position;
  }
}

function isDigit(ch: string): boolean {
  return ch >= '0' && ch <= '9';
}

function isLetter(ch: string): boolean {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

function isNameStart(ch: string): boolean {
  return isLetter(ch) || ch === '_';
}

function isNamePart(ch: string): boolean {
  return isNameStart(ch) || isDigit(ch);
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = [];
  let i = 0;

  while (i < source.length) {
    const ch = source.charAt(i);

    if (ch === ' ') {
      i++;
      continue;
    }

    if (isDigit(ch)) {
      const start = i;
      while (i < source.length && isDigit(source.charAt(i))) {
        i++;
      }
      if (
        i < source.length &&
        source.charAt(i) === '.' &&
        i + 1 < source.length &&
        isDigit(source.charAt(i + 1))
      ) {
        i++;
        while (i < source.length && isDigit(source.charAt(i))) {
          i++;
        }
      }
      tokens.push({
        kind: 'number',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (isNameStart(ch)) {
      const start = i;
      i++;
      while (i < source.length && isNamePart(source.charAt(i))) {
        i++;
      }
      tokens.push({
        kind: 'name',
        text: source.substring(start, i),
        position: start
      });
      continue;
    }

    if (ch === '+' || ch === '-' || ch === '*' || ch === '/' || ch === '%') {
      tokens.push({
        kind: 'operator',
        text: ch,
        position: i
      });
      i++;
      continue;
    }

    if (ch === '(' || ch === ')') {
      tokens.push({
        kind: 'paren',
        text: ch,
        position: i
      });
      i++;
      continue;
    }

    throw new ExpressionError(`Unexpected character '${ch}'`, i);
  }

  return tokens;
}

class ExprNode {
  kind: string;
  position: number;

  constructor(kind: string, position: number) {
    this.kind = kind;
    this.position = position;
  }
}

class NumberNode extends ExprNode {
  value: number;

  constructor(value: number, position: number) {
    super('number', position);
    this.value = value;
  }
}

class NameNode extends ExprNode {
  name: string;

  constructor(name: string, position: number) {
    super('name', position);
    this.name = name;
  }
}

class UnaryNode extends ExprNode {
  child: ExprNode;

  constructor(position: number, child: ExprNode) {
    super('unary', position);
    this.child = child;
  }
}

class BinaryNode extends ExprNode {
  op: string;
  left: ExprNode;
  right: ExprNode;

  constructor(op: string, position: number, left: ExprNode, right: ExprNode) {
    super('binary', position);
    this.op = op;
    this.left = left;
    this.right = right;
  }
}

class Parser {
  private tokens: Token[];
  private index: number = 0;
  private sourceLength: number;

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens;
    this.sourceLength = sourceLength;
  }

  parse(): ExprNode {
    if (this.tokens.length === 0) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }

    const expr = this.parseExpression();

    if (this.index < this.tokens.length) {
      const t = this.tokens[this.index];
      throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
    }

    return expr;
  }

  private peek(): Token | null {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index];
    }
    return null;
  }

  private next(): Token {
    const t = this.tokens[this.index];
    this.index++;
    return t;
  }

  private parseExpression(): ExprNode {
    let left = this.parseTerm();

    while (true) {
      const t = this.peek();
      if (
        t !== null &&
        t.kind === 'operator' &&
        (t.text === '+' || t.text === '-')
      ) {
        this.next();
        const right = this.parseTerm();
        left = new BinaryNode(t.text, t.position, left, right);
      } else {
        break;
      }
    }

    return left;
  }

  private parseTerm(): ExprNode {
    let left = this.parseUnary();

    while (true) {
      const t = this.peek();
      if (
        t !== null &&
        t.kind === 'operator' &&
        (t.text === '*' || t.text === '/' || t.text === '%')
      ) {
        this.next();
        const right = this.parseUnary();
        left = new BinaryNode(t.text, t.position, left, right);
      } else {
        break;
      }
    }

    return left;
  }

  private parseUnary(): ExprNode {
    const t = this.peek();
    if (t !== null && t.kind === 'operator' && t.text === '-') {
      this.next();
      const child = this.parseUnary();
      return new UnaryNode(t.position, child);
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ExprNode {
    const t = this.peek();

    if (t === null) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength);
    }

    if (t.kind === 'number') {
      this.next();
      return new NumberNode(parseFloat(t.text), t.position);
    }

    if (t.kind === 'name') {
      this.next();
      return new NameNode(t.text, t.position);
    }

    if (t.kind === 'paren' && t.text === '(') {
      this.next();
      const inner = this.parseExpression();
      const close = this.peek();

      if (close === null) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength);
      }

      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position);
      }

      this.next();
      return inner;
    }

    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position);
  }
}

function evaluateNode(node: ExprNode, variables: Record<string, number>): number {
  if (node instanceof NumberNode) {
    return node.value;
  }

  if (node instanceof NameNode) {
    if (Object.keys(variables).indexOf(node.name) < 0) {
      throw new ExpressionError(`Unknown variable '${node.name}'`, node.position);
    }
    return variables[node.name];
  }

  if (node instanceof UnaryNode) {
    const value = evaluateNode(node.child, variables);
    return -value;
  }

  if (node instanceof BinaryNode) {
    const left = evaluateNode(node.left, variables);
    const right = evaluateNode(node.right, variables);

    if (node.op === '+') {
      return left + right;
    }
    if (node.op === '-') {
      return left - right;
    }
    if (node.op === '*') {
      return left * right;
    }
    if (node.op === '/') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', node.position);
      }
      return left / right;
    }
    if (node.op === '%') {
      if (right === 0) {
        throw new ExpressionError('Division by zero', node.position);
      }
      return left % right;
    }
  }

  throw new ExpressionError('Unexpected token', node.position);
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens = tokenize(source);
  const parser = new Parser(tokens, source.length);
  const root = parser.parse();
  return evaluateNode(root, variables);
}

