export interface Token {
  kind: string
  text: string
  position: number
}

export class ExpressionError extends Error {
  public position: number

  constructor(message: string, position: number) {
    super(message)
    this.name = 'ExpressionError'
    this.position = position
  }
}

function isDigit(c: string): boolean {
  return c >= '0' && c <= '9'
}

function isNameStart(c: string): boolean {
  return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_'
}

function isNamePart(c: string): boolean {
  return isNameStart(c) || isDigit(c)
}

export function tokenize(source: string): Token[] {
  const tokens: Token[] = []
  let i: number = 0
  while (i < source.length) {
    const c: string = source.charAt(i)
    if (c === ' ') {
      i++
      continue
    }
    if (isDigit(c)) {
      const start: number = i
      while (i < source.length && isDigit(source.charAt(i))) {
        i++
      }
      if (i < source.length && source.charAt(i) === '.' &&
        i + 1 < source.length && isDigit(source.charAt(i + 1))) {
        i++
        while (i < source.length && isDigit(source.charAt(i))) {
          i++
        }
      }
      const t: Token = {
        kind: 'number',
        text: source.substring(start, i),
        position: start
      }
      tokens.push(t)
      continue
    }
    if (isNameStart(c)) {
      const start: number = i
      i++
      while (i < source.length && isNamePart(source.charAt(i))) {
        i++
      }
      const t: Token = {
        kind: 'name',
        text: source.substring(start, i),
        position: start
      }
      tokens.push(t)
      continue
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%') {
      const t: Token = { kind: 'operator', text: c, position: i }
      tokens.push(t)
      i++
      continue
    }
    if (c === '(' || c === ')') {
      const t: Token = { kind: 'paren', text: c, position: i }
      tokens.push(t)
      i++
      continue
    }
    throw new ExpressionError(`Unexpected character '${c}'`, i)
  }
  return tokens
}

abstract class Node {
  abstract evaluate(variables: Record<string, number>): number
}

class NumNode extends Node {
  private value: number

  constructor(value: number) {
    super()
    this.value = value
  }

  evaluate(variables: Record<string, number>): number {
    return this.value
  }
}

class NameNode extends Node {
  private name: string
  private position: number

  constructor(name: string, position: number) {
    super()
    this.name = name
    this.position = position
  }

  evaluate(variables: Record<string, number>): number {
    const keys: string[] = Object.keys(variables)
    if (keys.indexOf(this.name) < 0) {
      throw new ExpressionError(`Unknown variable '${this.name}'`, this.position)
    }
    return variables[this.name]
  }
}

class NegNode extends Node {
  private child: Node

  constructor(child: Node) {
    super()
    this.child = child
  }

  evaluate(variables: Record<string, number>): number {
    return -this.child.evaluate(variables)
  }
}

class BinNode extends Node {
  private op: string
  private left: Node
  private right: Node
  private position: number

  constructor(op: string, left: Node, right: Node, position: number) {
    super()
    this.op = op
    this.left = left
    this.right = right
    this.position = position
  }

  evaluate(variables: Record<string, number>): number {
    const l: number = this.left.evaluate(variables)
    const r: number = this.right.evaluate(variables)
    if (r === 0 && (this.op === '/' || this.op === '%')) {
      throw new ExpressionError('Division by zero', this.position)
    }
    if (this.op === '+') {
      return l + r
    }
    if (this.op === '-') {
      return l - r
    }
    if (this.op === '*') {
      return l * r
    }
    if (this.op === '/') {
      return l / r
    }
    return l % r
  }
}

class Parser {
  private tokens: Token[]
  private index: number
  private sourceLength: number

  constructor(tokens: Token[], sourceLength: number) {
    this.tokens = tokens
    this.index = 0
    this.sourceLength = sourceLength
  }

  private peek(): Token | undefined {
    if (this.index < this.tokens.length) {
      return this.tokens[this.index]
    }
    return undefined
  }

  parse(): Node {
    const node: Node = this.parseExpr()
    const t: Token | undefined = this.peek()
    if (t !== undefined) {
      throw new ExpressionError(`Unexpected token '${t.text}'`, t.position)
    }
    return node
  }

  private parseExpr(): Node {
    let node: Node = this.parseTerm()
    while (true) {
      const t: Token | undefined = this.peek()
      if (t !== undefined && t.kind === 'operator' && (t.text === '+' || t.text === '-')) {
        this.index++
        const right: Node = this.parseTerm()
        node = new BinNode(t.text, node, right, t.position)
      } else {
        return node
      }
    }
  }

  private parseTerm(): Node {
    let node: Node = this.parseUnary()
    while (true) {
      const t: Token | undefined = this.peek()
      if (t !== undefined && t.kind === 'operator' &&
        (t.text === '*' || t.text === '/' || t.text === '%')) {
        this.index++
        const right: Node = this.parseUnary()
        node = new BinNode(t.text, node, right, t.position)
      } else {
        return node
      }
    }
  }

  private parseUnary(): Node {
    const t: Token | undefined = this.peek()
    if (t !== undefined && t.kind === 'operator' && t.text === '-') {
      this.index++
      return new NegNode(this.parseUnary())
    }
    return this.parsePrimary()
  }

  private parsePrimary(): Node {
    const t: Token | undefined = this.peek()
    if (t === undefined) {
      throw new ExpressionError('Unexpected end of expression', this.sourceLength)
    }
    if (t.kind === 'number') {
      this.index++
      return new NumNode(Number(t.text))
    }
    if (t.kind === 'name') {
      this.index++
      return new NameNode(t.text, t.position)
    }
    if (t.kind === 'paren' && t.text === '(') {
      this.index++
      const inner: Node = this.parseExpr()
      const close: Token | undefined = this.peek()
      if (close === undefined) {
        throw new ExpressionError('Unexpected end of expression', this.sourceLength)
      }
      if (close.kind !== 'paren' || close.text !== ')') {
        throw new ExpressionError(`Unexpected token '${close.text}'`, close.position)
      }
      this.index++
      return inner
    }
    throw new ExpressionError(`Unexpected token '${t.text}'`, t.position)
  }
}

export function evaluate(source: string, variables: Record<string, number>): number {
  const tokens: Token[] = tokenize(source)
  const parser: Parser = new Parser(tokens, source.length)
  const node: Node = parser.parse()
  return node.evaluate(variables)
}

export class MissingDependencyError extends Error {
  public readonly task: string;
  public readonly dependency: string;

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`);
    this.task = task;
    this.dependency = dependency;
  }
}

export class CycleError extends Error {
  public readonly path: string[];

  constructor(path: string[]) {
    super('Dependency cycle: ' + path.join(' -> '));
    this.path = path;
  }
}

export class BuildPlan {
  private names: string[] = [];
  private nameSet: Set<string> = new Set<string>();
  private deps: Map<string, string[]> = new Map<string, string[]>();
  private orderList: string[] = [];

  constructor(spec: Record<string, string[]>) {
    const names: string[] = Object.keys(spec);
    const nameSet: Set<string> = new Set<string>();
    for (const n of names) {
      nameSet.add(n);
    }

    const deps: Map<string, string[]> = new Map<string, string[]>();
    for (const task of names) {
      const list: string[] = spec[task] ?? [];
      for (const d of list) {
        if (!nameSet.has(d)) {
          throw new MissingDependencyError(task, d);
        }
      }
      deps.set(task, list);
    }

    this.names = names;
    this.nameSet = nameSet;
    this.deps = deps;

    const placed: Set<string> = new Set<string>();
    const stack: string[] = [];
    const order: string[] = [];
    for (const task of names) {
      this.place(task, stack, placed, order);
    }
    this.orderList = order;
  }

  private place(task: string, stack: string[], placed: Set<string>, order: string[]): void {
    if (placed.has(task)) {
      return;
    }
    const idx: number = stack.indexOf(task);
    if (idx >= 0) {
      const cyclePath: string[] = stack.slice(idx);
      cyclePath.push(task);
      throw new CycleError(cyclePath);
    }
    stack.push(task);
    const list: string[] = this.deps.get(task) ?? [];
    for (const d of list) {
      this.place(d, stack, placed, order);
    }
    stack.pop();
    placed.add(task);
    order.push(task);
  }

  order(): string[] {
    return this.orderList.slice();
  }

  layers(): string[][] {
    if (this.names.length === 0) {
      return [];
    }
    const depth: Map<string, number> = new Map<string, number>();
    const depths: number[] = [];
    let max: number = -1;
    for (const t of this.names) {
      const d: number = this.computeDepth(t, depth);
      depths.push(d);
      if (d > max) {
        max = d;
      }
    }
    const result: string[][] = [];
    for (let i: number = 0; i <= max; i++) {
      result.push([]);
    }
    for (let i: number = 0; i < this.names.length; i++) {
      result[depths[i]].push(this.names[i]);
    }
    return result;
  }

  private computeDepth(task: string, depth: Map<string, number>): number {
    const cached: number | undefined = depth.get(task);
    if (cached !== undefined) {
      return cached;
    }
    let d: number = 0;
    const list: string[] = this.deps.get(task) ?? [];
    for (const dep of list) {
      const dd: number = this.computeDepth(dep, depth) + 1;
      if (dd > d) {
        d = dd;
      }
    }
    depth.set(task, d);
    return d;
  }

  dependentsOf(name: string): string[] {
    if (!this.nameSet.has(name)) {
      return [];
    }
    const cache: Map<string, boolean> = new Map<string, boolean>();
    const result: string[] = [];
    for (const t of this.orderList) {
      if (t !== name && this.dependsOn(t, name, cache)) {
        result.push(t);
      }
    }
    return result;
  }

  private dependsOn(task: string, target: string, cache: Map<string, boolean>): boolean {
    if (task === target) {
      return true;
    }
    const cached: boolean | undefined = cache.get(task);
    if (cached !== undefined) {
      return cached;
    }
    let r: boolean = false;
    const list: string[] = this.deps.get(task) ?? [];
    for (const d of list) {
      if (this.dependsOn(d, target, cache)) {
        r = true;
        break;
      }
    }
    cache.set(task, r);
    return r;
  }
}

import { app } from '@ohos.app.abilityContext';
