// Global dark mode state using app-level context
const darkModeContext = app.createApplicationContext();

// Custom storage for dark mode setting
const darkModeStorage = {
  _value: false,
  _listeners: new Set<() => void>(),

  get value(): boolean {
    return this._value;
  },

  set value(val: boolean) {
    if (this._value !== val) {
      this._value = val;
      this._listeners.forEach(listener => listener());
    }
  },

  subscribe(listener: () => void): void {
    this._listeners.add(listener);
  },

  unsubscribe(listener: () => void): void {
    this._listeners.delete(listener);
  }
};

// Initialize dark mode from system settings if available
try {
  const systemDarkMode = darkModeContext.isSystemDarkMode();
  darkModeStorage.value = systemDarkMode;
} catch (e) {
  // Fallback to default (off)
  darkModeStorage.value = false;
}

