interface LogEntry {
  id: number
  message: string
  level: string
}

@Entry
@Component
struct LogPage {
  @State entries: LogEntry[] = []
  @State isRefreshing: boolean = false

  aboutToAppear(): void {
    this.entries = this.generateEntries(1, 3000)
  }

  generateEntries(startId: number, endId: number): LogEntry[] {
    const result: LogEntry[] = []
    for (let i = startId; i <= endId; i++) {
      let level: string
      if (i % 50 === 0) {
        level = 'error'
      } else if (i % 10 === 0) {
        level = 'warning'
      } else {
        level = 'info'
      }
      result.push({
        id: i,
        message: `Event ${i}`,
        level: level
      })
    }
    return result
  }

  @Builder
  LogEntryRow(entry: LogEntry) {
    Row() {
      Text(entry.message)
        .fontSize(16)
        .margin({ right: 10 })
      Text(entry.level)
        .fontSize(14)
        .fontColor(this.getLevelColor(entry.level))
    }
    .padding(10)
    .backgroundColor(Color.White)
    .borderBottom({ width: 1, color: Color.Grey })
  }

  getLevelColor(level: string): string {
    switch (level) {
      case 'error':
        return '#D32F2F'
      case 'warning':
        return '#F57C00'
      case 'info':
        return '#757575'
      default:
        return '#757575'
    }
  }

  build() {
    Column() {
      Text(`${this.entries.length} entries`)
        .fontSize(18)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 20, bottom: 10 })

      List({ space: 0 }) {
        LazyForEach(this.entries.reverse(), (entry: LogEntry) => {
          this.LogEntryRow(entry)
        }, (entry: LogEntry) => entry.id)
      }
      .width('100%')
      .height('100%')
      .scrollBar(BarState.Off)
      .onRefresh(() => {
        this.isRefreshing = true
        setTimeout(() => {
          const startId = this.entries.length > 0 
            ? this.entries[0].id + 1 
            : 3001
          const newEntries = this.generateEntries(startId, startId + 4)
          this.entries = newEntries.concat(this.entries)
          this.isRefreshing = false
        }, 1000)
      })
      .refreshStatus((status: RefreshStatus) => {
        if (status === RefreshStatus.Refreshing) {
          this.isRefreshing = true
        } else {
          this.isRefreshing = false
        }
      })
    }
    .width('100%')
    .height('100%')
    .backgroundColor(Color.White)
  }
}

