@Component
struct SignInPage {
  @State email: string = '';
  @State password: string = '';
  @State emailError: string = '';
  @State passwordError: string = '';

  aboutToAppear(): void {
    this.validateEmail();
    this.validatePassword();
  }

  validateEmail(): void {
    if (this.email === '') {
      this.emailError = '';
      return;
    }

    const emailRegex = /^[^@]+@[^@]+\.[^@]+$/;
    if (!emailRegex.test(this.email)) {
      this.emailError = 'Enter a valid email address';
    } else {
      this.emailError = '';
    }
  }

  validatePassword(): void {
    if (this.password === '') {
      this.passwordError = '';
      return;
    }

    if (this.password.length < 8) {
      this.passwordError = 'Password must be at least 8 characters';
    } else {
      this.passwordError = '';
    }
  }

  build(): void {
    Column() {
      Text('Sign In')
        .fontSize(24)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 40, bottom: 30 })

      Column() {
        TextInput({
          text: this.email,
          placeholder: 'Email'
        })
          .type(InputType.Email)
          .onChange((value: string) => {
            this.email = value;
            this.validateEmail();
          })
          .margin({ bottom: 10 })

        if (this.emailError !== '') {
          Text(this.emailError)
            .fontSize(12)
