class LogEntry {
  id: number
  message: string
  level: 'info' | 'warning' | 'error'

  constructor(id: number) {
    this.id = id
    this.message = `Event ${id}`
    if (id % 50 === 0) {
      this.level = 'error'
    } else if (id % 10 === 0) {
      this.level = 'warning'
    } else {
      this.level = 'info'
    }
  }
}

@Component
struct LogEntryRow {
  entry: LogEntry

  build() {
    let levelColor: string
    switch (this.entry.level) {
      case 'error':
        levelColor = '#D32F2F'
        break
      case 'warning':
        levelColor = '#F57C00'
        break
      case 'info':
        levelColor = '#757575'
        break
      default:
        levelColor = '#757575'
    }

    Row({ space: 10 }) {
      Text(this.entry.message)
        .fontSize(16)
      Text(this.entry.level)
        .fontSize(14)
        .fontColor(levelColor)
    }
    .width('100%')
  }
}

@Entry
@Component
struct Solution {
  @State entries: LogEntry[] = []
  @State totalEntries: number = 0

  aboutToAppear() {
    // Create 3000 entries
    const initialEntries: LogEntry[] = []
    for (let i = 1; i <= 3000; i++) {
      initialEntries.push(new LogEntry(i))
    }
    this.entries = initialEntries
    this.totalEntries = 3000
  }

  build() {
    Column() {
      Text(`${this.totalEntries} entries`)
        .fontSize(20)
        .margin({ top: 10, bottom: 10 })

      List({ scroller: new Scroller() }) {
        ForEach(this.entries, (entry: LogEntry) => {
          ListItem() {
            LogEntryRow({ entry: entry })
          }
        }, entry => entry.id)
      }
      .width('100%')
      .height('100%')
      .refresh(() => {
        RefreshOptions({
          refreshing: false,
          promptText: 'Loading...',
          builder: () => {
            Text('Loading...')
              .fontSize(16)
          }
        })
      })
      .onRefresh((callback: () => void) => {
        // Simulate network delay
        setTimeout(() => {
          const newEntries: LogEntry[] = []
          const startId = this.totalEntries + 1
          for (let i = 0; i < 5; i++) {
            newEntries.push(new LogEntry(startId + i))
          }
          this.entries = [...newEntries, ...this.entries]
          this.totalEntries += 5
          callback()
        }, 1000)
      })
    }
    .width('100%')
    .height('100%')
    .padding({ left: 10, right: 10 })
  }
}

