export enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped'
}

export class OrderLine {
  sku: string;
  quantity: number;
  unitPrice: number;

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku;
    this.quantity = quantity;
    this.unitPrice = unitPrice;
  }

  total(): number {
    return this.quantity * this.unitPrice;
  }
}

export interface Order {
  id: string;
  status: OrderStatus;
  lines: OrderLine[];
}

export interface FieldError {
  path: string;
  message: string;
}

export interface ParseResult {
  order: Order | undefined;
  errors: FieldError[];
}

type JsonValue = Object | null | undefined;

function addError(errors: FieldError[], path: string, message: string): void {
  const e: FieldError = { path: path, message: message };
  errors.push(e);
}

function singleError(path: string, message: string): ParseResult {
  const list: FieldError[] = [];
  addError(list, path, message);
  const res: ParseResult = { order: undefined, errors: list };
  return res;
}

function getField(obj: Record<string, JsonValue>, name: string): JsonValue {
  return obj[name];
}

function checkLine(item: JsonValue, index: number, errors: FieldError[]): OrderLine | undefined {
  const basePath: string = 'lines[' + index.toString() + ']';
  if (item === null || item === undefined) {
    addError(errors, basePath, 'expected an object');
    return undefined;
  }
  if (Array.isArray(item) || typeof item !== 'object') {
    addError(errors, basePath, 'expected an object');
    return undefined;
  }
  const rec: Record<string, JsonValue> = item as Record<string, JsonValue>;

  let sku: string | undefined = undefined;
  const skuPath: string = basePath + '.sku';
  const sv: JsonValue = getField(rec, 'sku');
  if (sv === undefined || sv === null) {
    addError(errors, skuPath, 'required');
  } else if (typeof sv !== 'string') {
    addError(errors, skuPath, 'expected a string');
  } else if ((sv as string) === '') {
    addError(errors, skuPath, 'must not be empty');
  } else {
    sku = sv as string;
  }

  let quantity: number | undefined = undefined;
  const quantityPath: string = basePath + '.quantity';
  const qv: JsonValue = getField(rec, 'quantity');
  if (qv === undefined || qv === null) {
    addError(errors, quantityPath, 'required');
  } else if (typeof qv !== 'number') {
    addError(errors, quantityPath, 'expected a number');
  } else {
    const q: number = qv as number;
    if (q < 1 || q % 1 !== 0) {
      addError(errors, quantityPath, 'must be a whole number of 1 or more');
    } else {
      quantity = q;
    }
  }

  let unitPrice: number | undefined = undefined;
  const pricePath: string = basePath + '.unitPrice';
  const pv: JsonValue = getField(rec, 'unitPrice');
  if (pv === undefined || pv === null) {
    addError(errors, pricePath, 'required');
  } else if (typeof pv !== 'number') {
    addError(errors, pricePath, 'expected a number');
  } else {
    const p: number = pv as number;
    if (p < 0) {
      addError(errors, pricePath, 'must be 0 or more');
    } else {
      unitPrice = p;
    }
  }

  const lineKeys: string[] = Object.keys(rec);
  for (const key of lineKeys) {
    if (key !== 'sku' && key !== 'quantity' && key !== 'unitPrice') {
      addError(errors, basePath + '.' + key, 'unknown field');
    }
  }

  if (sku !== undefined && quantity !== undefined && unitPrice !== undefined) {
    return new OrderLine(sku, quantity, unitPrice);
  }
  return undefined;
}

export function parseOrder(text: string): ParseResult {
  const errors: FieldError[] = [];

  let parsed: JsonValue = undefined;
  let validJson: boolean = false;
  try {
    parsed = JSON.parse(text) as Object | null;
    validJson = true;
  } catch (e) {
    validJson = false;
  }
  if (!validJson) {
    return singleError('', 'invalid JSON');
  }
  if (parsed === undefined || parsed === null) {
    return singleError('', 'expected an object');
  }
  if (typeof parsed !== 'object' || Array.isArray(parsed)) {
    return singleError('', 'expected an object');
  }

  const obj: Record<string, JsonValue> = parsed as Record<string, JsonValue>;

  let idValue: string | undefined = undefined;
  const iv: JsonValue = getField(obj, 'id');
  if (iv === undefined || iv === null) {
    addError(errors, 'id', 'required');
  } else if (typeof iv !== 'string') {
    addError(errors, 'id', 'expected a string');
  } else if ((iv as string) === '') {
    addError(errors, 'id', 'must not be empty');
  } else {
    idValue = iv as string;
  }

  let statusValue: OrderStatus = OrderStatus.Draft;
  const sv: JsonValue = getField(obj, 'status');
  if (sv !== undefined && sv !== null) {
    let matched: boolean = false;
    if (typeof sv === 'string') {
      const s: string = sv as string;
      if (s === 'draft') {
        statusValue = OrderStatus.Draft;
        matched = true;
      } else if (s === 'paid') {
        statusValue = OrderStatus.Paid;
        matched = true;
      } else if (s === 'shipped') {
        statusValue = OrderStatus.Shipped;
        matched = true;
      }
    }
    if (!matched) {
      addError(errors, 'status', 'expected one of draft, paid, shipped');
    }
  }

  const lines: OrderLine[] = [];
  const lv: JsonValue = getField(obj, 'lines');
  if (lv === undefined || lv === null) {
    addError(errors, 'lines', 'required');
  } else if (!Array.isArray(lv)) {
    addError(errors, 'lines', 'expected an array');
  } else {
    const arr: JsonValue[] = lv as JsonValue[];
    if (arr.length === 0) {
      addError(errors, 'lines', 'must not be empty');
    } else {
      for (let i: number = 0; i < arr.length; i++) {
        const line: OrderLine | undefined = checkLine(arr[i], i, errors);
        if (line !== undefined) {
          lines.push(line);
        }
      }
    }
  }

  const orderKeys: string[] = Object.keys(obj);
  for (const key of orderKeys) {
    if (key !== 'id' && key !== 'status' && key !== 'lines') {
      addError(errors, key, 'unknown field');
    }
  }

  if (errors.length > 0) {
    const res: ParseResult = { order: undefined, errors: errors };
    return res;
  }

  const order: Order = {
    id: idValue as string,
    status: statusValue,
    lines: lines
  };
  const noErrors: FieldError[] = [];
  const ok: ParseResult = { order: order, errors: noErrors };
  return ok;
}

