export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

class QueueTask {
  start: () => void;
  cancel: () => void;

  constructor(start: () => void, cancel: () => void) {
    this.start = start;
    this.cancel = cancel;
  }
}

export class JobQueue {
  private concurrency: number = 1;
  private runningCount: number = 0;
  private completedCount: number = 0;
  private failedCount: number = 0;
  private paused: boolean = false;
  private pumping: boolean = false;
  private waitingTasks: Array<QueueTask> = [];
  private idleResolvers: Array<(value: void | PromiseLike<void>) => void> = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  get running(): number {
    return this.runningCount;
  }

  get waiting(): number {
    return this.waitingTasks.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve: (value: T | PromiseLike<T>) => void, reject: (reason?: Object) => void) => {
      const task: QueueTask = new QueueTask(
        () => {
          const result: Promise<T> = job();
          result.then(
            (value: T) => {
              this.runningCount--;
              this.completedCount++;
              resolve(value);
              this.pump();
              this.checkIdle();
            },
            (reason: Object) => {
              this.runningCount--;
              this.failedCount++;
              reject(reason);
              this.pump();
              this.checkIdle();
            }
          );
        },
        () => {
          reject(new Error('Job was cancelled'));
        }
      );
      this.waitingTasks.push(task);
      this.pump();
    });
  }

  pause(): void {
    this.paused = true;
  }

  resume(): void {
    this.paused = false;
    this.pump();
  }

  clear(): number {
    const count: number = this.waitingTasks.length;
    const tasks: Array<QueueTask> = this.waitingTasks;
    this.waitingTasks = [];
    for (let i = 0; i < tasks.length; i++) {
      tasks[i].cancel();
    }
    this.checkIdle();
    return count;
  }

  whenIdle(): Promise<void> {
    if (this.runningCount === 0 && this.waitingTasks.length === 0) {
      return Promise.resolve<void>(undefined);
    }
    return new Promise<void>((resolve: (value: void | PromiseLike<void>) => void) => {
      this.idleResolvers.push(resolve);
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const promises: Array<Promise<JobOutcome<T>>> = [];
    for (let i = 0; i < jobs.length; i++) {
      const job: () => Promise<T> = jobs[i];
      const p: Promise<JobOutcome<T>> = this.add<T>(job).then(
        (value: T): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: true, value: value, error: undefined };
          return outcome;
        },
        (reason: Object): JobOutcome<T> => {
          const outcome: JobOutcome<T> = { ok: false, value: undefined, error: reason as Error };
          return outcome;
        }
      );
      promises.push(p);
    }
    return Promise.all(promises);
  }

  private pump(): void {
    if (this.pumping) {
      return;
    }
    this.pumping = true;
    try {
      while (!this.paused && this.runningCount < this.concurrency && this.waitingTasks.length > 0) {
        const task: QueueTask | undefined = this.waitingTasks.shift();
        if (task === undefined) {
          break;
        }
        this.runningCount++;
        task.start();
      }
    } finally {
      this.pumping = false;
    }
  }

  private checkIdle(): void {
    if (this.runningCount === 0 && this.waitingTasks.length === 0) {
      const resolvers: Array<(value: void | PromiseLike<void>) => void> = this.idleResolvers;
      this.idleResolvers = [];
      for (let i = 0; i < resolvers.length; i++) {
        resolvers[i](undefined);
      }
    }
  }
}

export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

export class JobQueue {
  private concurrency: number;
  private waitingQueue: Array<() => Promise<any>> = [];
  private runningPromises: Array<Promise<any>> = [];
  private completedCount: number = 0;
  private failedCount: number = 0;
  private isPaused: boolean = false;
  private whenIdleResolve: (() => void) | null = null;
  private whenIdlePromise: Promise<void> | null = null;
  private idleState: boolean = true;
  private cancelledJobs: Array<Promise<any>> = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  private startNextJob(): void {
    if (this.isPaused || this.runningPromises.length >= this.concurrency) {
      return;
    }

    if (this.waitingQueue.length === 0) {
      return;
    }

    const job = this.waitingQueue.shift()!;
    const promise = job();
    this.runningPromises.push(promise);

    promise
      .then((value) => {
        this.completedCount++;
        this.runningPromises = this.runningPromises.filter(p => p !== promise);
        this.checkIdle();
      })
      .catch((error) => {
        this.failedCount++;
        this.runningPromises = this.runningPromises.filter(p => p !== promise);
        this.checkIdle();
      });
  }

  private checkIdle(): void {
    if (this.runningPromises.length === 0 && this.waitingQueue.length === 0) {
      this.idleState = true;
      if (this.whenIdleResolve) {
        this.whenIdleResolve();
        this.whenIdleResolve = null;
      }
    }
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    const promise = job();
    this.waitingQueue.push(job);

    if (!this.isPaused && this.runningPromises.length < this.concurrency) {
      this.startNextJob();
    }

    return promise;
  }

  get running(): number {
    return this.runningPromises.length;
  }

  get waiting(): number {
    return this.waitingQueue.length;
  }

  get completed(): number {
    return this.completedCount;
  }

  get failed(): number {
    return this.failedCount;
  }

  pause(): void {
    this.isPaused = true;
  }

  resume(): void {
    this.isPaused = false;
    while (this.runningPromises.length < this.concurrency && this.waitingQueue.length > 0) {
      this.startNextJob();
    }
  }

  clear(): number {
    const count = this.waitingQueue.length;
    this.waitingQueue = [];

    // Cancel all waiting jobs with specific error
    this.cancelledJobs = this.waitingQueue.map(() => {
      const error = new Error('Job was cancelled');
      return Promise.reject(error);
    });

    return count;
  }

  whenIdle(): Promise<void> {
    if (this.idleState) {
      return Promise.resolve();
    }

    if (!this.whenIdlePromise) {
      this.whenIdlePromise = new Promise<void>(resolve => {
        this.whenIdleResolve = resolve;
      });
    }

    return this.whenIdlePromise;
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    const outcomes: JobOutcome<T>[] = [];
    const jobPromises: Array<Promise<any>> = [];

    for (const job of jobs) {
      const promise = job();
      jobPromises.push(promise);

      promise
        .then((value) => {
          outcomes.push({ ok: true, value, error: undefined });
        })
        .catch((error) => {
          outcomes.push({ ok: false, value: undefined, error });
        });
    }

    return Promise.all(jobPromises).then(() => {
      return outcomes;
    });
  }
}

