// The "Addresses" screen, pushed on top of the checkout screen.
@Component
struct AddressesPage {
  @State currentId: string = '';
  pathStack: NavPathStack | undefined = undefined;

  aboutToAppear(): void {
    if (this.pathStack) {
      const params: Array<Object | null> = this.pathStack.getParamByName('addresses') as Array<Object | null>;
      if (params.length > 0) {
        const param: Object | null = params[params.length - 1];
        if (typeof param === 'string') {
          this.currentId = param;
        }
      }
    }
  }

  build() {
    NavDestination() {
      Column({ space: 12 }) {
        ForEach(ADDRESSES, (addr: Address) => {
          AddressRow({
            address: addr,
            isCurrent: addr.id === this.currentId,
            onSelected: (id: string) => {
              // Pop with a result; the push's onPop callback receives it.
              this.pathStack?.pop(id);
            }
          })
        }, (addr: Address) => addr.id)
