import { Entry, State } from '@arkui/extension';
import { List, ListItem, LazyForEach, Refresh } from '@arkui/extension';

class LogEntry {
  id: number;
  message: string;
  level: string;

  constructor(id: number) {
    this.id = id;
    this.message = `Event ${id}`;
    if (id % 50 === 0) {
      this.level = "error";
    } else if (id % 10 === 0) {
      this.level = "warning";
    } else {
      this.level = "info";
    }
  }
}

@Builder
function LogRow(entry: LogEntry) {
  let color: string;
  switch (entry.level) {
    case "error":
      color = "#D32F2F";
      break;
    case "warning":
      color = "#F57C00";
      break;
    case "info":
      color = "#757575";
      break;
    default:
      color = "#757575";
  }

  Column() {
    Text(`${entry.message}`)
      .fontSize(16)
    Text(`${entry.level}`)
      .fontSize(14)
      .fontColor(color)
  }
  .width('100%')
  .padding({ left: 16, right: 16, top: 8, bottom: 8 })
}

@Entry
struct Solution {
  @State entries: LogEntry[] = [];
  @State totalEntries: number = 0;

  aboutToAppear() {
    // Create 3000 entries
    this.entries = [];
    for (let i = 1; i <= 3000; i++) {
      this.entries.push(new LogEntry(i));
    }
    this.totalEntries = 3000;
  }

  build() {
    Column() {
      Text(`${this.totalEntries} entries`)
        .fontSize(20)
        .fontWeight(FontWeight.Bold)
        .margin({ top: 16, bottom: 8 })

      List() {
        Refresh({
          refreshOffset: 100,
          pullToRefresh: true
        }) {
          // Refresh indicator content would be handled by system
        }
        .onRefreshing(() => {
          // Simulate network delay
          setTimeout(() => {
            const newEntries: LogEntry[] = [];
            const startId = this.totalEntries + 1;
            for (let i = 0; i < 5; i++) {
              newEntries.push(new LogEntry(startId + i));
            }
            this.entries = [...newEntries, ...this.entries];
            this.totalEntries += 5;
          }, 1000);
        })
        .height('100%')

        LazyForEach(this.entries, (entry: LogEntry) => {
          ListItem() {
            LogRow(entry)
          }
        }, (entry: LogEntry) => {
          return entry.id.toString();
        })
      }
      .width('100%')
      .height('100%')
    }
    .width('100%')
    .height('100%')
    .padding({ left: 16, right: 16, top: 16, bottom: 16 })
  }
}

