@Entry
@Component
struct WaterTrackerPage {
  @State count: number = 0;
  @State goal: number = 8;

  // Callback to update the goal from the dialog
  @State updateGoal: (value: number) => void = () => {};

  aboutToAppear() {
    // Load data from AppStorage
    const savedCount = AppStorage.get<number>('waterCount');
    const savedGoal = AppStorage.get<number>('waterGoal');

    if (savedCount !== undefined) {
      this.count = savedCount;
    }
    if (savedGoal !== undefined) {
      this.goal = savedGoal;
    }
  }

  aboutToDisappear() {
    // Save data to AppStorage
    AppStorage.set('waterCount', this.count);
    AppStorage.set('waterGoal', this.goal);
  }

  build() {
    Column() {
      // Main display
      Text(`${this.count} of ${this.goal} glasses`)
        .fontSize(32)
        .fontWeight(FontWeight.Bold)
        .margin({ bottom: 24 })

      // Status message
      if (this.count >= this.goal) {
        Text('Goal reached')
          .fontSize(18)
          .fontWeight(FontWeight.Bold)
          .color(Color.Green)
          .margin({ bottom: 32 })
      }

      // Add button
      Button('Add a glass')
        .width('100%')
        .onClick(() => {
          this.count++;
        })

      // Change goal button
      Button('Change goal')
        .width('100%')
        .margin({ top: 16 })
        .onClick(() => {
          // Open the dialog
          const dialog = new GoalDialog();
          dialog.onSave = (value: number) => {
            this.goal = value;
            this.updateGoal(value);
          };
          dialog.cancelOnClose = true;

          // Show dialog using router.push or similar mechanism if available, 
          // but for a simple modal in a single file without complex routing,
          // we can use a simple overlay or assume the environment supports 
          // showing a component. However, standard ArkUI doesn't have a direct 
          // "showModal" function for custom components in the same way.
          // The standard way is to use a Dialog component from the UI kit or 
          // manage state. 
          // Since the prompt asks for a "dialog component... declared in the file" 
          // and "system shows it as a modal", we will use the standard 
          // `Dialog` component from ArkUI if available, or implement a simple 
          // overlay if not. 
          // Given the constraints of "ArkTS in one page" and standard imports:
