export interface JobOutcome<T> {
  ok: boolean;
  value: T | undefined;
  error: Error | undefined;
}

interface WaitingJobEntry {
  run: () => void;
  cancel: () => void;
}

export class JobQueue {
  private concurrency: number;
  private _running: number = 0;
  private _completed: number = 0;
  private _failed: number = 0;
  private _paused: boolean = false;
  private queue: WaitingJobEntry[] = [];
  private idleResolvers: (() => void)[] = [];

  constructor(concurrency: number) {
    this.concurrency = concurrency;
  }

  get running(): number {
    return this._running;
  }

  get waiting(): number {
    return this.queue.length;
  }

  get completed(): number {
    return this._completed;
  }

  get failed(): number {
    return this._failed;
  }

  add<T>(job: () => Promise<T>): Promise<T> {
    return new Promise<T>((resolve, reject) => {
      const run = (): void => {
        this._running++;
        try {
          const p = job();
          p.then(
            (value: T) => {
              this._running--;
              this._completed++;
              resolve(value);
              this.onJobSettled();
            },
            (err) => {
              this._running--;
              this._failed++;
              reject(err);
              this.onJobSettled();
            }
          );
        } catch (e) {
          this._running--;
          this._failed++;
          reject(e);
          this.onJobSettled();
        }
      };
      const cancel = (): void => {
        reject(new Error('Job was cancelled'));
      };
      this.queue.push({ run, cancel });
      this.tryStartNext();
    });
  }

  private tryStartNext(): void {
    while (!this._paused && this.queue.length > 0 && this._running < this.concurrency) {
      const entry = this.queue.shift()!;
      entry.run();
    }
  }

  private onJobSettled(): void {
    this.checkIdle();
    this.tryStartNext();
  }

  private checkIdle(): void {
    if (this._running === 0 && this.queue.length === 0) {
      const resolvers = this.idleResolvers;
      this.idleResolvers = [];
      for (let i = 0; i < resolvers.length; i++) {
        resolvers[i]();
      }
    }
  }

  pause(): void {
    this._paused = true;
  }

  resume(): void {
    this._paused = false;
    this.tryStartNext();
  }

  clear(): number {
    const count = this.queue.length;
    for (let i = 0; i < this.queue.length; i++) {
      this.queue[i].cancel();
    }
    this.queue = [];
    this.checkIdle();
    return count;
  }

  whenIdle(): Promise<void> {
    if (this._running === 0 && this.queue.length === 0) {
      return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
      this.idleResolvers.push(() => resolve());
    });
  }

  runAll<T>(jobs: Array<() => Promise<T>>): Promise<JobOutcome<T>[]> {
    if (jobs.length === 0) {
      return Promise.resolve([]);
    }

    const total = jobs.length;
    const outcomes: JobOutcome<T>[] = [];
    for (let i = 0; i < total; i++) {
      outcomes.push({ ok: false, value: undefined, error: undefined });
    }
    let settled = 0;

    return new Promise<JobOutcome<T>[]>((resolveAll) => {
      for (let i = 0; i < total; i++) {
        const index = i;
        this.add<T>(jobs[i]).then(
          (value: T) => {
            outcomes[index] = { ok: true, value: value, error: undefined };
            settled++;
            if (settled === total) {
              resolveAll(outcomes);
            }
          },
          (err) => {
            outcomes[index] = { ok: false, value: undefined, error: err as Error };
            settled++;
            if (settled === total) {
              resolveAll(outcomes);
            }
          }
        );
      }
    });
  }
}

