export class MissingDependencyError extends Error {
  task: string
  dependency: string

  constructor(task: string, dependency: string) {
    super(`Task '${task}' depends on unknown task '${dependency}'`)
    this.task = task
    this.dependency = dependency
  }
}

export class CycleError extends Error {
  path: string[]

  constructor(path: string[]) {
    super(`Dependency cycle: ${path.join(' -> ')}`)
    this.path = path
  }
}

export class BuildPlan {
  private spec: Record<string, string[]>
  private taskNames: string[]
  private taskDependencies: Map<string, string[]>

  constructor(spec: Record<string, string[]>) {
    this.spec = spec
    this.taskNames = Object.keys(spec)
    this.taskDependencies = new Map()

    for (const task of this.taskNames) {
      const deps = spec[task]
      this.taskDependencies.set(task, deps)
    }

    for (const task of this.taskNames) {
      const deps = this.taskDependencies.get(task)
      if (deps) {
        for (const dep of deps) {
          if (!this.taskNames.includes(dep)) {
            throw new MissingDependencyError(task, dep)
          }
        }
      }
    }

    this.checkCycles()
  }

  private checkCycles(): void {
    const visited = new Set<string>()
    const recStack = new Set<string>()
    const path: string[] = []

    const visit = (task: string): void => {
      if (recStack.has(task)) {
        const cycleStart = path.indexOf(task)
        const cyclePath = path.slice(cycleStart)
        cyclePath.push(task)
        throw new CycleError(cyclePath)
      }

      if (visited.has(task)) {
        return
      }

      visited.add(task)
      recStack.add(task)
      path.push(task)

      const deps = this.taskDependencies.get(task)
      if (deps) {
        for (const dep of deps) {
          visit(dep)
        }
      }

      path.pop()
      recStack.delete(task)
    }

    for (const task of this.taskNames) {
      if (!visited.has(task)) {
        visit(task)
      }
    }
  }

  order(): string[] {
    const result: string[] = []
    const placed = new Set<string>()

    for (const task of this.taskNames) {
      if (!placed.has(task)) {
        this.placeTask(task, placed, result)
      }
    }

    return result
  }

  private placeTask(task: string, placed: Set<string>, result: string[]): void {
    const deps = this.taskDependencies.get(task)
    if (deps) {
      for (const dep of deps) {
        if (!placed.has(dep)) {
          this.placeTask(dep, placed, result)
        }
      }
    }
    result.push(task)
    placed.add(task)
  }

  layers(): string[][] {
    const layers: string[][] = []
    const taskLayer: Map<string, number> = new Map()

    for (const task of this.taskNames) {
      taskLayer.set(task, 0)
    }

    for (const task of this.taskNames) {
      const deps = this.taskDependencies.get(task)
      if (deps) {
        for (const dep of deps) {
          const depLayer = taskLayer.get(dep)
          if (depLayer !== undefined) {
            const taskLayerVal = taskLayer.get(task)
            if (taskLayerVal !== undefined) {
              taskLayer.set(task, Math.max(taskLayerVal, depLayer + 1))
            }
          }
        }
      }
    }

    for (const task of this.taskNames) {
      const layer = taskLayer.get(task)
      if (layer !== undefined) {
        while (layers.length <= layer) {
          layers.push([])
        }
        layers[layer].push(task)
      }
    }

    return layers
  }

  dependentsOf(name: string): string[] {
    const result: string[] = []
    const visited = new Set<string>()

    const findDependents = (task: string): void => {
      if (visited.has(task)) {
        return
      }
      visited.add(task)

      const deps = this.taskDependencies.get(task)
      if (deps) {
        for (const dep of deps) {
          if (dep === name) {
            result.push(task)
          }
          findDependents(dep)
        }
      }
    }

    for (const task of this.taskNames) {
      if (task !== name) {
        findDependents(task)
      }
    }

    return result
  }
}

enum OrderStatus {
  Draft = 'draft',
  Paid = 'paid',
  Shipped = 'shipped',
}

class OrderLine {
  sku: string
  quantity: number
  unitPrice: number

  constructor(sku: string, quantity: number, unitPrice: number) {
    this.sku = sku
    this.quantity = quantity
    this.unitPrice = unitPrice
  }

  total(): number {
    return this.quantity * this.unitPrice
  }
}

interface Order {
  id: string
  status: OrderStatus
  lines: OrderLine[]
}

interface FieldError {
  path: string
  message: string
}

interface ParseResult {
  order: Order | undefined
  errors: FieldError[]
}

function parseOrder(text: string): ParseResult {
  const errors: FieldError[] = []
  let order: Order | undefined = undefined

  try {
    const raw = JSON.parse(text)

    if (typeof raw !== 'object' || raw === null) {
      errors.push({ path: '', message: 'expected an object' })
      return { order: undefined, errors }
    }

    const orderObj = raw
    const linesArr = raw.lines

    // Check id
    const hasId = 'id' in orderObj
    const idValue = orderObj.id
    if (!hasId || idValue === null) {
      errors.push({ path: 'id', message: 'required' })
    } else if (typeof idValue !== 'string') {
      errors.push({ path: 'id', message: 'expected a string' })
    } else if (idValue === '') {
      errors.push({ path: 'id', message: 'must not be empty' })
    }

    // Check status
    const hasStatus = 'status' in orderObj
    const statusValue = orderObj.status
    if (!hasStatus || statusValue === null) {
      orderObj.status = OrderStatus.Draft
    } else if (typeof statusValue !== 'string') {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' })
    } else if (statusValue !== 'draft' && statusValue !== 'paid' && statusValue !== 'shipped') {
      errors.push({ path: 'status', message: 'expected one of draft, paid, shipped' })
    }

    // Check lines
    const hasLines = 'lines' in orderObj
    const linesValue = orderObj.lines
    if (!hasLines || linesValue === null) {
      errors.push({ path: 'lines', message: 'required' })
    } else if (!Array.isArray(linesValue)) {
      errors.push({ path: 'lines', message: 'expected an array' })
    } else if (linesValue.length === 0) {
      errors.push({ path: 'lines', message: 'must not be empty' })
    } else {
      for (let i = 0; i < linesValue.length; i++) {
        const lineObj = linesValue[i]
        const linePath = `lines[${i}]`

        if (typeof lineObj !== 'object' || lineObj === null) {
          errors.push({ path: linePath, message: 'expected an object' })
          continue
        }

        // Check sku
        const hasSku = 'sku' in lineObj
        const skuValue = lineObj.sku
        if (!hasSku || skuValue === null) {
          errors.push({ path: `${linePath}.sku`, message: 'required' })
        } else if (typeof skuValue !== 'string') {
          errors.push({ path: `${linePath}.sku`, message: 'expected a string' })
        } else if (skuValue === '') {
          errors.push({ path: `${linePath}.sku`, message: 'must not be empty' })
        }

        // Check quantity
        const hasQuantity = 'quantity' in lineObj
        const quantityValue = lineObj.quantity
        if (!hasQuantity || quantityValue === null) {
          errors.push({ path: `${linePath}.quantity`, message: 'required' })
        } else if (typeof quantityValue !== 'number') {
          errors.push({ path: `${linePath}.quantity`, message: 'expected a number' })
        } else if (!Number.isInteger(quantityValue) || quantityValue < 1) {
          errors.push({ path: `${linePath}.quantity`, message: 'must be a whole number of 1 or more' })
        }

        // Check unitPrice
        const hasUnitPrice = 'unitPrice' in lineObj
        const unitPriceValue = lineObj.unitPrice
        if (!hasUnitPrice || unitPriceValue === null) {
          errors.push({ path: `${linePath}.unitPrice`, message: 'required' })
        } else if (typeof unitPriceValue !== 'number') {
          errors.push({ path: `${linePath}.unitPrice`, message: 'expected a number' })
        } else if (unitPriceValue < 0) {
          errors.push({ path: `${linePath}.unitPrice`, message: 'must be 0 or more' })
        }

        // Check unknown fields in line
        const knownLineFields = ['sku', 'quantity', 'unitPrice']
        for (const key of Object.keys(lineObj)) {
          let isKnown = false
          for (const known of knownLineFields) {
            if (key === known) {
              isKnown = true
              break
            }
          }
          if (!isKnown) {
            errors.push({ path: `${linePath}.${key}`, message: 'unknown field' })
          }
        }
      }
    }

    // Check unknown fields in order
    const knownOrderFields = ['id', 'status', 'lines']
    for (const key of Object.keys(orderObj)) {
      let isKnown = false
      for (const known of knownOrderFields) {
        if (key === known) {
          isKnown = true
          break
        }
      }
      if (!isKnown) {
        errors.push({ path: key, message: 'unknown field' })
      }
    }

    if (errors.length === 0) {
      const lines: OrderLine[] = []
      for (const lineObj of orderObj.lines) {
        lines.push(new OrderLine(lineObj.sku, lineObj.quantity, lineObj.unitPrice))
      }
      order = {
        id: orderObj.id,
        status: orderObj.status as OrderStatus,
        lines: lines,
      }
    }

  } catch (e) {
    errors.push({ path: '', message: 'invalid JSON' })
  }

  return { order, errors }
}

interface CacheEntry<K, V> {
  key: K
  value: V
}

interface LRUCacheState<K, V> {
  entries: CacheEntry<K, V>[]
  capacity: number
}

export class LruCache<K, V> {
  private state: LRUCacheState<K, V>

  constructor(capacity: number) {
    if (capacity < 1) {
      throw new Error('Capacity must be 1 or more')
    }
    this.state = {
      entries: [],
      capacity: capacity
    }
  }

  set(key: K, value: V): void {
    const index = this.findIndex(key)
    if (index !== -1) {
      this.state.entries[index].value = value
      this.moveToEnd(index)
    } else {
      this.state.entries.push({ key, value })
      if (this.state.entries.length > this.state.capacity) {
        this.state.entries.shift()
      }
    }
  }

  get(key: K): V | undefined {
    const index = this.findIndex(key)
    if (index !== -1) {
      this.moveToEnd(index)
      return this.state.entries[index].value
    }
    return undefined
  }

  has(key: K): boolean {
    return this.findIndex(key) !== -1
  }

  keys(): K[] {
    const result: K[] = []
    for (let i = 0; i < this.state.entries.length; i++) {
      result.push(this.state.entries[i].key)
    }
    return result
  }

  get size(): number {
    return this.state.entries.length
  }

  private findIndex(key: K): number {
    for (let i = 0; i < this.state.entries.length; i++) {
      if (this.state.entries[i].key === key) {
        return i
      }
    }
    return -1
  }

  private moveToEnd(index: number): void {
    const entry = this.state.entries[index]
    this.state.entries.splice(index, 1)
    this.state.entries.push(entry)
  }
}

