// Reusable Row Component
@Builder
function AddressRow(addressId: string, address: Address, largeText: boolean) {
  Column() {
    Row() {
      Text(address.label)
        .fontSize(largeText ? 24 : 16)
        .margin({ right: 10 })
      Text(address.street)
        .fontSize(largeText ? 24 : 16)
        .margin({ right: 10 })
      if (addressId === address.id) {
        Text('Current')
          .fontSize(largeText ? 24 : 16)
          .fontColor(Color.Gray)
      }
    }
    .width('100%')
    .justifyContent(FlexAlign.SpaceBetween)
    .padding({ left: 16, right: 16, top: 12, bottom: 12 })
    .backgroundColor(Color.White)
    .borderRadius(8)
    .margin({ bottom: 8 })
  }
  .width('100%')
  .onClick(() => {
    router.back({
      url: 'pages/CheckoutPage',
      params: { addressId: address.id }
    });
  })
}

// Address Data Class
class Address {
  id: string;
  label: string;
  street: string;

  constructor(id: string, label: string, street: string) {
    this.id = id;
    this.label = label;
    this.street = street;
  }

  static findById(id: string): Address | undefined {
    const addresses = [
      new Address('home', 'Home', '12 Elm Street'),
      new Address('work', 'Work', '400 Harbour Road'),
      new Address('gym', 'Gym', '7 Mill Lane')
    ];
    for (let i = 0; i < addresses.length; i++) {
      if (addresses[i].id === id) {
        return addresses[i];
      }
    }
    return undefined;
  }

  static findAll(): Address[] {
    return [
      new Address('home', 'Home', '12 Elm Street'),
      new Address('work', 'Work', '400 Harbour Road'),
      new Address('gym', 'Gym', '7 Mill Lane')
    ];
  }
}

