@Entry
@Component
struct ShoppingList {
  @State items: GroceryItem[] = [
    { id: 1, name: 'Milk', bought: false },
    { id: 2, name: 'Bread', bought: false },
    { id: 3, name: 'Eggs', bought: false },
    { id: 4, name: 'Apples', bought: false },
  ];
  @State newItemName: string = '';
  @State nextId: number = 5;

  aboutToAppear() {
    this.nextId = Math.max(...this.items.map(i => i.id)) + 1;
  }

  build() {
    Column() {
      Text(`${this.items.length} items, ${this.items.filter(i => i.bought).length} bought`)
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 16, bottom: 8 })

      List(this.items) {
        GroceryRow(item: GroceryItem)
      }

      Column() {
        Input(this.newItemName)
          .placeholder('New item')
          .margin({ bottom: 8 })

        Button('Add')
          .onClick(() => {
            const trimmed = this.newItemName.trim();
            if (trimmed.length > 0) {
              this.items.push({
                id: this.nextId++,
                name: trimmed,
                bought: false,
              });
              this.newItemName = '';
            }
          })
      }
    }
    .width('100%')
    .height('100%')
  }
}

