import {
  Entry,
  List,
  ListItem,
  Row,
  Column,
  Text,
  Input,
  Button,
  SwipeCell,
  Cell,
  CellContent,
  CellRightButton,
  CellLeftButton,
  CellTitle,
  CellDeleteButton,
  CellDivider,
  CellBackground,
  CellContentBackground,
  CellTitleBackground,
  CellRightButtonBackground,
  CellLeftButtonBackground,
  CellDeleteButtonBackground,
  CellDividerBackground,
} from '@kit.ArkUI';

interface GroceryItem {
  id: number;
  name: string;
  bought: boolean;
}

@Entry
@Component
struct ShoppingList {
  @State items: GroceryItem[] = [
    { id: 1, name: 'Milk', bought: false },
    { id: 2, name: 'Bread', bought: false },
    { id: 3, name: 'Eggs', bought: false },
    { id: 4, name: 'Apples', bought: false },
  ];
  @State newItemName: string = '';
  @State nextId: number = 5;

  aboutToAppear() {
    // Ensure nextId is higher than any existing id
    if (this.items.length > 0) {
      const maxId = this.items.reduce((max, item) => Math.max(max, item.id), 0);
      if (this.nextId <= maxId) {
        this.nextId = maxId + 1;
      }
    }
  }

  build() {
    Column() {
      Text(`${this.items.length} items, ${this.items.filter(i => i.bought).length} bought`)
        .fontSize(16)
        .fontWeight(FontWeight.Medium)
        .margin({ top: 16, bottom: 8 });

      List(this.items, (item: GroceryItem) => {
        return ListItem() {
          Row() {
            GroceryRow(item)
          }
          .width('100%')
          .justifyContent(FlexAlign.SpaceBetween)
          .padding({ left: 16, right: 16, top: 12, bottom: 12 });

          SwipeCell() {
            Cell() {
              CellContent() {
                Text('Delete')
                  .fontSize(14)
                  .fontWeight(FontWeight.Medium)
                  .color(Color.White)
                  .margin({ left: 16 });
              }
              .width('100%')
              .height('100%')
              .justifyContent(FlexAlign.Center)
              .backgroundColor('#D32F2F');

              CellRightButton() {
                Text('Delete')
                  .fontSize(14)
                  .fontWeight(FontWeight.Medium)
                  .color(Color.White);
              }
              .width('60')
              .height('100%')
              .justifyContent(FlexAlign.Center)
              .backgroundColor('#D32F2F');
            }
            .width('100%')
            .height('100%');
          }
          .width('100%');
        }
        .width('100%');
      }, (item: GroceryItem) => item.id.toString());

      Row() {
        Input(this.newItemName)
          .placeholder('New item')
          .width('100%')
          .margin({ right: 8 });

        Button('Add')
          .width(80)
          .height(40)
          .backgroundColor('#1976D2')
          .onClick(() => {
            const trimmed = this.newItemName.trim();
            if (trimmed.length > 0) {
              this.items.push({
                id: this.nextId,
                name: trimmed,
                bought: false,
              });
              this.nextId++;
              this.newItemName = '';
            }
          });
      }
      .width('100%')
      .justifyContent(FlexAlign.SpaceBetween)
      .padding({ top: 16, bottom: 16 });
    }
    .width('100%')
    .height('100%')
    .padding(16);
  }
}

@Component
struct GroceryRow {
  @ObjectLink item: GroceryItem;

  build() {
    Row() {
      Text(this.item.name)
        .fontSize(16)
        .fontWeight(this.item.bought ? FontWeight.Normal : FontWeight.Bold)
        .color(this.item.bought ? '#9E9E9E' : Color.Black)
        .onLongPress(() => {
          this.item.bought = !this.item.bought;
        });
    }
    .width('100%')
    .justifyContent(FlexAlign.Center)
    .padding({ left: 16, right: 16 });
  }
}
